    return new WasmMeshDeformation(geometry, { type: DeformationType.WOBBLE, ...config });
}

/**
 * Batch deformation for multiple meshes
 * Useful for deforming an entire forest
 */
export class BatchMeshDeformation {
    private deformers: WasmMeshDeformation[] = [];

    add(deformer: WasmMeshDeformation): void {
        this.deformers.push(deformer);
    }

    update(time: number, audioState: DeformationAudioState = {}): void {
        // Could parallelize this with WASM batchDeformMeshes in the future
        for (const deformer of this.deformers) {
            deformer.update(time, audioState);
        }
    }

    dispose(): void {
        for (const deformer of this.deformers) {
            deformer.dispose();
        }
        this.deformers = [];
    }
}

/**
 * @file noise-generator-gpu.ts
 * @description GPU-accelerated procedural noise generation using WebGPU compute shaders.
 *
 * Generates FBM noise textures on the GPU for terrain heightmaps and
 * candy swirl patterns. Falls back to ProceduralNoiseCompute on CPU.
 *
 * @example
 * ```ts
 * import { NoiseGeneratorGPU } from './noise-generator-gpu';
 *
 * const noise = new NoiseGeneratorGPU(512, 512, { scale: 2.0, octaves: 6 });
 * await noise.init();
 *
 * const texture = await noise.createTexture();
 * material.map = texture;
 * ```
 */

import * as THREE from 'three';
import { GPUComputeLibrary, getSharedGPUCompute } from './gpu-compute-library.ts';
import { NOISE_FBM_WGSL, NOISE_HEIGHTMAP_WGSL } from './gpu-compute-shaders.ts';
import { ProceduralNoiseCompute, NoiseConfig } from './noise_generator.ts';

// =============================================================================
// TYPES
// =============================================================================

export interface NoiseGeneratorGPUConfig extends NoiseConfig {
    /** Use GPU when available (default: true) */
    useGPU?: boolean;
}

// =============================================================================
// BIND GROUP LAYOUT
// =============================================================================

const NOISE_LAYOUT: GPUBindGroupLayoutEntry[] = [
    { binding: 0, visibility: GPUShaderStage.COMPUTE, buffer: { type: 'storage' } },
    { binding: 1, visibility: GPUShaderStage.COMPUTE, buffer: { type: 'uniform' } },
];

// =============================================================================
// GPU NOISE GENERATOR
// =============================================================================

export class NoiseGeneratorGPU {
    public readonly width: number;
    public readonly height: number;

    private gpuLib: GPUComputeLibrary;
    private cpuFallback: ProceduralNoiseCompute;
    private useGPU: boolean;

    // Configuration
    private scale: number;
    private octaves: number;
    private lacunarity: number;
    private persistence: number;

    // GPU resources
    private rgbaPipeline: GPUComputePipeline | null = null;
    private heightmapPipeline: GPUComputePipeline | null = null;
    private outputBuffer: GPUBuffer | null = null;
    private uniformBuffer: GPUBuffer | null = null;

    constructor(width = 256, height = 256, config: NoiseGeneratorGPUConfig = {}) {
        this.width = width;
        this.height = height;
        this.scale = config.scale ?? 1.0;
        this.octaves = config.octaves ?? 4;
        this.lacunarity = config.lacunarity ?? 2.0;
        this.persistence = config.persistence ?? 0.5;
        this.useGPU = config.useGPU ?? true;

        this.gpuLib = getSharedGPUCompute();
        this.cpuFallback = new ProceduralNoiseCompute(width, height, config);
    }

    /** Whether the GPU path is active */
    isReady(): boolean {
        return this.gpuLib.isReady() && this.rgbaPipeline !== null;
    }

    /**
     * Initialise GPU resources. Must be called before generate/createTexture.
     */
    async init(): Promise<void> {
        if (!this.useGPU) return;

        try {
            await this.gpuLib.initDevice();
        } catch {
            console.log('[GPU] NoiseGeneratorGPU: WebGPU unavailable, using CPU fallback');
            return;
        }

        try {
            this.rgbaPipeline = await this.gpuLib.createComputePipeline({
                shader: NOISE_FBM_WGSL,
                workgroupSize: 8,
                bindingLayout: NOISE_LAYOUT,
                label: 'noise-fbm-rgba',
            });

            this.heightmapPipeline = await this.gpuLib.createComputePipeline({
                shader: NOISE_HEIGHTMAP_WGSL,
                workgroupSize: 8,
                bindingLayout: NOISE_LAYOUT,
                label: 'noise-fbm-heightmap',
            });

            // Allocate output for RGBA (4 floats per pixel)
            const rgbaSize = this.width * this.height * 4 * 4; // 4 channels, 4 bytes each
            this.outputBuffer = this.gpuLib.createStorageBuffer(
                new Float32Array(this.width * this.height * 4),
                'noise-output'
            );

            // Uniform buffer: width(u32), height(u32), scale(f32), octaves(u32),
            //                  lacunarity(f32), persistence(f32), time(f32), pad(u32)
            const uniformView = new ArrayBuffer(32);
            const u32 = new Uint32Array(uniformView);
            const f32 = new Float32Array(uniformView);
            u32[0] = this.width;
            u32[1] = this.height;
            f32[2] = this.scale;
            u32[3] = this.octaves;
            f32[4] = this.lacunarity;
            f32[5] = this.persistence;
            f32[6] = 0; // time
            u32[7] = 0; // pad
            this.uniformBuffer = this.gpuLib.createUniformBuffer(
                new Float32Array(uniformView),
                'noise-uniforms'
            );

            console.log(`[GPU] NoiseGeneratorGPU initialised — ${this.width}×${this.height}`);
        } catch (e) {
            console.warn('[GPU] NoiseGeneratorGPU init failed:', e);
            this.rgbaPipeline = null;
        }
    }

    /** Set noise scale */
    setScale(scale: number): void {
        this.scale = scale;
        this.cpuFallback.setScale(scale);
    }

    /** Set number of FBM octaves */
    setOctaves(octaves: number): void {
        this.octaves = Math.max(1, Math.min(8, octaves));
        this.cpuFallback.setOctaves(this.octaves);
    }

    /**
     * Generate RGBA noise data on the GPU.
     * @param time - Optional time parameter for animated noise
     * @returns Float32Array of RGBA pixel data (width * height * 4)
     */
    async generate(time = 0): Promise<Float32Array> {
        if (!this.isReady()) {
            // CPU fallback
            this.cpuFallback.uTime.value = time;
            this.cpuFallback.generate();
            // Access internal data via createTexture and extract
            const tex = this.cpuFallback.createTexture();
            return (tex.image.data as any) as Float32Array;
        }

        this.writeUniforms(time);

        const bindGroup = this.gpuLib.createBindGroup(
            this.rgbaPipeline!,
            [this.outputBuffer!, this.uniformBuffer!],
            'noise-rgba-bind'
        );

        const wgX = Math.ceil(this.width / 8);
        const wgY = Math.ceil(this.height / 8);
        this.gpuLib.dispatchCompute(this.rgbaPipeline!, bindGroup, wgX, wgY);

        return this.gpuLib.readBuffer(this.outputBuffer!, this.width * this.height * 4 * 4);
    }

    /**
     * Generate a single-channel heightmap on the GPU.
     * @param time - Optional time parameter for animated noise
     * @returns Float32Array of height values (width * height)
     */
    async generateHeightmap(time = 0): Promise<Float32Array> {
        if (!this.isReady() || !this.heightmapPipeline) {
            // CPU fallback — generate and return single-channel
            const data = new Float32Array(this.width * this.height);
            for (let y = 0; y < this.height; y++) {
                for (let x = 0; x < this.width; x++) {
                    const nx = (x / this.width) * this.scale;
                    const ny = (y / this.height) * this.scale;
                    data[y * this.width + x] = this.cpuFallback.fbm(nx, ny);
                }
            }
            return data;
        }

        // Re-create output for single-channel
        const singleBuffer = this.gpuLib.createStorageBuffer(
            new Float32Array(this.width * this.height),
            'noise-heightmap-output'
        );

        this.writeUniforms(time);

        const bindGroup = this.gpuLib.createBindGroup(
            this.heightmapPipeline,
            [singleBuffer, this.uniformBuffer!],
            'noise-heightmap-bind'
        );

        const wgX = Math.ceil(this.width / 8);
        const wgY = Math.ceil(this.height / 8);
        this.gpuLib.dispatchCompute(this.heightmapPipeline, bindGroup, wgX, wgY);

        const result = await this.gpuLib.readBuffer(singleBuffer, this.width * this.height * 4);
        singleBuffer.destroy();
        return result;
    }

    /**
     * Create a Three.js DataTexture from GPU-generated noise.
     * @param time - Optional time parameter for animated noise
     */
    async createTexture(time = 0): Promise<THREE.DataTexture> {
        const data = await this.generate(time);

        const texture = new THREE.DataTexture(
            data as any,
            this.width,
            this.height,
            THREE.RGBAFormat,
            THREE.FloatType
        );

        texture.needsUpdate = true;
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.magFilter = THREE.LinearFilter;
        texture.minFilter = THREE.LinearMipmapLinearFilter;

        return texture;
    }

    /**
     * Get a single height value at world coordinates.
     * Delegates to CPU for single-point queries (GPU overhead too high).
     */
    getHeight(x: number, z: number, scale?: number): number {
        return this.cpuFallback.getHeight(x, z, scale);
    }

    /** Dispose of GPU and CPU resources */
    dispose(): void {
        this.outputBuffer?.destroy();
        this.uniformBuffer?.destroy();
        this.outputBuffer = null;
        this.uniformBuffer = null;
        this.rgbaPipeline = null;
        this.heightmapPipeline = null;
        this.cpuFallback.dispose();
    }

    // =========================================================================
    // Private
    // =========================================================================

    private writeUniforms(time: number): void {
        const uniformView = new ArrayBuffer(32);
        const u32 = new Uint32Array(uniformView);
        const f32 = new Float32Array(uniformView);
        u32[0] = this.width;
        u32[1] = this.height;
        f32[2] = this.scale;
        u32[3] = this.octaves;
        f32[4] = this.lacunarity;
        f32[5] = this.persistence;
        f32[6] = time;
        u32[7] = 0;
        this.gpuLib.writeUniformBuffer(this.uniformBuffer!, new Float32Array(uniformView));
    }
}

// =============================================================================
// CONVENIENCE FACTORY
// =============================================================================

/**
 * Create a candy swirl texture on the GPU.
 * @param width - Texture width
 * @param height - Texture height
 * @param scale - Noise scale
 */
export async function createGPUCandySwirlTexture(
    width = 256,
    height = 256,
    scale = 1.0
): Promise<THREE.DataTexture> {
    const gen = new NoiseGeneratorGPU(width, height, { scale });
    await gen.init();
    const texture = await gen.createTexture();
    gen.dispose();
    return texture;
}

/**
 * @file noise_generator.ts
 * @description Procedural noise generation for terrain and textures
 * 
 * Provides CPU-based FBM (Fractal Brownian Motion) noise generation
 * for terrain heightmaps and candy swirl patterns.
 * 
 * @example
 * ```ts
 * import { ProceduralNoiseCompute } from './noise_generator';
 * 
 * const noise = new ProceduralNoiseCompute(256, 256);
 * noise.setScale(2.0);
 * noise.setOctaves(6);
 * 
 * const texture = noise.createTexture();
 * material.map = texture;
 * ```
 */

import * as THREE from 'three';
import { uniform } from 'three/tsl';

/**
 * Configuration for procedural noise generation
 */
export interface NoiseConfig {
    /** Width of the noise texture (default: 256) */
    readonly width?: number;
    /** Height of the noise texture (default: 256) */
    readonly height?: number;
    /** Noise scale factor (default: 1.0) */
    readonly scale?: number;
    /** Number of octaves for FBM (default: 4) */
    readonly octaves?: number;
    /** Initial amplitude for FBM (default: 0.5) */
    readonly amplitude?: number;
    /** Frequency multiplier between octaves (default: 2.0) */
    readonly lacunarity?: number;
    /** Amplitude multiplier between octaves (default: 0.5) */
    readonly persistence?: number;
}

/**
 * Procedural noise generator using FBM.
 * Generates candy swirl patterns for terrain textures.
 */
export class ProceduralNoiseCompute {
    /** Texture width */
    public readonly width: number;

    /** Texture height */
    public readonly height: number;

    /** RGBA data buffer */
    private data: Float32Array;

    /** Scale uniform for shader integration */
    public readonly uScale = uniform(1.0);

    /** Octaves uniform for shader integration */
    public readonly uOctaves = uniform(4);

    /** Time uniform for animated noise */
    public readonly uTime = uniform(0.0);

    /** Lacunarity (frequency multiplier) */
    private lacunarity: number;

    /** Persistence (amplitude multiplier) */
    private persistence: number;

    /**
     * Creates a new procedural noise generator.
     * 
     * @param width - Texture width (default: 256)
     * @param height - Texture height (default: 256)
     * @param config - Additional configuration
     */
    constructor(width: number = 256, height: number = 256, config: NoiseConfig = {}) {
        this.width = width;
        this.height = height;
        this.data = new Float32Array(width * height * 4); // RGBA

        const {
            scale = 1.0,
            octaves = 4,
            lacunarity = 2.0,
            persistence = 0.5
        } = config;

        this.uScale.value = scale;
        this.uOctaves.value = octaves;
        this.lacunarity = lacunarity;
        this.persistence = persistence;
    }

    /**
     * Set the noise scale.
     * @param scale - Scale factor (higher = more zoomed out)
     */
    public setScale(scale: number): void {
        this.uScale.value = scale;
    }

    /**
     * Set the number of octaves for FBM.
     * @param octaves - Number of noise layers (1-8 recommended)
     */
    public setOctaves(octaves: number): void {
        this.uOctaves.value = Math.max(1, Math.min(8, octaves));
    }

    /**
     * Simple hash function for noise generation.
     * 
     * @param x - X coordinate
     * @param y - Y coordinate
     * @returns Hash value in range [0, 1]
     */
    private hash(x: number, y: number): number {
        const n = x * 374761393 + y * 668265263;
        return ((n ^ (n >> 13)) & 0x7fffffff) / 0x7fffffff;
    }

    /**
     * Linear interpolation.
     */
    private lerp(t: number, a: number, b: number): number {
        return a + t * (b - a);
    }

    /**
     * 2D value noise function.
     * 
     * @param x - X coordinate
     * @param y - Y coordinate
     * @returns Noise value in range [0, 1]
     */
    public noise2D(x: number, y: number): number {
        const X = Math.floor(x) & 255;
        const Y = Math.floor(y) & 255;

        x -= Math.floor(x);
        y -= Math.floor(y);

        // Smoothstep interpolation
        const u = x * x * (3 - 2 * x);
        const v = y * y * (3 - 2 * y);

        // Get corner values
        const a = this.hash(X, Y);
        const b = this.hash(X + 1, Y);
        const c = this.hash(X, Y + 1);
        const d = this.hash(X + 1, Y + 1);

        // Bilinear interpolation
        return this.lerp(v,
            this.lerp(u, a, b),
            this.lerp(u, c, d)
        );
    }

    /**
     * Fractal Brownian Motion noise.
     * Combines multiple octaves of noise for more natural results.
     * 
     * @param x - X coordinate
     * @param y - Y coordinate
     * @param octaves - Number of noise layers
     * @returns FBM noise value in range [0, 1]
     */
    public fbm(x: number, y: number, octaves?: number): number {
        const oct = octaves ?? this.uOctaves.value;
        let value = 0;
        let amplitude = 0.5;
        let frequency = 1.0;

        for (let i = 0; i < oct; i++) {
            value += amplitude * this.noise2D(x * frequency, y * frequency);
            frequency *= this.lacunarity;
            amplitude *= this.persistence;
        }

        return value;
    }

    /**
     * Generates the noise texture data.
     * Creates a candy swirl pattern using FBM noise.
     */
    public generate(): void {
        const scale = this.uScale.value || 1.0;
        const octaves = this.uOctaves.value || 4;

        for (let y = 0; y < this.height; y++) {
            for (let x = 0; x < this.width; x++) {
                const i = (y * this.width + x) * 4;

                // Normalized coordinates
                const nx = (x / this.width) * scale;
                const ny = (y / this.height) * scale;

                // Generate base noise
                const noise = this.fbm(nx, ny, octaves);

                // Create candy swirl pattern
                const swirl = Math.sin(nx * 10 + noise * 3) * 0.5 + 0.5;

                // Generate pastel candy colors
                const r = noise * 0.5 + swirl * 0.5;
                const g = noise * 0.7 + (1 - swirl) * 0.3;
                const b = noise * 0.3 + swirl * 0.7;

                this.data[i] = r;
                this.data[i + 1] = g;
                this.data[i + 2] = b;
                this.data[i + 3] = 1.0;
            }
        }
    }

    /**
     * Creates a Three.js DataTexture from the generated noise.
     * 
     * @returns A DataTexture with the noise pattern
     */
    public createTexture(): THREE.DataTexture {
        this.generate();

        const texture = new THREE.DataTexture(
            this.data as any,
            this.width,
            this.height,
            THREE.RGBAFormat,
            THREE.FloatType
        );

        texture.needsUpdate = true;
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        texture.magFilter = THREE.LinearFilter;
        texture.minFilter = THREE.LinearMipmapLinearFilter;

        return texture;
    }

    /**
     * Get a single height value at coordinates.
     * Useful for terrain sampling.
     * 
     * @param x - X coordinate (world space)
     * @param z - Z coordinate (world space)
     * @param scale - Optional scale override
     * @returns Height value
     */
    public getHeight(x: number, z: number, scale?: number): number {
        const s = scale ?? this.uScale.value;
        return this.fbm(x * s, z * s);
    }

    /**
     * Dispose of resources.
     */
    public dispose(): void {
        this.data = new Float32Array(0);
    }
}

/**
 * Creates a simple candy swirl texture.
 * Convenience function for quick texture generation.
 * 
 * @param width - Texture width
 * @param height - Texture height
 * @param scale - Noise scale
 * @returns A DataTexture with candy swirl pattern
 */
export function createCandySwirlTexture(
    width: number = 256,
    height: number = 256,
    scale: number = 1.0
): THREE.DataTexture {
    const noise = new ProceduralNoiseCompute(width, height, { scale });
    const texture = noise.createTexture();
    noise.dispose();
    return texture;
}

/**
 * @file particle_compute.ts
 * @description GPU Compute-based particle system using Three.js TSL
 *
 * This class provides a fully GPU-accelerated particle system with:
 * - Compute shader-based physics updates
 * - Automatic particle respawning
 * - Audio-reactive behavior
 * - WASM offloading for hot loops (optional)
 *
 * @example
 * ```ts
 * import { ComputeParticleSystem } from './particle_compute';
 *
 * const particles = new ComputeParticleSystem(10000, renderer);
 * scene.add(particles.createMesh());
 *
 * // In animation loop:
 * particles.update(deltaTime, { kick: audioState.kickTrigger });
 * ```
 */

import * as THREE from 'three';
import {
    storage,
    uniform,
    vec3,
    vec4,
    float,
    instanceIndex,
    cos,
    sin,
    If,
    Fn,
    uv,
    distance,
    smoothstep,
    vec2,
} from 'three/tsl';
import { StorageInstancedBufferAttribute, PointsNodeMaterial } from 'three/webgpu';
import type { WebGPURenderer } from 'three/webgpu';
import { isCIorHeadless } from '../core/config.ts';
import type { ParticleAudioData } from '../particles/compute-particles-types.ts';
import type { ParticleAudioState } from '../particles/particle_config.ts';

/** Local config for GPU compute particle system (distinct from factory ComputeParticleConfig). */
interface ParticleComputeConfig {
    type?: 'rain' | 'mist' | 'default';
    spawnCenter?: THREE.Vector3;
    gravity?: THREE.Vector3;
}

/**
 * Interface for optional WASM particle physics module
 */
interface WASMParticleModule {
    /**
     * Updates particle positions and velocities via WASM
     * @param posPtr - Pointer to position buffer in WASM memory
     * @param velPtr - Pointer to velocity buffer in WASM memory
     * @param count - Number of particles
     * @param dt - Delta time in seconds
     * @param gravity - Gravity strength
     * @param audio - Audio pulse strength (0-1)
     */
    updateParticlesWASM?(
        posPtr: number,
        velPtr: number,
        count: number,
        dt: number,
        gravity: number,
        audio: number
    ): void;
}

/**
 * GPU Compute-based particle system.
 * Uses TSL storage buffers and compute shaders for physics.
 */
export class ComputeParticleSystem {
    /** Total particle count */
    public readonly count: number;

    /** WebGPU renderer reference */
    private readonly renderer: WebGPURenderer;

    /** Position + life storage buffer (x, y, z, life) */
    private positionBuffer: Float32Array;

    /** Velocity + speed storage buffer (vx, vy, vz, speed) */
    private velocityBuffer: Float32Array;

    /** Color storage buffer (r, g, b, a) */
    private colorBuffer: Float32Array;

    /** TSL storage nodes */
    private positionStorage: ReturnType<typeof storage>;
    private velocityStorage: ReturnType<typeof storage>;
    private colorStorage: ReturnType<typeof storage>;

    /** Uniforms */
    private readonly uTime = uniform(0.0);
    private readonly uDeltaTime = uniform(0.016);
    private readonly uGravity: ReturnType<typeof uniform>;
    private readonly uSpawnCenter: ReturnType<typeof uniform>;
    private readonly uAudioPulse = uniform(0.0);

    /** Type of particle system */
    private readonly type: 'rain' | 'mist' | 'default';

    /** Compute shader node */
    private computeNode: any = null;

    /** Uniforms for audio/weather reactivity */
    private readonly uIntensity = uniform(0.0);
    private readonly uBassIntensity = uniform(0.0);
    private readonly uMelodyVolume = uniform(0.0);

    /** The actual Points mesh (stored for color updates) */
    private mesh: THREE.Points | null = null;

    /** Optional WASM module for physics */
    private wasmModule: WASMParticleModule | null = null;

    /** Whether to use WASM for physics (if available) */
    private useWASM: boolean = false;

    /**
     * Creates a new compute particle system.
     *
     * @param count - Number of particles (default: 10000)
     * @param renderer - WebGPU renderer instance
     * @param config - Optional configuration
     */
    constructor(count: number, renderer: WebGPURenderer, config: ParticleComputeConfig = {}) {
        this.count = count;
        this.renderer = renderer;
        this.type = config.type || 'default';

        const {
            spawnCenter = new THREE.Vector3(0, 5, 0),
            gravity = new THREE.Vector3(0, -2.0, 0),
        } = config;

        // Initialize buffers
        this.positionBuffer = new Float32Array(count * 4); // xyz + life
        this.velocityBuffer = new Float32Array(count * 4); // xyz + speed
        this.colorBuffer = new Float32Array(count * 4); // rgba

        this.initParticles();

        // Create storage buffer nodes
        this.positionStorage = storage(
            new StorageInstancedBufferAttribute(this.positionBuffer, 4),
            'vec4',
            this.count
        );
        this.velocityStorage = storage(
            new StorageInstancedBufferAttribute(this.velocityBuffer, 4),
            'vec4',
            this.count
        );
        this.colorStorage = storage(
            new StorageInstancedBufferAttribute(this.colorBuffer, 4),
            'vec4',
            this.count
        );

        // Create uniforms
        this.uGravity = uniform(gravity);
        this.uSpawnCenter = uniform(spawnCenter);

        this.setupComputeShader();
    }

    /**
     * Initialize particle data with random values
     */
    private initParticles(): void {
        for (let i = 0; i < this.count; i++) {
            const i4 = i * 4;

            // Spread out initially
            this.positionBuffer[i4] = (Math.random() - 0.5) * 50;
            this.positionBuffer[i4 + 1] = Math.random() * 20;
            this.positionBuffer[i4 + 2] = (Math.random() - 0.5) * 50;
            this.positionBuffer[i4 + 3] = Math.random(); // life

            this.velocityBuffer[i4] = (Math.random() - 0.5) * 2;
            this.velocityBuffer[i4 + 1] = Math.random() * 5;
            this.velocityBuffer[i4 + 2] = (Math.random() - 0.5) * 2;
            this.velocityBuffer[i4 + 3] = 1.0; // speed

            // HSL-ish color (hue, sat, lightness, alpha)
            this.colorBuffer[i4] = Math.random(); // Hue
            this.colorBuffer[i4 + 1] = 0.8; // Sat
            this.colorBuffer[i4 + 2] = 0.8; // Light
            this.colorBuffer[i4 + 3] = 1.0; // Alpha
        }
    }

    /**
     * Setup the TSL compute shader for particle physics
     */
    private setupComputeShader(): void {
        // TSL Compute Logic
        const computeLogic = (Fn as any)(() => {
            const idx = instanceIndex;

            // Fetch current particle data
            const posData = this.positionStorage.element(idx);
            const velData = this.velocityStorage.element(idx);

            // Read current values into variables
            const position = posData.toVar();
            const velocity = velData.toVar();

            // Physics
            const dt = this.uDeltaTime;

            if (this.type === 'rain') {
                // Rain: fast downward velocity, audio boost from bass
                const gravity = this.uGravity.mul(dt);
                velocity.y.addAssign(gravity.y);
                const speed = velocity.w.mul(this.uBassIntensity.mul(2.0).add(1.0));

                position.x.addAssign(velocity.x.mul(dt).mul(speed));
                position.y.addAssign(velocity.y.mul(dt).mul(speed));
                position.z.addAssign(velocity.z.mul(dt).mul(speed));

                position.w.subAssign(dt.mul(0.5)); // faster decay
            } else if (this.type === 'mist') {
                // Mist: slow drift, upward sine motion based on melody
                // Drift horizontally based on time and index
                const tOffset = this.uTime.add(float(idx).mul(0.1));
                const driftX = sin(this.uTime.mul(0.5).add(tOffset)).mul(2.0);
                const driftZ = cos(this.uTime.mul(0.4).add(tOffset)).mul(2.0);

                velocity.x.assign(driftX);
                velocity.z.assign(driftZ);

                // Slight upward pull
                velocity.y.assign(
                    float(1.0).add(sin(tOffset).mul(1.5).mul(this.uMelodyVolume.max(0.3)))
                );

                position.x.addAssign(velocity.x.mul(dt));
                position.y.addAssign(velocity.y.mul(dt));
                position.z.addAssign(velocity.z.mul(dt));

                position.w.subAssign(dt.mul(0.1)); // slow decay
            } else {
                // Default physics
                const gravity = this.uGravity.mul(dt);
                velocity.y.addAssign(gravity.y);
                const speed = velocity.w.mul(this.uAudioPulse.mul(2.0).add(1.0));

                position.x.addAssign(velocity.x.mul(dt).mul(speed));
                position.y.addAssign(velocity.y.mul(dt).mul(speed));
                position.z.addAssign(velocity.z.mul(dt).mul(speed));

                position.w.subAssign(dt.mul(0.3));
            }

            // Respawn Logic - when life < 0, reset particle
            If(position.w.lessThan(0.0), () => {
                // Reset Life
                position.w.assign(1.0);

                const seed = float(idx).mul(0.123).add(this.uTime.mul(0.1));

                if (this.type === 'rain') {
                    // Rain respawns high up in a wide area
                    const offsetX = sin(seed.mul(12.9898)).mul(50.0);
                    const offsetZ = cos(seed.mul(78.233)).mul(50.0);
                    const offsetY = float(20.0).add(cos(seed.mul(14.3)).mul(15.0)); // 5 to 35

                    position.x.assign(this.uSpawnCenter.x.add(offsetX));
                    position.y.assign(this.uSpawnCenter.y.add(offsetY));
                    position.z.assign(this.uSpawnCenter.z.add(offsetZ));

                    velocity.y.assign(float(-5.0).sub(sin(seed).mul(5.0)));
                    velocity.x.assign(float(0.0));
                    velocity.z.assign(float(0.0));
                } else if (this.type === 'mist') {
                    // Mist respawns low in a wide area
                    const offsetX = sin(seed.mul(12.9898)).mul(40.0);
                    const offsetZ = cos(seed.mul(78.233)).mul(40.0);
                    const offsetY = float(0.0).add(cos(seed.mul(14.3)).mul(2.5));

                    position.x.assign(this.uSpawnCenter.x.add(offsetX));
                    position.y.assign(this.uSpawnCenter.y.add(offsetY));
                    position.z.assign(this.uSpawnCenter.z.add(offsetZ));

                    velocity.y.assign(float(0.5));
                    velocity.x.assign(float(0.0));
                    velocity.z.assign(float(0.0));
                } else {
                    const offsetX = sin(seed.mul(12.9898)).mul(10.0);
                    const offsetZ = cos(seed.mul(78.233)).mul(10.0);
                    position.x.assign(this.uSpawnCenter.x.add(offsetX));
                    position.y.assign(this.uSpawnCenter.y);
                    position.z.assign(this.uSpawnCenter.z.add(offsetZ));

                    const velSeed = seed.add(float(idx).mul(0.456));
                    velocity.y.assign(float(5.0).add(cos(velSeed).mul(2.0)));
                    velocity.x.assign(sin(velSeed).mul(2.0));
                    velocity.z.assign(cos(velSeed.mul(1.5)).mul(2.0));
                }
            });

            // Write back to storage
            posData.assign(position);
            velData.assign(velocity);
        });

        // Create compute node
        this.computeNode = (computeLogic as any)().compute(this.count);
    }

    /**
     * Set optional WASM module for physics offloading.
     *
     * Note: WASM execution is reserved for future optimization.
     * Currently, the GPU compute shader handles all physics.
     * The WASM module can be used for CPU fallback when WebGPU
     * compute shaders are not available.
     *
     * @param module - WASM module with updateParticlesWASM function
     */
    public setWASMModule(module: WASMParticleModule): void {
        this.wasmModule = module;
        this.useWASM = typeof module.updateParticlesWASM === 'function';
        if (this.useWASM) {
            console.log(
                '[ComputeParticles] WASM physics module registered (GPU compute primary, WASM fallback available)'
            );
        }
    }

    /**
     * Update particle system.
     * Runs compute shader on GPU (primary) or uses WASM fallback if GPU compute unavailable.
     *
     * @param deltaTime - Time since last frame in seconds
     * @param audioState - Optional audio state for reactive behavior
     * @param intensity - Weather intensity (0 to 1)
     */
    public update(
        deltaTime: number,
        audioState: ParticleAudioState = {},
        intensity: number = 0.0
    ): void {
        this.uDeltaTime.value = deltaTime;
        this.uTime.value += deltaTime;
        this.uAudioPulse.value = audioState.kick ?? 0;
        this.uBassIntensity.value = audioState.low ?? audioState.kick ?? 0;
        this.uMelodyVolume.value = audioState.mid ?? audioState.level ?? 0;
        this.uIntensity.value = intensity;

        // Execute Compute Shader on GPU (primary path)
        if (this.computeNode && !isCIorHeadless()) {
            this.renderer.compute(this.computeNode);
        }
        // Note: WASM fallback would be implemented here if GPU compute is unavailable
        // Currently GPU compute is always available when WebGPU renderer is used
    }

    /**
     * Set the spawn center position.
     *
     * @param position - New spawn center
     */
    public setSpawnCenter(position: THREE.Vector3): void {
        (this.uSpawnCenter.value as any).copy(position);
    }

    /**
     * Set gravity vector.
     *
     * @param gravity - New gravity vector
     */
    public setGravity(gravity: THREE.Vector3): void {
        (this.uGravity.value as any).copy(gravity);
    }

    /**
     * Creates a Three.js Points mesh for rendering the particles.
     *
     * @returns A Points mesh using the particle storage buffers
     */
    public createMesh(): THREE.Points {
        const geometry = new THREE.BufferGeometry();

        // Use storage buffers as geometry attributes
        geometry.setAttribute('position', this.positionStorage as unknown as THREE.BufferAttribute);
        geometry.setAttribute('color', this.colorStorage as unknown as THREE.BufferAttribute);
        geometry.drawRange.count = this.count;

        let size = 0.2;
        let opacity = 0.8;
        let baseColorHex = 0xffffff;

        if (this.type === 'rain') {
            size = 0.3;
            baseColorHex = 0x88ccff;
        } else if (this.type === 'mist') {
            size = 0.15;
            opacity = 0.4;
            baseColorHex = 0xaaffaa;
        }

        const material = new PointsNodeMaterial({
            size: size,
            color: baseColorHex,
            transparent: true,
            opacity: opacity,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
        });

        // Use buffer data in shader
        const particlePos = (this.positionStorage as any).toAttribute();
        const life = particlePos.w;

        material.positionNode = particlePos.xyz;

        // Soft circular disc mask via uv() prevents Three.js from emitting
        // gl_PointCoord (a GLSL-only built-in) in the generated WGSL shader.
        const pointCircle = smoothstep(float(0.5), float(0.2), distance(uv(), vec2(0.5, 0.5)));

        if (this.type === 'rain') {
            (material as any).sizeNode = float(size).add(this.uBassIntensity.mul(0.5));
            const targetOpacity = float(0.4).add(this.uIntensity.mul(0.6));
            material.opacityNode = targetOpacity.mul(life).mul(pointCircle);
        } else if (this.type === 'mist') {
            const targetOpacity = float(0.3).add(this.uMelodyVolume.mul(0.4));
            material.opacityNode = targetOpacity.mul(life).mul(pointCircle);
        } else {
            (material as any).sizeNode = float(0.2).mul(life); // Shrink as they die
            material.colorNode = vec4(1.0, 0.5, 0.2, life); // Simple fade
        }

        this.mesh = new THREE.Points(geometry, material);
        this.mesh.userData.type = 'computeParticles';

        return this.mesh;
    }

    /**
     * Update the base color of the particle material
     */
    public setBaseColor(colorHex: number): void {
        if (this.mesh && this.mesh.material instanceof PointsNodeMaterial) {
            this.mesh.material.color.setHex(colorHex);
        }
    }

    /**
     * Dispose of all resources.
     */
    public dispose(): void {
        // Clear buffers (let GC handle them)
        this.positionBuffer = new Float32Array(0);
        this.velocityBuffer = new Float32Array(0);
        this.colorBuffer = new Float32Array(0);
        this.computeNode = null;
    }
}

/**
 * @file webgpu-safety.ts
 * @description WebGPU safety utilities for preventing validation errors when GPU buffers
 * are allocated with zero or minimal element counts.
 *
 * Problem: When CORE mode is active, certain entity registries (e.g., LuminousPlants) 
 * may be empty. If a TSL material's shader code has storage buffer bindings for these 
 * registries, WebGPU will fail validation when the backing buffer has size 0.
 *
 * Solution: Always allocate a minimum 1-element dummy buffer to keep the GPU descriptor
 * layout happy, even when no actual data is present.
 */

/**
 * Minimum safe buffer size for WebGPU storage buffers.
 * Prevents validation errors when registries are empty.
 * 
 * 4 bytes = size of a single f32 or u32
 */
const MIN_SAFE_BUFFER_SIZE = 4;

/**
 * Safely create a storage buffer with minimum size guarantee.
 * 
 * Even if activeCount is 0, allocates at least 1 element to prevent
 * WebGPU validation errors during bind group creation.
 * 
 * @param device - WebGPU device
 * @param activeCount - Number of active elements (may be 0)
 * @param elementSizeBytes - Size of each element in bytes (default: 4)
 * @param usage - GPU buffer usage flags (default: STORAGE | COPY_DST)
 * @returns GPUBuffer with guaranteed minimum size
 * 
 * @example
 * ```ts
 * // CORE mode: luminousPlants.count = 0
 * const count = luminousPlantBatcher?.mesh?.count || 0;
 * const buffer = createSafeStorageBuffer(
 *     device,
 *     count,  // 0 in CORE mode
 *     4,      // one float32
 *     GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST
 * );
 * // Buffer will have size 4 bytes minimum, preventing validation errors
 * ```
 */
export function createSafeStorageBuffer(
    device: GPUDevice,
    activeCount: number,
    elementSizeBytes: number = 4,
    usage: number = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST
): GPUBuffer {
    // Ensure at least 1 element
    const minCount = Math.max(activeCount, 1);
    const sizeBytes = minCount * elementSizeBytes;

    return device.createBuffer({
        size: sizeBytes,
        usage: usage,
        mappedAtCreation: false,
        label: `safe-storage-${activeCount > 0 ? 'active' : 'dummy'}`
    });
}

/**
 * Safely create a uniform buffer with minimum size guarantee.
 * Uniform buffers must be 256-byte aligned for WebGPU.
 * 
 * @param device - WebGPU device
 * @param activeCount - Number of active elements (may be 0)
 * @param elementSizeBytes - Size of each element (must be multiple of 256 for alignment)
 * @returns GPUBuffer with guaranteed minimum size
 */
export function createSafeUniformBuffer(
    device: GPUDevice,
    activeCount: number,
    elementSizeBytes: number = 256
): GPUBuffer {
    // Ensure at least 1 element and proper alignment
    const minCount = Math.max(activeCount, 1);
    const sizeBytes = minCount * elementSizeBytes;

    // Align to 256-byte boundary (WebGPU requirement)
    const alignedSize = Math.ceil(sizeBytes / 256) * 256;

    return device.createBuffer({
        size: alignedSize,
        usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
        mappedAtCreation: false,
        label: `safe-uniform-${activeCount > 0 ? 'active' : 'dummy'}`
    });
}

/**
 * Check if a registry is empty (CORE mode detection).
 * Returns true if the entity count is 0.
 * 
 * @param count - Number of active entities
 * @returns true if empty (CORE mode likely active)
 */
export function isEmptyRegistry(count: number): boolean {
    return count === 0;
}

/**
 * Log a warning when a compute dispatch is skipped due to empty registry.
 * Helps with debugging and performance analysis.
 * 
 * @param systemName - Name of the compute system (e.g., "LuminousPlantAnimator")
 * @param activeCount - Number of active entities
 */
export function logEmptyRegistryDispatch(systemName: string, activeCount: number): void {
    console.warn(
        `[WebGPU Safety] ${systemName}: Core mode detected (${activeCount} entities). ` +
        `Allocating dummy buffer to prevent validation error. Compute dispatch will be skipped.`
    );
}

/**
 * Validate WebGPU compute buffer configuration.
 * Ensures that all buffers in a bind group have compatible sizes and usage.
 * 
 * @param buffers - Array of GPU buffers to validate
 * @param expectedMinSize - Minimum expected buffer size
 * @returns true if all buffers are valid
 */
export function validateComputeBuffers(
    buffers: (GPUBuffer | null)[],
    expectedMinSize: number = MIN_SAFE_BUFFER_SIZE
): boolean {
    return buffers.every(buf => {
        if (!buf) return false;
        // WebGPU doesn't expose buffer size, so we assume if the buffer exists, it's valid
        // The safety is in createSafeStorageBuffer ensuring minimum size
        return true;
    });
}

export { MIN_SAFE_BUFFER_SIZE };

export function isCIorHeadless(): boolean {
    return (
        (typeof navigator !== 'undefined' &&
            /headless|playwright|ci|test/i.test(navigator.userAgent || '')) ||
        (typeof window !== 'undefined' && (window as any).__IS_FULL_BOOT_TEST === true) ||
        (typeof localStorage !== 'undefined' &&
            localStorage.getItem('__IS_FULL_BOOT_TEST') === 'true') ||
        (typeof navigator !== 'undefined' && (navigator as any).webdriver === true)
    );
}

/**
 * Approximate device RAM in GB via `navigator.deviceMemory` (Chrome/Edge).
 * Returns `undefined` when the API is unavailable (Firefox, Safari, etc.).
 */
export function getDeviceMemoryGB(): number | undefined {
    if (typeof navigator === 'undefined') return undefined;
    const gb = (navigator as any).deviceMemory;
    return typeof gb === 'number' && gb > 0 ? gb : undefined;
}

/**
 * JS heap usage ratio when `performance.memory` is available (Chromium).
 * Returns 0 when unavailable so callers can treat it as "unknown / fine".
 */
export function getJsHeapUsageRatio(): number {
    try {
        if (typeof performance === 'undefined') return 0;
        const mem = (performance as any).memory;
        if (!mem || !mem.jsHeapSizeLimit) return 0;
        return mem.usedJSHeapSize / mem.jsHeapSizeLimit;
    } catch {
        return 0;
    }
}

export type LoadMemoryTier = 'critical' | 'low' | 'medium' | 'high';

/**
 * Coarse RAM tier used to scale world population and batcher caps on load.
 * Prefers `navigator.deviceMemory`; falls back to JS heap pressure when present.
 */
export function getLoadMemoryTier(): LoadMemoryTier {
    const gb = getDeviceMemoryGB();
    if (typeof gb === 'number') {
        if (gb <= 2) return 'critical';
        if (gb <= 4) return 'low';
        if (gb <= 8) return 'medium';
        return 'high';
    }
    const heapRatio = getJsHeapUsageRatio();
    if (heapRatio >= 0.75) return 'critical';
    if (heapRatio >= 0.55) return 'low';
    if (heapRatio >= 0.35) return 'medium';
    return 'high';
}

/**
 * Multiplier applied to spawn counts / batcher caps for the current device.
 * 1.0 = full fidelity; lower values reduce RAM spikes during load.
 */
export function getLoadMemoryScale(): number {
    const tier = getLoadMemoryTier();
    switch (tier) {
        case 'critical':
            return 0.35;
        case 'low':
            return 0.55;
        case 'medium':
            return 0.8;
        default:
            return 1.0;
    }
}

/** True when the device should prefer lighter world modes on first paint. */
export function shouldPreferLightWorldLoad(): boolean {
    const tier = getLoadMemoryTier();
    if (tier === 'critical' || tier === 'low') return true;
    try {
        if (new URLSearchParams(window.location.search).has('lite')) return true;
    } catch {
        /* non-browser */
    }
    return false;
}

/**
 * Returns a CI/headless- or memory-adjusted count.
 * - CI/headless: aggressive reduction to prevent Playwright OOM.
 * - Consumer browsers: scales by `getLoadMemoryScale()` so low-RAM Windows
 *   machines do not lock up during Full-mode population.
 */
export function getCIAdjustedCount(fullCount: number, ciMultiplier = 0.15, minCount = 5): number {
    if (isCIorHeadless()) {
        const adjusted = Math.max(minCount, Math.floor(fullCount * ciMultiplier));
        console.log(`[CI Adjusted] ${fullCount} → ${adjusted} (multiplier: ${ciMultiplier})`);
        return adjusted;
    }
    const memScale = getLoadMemoryScale();
    if (memScale < 1) {
        const adjusted = Math.max(minCount, Math.floor(fullCount * memScale));
        if (adjusted !== fullCount) {
            console.log(
                `[Memory Adjusted] ${fullCount} → ${adjusted} (tier: ${getLoadMemoryTier()}, scale: ${memScale})`
            );
        }
        return adjusted;
    }
    return fullCount;
}

// src/core/deferred-init.ts
// Deferred visual initialization system

import * as THREE from 'three';
import { createAurora, harmonyOrbSystem } from '../foliage/aurora.ts';
import { initCelestialBodies } from '../foliage/celestial-bodies.ts';
import { createChromaticPulse } from '../foliage/chromatic.ts';
import { createDandelionSeedSystem } from '../foliage/dandelion-seeds.ts';
import { createDiscoveryEffect } from '../foliage/discovery-effect.ts';
import { createFluidFog } from '../foliage/fluid_fog.ts';
import { createImpactSystem } from '../foliage/impacts.ts';
import { uTime } from '../foliage/index.ts';
import { createMelodyRibbon } from '../foliage/ribbons.ts';
import { createShield } from '../foliage/shield.ts';
import { createSparkleTrail } from '../foliage/sparkle-trail.ts';
import { createStrobePulse } from '../foliage/strobe.ts';
import { ensureGameplay, preloadGameplay } from '../gameplay/lazy.ts';
import { initAwakenedPersistenceIfNeeded } from '../systems/awakened-persistence-api.ts';
import { startPhase, endPhase, recordWarmupMetrics } from '../utils/startup-profiler.ts';
import { animatedFoliage } from '../world/state.ts';
import { isCIorHeadless, FEATURE_FLAGS } from './config.ts';
import { syncDrawingBufferFromWindow } from './init.ts';

// Deferred visual elements
let aurora: THREE.Object3D | null = null;
let chromaticPulse: THREE.Object3D | null = null;
let strobePulse: THREE.Object3D | null = null;
let celestialBodiesInitialized = false;
let melodyRibbon: any = null;
let sparkleTrail: any = null;
let impactSystem: any = null;
let fluidFog: THREE.Mesh | null = null;
let playerShieldMesh: THREE.Object3D | null = null;
let dandelionSeedSystem: THREE.Object3D | null = null;
let discoveryEffect: any = null;
let harpoonLine: THREE.Mesh | null = null;

// Scene references (set during initialization)
let sceneRef: THREE.Scene | null = null;
let cameraRef: THREE.Camera | null = null;
let rendererRef: any = null;

export function initDeferredVisualsDependencies(
    scene: THREE.Scene,
    camera: THREE.Camera,
    renderer: any
) {
    sceneRef = scene;
    cameraRef = camera;
    rendererRef = renderer;
}

export function initDeferredVisuals() {
    if (!sceneRef || !cameraRef) {
        console.warn('[Deferred] Cannot initialize visuals: scene or camera not set');
        return;
    }

    // Arm the GPU compute library in the background so MeshDeformationGPU,
    // NoiseGeneratorGPU, and GPUCullingSystem find a warm device on first use.
    // Resolves silently when WebGPU is unavailable; CPU/WASM fallbacks stay active.
    void import('../compute/compute-init.ts').then(({ initGPUCompute }) => {
        initGPUCompute();
        return import('../compute/compute-orchestrator.ts');
    }).then(({ ensureGpuComputeReady }) => {
        void ensureGpuComputeReady().then(async () => {
            const { initGpuFoliageOrchestrator } = await import('../compute/gpu-foliage-orchestrator.ts');
            void initGpuFoliageOrchestrator();
        });
    });

    // Prefetch gameplay chunk in parallel with visual init (#1361)
    void preloadGameplay().then((gp) => {
        if (!sceneRef) return;
        if (gp.jitterMineSystem.mesh && !gp.jitterMineSystem.mesh.parent) {
            sceneRef.add(gp.jitterMineSystem.mesh);
            console.log('[Deferred] Jitter Mine System initialized');
        }
        gp.chordStrikeSystem.addToScene(sceneRef);
        if (!harpoonLine) {
            harpoonLine = gp.createHarpoonLine();
            sceneRef.add(harpoonLine);
            console.log('[Deferred] Harpoon Line initialized');
        }
    });

    if (FEATURE_FLAGS.awakenedPersistence) {
        initAwakenedPersistenceIfNeeded();
    }

    console.time('Deferred Visuals Init');

    // Group 1: Environmental effects (order matters for layering)
    console.time('Environmental Effects');
    if (!fluidFog) {
        fluidFog = createFluidFog(200, 200); // 200x200 patch at center
        sceneRef.add(fluidFog);
        console.log('[Deferred] Fluid Fog initialized');
    }

    if (!aurora) {
        aurora = createAurora();
        sceneRef.add(aurora);
        harmonyOrbSystem.addToScene(sceneRef); // Add Harmony Orbs
        console.log('[Deferred] Aurora & Systems initialized');
    }

    if (!chromaticPulse) {
        chromaticPulse = createChromaticPulse();
        cameraRef.add(chromaticPulse);
        console.log('[Deferred] Chromatic Pulse initialized');
    }

    if (!strobePulse) {
        strobePulse = createStrobePulse();
        cameraRef.add(strobePulse);
        console.log('[Deferred] Strobe Pulse initialized');
    }
    console.timeEnd('Environmental Effects');

    // Group 2: Celestial and world elements
    console.time('Celestial Elements');
    if (!celestialBodiesInitialized) {
        initCelestialBodies(sceneRef);
        celestialBodiesInitialized = true;
        console.log('[Deferred] Celestial bodies initialized');
    }
    console.timeEnd('Celestial Elements');

    // Group 3: Interactive musical elements
    console.time('Musical Elements');
    if (!melodyRibbon) {
        melodyRibbon = createMelodyRibbon(sceneRef);
        console.log('[Deferred] Melody Ribbon initialized');
    }

    if (!sparkleTrail) {
        sparkleTrail = createSparkleTrail();
        sceneRef.add(sparkleTrail);
        console.log('[Deferred] Sparkle Trail initialized');
    }

    if (!impactSystem) {
        impactSystem = createImpactSystem();
        sceneRef.add(impactSystem);
        console.log('[Deferred] Impact System initialized');
    }

    if (!dandelionSeedSystem) {
        dandelionSeedSystem = createDandelionSeedSystem();
        sceneRef.add(dandelionSeedSystem);
        console.log('[Deferred] Dandelion Seed System initialized');
    }

    if (!discoveryEffect) {
        discoveryEffect = createDiscoveryEffect();
        sceneRef.add(discoveryEffect.mesh);
        console.log('[Deferred] Discovery Effect initialized');

        // Export to global for easy triggering from discovery-optimized.ts
        (window as any).triggerDiscoveryEffect = (position: THREE.Vector3) => {
            if (discoveryEffect && discoveryEffect.trigger) {
                // Ensure we use the current global shader time
                discoveryEffect.trigger(position, uTime.value);
            }
        };
    }

    // Gameplay meshes (jitter / harpoon / chord) attach via preloadGameplay() above
    console.timeEnd('Musical Elements');

    console.timeEnd('Deferred Visuals Init');
}

/**
 * Apply persisted awakened glow to batchers after world entities are placed.
 * Called once post-populateWorld — O(awakened) GPU upload, no scene traversal.
 */
export function applyAwakenedPersistenceAfterWorldLoad(): void {
    if (!FEATURE_FLAGS.awakenedPersistence) return;
    void import('../systems/awakened-persistence.ts').then((m) => {
        m.getAwakenedStore()?.reconcileAndApplyToBatchers();
    });
}

// --- DEFERRED INCREMENTAL SHADER WARMUP ---
// Runs 2 seconds after world generation to pre-compile remaining shaders without
// blocking the main thread. Uses ShaderWarmup in time-budgeted batches so no
// single task exceeds WARMUP_BUDGET_MS.

/** Number of materials compiled per batch before yielding to the event loop. */
const WARMUP_BATCH_SIZE = 10;
/** Maximum milliseconds allowed per warmup batch before yielding. */
const WARMUP_BUDGET_MS = 100;

/** Set to true to cancel an in-progress deferred warmup (e.g. on scene transition). */
let _warmupAborted = false;

/** Cancel any in-progress deferred shader warmup. */
export function abortWarmup(): void {
    _warmupAborted = true;
}

export function runDeferredWarmup(scene: THREE.Scene, camera: THREE.Camera, renderer: any) {
    _warmupAborted = false;

    setTimeout(async () => {
        startPhase('Shader Warmup');
        performance.mark('candy:shader-warmup-start');
        console.log('[Deferred] Starting incremental shader pre-compilation...');

        // Check CI bypass here
        if (isCIorHeadless()) {
            console.log(
                '[Deferred] Skipping incremental shader pre-compilation in CI mode to prevent WebGPU Device Lost'
            );
            endPhase('Shader Warmup');
            return;
        }

        // FIX: Ensure clipping planes are defined before compilation.
        // WebGPURenderer 0.171.0+ can crash in setupHardwareClipping if undefined.
        if (renderer.clippingPlanes === undefined || renderer.clippingPlanes === null) {
            renderer.clippingPlanes = [];
            renderer.localClippingEnabled = false;
            console.log('[Deferred] Re-applied clipping planes fix (Safety Force).');
        }

        // Keep the rainbow blaster warmup — it uses a distinct particle material.
        const dummyOrigin = new THREE.Vector3(0, -9999, 0);
        const dummyDir = new THREE.Vector3(0, 1, 0);
        const gp = await ensureGameplay();
        gp.fireRainbow(scene, dummyOrigin, dummyDir);

        let warmupBatches = 0;
        let warmupBatchMaxMs = 0;

        try {
            // --- Phase 1: Compile predefined foliage / preset materials in batches ---
            // ShaderWarmup renders each material in a 1×1 pixel target and disposes
            // the temporary mesh+render-target; the original scene materials are unaffected.
            const { ShaderWarmup } = await import('../rendering/shader-warmup.ts');
            const warmup = new ShaderWarmup();
            const targets = warmup.getTargets();

            for (let i = 0; i < targets.length; i += WARMUP_BATCH_SIZE) {
                if (_warmupAborted) break;

                const batchStart = performance.now();
                const batch = targets.slice(i, i + WARMUP_BATCH_SIZE);

                for (const target of batch) {
                    if (_warmupAborted) break;
                    const mat = target.create();
                    try {
                        await warmup.warmupSingle(mat, renderer, target.name);
                    } catch (_e) {
                        // Non-fatal: continue with next material.
                    }
                }

                const batchMs = performance.now() - batchStart;
                warmupBatches++;
                if (batchMs > warmupBatchMaxMs) warmupBatchMaxMs = batchMs;

                // Always yield between batches to stay within the 100 ms long-task budget.
                await new Promise<void>((resolve) => setTimeout(resolve, 0));
            }
            warmup.dispose();

            // --- Phase 2: Compile materials found on actual scene objects ---
            // Frustum-visible objects are prioritised so the player's current view
            // is fully warmed before off-screen geometry.
            if (!_warmupAborted) {
                const frustum = new THREE.Frustum();
                const projMatrix = new THREE.Matrix4().multiplyMatrices(
                    (camera as any).projectionMatrix,
                    (camera as any).matrixWorldInverse
                );
                frustum.setFromProjectionMatrix(projMatrix);

                // Collect unique materials from scene meshes.
                const sceneEntries: Array<{ mat: THREE.Material; inFrustum: boolean }> = [];
                const seenIds = new Set<number>();

                scene.traverse((obj: THREE.Object3D) => {
                    if (!(obj instanceof THREE.Mesh) || !obj.visible) return;
                    const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
                    const inFrustum = frustum.intersectsObject(obj);
                    for (const mat of mats) {
                        if (!mat || seenIds.has(mat.id)) continue;
                        seenIds.add(mat.id);
                        sceneEntries.push({ mat, inFrustum });
                    }
                });

                // Frustum-visible first.
                sceneEntries.sort((a, b) => {
                    if (a.inFrustum === b.inFrustum) return 0;
                    return a.inFrustum ? -1 : 1;
                });

                // Compile each material by cloning it so warmupSingle can safely dispose
                // the clone while the original in the scene remains intact.
                const { ShaderWarmup } = await import('../rendering/shader-warmup.ts');
                const sceneWarmup = new ShaderWarmup();
                for (let i = 0; i < sceneEntries.length; i += WARMUP_BATCH_SIZE) {
                    if (_warmupAborted) break;

                    const batchStart = performance.now();
                    const batch = sceneEntries.slice(i, i + WARMUP_BATCH_SIZE);

                    for (const { mat } of batch) {
                        if (_warmupAborted) break;
                        try {
                            // Clone so warmupSingle can dispose the temporary copy.
                            const clone = mat.clone();
                            await sceneWarmup.warmupSingle(clone, renderer, `scene_${mat.id}`);
                        } catch (_e) {
                            /* skip */
                        }
                    }

                    const batchMs = performance.now() - batchStart;
                    warmupBatches++;
                    if (batchMs > warmupBatchMaxMs) warmupBatchMaxMs = batchMs;

                    // Yield if the batch took too long or more batches remain.
                    if (batchMs > WARMUP_BUDGET_MS || i + WARMUP_BATCH_SIZE < sceneEntries.length) {
                        await new Promise<void>((resolve) => setTimeout(resolve, 0));
                    }
                }
                sceneWarmup.dispose();
            }

            console.log(
                `✅ Scene shaders pre-compiled (${warmupBatches} batch${warmupBatches !== 1 ? 'es' : ''}, ` +
                    `max ${warmupBatchMaxMs.toFixed(0)} ms/batch).`
            );
        } catch (e) {
            console.warn('[Warmup] Shader compilation error:', e);
        }

        // Refresh canvas MSAA buffer after 1×1 warmup renders (same as startup shader warmup).
        syncDrawingBufferFromWindow(renderer);

        // Record warmup metrics for the startup profiler report.
        recordWarmupMetrics(warmupBatches, warmupBatchMaxMs);

        performance.mark('candy:shader-warmup-end');
        try {
            performance.measure(
                'candy:Shader Warmup',
                'candy:shader-warmup-start',
                'candy:shader-warmup-end'
            );
        } catch (_e) {
            /* ignore if marks were cleared */
        }

        console.log('[Deferred] Shader compilation complete');
        endPhase('Shader Warmup');
    }, 2000); // 2-second delay lets the browser settle after initial load.
}

