export function safeUpdateBatcher(batcher: any, delta: number, label = 'batcher', pos?: any) {
    if (batcher && typeof batcher.update === 'function') {
        try {
            batcher.update(delta, pos);
        } catch (err) {
            console.warn(
                `[GameLoop] Skipped update on ${label} (likely empty or incomplete in Core mode)`,
                err
            );
        }
    }
}

export function safeSystemUpdate(updateFn: any, label: string, ...args: any[]) {
    if (typeof updateFn !== 'function') return;
    try {
        updateFn(...args);
    } catch (err) {
        console.warn(`[GameLoop] Skipped ${label} update in Core mode`, err);
    }
}

