    beatFlashIntensity,
    setBeatFlashIntensity,
    cameraZoomPulse,
    setCameraZoomPulse,
    cameraShake,
    setCameraShakeCore,
    lastBeatPhase,
    setLastBeatPhase,
    baseFOV,
} from './game-loop-core.ts';
import { updateFoliagePhase } from './game-loop-foliage.ts';
