/**
 * Candy World always uses WebGPURenderer. WebGL2 fallback is the internal
 * GLSL node backend (`forceWebGL` / getFallback), not legacy THREE.WebGLRenderer.
 */
export type CandyRenderer = WebGPURenderer;

/**
 * Type guard to check if renderer is in WebGPU mode
 */
export const isWebGPUMode = (r: CandyRenderer): r is WebGPURenderer =>
    r instanceof WebGPURenderer;

/**
 * Configure sun shadow map, tight ortho frustum, and renderer shadow pass.
 * @returns true when shadows are active
 */
function configureSunShadows(
    sunLight: THREE.DirectionalLight,
    renderer: CandyRenderer,
    scene: THREE.Scene,
): boolean {
    const settings = resolveShadowSettings();

    if (!settings.enabled) {
        sunLight.castShadow = false;
        renderer.shadowMap.enabled = false;
        return false;
    }

    const cfg = CONFIG.lighting.shadows;
    const renderRadius = cfg.followRadius + cfg.snapHeadroom;

    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;

    sunLight.castShadow = true;
    sunLight.shadow.mapSize.set(settings.mapSize, settings.mapSize);
    sunLight.shadow.bias = cfg.bias;
    sunLight.shadow.normalBias = cfg.normalBias;
    sunLight.shadow.radius = cfg.pcfRadius;

    const cam = sunLight.shadow.camera as THREE.OrthographicCamera;
    cam.left = -renderRadius;
    cam.right = renderRadius;
    cam.top = renderRadius;
    cam.bottom = -renderRadius;
    cam.near = cfg.cameraNear;
    cam.far = cfg.cameraFar;
    cam.updateProjectionMatrix();

    // DirectionalLight aims position → target; target must be in the scene graph.
    scene.add(sunLight.target);
    return true;
}

/**
 * Return type for initScene function
 * Contains all created scene objects, lights, materials, and uniforms
 */
export interface SceneInitResult {
    scene: THREE.Scene;
    camera: THREE.PerspectiveCamera;
    renderer: CandyRenderer;
    mode: 'webgpu' | 'webgl';
    requested: RendererBackend;
    fallbackReason: string | null;
    ambientLight: THREE.HemisphereLight;
    sunLight: THREE.DirectionalLight;
    sunGlow: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
    sunCorona: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
    lightShaftGroup: THREE.Group;
    sunGlowMat: THREE.MeshBasicMaterial;
    coronaMat: THREE.MeshBasicMaterial;
    uShaftOpacity: ReturnType<typeof uniform<number>>;
}

/**
 * Window interface extension for global TSL uniforms
 * @internal
 */
declare global {
    interface Window {
        uShaftOpacity?: ReturnType<typeof uniform<number>>;
    }
}

/** True when the renderer is running Three's GLSL node backend (WebGL2). */
export function isWebGLNodeBackend(renderer: CandyRenderer): boolean {
    const backend = (renderer as WebGPURenderer & { backend?: { isWebGLBackend?: boolean } }).backend;
    return backend?.isWebGLBackend === true;
}

function createNodeRenderer(canvas: HTMLCanvasElement, forceWebGL = false): WebGPURenderer {
    if (!forceWebGL) {
        captureAdapterRequests();
    }
    return new WebGPURenderer({
        canvas,
        antialias: GPU_ANTIALIAS,
        alpha: GPU_ALPHA,
        powerPreference: GPU_POWER_PREFERENCE,
        requiredLimits: GPU_REQUIRED_LIMITS,
        forceWebGL,
    });
}

export interface CreateRendererResult {
    renderer: CandyRenderer;
    mode: 'webgpu' | 'webgl';
    requested: RendererBackend;
    fallbackReason: string | null;
}

/**
 * Create a renderer from an explicit preference.
 *
 * Priority:
 *   - `webgl`  → WebGPURenderer with `forceWebGL` (GLSL node backend)
 *   - `webgpu` → WebGPURenderer when available; falls back to GLSL backend on failure
 *
 * @param canvas The canvas element to render to
 * @param preference Resolved renderer preference from URL/localStorage
 */
export async function createRenderer(
    canvas: HTMLCanvasElement,
    preference: RendererBackend = resolveRendererBackend(),
): Promise<CreateRendererResult> {
    if (preference === 'webgl') {
        console.log('[Init] WebGL requested — creating WebGPURenderer (GLSL node backend)');
        return {
            renderer: createNodeRenderer(canvas, true),
            mode: 'webgl',
            requested: 'webgl',
            fallbackReason: 'explicit-webgl',
        };
    }

    if (WebGPU.isAvailable()) {
        try {
            console.log('[Init] WebGPU available, creating WebGPURenderer');
            const renderer = createNodeRenderer(canvas, false);
            return { renderer, mode: 'webgpu', requested: 'webgpu', fallbackReason: null };
        } catch (err) {
            // Issue #2: WebGPU may be declared available but fail at runtime
            // (e.g. requestAdapter returns null on Safari 17.4 / Chrome with
            // disabled GPU). Fall through to the GLSL node backend instead of crashing.
            console.warn('[Init] WebGPURenderer creation failed — falling back to GLSL node backend:', err);
        }
    }

    console.warn('[Init] WebGPU unavailable — falling back to WebGPURenderer (GLSL node backend)');
    const warning = WebGPU.getErrorMessage();
    if (warning && !document.getElementById('webgpu-warning')) {
        // Only append if not already present (avoid duplicates)
        warning.id = 'webgpu-warning';
        warning.style.zIndex = '1';  // Behind loading screen
        document.body.appendChild(warning);
    }

    return {
        renderer: createNodeRenderer(canvas, true),
        mode: 'webgl',
        requested: 'webgpu',
        fallbackReason: 'webgpu-unavailable',
    };
}

/**
 * Initialize the Three.js scene with renderer (WebGPU with WebGL fallback), lighting, fog, and visual effects.
 * 
 * Creates:
 * - WebGPU renderer with automatic WebGL fallback if unavailable
 * - Scene with TSL-driven fog node (WebGPU) and legacy fallback fog (all)
 * - Perspective camera positioned at (0, 5, 0)
 * - Hemisphere ambient light + directional sunlight with shadows
 * - Sun glow, corona, and volumetric light shafts
 * - Resize event handler
 * 
 * @returns Promise<SceneInitResult> containing all scene objects, lights, materials, uniforms, and mode
 */
export async function initScene(): Promise<SceneInitResult> {
    const canvas = document.querySelector('#glCanvas') as HTMLCanvasElement;
    const scene = new THREE.Scene();

    const requested = resolveRendererBackend();
    const { renderer, mode, fallbackReason } = await createRenderer(canvas, requested);

    if (mode === 'webgl') {
        (window as any).__computeDisabled = true;
    }

    // Adopt the renderer's device as the process-wide GPU context. Must complete
    // before setSize so MSAA colorBuffer / swapchain resolve match the canvas.
    await armGpuContext(renderer, mode, fallbackReason);

    const initialFog = getInitialFogDistances();

    // TSL-driven Crescendo Fog (WebGPURenderer — WGSL or GLSL node backend)
    if (isWebGPUMode(renderer)) {
        scene.fogNode = createCrescendoFogNode(color(PALETTE.day.fog));
    }
    // Standard fog kept for all renderers — distances derived from camera constants
    scene.fog = new THREE.Fog(PALETTE.day.fog, initialFog.near, initialFog.far);
    uFogNear.value = initialFog.near;
    uFogFar.value = initialFog.far;

    const camera = new THREE.PerspectiveCamera(
        60, 
        window.innerWidth / window.innerHeight, 
        0.1, 
        2000
    );
    camera.position.set(0, CONFIG.player.spawnEyeHeightY, 0);

    // WebGPURenderer configuration (WGSL or GLSL node backend)
    if (isWebGPUMode(renderer)) {
        // Fix: WebGPURenderer 0.171.0+ can crash in setupHardwareClipping if this is undefined
        const webgpuRenderer = renderer as WebGPURenderer;
        webgpuRenderer.clippingPlanes = [];
        webgpuRenderer.localClippingEnabled = false;
        console.log('[Init] WebGPURenderer clipping fix applied.');

        // Polyfill: attributeUtils.get is missing in three@0.171.0 but referenced by compute-particles.ts
        const backend = (webgpuRenderer as any).backend;
        if (backend && backend.attributeUtils && typeof backend.attributeUtils.get !== 'function') {
            backend.attributeUtils.get = () => null;
            console.log('[Init] WebGPU attributeUtils.get polyfill applied.');
        }

        // HDR Configuration (WebGPU backend only — Display P3 is not meaningful on GLSL fallback)
        const onWebGpuBackend = !isWebGLNodeBackend(renderer);
        const supportsHDR = onWebGpuBackend && window.matchMedia && window.matchMedia('(dynamic-range: high)').matches;
        if (supportsHDR) {
            console.log('[Init] HDR supported, configuring WebGPURenderer for extended dynamic range and Display P3.');
            try {
                webgpuRenderer.outputColorSpace = 'display-p3';
            } catch (e) {
                console.warn('[Init] Failed to set display-p3, falling back to srgb.');
                webgpuRenderer.outputColorSpace = 'srgb';
            }
            // Extended tone mapping for values > 1.0
            webgpuRenderer.toneMapping = THREE.LinearToneMapping;
        } else {
            if (!onWebGpuBackend) {
                console.log('[Init] GLSL node backend — using standard SDR configuration.');
            } else {
                console.log('[Init] HDR not supported, using standard SDR configuration.');
            }
            webgpuRenderer.outputColorSpace = 'srgb';
            webgpuRenderer.toneMapping = THREE.ACESFilmicToneMapping;
        }
    }

    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5)); // Cap pixel ratio for better performance
    renderer.toneMappingExposure = 1.0;

    // --- Lighting ---
    const ambientLight = new THREE.HemisphereLight(
        PALETTE.day.skyTop, 
        CONFIG.colors.ground, 
        1.1
    );
    scene.add(ambientLight);

    const sunLight = new THREE.DirectionalLight(PALETTE.day.sun, 0.9);
    sunLight.position.set(50, 80, 30);

    const shadowsActive = configureSunShadows(sunLight, renderer, scene);
    if (shadowsActive) {
        console.log(`[Init] Sun shadows enabled (map ${sunLight.shadow.mapSize.width}, ortho ±${CONFIG.lighting.shadows.followRadius}u)`);
    } else {
        console.log('[Init] Sun shadows disabled (quality tier / CONFIG)');
    }

    scene.add(sunLight);

    // Enhanced Sun Glow with dynamic corona effect
    const sunGlowMat = new THREE.MeshBasicMaterial({
        color: 0xFFE599,  // Warmer golden glow
        transparent: true,
        opacity: 0.25,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
        depthWrite: false
    });
    const sunGlow = new THREE.Mesh(new THREE.PlaneGeometry(80, 80), sunGlowMat);
    sunGlow.position.copy(sunLight.position.clone().normalize().multiplyScalar(400));
    sunGlow.lookAt(0, 0, 0);
    scene.add(sunGlow);

    // Add additional corona layer for more dramatic effect
    const coronaMat = new THREE.MeshBasicMaterial({
        color: 0xFFF4D6,  // Soft cream white
        transparent: true,
        opacity: 0.15,
        blending: THREE.AdditiveBlending,
        side: THREE.DoubleSide,
        depthWrite: false
    });
    const sunCorona = new THREE.Mesh(new THREE.PlaneGeometry(150, 150), coronaMat);
    sunCorona.position.copy(sunLight.position.clone().normalize().multiplyScalar(390));
    sunCorona.lookAt(0, 0, 0);
    scene.add(sunCorona);

    // Add light shafts/god rays for sunrise/sunset drama
    const lightShaftGroup = new THREE.Group();
    const shaftCount = 12;
    const shaftGeometry = new THREE.PlaneGeometry(8, 200);

    // Create light shaft material based on renderer mode
    const uShaftOpacity = window.uShaftOpacity || (window.uShaftOpacity = uniform(0.0));
    let shaftMaterial: THREE.MeshBasicMaterial | MeshBasicNodeMaterial;

    if (isWebGPUMode(renderer)) {
        // ⚡ OPTIMIZATION: Use a shared TSL material instead of looping over 12 clones in JS
        shaftMaterial = new MeshBasicNodeMaterial({
            color: 0xFFE5A0,
            transparent: true,
            blending: THREE.AdditiveBlending,
            side: THREE.DoubleSide,
            depthWrite: false
        });

        // TSL Volumetric God Rays:
        // Fade out horizontally at edges to prevent hard intersections
        const uvNode = uv();
        // Use proper boundaries: edge0 < edge1, then invert the result for the right side
        const leftFade = smoothstep(0.0, 0.4, uvNode.x);
        const rightFade = float(1.0).sub(smoothstep(0.6, 1.0, uvNode.x));
        const fadeX = leftFade.mul(rightFade);

        // Fade vertically to give a sense of scattering/dissipation (invert correctly)
        const fadeY = float(1.0).sub(smoothstep(0.0, 1.0, uvNode.y)).pow(float(1.5));

        // Link combined soft edges to global TSL uniform
        const softOpacity = fadeX.mul(fadeY).mul(uShaftOpacity);
        (shaftMaterial as MeshBasicNodeMaterial).opacityNode = softOpacity;
    } else {
        // WebGL fallback: use standard material with static opacity
        // Note: Opacity is updated dynamically in game-loop.ts based on sunrise/sunset.
        // Default starts at 0.0 (invisible) and matches uShaftOpacity uniform behavior.
        shaftMaterial = new THREE.MeshBasicMaterial({
            color: 0xFFE5A0,
            transparent: true,
            opacity: 0.0,  // See game-loop.ts for dynamic updates
            blending: THREE.AdditiveBlending,
            side: THREE.DoubleSide,
            depthWrite: false
        });
    }

    for (let i = 0; i < shaftCount; i++) {
        // Shared material instance, no .clone()
        const shaft = new THREE.Mesh(shaftGeometry, shaftMaterial);
        const angle = (i / shaftCount) * Math.PI * 2;
        shaft.rotation.z = angle;
        lightShaftGroup.add(shaft);
    }
    lightShaftGroup.position.copy(sunLight.position.clone().normalize().multiplyScalar(380));
    lightShaftGroup.userData.shaftMaterial = shaftMaterial;
    lightShaftGroup.visible = false; // Only visible during sunrise/sunset
    scene.add(lightShaftGroup);

    window.addEventListener('resize', () => {
        camera.aspect = window.innerWidth / window.innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
    });

    return {
        scene,
        camera,
        renderer,
        mode,
        requested,
        fallbackReason,
        ambientLight,
        sunLight,
        sunGlow,
        sunCorona,
        lightShaftGroup,
        sunGlowMat,
        coronaMat,
        uShaftOpacity
    };
}

/**
 * Force a full scene warmup render to prevent shader compilation stutter.
 * 
 * Only applies to WebGPU renderer. WebGL renderer returns immediately without
 * performing warmup, as WebGL is generally more stable during first render.
 * 
 * Temporarily disables frustum culling, moves camera to capture all objects,
 * renders a 1x1 pixel frame to trigger shader compilation, then restores
 * all original states.
 * 
 * @param renderer - The renderer instance (WebGPU or WebGL)
 * @param scene - The Three.js scene to warm up
 * @param camera - The camera to use for warmup rendering
 * @returns Promise that resolves when warmup is complete (immediate for WebGL)
 */
export async function forceFullSceneWarmup(
    renderer: CandyRenderer, 
    scene: THREE.Scene, 
    camera: THREE.PerspectiveCamera
): Promise<void> {
    // Only warmup WebGPU renderer; WebGL is more forgiving
    if (!isWebGPUMode(renderer)) {
        console.log('[Init] Skipping scene warmup for WebGL renderer');
        return;
    }
    // 1. Save state
    const originalMask = camera.layers.mask;
    const originalPos = camera.position.clone();
    const originalRot = camera.rotation.clone();
    const originalAutoClear = renderer.autoClear;

    // 2. Force visibility and hide sensitive meshes
    const restoreList: (THREE.Mesh | THREE.Points)[] = [];
    const visibleRestoreList: (THREE.Mesh | THREE.Points)[] = [];
    scene.traverse((obj: THREE.Object3D) => {
        const isRenderable = obj instanceof THREE.Mesh || obj instanceof THREE.Points;
        if (isRenderable && obj.frustumCulled) {
            obj.frustumCulled = false;
            restoreList.push(obj);
        }
        // Hide meshes/points with storage/compute attributes during warmup
        // Their TSL materials can crash the renderer if compiled in a generic context.
        if (isRenderable && obj.visible) {
            const geo = obj.geometry;
            const hasStorageAttr = geo && Object.values(geo.attributes).some((attr: any) =>
                attr instanceof StorageInstancedBufferAttribute ||
                attr instanceof StorageBufferAttribute
            );
            if (hasStorageAttr) {
                obj.visible = false;
                visibleRestoreList.push(obj);
            }
        }
    });

    // 3. Render 1x1 pixel frame
    const scissor = new THREE.Vector4();
    renderer.getViewport(scissor);
    renderer.setViewport(0, 0, 1, 1);

    camera.layers.enableAll();
    camera.position.set(0, 50, 0);
    camera.lookAt(0, 0, 0);

    try {
        renderer.render(scene, camera);
    } catch (e) { 
        console.warn("Warmup error", e); 
    }

    // 4. Restore
    renderer.setViewport(scissor.x, scissor.y, scissor.z, scissor.w);
    restoreList.forEach(o => o.frustumCulled = true);
    visibleRestoreList.forEach(o => {
        if (o && typeof o.visible !== 'undefined') {
            o.visible = true;
        }
    });
    visibleRestoreList.length = 0; // prevent stale references
    camera.layers.mask = originalMask;
    camera.position.copy(originalPos);
    camera.rotation.copy(originalRot);
    renderer.autoClear = originalAutoClear;
    renderer.clear();
}

/**
 * Re-sync the WebGPU drawing buffer and MSAA resolve target to the current window
 * size. Shader warmup renders into 1×1 offscreen targets; calling this after warmup
 * prevents CopyTextureToTexture validation errors when resolving to the canvas.
 */
export function syncDrawingBufferFromWindow(renderer: CandyRenderer): void {
    renderer.setSize(window.innerWidth, window.innerHeight);
}

/**
 * Audio Controls Module
 * Handles mute toggle, volume adjustment, and audio button UI state
 */

import { AudioSystem } from '../../audio/audio-system';
import { announce, announceValueChange, announcePolite } from '../../ui/announcer.ts';
import { showToast } from '../../utils/toast.ts';
import { keyStates } from './input-types.ts';

let audioSystemRef: AudioSystem | null = null;

// DOM Elements
let toggleMuteBtn: HTMLElement | null = null;
let volDownBtn: HTMLButtonElement | null = null;
let volUpBtn: HTMLButtonElement | null = null;

/**
 * Initialize audio controls with DOM references
 */
export function initAudioControls(audioSystem: AudioSystem): void {
    audioSystemRef = audioSystem;

    toggleMuteBtn = document.getElementById('toggleMuteBtn');
    volDownBtn = document.getElementById('volDownBtn') as HTMLButtonElement | null;
    volUpBtn = document.getElementById('volUpBtn') as HTMLButtonElement | null;

    // Initialize Volume Buttons State
    if (volDownBtn) volDownBtn.setAttribute('aria-disabled', String(audioSystem.volume <= 0.01));
    if (volUpBtn) volUpBtn.setAttribute('aria-disabled', String(audioSystem.volume >= 0.99));

    // NEW: Initialize Tooltips
    const initialVolPct = Math.round(audioSystem.volume * 100);
    if (volDownBtn) {
        const isMin = audioSystem.volume <= 0.01;
        volDownBtn.title = isMin ? "Minimum volume reached" : `Decrease Volume (-) • ${initialVolPct}%`;
        volDownBtn.setAttribute('aria-label', isMin ? "Decrease Volume (Disabled: Minimum reached)" : `Decrease Volume (Current: ${initialVolPct}%)`);
    }
    if (volUpBtn) {
        const isMax = audioSystem.volume >= 0.99;
        volUpBtn.title = isMax ? "Maximum volume reached" : `Increase Volume (+) • ${initialVolPct}%`;
        volUpBtn.setAttribute('aria-label', isMax ? "Increase Volume (Disabled: Maximum reached)" : `Increase Volume (Current: ${initialVolPct}%)`);
    }
    if (toggleMuteBtn) toggleMuteBtn.title = audioSystem.isMuted ? 'Unmute Audio (M)' : 'Mute Audio (M)';

    // Attach event listeners
    if (volDownBtn) {
        volDownBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            if (volDownBtn!.getAttribute('aria-disabled') === 'true') return;
            adjustVolume(-0.1);
        });
    }

    if (volUpBtn) {
        volUpBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            if (volUpBtn!.getAttribute('aria-disabled') === 'true') return;
            adjustVolume(0.1);
        });
    }

    if (toggleMuteBtn) {
        toggleMuteBtn.addEventListener('click', (e) => {
            e.stopPropagation(); // Prevent locking/unlocking if that's an issue
            toggleMute();
        });
    }
}

// Helper: Update Mute UI
export const updateMuteUI = (isMuted: boolean) => {
    if (toggleMuteBtn) {
        toggleMuteBtn.setAttribute('aria-checked', String(isMuted));
        toggleMuteBtn.innerHTML = isMuted ? '<span aria-hidden="true">🔇</span> Unmute <span class="key-badge" aria-hidden="true">M</span>' : '<span aria-hidden="true">🔊</span> Mute <span class="key-badge" aria-hidden="true">M</span>';
        toggleMuteBtn.setAttribute('aria-label', isMuted ? 'Unmute Audio' : 'Mute Audio');
        toggleMuteBtn.title = isMuted ? 'Unmute Audio (M)' : 'Mute Audio (M)';
    }
};

// Helper: Mute Toggle Logic
export const toggleMute = () => {
    if (!audioSystemRef) return false;

    const isMuted = audioSystemRef.toggleMute();
    updateMuteUI(isMuted);

    showToast(isMuted ? "Audio Muted 🔇" : "Audio Unmuted 🔊", isMuted ? '🔇' : '🔊');

    announce(isMuted ? "Audio Muted" : "Audio Unmuted", "polite");

    return isMuted;
};

// Helper: Adjust Volume
export const adjustVolume = (delta: number) => {
    if (!audioSystemRef) return;

    let newVol = audioSystemRef.volume + delta;
    newVol = Math.max(0, Math.min(1, newVol));
    audioSystemRef.setVolume(newVol);

    if (newVol > 0 && audioSystemRef.isMuted) {
        audioSystemRef.isMuted = false;
        updateMuteUI(false);
    }

    const percentage = Math.round(newVol * 100);

    // UX: Update Button States (Visual Polish)
    // Use epsilon for float comparison safety
    const isMin = newVol <= 0.01;
    const isMax = newVol >= 0.99;

    if (volDownBtn) {
        volDownBtn.setAttribute('aria-disabled', String(isMin));
        // 🎨 Palette: Explain why the button is disabled
        volDownBtn.title = isMin ? "Minimum volume reached" : `Decrease Volume (-) • ${percentage}%`;
        volDownBtn.setAttribute('aria-label', isMin ? "Decrease Volume (Disabled: Minimum reached)" : `Decrease Volume (Current: ${percentage}%)`);
    }
    if (volUpBtn) {
        volUpBtn.setAttribute('aria-disabled', String(isMax));
        // 🎨 Palette: Explain why the button is disabled
        volUpBtn.title = isMax ? "Maximum volume reached" : `Increase Volume (+) • ${percentage}%`;
        volUpBtn.setAttribute('aria-label', isMax ? "Increase Volume (Disabled: Maximum reached)" : `Increase Volume (Current: ${percentage}%)`);
    }

    const icon = newVol === 0 ? '🔇' : newVol < 0.5 ? '🔉' : '🔊';

    showToast(`Volume: ${percentage}% ${icon}`, icon);

    if (isMin) {
        announcePolite('Volume at minimum');
    } else if (isMax) {
        announcePolite('Volume at maximum');
    } else {
        announceValueChange('Volume', `${percentage}%`);
    }
};

/**
 * Handle KeyM for mute toggle from keyboard handler
 */
export function handleMuteKey(): void {
    toggleMute();
}

/**
 * Handle volume adjustment keys (+/-)
 */
export function handleVolumeKey(delta: number): void {
    adjustVolume(delta);
}

/**
 * Main Input Module (barrel)
 * Handles pointer lock controls, keyboard/mouse input, ability HUD, and drag & drop
 * Coordinates with playlist-manager and audio-controls modules
 */

import { keyStates } from './input-types.ts';
import type { KeyStates, InitInputResult } from './input-types.ts';

export function initInput(
    camera: THREE.Camera,
    audioSystem: AudioSystem,
    toggleDayNightCallback: (() => void) | null,
    shouldPreventMenuOnUnlock: (() => boolean) | null
): InitInputResult {
    const controls = new PointerLockControls(camera, document.body);
    const instructions = document.getElementById('instructions');
    const startButton = document.getElementById('startButton') as HTMLButtonElement | null;
    const canvas = document.getElementById('glCanvas') as HTMLCanvasElement | null;
    // @ts-expect-error - Vite handles import.meta.env, tsc doesn't know it
    const isDevBuild = import.meta.env?.DEV || false;

    // Ability HUD Elements
    const hudDash = document.getElementById('ability-dash');
    const hudMine = document.getElementById('ability-mine');
    const hudPhase = document.getElementById('ability-phase');

    // Modal Focus Trap Cleanups
    let releasePauseMenuFocus: (() => void) | null = null;
    let lastFocusedElement: HTMLElement | null = null;

    function resetMovementInput() {
        keyStates.forward = false;
        keyStates.backward = false;
        keyStates.left = false;
        keyStates.right = false;
        keyStates.jump = false;
        keyStates.sneak = false;
        keyStates.sprint = false;
        keyStates.dash = false;
        keyStates.action = false;
        keyStates.phase = false;
        keyStates.clap = false;
        keyStates.strike = false;
        keyStates.dance = false;
        keyStates.dodgeRoll = false;
    }

    const hideInstructionsImmediately = () => {
        if (!instructions) return;
        instructions.style.display = 'none';
        instructions.style.opacity = '0';
        instructions.style.backdropFilter = 'blur(0px)';
    };

    const exploreVariant: ExploreVariant = resolveExploreVariant();
    const exploreCamera = initExploreCamera({
        camera: camera as THREE.PerspectiveCamera,
        canvas: canvas ?? (document.body as unknown as HTMLCanvasElement),
        controls,
        variant: exploreVariant,
        onResetInput: resetMovementInput,
        onHidePauseMenu: hideInstructionsImmediately,
    });

    const isInteractiveTarget = (eventTarget: EventTarget | null) => {
        if (!(eventTarget instanceof HTMLElement)) return false;
        return !!eventTarget.closest(
            'button, input, select, textarea, a, label, [role="button"], [role="dialog"], #ability-hud, #playlist-overlay, #playlist-backdrop, #dpad-controls, #instructions, #mode-select'
        );
    };

    const stopDevOrbitLoop = () => {
        /* orbit updates run in game-loop via updateExploreCamera */
    };

    const setPausedTitle = (paused: boolean) => {
        const title = instructions ? instructions.querySelector('h1') : null;
        if (title) {
            title.innerHTML = paused
                ? 'Dream Paused <span aria-hidden="true">⏸️</span>'
                : '<span aria-hidden="true">🍭</span> Candy World';
        }
    };

    const setStartButtonResumeLabel = () => {
        if (startButton) {
            startButton.innerHTML =
                'Resume the Dream <span aria-hidden="true">✨</span> <span class="key-badge" aria-hidden="true">Enter</span>';
        }
    };

    const setStartButtonEnterLabel = () => {
        if (startButton) {
            startButton.innerHTML =
                'Enter the Dream <span aria-hidden="true">🍭</span> <span class="key-badge" aria-hidden="true">Enter</span>';
        }
    };

    const disableExploreMode = (relock = true) => {
        exploreCamera.exitToFirstPerson(relock);
    };

    const enableExploreMode = async (options?: { temporary?: boolean; fromToggle?: boolean }) => {
        await exploreCamera.enter(options);
    };

    // --- NEW: Visual Reticle (Crosshair) ---
    // Check if it exists; if not, create it
    if (!document.getElementById('game-reticle')) {
        const reticle = document.createElement('div');
        reticle.id = 'game-reticle';
        document.body.appendChild(reticle);
    }

    // Function to animate reticle based on state using CSS classes
    function updateReticleState(state: 'idle' | 'hover' | 'interact', label?: string): void {
        const reticle = document.getElementById('game-reticle');
        if (!reticle) return;
        const reticleLabel = document.getElementById('reticle-label');

        // Reset classes
        reticle.classList.remove('hover', 'interact');

        // Apply new state
        if (state === 'hover') {
            reticle.classList.add('hover');
        } else if (state === 'interact') {
            reticle.classList.add('interact');
        }

        // Handle Label
        if (reticleLabel) {
            if (state === 'hover' && label) {
                reticleLabel.innerText = label;
                reticleLabel.classList.add('visible');
            } else if (state === 'idle') {
                reticleLabel.classList.remove('visible');
            }
            // Note: On 'interact', we keep the label visible if it was already there
        }
    }

    // ♿ Aria: Map HUD Ability Slots to game inputs
    const abilitySlots = document.querySelectorAll('.ability-slot[role="button"]');
    abilitySlots.forEach((slot) => {
        const actionKey = slot.getAttribute('aria-keyshortcuts');
        if (!actionKey) return;

        // Pointer / touch support (hold)
        slot.addEventListener('pointerdown', (e) => {
            const ev = e as PointerEvent;
            if (ev.button !== 0) return; // Only left click / primary touch
            const keyEvent = new KeyboardEvent('keydown', {
                key: actionKey,
                code: `Key${actionKey.toUpperCase()}`,
                bubbles: true,
            });
            document.dispatchEvent(keyEvent);
            slot.classList.add('keyboard-active');
        });

        slot.addEventListener('pointerup', () => {
            const keyEvent = new KeyboardEvent('keyup', {
                key: actionKey,
                code: `Key${actionKey.toUpperCase()}`,
                bubbles: true,
            });
            document.dispatchEvent(keyEvent);
            slot.classList.remove('keyboard-active');
        });

        slot.addEventListener('pointercancel', () => {
            const keyEvent = new KeyboardEvent('keyup', {
                key: actionKey,
                code: `Key${actionKey.toUpperCase()}`,
                bubbles: true,
            });
            document.dispatchEvent(keyEvent);
            slot.classList.remove('keyboard-active');
        });

        slot.addEventListener('pointerout', () => {
            // In case pointer leaves element while held
            if (slot.classList.contains('keyboard-active')) {
                const keyEvent = new KeyboardEvent('keyup', {
                    key: actionKey,
                    code: `Key${actionKey.toUpperCase()}`,
                    bubbles: true,
                });
                document.dispatchEvent(keyEvent);
                slot.classList.remove('keyboard-active');
            }
        });

        // Keyboard (Enter/Space)
        slot.addEventListener('keydown', (e) => {
            const ev = e as KeyboardEvent;
            if (ev.key === 'Enter' || ev.key === ' ') {
                if (ev.repeat) return;
                ev.preventDefault();
                const keyEvent = new KeyboardEvent('keydown', {
                    key: actionKey,
                    code: `Key${actionKey.toUpperCase()}`,
                    bubbles: true,
                });
                document.dispatchEvent(keyEvent);
                slot.classList.add('keyboard-active');
            }
        });

        slot.addEventListener('keyup', (e) => {
            const ev = e as KeyboardEvent;
            if (ev.key === 'Enter' || ev.key === ' ') {
                const keyEvent = new KeyboardEvent('keyup', {
                    key: actionKey,
                    code: `Key${actionKey.toUpperCase()}`,
                    bubbles: true,
                });
                document.dispatchEvent(keyEvent);
                slot.classList.remove('keyboard-active');
            }
        });

        slot.addEventListener('blur', () => slot.classList.remove('keyboard-active'));

        // Prevent context menu on long-press/touch
        slot.addEventListener('contextmenu', (e) => e.preventDefault());
    });

    // Initialize sub-modules
    initPlaylistManager(audioSystem, controls, instructions);
    initAudioControls(audioSystem);
    initLegacyMusicUpload(audioSystem);

    // --- Pointer Lock & Menu Logic ---

    if (startButton) {
        startButton.addEventListener('click', () => {
            controls.lock();
        });
    }

    if (instructions) {
        instructions.addEventListener('click', (event: MouseEvent) => {
            if (event.target === instructions) {
                controls.lock();
            }
        });

        if (startButton) {
            // ♿ Aria: Keyboard tactile feedback for start button
            startButton.addEventListener('keydown', (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    if (e.repeat) return;
                    startButton.classList.add('keyboard-active');
                }
            });

            const cleanupStartBtn = () => startButton.classList.remove('keyboard-active');

            startButton.addEventListener('keyup', (e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                    cleanupStartBtn();
                }
            });
            startButton.addEventListener('blur', cleanupStartBtn);
        }
    }

    controls.addEventListener('lock', () => {
        if (isExploreActive()) {
            disableExploreMode(false);
        }
        // UX: If generating the world, keep the "Generating..." message visible
        // The main.js logic will hide it when done.
        const currentStartButton = document.getElementById(
            'startButton'
        ) as HTMLButtonElement | null;
        if (currentStartButton && currentStartButton.disabled) {
            return;
        }

        if (releasePauseMenuFocus) {
            releasePauseMenuFocus();
            releasePauseMenuFocus = null;
        }

        if (instructions) {
            instructions.style.opacity = '0';
            instructions.style.backdropFilter = 'blur(0px)';
            const content = instructions.querySelector('.instructions-content') as HTMLElement;
            if (content) {
                content.style.transform = 'scale(0.95)';
            }
            setTimeout(() => {
                if (instructions) instructions.style.display = 'none';
                if (lastFocusedElement && typeof lastFocusedElement.focus === 'function') {
                    lastFocusedElement.focus({ preventScroll: true });
                    lastFocusedElement = null;
                }
                setPausedTitle(false);
                setStartButtonEnterLabel();
            }, 200);
        } else {
            if (lastFocusedElement && typeof lastFocusedElement.focus === 'function') {
                lastFocusedElement.focus({ preventScroll: true });
                lastFocusedElement = null;
            }
        }

        // If we locked, force playlist closed just in case
        setIsPlaylistOpen(false);
        const playlistOverlay = document.getElementById('playlist-overlay');
        const playlistBackdrop = document.getElementById('playlist-backdrop');
        const openJukeboxBtn = document.getElementById('openJukeboxBtn');
        if (playlistOverlay) playlistOverlay.style.display = 'none';
        if (playlistBackdrop) playlistBackdrop.style.display = 'none';
        if (openJukeboxBtn) openJukeboxBtn.setAttribute('aria-expanded', 'false');

        const releaseJukebox = getReleaseJukeboxFocus();
        if (releaseJukebox) {
            releaseJukebox();
            setReleaseJukeboxFocus(null);
        }

        closeAccessibilityMenu();
    });

    controls.addEventListener('unlock', () => {
        if (isExploreActive()) return;
        // CRITICAL: Only show Main Menu if Playlist ISN'T open.
        // If Playlist is open, we *want* to be unlocked, but seeing the Playlist, not the start screen.
        if (!getIsPlaylistOpen()) {
            // Check if external condition (like dancing) prevents showing the menu
            if (shouldPreventMenuOnUnlock && shouldPreventMenuOnUnlock()) {
                return;
            }

            if (instructions) {
                lastFocusedElement = document.activeElement as HTMLElement;
                instructions.style.display = 'flex';
                instructions.style.opacity = '0';
                instructions.style.backdropFilter = 'blur(0px)';
                instructions.style.transition = 'opacity 0.2s ease, backdrop-filter 0.2s ease';

                const content = instructions.querySelector('.instructions-content') as HTMLElement;
                if (content) {
                    content.style.transform = 'scale(0.95)';
                    content.style.transition =
                        'transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
                }

                requestAnimationFrame(() => {
                    if (instructions) {
                        instructions.style.opacity = '1';
                        instructions.style.backdropFilter = 'blur(10px)';
                    }
                    if (content) {
                        content.style.transform = 'scale(1)';
                    }
                });

                yieldToPaint(50).then(() => {
                    if (instructions && instructions.style.display !== 'none') {
                        releasePauseMenuFocus = trapFocusInside(instructions, { skipAutoFocus: true });
                        if (startButton) {
                            startButton.focus({ preventScroll: true });
                        }
                    }
                });
            }

            // UX: Update Title to "Paused" to give context
            setPausedTitle(true);
            setStartButtonResumeLabel();
        }
    });

    // Click to Resume behavior when menu is hidden but controls are unlocked (e.g. after dancing)
    const onBodyClick = (event: MouseEvent) => {
        // Only trigger if:
        // 1. Controls are unlocked
        // 2. Playlist is closed
        // 3. Instructions (Pause Menu) are hidden
        // 4. We are NOT currently prevented from locking (i.e. not dancing)
        const target = event.target;
        if (
            !controls.isLocked &&
            !isExploreActive() &&
            !getIsPlaylistOpen() &&
            instructions &&
            instructions.style.display === 'none' &&
            !isInteractiveTarget(target) &&
            (target === canvas || target === document.body)
        ) {
            if (shouldPreventMenuOnUnlock && shouldPreventMenuOnUnlock()) {
                // Still dancing/prevented? Do nothing, keep cursor free.
                return;
            }

            controls.lock();
        }
    };
    document.body.addEventListener('click', onBodyClick);

    function isGameFocused(): boolean {
        const activeEl = document.activeElement;
        const currentCanvas = canvas ?? document.getElementById('glCanvas');
        return activeEl === document.body || activeEl === currentCanvas;
    }

    // Key Handlers
    const onKeyDown = function (event: KeyboardEvent) {
        if (getPhotoMode()?.handleKeyDown(event)) {
            return;
        }

        if (isPhotoModeActive()) {
            if (event.code === 'Escape' || event.code === 'Enter') {
                return;
            }
            // Block gameplay keys while composing a shot
            if (!event.altKey && event.code !== 'Tab') {
                return;
            }
        }

        if (
            event.code === 'KeyP' &&
            !event.ctrlKey &&
            !event.shiftKey &&
            !event.metaKey &&
            !getIsPlaylistOpen() &&
            instructions &&
            instructions.style.display === 'none'
        ) {
            event.preventDefault();
            getPhotoMode()?.toggle();
            return;
        }

        if (isDevBuild && event.ctrlKey && event.shiftKey && event.code === 'KeyO') {
            event.preventDefault();
            if (isExploreActive()) {
                disableExploreMode(true);
            } else {
                void enableExploreMode({ fromToggle: true });
            }
            return;
        }

        if (event.code === 'Tab') {
            if (isGameFocused()) {
                event.preventDefault();
                exploreCamera.onTabDown();
            }
            return; // inside modals: don't preventDefault — trapFocusInside handles Tab
        }

        if (isExploreActive()) {
            if (event.code === 'Escape') {
                event.preventDefault();
                disableExploreMode(true);
                return;
            }
            if (event.code === 'Enter') {
                event.preventDefault();
                disableExploreMode(true);
                return;
            }
            if (exploreCamera.isHybrid()) {
                // Hybrid pan handled via movement keys below when explore active
            } else {
                return;
            }
        }

        // Prevent default browser actions (like Ctrl+S)
        if (event.ctrlKey && event.code !== 'ControlLeft' && event.code !== 'ControlRight') {
            event.preventDefault();
        }

        const isPlaylistOpen = getIsPlaylistOpen();

        // Escape: Special Handling to FORCE menu open if it was suppressed (e.g. by dancing)
        if (event.code === 'Escape') {
            if (isPlaylistOpen) {
                event.preventDefault();
                const closePlaylistBtn = document.getElementById('closePlaylistBtn');
                if (closePlaylistBtn) {
                    closePlaylistBtn.classList.add('keyboard-active');
                    setTimeout(() => closePlaylistBtn.classList.remove('keyboard-active'), 150);
                }
                togglePlaylist();
                return;
            } else if (shouldPreventMenuOnUnlock && shouldPreventMenuOnUnlock()) {
                // If we are dancing, the unlock event fired but menu was suppressed.
                // Pressing Escape again should manually bring up the menu.
                if (instructions) {
                    lastFocusedElement = document.activeElement as HTMLElement;
                    instructions.style.display = 'flex';
                    instructions.style.opacity = '0';
                    instructions.style.backdropFilter = 'blur(0px)';
                    instructions.style.transition = 'opacity 0.2s ease, backdrop-filter 0.2s ease';

                    const content = instructions.querySelector(
                        '.instructions-content'
                    ) as HTMLElement;
                    if (content) {
                        content.style.transform = 'scale(0.95)';
                        content.style.transition =
                            'transform 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
                    }

                    // Force a layout calculation so transitions work correctly
                    void instructions.offsetWidth;

                    requestAnimationFrame(() => {
                        if (instructions) {
                            instructions.style.opacity = '1';
                            instructions.style.backdropFilter = 'blur(10px)';
                        }
                        if (content) {
                            content.style.transform = 'scale(1)';
                        }
                    });

                    yieldToPaint(50).then(() => {
                        if (instructions && instructions.style.display !== 'none') {
                            releasePauseMenuFocus = trapFocusInside(instructions, { skipAutoFocus: true });
                            if (startButton) {
                                startButton.focus({ preventScroll: true });
                            }
                        }
                    });
                }
                if (startButton) {
                    setStartButtonResumeLabel();
                }
                return;
            }

            // Resume if in pause menu
            if (instructions && instructions.style.display !== 'none') {
                controls.lock();
                return;
            }
        }

        // Enter: Resume/Start if menu is visible and button is active
        if (event.code === 'Enter') {
            if (!isPlaylistOpen && instructions && instructions.style.display !== 'none') {
                if (
                    startButton &&
                    !startButton.disabled &&
                    document.activeElement !== startButton
                ) {
                    startButton.click();
                    event.preventDefault();
                }
            }
        }

        // --- UX: Focus Trap for Main Menu (Pause Screen) ---
        if (!isPlaylistOpen && instructions && instructions.style.display !== 'none') {
            // 🎨 Palette: Interactive Key Hints
            // Highlight the visual key in the help menu when pressed
            const keyChar = event.key.toUpperCase();
            const code = event.code;
            const keys = instructions.querySelectorAll('kbd.key');

            keys.forEach((k) => {
                const text = (k as HTMLElement).innerText.toUpperCase();
                // Match by text content or specific codes
                let match = false;
                if (text === keyChar) match = true;
                if (text === 'SPACE' && code === 'Space') match = true;
                if (text === 'SHIFT' && (code === 'ShiftLeft' || code === 'ShiftRight'))
                    match = true;
                if (text === 'CTRL' && (code === 'ControlLeft' || code === 'ControlRight'))
                    match = true;
                if (text === '+' && (code === 'Equal' || code === 'NumpadAdd')) match = true;
                if (text === '-' && (code === 'Minus' || code === 'NumpadSubtract')) match = true;

                if (match) {
                    k.classList.add('key-highlight');
                }
            });
        }

        // --- UX: Focus Trap & Control Lock when Playlist is open ---
        if (handlePlaylistKeyDown(event)) {
            return;
        }
        // --------------------------------------------------------

        switch (event.code) {
            case 'KeyL':
                if (document.pointerLockElement) {
                    controls.unlock();
                }
                discoverySystem.showLog();
                break;
            case 'KeyQ':
                if (getIsPlaylistOpen()) return; // Handled by playlist manager
                if (event.repeat) return;
                triggerButtonPressDown('openJukeboxBtn');
                togglePlaylist();
                break;
            case 'KeyW':
                if (isExploreActive() && !exploreCamera.isHybrid()) break;
                keyStates.forward = true;
                break;
            case 'KeyA':
                if (isExploreActive() && !exploreCamera.isHybrid()) break;
                keyStates.left = true;
                break;
            case 'KeyS':
                if (isExploreActive() && !exploreCamera.isHybrid()) break;
                keyStates.backward = true;
                break;
            case 'KeyD':
                if (isExploreActive() && !exploreCamera.isHybrid()) break;
                keyStates.right = true;
                break;
            case 'KeyF':
                if (isExploreActive()) break;
                keyStates.action = true;
                if (hudMine) hudMine.classList.add('keyboard-active');
                break; // Jitter Mine Ability
            case 'KeyE':
            case 'e':
                if (isExploreActive()) break;
                keyStates.dash = true;
                if (hudDash) hudDash.classList.add('keyboard-active');
                break; // Dash Ability
            case 'KeyX':
            case 'x':
                if (isExploreActive()) break;
                keyStates.dodgeRoll = true;
                break; // Dodge Roll Ability
            case 'KeyZ':
            case 'z':
                if (isExploreActive()) break;
                keyStates.phase = true;
                if (hudPhase) hudPhase.classList.add('keyboard-active');
                break; // Phase Shift Ability
            case 'KeyC':
            case 'c':
                if (isExploreActive()) break;
                keyStates.clap = true;
                break; // Sonic Clap Ability
            case 'KeyV':
            case 'v':
                if (isExploreActive()) break;
                keyStates.strike = true;
                break; // Chord Strike Ability
            case 'KeyR':
            case 'r':
                if (isExploreActive()) break;
                keyStates.dance = true;
                break; // Dance Ability
            case 'Space':
                if (isExploreActive()) break;
                keyStates.jump = true;
                break;
            case 'KeyN':
                if (event.repeat) return;
                triggerButtonPressDown('toggleDayNight');
                if (toggleDayNightCallback) toggleDayNightCallback();
                break;
            case 'KeyM':
                if (event.repeat) return;
                triggerButtonPressDown('toggleMuteBtn');
                handleMuteKey();
                break;
            case 'KeyU': {
                if (event.repeat) return;
                triggerButtonPressDown('musicUploadBtn');
                const uploadInput = document.getElementById('musicUpload') as HTMLInputElement;
                if (uploadInput) uploadInput.click();
                break;
            }
            case 'Equal':
            case 'NumpadAdd':
                if (event.repeat) return;
                // ♿ Aria: Added tactile keyboard feedback for volume hotkeys
                triggerButtonPressDown('volUpBtn');
                handleVolumeKey(0.1);
                break;
            case 'Minus':
            case 'NumpadSubtract':
                if (event.repeat) return;
                // ♿ Aria: Added tactile keyboard feedback for volume hotkeys
                triggerButtonPressDown('volDownBtn');
                handleVolumeKey(-0.1);
                break;
            case 'ControlLeft':
            case 'ControlRight':
                if (isExploreActive()) break;
                keyStates.sneak = true;
                event.preventDefault();
                break;
            case 'ShiftLeft':
            case 'ShiftRight':
                if (isExploreActive()) break;
                keyStates.sprint = true;
                break;
        }
    };

    const onKeyUp = function (event: KeyboardEvent) {
        if (event.code === 'Tab' && isGameFocused()) {
            exploreCamera.onTabUp();
            return;
        }

        // --- UX: Tactile Feedback Cleanup when Playlist is open ---
        handlePlaylistKeyUp(event);

        if (isExploreActive()) return;
        if (instructions && instructions.style.display !== 'none') {
            const keyChar = event.key.toUpperCase();
            const code = event.code;
            const keys = instructions.querySelectorAll('kbd.key');

            keys.forEach((k) => {
                const text = (k as HTMLElement).innerText.toUpperCase();
                let match = false;
                if (text === keyChar) match = true;
                if (text === 'SPACE' && code === 'Space') match = true;
                if (text === 'SHIFT' && (code === 'ShiftLeft' || code === 'ShiftRight'))
                    match = true;
                if (text === 'CTRL' && (code === 'ControlLeft' || code === 'ControlRight'))
                    match = true;
                if (text === '+' && (code === 'Equal' || code === 'NumpadAdd')) match = true;
                if (text === '-' && (code === 'Minus' || code === 'NumpadSubtract')) match = true;

                if (match) {
                    k.classList.remove('key-highlight');
                }
            });
        }

        switch (event.code) {
            case 'KeyW':
                keyStates.forward = false;
                break;
            case 'KeyA':
                keyStates.left = false;
                break;
            case 'KeyS':
                keyStates.backward = false;
                break;
            case 'KeyD':
                keyStates.right = false;
                break;
            case 'KeyF':
                keyStates.action = false;
                if (hudMine) hudMine.classList.remove('keyboard-active');
                break;
            case 'KeyE':
            case 'e':
                keyStates.dash = false;
                if (hudDash) hudDash.classList.remove('keyboard-active');
                break;
            case 'KeyX':
            case 'x':
                keyStates.dodgeRoll = false;
                break;
            case 'KeyZ':
            case 'z':
                keyStates.phase = false;
                if (hudPhase) hudPhase.classList.remove('keyboard-active');
                break;
            case 'KeyR':
            case 'r':
                keyStates.dance = false;
                break;
            case 'Space':
                keyStates.jump = false;
                break;
            case 'KeyC':
            case 'c':
                keyStates.clap = false;
                break;
            case 'KeyV':
            case 'v':
                keyStates.strike = false;
                break;
            case 'ControlLeft':
            case 'ControlRight':
                keyStates.sneak = false;
                break;
            case 'ShiftLeft':
            case 'ShiftRight':
                keyStates.sprint = false;
                break;

            // ♿ Aria: Tactile feedback cleanup
            case 'KeyQ':
                triggerButtonPressUp('openJukeboxBtn');
                break;
            case 'KeyN':
                triggerButtonPressUp('toggleDayNight');
                break;
            case 'KeyM':
                triggerButtonPressUp('toggleMuteBtn');
                break;
            case 'KeyU':
                triggerButtonPressUp('musicUploadBtn');
                break;
            case 'Equal':
            case 'NumpadAdd':
                // ♿ Aria: Added tactile keyboard feedback for volume hotkeys
                triggerButtonPressUp('volUpBtn');
                break;
            case 'Minus':
            case 'NumpadSubtract':
                // ♿ Aria: Added tactile keyboard feedback for volume hotkeys
                triggerButtonPressUp('volDownBtn');
                break;
        }
    };

    // Standard Mouse State (Right click to move)
    const onMouseDown = function (event: MouseEvent) {
        if (getIsPlaylistOpen()) return;
        exploreCamera.onHybridMouseDown(event.button);
        if (isExploreActive() && event.button === 0 && !isInteractiveTarget(event.target)) {
            disableExploreMode(true);
            return;
        }
        if (event.button === 2) keyStates.forward = true;
    };

    const onMouseUp = function (event: MouseEvent) {
        if (getIsPlaylistOpen()) return;
        exploreCamera.onHybridMouseUp(event.button);
        if (event.button === 2) keyStates.forward = false;
    };

    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('keyup', onKeyUp);
    document.addEventListener('mousedown', onMouseDown);
    document.addEventListener('mouseup', onMouseUp);

    // --- UX: Keyboard Interactions for HUD Abilities ---
    // ♿ Aria: Support pointer hold for ability buttons
    function setupAbilityKeyboardInteractions(element: HTMLElement | null, keyCode: string) {
        if (!element) return;

        element.addEventListener('keydown', (e: KeyboardEvent) => {
            if (e.key === 'Enter' || e.code === 'Space') {
                e.preventDefault(); // Prevent scrolling for space
                onKeyDown(new KeyboardEvent('keydown', { code: keyCode }));
            }
        });

        element.addEventListener('keyup', (e: KeyboardEvent) => {
            if (e.key === 'Enter' || e.code === 'Space') {
                e.preventDefault();
                onKeyUp(new KeyboardEvent('keyup', { code: keyCode }));
            }
        });

        element.addEventListener('pointerdown', (e: PointerEvent) => {
            e.preventDefault();
            e.stopPropagation();
            element.setPointerCapture(e.pointerId);
            onKeyDown(new KeyboardEvent('keydown', { code: keyCode }));
        });

        element.addEventListener('pointerup', (e: PointerEvent) => {
            e.preventDefault();
            e.stopPropagation();
            onKeyUp(new KeyboardEvent('keyup', { code: keyCode }));
        });

        element.addEventListener('pointercancel', (e: PointerEvent) => {
            e.preventDefault();
            e.stopPropagation();
            onKeyUp(new KeyboardEvent('keyup', { code: keyCode }));
        });

        element.addEventListener('contextmenu', (e: MouseEvent) => {
            e.preventDefault();
        });

        element.addEventListener('blur', () => {
            // Ensure ability isn't stuck on if focus is lost while pressing
            onKeyUp(new KeyboardEvent('keyup', { code: keyCode }));
        });
    }
    // ---------------------------------------------------

    // ♿ Aria: Tactile feedback mapping keyboard interactions to standard :active behavior
    const activeKeyboardButtons = new Set<string>();

    function triggerButtonPressDown(buttonId: string): void {
        const btn = document.getElementById(buttonId);
        if (btn && btn.getAttribute('aria-disabled') !== 'true') {
            btn.classList.add('keyboard-active');
            activeKeyboardButtons.add(buttonId);
        }
    }

    function triggerButtonPressUp(buttonId: string): void {
        const btn = document.getElementById(buttonId);
        if (btn) {
            btn.classList.remove('keyboard-active');
        }
        activeKeyboardButtons.delete(buttonId);
    }

    // Safety: release all stuck button states if window loses focus
    window.addEventListener('blur', () => {
        for (const buttonId of activeKeyboardButtons) {
            triggerButtonPressUp(buttonId);
        }
    });

    const toggleDayNightBtn = document.getElementById('toggleDayNight');
    if (toggleDayNightBtn && toggleDayNightCallback) {
        toggleDayNightBtn.addEventListener('click', toggleDayNightCallback);
    }

    // --- D-Pad Direction Controls ---
    type DpadDirection = 'forward' | 'backward' | 'left' | 'right';

    const dpadMap: Record<string, DpadDirection> = {
        'dpad-forward': 'forward',
        'dpad-backward': 'backward',
        'dpad-left': 'left',
        'dpad-right': 'right',
    };

    // Track which D-pad directions are currently held via pointer
    const dpadHeld = new Set<DpadDirection>();

    const dpadPress = (dir: DpadDirection, btn: HTMLElement) => {
        dpadHeld.add(dir);
        keyStates[dir] = true;
        btn.setAttribute('aria-pressed', 'true');
    };

    const dpadRelease = (dir: DpadDirection, btn: HTMLElement) => {
        dpadHeld.delete(dir);
        keyStates[dir] = false;
        btn.setAttribute('aria-pressed', 'false');
    };

    for (const [id, dir] of Object.entries(dpadMap)) {
        const btn = document.getElementById(id) as HTMLElement | null;
        if (!btn) continue;

        btn.addEventListener('pointerdown', (e: PointerEvent) => {
            e.preventDefault();
            e.stopPropagation();
            btn.setPointerCapture(e.pointerId);
            dpadPress(dir, btn);
        });

        btn.addEventListener('pointerup', (e: PointerEvent) => {
            e.preventDefault();
            e.stopPropagation();
            dpadRelease(dir, btn);
        });

        btn.addEventListener('pointercancel', (e: PointerEvent) => {
            e.preventDefault();
            e.stopPropagation();
            dpadRelease(dir, btn);
        });

        // Prevent context menu on long-press (mobile)
        btn.addEventListener('contextmenu', (e) => e.preventDefault());
    }

    // Safety: release all D-pad directions if window loses focus
    const releaseDpadAll = () => {
        for (const [id, dir] of Object.entries(dpadMap)) {
            const btn = document.getElementById(id) as HTMLElement | null;
            if (btn) dpadRelease(dir, btn);
        }
    };
    window.addEventListener('blur', releaseDpadAll);

    // --- UX: Interactive Ability HUD ---
    // (Variables moved to top of initInput)
    // Wire up the unified keyboard + click handling for ability buttons
    setupAbilityKeyboardInteractions(hudDash, 'KeyE');
    setupAbilityKeyboardInteractions(hudMine, 'KeyF');
    setupAbilityKeyboardInteractions(hudPhase, 'KeyZ');

    const openA11yBtn = document.getElementById('openA11yBtn');
    if (openA11yBtn) {
        openA11yBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            openAccessibilityMenu();
        });
    }

    // --- UX: Drag & Drop Support ---
    const dragOverlay = document.getElementById('drag-overlay');
    let dragCounter = 0;

    const onDragEnter = (e: DragEvent) => {
        e.preventDefault();
        dragCounter++;
        if (dragOverlay) {
            dragOverlay.classList.add('active');
            dragOverlay.setAttribute('aria-hidden', 'false');
        }
    };

    const onDragLeave = (e: DragEvent) => {
        e.preventDefault();
        dragCounter--;
        if (dragCounter <= 0) {
            dragCounter = 0;
            if (dragOverlay) {
                dragOverlay.classList.remove('active');
                dragOverlay.setAttribute('aria-hidden', 'true');
            }
        }
    };

    const onDragOver = (e: DragEvent) => {
        e.preventDefault(); // Necessary to allow dropping
    };

    const onDrop = (e: DragEvent) => {
        e.preventDefault();
        dragCounter = 0;
        if (dragOverlay) {
            dragOverlay.classList.remove('active');
            dragOverlay.setAttribute('aria-hidden', 'true');
        }

        const files = e.dataTransfer?.files;
        if (files && files.length > 0) {
            // Use the filter function from input-types
            const { validFiles, invalidFiles } = filterValidMusicFiles(files);

            if (validFiles.length > 0) {
                audioSystem.addToQueue(validFiles);

                // Show feedback via Toast
                import('../../utils/toast.ts').then(({ showToast }) => {
                    if (invalidFiles.length > 0) {
                        showToast(
                            `Added ${validFiles.length} song${validFiles.length > 1 ? 's' : ''}. (${invalidFiles.length} ignored)`,
                            '⚠️'
                        );
                    } else {
                        showToast(
                            `Added ${validFiles.length} Song${validFiles.length > 1 ? 's' : ''}! 🎶`,
                            '📂'
                        );
                    }
                });
            } else {
                // All files were invalid
                import('../../utils/toast.ts').then(({ showToast }) => {
                    showToast('❌ Only .mod, .xm, .it, .s3m allowed!', '🚫');
                });
            }
            // End filter
        }
    };

    if (dragOverlay) {
        window.addEventListener('dragenter', onDragEnter);
        window.addEventListener('dragleave', onDragLeave);
        window.addEventListener('dragover', onDragOver);
        window.addEventListener('drop', onDrop);
    }

    const toggleExploreBtn = document.getElementById('toggleExploreBtn');
    if (toggleExploreBtn) {
        toggleExploreBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            exploreCamera.togglePersistent();
            const active = isExploreActive();
            toggleExploreBtn.setAttribute('aria-checked', String(active));
            toggleExploreBtn.innerHTML = active
                ? '<span aria-hidden="true">🚶</span> First-Person <span class="key-badge" aria-hidden="true">Tab</span>'
                : '<span aria-hidden="true">🎥</span> Explore Mode <span class="key-badge" aria-hidden="true">Tab</span>';
            toggleExploreBtn.setAttribute(
                'aria-label',
                active ? 'Toggle First-person camera mode' : 'Toggle Explore camera mode'
            );
            toggleExploreBtn.title = active
                ? 'Return to first-person view (Tab)'
                : 'Cinematic orbit camera (hold Tab)';
            announcePolite(active ? 'Explore mode enabled' : 'First-person mode');
        });
    }

    void bootstrapExploreFromPreference();

    return {
        controls,
        updateReticleState,
        cleanup: () => {
            exploreCamera.dispose();
            document.body.removeEventListener('click', onBodyClick);
            document.removeEventListener('keydown', onKeyDown);
            document.removeEventListener('keyup', onKeyUp);
            document.removeEventListener('mousedown', onMouseDown);
            document.removeEventListener('mouseup', onMouseUp);
            window.removeEventListener('blur', releaseDpadAll);

            if (dragOverlay) {
                window.removeEventListener('dragenter', onDragEnter);
                window.removeEventListener('dragleave', onDragLeave);
                window.removeEventListener('dragover', onDragOver);
                window.removeEventListener('drop', onDrop);
            }
        },
        updateDayNightButtonState: (isPressed: boolean) => {
            if (toggleDayNightBtn) {
                toggleDayNightBtn.setAttribute('aria-checked', String(isPressed));
                toggleDayNightBtn.setAttribute(
                    'aria-label',
                    isPressed ? 'Switch to Day' : 'Switch to Night'
                );
                toggleDayNightBtn.title = isPressed ? 'Switch to Day (N)' : 'Switch to Night (N)';
                // UX: Update button text to show available action
                toggleDayNightBtn.innerHTML = isPressed
                    ? '<span aria-hidden="true">☀️</span> Switch to Day <span class="key-badge" aria-hidden="true">N</span>'
                    : '<span aria-hidden="true">🌙</span> Switch to Night <span class="key-badge" aria-hidden="true">N</span>';

                import('../../utils/toast.ts').then(({ showToast }) => {
                    const mode = isPressed ? 'Night Mode Active 🌙' : 'Day Mode Active ☀️';
                    showToast(mode, isPressed ? '🌙' : '☀️');
                });
            }
        },
    };
}

import { AudioSystem } from '../../audio/audio-system.ts';
import { BeatSync } from '../../audio/beat-sync.ts';
import { StageLoader } from '../../debug/index.ts';
import { validateNodeGeometries } from '../../foliage/index.ts';
import { musicReactivitySystem } from '../../systems/music-reactivity.ts';
import type { WeatherSystem } from '../../systems/weather.ts';
import { initWorldCritical } from '../../world/generation.ts';
import { CONFIG } from '../config.ts';
import type { MainContext } from './context.ts';
import { scene, renderer } from './exports.ts';

export async function runAudioWorldPipeline(ctx: MainContext): Promise<void> {
    const { loadingScreen } = ctx;

    loadingScreen.startPhase('audio-init');
    console.time('Audio & Systems Init');

    await StageLoader.loadStage('audio', () => {
        ctx.audioSystem = new AudioSystem(CONFIG.audio.useScriptProcessorNode);
        (window as any).AudioSystem = ctx.audioSystem;
        loadingScreen.updateProgress(40, 'Creating audio system...');
        ctx.beatSync = new BeatSync(ctx.audioSystem!);
    });

    await StageLoader.loadStage('weather', async () => {
        loadingScreen.updateProgress(70, 'Initializing weather system...');
        const { loadWeatherSystem } = await import('../../systems/weather/lazy.ts');
        ctx.weatherSystem = (await loadWeatherSystem(scene, renderer as any)) as WeatherSystem;
    });

    console.timeEnd('Audio & Systems Init');
    loadingScreen.updateProgress(100);
    loadingScreen.completePhase('audio-init');

    loadingScreen.startPhase('world-generation');
    console.time('World Generation');
    loadingScreen.updateProgress(10, 'Loading critical world...');

    await StageLoader.loadStage('worldCritical', async () => {
        loadingScreen.updateProgress(20, 'Generating terrain...');
        const result = await initWorldCritical(scene, ctx.weatherSystem!);
        ctx.moon = result.moon;
        loadingScreen.updateProgress(90, 'World objects ready...');
    });

    console.timeEnd('World Generation');
    loadingScreen.updateProgress(100, 'Base world ready');
    loadingScreen.completePhase('world-generation');

    await StageLoader.loadStage('musicReactivity', () => {
        musicReactivitySystem.init(scene, ctx.weatherSystem!, ctx.beatSync);
        if (ctx.moon) {
            musicReactivitySystem.registerMoon(ctx.moon);
        }

        const audioSystem = ctx.audioSystem;
        if (audioSystem) {
            if (audioSystem.onNote) {
                audioSystem.onNote((note: string, velocity: number, channel: number) => {
                    musicReactivitySystem.handleNoteOn(note, velocity, channel);
                });
            } else if (audioSystem.setNoteCallback) {
                audioSystem.setNoteCallback((note: string, velocity: number, channel: number) => {
                    musicReactivitySystem.handleNoteOn(note, velocity, channel);
                });
            }
        }
    });

    if ('requestIdleCallback' in window) {
        requestIdleCallback(() => validateNodeGeometries(scene), { timeout: 3000 });
    } else {
        setTimeout(() => validateNodeGeometries(scene), 100);
    }
}

import type { InteractionSystem } from '../../systems/interaction.ts';
import { runAudioWorldPipeline } from './audio-world-pipeline.ts';
import type { MainContext } from './context.ts';
import { scheduleDeferredLoading } from './deferred-loading.ts';
import { runInputPipeline } from './input-pipeline.ts';
import { runLoadingBootstrap } from './loading-bootstrap.ts';
import { runScenePipeline } from './scene-pipeline.ts';
import { runShaderWarmup } from './shader-warmup.ts';
import { setupStartScreen } from './start-screen.ts';
import { runWasmPipeline } from './wasm-pipeline.ts';

function createInitialContext(
    loadingScreen: MainContext['loadingScreen'],
    waitForFullPopulation: boolean
): MainContext {
    return {
        loadingScreen,
        waitForFullPopulation,
        worldGenerationActive: false,
        mode: 'webgpu',
        postProcessing: null,
        timeOffset: { value: 0 },
        inputSystem: null,
        controls: null,
        interactionSystem: {
            triggerClick: () => false,
            update: () => {},
            dispose: () => {},
        } as any as InteractionSystem,
    };
}

export async function runBootstrap(): Promise<void> {
    const { loadingScreen, waitForFullPopulation } = runLoadingBootstrap();
    const ctx = createInitialContext(loadingScreen, waitForFullPopulation);

    await runScenePipeline(ctx);
    await runAudioWorldPipeline(ctx);
    await runInputPipeline(ctx);
    await runWasmPipeline(ctx);
    runShaderWarmup(ctx);
    setupStartScreen(ctx);
    scheduleDeferredLoading(ctx);
}

