const _scratchClickDir = new THREE.Vector3();
const _scratchClickOrigin = new THREE.Vector3();

export async function runInputPipeline(ctx: MainContext): Promise<void> {
    ctx.timeOffset = { value: 0 };

    await StageLoader.loadStage('input', () => {
        ctx.inputSystem = initInput(
            camera,
            ctx.audioSystem!,
            () => toggleDayNight(ctx.timeOffset),
            () => (player as any).isDancing
        );
        setInputSystem(ctx.inputSystem);
        ctx.controls = ctx.inputSystem.controls;
    });

    if (!ctx.inputSystem) {
        ctx.inputSystem = {
            controls: null,
            updateReticleState: () => {},
            setPlaylistMode: () => {},
            getPlaylistIndex: () => -1,
        };
    }

    await StageLoader.loadStage('interaction', () => {
        ctx.interactionSystem = new InteractionSystem(camera, ctx.inputSystem.updateReticleState);
    });

    if (!ctx.interactionSystem) {
        ctx.interactionSystem = {
            triggerClick: () => false,
            update: () => {},
            dispose: () => {},
        } as any;
    }

    initDeferredVisualsDependencies(scene, camera, renderer);

    const sceneInit = ctx.sceneInitResult!;
    await StageLoader.loadStage('gameLoop', () => {
        if (!ctx.interactionSystem) {
            console.warn('[gameLoop] InteractionSystem not initialized, using dummy');
            ctx.interactionSystem = {
                triggerClick: () => false,
                update: () => {},
                dispose: () => {},
            } as any;
        }
        initGameLoopDependencies({
            scene,
            camera,
            renderer,
            postProcessing: ctx.postProcessing,
            weatherSystem: ctx.weatherSystem!,
            audioSystem: ctx.audioSystem!,
            beatSync: ctx.beatSync!,
            interactionSystem: ctx.interactionSystem!,
            moon: ctx.moon,
            fireflies: null,
            controls: ctx.controls,
            sunLight: sceneInit.sunLight,
            ambientLight: sceneInit.ambientLight,
            sunGlow: sceneInit.sunGlow,
            sunCorona: sceneInit.sunCorona,
            lightShaftGroup: sceneInit.lightShaftGroup,
            sunGlowMat: sceneInit.sunGlowMat,
            coronaMat: sceneInit.coronaMat,
            uShaftOpacity: sceneInit.uShaftOpacity,
            timeOffset: ctx.timeOffset,
        });

        const canvasEl = document.getElementById('glCanvas') as HTMLCanvasElement | null;
        if (canvasEl && ctx.controls) {
            registerPhotoModeInit({
                camera,
                canvas: canvasEl,
                controls: ctx.controls,
                timeOffset: ctx.timeOffset,
                renderer,
                renderFrame: () => ctx.postProcessing.render(),
                getGameTime,
            });
        }
    });

    window.addEventListener('keydown', (e) => {
        try {
            if (!e.key) return;
            const key = e.key.toLowerCase();
            if (key === 'p') {
                profiler.toggle();
            } else if (key === 'o' && !e.ctrlKey && !e.shiftKey && !e.altKey && !e.metaKey) {
                toggleOverlay();
            } else if (key === 'f') {
                // Demo logic...
            } else if (key === 'g') {
                if (document.pointerLockElement) {
                    camera.getWorldDirection(_scratchClickDir);
                    void ensureGameplay().then((gp) => {
                        gp.glitchGrenadeSystem.throwGrenade(scene, camera.position, _scratchClickDir);
                    });
                }
            }
        } catch (err) {
            console.warn('Demo trigger error', err);
        }
    });

    window.addEventListener('mousedown', (e) => {
        if (document.pointerLockElement) {
            if (e.button === 0) {
                const handled = ctx.interactionSystem?.triggerClick?.() ?? false;
                if (!handled) {
                    camera.getWorldDirection(_scratchClickDir);
                    _scratchClickOrigin.copy(camera.position).addScaledVector(_scratchClickDir, 1.0);
                    _scratchClickOrigin.y -= 0.2;
                    void ensureGameplay().then((gp) => {
                        gp.fireRainbow(scene, _scratchClickOrigin, _scratchClickDir);
                    });
                }
            }
        }
    });

    const initialGroundY = getGroundHeight(camera.position.x, camera.position.z);
    camera.position.y = initialGroundY + CONFIG.player.eyeHeight;
    player.position.copy(camera.position);
    player.velocity.set(0, 0, 0);
    console.log(`[Startup] Camera positioned at ground height: y=${camera.position.y.toFixed(2)}`);
}

import { initDebugPanelIfNeeded } from '../../debug/index.ts';
import { initializeSaveSystemIntegration } from '../../systems/save-integration-lazy.ts';
import { initAnalyticsDebugIfNeeded } from '../../ui/analytics-debug-lazy.ts';
import { initLoadingScreen, installLegacyAPI } from '../../ui/loading-screen.ts';
import { installPresenceStartScreenUI } from '../../ui/presence-lazy.ts';
import { installSaveMenuGlobals } from '../../ui/save-menu/lazy.ts';
import { enableStartupProfiler } from '../../utils/startup-profiler.ts';
import {
    isCIorHeadless,
    getDeviceMemoryGB,
    getLoadMemoryScale,
    getLoadMemoryTier,
    shouldPreferLightWorldLoad,
    CONFIG,
} from '../config.ts';
import { loadStartupProfile, mapSizeWaitsForFullPopulation } from '../startup-profile.ts';
import type { LoadingScreen } from './context.ts';

export interface LoadingBootstrapResult {
    loadingScreen: LoadingScreen;
    waitForFullPopulation: boolean;
}

export function runLoadingBootstrap(): LoadingBootstrapResult {
    if (CONFIG.safeMode || isCIorHeadless()) {
        console.warn('[Startup] safeMode active (?safe=1) — shader warmup and compute disabled');
        (window as any).__computeDisabled = true;
    }

    const profile = loadStartupProfile();
    (window as any).__startupProfile = profile;
    // Large map implies wait-for-full; URL ?waitForFull still forces it for smoke/debug.
    const waitForFullPopulation =
        new URLSearchParams(location.search).has('waitForFull') ||
        mapSizeWaitsForFullPopulation(profile.mapSize);

    const loadingScreen = initLoadingScreen({ theme: 'candy', showEstimatedTime: true });
    loadingScreen.show();
    installLegacyAPI();

    installPresenceStartScreenUI();

    window.addEventListener('unhandledrejection', (event) => {
        const err = event.reason;
        const msg = err instanceof Error ? err.message : String(err ?? 'Unknown error');
        console.error('[Bootstrap] Unhandled rejection during startup:', err);
        try {
            loadingScreen.showFatalError(
                `Startup failed: ${msg}\n\nRefresh the page to try again.`
            );
        } catch (_) {
            const fallback =
                document.getElementById('loading-overlay') ??
                document.getElementById('loading-container');
            if (fallback) {
                const p = document.createElement('p');
                p.style.cssText = 'color:red;padding:1rem';
                p.textContent = `Error: ${msg}`;
                const btn = document.createElement('button');
                btn.textContent = 'Reload';
                btn.addEventListener('click', () => window.location.reload());
                p.appendChild(document.createElement('br'));
                p.appendChild(btn);
                fallback.appendChild(p);
            }
        }
    });

    enableStartupProfiler({
        slowPhaseThreshold: 100,
        enableOverlay: false,
        enableConsole: true,
        saveToFile: false,
    });

    {
        const tier = getLoadMemoryTier();
        const gb = getDeviceMemoryGB();
        console.log(
            `[Startup] Memory tier: ${tier}` +
                (typeof gb === 'number' ? ` (~${gb} GB deviceMemory)` : '') +
                ` · population scale=${getLoadMemoryScale().toFixed(2)}` +
                (shouldPreferLightWorldLoad() ? ' · preferring lighter Full-mode population' : '')
        );
        console.log(
            `[Startup] Profile: graphics=${profile.graphics} map=${profile.mapSize}` +
                (waitForFullPopulation ? ' · wait-for-full' : '')
        );
    }

    initDebugPanelIfNeeded();
    void import('../../foliage/batcher-telemetry.ts').then((m) => m.installBatcherTelemetry());
    installSaveMenuGlobals();
    void initAnalyticsDebugIfNeeded();
    initializeSaveSystemIntegration();

    return { loadingScreen, waitForFullPopulation };
}

