// EXAMPLE 6: Complete Integration
// ============================================================================

export async function initializeGame(): Promise<void> {
    const scene = new THREE.Scene();
    const player = new THREE.Object3D();
    const audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();

    // 1. Set up asset streaming
    const streamer = setupAssetStreaming(scene, audioContext);

    // 2. Create game world
    const world = new GameWorld(scene, player, streamer);

    // 3. Set up memory monitoring
    setupMemoryMonitoring(streamer);

    // 4. Load critical assets first
    await streamer.loadAsset('player_model', AssetPriority.CRITICAL);
    await streamer.loadAsset('core_shaders', AssetPriority.CRITICAL);

    // 5. Start game loop
    function gameLoop() {
        requestAnimationFrame(gameLoop);

        // Update player position (would come from input/physics)
        // player.position.add(velocity);

        // Update streaming
        world.update(1/60);
    }

    gameLoop();

    // 6. Handle page unload
    window.addEventListener('beforeunload', () => {
        world.dispose();
    });
}

// Import for types
import type { LoadingProgress } from '../systems';

import { positionLocal, time, float, sin, cos, vec3, attribute, select, positionWorld, normalLocal } from 'three/tsl';
import { uAudioLow, uAudioHigh } from './material-core.ts';


// Enum-like IDs for animation types
export const ANIMATION_TYPES = {
    STATIC: 0,
    GENTLE_SWAY: 1,
    BOUNCE: 2,
    SHIVER: 3,
    HOP: 4,
    VINE_SWAY: 5,
    SPIRAL_WAVE: 6,
    SPRING: 7,
    WOBBLE: 8,
    ACCORDION: 9,
    ACCORDION_STRETCH: 10,
    FIBER_WHIP: 11
};

/**
 * Shared TSL animation nodes
 */

// Gentle Sway: Slow, subtle rotation on Z and X
export const gentleSwayNode = (animOffset: any) => {
    const t = time.add(animOffset);
    const swayZ = sin(t).mul(0.05);
    const swayX = cos(t.mul(0.8)).mul(0.05);
    return vec3(swayX.mul(positionLocal.y), float(0), swayZ.mul(positionLocal.y));
};

// Bounce: Scale Y up and down
export const bounceNode = (animOffset: any) => {
    const t = time.mul(4).add(animOffset);
    const bounce = sin(t).mul(0.1).add(uAudioLow.mul(0.2));
    return vec3(positionLocal.x, positionLocal.y.mul(bounce.add(1.0)), positionLocal.z).sub(positionLocal);
};

// Shiver: Fast vibration
export const shiverNode = (animOffset: any) => {
    const t = time.mul(20).add(animOffset);
    const shiverZ = sin(t).mul(0.05).add(uAudioLow.mul(0.1));
    const shiverX = shiverZ.mul(0.5);
    return vec3(shiverX.mul(positionLocal.y), float(0), shiverZ.mul(positionLocal.y));
};

// Spring: Scale Y inverse to X/Z
export const springNode = (animOffset: any) => {
    const t = time.mul(5).add(animOffset);
    const sy = sin(t).mul(0.1).add(1.0);
    const sxz = float(1.0).sub(sin(t).mul(0.05));
    return vec3(positionLocal.x.mul(sxz), positionLocal.y.mul(sy), positionLocal.z.mul(sxz)).sub(positionLocal);
};

// Vine Sway: Like sway but faster
export const vineSwayNode = (animOffset: any) => {
    const t = time.mul(1.5).add(animOffset);
    const swayZ = sin(t).mul(0.2);
    const swayX = cos(t.mul(1.2).add(animOffset)).mul(0.1);
    return vec3(swayX.mul(positionLocal.y), float(0), swayZ.mul(positionLocal.y));
};

// Hop: Upward bob
export const hopNode = (animOffset: any) => {
    const t = time.mul(6).add(animOffset);
    const hopY = sin(t).mul(0.1);
    return vec3(float(0), hopY, float(0));
};

// Wobble: Bending side to side
export const wobbleNode = (animOffset: any) => {
    const t = time.mul(3).add(animOffset);
    const wobbleZ = sin(t).mul(0.1);
    return vec3(float(0), float(0), wobbleZ.mul(positionLocal.y));
};

// Accordion / Stretch: Scale Y heavily
export const accordionNode = (animOffset: any) => {
    const t = time.mul(3).add(animOffset);
    const stretch = sin(t).mul(0.2);
    return vec3(positionLocal.x, positionLocal.y.mul(stretch.add(1.0)), positionLocal.z).sub(positionLocal);
};

// Spiral Wave: Rotate around Y axis while swaying
export const spiralWaveNode = (animOffset: any) => {
    const t = time.mul(2).add(animOffset);
    const swayX = sin(t.add(positionLocal.y)).mul(0.1);
    const swayZ = cos(t.add(positionLocal.y)).mul(0.1);
    return vec3(swayX.mul(positionLocal.y), float(0), swayZ.mul(positionLocal.y));
};

// Fiber Whip: Like grass waving fast
export const fiberWhipNode = (animOffset: any) => {
    const t = time.mul(4).add(animOffset);
    const whipZ = sin(t.add(positionLocal.y.mul(2))).mul(0.15);
    return vec3(float(0), float(0), whipZ.mul(positionLocal.y));
};

/**
 * Main switch node for instance animation.
 * Evaluates the `instanceAnimType` and `instanceAnimOffset` attributes.
 * Returns the positional offset to ADD to positionLocal.
 */
export const applyInstanceAnimation = () => {
    const animType = attribute('instanceAnimType', 'float');
    const animOffset = attribute('instanceAnimOffset', 'float');

    // Default: return zero offset
    let offset = vec3(0, 0, 0);

    offset = select(animType.equal(ANIMATION_TYPES.GENTLE_SWAY), gentleSwayNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.BOUNCE), bounceNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.SHIVER), shiverNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.SPRING), springNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.VINE_SWAY), vineSwayNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.HOP), hopNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.WOBBLE), wobbleNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.ACCORDION), accordionNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.ACCORDION_STRETCH), accordionNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.SPIRAL_WAVE), spiralWaveNode(animOffset), offset);
    offset = select(animType.equal(ANIMATION_TYPES.FIBER_WHIP), fiberWhipNode(animOffset), offset);

    return offset;
};

/**
 * Optional function to compute the normal map rotation
 */
export const applyInstanceNormalAnimation = () => {
    const animType = attribute('instanceAnimType', 'float');
    const animOffset = attribute('instanceAnimOffset', 'float');
    const t = time.mul(1.5).add(animOffset);
    const swayZ = sin(t).mul(0.2);
    const swayX = cos(t.mul(1.2).add(animOffset)).mul(0.1);

    // Crude approximation of normal rotation for intense sway
    const n = normalLocal;
    // We would rotate the normal if it was Vine Sway.
    // Given the TSL complexity of quaternions, we can do a simplified normal shift.
    const shiftedNormal = vec3(n.x.add(swayX), n.y, n.z.add(swayZ)).normalize();
    return select(animType.equal(ANIMATION_TYPES.VINE_SWAY), shiftedNormal, n);
};

// src/foliage/animation.ts

import * as THREE from 'three';
import { CONFIG } from '../core/config.ts';
import { 
  freqToHue, 
  isWasmReady,
  wasmMemory,
  wasmSmoothWobble,
  wasmBatchGrowth,
  wasmBatchBloom,
  wasmBatchScaleAnimation,
  OUTPUT_OFFSET
} from '../utils/wasm-loader.ts';
import { foliageBatcher } from './batcher/index.ts';
import { spawnImpact } from './impacts.ts';
import { reactiveMaterials, _foliageReactiveColor, median } from './index.ts';
import { FoliageObject, AudioData, FoliageMaterial, ChannelData } from './types.ts';

// WASM memory views for batch operations
let growthDataView: Float32Array | null = null;
let bloomDataView: Float32Array | null = null;
let scaleAnimDataView: Float32Array | null = null;
let wobbleBufferView: Float32Array | null = null;

/**
 * Initialize WASM memory views for batch operations
 */
function initWasmViews(): void {
  if (!wasmMemory) return;
  const buffer = wasmMemory.buffer;
  // Allocate views at OUTPUT_OFFSET for batch operations
  growthDataView = new Float32Array(buffer, OUTPUT_OFFSET, 1024);
  bloomDataView = new Float32Array(buffer, OUTPUT_OFFSET + 4096, 1024);
  scaleAnimDataView = new Float32Array(buffer, OUTPUT_OFFSET + 8192, 1024);
  wobbleBufferView = new Float32Array(buffer, OUTPUT_OFFSET + 12288, 256);
}

export * from './types.ts';

// ⚡ OPTIMIZATION: Shared scratch variables to prevent GC in hot loops
const _scratchOne = new THREE.Vector3(1, 1, 1);
const _scratchWhite = new THREE.Color(0xFFFFFF);
const _scratchDarkColor = new THREE.Color(); // For applyWetEffect

export function triggerGrowth(plants: FoliageObject[], intensity: number): void {
    // Initialize WASM views on first use
    if (isWasmReady() && !growthDataView) {
        initWasmViews();
    }

    // Use WASM batch processing if available and we have enough plants
    if (isWasmReady() && wasmBatchGrowth && growthDataView && plants.length >= 4) {
        const batchSize = Math.min(plants.length, 36); // Max 36 plants per batch (36 * 7 floats = 1008 bytes)
        let dataIdx = 0;

        // Prepare batch data
        for (let i = 0; i < batchSize; i++) {
            const plant = plants[i];

            // Initialize baseline scales if not present
            if (plant.userData.initialScale === undefined) {
                plant.userData.initialScale = plant.scale.x;
            }
            if (!plant.userData.maxScale) {
                const growthFactor = plant.userData.type === 'mushroom' ? 2.5 : 1.5;
                plant.userData.maxScale = plant.userData.initialScale * growthFactor;
            }
            if (!plant.userData.minScale) {
                plant.userData.minScale = plant.userData.initialScale * 0.5;
            }

            // Pack data: [currentScale, initialScale, maxScale, minScale, growthRate, outputScale, changed]
            growthDataView![dataIdx++] = plant.scale.x;
            growthDataView![dataIdx++] = plant.userData.initialScale;
            growthDataView![dataIdx++] = plant.userData.maxScale;
            growthDataView![dataIdx++] = plant.userData.minScale;
            growthDataView![dataIdx++] = intensity * 0.01;
            growthDataView![dataIdx++] = 0; // output placeholder
            growthDataView![dataIdx++] = 0; // changed flag placeholder
        }

        // Call WASM batch function
        wasmBatchGrowth(OUTPUT_OFFSET, batchSize);

        // Apply results
        dataIdx = 0;
        for (let i = 0; i < batchSize; i++) {
            const plant = plants[i];
            const newScale = growthDataView![dataIdx + 5];
            const changed = growthDataView![dataIdx + 6];
            dataIdx += 7;

            if (changed > 0.5) {
                plant.scale.setScalar(newScale);
            }
        }

        // Process remaining plants with JS fallback
        for (let i = batchSize, len = plants.length; i < len; i++) {
            processGrowthJS(plants[i], intensity);
        }
    } else {
        // JS Fallback: Use cached for-loop to avoid closure allocation
        for (let i = 0, len = plants.length; i < len; i++) {
            processGrowthJS(plants[i], intensity);
        }
    }
}

/** JS fallback for single plant growth */
function processGrowthJS(plant: FoliageObject, intensity: number): void {
    const ud = plant.userData;

    // ⚡ OPTIMIZATION: Bypassed repeated undefined checks and property lookups by caching limits
    if (ud._growthLimitsInit === undefined) {
        if (ud.initialScale === undefined) {
            ud.initialScale = plant.scale.x;
        }

        const growthFactor = ud.type === 'mushroom' ? 2.5 : 1.5;
        ud.maxScale = ud.initialScale * growthFactor;
        ud.minScale = ud.initialScale * 0.5;
        ud._growthLimitsInit = true;
    }

    const currentScale = plant.scale.x;
    const growthRate = intensity * 0.01;
    let nextScale = currentScale + growthRate;

    // Apply Limits
    if (growthRate > 0) {
        if (nextScale > (ud.maxScale ?? 1.5)) nextScale = ud.maxScale ?? 1.5;
    } else {
        if (nextScale < ud.minScale) nextScale = ud.minScale;
    }

    // Apply scale if changed
    if (Math.abs(nextScale - currentScale) > 0.0001) {
        plant.scale.setScalar(nextScale);
    }
}

export function triggerBloom(flowers: FoliageObject[], intensity: number): void {
    // Initialize WASM views on first use
    if (isWasmReady() && !bloomDataView) {
        initWasmViews();
    }

    // Filter flowers first
    const flowerList: FoliageObject[] = [];
    for (let i = 0, len = flowers.length; i < len; i++) {
        const f = flowers[i];
        if (f.userData.type === 'flower' && (f.userData.isFlower || f.userData.type === 'flower')) {
            flowerList.push(f);
        }
    }

    // Use WASM batch processing if available and we have enough flowers
    if (isWasmReady() && wasmBatchBloom && bloomDataView && flowerList.length >= 4) {
        const batchSize = Math.min(flowerList.length, 42); // Max 42 flowers per batch (42 * 6 floats = 1008 bytes)
        let dataIdx = 0;

        // Prepare batch data
        for (let i = 0; i < batchSize; i++) {
            const flower = flowerList[i];

            if (!flower.userData.maxBloom) {
                flower.userData.maxBloom = flower.scale.x * 1.3;
            }

            // Pack data: [currentScale, maxBloom, bloomRate, outputScale, changed, padding]
            bloomDataView![dataIdx++] = flower.scale.x;
            bloomDataView![dataIdx++] = flower.userData.maxBloom;
            bloomDataView![dataIdx++] = intensity * 0.02;
            bloomDataView![dataIdx++] = 0; // output placeholder
            bloomDataView![dataIdx++] = 0; // changed flag placeholder
            bloomDataView![dataIdx++] = 0; // padding
        }

        // Call WASM batch function
        wasmBatchBloom(OUTPUT_OFFSET + 4096, batchSize);

        // Apply results
        dataIdx = 0;
        for (let i = 0; i < batchSize; i++) {
            const flower = flowerList[i];
            const newScale = bloomDataView![dataIdx + 3];
            const changed = bloomDataView![dataIdx + 4];
            dataIdx += 6;

            if (changed > 0.5) {
                flower.scale.setScalar(newScale);
            }
        }

        // Process remaining flowers with JS fallback
        for (let i = batchSize, len = flowerList.length; i < len; i++) {
            processBloomJS(flowerList[i], intensity);
        }
    } else {
        // JS Fallback
        for (let i = 0, len = flowerList.length; i < len; i++) {
            processBloomJS(flowerList[i], intensity);
        }
    }
}

/** JS fallback for single flower bloom */
function processBloomJS(flower: FoliageObject, intensity: number): void {
    if (!flower.userData.maxBloom) {
        flower.userData.maxBloom = flower.scale.x * 1.3;
    }

    if (flower.scale.x < flower.userData.maxBloom) {
        const bloomRate = intensity * 0.02;
        flower.scale.addScalar(bloomRate);
    }
}

function applyWetEffect(material: FoliageMaterial, wetAmount: number): void {
    if (material.userData.dryRoughness === undefined) {
        material.userData.dryRoughness = material.roughness || 0.5;
        material.userData.dryMetalness = material.metalness || 0;
        if (material.color) {
            // ⚡ OPTIMIZATION: Avoid allocating a new color on the fly
            if (!material.userData.dryColor) {
                 material.userData.dryColor = new THREE.Color();
            }
            material.userData.dryColor.copy(material.color);
        }
    }

    if (material.roughness !== undefined && material.userData.dryRoughness !== undefined) {
        const targetRoughness = THREE.MathUtils.lerp(material.userData.dryRoughness, 0.2, wetAmount);
        material.roughness = targetRoughness;
    }

    if (material.metalness !== undefined && material.userData.dryMetalness !== undefined) {
        const targetMetalness = THREE.MathUtils.lerp(material.userData.dryMetalness, 0.15, wetAmount);
        material.metalness = targetMetalness;
    }

    if (material.color && material.userData.dryColor) {
        // ⚡ OPTIMIZATION: Avoid clone() by using scratch variable
        _scratchDarkColor.copy(material.userData.dryColor).multiplyScalar(1 - wetAmount * 0.3);
        material.color.lerp(_scratchDarkColor, 0.1);
    }
}

export function updateFoliageMaterials(audioData: AudioData | null, isNight: boolean, weatherState: string | null = null, weatherIntensity: number = 0): void {
    if (!audioData) return;

    const channels = audioData.channelData;
    const hasChannels = channels && channels.length > 0;

    // Calculate global wetAmount once per frame outside the loop
    let globalWetAmount = 0;
    if (weatherState && weatherIntensity > 0) {
        if (weatherState === 'rain') {
            globalWetAmount = weatherIntensity * 0.5;
        } else if (weatherState === 'storm') {
            globalWetAmount = weatherIntensity * 0.8;
        }
    }

    // ⚡ OPTIMIZATION: Single O(N) loop over reactiveMaterials combining audio and weather reactivity
    const mats = reactiveMaterials as unknown as FoliageMaterial[];
    for (let i = 0; i < mats.length; i++) {
        const mat = mats[i];
        if (!mat) continue;

        // 1. Audio Reactivity (Night/Day)
        if (isNight && hasChannels) {
            const chIndex = (i % 4) + 1;
            const ch = channels[Math.min(chIndex, channels.length - 1)];

            if (ch && ch.freq > 0) {
                const hue = freqToHue(ch.freq);
                _foliageReactiveColor.setHSL(hue, 1.0, 0.6);

                // Check material type using 'type' string or property presence
                if ((mat as any).isMeshBasicMaterial && mat.color) {
                    mat.color.lerp(_foliageReactiveColor, 0.3);
                } else if (mat.emissive) {
                    mat.emissive.lerp(_foliageReactiveColor, 0.3);
                }
            }
            const intensity = 0.2 + (ch?.volume || 0) + (ch?.trigger || 0) * 2.0;

            if (!(mat as any).isMeshBasicMaterial && mat.emissiveIntensity !== undefined) {
                 mat.emissiveIntensity = intensity;
            }
        } else if (!isNight) {
            // Day mode - reset emissive
            if (mat.emissive) {
                mat.emissive.setHex(0x000000);
                mat.emissiveIntensity = 0;
            }
        }

        // 2. Weather Reactivity (Wet Effect)
        if (globalWetAmount > 0 && (mat as any).isMaterial) {
            applyWetEffect(mat, globalWetAmount);
        }
    }
}

// @perf-migrate {target: "asc", reason: "hot-loop-math", threshold: "3ms", note: "Iterates over thousands of reactive objects every frame"}
export function animateFoliage(foliageObject: FoliageObject, time: number, audioData: AudioData | null, isDay: boolean, isDeepNight: boolean = false): void {
    const offset = foliageObject.userData.animationOffset || 0;
    const type = foliageObject.userData.animationType;

    // --- Per-note flash application (emissive/color) with automatic fade-back ---
    // This logic handles visual color flashes. It needs to run even if physics/motion is batched.
    const reactive = foliageObject.userData.reactiveMeshes;

    // Fast path: skip material updates if no reactive meshes
    if (reactive && reactive.length > 0) {
        // Check if any child has active flash or needs fade back to avoid unnecessary iteration
        let hasActiveFlash = false;
        let needsFadeBack = false;
        for (let i = 0; i < reactive.length; i++) {
            const child = reactive[i];
            if ((child.userData.flashIntensity || 0) > 0) {
                hasActiveFlash = true;
            }
            if (child.userData._needsFadeBack) {
                needsFadeBack = true;
            }
            if (hasActiveFlash && needsFadeBack) break; // Early exit if we found both
        }

        // Only update materials if there's an active flash or we need to fade back
        if (hasActiveFlash || needsFadeBack) {
            for (let i = 0; i < reactive.length; i++) {
                const child = reactive[i];
                const fi = child.userData.flashIntensity || 0;
                const decay = child.userData.flashDecay ?? 0.05;

                // ⚡ OPTIMIZATION: Removed Array Allocation [child.material] and repeated isArray checks
                if (child.userData._matCount === undefined) {
                    child.userData._isArray = Array.isArray(child.material);
                    child.userData._matCount = child.userData._isArray ? (child.material as FoliageMaterial[]).length : (child.material ? 1 : 0);
                }
                const isArray = child.userData._isArray;
                const materialCount = child.userData._matCount;

                if (fi > 0) {
                    const fc = child.userData.flashColor || _scratchWhite;
                    for (let m = 0; m < materialCount; m++) {
                        const mat = isArray ? (child.material as FoliageMaterial[])[m] : (child.material as FoliageMaterial);
                        if (!mat) continue;

                        // ⚡ OPTIMIZATION: Cache property access to avoid dynamic lookups
                        const matIsMeshBasicMaterial = (mat as any).isMeshBasicMaterial;

                        // stronger blend for higher intensity; immediate override when very strong
                        const t = Math.min(1, fi * 1.2) * 0.8;

                        if (matIsMeshBasicMaterial && mat.color) {
                            if (fi > 0.7) mat.color.copy(fc);
                            else mat.color.lerp(fc, t);
                        } else if (mat.emissive) {
                            if (fi > 0.7) mat.emissive.copy(fc);
                            else mat.emissive.lerp(fc, t);
                            // ensure visible intensity (min floor) scaled by global flashScale
                            mat.emissiveIntensity = Math.max(0.2, fi * ((CONFIG as any).flashScale || 2.0));
                        }
                    }

                    // decay flash intensity
                    child.userData.flashIntensity = Math.max(0, fi - decay);
                    if (child.userData.flashIntensity === 0) {
                        // keep base colors in place and allow fade-back logic to run next frame
                        // ⚡ OPTIMIZATION: Do not use 'delete' on object properties as it de-optimizes the V8 hidden class and causes GC.
                        // Setting to undefined or 0 is preferable. In this case, flashIntensity = 0 effectively disables it.
                        child.userData.flashDecay = 0;
                        child.userData._needsFadeBack = true; // Mark this specific child for fade-back
                    }
                } else if (child.userData._needsFadeBack) {
                    // No active flash: smoothly fade materials back to their stored base colors/emissives
                    const fadeT = (CONFIG as any).reactivity?.fadeSpeed ?? 0.06;
                    const snapThreshold = (CONFIG as any).reactivity?.fadeSnapThreshold ?? 0.06;
                    const snapThresholdSq = snapThreshold * snapThreshold; // Avoid sqrt in distance check
                    let allFadedBack = true;

                    for (let m = 0; m < materialCount; m++) {
                        const mat = isArray ? (child.material as FoliageMaterial[])[m] : (child.material as FoliageMaterial);
                        if (!mat) continue;

                        // ⚡ OPTIMIZATION: Cache property access to avoid dynamic lookups
                        const matIsMeshBasicMaterial = (mat as any).isMeshBasicMaterial;
                        const matUserData = mat.userData;

                        if (matIsMeshBasicMaterial) {
                            if (matUserData && matUserData.baseColor && mat.color) {
                                // ⚡ OPTIMIZATION: Inline color distance check to avoid method-call overhead
                                const c = mat.color;
                                const b = matUserData.baseColor;
                                const dr = c.r - b.r;
                                const dg = c.g - b.g;
                                const db = c.b - b.b;
                                const distSq = dr * dr + dg * dg + db * db;
                                if (distSq > snapThresholdSq) {
                                    mat.color.lerp(matUserData.baseColor, fadeT);
                                    allFadedBack = false;
                                } else {
                                    mat.color.copy(matUserData.baseColor);
                                }
                            }
                        } else if (mat.emissive) {
                            if (matUserData && matUserData.baseEmissive) {
                                mat.emissive.lerp(matUserData.baseEmissive, fadeT);
                            }
                            // lerp emissiveIntensity back toward 0
                            const current = mat.emissiveIntensity || 0;
                            if (current > snapThreshold) {
                                mat.emissiveIntensity = THREE.MathUtils.lerp(current, 0, fadeT);
                                allFadedBack = false;
                            } else {
                                // If intensity is very low, snap back to base to avoid residual tint
                                if (matUserData && matUserData.baseEmissive) {
                                    mat.emissive.copy(matUserData.baseEmissive);
                                }
                                mat.emissiveIntensity = 0;
                            }
                        }
                    }

                    // Clear fade back flag when all materials have returned to base
                    if (allFadedBack) {
                        child.userData._needsFadeBack = false;
                    }
                }
            }
        }
    }

    // --- Mushroom Night Glow Animation (Bioluminescence) ---
    // Animate the glow light intensity for mushrooms with bioluminescence
    if (foliageObject.userData.glowLight && foliageObject.userData.isBioluminescent) {
        const light = foliageObject.userData.glowLight;
        const baseIntensity = light.userData.baseIntensity || 0.8;

        // If there was a recent flash (from note trigger), decay back to base
        if (light.intensity > baseIntensity * 1.2) {
            light.intensity = THREE.MathUtils.lerp(light.intensity, baseIntensity, 0.08);
        } else {
            // Normal gentle pulsing when idle (at night)
            const pulseSpeed = 2.0 + (foliageObject.userData.animationOffset || 0) * 0.3;
            const pulse = Math.sin(time * pulseSpeed) * 0.2 + 1.0; // 0.8 to 1.2
            light.intensity = baseIntensity * pulse;
        }
    }

    // --- Mushroom Scale Animation (from note bounce) ---
    // Animate scale back to base after note trigger (replaces setTimeout)
    if (foliageObject.userData.scaleAnimStart) {
        const elapsed = Date.now() - foliageObject.userData.scaleAnimStart;
        const duration = foliageObject.userData.scaleAnimTime || 0.08;
        const t = Math.min(1.0, elapsed / (duration * 1000));

        // Initialize WASM views on first use
        if (isWasmReady() && !scaleAnimDataView) {
            initWasmViews();
        }

        if (isWasmReady() && wasmBatchScaleAnimation && scaleAnimDataView && t < 1.0) {
            // Use WASM for scale animation calculation
            const target = foliageObject.userData.scaleTarget || 1.0;
            const lerpFactor = t * 0.5;

            // Pack data: [curX, curY, curZ, target, lerpT, ...output]
            scaleAnimDataView[0] = foliageObject.scale.x;
            scaleAnimDataView[1] = foliageObject.scale.y;
            scaleAnimDataView[2] = foliageObject.scale.z;
            scaleAnimDataView[3] = target;
            scaleAnimDataView[4] = lerpFactor;

            // Call WASM function
            wasmBatchScaleAnimation(OUTPUT_OFFSET + 8192, 1);

            // Apply results
            foliageObject.scale.x = scaleAnimDataView[5];
            foliageObject.scale.y = scaleAnimDataView[6];
            foliageObject.scale.z = scaleAnimDataView[7];

            // Check if completed
            if (scaleAnimDataView[8] > 0.5) {
                foliageObject.scale.setScalar(target);
                foliageObject.userData.scaleAnimStart = undefined;
                foliageObject.userData.scaleTarget = undefined;
                foliageObject.userData.scaleAnimTime = undefined;
            }
        } else if (t < 1.0) {
            const target = foliageObject.userData.scaleTarget || 1.0;
            // Lerp each axis independently to handle non-uniform squash/stretch smoothly
            // (e.g. restoring aspect ratio from flattened state)
            foliageObject.scale.x = THREE.MathUtils.lerp(foliageObject.scale.x, target, t * 0.5);
            foliageObject.scale.y = THREE.MathUtils.lerp(foliageObject.scale.y, target, t * 0.5);
            foliageObject.scale.z = THREE.MathUtils.lerp(foliageObject.scale.z, target, t * 0.5);
        } else {
            // Animation complete
            foliageObject.scale.setScalar(foliageObject.userData.scaleTarget || 1.0);
            foliageObject.userData.scaleAnimStart = undefined;
            foliageObject.userData.scaleTarget = undefined;
            foliageObject.userData.scaleAnimTime = undefined;
        }
    }

    // --- Mushroom wobble smoothing (median + lerp) ---
    if (foliageObject.userData.type === 'mushroom') {
        const buf = foliageObject.userData.noteBuffer || [];

        // Initialize WASM views on first use
        if (isWasmReady() && !wobbleBufferView) {
            initWasmViews();
        }

        // Use WASM if available and buffer has data
        if (isWasmReady() && wasmSmoothWobble && wobbleBufferView && buf.length > 0) {
            // Copy buffer to WASM memory (max 64 floats = 256 bytes)
            const bufferSize = Math.min(buf.length, 64);
            for (let i = 0; i < bufferSize; i++) {
                wobbleBufferView![i] = buf[i];
            }

            const cfg = (CONFIG as any).reactivity?.mushroom || {};
            const currentWobble = foliageObject.userData.wobbleCurrent || 0;

            // Call WASM smoothWobble function
            const newWobble = wasmSmoothWobble(
                OUTPUT_OFFSET + 12288,  // wobbleBuffer location
                bufferSize,
                currentWobble,
                cfg.scale || 1.0,
                cfg.maxAmplitude ?? 1.0,
                cfg.minThreshold ?? 0.01,
                cfg.smoothingRate || 8
            );

            foliageObject.userData.wobbleCurrent = newWobble;
        } else {
            // JS Fallback
            const medianVel = median(buf);
            const cfg = (CONFIG as any).reactivity?.mushroom || {};
            const scale = cfg.scale || 1.0;
            const target = Math.min(cfg.maxAmplitude ?? 1.0, Math.max(cfg.minThreshold ?? 0.01, medianVel * scale));
            const cur = foliageObject.userData.wobbleCurrent || 0;
            const lerpT = Math.min(0.25, (cfg.smoothingRate || 8) * 0.02);
            foliageObject.userData.wobbleCurrent = THREE.MathUtils.lerp(cur, target, lerpT);
        }
    }

    let kick = 0, groove = 0, beatPhase = 0, leadVol = 0;
    if (audioData) {
        kick = audioData.kickTrigger || 0;
        groove = audioData.grooveAmount || 0;
        beatPhase = audioData.beatPhase || 0;
        leadVol = audioData.channelData?.[2]?.volume || 0;
    }

    const isActive = !isDay;
    const intensity = isActive ? (1.0 + groove * 5.0) : 0.2;
    const animTime = time + beatPhase;

    // --- WASM Batching Integration ---
    // ⚡ OPTIMIZATION: Try to queue deeply batched animation first
    // If queued, we skip the CPU transform logic below.
    // NOTE: Material Flash logic (above) still runs because TSL doesn't handle that yet for all types.
    if (foliageObject.userData.animationType && foliageBatcher.queue(foliageObject, foliageObject.userData.animationType, intensity, animTime, kick)) {
        return; // Handled by batcher
    }

    // --- Fallback JS Logic ---
    // Note: Types handled by FoliageBatcher (sway, bounce, wobble, fiberWhip, etc.)
    // are skipped if the batcher successfully queued them.
    // The logic below handles types NOT yet migrated or if the batcher is full.

    if (isDeepNight) {
        const isNightFlower = foliageObject.userData.type === 'flower' && foliageObject.userData.animationType === 'glowPulse';

        if (!isNightFlower) {
            const sleepSpeed = 0.5;
            const sleepAmount = 0.02;
            const shiver = Math.sin(time * sleepSpeed + offset) * sleepAmount;

            foliageObject.rotation.z = shiver;
            foliageObject.rotation.x = shiver * 0.5;
            return;
        }
    }

    // @perf-migrate {target: "cpp", reason: "hot-loop", threshold: "1-2ms"}
    // Migrated to C++: batchShiver_c() in emscripten/animation_batch.cpp
    if (type === 'shiver') {
        const shiver = Math.sin(animTime * 20 + offset) * 0.05 * intensity;
        foliageObject.rotation.z = shiver;
        foliageObject.rotation.x = shiver * 0.5;
    }
    // @perf-migrate {target: "cpp", reason: "hot-loop", threshold: "1-2ms"}
    // Migrated to C++: batchSpring_c() in emscripten/animation_batch.cpp
    else if (type === 'spring') {
        const springTime = animTime * 5 + offset;
        foliageObject.scale.y = 1.0 + Math.sin(springTime) * 0.1 * intensity;
        foliageObject.scale.x = 1.0 - Math.sin(springTime) * 0.05 * intensity;
        foliageObject.scale.z = 1.0 - Math.sin(springTime) * 0.05 * intensity;
    }
    else if (type === 'vineSway') {
        foliageObject.rotation.z = Math.sin(time * 1.5 + offset) * 0.2 * intensity;
        foliageObject.rotation.x = Math.cos(time * 1.2 + offset) * 0.1 * intensity;
    }
    // @perf-migrate {target: "cpp", reason: "hot-loop", threshold: "1-2ms"}
    // Migrated to C++: batchFloat_c() in emscripten/animation_batch.cpp
    else if (type === 'float') {
        const y = foliageObject.userData.originalY ?? foliageObject.position.y;
        foliageObject.userData.originalY = y;
        foliageObject.position.y = y + Math.sin(time * 2 + offset) * 0.5 * intensity;
    }
    else if (type === 'spin') {
        foliageObject.rotation.y += 0.01 * intensity;
    }
    else if (type === 'glowPulse') {
        const y = foliageObject.userData.originalY ?? foliageObject.position.y;
        foliageObject.userData.originalY = y;
        foliageObject.position.y = y + Math.sin(time * 2 + offset) * 0.1;
    }
    else if (type === 'rain') {
        let rainChild: THREE.Points | null = null;
        for (let i = 0; i < foliageObject.children.length; i++) {
            if (foliageObject.children[i].type === 'Points') {
                rainChild = foliageObject.children[i] as THREE.Points;
                break;
            }
        }
        if (rainChild && rainChild.geometry && rainChild.geometry.attributes.position) {
            const positions = rainChild.geometry.attributes.position.array as Float32Array;
            for (let i = 0; i < positions.length; i += 3) {
                positions[i + 1] -= 0.1;
                if (positions[i + 1] < -6) positions[i + 1] = 0;
            }
            rainChild.geometry.attributes.position.needsUpdate = true;
        }
        const y = foliageObject.userData.originalY ?? foliageObject.position.y;
        foliageObject.userData.originalY = y;
        foliageObject.position.y = y + Math.sin(time * 0.3 + offset) * 0.2;
    }
    // @perf-migrate {target: "cpp", reason: "hot-loop", threshold: "1-2ms"}
    // Migrated to C++: batchCloudBob_c() in emscripten/animation_batch.cpp
    else if (type === 'cloudBob') {
        const y = foliageObject.userData.originalY ?? foliageObject.position.y;
        foliageObject.userData.originalY = y;
        foliageObject.position.y = y + Math.sin(time * 0.5 + offset) * 0.3;
        foliageObject.rotation.y = Math.sin(time * 0.2 + offset * 0.5) * 0.05;
    }
    else if (type === 'geyserErupt') {
        const plume = foliageObject.userData.plume;
        const plumeLight = foliageObject.userData.plumeLight;
        const coreMat = foliageObject.userData.coreMaterial;
        const maxHeight = foliageObject.userData.maxHeight || 5.0;

        const kickThreshold = 0.3;
        let eruptionStrength = foliageObject.userData.eruptionStrength || 0;

        // Charge Logic (from Rainbow Blaster)
        const charge = foliageObject.userData.chargeLevel || 0;
        if (charge > 0) {
            foliageObject.userData.chargeLevel = Math.max(0, charge - 0.01);
        }
        const chargeBoost = 1.0 + charge; // Multiplier

        if (kick > kickThreshold) {
            eruptionStrength = Math.min(1.0, eruptionStrength + kick * 0.5 * chargeBoost);
        } else {
            eruptionStrength = Math.max(0, eruptionStrength - 0.03);
        }
        foliageObject.userData.eruptionStrength = eruptionStrength;

        if (plume) {
            if (plume) plume.visible = eruptionStrength > 0.05;

            // ⚡ OPTIMIZATION: Plume position logic replaced by TSL in environment.ts
            if (foliageObject.userData.uEruptionStrength) {
                foliageObject.userData.uEruptionStrength.value = eruptionStrength;
            }

            if ((plume.material as any).opacity !== undefined) {
                 (plume.material as any).opacity = 0.5 + eruptionStrength * 0.5;
            }
        }

        if (plumeLight) {
            plumeLight.intensity = eruptionStrength * 2.0;
            plumeLight.position.y = 1 + eruptionStrength * maxHeight * 0.3;
        }

        if (coreMat) {
            coreMat.emissiveIntensity = 0.3 + eruptionStrength * 1.5 + Math.sin(time * 20) * 0.2 * eruptionStrength;
        }
    }
    else if (type === 'retriggerPulse') {
        // Retrigger Mushroom Animation - creates stutter/glitch visual effects
        const cap = foliageObject.userData.cap;
        const capMat = foliageObject.userData.capMaterial;
        const rings = foliageObject.userData.rings;
        const particles = foliageObject.userData.particles;
        const light = foliageObject.userData.light;
        const stemHeight = foliageObject.userData.stemHeight || 0.4;
        const retriggerSpeed = foliageObject.userData.retriggerSpeed || 4;

        // Trigger retrigger effect on kick (bass hits)
        const kickThreshold = 0.25;
        let retriggerIntensity = foliageObject.userData.retriggerIntensity || 0;

        if (kick > kickThreshold) {
            retriggerIntensity = Math.min(1.0, retriggerIntensity + kick * 0.8);
            foliageObject.userData.retriggerActive = true;

            // Trigger callback if set (for audio system integration)
            if (foliageObject.userData.onRetrigger && retriggerIntensity > 0.5) {
                foliageObject.userData.onRetrigger(retriggerSpeed, retriggerIntensity);
            }
        } else {
            retriggerIntensity = Math.max(0, retriggerIntensity - 0.05);
            if (retriggerIntensity < 0.1) {
                foliageObject.userData.retriggerActive = false;
            }
        }
        foliageObject.userData.retriggerIntensity = retriggerIntensity;

        // Retrigger phase (creates the "stutter" timing)
        const phase = (time * retriggerSpeed * 10) % 1.0;
        foliageObject.userData.retriggerPhase = phase;

        // Cap animation - quick scale pulses during retrigger
        if (cap && retriggerIntensity > 0) {
            const stutterPulse = phase < 0.5 ? 1.0 : 0.8;
            const scaleMultiplier = 1.0 + (stutterPulse - 1.0) * retriggerIntensity * 0.3;
            cap.scale.setScalar(scaleMultiplier);
        } else if (cap) {
            cap.scale.setScalar(1.0);
        }

        // Ring animation - sequential flashes
        if (rings && rings.length > 0) {
            for (let i = 0; i < rings.length; i++) {
                const ring = rings[i];
                const ringPhase = (phase + (i / rings.length)) % 1.0;
                const ringActive = ringPhase < 0.3 && retriggerIntensity > 0.2;

                // Vertical jitter
                const baseY = ring.userData.baseY || stemHeight;
                ring.position.y = baseY + (ringActive ? 0.02 * retriggerIntensity : 0);

                // Material intensity
                if (ring.material && ring.material.emissiveIntensity !== undefined) {
                    ring.material.emissiveIntensity = ringActive ? 0.8 * retriggerIntensity : 0.1;
                }
            }
        }

        // Particles - visible and jittering during retrigger
        if (particles) {
            if (particles) particles.visible = retriggerIntensity > 0.3;

            if (particles.visible && particles.geometry.attributes.position) {
                const positions = particles.geometry.attributes.position.array as Float32Array;
                for (let i = 0; i < positions.length / 3; i++) {
                    // Random jitter based on retrigger phase
                    if (phase < 0.2) {
                        positions[i * 3] += (Math.random() - 0.5) * 0.02 * retriggerIntensity;
                        positions[i * 3 + 2] += (Math.random() - 0.5) * 0.02 * retriggerIntensity;
                    }
                }
                particles.geometry.attributes.position.needsUpdate = true;
            }

            if (particles.material && (particles.material as any).opacity !== undefined) {
                (particles.material as any).opacity = 0.3 + retriggerIntensity * 0.5;
            }
        }

        // Light - flashes with retrigger
        if (light) {
            const lightPulse = phase < 0.3 ? 1.0 : 0.2;
            light.intensity = lightPulse * retriggerIntensity * 1.5;
        }

        // Cap material glow
        if (capMat && capMat.emissiveIntensity !== undefined) {
            capMat.emissiveIntensity = 0.2 + retriggerIntensity * 0.8 * (phase < 0.3 ? 1.0 : 0.5);
        }

        // Subtle wobble
        foliageObject.rotation.z = Math.sin(time * 3 + offset) * 0.02 * (1 + retriggerIntensity);
    }
    else if (type === 'instrumentShrine') {
        // --- Instrument Shrine Logic ---
        const targetID = foliageObject.userData.instrumentID;
        const orb = foliageObject.userData.orb;
        const orbMat = foliageObject.userData.orbMat;
        const isSolved = foliageObject.userData.isSolved;

        let isActive = false;
        let matchedVolume = 0;

        // Check audio channels for matching instrument
        if (audioData && audioData.channelData) {
            // Bassline is typically on channel 1 in our 4-channel MODs (0=Drums, 1=Bass, 2=Melody, 3=Chords)
            // We check channel 1 specifically to match the "bassline instrument IDs" puzzle requirement.
            const bassChannel = audioData.channelData[1];
            if (bassChannel && bassChannel.instrument === targetID && (bassChannel.volume || 0) > 0.05) {
                isActive = true;
                matchedVolume = bassChannel.volume || 0;
            }
        }

        // Update State
        foliageObject.userData.isActive = isActive;

        // Update Text
        if (!isSolved) {
            if (isActive) {
                foliageObject.userData.interactionText = "Activate Shrine";
            } else {
                // Reset text if it was previously active but the bassline stopped
                foliageObject.userData.interactionText = `Tune Shrine (Current: ${targetID})`;
            }
        } else {
             foliageObject.userData.interactionText = "Shrine Activated";
        }

        // Animation
        const baseY = foliageObject.userData.originalY ?? foliageObject.position.y;
        foliageObject.userData.originalY = baseY;

        if (isSolved) {
            // Solved: Steady, glorious float
            foliageObject.position.y = baseY + Math.sin(time * 1.0 + offset) * 0.2;
            foliageObject.rotation.y += 0.01; // Slow spin

            // Orb: Gold Pulse
            if (orb) {
                 orb.position.y = 3.5 + Math.sin(time * 2.0) * 0.5;
                 orb.scale.setScalar(0.8);
            }
            if (orbMat) {
                orbMat.emissiveIntensity = 2.0 + Math.sin(time * 3.0) * 0.5;
                // Color set to Gold in onInteract
            }
        } else if (isActive) {
            // Active: Excited, fast float/pulse
            foliageObject.position.y = baseY + Math.sin(time * 5.0) * 0.5; // Fast bob
            foliageObject.rotation.y += 0.05 + matchedVolume * 0.1; // Fast spin

            if (orb) {
                orb.scale.setScalar(0.5 + Math.sin(time * 10.0) * 0.2);
            }
            if (orbMat) {
                orbMat.emissiveIntensity = 1.0 + matchedVolume * 2.0; // Bright flash
                // Color white/default
                orbMat.emissive.setHex(0xFFFFFF);
            }
        } else {
            // Dormant: Slow float
            foliageObject.position.y = baseY + Math.sin(time * 0.5 + offset) * 0.1;
            foliageObject.rotation.y = Math.sin(time * 0.2 + offset) * 0.1; // Gentle sway

            if (orb) {
                orb.scale.setScalar(0.5);
            }
            if (orbMat) {
                orbMat.emissiveIntensity = 0.2;
                orbMat.emissive.setHex(0x444444); // Dim
            }
        }
    }
}

import * as THREE from 'three';
