} from './index.ts';
import { PlantPoseMachine } from './plant-pose-machine.ts';

const MAX_FERNS = getCIAdjustedCount(500, 0.1, 50); // Reduced from 2000 for WebGPU uniform buffer limits
const FRONDS_PER_FERN = 5;
const _scratchMatrix = new THREE.Matrix4();
const _scratchQuaternion = new THREE.Quaternion();

export class ArpeggioFernBatcher {
    initialized: boolean;
    count: number;
    logicFerns: any[];

    private static _debugLogged = false;

    // GPU Buffers
    mesh: THREE.InstancedMesh | null; // Merged mesh

    // Scratch
    _color: THREE.Color;

    // GLOBAL TSL Uniform
    public globalUnfurl: number = 0;
    public uFernUnfurl: any;

    // Global Logic State
    private currentTargetStep: number = 0;
    private currentUnfurlValue: number = 0;
    private lastTrigger: boolean = false;

    // Matrix/color batching state (SoA → native or TS writeInstancePose)
    private _matricesDirty: boolean = false;
    private _batchPositions: Float32Array;
    private _batchQuaternions: Float32Array;
    private _batchScales: Float32Array;
    private _batchColors: Float32Array;

    /**
     * Day/night pose state machine — single slot (global unfurl for all ferns).
     * Uses a Float32Array of capacity 1; no per-frame allocations.
     */
    private _poseMachine!: PlantPoseMachine;

    constructor() {
        this.initialized = false;
        this.count = 0;
        this.logicFerns = [];

        this.mesh = null;

        this._color = new THREE.Color();

        // Initialize global uniform
        this.uFernUnfurl = uniform(float(0.0));

        // C++ / TS batching SoA buffers (#1358 writeInstancePose)
        this._batchPositions = new Float32Array(MAX_FERNS * 3);
        this._batchQuaternions = new Float32Array(MAX_FERNS * 4);
        this._batchScales = new Float32Array(MAX_FERNS * 3);
        this._batchColors = new Float32Array(MAX_FERNS * 3);
    }

    init() {
        if (this.initialized) return;

        // Single-slot pose machine for global fern unfurl (capacity=1, no per-frame alloc)
        this._poseMachine = new PlantPoseMachine(1);

        // --- Geometry Preparation ---

        // 1. Frond Geometry (Base Scale 1.0)
        const frondHeight = 2.3;
        const frondGeo = new THREE.BoxGeometry(0.1, frondHeight, 0.02, 1, 16, 1);
        frondGeo.translate(0, frondHeight / 2, 0); // Pivot at bottom

        // 2. Base Geometry
        const baseGeo = new THREE.ConeGeometry(0.2, 0.5, 6);
        baseGeo.translate(0, 0.25, 0);

        const geometriesToMerge: THREE.BufferGeometry[] = [];

        // --- BASE SETUP ---
        // Base is at (0,0,0) locally, no rotation
        // Attributes: aIsFrond=0, aFrondAngle=0, aFrondTilt=0
        const baseCount = baseGeo.attributes.position.count;
        const baseIsFrond = new Float32Array(baseCount).fill(0);
        const baseAngle = new Float32Array(baseCount).fill(0);
        const baseTilt = new Float32Array(baseCount).fill(0);

        baseGeo.setAttribute('aIsFrond', new THREE.BufferAttribute(baseIsFrond, 1));
        baseGeo.setAttribute('aFrondAngle', new THREE.BufferAttribute(baseAngle, 1));
        baseGeo.setAttribute('aFrondTilt', new THREE.BufferAttribute(baseTilt, 1));

        geometriesToMerge.push(baseGeo);

        // --- FROND SETUP (5 copies) ---
        const frondYOffset = 0.4; // From original code logic
        const tiltAngle = 0.2; // From original code logic

        for (let f = 0; f < FRONDS_PER_FERN; f++) {
            const angle = (f / FRONDS_PER_FERN) * Math.PI * 2;
            const geo = frondGeo.clone();

            // Apply transformations that define the frond's rest position relative to the fern center
            // 1. Tilt (Rotate X)
            geo.rotateX(tiltAngle);
            // 2. Fan (Rotate Y)
            geo.rotateY(angle);
            // 3. Lift (Translate Y)
            geo.translate(0, frondYOffset, 0);

            // Attributes
            const count = geo.attributes.position.count;
            const isFrond = new Float32Array(count).fill(1.0);
            const frondAngle = new Float32Array(count).fill(angle);
            const frondTilt = new Float32Array(count).fill(tiltAngle);

            geo.setAttribute('aIsFrond', new THREE.BufferAttribute(isFrond, 1));
            geo.setAttribute('aFrondAngle', new THREE.BufferAttribute(frondAngle, 1));
            geo.setAttribute('aFrondTilt', new THREE.BufferAttribute(frondTilt, 1));

            geometriesToMerge.push(geo);
        }

        // Merge Everything
        const mergedGeo = mergeGeometries(geometriesToMerge);

        // --- MATERIAL SETUP ---

        // 1. Base Properties (Mixed based on aIsFrond)
        const isFrondAttr = attribute('aIsFrond', 'float');

        // Base: 0x2E8B57, Rough 0.8, Metal 0.0
        // Frond: 0x00FF88, Rough 0.6, Metal 0.1
        // Frond accent (hue-shifted purple-violet — blended in by uHueShift)
        const baseColor = color(0x2E8B57);
        const frondColor = color(0x00FF88);
        const frondAccentColor = color(0x8844FF); // Purple-violet accent for hue shift
        // Arpeggio Grove hue shift: mix frond colour towards accent based on uHueShift channel
        const dynamicFrondColor = mix(frondColor, frondAccentColor, arpeggioUniforms.hueShift);
        const mixedColor = mix(baseColor, dynamicFrondColor, isFrondAttr);

        const mixedRough = mix(float(0.8), float(0.6), isFrondAttr);
        const mixedMetal = mix(float(0.0), float(0.1), isFrondAttr);

        const material = createStandardNodeMaterial({
            color: 0xFFFFFF, // Overridden by node
            roughness: 1.0,
            metalness: 0.0
        });
        registerReactiveMaterial(material);

        // Lightweight debug indicator for biome tagging / music reactivity system
        if (!ArpeggioFernBatcher._debugLogged && CONFIG.debugNoteReactivity) {
            console.log('[Biome] ArpeggioFernBatcher using biome=', ARPEGGIO_BIOME, 'via getBiomeUniforms()');
            ArpeggioFernBatcher._debugLogged = true;
        }

        material.colorNode = mixedColor; // Will be multiplied by instanceColor in fragment logic?
        // Actually, createStandardNodeMaterial usually sets basic properties.
        // We override them here.
        material.roughnessNode = mixedRough;
        material.metalnessNode = mixedMetal;

        // --- VERTEX LOGIC (CURL) ---

        const frondAngle = attribute('aFrondAngle', 'float');
        const frondTilt = attribute('aFrondTilt', 'float'); // 0.2
        const pos = positionLocal; // Vertex Position in Fern Local Space

        // We need to un-rotate the vertex to apply the curl in canonical space (Z-aligned)
        // Inverse of: Translate(0, 0.4, 0) -> RotateY(angle) -> RotateX(tilt)
        // Wait, matrix multiplication order is Translate * RotateY * RotateX * v
        // So v_world = T * Ry * Rx * v_local
        // To unwind: v_local = Rx' * Ry' * T' * v_world
        // But we baked T * Ry * Rx into the geometry.
        // So 'pos' is v_world (relative to fern center).

        // Step 1: Untranslate Y
        const p1 = vec3(pos.x, pos.y.sub(float(frondYOffset)), pos.z);

        // Step 2: Unrotate Y (angle)
        // x' = x*cos(-a) - z*sin(-a)
        // z' = x*sin(-a) + z*cos(-a)
        const cY = cos(frondAngle.negate());
        const sY = sin(frondAngle.negate());
        const p2 = vec3(
            p1.x.mul(cY).sub(p1.z.mul(sY)),
            p1.y,
            p1.x.mul(sY).add(p1.z.mul(cY))
        );

        // Step 3: Unrotate X (tilt)
        // y' = y*cos(-t) - z*sin(-t)
        // z' = y*sin(-t) + z*cos(-t)
        const cX = cos(frondTilt.negate());
        const sX = sin(frondTilt.negate());
        const p3 = vec3(
            p2.x,
            p2.y.mul(cX).sub(p2.z.mul(sX)),
            p2.y.mul(sX).add(p2.z.mul(cX))
        );

        // p3 is now in "Canonical Frond Space" (Vertical along Y, facing Z?)
        // Frond geometry was: Box(..., height=2.3). Translated(0, 1.15, 0).
        // So p3.y is 0..2.3. p3.z is thickness. p3.x is width.

        // --- APPLY CURL LOGIC ---
        // Logic from original code, adapted for p3
        const baseUnfurl = this.uFernUnfurl;
        const spatialDelay = sin(positionWorld.x.mul(0.5).add(positionWorld.z.mul(0.3))).mul(0.1);
        const instanceUnfurl = baseUnfurl.add(spatialDelay).clamp(0.0, 1.0);

        const yNorm = p3.y.div(float(frondHeight));

        const maxCurl = float(-4.0);
        const minCurl = float(-0.2);
        const currentTotalCurl = mix(maxCurl, minCurl, instanceUnfurl);

        const theta = currentTotalCurl.mul(yNorm);
        const wavePhase = uTime.mul(5.0).add(yNorm.mul(4.0));
        const wave = sin(wavePhase).mul(0.1).mul(instanceUnfurl).mul(yNorm);

        const finalAngle = theta.add(wave);

        const cCurl = cos(finalAngle);
        const sCurl = sin(finalAngle);

        // Curl around X axis (modifying Y and Z)
        // y' = y*cos - z*sin
        // z' = y*sin + z*cos
        const curledY = p3.y.mul(cCurl).sub(p3.z.mul(sCurl));
        const curledZ = p3.y.mul(sCurl).add(p3.z.mul(cCurl));

        const pCurled = vec3(p3.x, curledY, curledZ);

        // --- RE-WIND ROTATION ---
        // Inverse of Step 3 (Rotate X)
        const cX2 = cos(frondTilt);
        const sX2 = sin(frondTilt);
        const p4 = vec3(
            pCurled.x,
            pCurled.y.mul(cX2).sub(pCurled.z.mul(sX2)),
            pCurled.y.mul(sX2).add(pCurled.z.mul(cX2))
        );

        // Inverse of Step 2 (Rotate Y)
        const cY2 = cos(frondAngle);
        const sY2 = sin(frondAngle);
        const p5 = vec3(
            p4.x.mul(cY2).sub(p4.z.mul(sY2)),
            p4.y,
            p4.x.mul(sY2).add(p4.z.mul(cY2))
        );

        // Inverse of Step 1 (Translate Y)
        const pFinalFrond = vec3(p5.x, p5.y.add(float(frondYOffset)), p5.z);

        // --- COMBINE WITH BASE ---
        // If it's a base vertex, use original position. If frond, use curled.
        const combinedPos = mix(pos, pFinalFrond, isFrondAttr);

        // --- JUICE (Audio, Interaction, Wind) ---
        // Audio Pulse (Scale width/thickness with High Freq)
        const audioScale = uAudioHigh.mul(0.3).add(1.0);
        // Apply audio scale only to fronds? Or both?
        // Original code applied to fronds only.
        const pulsedPos = mix(
            combinedPos,
            vec3(combinedPos.x.mul(audioScale), combinedPos.y, combinedPos.z.mul(audioScale)),
            isFrondAttr
        );

        // Interaction (Bending)
        const withWind = applyStandardDeformation(pulsedPos);

        // Bobbing (Unfurl bounce)
        const bob = instanceUnfurl.mul(0.2);
        const finalPos = withWind.add(vec3(0, bob, 0));

        const glitched = applyGlitch(uv(), finalPos, uGlitchIntensity as unknown as import('three/src/nodes/tsl/TSLCore.js').ShaderNodeObject<import('three/webgpu').Node>);
        material.positionNode = glitched.position;

        // Fragment Shader: Instance Color Tint + Rim Light
        const baseInstanceColor = varyingProperty('vec3', 'vInstanceColor');
        // Mix instance color into base color, then apply distance-driven aerial perspective
        material.colorNode = applyBaseContactAO(
            applyAerialPerspective(
                mixedColor.mul(baseInstanceColor),
                positionWorld,
            ),
            positionLocal.y,
            float(getBaseContactHeight('arpeggio_fern')),
        );

        // Juicy Rim Light
        const rim = createJuicyRimLight(baseInstanceColor, float(2.0), float(3.0), null);
        const audioEmissive = uAudioHigh.mul(0.5);
        // Arpeggio Grove shimmer: soft teal sparkle driven by melody channels
        const shimmerColor = color(0x88FFCC);
        const shimmerGlow = arpeggioUniforms.shimmer.mul(shimmerColor).mul(3.0);
        material.emissiveNode = rim.add(baseInstanceColor.mul(audioEmissive)).add(shimmerGlow);

        // --- INSTANCED MESH ---
        this.mesh = new THREE.InstancedMesh(mergedGeo, material, MAX_FERNS);
        this.mesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(MAX_FERNS * 3), 3);
        this.mesh.geometry.setAttribute('instanceColor', this.mesh.instanceColor);
        this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.mesh.castShadow = true;
        this.mesh.receiveShadow = true;
        this.mesh.frustumCulled = false;
        this.mesh.count = 0;

        foliageGroup.add(this.mesh);

        this.initialized = true;
        console.log(`[ArpeggioBatcher] Initialized unified mesh system (Cap: ${MAX_FERNS})`);
    }

    dispose() {
        if (!this.initialized) return;

        if (this.mesh) {
            safeRemoveAndDispose(foliageGroup as unknown as THREE.Scene, this.mesh);
        }

        this.initialized = false;
        this.count = 0;

        this._batchPositions.fill(0);
        this._batchScales.fill(0);
    }

    register(dummy: any, options: any = {}) {
        if (!this.initialized) this.init();
        if (this.count >= MAX_FERNS) {
            console.warn('[ArpeggioBatcher] Max limit reached');
            return;
        }

        const { color = 0x00FF88, scale = 1.0 } = options;
        const i = this.count;
        this.count++;

        // Store reference
        dummy.userData.batchIndex = i;
        dummy.userData.unfurlFactor = 0;
        this.logicFerns.push(dummy);

        // Setup Instance (Only ONE matrix per fern now!)
        // No extra Y offset needed, baked into geometry logic relative to pivot
        // Base was offset 0.25, Frond 0.4.
        // But original register() added 0.25 * scale to base, and 0.4 * scale to frond.
        // Wait, scale applies to the whole object.
        // If we scale the object, offsets scale too.
        // We should just set the matrix.
        // But the geometry assumes a specific pivot?
        // Base geometry was translated (0, 0.25, 0). So pivot is at 0.
        // Frond geometry was translated (0, 0.4, 0) relative to base?
        // In original register():
        // Base: pos.y += 0.25 * scale
        // Frond: pos.y += 0.4 * scale
        // This implies the pivot of the *Instance* is at y=0, but the parts are lifted.
        // If I bake the lift (0.25 and 0.4) into the geometry, I don't need to add it to the matrix position.
        // BUT, I merged Base (y+0.25) and Frond (y+0.4).
        // So the merged geometry has its bottom at y=0 (actually base starts at 0, cone height 0.5 centered at 0.25).
        // So yes, pivot is at bottom.

        // ⚡ OPTIMIZATION: Queue properties for batch C++ matrix composition rather than doing it immediately
        dummy.scale.setScalar(scale);
        getGroundAlignedQuaternion(dummy, _scratchQuaternion);

        // Write to SoA buffers for WASM payload
        this._batchPositions[i * 3 + 0] = dummy.position.x;
        this._batchPositions[i * 3 + 1] = dummy.position.y;
        this._batchPositions[i * 3 + 2] = dummy.position.z;

        this._batchQuaternions[i * 4 + 0] = _scratchQuaternion.x;
        this._batchQuaternions[i * 4 + 1] = _scratchQuaternion.y;
        this._batchQuaternions[i * 4 + 2] = _scratchQuaternion.z;
        this._batchQuaternions[i * 4 + 3] = _scratchQuaternion.w;

        this._batchScales[i * 3 + 0] = dummy.scale.x;
        this._batchScales[i * 3 + 1] = dummy.scale.y;
        this._batchScales[i * 3 + 2] = dummy.scale.z;

        // Color → SoA (flushed with matrices via writeInstancePose)
        this._color.setHex(color);
        this._batchColors[i * 3 + 0] = this._color.r;
        this._batchColors[i * 3 + 1] = this._color.g;
        this._batchColors[i * 3 + 2] = this._color.b;

        this._matricesDirty = true;
        this.flushMatrices(); // immediate matrix+color write (native or TS)

        // Update count
        this.mesh!.count = this.count;
    }

    updateInstance(index: number, dummy: any) {
        if (!this.initialized || index < 0 || index >= this.count) return;

        getGroundAlignedQuaternion(dummy, _scratchQuaternion);

        // Write to SoA buffers for WASM payload
        this._batchPositions[index * 3 + 0] = dummy.position.x;
        this._batchPositions[index * 3 + 1] = dummy.position.y;
        this._batchPositions[index * 3 + 2] = dummy.position.z;

        this._batchQuaternions[index * 4 + 0] = _scratchQuaternion.x;
        this._batchQuaternions[index * 4 + 1] = _scratchQuaternion.y;
        this._batchQuaternions[index * 4 + 2] = _scratchQuaternion.z;
        this._batchQuaternions[index * 4 + 3] = _scratchQuaternion.w;

        this._batchScales[index * 3 + 0] = dummy.scale.x;
        this._batchScales[index * 3 + 1] = dummy.scale.y;
        this._batchScales[index * 3 + 2] = dummy.scale.z;

        this._matricesDirty = true;
    }

    /**
     * Flush packed pose SoA into InstancedMesh matrix + color buffers.
     * Native path: batchWriteInstancePose_c when candy_native is ready;
     * otherwise allocation-free TS fallback (PlantPoseMachine stays in TS).
     */
    private flushMatrices() {
        if (!this._matricesDirty || !this.mesh || this.count === 0) return;

        const matrixArray = this.mesh.instanceMatrix.array as Float32Array;
        const colorArray = this.mesh.instanceColor
            ? (this.mesh.instanceColor.array as Float32Array)
            : null;

        writeInstancePose(
            this._batchPositions,
            this._batchQuaternions,
            this._batchScales,
            this._batchColors,
            matrixArray,
            colorArray,
            1.0,
            this.count
        );

        this.mesh.instanceMatrix.needsUpdate = true;
        if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
        this._matricesDirty = false;
    }

    update(audioState: any = null, dayNightBias: number = 1.0) {
        if (!this.initialized || this.count === 0) return;

        this.flushMatrices();

        // --- Arpeggio detection (unchanged) ---
        let arpeggioActive = false;
        let noteTrigger = false;
        if (audioState && audioState.channelData) {
            for (const ch of audioState.channelData) {
                if (ch.activeEffect === 4 || (ch.activeEffect === 0 && ch.effectValue && ch.effectValue > 0)) {
                    arpeggioActive = true;
                }
                if (ch.trigger > 0.1) {
                    noteTrigger = true;
                }
            }
        }

        const maxSteps = 12;
        let nextTarget = this.currentTargetStep;

        if (arpeggioActive) {
            if (noteTrigger && !this.lastTrigger) {
                nextTarget += 1;
                if (nextTarget > maxSteps) nextTarget = maxSteps;
            }
        } else {
            nextTarget = 0;
        }

        this.currentTargetStep = nextTarget;
        this.lastTrigger = noteTrigger;

        const speed = (nextTarget > this.currentUnfurlValue) ? 0.3 : 0.05;
        this.currentUnfurlValue += (nextTarget - this.currentUnfurlValue) * speed;

        // --- Day/night ADSR envelope (pose machine) ---
        // Channel intensity: 1.0 when arpeggio is active, 0.0 otherwise.
        const channelIntensity = arpeggioActive ? 1.0 : 0.0;
        const poseConfig = CONFIG.plantPose.arpeggioFern;

        // Fixed dt (60 Hz assumption) keeps parity with portamento batcher convention.
        const activeWave = getActiveWave();
        const cameraPos = camera ? camera.position : undefined;

        const getPlantPos = (index: number, out: THREE.Vector3) => {
            if (!this.mesh) return;
            const array = this.mesh.instanceMatrix.array as Float32Array;
            const offset = index * 16;
            out.set(array[offset + 12], array[offset + 13], array[offset + 14]);
        };

        this._poseMachine.update(1, 0.016, channelIntensity, dayNightBias, poseConfig, activeWave, getPlantPos, cameraPos);

        // Day/night baseline from pose machine (0 = night-closed, up to nightTarget/dayTarget).
        // Blends a gentle partial-open bias from daylight into the step-driven unfurl.
        const dnBaseline = this._poseMachine.getPose(0);

        // Final unfurl: day/night baseline + step-driven contribution in the remaining range.
        const stepUnfurl = this.currentUnfurlValue / maxSteps;
        const unfurl = dnBaseline + stepUnfurl * (1.0 - dnBaseline);

        this.globalUnfurl = unfurl;
        this.uFernUnfurl.value = unfurl;

        // ⚡ OPTIMIZATION: Zero-Allocation WASM Physics Sync
        // Write the expanded radius directly into the WASM memory view
        if (dynamicRadiiView) {
            // Base radius is ~2.0 when closed, expands to ~8.0 when unfurled
            const activeRadius = 2.0 + (unfurl * 6.0);
            for (let i = 0; i < this.count; i++) {
                // scale.x applies uniformly, so multiply by scale
                dynamicRadiiView[i] = activeRadius * this.logicFerns[i].scale.x;
            }
        }
    }
}

export const arpeggioFernBatcher = new ArpeggioFernBatcher();

import * as THREE from 'three';
import { calcArpeggioStep } from '../utils/wasm-loader.ts';
import { FoliageObject, AudioData } from './types.ts';

export function updateArpeggio(foliageObject: FoliageObject, time: number, audioData: AudioData | null) {
    // Step-based unfurling logic (Revised for Quantized Steps with Rising Edge)
    let arpeggioActive = false;
    let noteTrigger = false;

    // Scan for arpeggio effect
    if (audioData && audioData.channelData) {
        for (const ch of audioData.channelData) {
            if (ch.activeEffect === 4 || (ch.activeEffect === 0 && ch.effectValue && ch.effectValue > 0)) {
                arpeggioActive = true;
            }
            if (ch.trigger > 0.1) {
                noteTrigger = true;
            }
        }
    }

    // State initialization
    if (foliageObject.userData.unfurlStep === undefined) foliageObject.userData.unfurlStep = 0;
    if (foliageObject.userData.targetStep === undefined) foliageObject.userData.targetStep = 0;
    if (foliageObject.userData.lastTrigger === undefined) foliageObject.userData.lastTrigger = false;

    const maxSteps = 12;

    // --- WASM Acceleration ---
    // Offload the state machine and lerp logic to AssemblyScript
    const result = calcArpeggioStep(
        foliageObject.userData.unfurlStep,
        foliageObject.userData.targetStep,
        foliageObject.userData.lastTrigger,
        arpeggioActive,
        noteTrigger,
        maxSteps
    );

    foliageObject.userData.targetStep = result.targetStep;
    foliageObject.userData.unfurlStep = result.unfurlStep;

    // Update trigger state for next frame
    foliageObject.userData.lastTrigger = noteTrigger;

    const unfurlFactor = (foliageObject.userData.unfurlStep || 0) / maxSteps;

    // Update state for Batcher
    foliageObject.userData.unfurlFactor = unfurlFactor;

    // ⚡ OPTIMIZATION: Update TSL Uniform instead of traversing mesh hierarchy
    // This replaces 200+ draw calls and Matrix updates per fern with a single uniform update.
    if (foliageObject.userData.uUnfurl) {
        foliageObject.userData.uUnfurl.value = unfurlFactor;
    } else {
        // Fallback for legacy objects (if any)
        const fronds = foliageObject.userData.fronds;
        if (fronds) {
            for (let fIdx = 0; fIdx < fronds.length; fIdx++) {
                const segments: any = fronds[fIdx];
                for (let sIdx = 0; sIdx < segments.length; sIdx++) {
                    const segData: any = segments[sIdx];
                    const targetRot = THREE.MathUtils.lerp(segData.initialCurl, 0.2, unfurlFactor);
                    const wave = Math.sin(time * 5 + sIdx * 0.5) * 0.1 * unfurlFactor;
                    segData.pivot.rotation.x = targetRot + wave;
                }
            }
        }
    }

    // Bob base slightly
    if (foliageObject.userData.originalY === undefined) {
        foliageObject.userData.originalY = foliageObject.position.y;
    }
    foliageObject.position.y = foliageObject.userData.originalY + unfurlFactor * 0.2;
}

// src/foliage/aurora.ts

import * as THREE from 'three';
import { color, float, vec3, vec4, uv, mix, smoothstep, uniform, Fn, time, mx_noise_float, positionWorld, positionLocal, dot, sin, cos, storage, instanceIndex, vec2, If } from 'three/tsl';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, StorageInstancedBufferAttribute } from 'three/webgpu';
import { getCIAdjustedCount } from '../core/config.ts';
import { getBiomeUniforms, type BiomeId } from '../systems/biome-uniforms.ts';
import { getSphereGeometry } from '../utils/geometry-dedup.ts';
import { uAudioLow, uAudioHigh, CandyPresets, uTime, createJuicyRimLight } from './index.ts';

// Global uniforms for Aurora control
export const uAuroraIntensity = uniform(0.0); // 0.0 to 1.0
export const uAuroraColor = uniform(color(0x00FF99)); // Base color (Greenish default)
export const uAuroraSpeed = uniform(0.2); // Speed of the wave movement

export function createAurora(): THREE.Mesh {
    // Create a tall cylinder for the aurora curtain
    // Radius ~800, Height ~500, High segment count for smooth waves
    const geometry = new THREE.CylinderGeometry(800, 800, 500, 128, 32, true);
    geometry.translate(0, 300, 0); // Lift it up into the sky

    // TSL Shader Logic
    const mainAurora = (Fn as any)(() => {
        const vUv = uv();

        // 1. Organic Curtain Movement (Noise-based)
        // Displace UVs with noise to create "folds"
        // Bass boosts speed slightly
        const timeScaled = time.mul(uAuroraSpeed.add(uAudioLow.mul(0.1)));

        // Large slow wave
        const noise1 = mx_noise_float(vec3(vUv.x.mul(5.0), timeScaled.mul(0.5), float(0.0)));
        // Smaller fast ripple
        const noise2 = mx_noise_float(vec3(vUv.x.mul(15.0).add(noise1), timeScaled.mul(1.5), float(0.0)));

        const distortedX = vUv.x.add(noise1.mul(0.2)).add(noise2.mul(0.1));

        // 2. Vertical Rays
        // High frequency noise for the "curtain rays"
        const rayNoise = mx_noise_float(vec3(distortedX.mul(30.0), float(0.0), float(0.0)));
        const rayIntensity = smoothstep(0.3, 0.7, rayNoise).mul(0.8).add(0.2);

        // 3. Audio Reactivity (Juice)
        // Bass pushes the curtain "up" (modulates vertical fade)
        const bassLift = uAudioLow.mul(0.2);

        // Treble adds "sparkle" or "shimmer" to the rays
        const shimmer = uAudioHigh.mul(mx_noise_float(vec3(vUv.x.mul(100.0), time.mul(5.0), vUv.y)));

        // 4. Vertical Fade (Soft top and bottom)
        const bottomFade = smoothstep(0.0, 0.3, vUv.y.add(bassLift));
        const topFade = float(1.0).sub(smoothstep(0.7, 1.0, vUv.y));
        const verticalFade = bottomFade.mul(topFade);

        // 5. Spectral Color Shift
        // Base color mixed with a "Magic" color (Purple/Pink) based on height and Audio
        const magicColor = color(0x9933FF);
        // More purple when bass hits or at top
        const colorMix = vUv.y.mul(0.5).add(uAudioLow.mul(0.4)).min(1.0);

        const finalColorRGB = mix(uAuroraColor, magicColor, colorMix).add(
            getBiomeUniforms('sky_moon').noteColor.mul(0.12)
        );

        // 6. Combine
        // Rays + Shimmer + Fade + Global Intensity
        const combinedIntensity = rayIntensity.add(shimmer).mul(verticalFade).mul(uAuroraIntensity);

        return vec4(finalColorRGB, combinedIntensity);
    });

    const material = new MeshBasicNodeMaterial();
    material.colorNode = mainAurora();
    material.transparent = true;
    material.blending = THREE.AdditiveBlending;
    material.side = THREE.DoubleSide;
    material.depthWrite = false;
    material.fog = false; // Aurora glows through fog

    const mesh = new THREE.Mesh(geometry, material);
    mesh.userData.type = 'aurora';
    mesh.frustumCulled = false; // Always visible in sky

    return mesh;
}


// --- HARMONY ORBS SYSTEM ---

const MAX_ORBS = getCIAdjustedCount(50, 0.2, 10);

interface HarmonyOrb {
    active: boolean;
    life: number;
    position: THREE.Vector3;
    velocity: THREE.Vector3;
    scale: number;
}

class HarmonyOrbSystem {
    mesh: THREE.InstancedMesh;
    dummy: THREE.Object3D;
    orbs: HarmonyOrb[];
    dropCooldown: number = 0;

    // WebGPU Compute specific
    positionBuffer: StorageInstancedBufferAttribute;
    velocityBuffer: StorageInstancedBufferAttribute;
    stateBuffer: StorageInstancedBufferAttribute; // x: life, y: scale (negative life = inactive)
    computeNode: any;

    // Uniforms for compute
    private uDeltaTime = uniform(0.016);
    private uOrbAudioSway = uniform(0.0);

    // Spawning Uniforms
    private uSpawnIndex = uniform(-1); // -1 means no spawn this frame
    private uSpawnPos = uniform(vec3(0));
    private uSpawnVel = uniform(vec3(0));

    // CPU-side tracking to prevent spawning over active orbs without reading back from GPU
    private _nextSpawnIndex: number = 0;

    constructor() {
        // High quality sphere for glossy look
        const geometry = getSphereGeometry(0.3, 32, 32);

        // Initialize CPU-side orb tracking
        this.dummy = new THREE.Object3D();
        this.orbs = [];
        for (let i = 0; i < MAX_ORBS; i++) {
            this.orbs.push({
                active: false,
                life: 0,
                position: new THREE.Vector3(0, -9999, 0),
                velocity: new THREE.Vector3(),
                scale: 0
            });
        }

        // 1. Initialize Storage Buffers (Empty arrays, initialized in compute)
        const initialPositions = new Float32Array(MAX_ORBS * 3);
        const initialVelocities = new Float32Array(MAX_ORBS * 3);
        const initialStates = new Float32Array(MAX_ORBS * 2);

        for (let i = 0; i < MAX_ORBS; i++) {
            initialStates[i * 2] = -1.0;     // Life
            initialStates[i * 2 + 1] = 0.0;  // Scale
            initialPositions[i * 3 + 1] = -9999.0;
        }

        this.positionBuffer = new StorageInstancedBufferAttribute(initialPositions, 3);
        this.velocityBuffer = new StorageInstancedBufferAttribute(initialVelocities, 3);
        this.stateBuffer = new StorageInstancedBufferAttribute(initialStates, 2);

        // CandyPresets.Gummy base
        const opts = {
            transmission: 0.8,
            thickness: 1.5,
            roughness: 0.1,
            ior: 1.5,
            subsurfaceStrength: 1.0,
            subsurfaceColor: 0x9933FF
        };
        const material = CandyPresets.Gummy(0x9933FF, opts);

        // TSL Logic for Audio-Reactive Pulse and Glow
        const baseColor = color(0x00FF99);
        const magicColor = color(0x9933FF);

        // Mix colors based on audio high
        const orbColor = mix(baseColor, magicColor, uAudioHigh.add(float(0.5)).min(1.0));

        // Emissive: Pulse with bass and rim light
        const phase = dot(positionWorld, vec3(0.5)).mul(5.0);
        const beatSpeed = float(8.0);
        const heartbeat = sin(uTime.mul(beatSpeed).add(phase)).pow(4.0);
        const glowIntensity = float(0.5).add(heartbeat.mul(uAudioLow));

        // Add rim light for juice
        const rim = createJuicyRimLight(orbColor, float(1.5), float(3.0), null);

        // Music Impact: subtle sky-moon noteColor tint on harmony orbs
        const skyMoonUniforms = getBiomeUniforms('sky_moon');
        const skyTint = skyMoonUniforms.noteColor.mul(skyMoonUniforms.shimmer).mul(0.25);
        material.emissiveNode = orbColor.mul(glowIntensity).add(rim).add(skyTint);

        // 2. Map Storage Buffers to Material
        const instIndex = instanceIndex;
        const stateNode = storage(this.stateBuffer, 'vec2', this.stateBuffer.count).element(instIndex);
        const positionNode = storage(this.positionBuffer, 'vec3', this.positionBuffer.count).element(instIndex);

        const orbScale = stateNode.y;

        // Vertex displacement (Squishy feel based on velocity/audio)
        // Scale with bass AND individual orb scale
        const scaleFactor = float(1.0).add(heartbeat.mul(uAudioLow).mul(0.3)).mul(orbScale);

        // Final position = (Local * Scale) + WorldPosition from Buffer
        material.positionNode = positionLocal.mul(scaleFactor).add(positionNode);

        this.mesh = new THREE.InstancedMesh(geometry, material, MAX_ORBS);
        this.mesh.castShadow = true;
        this.mesh.receiveShadow = false;

        // 3. Define TSL Compute Node for Physics/Lifecycle Updates
        const updateOrbsCompute: any = (Fn as any)(() => {
            const index = instanceIndex;

            const position = storage(this.positionBuffer, 'vec3', this.positionBuffer.count).element(index);
            const velocity = storage(this.velocityBuffer, 'vec3', this.velocityBuffer.count).element(index);
            const state = storage(this.stateBuffer, 'vec2', this.stateBuffer.count).element(index);

            const life = state.x;
            const currentScale = state.y;
            const pos = position.toVar();
            const vel = velocity.toVar();

            // Handle Spawning
            If(index.equal(this.uSpawnIndex), () => {
                state.x = float(20.0); // 20s life
                state.y = float(0.1);  // Initial scale
                position.assign(this.uSpawnPos);
                velocity.assign(this.uSpawnVel);
            }).ElseIf(life.greaterThan(0.0), () => {
                // Update active orbs
                // Decrease life
                state.x = life.sub(this.uDeltaTime);

                // Increase scale to max 1.0
                state.y = currentScale.add(this.uDeltaTime).min(1.0);

                // Physics: Gravity
                vel.y = vel.y.sub(float(9.8).mul(0.2).mul(this.uDeltaTime)); // Floaty gravity

                // Wind Sway (based on life/time)
                const swaySpeed = float(2.0);
                vel.x = vel.x.add(sin(life.mul(swaySpeed)).mul(2.0).mul(this.uDeltaTime));
                vel.z = vel.z.add(cos(life.mul(swaySpeed).mul(0.75)).mul(2.0).mul(this.uDeltaTime));

                // Terminal velocity for falling
                vel.y = vel.y.max(-5.0);

                // Audio Sway Reactivity
                vel.x = vel.x.add(this.uOrbAudioSway.mul(this.uDeltaTime));

                velocity.assign(vel);

                // Update Position
                position.assign(pos.add(vel.mul(this.uDeltaTime)));

                // Floor Collision -> Destroy
                // Note: We access the specific component of the vector since position.y isn't valid on a var in this TSL context
                const posY = pos.add(vel.mul(this.uDeltaTime)).y;
                If(posY.lessThan(-5.0), () => {
                     state.x = float(-1.0); // Kill
                     // Assign new hidden position
                     position.assign(vec3(pos.x, float(-9999.0), pos.z));
                });
            });
        });

        this.computeNode = (updateOrbsCompute() as any).compute(MAX_ORBS);
    }

    addToScene(scene: THREE.Scene) {
        scene.add(this.mesh);
    }

    spawnOrb(playerPos: THREE.Vector3) {
        // Use ring-buffer approach for spawning to avoid reading back from GPU
        // Assuming orbs live ~20s, pool of 50 should be plenty
        const idx = this._nextSpawnIndex;
        this._nextSpawnIndex = (this._nextSpawnIndex + 1) % MAX_ORBS;

        const spawnRadius = 30.0;
        (this.uSpawnPos.value as any).set(
            playerPos.x + (Math.random() - 0.5) * spawnRadius,
            200.0 + Math.random() * 50.0,
            playerPos.z + (Math.random() - 0.5) * spawnRadius
        );

        (this.uSpawnVel.value as any).set(
            (Math.random() - 0.5) * 5.0,
            -10.0,
            (Math.random() - 0.5) * 5.0
        );

        this.uSpawnIndex.value = idx;
    }

    update(dt: number, audioState: any, playerPos: THREE.Vector3) {
        // Reset spawn index at start of frame
        // If spawnOrb is called this frame, it will be overridden with the new index
        this.uSpawnIndex.value = -1;
        this.uDeltaTime.value = dt;

        let harmonicTrigger = 0;
        if (audioState && audioState.channelData) {
            if (audioState.channelData[4] && audioState.channelData[4].trigger > 0.8) harmonicTrigger = 1;
            if (audioState.channelData[5] && audioState.channelData[5].trigger > 0.8) harmonicTrigger = 1;

            // Pass audio context to compute shader for wind sway
            this.uOrbAudioSway.value = (audioState.channelData[0]?.trigger || 0) * 5.0;
        }

        if (this.dropCooldown > 0) {
            this.dropCooldown -= dt;
        } else if (harmonicTrigger > 0 && Math.random() < 0.3) {
            this.spawnOrb(playerPos);
            this.dropCooldown = 5.0; // Drop one every 5 seconds max
        }

        let needsUpdate = false;

        for (let i = 0; i < MAX_ORBS; i++) {
            const orb = this.orbs[i];
            if (!orb.active) continue;

            orb.life -= dt;
            if (orb.life <= 0) {

                orb.active = false;
                // ⚡ OPTIMIZATION: Direct matrix write bypasses Object3D overhead
                const te = this.mesh.instanceMatrix.array;
                const offset = i * 16;
                te[offset] = 0; te[offset+5] = 0; te[offset+10] = 0;
                te[offset+12] = 0; te[offset+13] = -9999; te[offset+14] = 0;
                needsUpdate = true;
                continue;
            }


            // Physics: Gravity, Wind, Floatiness
            orb.velocity.y -= 9.8 * 0.2 * dt; // Slow, floaty gravity (feather-like)

            // Add some sway based on sine wave (like a falling leaf or bubble)
            orb.velocity.x += Math.sin(orb.life * 2.0) * 2.0 * dt;
            orb.velocity.z += Math.cos(orb.life * 1.5) * 2.0 * dt;

            // Terminal velocity (slow fall)
            if (orb.velocity.y < -5.0) orb.velocity.y = -5.0;

            orb.position.addScaledVector(orb.velocity, dt);

            // Ground collision
            // We do a simple height check. Ideally we use getGroundHeight, but since orbs are floaty, we can just say y < 0 is destroyed.
            if (orb.position.y < -5.0) {

                orb.active = false;
                // ⚡ OPTIMIZATION: Direct matrix write bypasses Object3D overhead
                const te = this.mesh.instanceMatrix.array;
                const offset = i * 16;
                te[offset] = 0; te[offset+5] = 0; te[offset+10] = 0;
                te[offset+12] = 0; te[offset+13] = -9999; te[offset+14] = 0;
                needsUpdate = true;
                continue;
            }


            // Scale up smoothly
            if (orb.scale < 1.0) {
                orb.scale += dt;
                if (orb.scale > 1.0) orb.scale = 1.0;

            }

            // ⚡ OPTIMIZATION: Direct matrix write for scale and translation
            const te = this.mesh.instanceMatrix.array;
            const offset = i * 16;
            const s = orb.scale;
            te[offset] = s; te[offset+5] = s; te[offset+10] = s;
            te[offset+12] = orb.position.x;
            te[offset+13] = orb.position.y;
            te[offset+14] = orb.position.z;
            needsUpdate = true;
        }

        if (needsUpdate) {
            this.mesh.instanceMatrix.needsUpdate = true;
        }
    }
}

export const harmonyOrbSystem = new HarmonyOrbSystem();

// src/foliage/batcher/foliage-batcher-audio.ts
// Audio analysis helper functions for foliage batch processing

/**
 * Get vibrato amount from audio data
 * Effect code 1 = vibrato
 */
export function getVibratoAmount(audioData: any): number {
    if (!audioData?.channelData) return 0;
    let amount = 0;
    for (const ch of audioData.channelData) {
        if (ch.activeEffect === 1) {
            amount = Math.max(amount, ch.effectValue || 0);
        }
    }
    return amount;
}

/**
 * Get tremolo amount from audio data
 * Effect code 3 = tremolo
 */
export function getTremoloAmount(audioData: any): number {
    if (!audioData?.channelData) return 0;
    let amount = 0;
    for (const ch of audioData.channelData) {
        if (ch.activeEffect === 3) {
            amount = Math.max(amount, ch.effectValue || 0);
        }
    }
    // Also add beat-based pulse
    amount = Math.max(amount, Math.sin((audioData.beatPhase || 0) * Math.PI * 2) * 0.3);
    return amount;
}

/**
 * Get high frequency amount (channels 3 and 4 volume)
 */
export function getHighFreqAmount(audioData: any): number {
    if (!audioData?.channelData) return 0;
    const ch3 = audioData.channelData[3]?.volume || 0;
    const ch4 = audioData.channelData[4]?.volume || 0;
    return Math.max(ch3, ch4);
}

/**
 * Get average volume across all channels
 */
export function getAverageVolume(audioData: any): number {
    if (!audioData?.channelData) return 1.0;
    let sum = 0;
    for (const ch of audioData.channelData) {
        sum += ch.volume || 0;
    }
    return sum / 4.0;
}

/**
 * Get pan activity (volume weighted by pan amount)
 */
export function getPanActivity(audioData: any): number {
    if (!audioData?.channelData) return 0;
    let activity = 0;
    for (const ch of audioData.channelData) {
        const vol = ch.volume || 0;
        const pan = ch.pan || 0;
        activity += vol * Math.abs(pan);
    }
    return activity;
}

// src/foliage/batcher/foliage-batcher-core.ts
// OPTIMIZATION: WASM batch processing for foliage animations
// Migrated 10 additional animation types from JS to WASM (Phase 1)

import * as THREE from 'three';
import {
    submitFoliageGpuScalarBatch,
    takeFoliageGpuScalarResult,
    shouldUseFoliageGpuBatch,
} from '../../compute/foliage-gpu-batch.ts';
import type { FoliageGpuBatchMode } from '../../compute/foliage-gpu-batch.ts';
import { isCIorHeadless } from '../../core/config.ts';
import { FoliageEcsBridge, type SimpleAnimType } from '../../systems/ecs/foliage-ecs-bridge.ts';
import { getWasmInstance } from '../../utils/wasm-loader.ts';
import {
    getVibratoAmount,
    getTremoloAmount,
    getHighFreqAmount,
    getAverageVolume,
    getPanActivity
} from './foliage-batcher-audio.ts';
import {
    applySnareSnap,
    applyAccordion,
    applyFiberWhip,
    applySpiralWave,
    applyVibratoShake,
    applyTremoloPulse,
    applyCymbalShake,
    applyPanningBob,
    applySpiritFade
} from './foliage-batcher-effects.ts';
import {
    BATCH_SIZE,
    BATCH_MEMORY_START,
    BATCH_ARRAY_SIZE,
    EXTENDED_BATCH_START,
    ENTRY_STRIDE,
    ENTRY_SIZE,
    RESULT_STRIDE,
    BatchState,
    ExtendedBatchState,
    FoliageObject
} from './foliage-batcher-types.ts';

export class FoliageBatcher {
    private static instance: FoliageBatcher;
    private initialized = false;
    private extendedInitialized = false;

    // Batches for each supported type
    private batches: {
        sway: BatchState;
        bounce: BatchState;
        hop: BatchState;
        gentleSway: BatchState;
        wobble: BatchState;
    };

    // Extended batches for migrated animation types (Phase 1)
    private extendedBatches: {
        snareSnap: ExtendedBatchState;
        accordion: ExtendedBatchState;
        fiberWhip: ExtendedBatchState;
        spiralWave: ExtendedBatchState;
        vibratoShake: ExtendedBatchState;
        tremoloPulse: ExtendedBatchState;
        cymbalShake: ExtendedBatchState;
        panningBob: ExtendedBatchState;
        spiritFade: ExtendedBatchState;
    };

    // Simple animation batches (Agent 1 migration)
    private simpleBatches: {
        shiver: ExtendedBatchState;
        spring: ExtendedBatchState;
        float: ExtendedBatchState;
        cloudBob: ExtendedBatchState;
    };

    private simpleBatchesInitialized = false;

    // OPTIMIZATION: Cached Float32Array view to prevent GC spikes in hot loops
    private cachedMemoryView: Float32Array | null = null;

    private getMemoryView(instance: any): Float32Array {
        const memory = instance.exports.memory;
        const buffer = memory.buffer || memory;
        if (!this.cachedMemoryView || this.cachedMemoryView.buffer !== buffer) {
            this.cachedMemoryView = new Float32Array(buffer);
        }
        return this.cachedMemoryView;
    }

    private constructor() {
        this.batches = {
            sway: this.createBatch(),
            bounce: this.createBatch(true), // needs originalY
            hop: this.createBatch(true),
            gentleSway: this.createBatch(),
            wobble: this.createBatch(false, true, true) // needs wobbleBoosts, 2 outputs
        };

        // Create extended batches for new animation types
        this.extendedBatches = {
            snareSnap: this.createExtendedBatch(),
            accordion: this.createExtendedBatch(),
            fiberWhip: this.createExtendedBatch(),
            spiralWave: this.createExtendedBatch(),
            vibratoShake: this.createExtendedBatch(),
            tremoloPulse: this.createExtendedBatch(),
            cymbalShake: this.createExtendedBatch(),
            panningBob: this.createExtendedBatch(),
            spiritFade: this.createExtendedBatch()
        };

        this.simpleBatches = {
            shiver: this.createExtendedBatch(),
            spring: this.createExtendedBatch(),
            float: this.createExtendedBatch(),
            cloudBob: this.createExtendedBatch()
        };
    }

    static getInstance(): FoliageBatcher {
        if (!FoliageBatcher.instance) {
            FoliageBatcher.instance = new FoliageBatcher();
        }
        return FoliageBatcher.instance;
    }

    private createBatch(needsOriginalY = false, needsWobble = false, twoOutputs = false): BatchState {
        // Memory will be allocated from fixed offsets in WASM linear memory
        return {
            count: 0,
            offsets: new Float32Array(BATCH_SIZE),
            intensities: new Float32Array(BATCH_SIZE),
            originalYs: needsOriginalY ? new Float32Array(BATCH_SIZE) : undefined,
            wobbleBoosts: needsWobble ? new Float32Array(BATCH_SIZE) : undefined,
            outScalars: new Float32Array(BATCH_SIZE),
            outScalars2: twoOutputs ? new Float32Array(BATCH_SIZE) : undefined,
            objects: new Array(BATCH_SIZE),
            ptrOffsets: 0,
            ptrIntensities: 0,
            ptrOriginalYs: 0,
            ptrWobbleBoosts: 0,
            ptrOutScalars: 0,
            ptrOutScalars2: 0
        };
    }

    private createExtendedBatch(): ExtendedBatchState {
        return {
            count: 0,
            input: new Float32Array(BATCH_SIZE * ENTRY_STRIDE),
            output: new Float32Array(BATCH_SIZE * RESULT_STRIDE),
            objects: new Array(BATCH_SIZE),
            ptrInput: 0,
            ptrOutput: 0
        };
    }

    private initBatchMemory(batch: BatchState, memoryOffset: number) {
        if (batch.ptrOffsets !== 0) return; // Already initialized

        const instance = getWasmInstance();
        if (!instance) return;

        // Use fixed memory offsets instead of dynamic allocation
        // This avoids the need for __new and __pin which aren't exported
        let currentOffset = memoryOffset;

        batch.ptrOffsets = currentOffset;
        currentOffset += BATCH_ARRAY_SIZE;

        batch.ptrIntensities = currentOffset;
        currentOffset += BATCH_ARRAY_SIZE;

        batch.ptrOutScalars = currentOffset;
        currentOffset += BATCH_ARRAY_SIZE;

        if (batch.originalYs) {
            batch.ptrOriginalYs = currentOffset;
            currentOffset += BATCH_ARRAY_SIZE;
        }

        if (batch.wobbleBoosts) {
            batch.ptrWobbleBoosts = currentOffset;
            currentOffset += BATCH_ARRAY_SIZE;
        }

        if (batch.outScalars2) {
            batch.ptrOutScalars2 = currentOffset;
            currentOffset += BATCH_ARRAY_SIZE;
        }
    }

    private initExtendedBatchMemory(batch: ExtendedBatchState, memoryOffset: number) {
        if (batch.ptrInput !== 0) return;

        const instance = getWasmInstance();
        if (!instance) return;

        batch.ptrInput = memoryOffset;
        batch.ptrOutput = memoryOffset + (BATCH_SIZE * ENTRY_SIZE);
    }

    init() {
        const instance = getWasmInstance();
        if (this.initialized || !instance) return;

        // Allocate memory for each batch type at fixed offsets
        // Calculate offsets for each batch (5 arrays max per batch)
        let currentOffset = BATCH_MEMORY_START;

        // Sway batch (3 arrays: offsets, intensities, outScalars)
        this.initBatchMemory(this.batches.sway, currentOffset);
        currentOffset += BATCH_ARRAY_SIZE * 3;

        // Bounce batch (4 arrays: offsets, intensities, originalYs, outScalars)
        this.initBatchMemory(this.batches.bounce, currentOffset);
        currentOffset += BATCH_ARRAY_SIZE * 4;

        // Hop batch (4 arrays: offsets, intensities, originalYs, outScalars)
        this.initBatchMemory(this.batches.hop, currentOffset);
        currentOffset += BATCH_ARRAY_SIZE * 4;

        // GentleSway batch (3 arrays: offsets, intensities, outScalars)
        this.initBatchMemory(this.batches.gentleSway, currentOffset);
        currentOffset += BATCH_ARRAY_SIZE * 3;

        // Wobble batch (5 arrays: offsets, intensities, wobbleBoosts, outScalars, outScalars2)
        this.initBatchMemory(this.batches.wobble, currentOffset);
        currentOffset += BATCH_ARRAY_SIZE * 5;

        this.initialized = true;
        console.log('[FoliageBatcher] WASM memory allocated using fixed offsets for batching');
        console.log(`[FoliageBatcher] Total memory used: ${currentOffset - BATCH_MEMORY_START} bytes`);
    }

    private initExtended() {
        const instance = getWasmInstance();
        if (this.extendedInitialized || !instance) return;

        if (isCIorHeadless()) {
            console.log('[FoliageBatcher] Skipping extended WASM allocation in CI to prevent crash');
            this.extendedInitialized = true;
            return;
        }

        let currentOffset = EXTENDED_BATCH_START;
        const batchSize = (BATCH_SIZE * ENTRY_SIZE) + (BATCH_SIZE * RESULT_STRIDE * 4);

        // Initialize each extended batch
        this.initExtendedBatchMemory(this.extendedBatches.snareSnap, currentOffset);
        currentOffset += batchSize;

        this.initExtendedBatchMemory(this.extendedBatches.accordion, currentOffset);
        currentOffset += batchSize;

        this.initExtendedBatchMemory(this.extendedBatches.fiberWhip, currentOffset);
        currentOffset += batchSize;

        this.initExtendedBatchMemory(this.extendedBatches.spiralWave, currentOffset);
        currentOffset += batchSize;

        this.initExtendedBatchMemory(this.extendedBatches.vibratoShake, currentOffset);
        currentOffset += batchSize;

        this.initExtendedBatchMemory(this.extendedBatches.tremoloPulse, currentOffset);
        currentOffset += batchSize;

        this.initExtendedBatchMemory(this.extendedBatches.cymbalShake, currentOffset);
        currentOffset += batchSize;

        this.initExtendedBatchMemory(this.extendedBatches.panningBob, currentOffset);
        currentOffset += batchSize;

        this.initExtendedBatchMemory(this.extendedBatches.spiritFade, currentOffset);
        currentOffset += batchSize;

        this.extendedInitialized = true;
        console.log('[FoliageBatcher] Extended WASM memory allocated for new animation types');
        console.log(`[FoliageBatcher] Extended memory used: ${currentOffset - EXTENDED_BATCH_START} bytes`);
    }

    private initSimpleBatches() {
        const instance = getWasmInstance();
        if (this.simpleBatchesInitialized || !instance) return;

        if (isCIorHeadless()) {
            console.log('[FoliageBatcher] Skipping simple WASM allocation in CI to prevent crash');
            this.simpleBatchesInitialized = true;
            return;
        }

        let currentOffset = EXTENDED_BATCH_START + (BATCH_SIZE * (ENTRY_SIZE + RESULT_STRIDE * 4) * 9); // After existing batches
        const batchSize = (BATCH_SIZE * ENTRY_SIZE) + (BATCH_SIZE * RESULT_STRIDE * 4);

        this.initExtendedBatchMemory(this.simpleBatches.shiver, currentOffset);
        currentOffset += batchSize;
        this.initExtendedBatchMemory(this.simpleBatches.spring, currentOffset);
        currentOffset += batchSize;
        this.initExtendedBatchMemory(this.simpleBatches.float, currentOffset);
        currentOffset += batchSize;
        this.initExtendedBatchMemory(this.simpleBatches.cloudBob, currentOffset);

        this.simpleBatchesInitialized = true;
    }

    queue(obj: FoliageObject, type: string, intensity: number, time: number, kick: number = 0): boolean {
        // Return true if handled, false if caller should use fallback
        if (!this.initialized) this.init();
        if (!this.initialized) return false;

        let batch: BatchState | undefined;

        if (type === 'sway') batch = this.batches.sway;
        else if (type === 'bounce') batch = this.batches.bounce;
        else if (type === 'hop') batch = this.batches.hop;
        else if (type === 'gentleSway') batch = this.batches.gentleSway;
        else if (type === 'wobble') batch = this.batches.wobble;

        if (batch) {
            if (batch.count >= BATCH_SIZE) return false;

            const i = batch.count;
            batch.objects[i] = obj;
            batch.offsets[i] = obj.userData.animationOffset || 0;
            batch.intensities[i] = intensity;

            if (batch.originalYs) {
                // Init originalY if missing
                if (obj.userData.originalY === undefined) obj.userData.originalY = obj.position.y;
                batch.originalYs[i] = obj.userData.originalY;
            }

            if (batch.wobbleBoosts) {
                batch.wobbleBoosts[i] = obj.userData.wobbleCurrent || 0;
            }

            batch.count++;
            return true;
        }

        // Try simple animation batch types (Agent 1 migration)
        if (type === 'shiver') {
            return this.queueSimpleBatch(obj, 'shiver', intensity, time);
        }
        if (type === 'spring') {
            return this.queueSimpleBatch(obj, 'spring', intensity, time);
        }
        if (type === 'float') {
            return this.queueSimpleBatch(obj, 'float', intensity, time);
        }
        if (type === 'cloudBob') {
            return this.queueSimpleBatch(obj, 'cloudBob', intensity, time);
        }

        // Try extended batches for new animation types
        return this.queueExtended(obj, type, intensity, time, kick);
    }

    private queueSimpleBatch(obj: FoliageObject, type: 'shiver' | 'spring' | 'float' | 'cloudBob', intensity: number, time: number): boolean {
        // If the ECS bridge is active it owns the entity; skip legacy queue path.
        const bridge = FoliageEcsBridge.getInstance();
        if (bridge.isReady()) {
            // Register each object once (no-op for subsequent frames — bridge tracks entities).
            if (obj.userData._ecsBridgeId === undefined) {
                obj.userData._ecsBridgeId = bridge.registerEntity(obj, type);
            }
            return true;
        }

        this.initSimpleBatches();
        if (!this.simpleBatchesInitialized) return false;

        const batch = this.simpleBatches[type];
        if (batch.count >= BATCH_SIZE) return false;

        const i = batch.count;
        const entryOffset = i * ENTRY_STRIDE;

        batch.objects[i] = obj;
        batch.input[entryOffset] = obj.userData.animationOffset || 0; // offset
        batch.input[entryOffset + 1] = intensity;

        if (type === 'float' || type === 'cloudBob') {
            if (obj.userData.originalY === undefined) obj.userData.originalY = obj.position.y;
            batch.input[entryOffset + 2] = obj.userData.originalY;
        }

        batch.count++;
        return true;
    }

    private queueExtended(obj: FoliageObject, type: string, intensity: number, time: number, kick: number): boolean {
        if (!this.extendedInitialized) this.initExtended();
        if (!this.extendedInitialized) return false;

        let batch: ExtendedBatchState | undefined;
        let animTypeCode = 0;

        switch (type) {
            case 'snareSnap':
                batch = this.extendedBatches.snareSnap;
                animTypeCode = 13;
                break;
            case 'accordion':
            case 'accordionStretch':
                batch = this.extendedBatches.accordion;
                animTypeCode = 14;
                break;
            case 'fiberWhip':
                batch = this.extendedBatches.fiberWhip;
                animTypeCode = 15;
                break;
            case 'spiralWave':
                batch = this.extendedBatches.spiralWave;
                animTypeCode = 16;
                break;
            case 'vibratoShake':
                batch = this.extendedBatches.vibratoShake;
                animTypeCode = 17;
                break;
            case 'tremoloPulse':
                batch = this.extendedBatches.tremoloPulse;
                animTypeCode = 18;
                break;
            case 'cymbalShake':
                batch = this.extendedBatches.cymbalShake;
                animTypeCode = 19;
                break;
            case 'panningBob':
                batch = this.extendedBatches.panningBob;
                animTypeCode = 20;
                break;
            case 'spiritFade':
                batch = this.extendedBatches.spiritFade;
                animTypeCode = 21;
                break;
        }

        if (!batch || batch.count >= BATCH_SIZE) return false;

        const i = batch.count;
        const entryOffset = i * ENTRY_STRIDE;

        batch.objects[i] = obj;

        // Fill entry data based on animation type
        batch.input[entryOffset] = obj.userData.animationOffset || 0; // offset
        batch.input[entryOffset + 1] = intensity; // intensity

        // Type-specific parameter setup
        switch (animTypeCode) {
            case 13: // snareSnap
                if (obj.userData.originalY === undefined) obj.userData.originalY = obj.position.y;
                batch.input[entryOffset + 2] = obj.userData.originalY;
                batch.input[entryOffset + 4] = obj.userData.snapState || 0; // persist state
                break;
            case 14: // accordion
                batch.input[entryOffset + 2] = 0; // originalY unused
                break;
            case 15: // fiberWhip
                batch.input[entryOffset + 4] = obj.userData.branchIndex || 0;
                break;
            case 19: // cymbalShake
                batch.input[entryOffset + 4] = obj.userData.rotZ || 0; // persist rotZ
                batch.input[entryOffset + 5] = obj.userData.rotX || 0; // persist rotX
                break;
            case 20: // panningBob
                if (obj.userData.originalY === undefined) obj.userData.originalY = obj.position.y;
                batch.input[entryOffset + 2] = obj.userData.originalY;
                batch.input[entryOffset + 4] = obj.userData.panBias || 0;
                batch.input[entryOffset + 5] = obj.userData.currentBob || 0;
                break;
            case 21: // spiritFade
                if (obj.userData.originalY === undefined) obj.userData.originalY = obj.position.y;
                batch.input[entryOffset + 2] = obj.userData.originalY;
                batch.input[entryOffset + 4] = obj.userData.currentOpacity || 0;
                batch.input[entryOffset + 5] = obj.userData.fleeSpeed || 0;
                break;
            default:
                if (obj.userData.originalY === undefined) obj.userData.originalY = obj.position.y;
                batch.input[entryOffset + 2] = obj.userData.originalY;
        }

        batch.count++;
        return true;
    }

    flush(time: number, kick: number, audioData: any = null) {
        if (!this.initialized) return;

        // Process Sway
        this.processSimpleBatch(this.batches.sway, 'computeSway', time, (obj, val) => {
            obj.rotation.z = val;
        });

        // Process Gentle Sway
        this.processSimpleBatch(this.batches.gentleSway, 'computeGentleSway', time, (obj, val) => {
            obj.rotation.z = val;
        });

        // Process Bounce
        this.processPhysicsBatch(this.batches.bounce, 'computeBounce', time, kick, (obj, val) => {
            obj.position.y = val;
        });

        // Process Hop
        this.processPhysicsBatch(this.batches.hop, 'computeHop', time, kick, (obj, val) => {
            obj.position.y = val;
        });

        // Process Wobble
        this.processWobbleBatch(this.batches.wobble, time);

        // Process extended batches
        this.flushExtended(time, kick, audioData);

        // Process simple animation batches (Agent 1 migration)
        // Use audio intensity from audioData if available
        const audioIntensity = audioData?.intensity || kick || 0.5;
        this.flushSimpleBatches(time, audioIntensity);
    }

    private processSimpleBatch(batch: BatchState, funcName: string, time: number, apply: (o: FoliageObject, v: number) => void) {
        if (batch.count === 0) return;

        const count = batch.count;
        const gpuMode = this.funcNameToGpuMode(funcName);
        const batchKey = `foliage-${funcName}`;

        if (gpuMode && shouldUseFoliageGpuBatch(count)) {
            const gpuScalars = takeFoliageGpuScalarResult(batchKey);
            if (gpuScalars && gpuScalars.length >= count) {
                for (let i = 0; i < count; i++) {
                    apply(batch.objects[i], gpuScalars[i]);
                    batch.objects[i] = undefined as any;
                }
                submitFoliageGpuScalarBatch(
                    batchKey,
                    gpuMode,
                    count,
                    time,
                    0,
                    batch.offsets.subarray(0, count),
                    batch.intensities.subarray(0, count),
                    batch.originalYs?.subarray(0, count) ?? batch.offsets.subarray(0, count)
                );
                batch.count = 0;
                return;
            }
        }

        const instance = getWasmInstance();
        if (!instance) return;

        // OPTIMIZATION: Cached Float32Array view to prevent GC spikes in hot loops
        const F32 = this.getMemoryView(instance);

        const offPtr = batch.ptrOffsets >>> 2;
        const intPtr = batch.ptrIntensities >>> 2;

        let validCount = batch.count;
        if (offPtr + validCount > F32.length) validCount = Math.max(0, F32.length - offPtr);
        if (intPtr + validCount > F32.length) validCount = Math.max(0, F32.length - intPtr);
        if (validCount > 0) {
            F32.set(batch.offsets.subarray(0, validCount), offPtr);
            F32.set(batch.intensities.subarray(0, validCount), intPtr);
        }

        const func = (instance.exports as any)[funcName];
        if (func) {
            func(batch.count, time, batch.ptrOffsets, batch.ptrIntensities, batch.ptrOutScalars);

            const outPtr = batch.ptrOutScalars >>> 2;
            const res = F32.subarray(outPtr, outPtr + batch.count);

            for (let i = 0; i < batch.count; i++) {
                apply(batch.objects[i], res[i]);
                batch.objects[i] = undefined as any;
            }
        }

        if (gpuMode && shouldUseFoliageGpuBatch(count)) {
            submitFoliageGpuScalarBatch(
                batchKey,
                gpuMode,
                count,
                time,
                0,
                batch.offsets.subarray(0, count),
                batch.intensities.subarray(0, count),
                batch.originalYs?.subarray(0, count) ?? batch.offsets.subarray(0, count)
            );
        }

        batch.count = 0;
    }

    private funcNameToGpuMode(funcName: string): FoliageGpuBatchMode | null {
        switch (funcName) {
            case 'computeSway':
                return 'sway';
            case 'computeGentleSway':
                return 'gentleSway';
            case 'computeBounce':
                return 'bounce';
            case 'computeHop':
                return 'hop';
            default:
                return null;
        }
    }

    private processPhysicsBatch(batch: BatchState, funcName: string, time: number, kick: number, apply: (o: FoliageObject, v: number) => void) {
        if (batch.count === 0) return;

        const count = batch.count;
        const gpuMode = this.funcNameToGpuMode(funcName);
        const batchKey = `foliage-${funcName}`;

        if (gpuMode && shouldUseFoliageGpuBatch(count) && batch.originalYs) {
            const gpuScalars = takeFoliageGpuScalarResult(batchKey);
            if (gpuScalars && gpuScalars.length >= count) {
                for (let i = 0; i < count; i++) {
                    apply(batch.objects[i], gpuScalars[i]);
                    batch.objects[i] = undefined as any;
                }
                submitFoliageGpuScalarBatch(
                    batchKey,
                    gpuMode,
                    count,
                    time,
                    kick,
                    batch.offsets.subarray(0, count),
                    batch.intensities.subarray(0, count),
                    batch.originalYs.subarray(0, count)
                );
                batch.count = 0;
                return;
            }
        }

        const instance = getWasmInstance();
        if (!instance) return;

        // OPTIMIZATION: Cached Float32Array view to prevent GC spikes in hot loops
        const F32 = this.getMemoryView(instance);

        const offPtr = batch.ptrOffsets >>> 2;
        const intPtr = batch.ptrIntensities >>> 2;
        const orgPtr = (batch.ptrOriginalYs!) >>> 2;

        let validCount = batch.count;
        if (offPtr + validCount > F32.length) validCount = Math.max(0, F32.length - offPtr);
        if (intPtr + validCount > F32.length) validCount = Math.max(0, F32.length - intPtr);
        if (validCount > 0) {
            F32.set(batch.offsets.subarray(0, validCount), offPtr);
            F32.set(batch.intensities.subarray(0, validCount), intPtr);
        }
        F32.set(batch.originalYs!.subarray(0, batch.count), orgPtr);

        const func = (instance.exports as any)[funcName];
        if (func) {
            func(batch.count, time, batch.ptrOriginalYs, batch.ptrOffsets, batch.ptrIntensities, kick, batch.ptrOutScalars);

            const outPtr = batch.ptrOutScalars >>> 2;
            const res = F32.subarray(outPtr, outPtr + batch.count);

            for (let i = 0; i < batch.count; i++) {
                apply(batch.objects[i], res[i]);
                batch.objects[i] = undefined as any;
            }
        }

        if (gpuMode && shouldUseFoliageGpuBatch(count) && batch.originalYs) {
            submitFoliageGpuScalarBatch(
                batchKey,
                gpuMode,
                count,
                time,
                kick,
                batch.offsets.subarray(0, count),
                batch.intensities.subarray(0, count),
                batch.originalYs.subarray(0, count)
            );
        }

        batch.count = 0;
    }

    private processWobbleBatch(batch: BatchState, time: number) {
        if (batch.count === 0) return;

        const instance = getWasmInstance();
        if (!instance) return;

        // OPTIMIZATION: Cached Float32Array view to prevent GC spikes in hot loops
        const F32 = this.getMemoryView(instance);

        const offPtr = batch.ptrOffsets >>> 2;
        const intPtr = batch.ptrIntensities >>> 2;
        const boostPtr = (batch.ptrWobbleBoosts!) >>> 2;

        let validCount = batch.count;
        if (offPtr + validCount > F32.length) validCount = Math.max(0, F32.length - offPtr);
        if (intPtr + validCount > F32.length) validCount = Math.max(0, F32.length - intPtr);
        if (validCount > 0) {
            F32.set(batch.offsets.subarray(0, validCount), offPtr);
            F32.set(batch.intensities.subarray(0, validCount), intPtr);
        }
        F32.set(batch.wobbleBoosts!.subarray(0, batch.count), boostPtr);

        const func = (instance.exports as any)['computeWobble'];
        if (func) {
            func(batch.count, time, batch.ptrOffsets, batch.ptrIntensities, batch.ptrWobbleBoosts, batch.ptrOutScalars, batch.ptrOutScalars2);

            const outPtr1 = batch.ptrOutScalars >>> 2;
            const outPtr2 = (batch.ptrOutScalars2!) >>> 2;

            for (let i = 0; i < batch.count; i++) {
                const obj = batch.objects[i];
                obj.rotation.x = F32[outPtr1 + i];
                obj.rotation.z = F32[outPtr2 + i];
                // Decay wobble state
                if (obj.userData.wobbleCurrent) {
                    obj.userData.wobbleCurrent *= 0.9;
                }
                batch.objects[i] = undefined as any;
            }
        }
        batch.count = 0;
    }

    private processExtendedBatch(
        batch: ExtendedBatchState,
        animType: number,
        time: number,
        kick: number,
        groove: number,
        audioParam: number,
        apply: (obj: FoliageObject, data: Float32Array, offset: number) => void
    ) {
        if (batch.count === 0) return;

        const instance = getWasmInstance();
        if (!instance) return;

        // OPTIMIZATION: Cached Float32Array view to prevent GC spikes in hot loops
        const F32 = this.getMemoryView(instance);

        // Copy input data to WASM memory
        const inPtr = batch.ptrInput >>> 2;
        let countToCopy = batch.count * ENTRY_STRIDE;
        if (inPtr + countToCopy > F32.length) {
            countToCopy = F32.length - inPtr;
        }
        if (countToCopy > 0) {
            F32.set(batch.input.subarray(0, countToCopy), inPtr);
        }

        // Call the universal batch processor (C++ or AssemblyScript)
        const func = (instance.exports as any)['processBatchUniversal_c'] || 
                     (instance.exports as any)['processBatchUniversal'];

        if (func) {
            func(
                animType,
                batch.ptrInput,
                batch.count,
                time,
                0, // beatPhase
                kick,
                groove,
                audioParam,
                batch.ptrOutput
            );

            // Read results
            const outPtr = batch.ptrOutput >>> 2;
            const results = F32.subarray(outPtr, outPtr + batch.count * RESULT_STRIDE);

            // Apply results to objects
            // OPTIMIZATION: Removed 'results.subarray' allocation in loop
            for (let i = 0; i < batch.count; i++) {
                const obj = batch.objects[i];
                const outOffset = i * RESULT_STRIDE;
                apply(obj, results, outOffset);
                batch.objects[i] = undefined as any;
            }
        }

        batch.count = 0;
    }

    private flushExtended(time: number, kick: number, audioData: any) {
        if (!this.extendedInitialized) return;

        const instance = getWasmInstance();
        if (!instance) return;

        // Extract audio parameters
        const groove = audioData?.grooveAmount || 0;
        const snareTrigger = audioData?.channelData?.[1]?.trigger || 0;
        const leadVol = audioData?.channelData?.[2]?.volume || 0;
        const vibrato = getVibratoAmount(audioData);
        const tremolo = getTremoloAmount(audioData);
        const highFreq = getHighFreqAmount(audioData);
        const volume = getAverageVolume(audioData);

        // Process snare snap
        this.processExtendedBatch(
            this.extendedBatches.snareSnap,
            13, time, kick, groove, snareTrigger,
            applySnareSnap
        );

        // Process accordion
        this.processExtendedBatch(
            this.extendedBatches.accordion,
            14, time, kick, groove, 0,
            applyAccordion
        );

        // Process fiber whip
        this.processExtendedBatch(
            this.extendedBatches.fiberWhip,
            15, time, kick, groove, leadVol,
            applyFiberWhip
        );

        // Process spiral wave
        this.processExtendedBatch(
            this.extendedBatches.spiralWave,
            16, time, kick, groove, 0,
            applySpiralWave
        );

        // Process vibrato shake
        this.processExtendedBatch(
            this.extendedBatches.vibratoShake,
            17, time, kick, groove, vibrato,
            applyVibratoShake
        );

        // Process tremolo pulse
        this.processExtendedBatch(
            this.extendedBatches.tremoloPulse,
            18, time, kick, groove, tremolo,
            applyTremoloPulse
        );

        // Process cymbal shake
        this.processExtendedBatch(
            this.extendedBatches.cymbalShake,
            19, time, kick, groove, highFreq,
            applyCymbalShake
        );

        // Process panning bob
        this.processExtendedBatch(
            this.extendedBatches.panningBob,
            20, time, kick, groove, getPanActivity(audioData),
            applyPanningBob
        );

        // Process spirit fade
        this.processExtendedBatch(
            this.extendedBatches.spiritFade,
            21, time, kick, groove, volume,
            applySpiritFade
        );
    }

    private flushSimpleBatches(time: number, intensity: number) {
        // Fast path: C++ ECS handles entity query + batch animate in one shot.
        const bridge = FoliageEcsBridge.getInstance();
        if (bridge.isReady()) {
            const types: SimpleAnimType[] = ['shiver', 'spring', 'float', 'cloudBob'];
            for (const t of types) bridge.runBatch(t, time, intensity);
            return;
        }

        if (!this.simpleBatchesInitialized) return;

        const instance = getWasmInstance();
        if (!instance) return;

        const func = (instance.exports as any)['processBatchUniversal_c'] || 
                     (instance.exports as any)['processBatchUniversal'];
        if (!func) return;

        // Animation type codes for simple batches (22-25)
        const batchConfigs: { type: 'shiver' | 'spring' | 'float' | 'cloudBob', code: number, apply: (obj: FoliageObject, data: Float32Array, offset: number) => void }[] = [
            {
                type: 'shiver',
                code: 22,
                apply: (obj, data, offset) => {
                    obj.rotation.z = data[offset];      // rotZ
                    obj.rotation.x = data[offset + 1];  // rotX
                }
            },
            {
                type: 'spring',
                code: 23,
                apply: (obj, data, offset) => {
                    obj.scale.y = data[offset];      // scaleY
                    obj.scale.x = data[offset + 1];  // scaleX
                    obj.scale.z = data[offset + 2];  // scaleZ
                }
            },
            {
                type: 'float',
                code: 24,
                apply: (obj, data, offset) => {
                    obj.position.y = data[offset];  // posY
                }
            },
            {
                type: 'cloudBob',
                code: 25,
                apply: (obj, data, offset) => {
                    obj.position.y = data[offset];   // posY
                    obj.rotation.y = data[offset + 1]; // rotY
                }
            }
        ];

        // OPTIMIZATION: Cached Float32Array view to prevent GC spikes in hot loops
        const F32 = this.getMemoryView(instance);

        for (const config of batchConfigs) {
            const batch = this.simpleBatches[config.type];
            if (batch.count === 0) continue;

            // Copy input data
            const inPtr = batch.ptrInput >>> 2;
        let countToCopy = batch.count * ENTRY_STRIDE;
        if (inPtr + countToCopy > F32.length) {
            countToCopy = F32.length - inPtr;
        }
        if (countToCopy > 0) {
            F32.set(batch.input.subarray(0, countToCopy), inPtr);
        }

            // Call native function
            const nativeFunc = (instance.exports as any)[`batch${config.type.charAt(0).toUpperCase() + config.type.slice(1)}_c`];
            if (nativeFunc) {
                nativeFunc(batch.ptrInput, batch.count, time, intensity, batch.ptrOutput);
            } else {
                // Fallback to universal processor
                func(config.code, batch.ptrInput, batch.count, time, 0, 0, 0, 0, batch.ptrOutput);
            }

            // Read results
            const outPtr = batch.ptrOutput >>> 2;
            const results = F32.subarray(outPtr, outPtr + batch.count * RESULT_STRIDE);

            // Apply to objects
            for (let i = 0; i < batch.count; i++) {
                const obj = batch.objects[i];
                const offset = i * RESULT_STRIDE;
                config.apply(obj, results, offset);
                batch.objects[i] = undefined as any;
            }

            batch.count = 0;
        }
    }
}

