// --- Falling Berry Particle System ---
let fallingBerryPool: FallingBerry[] = [];
const MAX_FALLING_BERRIES = 50;
let fallingBerryMesh: THREE.Points | null = null;
const _scratchColorFalling = new THREE.Color();

// WebGPU Compute Nodes & Buffers



let computeParticleSystem: ComputeParticleSystem | null = null;

export function initFallingBerries(scene: THREE.Scene): void {
    // ⚡ OPTIMIZATION: Replace CPU-driven bespoke TSL logic with global Phase 4 ComputeParticleSystem
    computeParticleSystem = createComputeBerries({ count: MAX_FALLING_BERRIES });
    fallingBerryMesh = computeParticleSystem.mesh as THREE.Points;
    fallingBerryMesh.name = 'fallingBerries';
    fallingBerryMesh.userData.isFallingBerrySystem = true;
    fallingBerryMesh.userData.computeParticleSystem = computeParticleSystem;

    // Keep CPU Proxy array initialized for rapid collision detection
    fallingBerryPool = [];
    for (let i = 0; i < MAX_FALLING_BERRIES; i++) {
        fallingBerryPool.push({
            active: false,
            age: 0,
            velocity: new THREE.Vector3(),
            position: new THREE.Vector3()
        });
    }

    scene.add(fallingBerryMesh);
}


export function spawnFallingBerry(position: THREE.Vector3, colorHex: number = 0xFF6600): void {
    if (!fallingBerryMesh) return;

    let index = -1;
    for (let i = 0; i < MAX_FALLING_BERRIES; i++) {
        if (!fallingBerryPool[i].active) {
            index = i;
            break;
        }
    }

    if (index === -1) return;

    const berry = fallingBerryPool[index];

    berry.position.copy(position);
    berry.velocity.set(
        (Math.random() - 0.5) * 2,
        -2 - Math.random() * 3,
        (Math.random() - 0.5) * 2
    );
    berry.active = true;
    berry.age = 0;

    // Spawn natively via WebGPU ComputeParticleSystem zero-allocation method
    if (computeParticleSystem) {
        berry.gpuIndex = computeParticleSystem.spawn({
            position: berry.position,
            velocity: berry.velocity,
            life: 3.0,
            size: 1.0
        });
    }

    // Note: ComputeParticleSystem handles base coloring internally via TSL material or options.
    // fallingBerryMesh.setColorAt is not valid for THREE.Points.
}

export function updateFallingBerries(delta: number, renderer?: THREE.Renderer): void {
    if (!fallingBerryMesh) return;

    // Sync compute system if available
    if (computeParticleSystem && renderer) {
        // We pass a dummy player and audio data since this is environmentally updated
        _scratchZeroVector.set(0, 0, 0); // ⚡ OPTIMIZATION: Use scratch vector instead of new THREE.Vector3()
        computeParticleSystem.update(renderer, delta, _scratchZeroVector, {
            low: 0, mid: 0, high: 0, beat: false, groove: 0, windX: 0, windZ: 0, windSpeed: 0
        });
    }

    const gravity = -9.8;
    const maxAge = 3.0;

    // Update CPU Proxy for collisions only
    for (let i = 0; i < MAX_FALLING_BERRIES; i++) {
        const berry = fallingBerryPool[i];
        if (!berry.active) continue;

        berry.age += delta;
        berry.velocity.y += gravity * delta;

        berry.position.x += berry.velocity.x * delta;
        berry.position.y += berry.velocity.y * delta;
        berry.position.z += berry.velocity.z * delta;

        if (berry.position.y < 0 || berry.age > maxAge) {
            berry.active = false;
        }
    }
}

export function shakeBerriesLoose(cluster: THREE.Group, intensity: number): void {
    const count = cluster.userData.count || 0;
    // Use Batcher helper to find positions
    for (let i = 0; i < count; i++) {
        if (Math.random() < intensity * 0.02) {
            BerryBatcher.getInstance().getBerryWorldPosition(cluster, i, _scratchWorldPos);
            spawnFallingBerry(_scratchWorldPos, cluster.userData.berryColor || 0xFF6600);
        }
    }
}

export function collectFallingBerries(playerPos: THREE.Vector3, collectRadius: number = 1.0): number {
    if (!fallingBerryMesh) return 0;

    let collected = 0;
    const radiusSq = collectRadius * collectRadius;

    for (let i = 0; i < MAX_FALLING_BERRIES; i++) {
        const berry = fallingBerryPool[i];
        if (!berry.active) continue;

        const dx = berry.position.x - playerPos.x; const dy = berry.position.y - playerPos.y; const dz = berry.position.z - playerPos.z; const distSq = dx*dx + dy*dy + dz*dz;
        if (distSq < radiusSq) {
            spawnImpact(berry.position, 'berry');

            if (uChromaticIntensity) {
                uChromaticIntensity.value += 0.3;
                if (uChromaticIntensity.value > 1.0) uChromaticIntensity.value = 1.0;
            }

            // Kill it in the CPU proxy and GPU buffer
            berry.active = false;
            if (computeParticleSystem && berry.gpuIndex !== undefined) {
                computeParticleSystem.kill(berry.gpuIndex);
            }
            collected++;
        }
    }



    return collected;
}

// src/foliage/celestial-bodies.ts

import * as THREE from 'three';
import { color, float, vec3, vec4, uniform, mix, sin, cos, time, positionLocal, attribute } from 'three/tsl';
import { MeshBasicNodeMaterial, PointsNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { attachReactivity, CandyPresets, uAudioLow, uAudioHigh, uTime } from './index.ts';

// Helper to place objects on a distant sky sphere
function getRandomSkyPosition(radius: number): THREE.Vector3 {
    const phi = Math.acos((Math.random() * 2) - 1); // 0 to PI
    const theta = Math.random() * Math.PI * 2;       // 0 to 2PI

    // Convert spherical to cartesian
    const x = radius * Math.sin(phi) * Math.cos(theta);
    const y = Math.abs(radius * Math.cos(phi)); // Ensure mostly upper hemisphere (positive Y)
    const z = radius * Math.sin(phi) * Math.sin(theta);

    return new THREE.Vector3(x, Math.max(100, y), z);
}

// --- 1. THE PULSAR (High Freq / Sky Reactivity) ---
function createPulsar(): THREE.Group {
    const group = new THREE.Group();

    // 🎨 PALETTE: TSL Audio Reactive Pulsar
    const baseScale = float(1.0).add(uAudioHigh.mul(1.5)); // Expand on Highs
    const pulseOffset = sin(uTime.mul(5.0)).mul(0.1).add(1.0); // Subtle idle breathe
    const totalScale = baseScale.mul(pulseOffset);

    // Core Star
    const geo = new THREE.SphereGeometry(4, 16, 16);
    const mat = new MeshStandardNodeMaterial({
        color: 0xFFFFFF,
        roughness: 0.2,
        metalness: 0.1
    });

    // Deform vertices and make it glow
    mat.positionNode = positionLocal.mul(totalScale);
    mat.emissiveNode = color(0xAAFFFF).mul(float(2.0).add(uAudioHigh.mul(5.0)));

    const core = new THREE.Mesh(geo, mat);
    group.add(core);

    // Glow Halo (Billboard Sprite logic or simple transparent sphere)
    const glowGeo = new THREE.SphereGeometry(8, 16, 16);
    const glowMat = new MeshStandardNodeMaterial({
        color: 0x00FFFF,
        transparent: true,
        opacity: 0.4,
        blending: THREE.AdditiveBlending,
        side: THREE.BackSide,
        depthWrite: false
    });

    // Scale the halo aggressively on beat
    const haloScale = float(1.0).add(uAudioHigh.mul(2.0)).mul(pulseOffset);
    glowMat.positionNode = positionLocal.mul(haloScale);
    glowMat.emissiveNode = color(0x00FFFF).mul(float(1.0).add(uAudioHigh.mul(3.0)));

    const glow = new THREE.Mesh(glowGeo, glowMat);
    group.add(glow);

    // Reactivity Config
    group.userData.type = 'pulsar';
    group.userData.reactivityType = 'sky'; // Reacts to Drums
    // Pulsars are visible even in day, but best at night
    group.userData.minLight = 0.0;
    group.userData.maxLight = 1.0;

    return attachReactivity(group);
}

// --- 2. THE BASS PLANET (Low Freq / Flora Reactivity) ---
function createBassPlanet(): THREE.Group {
    const group = new THREE.Group();

    // 🎨 PALETTE: TSL Audio Reactive Bass Planet
    const bassPulse = uAudioLow.mul(0.2); // Pulse on kick
    const planetScale = float(1.0).add(bassPulse);

    // Planet Body
    const planetGeo = new THREE.IcosahedronGeometry(15, 2);
    const planetMat = CandyPresets.Clay(0xFF4444, {
        roughness: 0.8
    });

    // Deform planet and add inner glow
    planetMat.positionNode = positionLocal.mul(planetScale);
    planetMat.emissiveNode = color(0xFF4444).mul(bassPulse.mul(2.0));

    const planet = new THREE.Mesh(planetGeo, planetMat);
    group.add(planet);

    // Rings
    const ringGeo = new THREE.RingGeometry(20, 35, 32);
    const ringMat = new MeshStandardNodeMaterial({
        color: 0xFFAA88,
        side: THREE.DoubleSide,
        transparent: true,
        opacity: 0.8,
        roughness: 0.4
    });

    // Rings warp and glow on bass
    const ringWarp = sin(uTime.mul(2.0).add(positionLocal.x.mul(0.1))).mul(uAudioLow.mul(2.0));
    const ringScale = float(1.0).add(uAudioLow.mul(0.1));

    ringMat.positionNode = positionLocal.mul(ringScale).add(vec3(0, ringWarp, 0));
    ringMat.emissiveNode = color(0xFFAA88).mul(bassPulse.mul(3.0));

    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = Math.PI / 2.5; // Tilt the ring
    group.add(ring);

    // Reactivity Config
    group.userData.type = 'planet';
    group.userData.reactivityType = 'flora';
    group.userData.reactivityId = 0; // Lock to Kick/Bass channel

    return attachReactivity(group);
}

// --- 3. THE SPIRAL GALAXY (Melody Reactivity) ---
function createGalaxy(): THREE.Points {
    const particles = 1000;
    const geo = new THREE.BufferGeometry();
    const positions = new Float32Array(particles * 3);
    const colors = new Float32Array(particles * 3);
    const sizes = new Float32Array(particles);

    const colorInside = new THREE.Color(0xff6030);
    const colorOutside = new THREE.Color(0x1b3984);

    for (let i = 0; i < particles; i++) {
        // Logarithmic Spiral Math
        const radius = Math.random() * 40;
        const spinAngle = radius * 0.5; // Tighter spiral near center
        const branchAngle = (i % 3) * ((Math.PI * 2) / 3); // 3 Arms

        const randomX = Math.pow(Math.random(), 3) * (Math.random() < 0.5 ? 1 : -1);
        const randomY = Math.pow(Math.random(), 3) * (Math.random() < 0.5 ? 1 : -1);
        const randomZ = Math.pow(Math.random(), 3) * (Math.random() < 0.5 ? 1 : -1);

        const x = Math.cos(spinAngle + branchAngle) * radius + randomX;
        const y = Math.random() * 2 + randomY; // Flattened disk
        const z = Math.sin(spinAngle + branchAngle) * radius + randomZ;

        positions[i * 3] = x;
        positions[i * 3 + 1] = y;
        positions[i * 3 + 2] = z;

        // Color Mix
        const mixedColor = colorInside.clone();
        mixedColor.lerp(colorOutside, radius / 40);

        colors[i * 3] = mixedColor.r;
        colors[i * 3 + 1] = mixedColor.g;
        colors[i * 3 + 2] = mixedColor.b;

        sizes[i] = Math.random() * 2;
    }

    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));

    // TSL Compatibility: Add dummy normals
    const normals = new Float32Array(particles * 3);
    for(let i=0; i<particles*3; i+=3) { normals[i] = 0; normals[i+1] = 1; normals[i+2] = 0; }
    geo.setAttribute('normal', new THREE.BufferAttribute(normals, 3));

    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geo.setAttribute('size', new THREE.BufferAttribute(sizes, 1)); // For shader if used, or size attenuation

    const mat = new PointsNodeMaterial({
        size: 0.8,
        vertexColors: true, // We will override with colorNode, but keep this to pass vertexColors
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        transparent: true
    });

    // 🎨 PALETTE: TSL Audio Reactive Galaxy
    const particleSize = attribute('size', 'float');
    const particleColor = attribute('color', 'vec3');

    // Pulse size on melody highs
    const audioScale = float(1.0).add(uAudioHigh.mul(2.0));
    (mat as any).sizeNode = particleSize.mul(audioScale).mul(mat.size);

    // Shift color towards neon on beat
    const highColor = mix(particleColor, vec3(1.0, 0.2, 0.8), uAudioHigh.mul(0.5));
    mat.colorNode = vec4(highColor, 1.0);

    // Add subtle idle rotation to particles using positionLocal
    const angle = uTime.mul(0.5);
    const rotatedX = positionLocal.x.mul(cos(angle)).sub(positionLocal.z.mul(sin(angle)));
    const rotatedZ = positionLocal.x.mul(sin(angle)).add(positionLocal.z.mul(cos(angle)));
    mat.positionNode = vec3(rotatedX, positionLocal.y, rotatedZ);

    const galaxy = new THREE.Points(geo, mat);

    // Reactivity Config
    galaxy.userData.type = 'galaxy';
    galaxy.userData.reactivityType = 'flora'; // Melody channels
    galaxy.userData.baseRotationSpeed = 0.0005;

    return attachReactivity(galaxy);
}

export function initCelestialBodies(scene: THREE.Scene): THREE.Object3D[] {
    const bodies: THREE.Object3D[] = [];

    // Create 1 Galaxy
    const galaxy = createGalaxy();
    galaxy.position.copy(getRandomSkyPosition(900));
    galaxy.lookAt(0, 0, 0); // Face the world
    scene.add(galaxy);
    bodies.push(galaxy);

    // Create 2 Pulsars
    for (let i = 0; i < 2; i++) {
        const pulsar = createPulsar();
        pulsar.position.copy(getRandomSkyPosition(950));
        scene.add(pulsar);
        bodies.push(pulsar);
    }

    // Create 1 Bass Planet
    const planet = createBassPlanet();
    planet.position.copy(getRandomSkyPosition(800));
    scene.add(planet);
    bodies.push(planet);

    return bodies;
}

import * as THREE from 'three';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
import {
    color, uniform, mix, vec3, positionLocal, normalLocal, mx_noise_float,
    float, normalize, positionWorld, normalWorld, cameraPosition, dot, abs, sin, pow,
    uv, smoothstep
} from 'three/tsl';
import { attribute } from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { camera } from '../core/camera-ref.ts';
import { CONFIG } from '../core/config.ts';


// --- Global Uniforms (Moved from clouds.js) ---
export const uCloudRainbowIntensity = uniform(0.0);
export const uCloudLightningStrength = uniform(0.0);
export const uCloudLightningColor = uniform(color(0xFFFFFF));

// --- Material Creation ---
function createCloudMaterial() {
    const material = new MeshStandardNodeMaterial({
        color: 0xffffff,     // Pure cotton white base
        roughness: 0.9,      // Mostly matte but allows some sheen
        metalness: 0.0,
        flatShading: false,
    });

    // --- PALETTE: Juicy Cloud Logic ---

    // 1. Player Interaction (Juicy Landing/Jump Squash)
    // The player touching the cloud pushes it down, causing it to bulge outwards
    const playerDistVector = positionWorld.sub(uPlayerPosition);
    // Ignore Y distance for cylinder interaction radius check
    const playerDistXZ = vec3(playerDistVector.x, float(0.0), playerDistVector.z);
    const distSq = dot(playerDistXZ, playerDistXZ);

    // Interaction Radius = 4.0m (Sq = 16.0)
    const interactRadiusSq = float(16.0);

    // Force falls off with distance. Normalized distance (0 to 1 inside radius)
    const distFactor = distSq.div(interactRadiusSq).min(1.0);
    // Strength: 1.0 at center, 0.0 at edge
    const playerStrength = float(1.0).sub(smoothstep(0.0, 1.0, distFactor));

    // Squash Y down, Bulge XZ out
    const playerSquashAmount = playerStrength.mul(0.6); // Max 60% squash
    const playerSquishScale = vec3(
        float(1.0).add(playerSquashAmount.mul(0.5)), // Expand X
        float(1.0).sub(playerSquashAmount),          // Compress Y
        float(1.0).add(playerSquashAmount.mul(0.5))  // Expand Z
    );

    // 2. Wind Shearing (Clouds drift faster at the top)
    // We use positionLocal.y (approx height) to shear along Wind Direction
    // Shearing Factor = Height * WindSpeed * 0.5
    const shearHeight = positionLocal.y.max(0.0); // Clamp to 0 to keep bottom fixed-ish
    const shearAmount = shearHeight.mul(uWindSpeed).mul(0.5);
    const windShear = vec3(
        uWindDirection.x.mul(shearAmount),
        float(0.0), // No vertical shear
        uWindDirection.z.mul(shearAmount)
    );

    // 3. Internal Turbulence (Boiling Effect)
    // Use 3D noise that scrolls with time
    const noiseScale = float(1.2);
    const boilSpeed = float(0.3); // Slow boiling
    const timeOffset = vec3(0.0, uTime.mul(boilSpeed), 0.0);

    const noisePos = positionLocal.mul(noiseScale).add(timeOffset);
    // Standard noise for shape
    const shapeNoise = mx_noise_float(noisePos);

    // 4. Audio Reactivity (Squish + Pulse)
    // Bass Squish: Squashes the cloud vertically on Kick and bulges horizontally
    const bassSquish = uAudioLow.mul(0.3);
    const verticalSquish = vec3(
        float(1.0).add(bassSquish.mul(0.5)),
        float(1.0).sub(bassSquish),
        float(1.0).add(bassSquish.mul(0.5))
    );

    // Melody Puff: Expands the cloud slightly on Highs
    const melodyPuff = uAudioHigh.mul(0.2);

    // Music Impact: soft internal starlight pulse on melody hits
    const melodyGlow = uAudioHigh.mul(float(CONFIG.cloud.emissivePulse));

    // Total Displacement Magnitude
    // Base fluff + Melody expansion
    const displacementStrength = float(0.2).add(melodyPuff);

    // Calculate final position
    // Start with shearing
    const shearedPos = positionLocal.add(windShear);
    // Apply Audio Squish and Player Squash scale
    const squishedPos = shearedPos.mul(verticalSquish).mul(playerSquishScale);

    // Apply Fluff Displacement along Normal
    // Audio-reactive puff intensity during deformation
    const puffIntensity = float(1.0).add(uAudioHigh.mul(0.8));
    const fluffOffset = normalLocal.mul(shapeNoise.mul(displacementStrength)).mul(puffIntensity);

    // ⚡ OPTIMIZATION: TSL Floating Animation (Replaces CPU update)
    // Use world X/Z as phase seed for coherent bobbing
    const floatSpeed = float(0.5);
    const floatAmp = float(0.5);
    const worldPhase = positionWorld.x.mul(0.05).add(positionWorld.z.mul(0.05));
    const floatDisp = sin(uTime.mul(floatSpeed).add(worldPhase)).mul(floatAmp);
    const floatOffset = vec3(0.0, floatDisp, 0.0);

    // === SPRING BOUNCE (player land/jump response) ===
    // High-frequency sine gives that satisfying candy "boing" overshoot
    const bounceRinging = sin(uTime.mul(15.0)).mul(playerStrength).mul(0.15);
    const bounceDisp = vec3(0.0, bounceRinging, 0.0);

    const animatedPos = squishedPos.add(fluffOffset).add(floatOffset).add(bounceDisp);

    // Apply player interaction
    material.positionNode = applyStandardDeformation(animatedPos);

    // 4. Surface Detail (Triplanar Noise for "Cotton" Texture)
    // Adds high-frequency noise to Roughness and slightly to Color
    // Scale 10.0 for micro-detail
    const cottonDetail = triplanarNoise(positionLocal, float(10.0));

    // Modulate roughness: Valleys are rougher (shadowy), Peaks are smoother
    material.roughnessNode = float(0.8).add(cottonDetail.mul(0.2));

    // 5. Lighting & Juice
    // Lightning Flash (Global Event)
    const lightningGlow = uCloudLightningColor.mul(uCloudLightningStrength.mul(3.0));

    // Juicy Rim Light (Replaces standard rim)
    // Reacts to Melody (AudioHigh)
    const rimColor = color(0xFFF8E7); // Warm white
    const rimIntensity = float(0.5);
    const rimPower = float(2.0);
    // Note: createJuicyRimLight adds its own audio pulse and color shift
    const juicyRim = createJuicyRimLight(rimColor, rimIntensity, rimPower, normalWorld);

    // Fake Rainbow Sheen (Optical effect)
    // Only visible when looking at grazing angles (Fresnel)
    const viewDir = normalize(cameraPosition.sub(positionWorld));
    const NdotV = abs(dot(normalWorld, viewDir));
    const fresnel = float(1.0).sub(NdotV).pow(float(2.0));

    const irisR = sin(fresnel.mul(10.0));
    const irisG = sin(fresnel.mul(10.0).add(2.0));
    const irisB = sin(fresnel.mul(10.0).add(4.0));
    const rainbowColor = vec3(irisR, irisG, irisB).mul(0.5).add(0.5);

    const rainbowSheen = rainbowColor.mul(uCloudRainbowIntensity).mul(fresnel);

    // Ambient Occlusion Approximation
    // Darken the bottom of the cloud (y < 0)
    // We use positionLocal.y from before displacement for stability
    const aoGradient = smoothstep(-1.0, 1.0, positionLocal.y); // 0 at bottom, 1 at top
    // PALETTE: Candy cloud pastels — lavender shadow, pink body, cream highlights
    const shadowColor = color(CONFIG.cloud.lavenderShadow);
    const candyBody = color(CONFIG.cloud.pastelTint);
    const highlightColor = color(CONFIG.cloud.creamHighlight);
    const baseColor = mix(shadowColor, mix(candyBody, highlightColor, aoGradient), aoGradient);

    // Apply cotton detail to base color (subtle dirtying)
    const texturedColor = baseColor.mul(float(0.95).add(cottonDetail.mul(0.05)));

    // --- INTEGRATED: Day/Night & Storm Logic ---
    // 1. Darken during storms (uSkyDarkness -> 1.0)
    const stormDarkness = float(1.0).sub(uSkyDarkness.mul(0.8)); // Never fully black, keep some form

    // 2. Tint during Twilight/Night (uTwilight -> 1.0)
    // Shift towards deep blue-grey at night
    const nightTint = color(0x223355);
    const dayTint = color(0xFFFFFF);
    const ambientTint = mix(dayTint, nightTint, uTwilight.mul(0.7)); // 0.7 intensity

    // Final Color Composition
    const lakeTint = mix(color(0xFFFFFF), BiomeUniforms.lakeFeatures.noteColor, BiomeUniforms.lakeFeatures.hueShift.mul(0.35));
    const finalColor = texturedColor.mul(ambientTint).mul(stormDarkness).mul(lakeTint);

    material.colorNode = finalColor;

    // --- VERTICAL ECOSYSTEM: Crystallized Rim for Walkable Clouds ---
    // Walkable clouds (tier 1) get a subtle cyan ice-crystal edge glow
    const walkableFlag = attribute('aIsWalkable', 'float');
    const crystalColor = color(0xE0FFFF);
    const bobPulse = sin(uTime.mul(2.0).add(positionWorld.x.mul(0.1))).mul(0.3).add(0.7);
    const crystalRim = createJuicyRimLight(crystalColor, float(0.8), float(2.5), normalWorld).mul(walkableFlag).mul(bobPulse).add(walkableFlag.mul(melodyGlow));

    // Dim emissive effects during storms too, except lightning
    material.emissiveNode = lightningGlow
        .add(juicyRim.mul(stormDarkness))
        .add(rainbowSheen.mul(stormDarkness))
        .add(crystalRim)
        .add(candyBody.mul(melodyGlow));

    return material;
}

let _sharedCloudMaterial: any = null;
export function getSharedCloudMaterial() {
    if (!_sharedCloudMaterial) {
        _sharedCloudMaterial = createCloudMaterial();
    }
    return _sharedCloudMaterial;
}

import { getCIAdjustedCount } from '../core/config.ts';
import { BiomeUniforms } from '../systems/biome-uniforms.ts';
import { getIcosahedronGeometry } from '../utils/geometry-dedup.ts';
import { batchDistanceCull_c } from '../utils/wasm-batch-animation.ts';
import { foliageGroup } from '../world/state.ts';
import {
    uTime, createJuicyRimLight, uAudioLow, uAudioHigh,
    uWindSpeed, uWindDirection, triplanarNoise, uPlayerPosition, applyStandardDeformation, uPlayerVelocity
} from './index.ts';
import { uSkyDarkness, uTwilight } from './sky.ts';

// --- Cloud Batcher ---
const MAX_PUFFS = getCIAdjustedCount(400, 0.1, 50); // Reduced from 1000 for WebGPU uniform buffer limits (64KB max)
const _scratchMat = new THREE.Matrix4();
const _scratchWorldMat = new THREE.Matrix4();
const _scratchPos = new THREE.Vector3();
const _scratchQuat = new THREE.Quaternion();
const _scratchScale = new THREE.Vector3();
const _scratchObject3D = new THREE.Object3D();

export class CloudBatcher {
    private static instance: CloudBatcher;
    private static walkableInstance: CloudBatcher;

    public static getInstance(): CloudBatcher {
        if (!CloudBatcher.instance) {
            CloudBatcher.instance = new CloudBatcher();
        }
        return CloudBatcher.instance;
    }

    public static getWalkableInstance(): CloudBatcher {
        if (!CloudBatcher.walkableInstance) {
            CloudBatcher.walkableInstance = new CloudBatcher();
        }
        return CloudBatcher.walkableInstance;
    }
    initialized: boolean;
    count: number;
    mesh: THREE.InstancedMesh | null;
    clouds: any[]; // Logic objects
    isWalkableAttribute: THREE.InstancedBufferAttribute | null;
    private _cullPositions: Float32Array | null = null;
    private _cullFlags: Float32Array | null = null;

    constructor() {
        this.initialized = false;
        this.count = 0;
        this.mesh = null;
        this.clouds = [];
        this.isWalkableAttribute = null;
    }

    init() {
        if (this.initialized) return;

        // PALETTE: Increased detail for smoother TSL displacement (1 -> 2)
        // ⚡ OPTIMIZATION: Use shared geometry via registry (deduplicated)
        const puffGeometry = getIcosahedronGeometry(1, 2);

        // ⚡ VERTEX BUFFER BUDGET: position(1) + normal(2) + uv(3) + instanceMatrix(4-7) + aIsWalkable(8)
        // Staying exactly at the 8-buffer WebGPU limit for GTX 1060 compatibility
        this.isWalkableAttribute = new THREE.InstancedBufferAttribute(new Float32Array(MAX_PUFFS), 1);
        puffGeometry.setAttribute('aIsWalkable', this.isWalkableAttribute);

        this.mesh = new THREE.InstancedMesh(puffGeometry, getSharedCloudMaterial(), MAX_PUFFS);
        this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.mesh.castShadow = true;
        this.mesh.receiveShadow = true;
        this.mesh.count = 0;
        this.mesh.frustumCulled = false; // Clouds might be large

        foliageGroup.add(this.mesh);

        this.initialized = true;
        console.log(`[CloudBatcher] Initialized with capacity ${MAX_PUFFS}`);
    }

    register(cloudGroup: any, options: any = {}) {
        if (!this.initialized) this.init();
        if (!this.mesh) return;

        const { scale = 1.0, puffCount = 12 + Math.floor(Math.random() * 8) } = options;

        if (this.count + puffCount > MAX_PUFFS) {
            console.warn(`[CloudBatcher] Max capacity reached (${this.count} / ${MAX_PUFFS})`);
            return;
        }

        const startIndex = this.count;
        this.count += puffCount;

        // Generate Puffs (Local Transforms)
        const puffs: THREE.Matrix4[] = [];

        for (let i = 0; i < puffCount; i++) {
            const radiusSpread = (Math.random() * 2.5 + 0.5) * scale;
            const theta = Math.random() * Math.PI * 2;
            const phi = Math.acos(2 * Math.random() - 1);

            const x = radiusSpread * Math.sin(phi) * Math.cos(theta);
            const z = radiusSpread * Math.sin(phi) * Math.sin(theta);
            let y = radiusSpread * Math.cos(phi);

            y *= 0.6; // Flatten bottom

            _scratchObject3D.position.set(x, y, z);

            const distFromCenter = _scratchObject3D.position.length();
            const sizeBase = 1.0 - (distFromCenter / (3.5 * scale)) * 0.5;
            const puffScaleRandom = 0.5 + Math.random() * 1.0;
            const finalPuffScale = Math.max(0.2, sizeBase * puffScaleRandom * scale);

            _scratchObject3D.scale.setScalar(finalPuffScale);
            _scratchObject3D.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI);
            _scratchMat.compose(_scratchObject3D.position, _scratchObject3D.quaternion, _scratchObject3D.scale);
            puffs.push(_scratchMat.clone());
        }

        cloudGroup.userData.puffs = puffs;
        cloudGroup.userData.batchStart = startIndex;
        cloudGroup.userData.batchCount = puffCount;

        // ⚡ OPTIMIZATION: Copy to pre-allocated state (from createCloud) for dirty checking
        if (!cloudGroup.userData.lastPos) cloudGroup.userData.lastPos = new THREE.Vector3();
        if (!cloudGroup.userData.lastRot) cloudGroup.userData.lastRot = new THREE.Euler();
        cloudGroup.userData.lastPos.copy(cloudGroup.position);
        cloudGroup.userData.lastRot.copy(cloudGroup.rotation);

        // Set walkable attribute for all puffs in this cloud
        const isWalkable = cloudGroup.userData.isWalkable ? 1.0 : 0.0;
        if (this.isWalkableAttribute) {
            for (let i = 0; i < puffCount; i++) {
                this.isWalkableAttribute.setX(startIndex + i, isWalkable);
            }
            this.isWalkableAttribute.needsUpdate = true;
        }

        this.clouds.push(cloudGroup);

        // Initial Update
        this.updateCloudInstance(cloudGroup);
    }

    updateCloudInstance(cloud: any) {
        if (!this.mesh) return;

        const start = cloud.userData.batchStart;
        const count = cloud.userData.batchCount;
        const puffs = cloud.userData.puffs;

        // ⚡ OPTIMIZATION: Bypassed THREE.Object3D overhead in high-frequency batchers!
        // Replaced cloud.updateMatrixWorld() with manual composition.
        _scratchWorldMat.compose(cloud.position, cloud.quaternion, cloud.scale);

        for (let i = 0; i < count; i++) {
            // Global = CloudWorld * PuffLocal
            _scratchMat.multiplyMatrices(_scratchWorldMat, puffs[i]);
            // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
            _scratchMat.toArray(this.mesh.instanceMatrix.array, (start + i) * 16);
        }
    }

                update(delta: number, cameraPos?: THREE.Vector3) {
        if (!this.initialized || !this.mesh) return;

        let needsUpdate = false;

        // 1. Sync capacity
        const cloudCount = this.clouds.length;
        if (!this._cullPositions || this._cullPositions.length < cloudCount * 3) {
            const newCap = Math.max(cloudCount * 2, 256);
            this._cullPositions = new Float32Array(newCap * 3);
            this._cullFlags = new Float32Array(newCap);
        }

        // 2. Pack positions
        for (let i = 0; i < cloudCount; i++) {
            const cloud = this.clouds[i];
            this._cullPositions[i * 3] = cloud.position.x;
            this._cullPositions[i * 3 + 1] = cloud.position.y;
            this._cullPositions[i * 3 + 2] = cloud.position.z;
        }

        // 3. WASM batch distance cull (max distance ~250m)
        if (cameraPos && cloudCount > 0 && this._cullPositions && this._cullFlags) {
            const cullPositions = this._cullPositions;
            const cullFlags = this._cullFlags;
            const cx = cameraPos.x;
            const cy = cameraPos.y;
            const cz = cameraPos.z;
            batchDistanceCull_c(cullPositions, cloudCount, cx, cy, cz, 250 * 250, cullFlags);
        } else if (this._cullFlags) {
            // Default everything to visible if no camera
            for(let i=0; i<cloudCount; i++) this._cullFlags[i] = 1.0;
        }

        // Iterate over clouds
        // ⚡ OPTIMIZATION: Only update moving clouds (e.g. falling or dragged)
        // Static clouds are now animated via TSL (Vertex Shader)
        for (let i = 0; i < cloudCount; i++) {
            const cloud = this.clouds[i];

            // ⚡ OPTIMIZATION: Skip distant clouds completely based on WASM cull flags
            if (!this._cullFlags || this._cullFlags[i] === 0.0) continue;

            // Run Cloud Logic (Sine Wave / Falling)
            // Note: updateFallingClouds in clouds.js handles falling physics on cloud.position externally.
            // Here we just handle the "Animation" callback if it exists.
            if (cloud.userData.onAnimate) {
                cloud.userData.onAnimate(delta, uTime.value);
            }

            // Check for Movement
            // ⚡ OPTIMIZATION: Dirty check against last frame's transform
            // Only update matrix buffer if cloud actually moved (physics/drag)
            // Floating animation is handled by TSL Vertex Shader
            if (cloud.userData.lastPos) {
                 const dx = cloud.position.x - cloud.userData.lastPos.x; const dy = cloud.position.y - cloud.userData.lastPos.y; const dz = cloud.position.z - cloud.userData.lastPos.z; const moved = (dx*dx + dy*dy + dz*dz) > 0.0001;
                 const rotated = Math.abs(cloud.rotation.x - cloud.userData.lastRot.x) > 0.001 ||
                                 Math.abs(cloud.rotation.y - cloud.userData.lastRot.y) > 0.001 ||
                                 Math.abs(cloud.rotation.z - cloud.userData.lastRot.z) > 0.001;

                 if (moved || rotated) {
                     cloud.userData.lastPos.copy(cloud.position);
                     cloud.userData.lastRot.copy(cloud.rotation);
                     this.updateCloudInstance(cloud);
                     needsUpdate = true;
                 }
            }
        }

        if (needsUpdate) {
            this.mesh.count = this.count;
            this.mesh.instanceMatrix.needsUpdate = true;
        }
    }

    dispose(): void {
        if (this.mesh && this.mesh.parent) {
            safeRemoveAndDispose(this.mesh.parent, this.mesh, true);
        }
    }
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import {
    float, vec3, positionLocal, attribute, mix, sin, color,
    instanceIndex, normalLocal, step, length
} from 'three/tsl';
import { CONFIG } from '../core/config.ts';
import { BiomeUniforms } from '../systems/biome-uniforms.ts';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
import { foliageGroup } from '../world/state.ts';
import {
    createStandardNodeMaterial,
    calculateWindSway,
    applyPlayerInteraction,
    applyStandardDeformation,
    uAudioLow,
    uAudioHigh,
    uTime,
    createSugarSparkle,
    createJuicyRimLight,
    getCachedProceduralMaterial
} from './index.ts';
import { uTwilight } from './sky.ts';

const MAX_DANDELIONS = 500;
const SEEDS_PER_HEAD = 24;

// Scratch variables
const _scratchMat = new THREE.Matrix4();
const _scratchMat2 = new THREE.Matrix4(); // ⚡ OPTIMIZATION: Additional scratch matrix
const _scratchScale = new THREE.Vector3();
const _scratchVec3 = new THREE.Vector3(); // ⚡ OPTIMIZATION: Additional scratch vector
const _scratchUp = new THREE.Vector3(0, 1, 0); // ⚡ OPTIMIZATION: Additional scratch vector
const _scratchQuat = new THREE.Quaternion(); // ⚡ OPTIMIZATION: Additional scratch quat

// Colors
const COLOR_STEM = new THREE.Color(0x556B2F); // Olive Drab
const COLOR_STALK = new THREE.Color(0xFFFFFF); // White
const COLOR_TIP = new THREE.Color(0xFFD700);   // Gold

export class DandelionBatcher {
    initialized: boolean;
    count: number;

    mesh: THREE.InstancedMesh | null;
    dummy: THREE.Object3D; // For matrix calculations

    constructor() {
        this.initialized = false;
        this.count = 0;
        this.mesh = null;
        this.dummy = new THREE.Object3D();
    }

    init() {
        if (this.initialized) return;

        // --- 1. Geometry Construction (Unified) ---

        const geometries: THREE.BufferGeometry[] = [];

        // A. Stem
        // Cylinder radius 0.02, height 1.5. Pivot at bottom (translate y=0.75)
        const stemGeo = new THREE.CylinderGeometry(0.02, 0.03, 1.5, 6);
        stemGeo.translate(0, 0.75, 0);

        // Add Attributes for Stem
        const stemCount = stemGeo.attributes.position.count;
        const stemColors = new Float32Array(stemCount * 3);
        const stemPuff = new Float32Array(stemCount * 3); // Zeros (no puff)

        for(let i=0; i<stemCount; i++) {
            stemColors[i*3] = COLOR_STEM.r;
            stemColors[i*3+1] = COLOR_STEM.g;
            stemColors[i*3+2] = COLOR_STEM.b;
            // Puff Dir remains 0,0,0
        }
        stemGeo.setAttribute('color', new THREE.BufferAttribute(stemColors, 3));
        stemGeo.setAttribute('aPuffDir', new THREE.BufferAttribute(stemPuff, 3));
        geometries.push(stemGeo);

        // B. Seeds (Stalk + Tip)
        // Reusable Base Geometries for seeds
        const baseStalkGeo = new THREE.CylinderGeometry(0.005, 0.005, 0.4, 3);
        baseStalkGeo.translate(0, 0.2, 0); // Pivot at bottom

        const baseTipGeo = new THREE.SphereGeometry(0.04, 6, 6);
        // Tip is at the end of the stalk (y=0.4)
        baseTipGeo.translate(0, 0.4, 0);

        // Head Center relative to Stem Pivot
        // Stem is 1.5 high. Head center is at y=1.5
        const headCenterY = 1.5;

        for (let s = 0; s < SEEDS_PER_HEAD; s++) {
            // 1. Calculate Seed Direction
            const phi = Math.acos(-1 + (2 * s) / SEEDS_PER_HEAD);
            const theta = Math.sqrt(SEEDS_PER_HEAD * Math.PI) * phi;

            // ⚡ OPTIMIZATION: Re-use scratch variable to avoid GC spikes
            _scratchVec3.set(
                Math.sin(phi) * Math.cos(theta),
                Math.sin(phi) * Math.sin(theta),
                Math.cos(phi)
            ).normalize();

            // 2. Align Seed (Y-up aligns with Dir)
            // ⚡ OPTIMIZATION: Re-use scratch variable to avoid GC spikes
            _scratchQuat.setFromUnitVectors(_scratchUp, _scratchVec3);
            const m = _scratchMat2;
            m.makeRotationFromQuaternion(_scratchQuat);
            // Translate to Head Center
            m.setPosition(0, headCenterY, 0); // All seeds start from head center

            // 3. Transform & Clone Stalk
            const sGeo = baseStalkGeo.clone();
            sGeo.applyMatrix4(m);

            // Attributes for Stalk
            const sCount = sGeo.attributes.position.count;
            const sColors = new Float32Array(sCount * 3);
            const sPuff = new Float32Array(sCount * 3);

            for(let k=0; k<sCount; k++) {
                sColors[k*3] = COLOR_STALK.r;
                sColors[k*3+1] = COLOR_STALK.g;
                sColors[k*3+2] = COLOR_STALK.b;

                sPuff[k*3] = _scratchVec3.x;
                sPuff[k*3+1] = _scratchVec3.y;
                sPuff[k*3+2] = _scratchVec3.z;
            }
            sGeo.setAttribute('color', new THREE.BufferAttribute(sColors, 3));
            sGeo.setAttribute('aPuffDir', new THREE.BufferAttribute(sPuff, 3));
            geometries.push(sGeo);

            // 4. Transform & Clone Tip
            const tGeo = baseTipGeo.clone();
            tGeo.applyMatrix4(m); // Transforms to head center + rotation

            // Attributes for Tip
            const tCount = tGeo.attributes.position.count;
            const tColors = new Float32Array(tCount * 3);
            const tPuff = new Float32Array(tCount * 3);

            for(let k=0; k<tCount; k++) {
                tColors[k*3] = COLOR_TIP.r;
                tColors[k*3+1] = COLOR_TIP.g;
                tColors[k*3+2] = COLOR_TIP.b;

                tPuff[k*3] = _scratchVec3.x;
                tPuff[k*3+1] = _scratchVec3.y;
                tPuff[k*3+2] = _scratchVec3.z;
            }
            tGeo.setAttribute('color', new THREE.BufferAttribute(tColors, 3));
            tGeo.setAttribute('aPuffDir', new THREE.BufferAttribute(tPuff, 3));
            geometries.push(tGeo);
        }

        // Merge all
        const unifiedGeo = mergeGeometries(geometries);
        // Ensure bounds are correct for culling
        unifiedGeo.computeBoundingSphere();


        // --- 2. Material (TSL Juice) ---

        const mat = getCachedProceduralMaterial('dandelion_batch', 0xFFD700, () => {
            const m = createStandardNodeMaterial({
                side: THREE.FrontSide,
                vertexColors: true, // Use attribute('color')
                roughness: 0.8,
                metalness: 0.0
            });

            // Inputs
            const vColor = attribute('color', 'vec3');
            const vPuffDir = attribute('aPuffDir', 'vec3');

            // 1. Base Color logic
            m.colorNode = vColor;

            // 2. Emission & Roughness Logic
            // Detect Gold Tip: Red > 0.5 (Stalk/Tip) AND Blue < 0.1 (Stem/Tip has low blue? No Stem has 0.18, Stalk has 1.0)
            // Tip: R=1.0, G=0.84, B=0.0
            // Stalk: R=1.0, G=1.0, B=1.0
            // Stem: R=0.33, G=0.42, B=0.18

            // Gold check: High Red, Low Blue.
            const highRed = step(0.5, vColor.r);
            const lowBlue = float(1.0).sub(step(0.1, vColor.b));
            const isGold = highRed.mul(lowBlue);

            // Audio Pulse for Gold
            const pulse = uAudioHigh.mul(3.0);
            // Reduce sugar sparkle density/scale for tips
            const sparkle = createSugarSparkle(normalLocal, float(40.0), float(0.5), float(2.0));

            // Emission: Only on Gold Tips
            const goldEmission = vColor.mul(float(0.2).add(pulse)).add(sparkle);

            // 🎨 PALETTE: Add Juicy Rim Light to dandelion tips
            const rim = createJuicyRimLight(vColor, float(2.0), float(3.0), normalLocal);

            // 🎨 PALETTE: Twilight Glow for dandelion tips
            const glowPhaseOffset = positionLocal.x.add(positionLocal.y).add(positionLocal.z).mul(5.0);
            const idlePulse = sin(uTime.mul(float(CONFIG.glow.glowPulseFrequency)).add(glowPhaseOffset)).mul(float(CONFIG.glow.glowPulseAmplitude)).add(1.0).mul(float(0.5)).mul(uAudioLow.mul(0.3).add(0.7));
            const targetGlowColor = color(CONFIG.glow.glowColorMap['dandelion']);
            const twilightGlowTint = targetGlowColor
                .mul(uTwilight)
                .mul(float(CONFIG.glow.glowIntensityMax))
                .mul(float(0.3).add(idlePulse));
            const biomeTint = BiomeUniforms.musicalFlora.noteColor.mul(BiomeUniforms.musicalFlora.shimmer.mul(0.3));
            const goldEmissionWithTwilight = goldEmission.add(twilightGlowTint).add(biomeTint);

            // Mix: If Gold, use Emission. Else Black.
            m.emissiveNode = mix(vec3(0.0), goldEmissionWithTwilight.add(rim), isGold);

            // Roughness: Gold is shiny (0.2), others are matte (0.8)
            m.roughnessNode = mix(float(0.8), float(0.2), isGold);


            // 3. Animation Logic (Puff + Shake + Sway + Push)

            // A. Puff (Breathing) - Expand along aPuffDir
            const puffOffset = vPuffDir.mul(uAudioLow).mul(0.3);

            // B. Shake (High Freq Vibration) - Only for seeds
            // Use length(vPuffDir) to detect seeds (non-zero puff dir)
            const seedFactor = step(0.1, length(vPuffDir)); // 1.0 if seed, 0.0 if stem

            const shakePhase = float(instanceIndex).add(uTime.mul(20.0));
            const shakeAmt = sin(shakePhase).mul(0.02).mul(uAudioHigh);
            const shakeOffset = vPuffDir.mul(shakeAmt).mul(seedFactor);

            // Apply Local Deformations
            const posPuffed = positionLocal.add(puffOffset).add(shakeOffset);

            // C. Global Sway & Player Interaction
            // Apply to the *entire* geometry (Stem + Seeds)
            // This makes the stem bend, and seeds (being part of same geo) move with it.
            const posFinal = applyStandardDeformation(posPuffed);

            m.positionNode = posFinal;

            return m;
        });


        // --- 3. InstancedMesh Setup ---

        this.mesh = new THREE.InstancedMesh(unifiedGeo, mat, MAX_DANDELIONS);
        this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.mesh.castShadow = true;
        this.mesh.receiveShadow = true;
        this.mesh.count = 0;

        if (foliageGroup) {
            foliageGroup.add(this.mesh);
        }

        this.initialized = true;
        console.log(`[DandelionBatcher] Unified Initialized. 1 Draw Call.`);
    }

    dispose() {
        if (!this.initialized) return;

        [this.mesh].forEach(mesh => {
            if (!mesh) return;
            safeRemoveAndDispose(foliageGroup as unknown as THREE.Scene, mesh);
        });

        this.initialized = false;
        this.count = 0;


    }

    register(logicObject: THREE.Object3D, options: any = {}) {
        if (!this.initialized) this.init();
        if (this.count >= MAX_DANDELIONS) return;

        const i = this.count;
        this.count++;

        // Scale logic
        const scale = options.scale || 1.0;

        // Copy transform from logic object
        _scratchMat.compose(logicObject.position, logicObject.quaternion, logicObject.scale);

        // Apply Scale to the matrix
        _scratchScale.setScalar(scale);
        _scratchMat.scale(_scratchScale);

        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMat.toArray(this.mesh!.instanceMatrix.array, (i) * 16);
        this.mesh!.instanceMatrix.needsUpdate = true;
        this.mesh!.count = this.count;

        // Store batch index on logic object for later updates (like harvesting)
        logicObject.userData.batchIndex = i;
    }

    harvest(batchIndex: number) {
        if (!this.initialized || !this.mesh) return;
        if (batchIndex < 0 || batchIndex >= this.count) return;

        // Just hide it by scaling to zero
        this.dummy.scale.set(0, 0, 0);
        _scratchMat.compose(this.dummy.position, this.dummy.quaternion, this.dummy.scale);
        _scratchMat.toArray(this.mesh.instanceMatrix.array, (batchIndex) * 16);
        this.mesh.instanceMatrix.needsUpdate = true;

        console.log(`[DandelionBatcher] Harvested dandelion #${batchIndex}`);
    }
}

export const dandelionBatcher = new DandelionBatcher();

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import {
    attribute, float, sin, cos, positionLocal, normalLocal,
    exp, rotate, normalize, vec4, vec3, smoothstep, step,
    mix, color, storage, instanceIndex, uniform, Fn, If
} from 'three/tsl';
import { MeshStandardNodeMaterial, StorageInstancedBufferAttribute } from 'three/webgpu';
import { isCIorHeadless } from '../core/config.ts';
import { uTime, uAudioHigh, uWindSpeed, uWindDirection, createSugarSparkle } from './index.ts';

const MAX_SEEDS = 500; // Reduced from 2000 for WebGPU uniform buffer limits
const MAX_SPAWNS_PER_FRAME = 200; // Allow multiple explosions in a single frame

let _seedMesh: THREE.InstancedMesh | null = null;
let _head = 0;

export interface DandelionSeedUserData {
    isDandelionSeedSystem: boolean;
    computeNode: any;
    uSpawnCount: any;
    uSpawnIndex: any;
    stagingSpawnArray: Float32Array;
    stagingVelArray: Float32Array;
    stagingMiscArray: Float32Array;
    stagingSpawnBuffer: StorageInstancedBufferAttribute;
    stagingVelBuffer: StorageInstancedBufferAttribute;
    stagingMiscBuffer: StorageInstancedBufferAttribute;
    maxSpawnsPerFrame: number;
}

// ⚡ OPTIMIZATION: Scratch variables
const _scratchVec3 = new THREE.Vector3();

// WGSL-compatible modulo: x - y * floor(x / y)
const modUint = (x: any, y: any) => {
    return x.remainder(y);
};

// Colors
const COLOR_STALK = new THREE.Color(0xFFFFFF); // White
const COLOR_TIP = new THREE.Color(0xFFD700);   // Gold

export function createDandelionSeedSystem(): THREE.InstancedMesh {
    if (_seedMesh) return _seedMesh;

    // --- 1. Geometry Construction (Stalk + Tip) ---
    // Reusing logic from DandelionBatcher to match visuals

    // A. Stalk
    const stalkGeo = new THREE.CylinderGeometry(0.005, 0.005, 0.4, 3);
    stalkGeo.translate(0, 0.2, 0); // Pivot at bottom

    // B. Tip
    const tipGeo = new THREE.SphereGeometry(0.04, 6, 6);
    tipGeo.translate(0, 0.4, 0); // Tip at end of stalk

    // Add 'color' attribute to distinguish parts
    const stalkCount = stalkGeo.attributes.position.count;
    const tipCount = tipGeo.attributes.position.count;

    const stalkColors = new Float32Array(stalkCount * 3);
    for(let i=0; i<stalkCount; i++) {
        stalkColors[i*3] = COLOR_STALK.r;
        stalkColors[i*3+1] = COLOR_STALK.g;
        stalkColors[i*3+2] = COLOR_STALK.b;
    }
    stalkGeo.setAttribute('color', new THREE.BufferAttribute(stalkColors, 3));

    const tipColors = new Float32Array(tipCount * 3);
    for(let i=0; i<tipCount; i++) {
        tipColors[i*3] = COLOR_TIP.r;
        tipColors[i*3+1] = COLOR_TIP.g;
        tipColors[i*3+2] = COLOR_TIP.b;
    }
    tipGeo.setAttribute('color', new THREE.BufferAttribute(tipColors, 3));

    const geometry = mergeGeometries([stalkGeo, tipGeo]);
    geometry.computeBoundingSphere();


    // Custom Attributes for TSL via Storage Instanced Buffers
    const spawnArray = new Float32Array(MAX_SEEDS * 4);
    const velArray = new Float32Array(MAX_SEEDS * 4);
    const miscArray = new Float32Array(MAX_SEEDS * 4);

    // Initialize to dead
    for(let i=0; i<MAX_SEEDS; i++) {
        spawnArray[i*4+3] = -1000.0;
        miscArray[i * 4 + 0] = Math.random() - 0.5;
        miscArray[i * 4 + 1] = Math.random() - 0.5;
        miscArray[i * 4 + 2] = Math.random() - 0.5;
    }

    const spawnBuffer = new StorageInstancedBufferAttribute(spawnArray, 4);
    const velBuffer = new StorageInstancedBufferAttribute(velArray, 4);
    const miscBuffer = new StorageInstancedBufferAttribute(miscArray, 4);

    // --- 2. TSL Material ---

    const mat = new MeshStandardNodeMaterial({
        vertexColors: true,
        roughness: 0.8,
        metalness: 0.0,
        transparent: true,
        depthWrite: false,
    });

    // Attributes mapped to storage buffers
    const aSpawn = storage(spawnBuffer, 'vec4', spawnBuffer.count);
    const aVelocity = storage(velBuffer, 'vec4', velBuffer.count);
    const aMisc = storage(miscBuffer, 'vec4', miscBuffer.count);

    const spawnPos = aSpawn.element(instanceIndex).xyz;
    const birthTime = aSpawn.element(instanceIndex).w;

    const velocity = aVelocity.element(instanceIndex).xyz;
    const lifeSpan = aVelocity.element(instanceIndex).w;

    const rotAxis = aMisc.element(instanceIndex).xyz;
    const randomPhase = aMisc.element(instanceIndex).w;

    // Time & Age
    const age = uTime.sub(birthTime);
    const lifeProgress = age.div(lifeSpan);
    const isAlive = lifeProgress.greaterThan(0.0).and(lifeProgress.lessThan(1.0));

    // Physics: Floating
    // 1. Initial burst with drag
    const drag = float(1.5);
    const burstDist = velocity.mul(float(1.0).sub(exp(age.mul(drag).negate()))).div(drag);

    // 2. Wind Drift (starts affecting after initial burst slows down)
    const windInfluence = smoothstep(0.5, 2.0, age);
    const windDrift = uWindDirection.mul(uWindSpeed).mul(age.mul(windInfluence));

    // 3. Floating Sway (Sine wave up/down/side)
    const swayFreq = float(2.0);
    const swayAmp = float(0.2);
    const sway = vec3(
        sin(age.mul(swayFreq).add(randomPhase)).mul(swayAmp),
        cos(age.mul(swayFreq.mul(0.7)).add(randomPhase)).mul(swayAmp),
        sin(age.mul(swayFreq.mul(1.3)).add(randomPhase)).mul(swayAmp)
    );

    // 4. Gravity (Very slight downward drift, or updraft)
    const gravity = vec3(0.0, -0.2, 0.0);
    const gravityDrop = gravity.mul(age);

    const particleWorldPos = spawnPos.add(burstDist).add(windDrift).add(sway).add(gravityDrop);


    // Rotation: Tumbling
    const tumbleSpeed = float(2.0);
    const tumbleAngle = age.mul(tumbleSpeed).add(randomPhase);
    const rotatedLocal = rotate(positionLocal, tumbleAngle);

    // Apply Position
    mat.positionNode = particleWorldPos.add(rotatedLocal);

    // Color & Opacity
    const vColor = attribute('color', 'vec3');

    // Sparkle on Gold Tip
    // Detect Gold Tip: Red > 0.5 AND Blue < 0.1
    // Stalk: R=1, G=1, B=1
    // Tip: R=1, G=0.84, B=0
    // Low Blue check works
    const isGold = float(1.0).sub(step(0.1, vColor.b));

    const sparkle = createSugarSparkle(normalLocal, float(40.0), float(0.5), float(2.0));
    const emission = vColor.mul(sparkle).mul(isGold);

    mat.colorNode = vColor;
    mat.emissiveNode = emission;

    // Fade Out
    const opacity = float(1.0).sub(smoothstep(0.7, 1.0, lifeProgress));
    mat.opacityNode = opacity.mul(isAlive);


    // --- 3. Mesh Setup ---

    _seedMesh = new THREE.InstancedMesh(geometry, mat, MAX_SEEDS);
    _seedMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    _seedMesh.count = MAX_SEEDS;
    _seedMesh.frustumCulled = false;
    _seedMesh.castShadow = false;
    _seedMesh.receiveShadow = false;

    // COMPUTE SHADER LOGIC
    const stagingSpawnArray = new Float32Array(MAX_SPAWNS_PER_FRAME * 4);
    const stagingVelArray = new Float32Array(MAX_SPAWNS_PER_FRAME * 4);
    const stagingMiscArray = new Float32Array(MAX_SPAWNS_PER_FRAME * 4);

    const stagingSpawnBuffer = new StorageInstancedBufferAttribute(stagingSpawnArray, 4);
    const stagingVelBuffer = new StorageInstancedBufferAttribute(stagingVelArray, 4);
    const stagingMiscBuffer = new StorageInstancedBufferAttribute(stagingMiscArray, 4);

    const uSpawnCount = uniform(0, 'uint');
    const uSpawnIndex = uniform(0, 'uint');

    const updateCompute: any = (Fn as any)(() => {
        const stageIndex = instanceIndex;

        const sSpawnNode = storage(spawnBuffer, 'vec4', spawnBuffer.count);
        const sVelNode = storage(velBuffer, 'vec4', velBuffer.count);
        const sMiscNode = storage(miscBuffer, 'vec4', miscBuffer.count);

        const inSpawnNode = storage(stagingSpawnBuffer, 'vec4', stagingSpawnBuffer.count).element(stageIndex);
        const inVelNode = storage(stagingVelBuffer, 'vec4', stagingVelBuffer.count).element(stageIndex);
        const inMiscNode = storage(stagingMiscBuffer, 'vec4', stagingMiscBuffer.count).element(stageIndex);

        const spawnCount = uSpawnCount;
        const spawnIdx = uSpawnIndex;

        If(stageIndex.lessThan(spawnCount), () => {
            const targetIdx = modUint(spawnIdx.add(stageIndex), MAX_SEEDS);

            // Write to main buffer
            sSpawnNode.element(targetIdx).assign(inSpawnNode);
            sVelNode.element(targetIdx).assign(inVelNode);
            sMiscNode.element(targetIdx).assign(inMiscNode);
        });
    });

    const computeNode = (updateCompute() as any).compute(MAX_SPAWNS_PER_FRAME);

    const userData: DandelionSeedUserData = {
        isDandelionSeedSystem: true,
        computeNode,
        uSpawnCount,
        uSpawnIndex,
        stagingSpawnArray,
        stagingVelArray,
        stagingMiscArray,
        stagingSpawnBuffer,
        stagingVelBuffer,
        stagingMiscBuffer,
        maxSpawnsPerFrame: MAX_SPAWNS_PER_FRAME
    };

    _seedMesh.userData = userData;

    return _seedMesh;
}

let _currentStageOffset = 0;
let _spawnHeadStart = -1;

export function spawnDandelionExplosion(
    center: THREE.Vector3,
    count: number = 24
) {
    if (!_seedMesh) return;

    const ud = _seedMesh.userData as DandelionSeedUserData;
    if (!ud.isDandelionSeedSystem) return;

    if (_currentStageOffset === 0) {
        _spawnHeadStart = _head;
    }

    const limit = Math.min(count, ud.maxSpawnsPerFrame - _currentStageOffset);
    if (limit <= 0) return;

    const now = ((uTime as any).value !== undefined) ? (uTime as any).value : performance.now() / 1000;

    for(let i=0; i<limit; i++) {
        const offset = (_currentStageOffset + i) * 4;

        // Spread out start position slightly (radius of head)
        // Dandelion head radius approx 0.2
        const r = 0.2 * Math.cbrt(Math.random()); // Uniform sphere distribution
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);

        const dx = r * Math.sin(phi) * Math.cos(theta);
        const dy = r * Math.sin(phi) * Math.sin(theta);
        const dz = r * Math.cos(phi);

        ud.stagingSpawnArray[offset + 0] = center.x + dx;
        ud.stagingSpawnArray[offset + 1] = center.y + dy;
        ud.stagingSpawnArray[offset + 2] = center.z + dz;
        ud.stagingSpawnArray[offset + 3] = now;

        // Velocity: Explode outward from center
        // Add some randomness
        const speed = 2.0 + Math.random() * 3.0;

        // ⚡ OPTIMIZATION: Use scratch vector to avoid allocation in loop
        _scratchVec3.set(dx, dy, dz).normalize();

        ud.stagingVelArray[offset + 0] = _scratchVec3.x * speed;
        ud.stagingVelArray[offset + 1] = _scratchVec3.y * speed;
        ud.stagingVelArray[offset + 2] = _scratchVec3.z * speed;
        ud.stagingVelArray[offset + 3] = 4.0 + Math.random() * 4.0; // Life span (4-8s)

        // Misc: Rotation Axis & Phase
        ud.stagingMiscArray[offset + 0] = Math.random() - 0.5;
        ud.stagingMiscArray[offset + 1] = Math.random() - 0.5;
        ud.stagingMiscArray[offset + 2] = Math.random() - 0.5;
        ud.stagingMiscArray[offset + 3] = Math.random() * Math.PI * 2;
    }

    ud.stagingSpawnBuffer.needsUpdate = true;
    ud.stagingVelBuffer.needsUpdate = true;
    ud.stagingMiscBuffer.needsUpdate = true;

    _currentStageOffset += limit;
    _head = (_head + limit) % MAX_SEEDS;
}

/**
 * Call this every frame from the main render loop to process pending
 * dandelion seed spawns and run the compute shader.
 */
export function updateDandelionSeeds(renderer: any) {
    if (!_seedMesh) return;

    const ud = _seedMesh.userData as DandelionSeedUserData;
    if (!ud.isDandelionSeedSystem || !renderer || !renderer.compute) return;

    if (_currentStageOffset > 0) {
        ud.uSpawnCount.value = _currentStageOffset;
        ud.uSpawnIndex.value = _spawnHeadStart;

        if (!isCIorHeadless()) { renderer.compute(ud.computeNode); }

        _currentStageOffset = 0;
    } else {
        // If no spawns, still need to ensure spawnCount is 0 so the shader doesn't
        // keep writing stale data
        if (ud.uSpawnCount.value > 0) {
            ud.uSpawnCount.value = 0;
        }
    }
}

import * as THREE from 'three';
import {
    time, color, positionLocal, vec3, vec4, attribute, float,
    mix, sin, cos, positionWorld, abs, step
} from 'three/tsl';
import { PointsNodeMaterial } from 'three/webgpu';

/**
 * Creates a magical, audio-reactive particle burst effect triggered upon rare flora discovery.
 * Utilizes TSL to offload physics and animation logic (expansion, fading, twinkling) to the GPU.
 */
export function createDiscoveryEffect() {
    const MAX_PARTICLES = 200;
    const geometry = new THREE.BufferGeometry();

    const positions = new Float32Array(MAX_PARTICLES * 3);
    const velocities = new Float32Array(MAX_PARTICLES * 3);
    const phases = new Float32Array(MAX_PARTICLES); // For twinkle offset
    const spawnTimes = new Float32Array(MAX_PARTICLES); // To track particle life
    const sizes = new Float32Array(MAX_PARTICLES);

    for (let i = 0; i < MAX_PARTICLES; i++) {
        // Initialize at origin (will be repositioned dynamically on trigger)
        positions[i * 3] = 0;
        positions[i * 3 + 1] = 0;
        positions[i * 3 + 2] = 0;

        // Spherical velocity distribution
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(Math.random() * 2 - 1);
        const speed = 2.0 + Math.random() * 3.0; // Explosion outward speed

        velocities[i * 3] = Math.sin(phi) * Math.cos(theta) * speed;
        velocities[i * 3 + 1] = Math.cos(phi) * speed;
        velocities[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * speed;

        phases[i] = Math.random() * Math.PI * 2;
        spawnTimes[i] = -999.0; // Initialize as inactive (spawn time far in past)
        sizes[i] = 0.5 + Math.random() * 1.5;
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geometry.setAttribute('aVelocity', new THREE.BufferAttribute(velocities, 3));
    geometry.setAttribute('aPhase', new THREE.BufferAttribute(phases, 1));
    geometry.setAttribute('aSpawnTime', new THREE.BufferAttribute(spawnTimes, 1));
    geometry.setAttribute('aSize', new THREE.BufferAttribute(sizes, 1));

    function ensureUVAttribute(geometry: THREE.BufferGeometry) {
        if (!geometry.attributes.uv && geometry.attributes.position) {
            const count = geometry.attributes.position.count;
            const uvs = new Float32Array(count * 2);
            geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
        }
    }
    ensureUVAttribute(geometry);

    // Create the Node Material for the particle burst
    const material = new PointsNodeMaterial({
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
    });

    // --- TSL Logic ---

    // TSL Attributes mapping
    const aVelocity = attribute('aVelocity', 'vec3');
    const aPhase = attribute('aPhase', 'float');
    const aSpawnTime = attribute('aSpawnTime', 'float');
    const aSize = attribute('aSize', 'float');

    // Calculate age of each particle based on current time
    const age = time.sub(aSpawnTime);

    // Life duration for particles is ~2.0 seconds
    const maxLife = float(2.0);

    // Normalize age between 0.0 and 1.0. If age < 0, it means it's inactive (or hasn't spawned)
    const normalizedAge = age.div(maxLife);

    // Physics Simulation (GPU Side):
    // Position = Initial_Position + Velocity * age * drag
    // Here we apply a simple linear expansion that slows down over time (simulated drag)
    const expansionCurve = age.sub(age.pow(2.0).mul(0.2)); // Slows down
    const offset = aVelocity.mul(expansionCurve);

    // Final vertex position
    material.positionNode = positionLocal.add(offset);

    // Size: Starts large, shrinks as it gets older
    // Base size multiplied by fade curve
    const sizeMultiplier = float(1.0).sub(normalizedAge);
    // Multiply by the original base size for the particle
    (material as any).sizeNode = aSize.mul(20.0).mul(sizeMultiplier);

    // Color Logic: Magical Cyan/Pink shift and twinkle
    // Shift color over particle life from Cyan (0x00FFFF) to Pink (0xFF69B4)
    const colorCyan = color(0x00ffff);
    const colorPink = color(0xff69b4);

    // Twinkle effect using sin combined with the phase attribute
    const twinkle = sin(time.mul(10.0).add(aPhase)).mul(0.5).add(0.5); // 0.0 to 1.0

    // Mix color over age
    const baseColor = mix(colorCyan, colorPink, normalizedAge);

    // Fade out completely when age > maxLife
    // Ensure visibility is 0 if not yet triggered (age < 0) or dead (age > 1.0)
    // We can use a step function or smoothstep for fading.
    // Opacity peaks instantly, then fades out over maxLife
    const opacity = float(1.0).sub(normalizedAge).mul(twinkle);
    // Clamp to 0 if outside active window
    const isActive = step(float(0.0), normalizedAge).mul(step(normalizedAge, float(1.0)));

    material.colorNode = vec4(baseColor, opacity.mul(isActive));

    const mesh = new THREE.Points(geometry, material);
    mesh.frustumCulled = false; // Always render when triggered

    // Trigger mechanism
    const trigger = (position: THREE.Vector3, currentTime: number) => {
        // Update all particles to spawn at the new position and time
        const posAttr = geometry.attributes.position as THREE.BufferAttribute;
        const spawnTimeAttr = geometry.attributes.aSpawnTime as THREE.BufferAttribute;

        for (let i = 0; i < MAX_PARTICLES; i++) {
            posAttr.setXYZ(i, position.x, position.y, position.z);
            spawnTimeAttr.setX(i, currentTime);
        }

        posAttr.needsUpdate = true;
        spawnTimeAttr.needsUpdate = true;
    };

    return { mesh, trigger };
}

import * as THREE from 'three';
import { time, vec3, vec4, positionLocal, length, sin, cos, color as tslColor, attribute, float, uniform, mix, smoothstep, color, positionWorld, normalWorld, floor } from 'three/tsl';
import { MeshStandardNodeMaterial, PointsNodeMaterial } from 'three/webgpu';

// WGSL-compatible modulo: x - y * floor(x / y)
// Note: Converts inputs to float first since WGSL floor() only works on floats
const modFloat = (x: any, y: any) => {
    const xf = float(x);
    const yf = float(y);
    return xf.sub(yf.mul(xf.div(yf).floor()));
};
import { registerReactiveMaterial, attachReactivity, CandyPresets, uTime, uAudioLow, uAudioHigh, createJuicyRimLight, createSugarSparkle } from './index.ts';
import { uTwilight, uHorizonColor } from './sky.ts';

export interface FloatingOrbOptions {
    color?: number;
    size?: number;
}

export interface KickDrumGeyserOptions {
    color?: number;
    maxHeight?: number;
}

export function createMelodyLake(width = 200, depth = 200) {
    const geo = new THREE.PlaneGeometry(width, depth, 64, 64);
    geo.rotateX(-Math.PI / 2);

    const mat = new MeshStandardNodeMaterial({
        roughness: 0.1,
        metalness: 0.5,
        transparent: true,
        opacity: 0.8,
    });

    const pos = positionLocal;
    const dist = length(pos.xz);

    // 🎨 PALETTE: Audio-Reactive Waves
    // Bass (uAudioLow) drives the height of the waves, creating a pulsing ocean
    const bassPulse = float(1.0).add(uAudioLow.mul(1.5));

    // Complex, overlapping sine waves for a more natural, fluid look
    const ripplePhase = dist.mul(0.5).sub(uTime.mul(2.0));
    const ripple = sin(ripplePhase).mul(0.2).mul(bassPulse);

    const wavePhaseX = pos.x.mul(0.2).add(uTime);
    const wavePhaseZ = pos.z.mul(0.2).add(uTime.mul(0.8));
    const wave = sin(wavePhaseX).mul(cos(wavePhaseZ)).mul(0.5).mul(bassPulse);

    const totalWaveHeight = ripple.add(wave);

    mat.positionNode = vec3(pos.x, pos.y.add(totalWaveHeight), pos.z);

    // 🎨 PALETTE: Bioluminescent / Neon Depth Colors
    // The crests of the waves glow bright cyan/neon, the troughs are deep blue
    const normalizedHeight = smoothstep(float(-0.5), float(0.8), totalWaveHeight);

    const deepColor = color(0x0A2E3F); // Deep water
    const crestColor = color(0x00FFFF); // Neon Cyan crests

    // Mix color based on wave height
    const baseWaterColor = mix(deepColor, crestColor, normalizedHeight);

    // 🎨 PALETTE: Sunset Pink Blend
    // Mix the water color with the horizon color based on twilight, enhancing the pinkish glow during sunset/sunrise
    const sunsetTint = mix(baseWaterColor, uHorizonColor, uTwilight.mul(0.6));
    const waterColor = sunsetTint;

    mat.colorNode = waterColor;

    // 🎨 PALETTE: Audio-Reactive Emissive Glow (Highs/Melody)
    // When the melody hits (uAudioHigh), the wave crests sparkle and glow
    const audioGlow = uAudioHigh.mul(normalizedHeight).mul(2.0);

    // Add a juicy rim light that reacts to the music and stands out at night
    const rimLight = createJuicyRimLight(waterColor, float(1.5), float(4.0), null);

    // Combine base glow, audio response, rim light, and boost at night (uTwilight)
    const baseGlow = crestColor.mul(normalizedHeight).mul(0.3);
    const nightBoost = uTwilight.mul(0.5);

    mat.emissiveNode = baseGlow.add(audioGlow).add(rimLight).mul(float(1.0).add(nightBoost));

    const mesh = new THREE.Mesh(geo, mat);
    mesh.receiveShadow = true;
    mesh.userData.type = 'lake';

    return mesh;
}

export function createFloatingOrb(options: FloatingOrbOptions = {}) {
    const { color: hexColor = 0x87CEEB, size = 0.5 } = options;
    const geo = new THREE.SphereGeometry(size, 8, 8);

    // Base Gummy Material
    const mat = CandyPresets.Gummy(hexColor, { emissive: hexColor, emissiveIntensity: 0.8 });

    // --- PALETTE: TSL Audio-Reactive Juice ---
    // 1. Audio-Reactive Squash & Stretch (Heartbeat/jelly feel)
    // Pulse with the kick drum
    const squash = smoothstep(0.0, 1.0, uAudioLow).pow(float(2.0)).mul(0.4);
    const scaleY = float(1.0).sub(squash);
    const scaleXZ = float(1.0).add(squash.mul(0.5));

    // 2. Idle Float & Spin
    // Organic floating offset using world position to desync instances
    const phaseX = positionWorld.x.mul(0.5);
    const phaseZ = positionWorld.z.mul(0.5);
    const floatOffset = sin(uTime.mul(2.0).add(phaseX).add(phaseZ)).mul(0.1);

    const animatedPos = vec3(
        positionLocal.x.mul(scaleXZ),
        positionLocal.y.mul(scaleY),
        positionLocal.z.mul(scaleXZ)
    ).add(vec3(0.0, floatOffset, 0.0));
    mat.positionNode = animatedPos;

    // 3. Audio-Reactive Emissive Pulse & Rim Light
    // High frequency triggers bright flashes
    const baseGlowColor = tslColor(hexColor);
    // 🎨 PALETTE: Make flash non-linear so it pops more
    const flashIntensity = uAudioHigh.pow(float(1.5)).mul(2.5);
    const baseEmissive = baseGlowColor.mul(float(0.5).add(flashIntensity));

    // Juicy Rim Light for that "Neon/Bioluminescent" magic feel
    const rimLight = createJuicyRimLight(baseGlowColor, float(1.5), float(3.0), null);

    // 🎨 PALETTE: Add Sugar Sparkle for magical dust effect
    const sparkle = createSugarSparkle(normalWorld, float(25.0), float(0.2), float(2.0));

    mat.emissiveNode = baseEmissive.add(rimLight).add(sparkle);

    registerReactiveMaterial(mat);

    const orb = new THREE.Mesh(geo, mat);
    orb.castShadow = true;
    // CPU animation replaced by TSL positionNode for better performance and juice
    // orb.userData.animationType = 'float';
    orb.userData.animationOffset = Math.random() * 10;
    orb.userData.type = 'orb';

    const light = new THREE.PointLight(hexColor, 0.5, 4.0);
    orb.add(light);

    return attachReactivity(orb);
}

export function createFloatingOrbCluster(x: number, z: number) {
    const cluster = new THREE.Group();
    cluster.position.set(x, 5, z);
    for (let i = 0; i < 3; i++) {
        const orb = createFloatingOrb();
        orb.position.set(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5);
        cluster.add(orb);
    }
    return cluster;
}

