import * as THREE from 'three';
import { texture, vec4, color, vec3, uv, mx_noise_float, positionLocal, mix, smoothstep, normalLocal } from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { fluidSystem } from '../systems/fluid_system.ts';
import { uTime } from './index.ts';

export function createFluidFog(width = 100, depth = 100) {
    // High resolution grid to allow for vertex displacement based on fluid density/velocity
    const geometry = new THREE.PlaneGeometry(width, depth, 128, 128);
    geometry.rotateX(-Math.PI / 2); // Flat on ground

    // ⚡ OPTIMIZATION: Use MeshStandardNodeMaterial for lighting integration instead of flat Basic material
    // This allows the fog to receive shadows, react to weather colors, and fit the "Cute Clay" aesthetic.
    const material = new MeshStandardNodeMaterial();
    material.transparent = true;
    material.depthWrite = false;
    material.blending = THREE.AdditiveBlending;
    material.side = THREE.DoubleSide;

    // Base colors matching the "Mint/Pink" Candy World palette
    const mistColor = color(0x44FFCC);
    const hotColor = color(0xFF66B2); // Mix in pink for high density areas

    // TSL Logic
    // Sample the fluid texture from the C++ solver.
    // The texture is RedFormat, so .r contains the density value (0.0 to 1.0+)
    const densityRaw = texture(fluidSystem.texture);
    const density = densityRaw.r;

    // Apply some slow ambient noise to the UVs to make the fog feel alive even when still
    const noiseUV = uv().add(uTime.mul(0.05));
    const ambientNoise = mx_noise_float(noiseUV.mul(10.0));

    // Add procedural billowing based on density
    // High density areas will bulge upwards physically
    const heightDisplacement = density.mul(3.0).add(ambientNoise.mul(0.5));

    // Smoothstep the density to create defined edges rather than a linear fade
    const clampedDensity = smoothstep(0.0, 1.0, density.mul(2.0));

    // Mix colors based on density (hotter pink in the dense centers, mint on the edges)
    const finalColor = mix(mistColor, hotColor, clampedDensity);

    // Alpha depends on density with some noise breakup
    // Reduce alpha at edges of the geometry
    const edgeFadeX = uv().x.sub(0.5).abs().mul(2.0).oneMinus();
    const edgeFadeY = uv().y.sub(0.5).abs().mul(2.0).oneMinus();
    const edgeFade = edgeFadeX.mul(edgeFadeY).clamp(0.0, 1.0);

    const alpha = density.mul(2.5).add(ambientNoise.mul(0.2)).mul(edgeFade).clamp(0.0, 0.8);

    // Apply final nodes
    material.colorNode = finalColor;
    material.opacityNode = alpha;

    // Vertex displacement: Bulge up based on density
    const newPos = positionLocal.add(normalLocal.mul(heightDisplacement));
    material.positionNode = newPos;

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.y = 0.2; // Slightly above ground
    mesh.userData.type = 'fluid_fog';

    // Frustum culling bound expansion due to vertex displacement
    mesh.geometry.computeBoundingBox();
    if (mesh.geometry.boundingBox) {
        mesh.geometry.boundingBox.max.y += 5.0; // Allow for up to 5 units of vertical displacement
        mesh.geometry.boundingBox.min.y -= 1.0;
        mesh.geometry.computeBoundingSphere();
    }

    return mesh;
}

// src/foliage/foliage-materials.ts
// Foliage material instances - pre-configured materials for all foliage types

import * as THREE from 'three';
import { color, float, vec3, positionLocal, positionWorld, uv, sin, pow, abs, smoothstep, add } from 'three/tsl';
import { mx_noise_float } from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
    CandyPresets,
    createUnifiedMaterial,
    createStandardNodeMaterial,
    calculateWindSway,
    calculateFlowerBloom,
    createJuicyRimLight,
    applyPlayerInteraction,
    applyStandardDeformation,
    uTime,
    uAudioLow,
    uWindSpeed,
    uWindDirection
} from './material-core.ts';

// --- MATERIAL DEFINITIONS ---

export const foliageMaterials: { [key: string]: THREE.Material | THREE.Material[] } = {
    // Basic organics
    // PALETTE UPDATE: Apply Interaction + Wind to standard Stem
    stem: (() => {
        const mat = CandyPresets.Clay(0x66AA55);
        // Combine Player Push + Wind Sway
        mat.positionNode = applyStandardDeformation(positionLocal);

        // 🎨 PALETTE: Add Juicy Rim Light to stem so it pops against dark backgrounds
        const audioRimIntensity = float(1.0).add(uAudioLow.mul(0.5));
        const rimLight = createJuicyRimLight(color(0x66AA55), audioRimIntensity, float(3.0), null);
        mat.emissiveNode = add(mat.emissiveNode ?? color(0x000000), rimLight);

        return mat;
    })(),

    get flowerCenter() { return CandyPresets.Velvet(0x442211, { audioReactStrength: 0.5 }); },
    get vine() { return CandyPresets.Clay(0x558833); },
    get wood() { return createUnifiedMaterial(0x8B4513, { roughness: 0.9, bumpStrength: 0.3, noiseScale: 3.0 }); },
    get leaf() { return createUnifiedMaterial(0x228B22, { roughness: 0.6, side: THREE.DoubleSide, bumpStrength: 0.1 }); },

    // Restored/Upgraded Materials
    // PALETTE UPDATE: Apply Interaction + Wind to Flower Stem
    flowerStem: (() => {
        const mat = CandyPresets.Clay(0x66AA55);
        // Combine Player Push + Wind Sway
        mat.positionNode = applyStandardDeformation(positionLocal);

        // 🎨 PALETTE: Add Juicy Rim Light to flowerStem so it pops against dark backgrounds
        const audioRimIntensity = float(1.0).add(uAudioLow.mul(0.5));
        const rimLight = createJuicyRimLight(color(0x66AA55), audioRimIntensity, float(3.0), null);
        mat.emissiveNode = add(mat.emissiveNode ?? color(0x000000), rimLight);

        return mat;
    })(),

    get lotusRing() { return CandyPresets.Gummy(0xFFFFFF); },
    get opticCable() { return createUnifiedMaterial(0x111111, { roughness: 0.4 }); },
    get opticTip() { return createStandardNodeMaterial({
        color: 0xFFFFFF,
        emissive: 0xFF00FF,
        emissiveIntensity: 1.0,
        roughness: 0.2
    }); },

    // Special Effects
    // PALETTE UPDATE: Volumetric God Ray (TSL)
    lightBeam: (() => {
        const mat = new MeshStandardNodeMaterial({
            color: 0xFFFFFF,
            transparent: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false,
            roughness: 1.0,
            side: THREE.DoubleSide
        });

        // 1. Edge Fade (Cylinder UV x wraps 0..1)
        // Center (0.5) is bright, Edges (0.0/1.0) are transparent
        const beamCore = float(1.0).sub(abs(uv().x.sub(0.5)).mul(2.0));
        const softBeam = smoothstep(0.0, 0.5, beamCore);

        // 2. Vertical Fade (Top/Bottom)
        const verticalFade = smoothstep(0.0, 0.2, uv().y).mul(float(1.0).sub(smoothstep(0.8, 1.0, uv().y)));

        // 3. Dust Motes (Rising Noise)
        const dustSpeed = vec3(0.0, uTime.mul(0.2), 0.0);
        const dustPos = positionLocal.mul(2.0).add(dustSpeed);
        const dust = mx_noise_float(dustPos).mul(0.5).add(0.5); // 0..1

        // 4. Audio Pulse (Breathing)
        const pulse = sin(uTime.mul(2.0)).mul(0.1).add(0.9); // Idle breath
        const audioBoost = uAudioLow.mul(0.5); // Bass boost
        const totalPulse = pulse.add(audioBoost);

        // Combine
        const opacity = softBeam.mul(verticalFade).mul(dust).mul(totalPulse).mul(0.3);

        mat.opacityNode = opacity;
        // Use Node Color (can be overridden by instance color)
        mat.colorNode = color(0xFFFFFF);
        mat.emissiveNode = color(0xFFFFFF).mul(opacity);

        return mat;
    })(),

    mushroomStem: (() => {
        const mat = CandyPresets.Clay(0xF5F5DC);
        // ⚡ TSL Shaping: Apply curved profile to standard cylinder
        // Profile: r = 1.0 - (t - 0.3)^2 * 0.5
        const t = positionLocal.y; // unitCylinder is 0..1 in Y
        const curve = float(1.0).sub( pow(t.sub(0.3), 2.0).mul(0.5) );
        const newPos = vec3(positionLocal.x.mul(curve), positionLocal.y, positionLocal.z.mul(curve));

        // PALETTE UPDATE: Apply Interaction to Shaped Stem
        mat.positionNode = applyStandardDeformation(newPos);

        // Recalculate Normal: N = (x, -r'(y), z) -> (x, y-0.3, z)
        const ny = t.sub(0.3);
        const newNormal = vec3(positionLocal.x, ny, positionLocal.z).normalize();
        mat.normalNode = newNormal;

        // 🎨 PALETTE: Add Juicy Rim Light to mushroomStem so it pops against dark backgrounds
        const audioRimIntensity = float(1.0).add(uAudioLow.mul(0.5));
        const rimLight = createJuicyRimLight(color(0xF5F5DC), audioRimIntensity, float(3.0), mat.normalNode);
        mat.emissiveNode = add(mat.emissiveNode ?? color(0x000000), rimLight);

        return mat;
    })(),

    // Diverse Mushroom Caps
    get mushroomCap() {
        return [
            CandyPresets.Clay(0xFF6B6B),        // Matte Red
            CandyPresets.Gummy(0xFF9F43),       // Orange Gummy
            CandyPresets.Sugar(0xFDCB6E),       // Sugared Yellow
            CandyPresets.Crystal(0x54A0FF),     // Blue Crystal
            CandyPresets.OilSlick(0x222222)             // Rare Oil
        ];
    },

    get mushroomCheek() { return CandyPresets.Velvet(0xFFAACC); },

    // Upgraded parts
    get mushroomGills() { return CandyPresets.Clay(0x332211, { side: THREE.DoubleSide }); },
    get mushroomSpots() { return CandyPresets.Sugar(0xFFFFFF); },

    get flowerPetal() {
        return [
            CandyPresets.Velvet(0xFF69B4, { side: THREE.DoubleSide, audioReactStrength: 1.0, deformationNode: calculateFlowerBloom(positionLocal) }),
            CandyPresets.Gummy(0xFFD700, { side: THREE.DoubleSide, audioReactStrength: 0.8, deformationNode: calculateFlowerBloom(positionLocal) }),
            CandyPresets.Crystal(0xFFFFFF, { side: THREE.DoubleSide, audioReactStrength: 0.5, deformationNode: calculateFlowerBloom(positionLocal) }),
            CandyPresets.Sugar(0x9933FF, { side: THREE.DoubleSide, audioReactStrength: 1.0, deformationNode: calculateFlowerBloom(positionLocal) }),
        ];
    },

    // Faces
    get eye() { return CandyPresets.Gummy(0xFFFFFF); }, // Wet eyes
    get pupil() { return new MeshStandardNodeMaterial({ color: 0x000000, roughness: 0.0 }); },
    get mouth() { return CandyPresets.Clay(0x2D3436); },
    get clayMouth() { return CandyPresets.Clay(0x2D3436); }
};

// src/foliage/foliage-reactivity.ts
// Reactivity system for foliage objects - handles animated/interactive foliage registration

import * as THREE from 'three';
import { _scratchVec1 } from './material-core.ts';

// --- Reactive Objects Registry ---
export const reactiveObjects: THREE.Object3D[] = [];
let reactivityCounter = 0; 
export const reactiveMaterials: THREE.Material[] = [];
export const _foliageReactiveColor = new THREE.Color(); 

export function registerReactiveMaterial(mat: THREE.Material) { 
    if (!reactiveMaterials.includes(mat)) {
        reactiveMaterials.push(mat);
    }
}

export function pickAnimation(types: string[]) { 
    return types[Math.floor(Math.random() * types.length)]; 
}

export function attachReactivity<T extends THREE.Object3D>(group: T, options: any = {}): T {
    reactiveObjects.push(group);
    group.userData.reactivityType = options.type || group.userData.reactivityType || 'flora';
    if (typeof group.userData.reactivityId === 'undefined') group.userData.reactivityId = reactivityCounter++;
    const light = options.lightPreference || {};
    group.userData.minLight = (typeof light.min !== 'undefined') ? light.min : (group.userData.minLight ?? 0.0);
    group.userData.maxLight = (typeof light.max !== 'undefined') ? light.max : (group.userData.maxLight ?? 1.0);
    return group;
}

export function cleanupReactivity(object: THREE.Object3D) {
    const index = reactiveObjects.indexOf(object);
    if (index > -1) reactiveObjects.splice(index, 1);
}

// --- VALIDATION HELPERS ---

export function validateFoliageMaterials(foliageMaterials?: { [key: string]: THREE.Material | THREE.Material[] }) {
    // Use provided materials or return false - caller should provide materials
    const materials = foliageMaterials;

    if (!materials) {
        console.error('[Foliage] validateFoliageMaterials: No foliageMaterials provided.');
        return false;
    }

    const getFallbackMaterial = () => {
        return new THREE.MeshStandardMaterial({ color: 0xFF00FF });
    };
    const required = ['lightBeam', 'mushroomCap', 'opticTip', 'lotusRing', 'flowerStem'];
    let safe = true;
    for (let i = 0; i < required.length; i++) {
        const key = required[i];
        if (!materials[key]) {
            console.error(`[Foliage] Missing material: ${key}. Using fallback.`);
            materials[key] = getFallbackMaterial();
            safe = false;
        }
    }
    return safe;
}

export function validateNodeGeometries(scene: THREE.Object3D) {
    // Aggregate warnings to avoid spamming the console when many small geometries are missing attributes.
    const missingPosition: any[] = [];

    function inferVertexCount(geo: THREE.BufferGeometry) {
        if (!geo) return 0;
        if (geo.index) return geo.index.count;
        let maxCount = 0;
        for (const key in geo.attributes) {
            if (Object.prototype.hasOwnProperty.call(geo.attributes, key)) {
                const a = geo.attributes[key];
                if (a && a.count > maxCount) maxCount = a.count;
            }
        }
        return maxCount;
    }

    function getObjectPath(obj: THREE.Object3D | null) {
        const parts = [];
        let cur = obj;
        while (cur) {
            const name = cur.name || cur.type || cur.uuid;
            parts.unshift(name);
            cur = cur.parent;
        }
        return parts.join('/') || (obj ? obj.uuid : '');
    }

    scene.traverse((obj: THREE.Object3D) => {
        if ((obj as THREE.Mesh).isMesh || (obj as THREE.Points).isPoints) {
            const geo = (obj as THREE.Mesh).geometry;
            if (geo) {
                // Attempt to auto-patch a missing position attribute when we can infer a vertex count.
                if (!geo.attributes.position) {
                    let preAttrKeys = '';
                    if (geo.attributes) {
                        for (const key in geo.attributes) {
                            if (preAttrKeys.length > 0) preAttrKeys += ', ';
                            preAttrKeys += key;
                        }
                    }
                    if (preAttrKeys === '') preAttrKeys = '(none)';
                    const inferred = inferVertexCount(geo);
                    if (inferred > 0) {
                        const positions = new Float32Array(inferred * 3);
                        geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
                    } else {
                        try {
                            // ⚡ OPTIMIZATION: Reuse scratch vector to prevent GC spikes during validation
                            const worldPos = _scratchVec1;
                            obj.getWorldPosition(worldPos);
                            const positions = new Float32Array(3);
                            positions[0] = worldPos.x; positions[1] = worldPos.y; positions[2] = worldPos.z;
                            geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));

                            const normals = new Float32Array(3);
                            normals[0] = 0; normals[1] = 1; normals[2] = 0;
                            geo.setAttribute('normal', new THREE.BufferAttribute(normals, 3));

                            obj.userData._patchedByValidate = true;

                            const name = obj.name || 'Unnamed';
                            const type = obj.userData?.type || 'Unknown Type';
                            let attrKeys = '';
                            if (geo.attributes) {
                                for (const key in geo.attributes) {
                                    if (attrKeys.length > 0) attrKeys += ', ';
                                    attrKeys += key;
                                }
                            }
                            if (attrKeys === '') attrKeys = '(none)';
                            const geoType = geo.type || geo.constructor?.name || 'UnknownGeo';

                            let anc = obj.parent;
                            let ancestorType = null;
                            let ancestorName = null;
                            let depth = 0;
                            while (anc && depth < 10) {
                                if (anc && anc.userData && anc.userData.type) {
                                    ancestorType = anc.userData.type;
                                    ancestorName = anc.name || anc.userData.type;
                                    break;
                                }
                                anc = anc && anc.parent;
                                depth++;
                            }
                            missingPosition.push({ name, type, obj, geoType, attrKeys, path: getObjectPath(obj), patched: true, ancestorType, ancestorName, preAttrKeys });
                        } catch (err) {
                            const name = obj.name || 'Unnamed';
                            const type = obj.userData?.type || 'Unknown Type';
                            let attrKeys = '';
                            if (geo.attributes) {
                                for (const key in geo.attributes) {
                                    if (attrKeys.length > 0) attrKeys += ', ';
                                    attrKeys += key;
                                }
                            }
                            if (attrKeys === '') attrKeys = '(none)';
                            const geoType = geo.type || geo.constructor?.name || 'UnknownGeo';
                            missingPosition.push({ name, type, obj, geoType, attrKeys, path: getObjectPath(obj), preAttrKeys });
                        }
                    }
                }

                if (!geo.attributes.normal) {
                    const count = geo.attributes.position ? geo.attributes.position.count : inferVertexCount(geo);
                    if (count > 0) {
                        const normals = new Float32Array(count * 3);
                        for (let i = 0; i < count * 3; i += 3) { normals[i] = 0; normals[i + 1] = 1; normals[i + 2] = 0; }
                        geo.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
                    }
                }
            }
        }
    });

    if (missingPosition.length > 0) {
        const header = `[TSL] ${missingPosition.length} geometries missing 'position' attribute.`;

        // ⚡ OPTIMIZATION: Replaced .slice().map() and .filter() with manual loops to prevent GC spikes in hot initialization path.
        let examplesStr = '';
        const limit = Math.min(10, missingPosition.length);
        for (let i = 0; i < limit; i++) {
            const m = missingPosition[i];
            if (i > 0) examplesStr += '; ';
            examplesStr += `${m.path} -> ${m.name}(${m.type}) [${m.geoType}] attrs: ${m.attrKeys}`;
            if (m.patched) examplesStr += ' (patched)';
            if (m.ancestorType) examplesStr += ` ancestor:${m.ancestorType}`;
        }

        let patchedCount = 0;
        for (let i = 0; i < missingPosition.length; i++) {
            if (missingPosition[i].patched) patchedCount++;
        }

        const more = missingPosition.length > 10 ? ` + ${missingPosition.length - 10} more` : '';
        let msg = `${header} Examples: ${examplesStr}${more}.`;
        if (patchedCount > 0) {
            msg += ` Note: ${patchedCount} were auto-patched with minimal position/normal data; consider fixing the source constructor.`;
        }
        console.warn(msg);
    }
}

// Glass Mycelium Mushroom Batcher — glossy candy-glass fungi with a bioluminescent
// vein network, fake SSS along the stem, circadian night-glow and bass-driven cap ripple.
//
// Companion biome to the Luminous Plants around Melody Lake: it deliberately reuses the
// `luminous_plants` music binding (LuminousPlantUniforms.intensity / noteColor) so the
// mycelium pulses on the same tracker channel without any new music-bindings wiring.
//
// One InstancedMesh, one glass material => a single draw call for the whole grove.

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import {
    color, float, vec3, attribute, positionLocal, normalLocal,
    sin, mix, smoothstep, normalWorld, positionWorld, cameraPosition, normalize, dot,
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { CONFIG, getCIAdjustedCount } from '../core/config.ts';
import {
    LuminousPlantUniforms,
    luminousPlantsNoteColorNode,
    uCircadianPhase,
    uCircadianPoseOffset,
    circadianNightGlowMult,
} from '../systems/biome-uniforms.ts';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
import { foliageGroup } from '../world/state.ts';
import { registerReactiveMaterial } from './foliage-reactivity.ts';
import {
    CandyPresets,
    uTime,
    uAudioLow,
    createJuicyRimLight,
    applyStandardDeformation,
} from './material-core.ts';

/** Visual Impact: cyan candy-glass base tint (cool bioluminescent fungus). */
const GLASS_BASE_COLOR = 0x4DE2FF;
const MAX_GLASS_MUSHROOMS = getCIAdjustedCount(600, 0.1, 50);

// Baked proportions: wider cap, shorter stem (the brief's biomorphic silhouette).
const STEM_H = 0.7;
const CAP_Y = STEM_H * 0.92;

let _sharedGlassGeo: THREE.BufferGeometry | null = null;
const _scratchMatrix = new THREE.Matrix4();

function getGlassMushroomGeometry(): THREE.BufferGeometry {
    if (!_sharedGlassGeo) {
        // Short, slightly-bulbous stem anchored at the ground (y = 0).
        const stem = new THREE.CylinderGeometry(0.16, 0.28, STEM_H, 14, 1);
        stem.translate(0, STEM_H * 0.5, 0);

        // Wide, flattened dome cap — only the upper hemisphere, squashed on Y.
        const cap = new THREE.SphereGeometry(0.62, 26, 14, 0, Math.PI * 2, 0, Math.PI * 0.6);
        cap.scale(1.0, 0.5, 1.0);
        cap.translate(0, CAP_Y, 0);

        const merged = mergeGeometries([stem, cap], false);
        merged.computeVertexNormals();
        _sharedGlassGeo = merged;
    }
    return _sharedGlassGeo;
}

function createGlassMushroomMaterial(): MeshStandardNodeMaterial {
    // Visual Impact: glass body — high transmission + low roughness read as candy-glass.
    //   transmission 0.85  → strong see-through refraction (lower for milkier glass)
    //   roughness    0.06  → tight specular highlights (raise for frosted look)
    //   ior          1.4   → gentle refraction (raise toward 2.0 for diamond sparkle)
    //   iridescence  0.0   → emissive is fully owned below; keep preset iridescence off
    const mat = CandyPresets.Crystal(GLASS_BASE_COLOR, {
        transmission: 0.85,
        thickness: 1.2,
        roughness: 0.06,
        ior: 1.4,
        iridescenceStrength: 0.0,
        side: THREE.DoubleSide,
    }) as MeshStandardNodeMaterial;

    const aPhase = attribute('aPhase', 'float');

    // --- Region masks (cap vs. stem) from baked local height ---
    const capMask = smoothstep(STEM_H * 0.72, STEM_H * 0.95, positionLocal.y);
    const radial = positionLocal.xz.length();

    // --- Music + circadian energy ---
    const musicEnergy = LuminousPlantUniforms.intensity;            // 0–1, beat-driven
    const musicColor = mix(color(GLASS_BASE_COLOR), luminousPlantsNoteColorNode, musicEnergy.mul(0.8));
    mat.colorNode = musicColor;

    // --- Phase B reactivity: bass cap ripple ---------------------------------
    // Visual Impact: concentric ripple travels across the cap dome on bass hits.
    //   amplitude 0.12 → raise for splashier jiggle, lower for subtle shimmer.
    const rippleWave = sin(radial.mul(9.0).sub(uTime.mul(4.0)).add(aPhase));

    // 🎨 PALETTE: Circadian Pose offset logic. Modulate sway/ripple based on day/night phase.
    const circadianModulator = mix(float(0.5), float(1.0), uCircadianPhase);

    const ripple = rippleWave.mul(uAudioLow).mul(0.12).mul(capMask).mul(circadianModulator);
    const idleSway = sin(uTime.mul(1.1).add(aPhase)).mul(0.015).mul(capMask).mul(circadianModulator);

    // 🎨 PALETTE: Stem swell during the day based on uCircadianPoseOffset
    const stemMask = capMask.oneMinus();
    const heightFactor = positionLocal.y.div(STEM_H).clamp(0.0, 1.0);
    const circadianSwell = normalLocal.mul(uCircadianPoseOffset).mul(heightFactor).mul(stemMask);

    const localDeformation = normalLocal.mul(ripple.add(idleSway)).add(circadianSwell);
    const displaced = positionLocal.add(localDeformation);

    // 🎨 PALETTE: Glass mushrooms now respond to wind and player presence, matching the world's shared physical language.
    mat.positionNode = applyStandardDeformation(displaced);

    // --- Emissive vein network (fake SSS along the stem) ---------------------
    // Glowing filaments climb the body; brighter/denser on the stem than the cap.
    const veinCoord = positionLocal.y.mul(8.0).add(radial.mul(14.0)).add(aPhase);
    const veins = smoothstep(0.68, 1.0, sin(veinCoord).abs());
    const stemBias = capMask.oneMinus().mul(0.6).add(0.4); // veins stronger down the stem

    // Fresnel core glow — the "internal light" of fake subsurface scattering.
    const viewDir = normalize(cameraPosition.sub(positionWorld));
    const NdotV = dot(normalWorld, viewDir).abs();
    const innerGlow = NdotV.pow(1.5).mul(0.28);

    // Visual Impact: emissive intensity tunables.
    //   baseGlow 0.35      → resting self-illumination
    //   musicPulse 0.8     → how hard the tracker channel drives the glow
    //   beatBurst 0.6      → extra cap/vein flash on bass for visible bloom response
    const baseGlow = float(0.35);
    const musicPulse = musicEnergy.mul(0.8);
    const beatBurst = smoothstep(0.3, 1.0, uAudioLow).mul(0.6);
    const veinGlow = veins.mul(stemBias).mul(baseGlow.add(musicPulse).add(beatBurst));

    // Circadian night-glow: brighter at night (phase=0), dimmer by day (phase=1).
    const circadianGlowMult = circadianNightGlowMult();

    const rim = createJuicyRimLight(musicColor, float(1.0).add(musicEnergy.mul(2.0)), float(3.0), null);

    mat.emissiveNode = musicColor
        .mul(veinGlow.add(innerGlow))
        .mul(circadianGlowMult)
        .add(rim.mul(0.5));

    registerReactiveMaterial(mat);
    return mat;
}

export class GlassMushroomBatcher {
    private static _instance: GlassMushroomBatcher | null = null;

    public mesh: THREE.InstancedMesh;
    private maxInstances: number;
    private count = 0;

    static getInstance(): GlassMushroomBatcher {
        if (!GlassMushroomBatcher._instance) {
            GlassMushroomBatcher._instance = new GlassMushroomBatcher();
        }
        return GlassMushroomBatcher._instance;
    }

    constructor(maxInstances: number = MAX_GLASS_MUSHROOMS) {
        this.maxInstances = maxInstances;

        const geo = getGlassMushroomGeometry();
        const mat = createGlassMushroomMaterial();

        this.mesh = new THREE.InstancedMesh(geo, mat, maxInstances);
        this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.mesh.castShadow = true;
        this.mesh.receiveShadow = false;
        this.mesh.frustumCulled = true;
        this.mesh.count = 0;
        this.mesh.userData.type = 'glass_mushroom';

        const phaseArray = new Float32Array(maxInstances);
        this.mesh.geometry.setAttribute('aPhase', new THREE.InstancedBufferAttribute(phaseArray, 1));

        if (foliageGroup) {
            foliageGroup.add(this.mesh);
        } else {
            console.warn('[GlassMushroomBatcher] foliageGroup not found, glass mushrooms may not be visible.');
        }
    }

    /** Register a placed glass-mushroom group; returns its instance index or -1 if full. */
    register(group: THREE.Object3D): number {
        if (this.count >= this.maxInstances) {
            console.warn('[GlassMushroomBatcher] Max capacity reached');
            return -1;
        }
        const id = this.count;

        // ⚡ OPTIMIZATION: Bypassed THREE.Object3D proxy and setX() overhead by writing directly to buffer arrays
        _scratchMatrix.compose(group.position, group.quaternion, group.scale);
        _scratchMatrix.toArray(this.mesh.instanceMatrix.array, id * 16);

        const phaseAttr = this.mesh.geometry.getAttribute('aPhase') as THREE.InstancedBufferAttribute;
        phaseAttr.array[id] = Math.random() * Math.PI * 2;

        this.count++;
        this.mesh.count = this.count;
        this.mesh.instanceMatrix.needsUpdate = true;
        phaseAttr.needsUpdate = true;
        return id;
    }

    /** Update a specific instance matrix after registration */
    updateInstance(index: number, matrix: THREE.Matrix4): void {
        if (index < 0 || index >= this.count) return;
        matrix.toArray(this.mesh.instanceMatrix.array, index * 16);
        this.mesh.instanceMatrix.needsUpdate = true;
    }

    /** Live instance count — used by world-health / telemetry callers. */
    getCount(): number {
        return this.count;
    }

    dispose(): void {
        if (this.mesh) {
            const phaseAttr = this.mesh.geometry?.getAttribute('aPhase');
            if (phaseAttr && typeof (phaseAttr as any).dispose === 'function') {
                try { (phaseAttr as any).dispose(); } catch { /* noop */ }
            }
            if (this.mesh.geometry && this.mesh.geometry !== _sharedGlassGeo) {
                this.mesh.geometry.dispose();
            }
            if (this.mesh.material) {
                if (Array.isArray(this.mesh.material)) {
                    this.mesh.material.forEach((m) => m.dispose());
                } else {
                    (this.mesh.material as THREE.Material).dispose();
                }
            }
            if (this.mesh.instanceMatrix && typeof (this.mesh.instanceMatrix as any).dispose === 'function') {
                try { (this.mesh.instanceMatrix as any).dispose(); } catch { /* noop */ }
            }
            if (foliageGroup) {
                safeRemoveAndDispose(foliageGroup as unknown as THREE.Scene, this.mesh);
            }
        }
        if (_sharedGlassGeo) {
            _sharedGlassGeo.dispose();
            _sharedGlassGeo = null;
        }
        this.count = 0;
        GlassMushroomBatcher._instance = null;
    }
}

export const glassMushroomBatcher = GlassMushroomBatcher.getInstance();

import * as THREE from 'three';
import {
    color, float, vec3, attribute, positionLocal, positionWorld,
    sin, smoothstep, uniform, mix,
    varyingProperty
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import type { Node } from 'three/webgpu';
import { BiomeUniforms } from '../systems/biome-uniforms.ts';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
import { foliageGroup } from '../world/state.ts';
import {
    sharedGeometries, foliageMaterials, uTime,
    uAudioLow, uAudioHigh, uWindSpeed, uWindDirection,
    createJuicyRimLight, calculateWindSway, applyPlayerInteraction, applyStandardDeformation,
    createStandardNodeMaterial
} from './index.ts';
import { uTwilight } from './sky.ts';

// Use the instanced color varying populated by InstancedMeshNode
const instanceColor = varyingProperty('vec3', 'vInstanceColor');

const MAX_FLOWERS = 1000; // Reduced from 5000 for WebGPU uniform buffer limits
const _scratchMat = new THREE.Matrix4();
const _scratchMat2 = new THREE.Matrix4(); // ⚡ OPTIMIZATION: Additional scratch matrix
const _scratchMat3 = new THREE.Matrix4(); // ⚡ OPTIMIZATION: Additional scratch matrix
const _scratchScale = new THREE.Vector3();
const _scratchColor = new THREE.Color();

export class GlowingFlowerBatcher {
    initialized: boolean;
    count: number;
    private indexMap = new Map<string, number>();
    private logicObjects: THREE.Object3D[] = [];

    // Meshes
    stemMesh: THREE.InstancedMesh | null;
    headMesh: THREE.InstancedMesh | null;
    washMesh: THREE.InstancedMesh | null;

    constructor() {
        this.initialized = false;
        this.count = 0;
        this.stemMesh = null;
        this.headMesh = null;
        this.washMesh = null;
    }

    init() {
        if (this.initialized) return;

        // 1. Prepare Geometries

        // Stem: Unit Cylinder (0.05, height, 0.05) scaled via matrix
        const stemGeo = sharedGeometries.unitCylinder;

        // Head: Unit Sphere (0.2 scale)
        const headGeo = sharedGeometries.unitSphere;

        // Wash: Unit Sphere (1.5 scale)
        const washGeo = sharedGeometries.unitSphere;

        // 2. Prepare Materials

        // --- Day/Night Visibility Logic ---
        // Flowers appear when it gets dark.
        // uTwilight: 0.0 (Day) -> 1.0 (Night/Bioluminescence)
        // We want them to grow/appear as uTwilight goes from 0.4 to 0.8
        const visibilityScale = smoothstep(0.4, 0.8, uTwilight);

        // --- STEM MATERIAL ---
        // Uses standard foliage stem logic + Visibility Scaling
        const stemMat = (foliageMaterials as any).flowerStem.clone();

        // Apply Visibility Scale to Position (scales around pivot at bottom)
        // stemMat.positionNode is already set to (Push + Wind).
        // We need to multiply the final position by visibilityScale?
        // No, positionNode defines the vertex position.
        // If we multiply the WHOLE position by 0, it collapses to (0,0,0).
        // Since pivot is at bottom (0,0,0), this works perfectly for "growing from ground".

        // However, stemMat.positionNode in common.ts is:
        // mat.positionNode = withPush.add(calculateWindSway(positionLocal));
        // We need to wrap this.
        const baseStemPos = stemMat.positionNode;
        stemMat.positionNode = baseStemPos.mul(visibilityScale);


        // --- HEAD MATERIAL ---
        // Emissive Sphere + Pulse + Rim Light
        const headMat = createStandardNodeMaterial({
            color: 0xFFFFFF, // Overridden by instanceColor
            roughness: 0.8
        });

        // 1. Color from Instance
        headMat.colorNode = instanceColor;

        // 2. Emissive Logic
        // Base Emissive = Instance Color
        // Pulse = Audio High (Melody)
        const pulse = uAudioHigh.mul(1.5).add(0.5); // 0.5 to 2.0
        const biomeTint = BiomeUniforms.musicalFlora.noteColor.mul(BiomeUniforms.musicalFlora.shimmer.mul(0.4));
        const baseEmissive = instanceColor.mul(pulse).add(biomeTint);

        // Juicy Rim Light (Cyan/White edge)
        const rim = createJuicyRimLight(instanceColor, float(2.0), float(3.0), null);

        // Combine
        headMat.emissiveNode = baseEmissive.add(rim);

        // 3. Position Logic (Wind + Push + Visibility)
        // Head is at top of stem. In local space of InstancedMesh (which has matrix applied).
        // The matrix handles the "Place at stem top" (Translate Y).
        // But wait, the Stem scales Y based on random height.
        // The Head matrix also translates Y based on random height.
        // So we just need local deformation (Wind/Push) relative to the Head's position.
        // However, `calculateWindSway` assumes height factor based on Y.
        // Since Head is at top, Y is small (relative to Head center).
        // But in World Space, it works.
        // `calculateWindSway` uses `positionLocal.y` for bending factor.
        // If Head is a separate mesh at (0,H,0), its `positionLocal.y` is roughly 0 (center of sphere).
        // So `calculateWindSway` will return 0 bend!
        // We need to fake the height for bending.
        // The head is effectively at "Height" (from matrix).
        // We can use a fixed height factor for bending since it's always at the top.
        // Or we can assume the head moves with the stem tip.
        // Stem tip movement = calculateWindSway(vec3(0, 1, 0)) [since stem is unit cylinder, top is 1]

        const standardDef = applyStandardDeformation(vec3(0, 1, 0)).sub(vec3(0, 1, 0)); // Sway & Push at top

        // Apply to Head
        const headPos = positionLocal.mul(visibilityScale).add(standardDef);
        headMat.positionNode = headPos;


        // --- WASH MATERIAL (Volumetric Glow) ---
        // Additive blending, soft edges
        const washMat = (foliageMaterials as any).lightBeam.clone();

        // 1. Color from Instance
        washMat.colorNode = instanceColor;

        // 2. Opacity / Intensity
        // Fade out at edges (Sphere UVs or Normal?)
        // lightBeam material already handles some of this, but it's designed for Cones/Beams.
        // Let's customize for Sphere.
        // Simple fresnel-like falloff: center opaque, edge transparent?
        // Actually for a "Glow" sphere, we want center soft, edge soft.
        // A simple radial gradient in view space?
        // Or just use the sphere geometry and fresnel.
        // lightBeam uses UVs. Sphere UVs are different.
        // Let's just use a simple Fresnel fade.
        // dot(N, V). High at center, low at edge.
        // We want soft glow.

        const washPulse = uAudioLow.mul(0.5).add(0.5); // Bass pulse
        const washOpacity = float(0.3).mul(washPulse).mul(visibilityScale); // Fade with twilight too

        washMat.opacityNode = washOpacity;
        washMat.emissiveNode = instanceColor.mul(washOpacity); // Additive glow

        // 3. Position Logic (Same as Head)
        const washPos = positionLocal.mul(visibilityScale).add(standardDef);
        washMat.positionNode = washPos;


        // 3. Create InstancedMeshes

        this.stemMesh = this.createInstancedMesh(stemGeo, stemMat, MAX_FLOWERS, 'GlowingFlower_Stem');
        this.headMesh = this.createInstancedMesh(headGeo, headMat, MAX_FLOWERS, 'GlowingFlower_Head');
        this.washMesh = this.createInstancedMesh(washGeo, washMat, MAX_FLOWERS, 'GlowingFlower_Wash');

        // TSL Safety: Initialize instanceColor manually to prevent runtime errors with TSL attributes
        this.stemMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(MAX_FLOWERS * 3), 3);
        this.stemMesh.geometry.setAttribute('instanceColor', this.stemMesh.instanceColor);
        this.headMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(MAX_FLOWERS * 3), 3);
        this.headMesh.geometry.setAttribute('instanceColor', this.headMesh.instanceColor);
        this.washMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(MAX_FLOWERS * 3), 3);
        this.washMesh.geometry.setAttribute('instanceColor', this.washMesh.instanceColor);

        // Add to Scene
        foliageGroup.add(this.stemMesh);
        foliageGroup.add(this.headMesh);
        foliageGroup.add(this.washMesh);

        this.initialized = true;
        console.log(`[GlowingFlowerBatcher] Initialized with capacity ${MAX_FLOWERS}`);
    }

    private createInstancedMesh(geo: THREE.BufferGeometry, mat: THREE.Material, count: number, name: string): THREE.InstancedMesh {
        const mesh = new THREE.InstancedMesh(geo, mat, count);
        mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        mesh.castShadow = false; // Emissive usually doesn't cast shadow? Stem should.
        if (name.includes('Stem')) mesh.castShadow = true;
        mesh.receiveShadow = true;
        mesh.count = 0;
        mesh.name = name;
        if (!mesh.instanceColor) {
            const defaultColors = new Float32Array(count * 3);
            defaultColors.fill(1.0);
            mesh.instanceColor = new THREE.InstancedBufferAttribute(defaultColors, 3);
        }
        mesh.geometry.setAttribute('instanceColor', mesh.instanceColor);
        return mesh;
    }

    dispose() {
        if (!this.initialized) return;

        [this.stemMesh, this.headMesh, this.washMesh].forEach(mesh => {
            if (!mesh) return;
            safeRemoveAndDispose(foliageGroup as unknown as THREE.Scene, mesh);
        });

        this.initialized = false;
        this.count = 0;
        this.indexMap.clear();
        this.logicObjects.length = 0;
    }

    register(logicObject: THREE.Object3D, options: any = {}) {
        if (!this.initialized) this.init();
        if (this.count >= MAX_FLOWERS) {
            console.warn('[GlowingFlowerBatcher] Capacity full');
            return;
        }

        const i = this.count;
        const { color = 0xFFD700 } = options; // Default Gold

        // 1. Calculate Transforms
        _scratchMat.compose(logicObject.position, logicObject.quaternion, logicObject.scale);
        const baseMatrix = _scratchMat;

        // Stem: Scale (0.05, height, 0.05). Height is random.
        const stemHeight = 0.6 + Math.random() * 0.4;
        _scratchScale.set(0.05, stemHeight, 0.05);
        _scratchMat.makeScale(_scratchScale.x, _scratchScale.y, _scratchScale.z);
        _scratchMat.premultiply(baseMatrix);
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMat.toArray(this.stemMesh!.instanceMatrix.array, (i) * 16);

        // Head Transform (At top of stem)
        // ⚡ OPTIMIZATION: Re-use scratch variable to avoid GC spikes
        _scratchMat2.makeTranslation(0, stemHeight, 0);
        // Head Scale: 0.2 (from original code)
        _scratchScale.set(0.2, 0.2, 0.2);
        _scratchMat2.scale(_scratchScale);
        _scratchMat2.premultiply(baseMatrix);
        const headWorld = _scratchMat2;
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        headWorld.toArray(this.headMesh!.instanceMatrix.array, (i) * 16);

        // Wash Transform (At top of stem)
        // ⚡ OPTIMIZATION: Re-use scratch variable to avoid GC spikes
        _scratchMat3.makeTranslation(0, stemHeight, 0);
        // Wash Scale: 1.5 (from original code)
        _scratchScale.set(1.5, 1.5, 1.5);
        _scratchMat3.scale(_scratchScale);
        _scratchMat3.premultiply(baseMatrix);
        const washWorld = _scratchMat3;
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        washWorld.toArray(this.washMesh!.instanceMatrix.array, (i) * 16);

        // Color
        if (typeof color === 'number') _scratchColor.setHex(color);
        else if (color instanceof THREE.Color) _scratchColor.copy(color);
        else _scratchColor.set(color as string);

        // Set Colors
        // Stem doesn't use instance color (uses standard stem green), but we can set it if we want custom stem colors.
        // Original code used `foliageMaterials.flowerStem` which is green.
        // But head and wash need the color.
        // ⚡ OPTIMIZATION: Write directly to instanceColor array to bypass .setColorAt overhead.
        if (this.headMesh!.instanceColor) {
            const colorArray = this.headMesh!.instanceColor.array as Float32Array;
            const colorOffset = i * 3;
            colorArray[colorOffset] = _scratchColor.r;
            colorArray[colorOffset + 1] = _scratchColor.g;
            colorArray[colorOffset + 2] = _scratchColor.b;
        }
        // ⚡ OPTIMIZATION: Write directly to instanceColor array to bypass .setColorAt overhead.
        if (this.washMesh!.instanceColor) {
            const colorArray = this.washMesh!.instanceColor.array as Float32Array;
            const colorOffset = i * 3;
            colorArray[colorOffset] = _scratchColor.r;
            colorArray[colorOffset + 1] = _scratchColor.g;
            colorArray[colorOffset + 2] = _scratchColor.b;
        }
        // We set stem color just to be safe, though material might ignore it if not configured to use instanceColor
        // ⚡ OPTIMIZATION: Write directly to instanceColor array to bypass .setColorAt overhead.
        if (this.stemMesh!.instanceColor) {
            const colorArray = this.stemMesh!.instanceColor.array as Float32Array;
            const colorOffset = i * 3;
            colorArray[colorOffset] = _scratchColor.r;
            colorArray[colorOffset + 1] = _scratchColor.g;
            colorArray[colorOffset + 2] = _scratchColor.b;
        }

        this.count++;

        // Mark for update
        this.stemMesh!.instanceMatrix.needsUpdate = true;
        this.stemMesh!.count = this.count;

        this.headMesh!.instanceMatrix.needsUpdate = true;
        if (this.headMesh!.instanceColor) this.headMesh!.instanceColor.needsUpdate = true;
        this.headMesh!.count = this.count;

        this.washMesh!.instanceMatrix.needsUpdate = true;
        if (this.washMesh!.instanceColor) this.washMesh!.instanceColor.needsUpdate = true;
        this.washMesh!.count = this.count;
    }
}

export const glowingFlowerBatcher = new GlowingFlowerBatcher();

// src/foliage/grass.ts

import * as THREE from 'three';
import { time, positionLocal, positionWorld, sin, vec3, color, normalView, float, max, sign, length } from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uWindSpeed, uWindDirection, createClayMaterial, uAudioLow, uAudioHigh, createJuicyRimLight, applyStandardDeformation, calculatePlayerPush } from './material-core.ts';
import { uSkyDarkness } from './sky.ts';

let grassMeshes: THREE.InstancedMesh[] = [];
const dummy = new THREE.Object3D();
const MAX_PER_MESH = 1000;
const _scratchMatrix = new THREE.Matrix4();

export function initGrassSystem(scene: THREE.Scene, count = 5000): THREE.InstancedMesh[] {
    grassMeshes = [];
    const height = 0.8;
    const geo = new THREE.BoxGeometry(0.05, height, 0.05);
    geo.translate(0, height / 2, 0);
    // Ensure normals exist for TSL
    geo.computeVertexNormals();

    const mat = new MeshStandardNodeMaterial({
        color: 0x7CFC00,
        roughness: 0.8,
        metalness: 0.0
    });

    // --- PALETTE UPDATE: Dancing Grass ---
    // 1. Dance (Audio Layer) - Fast, twitchy reaction to Hi-Hats/Melody
    const dancePhase = time.mul(15.0).add(positionWorld.x.mul(0.5)).add(positionWorld.z.mul(0.5));
    // "Shiver" effect: High frequency shake, scaled by uAudioHigh
    const danceSway = sin(dancePhase).mul(uAudioHigh).mul(0.15).mul(positionLocal.y);

    // 2. Bounce (Kick Drum) - Squash the grass vertically on the beat
    // When uAudioLow is high, scale Y down and X/Z up slightly (volume preservation)
    const squashFactor = uAudioLow.mul(0.2); // Max 20% squash
    const scaleY = float(1.0).sub(squashFactor);
    // Apply squash relative to pivot (y=0)
    const newY = positionLocal.y.mul(scaleY);

    // PALETTE JUICE: Squash & Stretch Volume Preservation
    // When Y squashes (scaleY < 1), X and Z must bulge (scaleXZ > 1)
    // scaleXZ = 1.0 + squashFactor * 0.1 (Simple approximation)
    const scaleXZ = float(1.0).add(squashFactor.mul(0.1));

    const audioPos = vec3(
        positionLocal.x.mul(scaleXZ).add(danceSway.mul(uWindDirection.x)),
        newY,
        positionLocal.z.mul(scaleXZ).add(danceSway.mul(uWindDirection.z))
    );

    mat.positionNode = applyStandardDeformation(audioPos);

    // --- Material Colors ---
    // Base Colors
    const baseColor = color(0x7CFC00);

    // --- 🎨 PALETTE: Juicy Rim Light ---
    // Audio-reactive juicy rim light for music reactivity + visual consistency with other foliage.
    // Tuned with a cooler teal bias and lower intensity specifically for dense grass.
    const grassRimColor = color(0x00FFAA);
    const rimLight = createJuicyRimLight(grassRimColor, float(1.2), float(3.0), null);

    // 4. Night Glow (Bioluminescence)
    // Grass tips glow Cyan/Green when it's dark AND there is high-freq audio
    // Glow Strength = Darkness * AudioHigh * Height (tips only)
    const tipFactor = positionLocal.y.div(float(height)); // 0 at bottom, 1 at top
    const glowStrength = uSkyDarkness.mul(uAudioHigh).mul(tipFactor).mul(2.0); // Boost intensity
    const glowColor = color(0x00FFAA); // Cyan-Green Magic

    // PALETTE JUICE: Touch Glow (Player Interaction)
    // When player pushes grass, it glows Neon Pink
    const touchGlowColor = color(0xFF00FF);
    const touchGlowStrength = length(calculatePlayerPush(audioPos)).mul(2.0); // Bright flash on touch

    mat.colorNode = baseColor;

    // Add Glow and Rim to Emissive Node (so it blooms and respects the "Palette Juice" standards)
    // Combine Audio Glow + Touch Glow + Rim Light
    const totalEmissive = glowColor.mul(glowStrength).add(touchGlowColor.mul(touchGlowStrength)).add(rimLight);
    mat.emissiveNode = totalEmissive;

    const meshCount = Math.ceil(count / MAX_PER_MESH);

    for (let i = 0; i < meshCount; i++) {
        const capacity = Math.min(MAX_PER_MESH, count - i * MAX_PER_MESH);
        const mesh = new THREE.InstancedMesh(geo, mat, capacity);
        mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        mesh.count = 0;
        mesh.receiveShadow = true;
        scene.add(mesh);
        grassMeshes.push(mesh);
    }

    return grassMeshes;
}

export function addGrassInstance(x: number, y: number, z: number) {
    const mesh = grassMeshes.find(m => m.count < m.instanceMatrix.count);
    if (!mesh) return;

    const index = mesh.count;

    dummy.position.set(x, y, z);
    dummy.rotation.y = Math.random() * Math.PI;
    const s = 0.8 + Math.random() * 0.4;
    dummy.scale.set(s, s, s);

    _scratchMatrix.compose(dummy.position, dummy.quaternion, dummy.scale);
    // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
    _scratchMatrix.toArray(mesh.instanceMatrix.array, (index) * 16);
    mesh.count++;
    mesh.instanceMatrix.needsUpdate = true;
}

export function createGrass(options: { color?: number | string | THREE.Color, shape?: 'tall' | 'bushy' } = {}) {
    const { color = 0x7CFC00, shape = 'tall' } = options;
    const material = createClayMaterial(color);
    let geo;
    if (shape === 'tall') {
        const height = 0.5 + Math.random();
        geo = new THREE.BoxGeometry(0.05, height, 0.05);
        geo.translate(0, height / 2, 0);
        const pos = geo.attributes.position;
        for (let i = 0; i < pos.count; i++) {
            const y = pos.getY(i);
            if (y > height * 0.5) {
                const bendFactor = (y - height * 0.5) / (height * 0.5);
                pos.setX(i, pos.getX(i) + bendFactor * 0.1);
            }
        }
    } else if (shape === 'bushy') {
        const height = 0.2 + Math.random() * 0.3;
        geo = new THREE.CylinderGeometry(0.1, 0.05, height, 8);
        geo.translate(0, height / 2, 0);
    } else {
        // Fallback for types
        const height = 0.5;
        geo = new THREE.BoxGeometry(0.05, height, 0.05);
    }

    geo.computeVertexNormals();

    const blade = new THREE.Mesh(geo, material);
    blade.castShadow = true;
    blade.userData.type = 'grass';
    blade.userData.animationType = shape === 'tall' ? 'sway' : 'shiver';
    blade.userData.animationOffset = Math.random() * 10;
    return blade;
}

import * as THREE from 'three';
import {
    float, sin, cos, step, positionLocal, storage, Fn, If, instanceIndex, uniform,
    exp, rotate, normalize, vec4, vec3, smoothstep, mix, floor
} from 'three/tsl';
import { MeshStandardNodeMaterial, StorageInstancedBufferAttribute } from 'three/webgpu';
import { isCIorHeadless } from '../core/config.ts';

// WGSL-compatible modulo: x - y * floor(x / y)
// Note: Converts inputs to float first since WGSL floor() only works on floats
const modFloat = (x: any, y: any) => {
    const xf = float(x);
    const yf = float(y);
    return xf.sub(yf.mul(xf.div(yf).floor()));
};


const hash = Fn(([n]: [ReturnType<typeof float>]) => {
    return modFloat(sin(n).mul(43758.5453), 1.0);
});

import { uTime, uAudioHigh, uAudioLow } from './index.ts';

const MAX_PARTICLES = 1000; // Reduced from 4000 for WebGPU uniform buffer limits
let _impactMesh: THREE.InstancedMesh | null = null;
const _head = 0;

export type ImpactType =
  | 'jump'
  | 'land'
  | 'dash'
  | 'berry'
  | 'snare'
  | 'mist'
  | 'rain'
  | 'spore'
  | 'trail'
