};

export interface ImpactSystemUserData {
    head: number;
    isImpactSystem: boolean;
    bufferSize: number;
    computeNode: any;
    uSpawnCount: any;
    uSpawnIndex: any;

    stagingSpawnArray: Float32Array;
    stagingVelArray: Float32Array;
    stagingColorArray: Float32Array;
    stagingMiscArray: Float32Array;
    stagingSpawnBuffer: StorageInstancedBufferAttribute;
    stagingVelBuffer: StorageInstancedBufferAttribute;
    stagingColorBuffer: StorageInstancedBufferAttribute;
    stagingMiscBuffer: StorageInstancedBufferAttribute;
    maxSpawnsPerFrame: number;
}

// Global uniform to store max speed across multiple calls
const uMaxSpeed = 0;

export function createImpactSystem(): THREE.InstancedMesh {
    if (_impactMesh) return _impactMesh;

    // Candy Crumbs Geometry
    // OPTIMIZATION: Use Icosahedron (low poly) instead of Sphere
    // Fixes WebGPU pointUV issue and allows rotation
    const geometry = new THREE.IcosahedronGeometry(0.1, 0);

    // Custom Attributes for TSL via Storage Instanced Buffers
    const spawnArray = new Float32Array(MAX_PARTICLES * 4);
    const velArray = new Float32Array(MAX_PARTICLES * 4);
    const colorArray = new Float32Array(MAX_PARTICLES * 4);
    const miscArray = new Float32Array(MAX_PARTICLES * 4);

    // Initialize Birth Times to -1000 (Dead)
    for (let i = 0; i < MAX_PARTICLES; i++) {
        spawnArray[i * 4 + 3] = -1000.0;
        // set some default random misc values to avoid zero vectors
        miscArray[i * 4 + 0] = Math.random() - 0.5;
        miscArray[i * 4 + 1] = Math.random() - 0.5;
        miscArray[i * 4 + 2] = Math.random() - 0.5;
    }

    const spawnBuffer = new StorageInstancedBufferAttribute(spawnArray, 4);
    const velBuffer = new StorageInstancedBufferAttribute(velArray, 4);
    const colorBuffer = new StorageInstancedBufferAttribute(colorArray, 4);
    const miscBuffer = new StorageInstancedBufferAttribute(miscArray, 4);

    // JUICE: Custom TSL Material for particles
    const mat = new MeshStandardNodeMaterial({
        color: 0xFFFFFF,
        roughness: 0.4,
        metalness: 0.1,
        transparent: true,
        depthWrite: false, // Particles don't occlude
    });

    // --- TSL LOGIC ---
    // Use storage to retrieve per-instance data
    const aSpawn = storage(spawnBuffer, 'vec4', spawnBuffer.count);
    const aVelocity = storage(velBuffer, 'vec4', velBuffer.count);
    const aColor = storage(colorBuffer, 'vec4', colorBuffer.count);
    const aMisc = storage(miscBuffer, 'vec4', miscBuffer.count);

    // Map to logic variables
    const spawnPos = aSpawn.element(instanceIndex).xyz;
    const birthTime = aSpawn.element(instanceIndex).w;

    const velocity = aVelocity.element(instanceIndex).xyz;
    const lifeSpan = aVelocity.element(instanceIndex).w;

    const colorAttr = aColor.element(instanceIndex).rgb;
    const sizeAttr = aColor.element(instanceIndex).w;

    const rotAxis = aMisc.element(instanceIndex).xyz;
    const gravityScale = aMisc.element(instanceIndex).w;

    // Age & Progress
    const age = uTime.sub(birthTime);
    const lifeProgress = age.div(lifeSpan.add(0.0001)); // prevent div by 0
    const isAlive = lifeProgress.greaterThan(0.0).and(lifeProgress.lessThan(1.0));

    // 1. Physics: Explosive Drag + Gravity
    const drag = float(2.0);
    // Integral of v*exp(-drag*t)
    const explosiveDist = velocity.mul(float(1.0).sub(exp(age.mul(drag).negate()))).div(drag);

    const gravity = vec3(0.0, -12.0, 0.0); // Slightly heavier gravity for chunks
    const gravityDrop = gravity.mul(gravityScale).mul(age.mul(age).mul(0.5));

    const particleWorldPos = spawnPos.add(explosiveDist).add(gravityDrop);

    // 2. Rotation (Spin)
    const spinSpeed = float(10.0);
    const rotationAngle = age.mul(spinSpeed);
    const rotatedLocal = rotate(positionLocal, rotationAngle);

    // 3. Scaling (Pop in with Elastic Overshoot, Shrink out)
    // 🎨 PALETTE: Make particles pop in fast, overshoot, and slowly shrink
    const popIn = smoothstep(0.0, 0.15, lifeProgress); // 0 -> 1 very quickly
    const fadeOut = float(1.0).sub(smoothstep(0.15, 1.0, lifeProgress)); // 1 -> 0 slowly

    // Elastic bounce: sin(t * freq) * decay
    // We want the bounce to happen right after popIn
    const bouncePhase = lifeProgress.mul(Math.PI * 8.0);
    const bounceDecay = float(1.0).sub(lifeProgress).pow(4.0);
    const elasticBounce = sin(bouncePhase).mul(bounceDecay).mul(0.4); // Max 40% overshoot

    // Combine base size, pop, fade, and bounce
    const baseScale = popIn.mul(fadeOut);

    // Audio Reactivity (Juice): Pulse size with low frequencies (Kick)
    const audioScale = float(1.0).add(uAudioLow.mul(0.5));
    const finalScale = sizeAttr.mul(baseScale.add(elasticBounce).max(0.0)).mul(audioScale);

    // Apply scale to rotated local vertex
    const scaledLocal = rotatedLocal.mul(finalScale);

    // Final Position Node
    // This OVERRIDES the default vertex position logic, effectively ignoring the 
    // garbage transform that 'instanceMatrix' would normally produce.
    mat.positionNode = particleWorldPos.add(scaledLocal);

    // 4. Color & Juice
    // Audio Shimmer (Highs add shimmer, Lows add brightness pulse)
    const shimmer = sin(age.mul(20.0).add(uAudioHigh.mul(10.0))).mul(0.2).add(1.0);
    const bassGlow = uAudioLow.mul(1.5);
    const totalGlow = shimmer.add(bassGlow);

    // Fade Out
    const opacity = float(1.0).sub(smoothstep(0.7, 1.0, lifeProgress));

    mat.colorNode = colorAttr.mul(totalGlow);
    mat.opacityNode = opacity.mul(isAlive);

    // 5. Mesh Creation
    _impactMesh = new THREE.InstancedMesh(geometry, mat, MAX_PARTICLES);
    _impactMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    _impactMesh.count = MAX_PARTICLES; 
    _impactMesh.castShadow = false;
    _impactMesh.receiveShadow = false;
    _impactMesh.frustumCulled = false;

    // Remove old internal matrices CPU side logic as everything happens in TSL
    _impactMesh.matrixAutoUpdate = false;

    // COMPUTE SHADER LOGIC
    // We use a small staging buffer to pass the generated particles to the GPU
    // compute shader to avoid large uniform drops or CPU->GPU main buffer uploads.
    // This allows multiple different colored/sized impacts in one frame.
    const MAX_SPAWNS_PER_FRAME = 500;
    const stagingSpawnArray = new Float32Array(MAX_SPAWNS_PER_FRAME * 4);
    const stagingVelArray = new Float32Array(MAX_SPAWNS_PER_FRAME * 4);
    const stagingColorArray = new Float32Array(MAX_SPAWNS_PER_FRAME * 4);
    const stagingMiscArray = new Float32Array(MAX_SPAWNS_PER_FRAME * 4);

    const stagingSpawnBuffer = new StorageInstancedBufferAttribute(stagingSpawnArray, 4);
    const stagingVelBuffer = new StorageInstancedBufferAttribute(stagingVelArray, 4);
    const stagingColorBuffer = new StorageInstancedBufferAttribute(stagingColorArray, 4);
    const stagingMiscBuffer = new StorageInstancedBufferAttribute(stagingMiscArray, 4);

    const uSpawnCount = uniform(0);
    const uSpawnIndex = uniform(-1);

    const updateCompute = (Fn as any)((): void => {
        // Run ONLY for the number of particles spawned this frame
        const stageIndex = instanceIndex;

        const sSpawnNode = storage(spawnBuffer, 'vec4', spawnBuffer.count);
        const sVelNode = storage(velBuffer, 'vec4', velBuffer.count);
        const sColorNode = storage(colorBuffer, 'vec4', colorBuffer.count);
        const sMiscNode = storage(miscBuffer, 'vec4', miscBuffer.count);

        const inSpawnNode = storage(stagingSpawnBuffer, 'vec4', stagingSpawnBuffer.count).element(stageIndex);
        const inColorNode = storage(stagingColorBuffer, 'vec4', stagingColorBuffer.count).element(stageIndex);
        const inMiscNode = storage(stagingMiscBuffer, 'vec4', stagingMiscBuffer.count).element(stageIndex);

        const spawnCount = uSpawnCount.toVar();
        const spawnIdx = uSpawnIndex.toVar();

        If(stageIndex.lessThan(spawnCount), () => {
            // Target index in main buffer
            const targetIdx = modFloat(stageIndex.add(spawnIdx), float(MAX_PARTICLES));

            const baseColor = inColorNode.xyz;
            const typeId = inMiscNode.x; // We pass type as an integer in Misc.x
            const dirX = inMiscNode.y;
            const dirY = inMiscNode.z;
            const dirZ = inMiscNode.w;

            const baseSeed = float(targetIdx).add(uTime);

            const rand1 = hash(baseSeed);
            const rand2 = hash(baseSeed.add(1.0));
            const rand3 = hash(baseSeed.add(2.0));
            const rand4 = hash(baseSeed.add(3.0));

            const theta = rand1.mul(Math.PI * 2.0);
            const phi = rand2.mul(Math.PI);

            const finalVel = vec3(0.0).toVar();
            const finalLife = float(0.0).toVar();
            const finalColor = baseColor.toVar();
            const finalSize = float(0.5).add(rand4).toVar();
            const gScale = float(1.0).toVar();

            If(typeId.equal(0.0), () => { // jump
                const r = rand3.mul(2.0);
                finalVel.x = cos(theta).mul(r);
                finalVel.y = float(3.0).add(rand4.mul(4.0));
                finalVel.z = sin(theta).mul(r);
                finalLife.assign(float(0.5).add(rand2.mul(0.5)));
                finalColor.assign(vec3(1.0, 0.8, 0.2));
            }).ElseIf(typeId.equal(1.0), () => { // land
                const r = float(4.0).add(rand3.mul(3.0));
                finalVel.x = cos(theta).mul(r);
                finalVel.y = float(1.0).add(rand4.mul(2.0));
                finalVel.z = sin(theta).mul(r);
                finalLife.assign(float(0.5).add(rand2.mul(0.5)));
                finalColor.assign(vec3(0.6, 0.5, 0.4));
            }).ElseIf(typeId.equal(2.0), () => { // dash
                const speed = float(4.0).add(rand3.mul(6.0));
                finalVel.x = sin(phi).mul(cos(theta)).mul(speed);
                finalVel.y = cos(phi).mul(speed);
                finalVel.z = sin(phi).mul(sin(theta)).mul(speed);
                finalLife.assign(float(0.5).add(rand2.mul(0.5)));
                finalColor.assign(vec3(0.0, 1.0, 1.0));
            }).ElseIf(typeId.equal(3.0), () => { // berry
                const speed = float(2.0).add(rand3.mul(4.0));
                finalVel.x = sin(phi).mul(cos(theta)).mul(speed);
                finalVel.y = cos(phi).mul(speed);
                finalVel.z = sin(phi).mul(sin(theta)).mul(speed);
                finalLife.assign(float(0.5).add(rand2.mul(0.5)));
                finalColor.assign(mix(vec3(1.0, 0.6, 0.0), vec3(1.0, 0.2, 0.5), step(0.5, rand1)));
            }).ElseIf(typeId.equal(4.0), () => { // snare
                const r = float(2.0).add(rand3.mul(3.0));
                finalVel.x = cos(theta).mul(r);
                finalVel.y = float(2.0).add(rand4.mul(5.0));
                finalVel.z = sin(theta).mul(r);
                finalLife.assign(float(0.5).add(rand2.mul(0.5)));
                finalColor.assign(vec3(1.0, 0.1, 0.1));
            }).ElseIf(typeId.equal(5.0), () => { // mist
                const r = rand3.mul(1.5);
                finalVel.x = cos(theta).mul(r);
                finalVel.y = float(2.0).add(rand4.mul(3.0));
                finalVel.z = sin(theta).mul(r);
                gScale.assign(-0.5);
                finalLife.assign(float(0.5).add(rand2.mul(0.5)));
                finalColor.assign(vec3(0.9, 0.9, 1.0));
            }).ElseIf(typeId.equal(6.0), () => { // rain
                const r = rand3.mul(1.0);
                finalVel.x = cos(theta).mul(r);
                finalVel.y = float(-5.0).sub(rand4.mul(5.0));
                finalVel.z = sin(theta).mul(r);
                gScale.assign(2.0);
                finalLife.assign(float(0.5).add(rand2.mul(0.5)));
                finalColor.assign(vec3(0.2, 0.2, 1.0));
            }).ElseIf(typeId.equal(7.0), () => { // spore
                const r = rand3.mul(2.0);
                finalVel.x = cos(theta).mul(r);
                finalVel.y = float(1.0).add(rand4.mul(2.0));
                finalVel.z = sin(theta).mul(r);
                gScale.assign(-0.2);
                finalLife.assign(float(1.5).add(rand2.mul(1.5)));
                finalSize.assign(float(0.2).add(rand4.mul(0.3)));

                If(rand1.lessThan(0.33), () => {
                    finalColor.assign(vec3(0.0, 1.0, 1.0));
                }).ElseIf(rand1.lessThan(0.66), () => {
                    finalColor.assign(vec3(1.0, 0.0, 1.0));
                }).Else(() => {
                    finalColor.assign(vec3(0.5, 1.0, 0.0));
                });
            }).ElseIf(typeId.equal(8.0), () => { // trail
                finalVel.x = rand1.sub(0.5).mul(0.5);
                finalVel.y = rand2.sub(0.5).mul(0.5);
                finalVel.z = rand3.sub(0.5).mul(0.5);
                gScale.assign(0.0);
                finalLife.assign(float(0.3).add(rand2.mul(0.2)));
                finalSize.assign(float(0.3).add(rand4.mul(0.2)));
            }).ElseIf(typeId.equal(9.0), () => { // muzzle
                If(dirX.notEqual(0.0).or(dirY.notEqual(0.0)).or(dirZ.notEqual(0.0)), () => {
                    const speed = float(10.0).add(rand3.mul(5.0));
                    const spread = 2.0;
                    finalVel.x = dirX.mul(speed).add(rand1.sub(0.5).mul(spread));
                    finalVel.y = dirY.mul(speed).add(rand2.sub(0.5).mul(spread));
                    finalVel.z = dirZ.mul(speed).add(rand3.sub(0.5).mul(spread));
                }).Else(() => {
                    const speed = float(5.0).add(rand3.mul(5.0));
                    finalVel.x = sin(phi).mul(cos(theta)).mul(speed);
                    finalVel.y = cos(phi).mul(speed);
                    finalVel.z = sin(phi).mul(sin(theta)).mul(speed);
                });
                gScale.assign(0.5);
                finalLife.assign(float(0.15).add(rand2.mul(0.15)));
                finalSize.assign(float(0.5).add(rand4.mul(0.5)));
            }).Else(() => {
                finalVel.x = rand1.sub(0.5);
                finalVel.y = rand2.sub(0.5);
                finalVel.z = rand3.sub(0.5);
                finalLife.assign(float(0.5).add(rand2.mul(0.5)));
            });

            // Fallback for custom color passed directly via CPU
            If(baseColor.x.notEqual(-1.0), () => {
                finalColor.assign(baseColor);
            });

            // Copy to main
            sSpawnNode.element(targetIdx).assign(inSpawnNode);
            sVelNode.element(targetIdx).assign(vec4(finalVel, finalLife));
            sColorNode.element(targetIdx).assign(vec4(finalColor, finalSize));
            sMiscNode.element(targetIdx).assign(vec4(hash(baseSeed.add(4.0)).sub(0.5), hash(baseSeed.add(5.0)).sub(0.5), hash(baseSeed.add(6.0)).sub(0.5), gScale));
        });
    });

    const computeNode = (updateCompute() as unknown as { compute: (n: number) => unknown }).compute(MAX_SPAWNS_PER_FRAME);

    _impactMesh.userData = {
        head: 0,
        isImpactSystem: true,
        bufferSize: MAX_PARTICLES,
        computeNode: computeNode,
        uSpawnCount: uSpawnCount,
        uSpawnIndex: uSpawnIndex,

        // Expose staging buffers to CPU
        stagingSpawnArray,
        stagingVelArray,
        stagingColorArray,
        stagingMiscArray,
        stagingSpawnBuffer,
        stagingVelBuffer,
        stagingColorBuffer,
        stagingMiscBuffer,
        maxSpawnsPerFrame: MAX_SPAWNS_PER_FRAME
    } as ImpactSystemUserData;

    return _impactMesh;
}

// Staging queues for particles since spawnImpact can be called multiple times per frame
const _spawnQueue: any[] = [];

export function spawnImpact(
    pos: THREE.Vector3 | {x:number, y:number, z:number},
    type: ImpactType = 'jump',
    color?: number | {r:number, g:number, b:number} | THREE.Color,
    direction?: THREE.Vector3 | {x:number, y:number, z:number}
) {
    if (!_impactMesh || !_impactMesh.userData.isImpactSystem) return;

    const config = IMPACT_CONFIG[type] || IMPACT_CONFIG.jump;
    const count = config.count;

    // Queue the spawn
    _spawnQueue.push({ pos: {...pos}, type, color, direction, count });
}

export function updateImpacts(renderer: any, time: number) {
    if (!_impactMesh || !_impactMesh.userData.isImpactSystem) return;

    const userData = _impactMesh.userData as ImpactSystemUserData;

    // Reset spawn count initially
    userData.uSpawnCount.value = 0;

    if (_spawnQueue.length > 0 && renderer && renderer.compute) {

        let totalSpawns = 0;
        const now = time;

        for (let s = 0; s < _spawnQueue.length; s++) {
            const spawn = _spawnQueue[s];
            const type = spawn.type;
            let count = spawn.count;
            const pos = spawn.pos;
            const color = spawn.color;
            const direction = spawn.direction;

            // Cap to max staging buffer size
            if (totalSpawns + count > userData.maxSpawnsPerFrame) {
                count = userData.maxSpawnsPerFrame - totalSpawns;
                if (count <= 0) break;
            }

            for (let i = 0; i < count; i++) {
                const offset = (totalSpawns + i) * 4;

                // Position & Time
                const ox = (Math.random() - 0.5) * 0.5;
                const oy = (Math.random() - 0.5) * 0.5;
                const oz = (Math.random() - 0.5) * 0.5;

                userData.stagingSpawnArray[offset + 0] = pos.x + ox;
                userData.stagingSpawnArray[offset + 1] = pos.y + oy;
                userData.stagingSpawnArray[offset + 2] = pos.z + oz;
                userData.stagingSpawnArray[offset + 3] = now;

                // Base color parsing
                let r=-1.0, g=-1.0, b=-1.0;
                if (color !== undefined) {
                    if (typeof color === 'number') {
                        r = ((color >> 16) & 255) / 255;
                        g = ((color >> 8) & 255) / 255;
                        b = (color & 255) / 255;
                    } else if ((color as any).isColor) {
                        r = (color as THREE.Color).r;
                        g = (color as THREE.Color).g;
                        b = (color as THREE.Color).b;
                    } else {
                        const c = color as {r:number, g:number, b:number};
                        r = c.r; g = c.g; b = c.b;
                    }
                }

                userData.stagingColorArray[offset + 0] = r;
                userData.stagingColorArray[offset + 1] = g;
                userData.stagingColorArray[offset + 2] = b;
                userData.stagingColorArray[offset + 3] = 1.0;

                // Misc stores typeId and direction
                userData.stagingMiscArray[offset + 0] = IMPACT_TYPE_MAP[type as ImpactType] ?? 13.0;
                userData.stagingMiscArray[offset + 1] = direction ? direction.x : 0.0;
                userData.stagingMiscArray[offset + 2] = direction ? direction.y : 0.0;
                userData.stagingMiscArray[offset + 3] = direction ? direction.z : 0.0;
            }

            totalSpawns += count;
        }

        if (totalSpawns > 0) {
            // Push staging data to GPU
            userData.stagingSpawnBuffer.needsUpdate = true;
            userData.stagingVelBuffer.needsUpdate = true;
            userData.stagingColorBuffer.needsUpdate = true;
            userData.stagingMiscBuffer.needsUpdate = true;

            // Update uniforms
            userData.uSpawnCount.value = totalSpawns;
            userData.uSpawnIndex.value = userData.head;

            // Execute compute
            if (!isCIorHeadless()) { renderer.compute(userData.computeNode); }

            // Advance head
            userData.head = (userData.head + totalSpawns) % userData.bufferSize;
        }

        // Clear queue
        _spawnQueue.length = 0;
    }
}

import * as THREE from 'three';
import {
    color, float, mix, uv, sin, cos,
    vec3, vec2, floor, smoothstep, abs, mx_noise_float, uniform
} from 'three/tsl';
import { unlockSystem } from '../systems/unlocks.ts';
import { makeInteractive } from '../utils/interaction-utils.ts';
import { spawnImpact } from './impacts.ts';
import {
    createUnifiedMaterial,
    sharedGeometries,
    attachReactivity
} from './index.ts';

const _scratchPos = new THREE.Vector3();
const _scratchUp = new THREE.Vector3(0, 1, 0);

export interface InstrumentShrineOptions {
    instrumentID?: number;
    scale?: number;
}

export function createInstrumentShrine(options: InstrumentShrineOptions = {}): THREE.Group {
    const {
        instrumentID = 0,
        scale = 1.0
    } = options;

    const group = new THREE.Group();

    // The Shrine is a monolith that displays patterns based on the Instrument ID.
    // 0 = Drums, 1 = Bass, etc (in standard MOD files instruments are 1-based usually).

    const shrineMat = createUnifiedMaterial(0x333333, {
        roughness: 0.2,
        metalness: 0.8,
        bumpStrength: 0.1
    });

    // Custom TSL override for Color based on Instrument ID
    // We use uniforms so the puzzle pattern can be cycled on interact
    const uInstrumentID = uniform(instrumentID);

    // --- Instrument-ID Textures (Advanced Shaders) ---
    // Procedural patterns generated based on Instrument ID
    const pUV = uv().mul(10.0);
    const timeOffset = pUV.x.add(pUV.y).add(uInstrumentID);

    // Pattern 1: Grid-like (e.g. for structured synth instruments)
    const patternGrid = sin(pUV.x.add(uInstrumentID)).mul(cos(pUV.y.add(uInstrumentID)));

    // Pattern 2: Noise-like (e.g. for organic or percussive instruments)
    const patternNoise = mx_noise_float(vec3(pUV.x, pUV.y, uInstrumentID));

    // Pattern 3: Concentric ripples
    const distToCenter = vec2(pUV.x.sub(5.0), pUV.y.sub(5.0)).length();
    const patternRipple = sin(distToCenter.mul(3.0).sub(uInstrumentID.mul(2.0)));

    // Pattern 4: Diagonal stripes
    const patternStripes = sin(pUV.x.add(pUV.y).mul(5.0).add(uInstrumentID.mul(10.0)));

    // Smooth blending across 4 distinct pattern types based on Instrument ID modulo
    // We use a pseudo-modulo trick: id - 4 * floor(id/4)
    const mod4 = uInstrumentID.sub(floor(uInstrumentID.div(4.0)).mul(4.0));

    // Create blend masks using smoothstep for distinct pattern transitions
    const maskGrid = float(1.0).sub(smoothstep(0.0, 1.0, abs(mod4.sub(0.0))));
    const maskNoise = float(1.0).sub(smoothstep(0.0, 1.0, abs(mod4.sub(1.0))));
    const maskRipple = float(1.0).sub(smoothstep(0.0, 1.0, abs(mod4.sub(2.0))));
    const maskStripes = float(1.0).sub(smoothstep(0.0, 1.0, abs(mod4.sub(3.0))));

    // Combine all patterns weighted by their masks
    const combinedPattern = patternGrid.mul(maskGrid)
        .add(patternNoise.mul(maskNoise))
        .add(patternRipple.mul(maskRipple))
        .add(patternStripes.mul(maskStripes));

    const pattern = combinedPattern;

    // Colorize
    // Map ID to Hue and pass via Uniform to allow dynamic updating
    const jsHue = (instrumentID * 0.1) % 1.0;
    const jsColor = new THREE.Color().setHSL(jsHue, 1.0, 0.5);
    const uBaseColor = uniform(jsColor);

    // Apply pattern to emissive
    shrineMat.emissiveNode = uBaseColor.mul(pattern.add(0.5).mul(2.0)); // Glow

    // Geometry: Monolith
    const geo = new THREE.BoxGeometry(1, 3, 1);
    const mesh = new THREE.Mesh(geo, shrineMat);
    mesh.scale.set(scale, scale, scale);
    mesh.position.y = 1.5 * scale;
    mesh.castShadow = true;

    group.add(mesh);

    // Floating symbol on top (Sphere)
    const orbMat = createUnifiedMaterial(0xFFFFFF, {
        transmission: 1.0,
        thickness: 1.0,
        roughness: 0.0,
        ior: 1.5,
        iridescenceStrength: 1.0
    });
    const orb = new THREE.Mesh(sharedGeometries.unitSphere, orbMat);
    orb.position.y = 3.5 * scale;
    orb.scale.setScalar(0.5 * scale);
    group.add(orb);

    // Store orb for animation
    group.userData.orb = orb;
    group.userData.orbMat = orbMat;

    group.userData.type = 'instrumentShrine';
    group.userData.instrumentID = instrumentID;

    // Use specific animation type for logic
    group.userData.animationType = 'instrumentShrine';
    group.userData.animationOffset = Math.random() * 100;

    // Puzzle State
    group.userData.isActive = false; // Is matching instrument playing?
    group.userData.isSolved = false; // Has player activated it?
    group.userData.interactionText = `Tune Shrine (Current: ${instrumentID})`; // Shortened for UI fit

    // Store uniforms on userData so they can be updated
    group.userData.uInstrumentID = uInstrumentID;
    group.userData.uBaseColor = uBaseColor;
    group.userData.jsColor = jsColor;

    // Reactivity
    attachReactivity(group, { minLight: 0.0, maxLight: 1.0 });

    const interactive = makeInteractive(group);

    // Override interaction
    const originalInteract = group.userData.onInteract;
    group.userData.onInteract = () => {
        if (group.userData.isSolved) {
            // Already solved feedback
            // Maybe toggle something else or just show sparkle
             if ((window as any).AudioSystem) {
                // Play a small 'already done' sound if available, or just generic click
            }
            return;
        }

        if (group.userData.isActive) {
            // Solve!
            group.userData.isSolved = true;
            group.userData.interactionText = "Shrine Activated";

            // Visual feedback
            _scratchPos.copy(group.position).y += 3.0;
            spawnImpact(_scratchPos, 'muzzle', group.userData.jsColor, _scratchUp);

            // Audio feedback
            if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                 (window as any).AudioSystem.playSound('chime', { position: group.position, pitch: 1.0, volume: 0.8 });
            }

            // Reward
            unlockSystem.harvest('shrine_token', 1, 'Shrine Token');

            // Update visual state immediately
            orbMat.emissive.set(0xFFD700); // Turn Gold
            orbMat.emissiveIntensity = 2.0;

        } else {
            // Cycle the puzzle ID!
            group.userData.instrumentID = (group.userData.instrumentID + 1) % 16;

            // Update Uniforms
            group.userData.uInstrumentID.value = group.userData.instrumentID;
            group.userData.jsColor.setHSL((group.userData.instrumentID * 0.1) % 1.0, 1.0, 0.5);

            // Interaction Text Update
            group.userData.interactionText = `Tune Shrine (Current: ${group.userData.instrumentID})`;

            // Audio feedback for cycling
            if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                 (window as any).AudioSystem.playSound('click', { position: group.position, pitch: 1.0 + (group.userData.instrumentID * 0.05), volume: 0.5 });
            }
        }

        if (originalInteract) originalInteract();
    };

    return interactive as THREE.Group;
}

import * as THREE from 'three';
import {
    color, float, vec3, vec4, sin, cos, positionLocal, time, uniform, normalLocal, add
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { BiomeId } from '../systems/biome-uniforms.ts';
import { uCircadianPoseOffset } from '../systems/biome-uniforms.ts';
import { computeWaveDistSq, computeWaveTimeSinceArrival } from '../systems/music-wave.ts';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
import { foliageGroup } from '../world/state.ts';
import {
    CandyPresets,
    uTime,
    registerReactiveMaterial,
    calculateWindSway,
    applyPlayerInteraction,
    applyStandardDeformation,
    createJuicyRimLight
} from './index.ts';

const MAX_GEYSERS = 500;

export class KickDrumGeyserBatcher {
    baseMesh!: THREE.InstancedMesh;
    coreMesh!: THREE.InstancedMesh;
    plumeMesh!: THREE.InstancedMesh;

    private _count = 0;
    private _scratchMatrix = new THREE.Matrix4();
    private _scratchVec3 = new THREE.Vector3();
    private _scratchPos = new THREE.Vector3();

    // Data arrays for animation
    private _offsets: Float32Array;
    private _maxHeights: Float32Array;

    group = new THREE.Group();

    constructor() {
        this._offsets = new Float32Array(MAX_GEYSERS);
        this._maxHeights = new Float32Array(MAX_GEYSERS);
        this.init();
    }

    private init() {
        // Base Clay Mesh
        const baseGeo = new THREE.RingGeometry(0.1, 0.4, 8, 1);
        baseGeo.rotateX(-Math.PI / 2);
        const baseMat = CandyPresets.Clay(0x1A0A00, {
            roughness: 0.9,
            emissive: 0xFF4500,
            emissiveIntensity: 0.1
        });
        this.baseMesh = new THREE.InstancedMesh(baseGeo, baseMat, MAX_GEYSERS);
        this.baseMesh.count = 0;
        this.baseMesh.frustumCulled = false;
        foliageGroup.add(this.baseMesh);

        // Core Gummy Mesh
        const coreGeo = new THREE.CylinderGeometry(0.08, 0.12, 0.1, 8);
        coreGeo.translate(0, -0.05, 0);
        const coreMat = CandyPresets.Gummy(0xFF4500, {
            roughness: 0.3,
            emissive: 0xFF4500,
            emissiveIntensity: 0.8
        });
        // 🎨 PALETTE: Add juicy rim light to geyser core
        coreMat.emissiveNode = add(coreMat.emissiveNode ?? color(0x000000), createJuicyRimLight(color(0xFF4500), float(1.5), float(3.0), normalLocal));
        registerReactiveMaterial(coreMat);
        this.coreMesh = new THREE.InstancedMesh(coreGeo, coreMat, MAX_GEYSERS);
        this.coreMesh.count = 0;
        this.coreMesh.frustumCulled = false;
        foliageGroup.add(this.coreMesh);

        // Plume Mesh (Semi-transparent animated column)
        const plumeGeo = new THREE.CylinderGeometry(0.15, 0.15, 1, 8, 4);
        plumeGeo.translate(0, 0.5, 0); // Origin at bottom

        const plumeMat = new MeshStandardNodeMaterial({
            transparent: true,
            opacity: 0.8,
            blending: THREE.AdditiveBlending,
            depthWrite: false
        });

        // ⚡ OPTIMIZATION: TSL Node for Plume Animation (Wave-based scale handled in CPU update logic, but we can add jitter here)
        const jitterX = sin(uTime.mul(10.0).add(positionLocal.y.mul(10.0))).mul(0.1);
        const jitterZ = cos(uTime.mul(12.0).add(positionLocal.y.mul(10.0))).mul(0.1);

        const plumePos = vec3(
            positionLocal.x.add(jitterX),
            positionLocal.y,
            positionLocal.z.add(jitterZ)
        );

        // 🎨 PALETTE: Add wind sway and player interaction to the geyser plumes
        const circadianDroop = vec3(0, float(-0.5).mul(uCircadianPoseOffset).mul(positionLocal.y), 0);
        plumeMat.positionNode = applyStandardDeformation(plumePos.add(circadianDroop));
        plumeMat.colorNode = vec4(color(0xFF4500), float(0.8));

        this.plumeMesh = new THREE.InstancedMesh(plumeGeo, plumeMat, MAX_GEYSERS);
        this.plumeMesh.count = 0;
        this.plumeMesh.frustumCulled = false;
        foliageGroup.add(this.plumeMesh);
    }

    /**
     * Registers a new Geyser instance.
     */
    register(proxy: THREE.Object3D, options: { maxHeight?: number } = {}) {
        if (this._count >= MAX_GEYSERS) return;

        const i = this._count;
        this._count++;

        this.baseMesh.count = this._count;
        this.coreMesh.count = this._count;
        this.plumeMesh.count = this._count;

        // Apply Transform
        // ⚡ OPTIMIZATION: Bypassed THREE.Object3D proxy and setMatrixAt() overhead by writing directly to instanceMatrix
        proxy.updateWorldMatrix(false, false);
        const matrixArray = proxy.matrixWorld.elements;

        for (let j = 0; j < 16; j++) {
            this.baseMesh.instanceMatrix.array[i * 16 + j] = matrixArray[j];
            this.coreMesh.instanceMatrix.array[i * 16 + j] = matrixArray[j];
            this.plumeMesh.instanceMatrix.array[i * 16 + j] = matrixArray[j]; // Plume will be scaled dynamically later
        }

        this.baseMesh.instanceMatrix.needsUpdate = true;
        this.coreMesh.instanceMatrix.needsUpdate = true;
        this.plumeMesh.instanceMatrix.needsUpdate = true;

        this._offsets[i] = Math.random() * 10.0;
        this._maxHeights[i] = options.maxHeight ?? 5.0;
    }

    /**
     * Update loop to animate plumes based on kick drum audio
     */
    update(time: number, deltaTime: number, audioState: any, activeWave: any) {
        if (this._count === 0) return;

        // Eruption logic is driven by the 'kick' channel (typically uAudioLow in similar batchers or audioState.kick)
        const globalKick = audioState?.channels?.kick?.intensity || 0;

        const baseArray = this.baseMesh.instanceMatrix.array;
        const plumeArray = this.plumeMesh.instanceMatrix.array;

        // O(N) zero-allocation hot path
        for (let i = 0; i < this._count; i++) {
            // Get position directly from array for wave calculation
            const x = baseArray[i * 16 + 12];
            const y = baseArray[i * 16 + 13];
            const z = baseArray[i * 16 + 14];

            // ⚡ OPTIMIZATION: Zero-allocation position object for wave computation
            this._scratchPos.set(x, y, z);

            // Calculate distance-based wave timing
            const waveTime = computeWaveTimeSinceArrival(this._scratchPos, activeWave);

            // Simulate local kick intensity. If wave hasn't reached, it's 0.
            // If it reached recently, apply a sharp spike that decays.
            let localKick = globalKick;
            if (activeWave) {
                if (waveTime < 0) {
                    localKick = 0;
                } else if (waveTime < 0.2) {
                    // Sharp spike when wave hits
                    localKick = 1.0;
                } else {
                    // Exponential decay
                    localKick = Math.max(0, Math.exp(-10.0 * (waveTime - 0.2)));
                }
            }

            // Plume vertical scaling
            const targetHeight = this._maxHeights[i] * localKick;

            // Manual matrix composition for plume
            // Keep base transform, but scale Y axis
            // ⚡ OPTIMIZATION: Bypassed Matrix4 composition overhead by directly modifying the Y-axis basis vector in the Float32Array
            const scaleY = targetHeight + 0.01; // 0.01 to prevent singular matrix warning
            const baseIndex = i * 16;

            plumeArray[baseIndex + 0] = baseArray[baseIndex + 0];
            plumeArray[baseIndex + 1] = baseArray[baseIndex + 1];
            plumeArray[baseIndex + 2] = baseArray[baseIndex + 2];
            plumeArray[baseIndex + 3] = baseArray[baseIndex + 3];

            // Scale Y-axis basis vector
            plumeArray[baseIndex + 4] = baseArray[baseIndex + 4] * scaleY;
            plumeArray[baseIndex + 5] = baseArray[baseIndex + 5] * scaleY;
            plumeArray[baseIndex + 6] = baseArray[baseIndex + 6] * scaleY;
            plumeArray[baseIndex + 7] = baseArray[baseIndex + 7] * scaleY;

            plumeArray[baseIndex + 8] = baseArray[baseIndex + 8];
            plumeArray[baseIndex + 9] = baseArray[baseIndex + 9];
            plumeArray[baseIndex + 10] = baseArray[baseIndex + 10];
            plumeArray[baseIndex + 11] = baseArray[baseIndex + 11];

            plumeArray[baseIndex + 12] = baseArray[baseIndex + 12];
            plumeArray[baseIndex + 13] = baseArray[baseIndex + 13];
            plumeArray[baseIndex + 14] = baseArray[baseIndex + 14];
            plumeArray[baseIndex + 15] = baseArray[baseIndex + 15];
        }

        this.plumeMesh.instanceMatrix.needsUpdate = true;
    }

    dispose() {
        if (this.baseMesh && this.baseMesh.parent) {
            safeRemoveAndDispose(this.baseMesh.parent, this.baseMesh);
        }
        if (this.coreMesh && this.coreMesh.parent) {
            safeRemoveAndDispose(this.coreMesh.parent, this.coreMesh);
        }
        if (this.plumeMesh && this.plumeMesh.parent) {
            safeRemoveAndDispose(this.plumeMesh.parent, this.plumeMesh);
        }
    }
}

export const kickDrumGeyserBatcher = new KickDrumGeyserBatcher();

// src/foliage/lake_features.ts
import * as THREE from 'three';
import {
    positionLocal, vec3, float, sin, time, uv, add, color
} from 'three/tsl';
import { getBiomeUniforms, type BiomeId } from '../systems/biome-uniforms.ts';
import {
    CandyPresets, attachReactivity
} from './index.ts';

export interface IslandOptions {
    radius?: number;
    height?: number;
    hasCreek?: boolean;
}

/**
 * Creates a floating island with a stylized creek path
 */
export function createIsland(options: IslandOptions = {}): THREE.Group {
    const {
        radius = 15.0,
        height = 3.0,
        hasCreek = true
    } = options;

    const group = new THREE.Group();
    group.userData.type = 'lake_island'; // Updated type to match discovery map

    // 1. Base Island Geometry (Flattened Sphere/Cylinder hybrid)
    const islandGeo = new THREE.CylinderGeometry(radius, radius * 0.8, height, 16, 2);
    // Displace vertices for organic look
    const pos = islandGeo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
        const x = pos.getX(i);
        const y = pos.getY(i);
        const z = pos.getZ(i);

        // Noise-like displacement (simple random for now, could be improved)
        const angle = Math.atan2(z, x);
        const r = Math.sqrt(x*x + z*z);
        const noise = Math.sin(angle * 5) * 0.5 + Math.cos(angle * 8) * 0.3;

        if (y > 0) { // Top
            pos.setY(i, y + Math.random() * 0.5);
        } else { // Bottom
            pos.setX(i, x * (1 + noise * 0.1));
            pos.setZ(i, z * (1 + noise * 0.1));
        }
    }
    islandGeo.computeVertexNormals();

    const islandMat = CandyPresets.Clay(0xD2B48C, { // Tan/Sand color
        roughness: 0.9,
        bumpStrength: 0.2,
        noiseScale: 3.0
    });

    const islandMesh = new THREE.Mesh(islandGeo, islandMat);
    islandMesh.position.y = height / 2;
    group.add(islandMesh);

    // 2. Creek (if enabled)
    // A simple curved path on top of the island
    if (hasCreek) {
        const curve = new THREE.CatmullRomCurve3([
            new THREE.Vector3(-radius * 0.8, height + 0.1, -radius * 0.2),
            new THREE.Vector3(-radius * 0.2, height + 0.1, radius * 0.2),
            new THREE.Vector3(radius * 0.4, height + 0.1, -radius * 0.3),
            new THREE.Vector3(radius * 0.9, height + 0.1, 0)
        ]);

        const creekGeo = new THREE.TubeGeometry(curve, 20, 1.5, 8, false);

        // TSL Flowing Water Material
        const creekMat = CandyPresets.SeaJelly(0x44AAFF, {
            transmission: 0.8,
            roughness: 0.1
        }) as any; // Cast to any to access TSL properties like positionNode

        // ⚡ OPTIMIZATION & JUICE: Explicit TSL flow animation for the creek
        // Displace the creek surface based on UVs and time to create a flowing water effect
        const flowTime = time.mul(2.0);
        const flowUv = uv(); // TubeGeometry uses 2D UVs

        // Create ripples moving along the creek
        const ripple = sin(flowUv.x.mul(10.0).add(flowTime)).mul(0.1);
        const displacement = vec3(0, ripple, 0);

        // Apply the displacement
        const basePosition = positionLocal;
        creekMat.positionNode = add(basePosition, displacement);

        // Music Impact: crystalline nebula shimmer drives creek bioluminescence
        const nebulaUniforms = getBiomeUniforms('crystalline_nebula');
        creekMat.emissiveNode = color(0x44AAFF).mul(nebulaUniforms.shimmer).mul(0.35);

        const creekMesh = new THREE.Mesh(creekGeo, creekMat);
        group.add(creekMesh);
    }

    // 3. Decorations (Rocks, Small Plants)
    // Add a few rocks
    for (let i = 0; i < 5; i++) {
        const rockGeo = new THREE.DodecahedronGeometry(1 + Math.random(), 0);
        const rockMat = CandyPresets.Clay(0x808080);
        const rock = new THREE.Mesh(rockGeo, rockMat);
        const angle = Math.random() * Math.PI * 2;
        const dist = Math.random() * (radius * 0.7);
        rock.position.set(Math.cos(angle) * dist, height + 0.5, Math.sin(angle) * dist);
        rock.rotation.set(Math.random(), Math.random(), Math.random());
        group.add(rock);
    }

    // Reactivity
    attachReactivity(group, { type: 'flora' });

    return group;
}

import * as THREE from 'three';
import {
    color, float, vec3, vec4, attribute, positionLocal, positionWorld,
    sin, cos, mix, smoothstep, uniform, If, time,
    varying, dot, normalize, normalLocal, step, uv,
    mx_noise_float, varyingProperty
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { getCIAdjustedCount } from '../core/config.ts';
import { CONFIG } from '../core/config.ts';
import { BiomeUniforms, circadianNightGlowMult } from '../systems/biome-uniforms.ts';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
const instanceColor = varyingProperty('vec3', 'vInstanceColor');
import { getTorusGeometry, getConeGeometry } from '../utils/geometry-dedup.ts';
import { foliageGroup } from '../world/state.ts';
import {
    sharedGeometries, foliageMaterials, uTime,
    uAudioLow, uAudioHigh, createRimLight, createJuicyRimLight, calculateWindSway, applyPlayerInteraction, applyStandardDeformation,
    createStandardNodeMaterial, createUnifiedMaterial
} from './index.ts';
import { uTwilight } from './sky.ts';

const MAX_LANTERNS = getCIAdjustedCount(250, 0.2, 50); // Reduced from 1000 for WebGPU uniform buffer limits

// ⚡ OPTIMIZATION: Module scoped scratch variables to avoid GC spikes
const _scratchMatrixBatch = new THREE.Matrix4();
const _scratchV = new THREE.Vector3();
const _scratchN = new THREE.Vector3();
const _scratchQuat = new THREE.Quaternion();
const _scratchColor = new THREE.Color();

export class LanternBatcher {
    private static instance: LanternBatcher;
    private initialized = false;
    private count = 0;

    // Meshes
    public stemMesh: THREE.InstancedMesh | null = null;
    public topMesh: THREE.InstancedMesh | null = null;

    // Attributes
    private stemParams: THREE.InstancedBufferAttribute | null = null; // [height, unused, unused, spawnTime]
    private topParams: THREE.InstancedBufferAttribute | null = null;  // [height, randomPhase, unused, spawnTime]

    private constructor() {}

    static getInstance(): LanternBatcher {
        if (!LanternBatcher.instance) {
            LanternBatcher.instance = new LanternBatcher();
        }
        return LanternBatcher.instance;
    }

    init() {
        if (this.initialized) return;

        this.initStem();
        this.initTop();

        // Add to Scene
        if (foliageGroup) {
            if (this.stemMesh) foliageGroup.add(this.stemMesh);
            if (this.topMesh) foliageGroup.add(this.topMesh);
        }

        this.initialized = true;
        console.log('[LanternBatcher] Initialized with capacity ' + MAX_LANTERNS);
    }

    private initStem() {
        // Stem Geometry (Base Unit Cylinder, pivot at bottom)
        const geometry = sharedGeometries.unitCylinder.clone();

        // Attributes
        this.stemParams = new THREE.InstancedBufferAttribute(new Float32Array(MAX_LANTERNS * 4), 4);
        geometry.setAttribute('instanceParams', this.stemParams);

        // Material (TSL)
        // Clone standard stem material but modify for height scaling
        const stemMaterial = foliageMaterials.stem;
        const mat = (Array.isArray(stemMaterial) ? stemMaterial[0] : stemMaterial).clone() as MeshStandardNodeMaterial;

        // Custom Position Logic:
        // 1. Scale Y based on instanceParams.x (Height)
        // 2. Pop-In Animation based on instanceParams.w (SpawnTime)
        // 3. Apply Wind/Player Interaction
        const params = attribute('instanceParams', 'vec4');
        const height = params.x;
        const spawnTime = params.w;

        // Pop-In Logic
        const age = uTime.sub(spawnTime);
        const popProgress = smoothstep(0.0, 1.0, age.mul(2.0)); // 0.5s pop
        // Elastic overshoot
        const overshoot = sin(popProgress.mul(10.0)).mul(float(1.0).sub(popProgress)).mul(0.3);
        const popScale = popProgress.add(overshoot).max(0.001);

        const pos = positionLocal;
        // Apply Pop Scale to X/Z (thickness) and Y (height growth)
        const scaledPos = vec3(
            pos.x.mul(0.1).mul(popScale),
            pos.y.mul(height).mul(popScale),
            pos.z.mul(0.1).mul(popScale)
        ); // Thinner stem

        // Apply Sway (Scaled by height factor so bottom is fixed)
        // We use positionLocal.y (0 to 1) as factor
        mat.positionNode = applyStandardDeformation(scaledPos);

        // Mesh
        this.stemMesh = new THREE.InstancedMesh(geometry, mat, MAX_LANTERNS);
        this.stemMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.stemMesh.count = 0;
        this.stemMesh.castShadow = true;
        this.stemMesh.receiveShadow = true;
    }

    private initTop() {
        const geometry = this.createTopGeometry();

        // Attributes - SINGLE packed attribute to stay within WebGPU 8 buffer limit
        this.topParams = new THREE.InstancedBufferAttribute(new Float32Array(MAX_LANTERNS * 4), 4);
        geometry.setAttribute('instanceParams', this.topParams);

        // Materials
        // 0: Dark Metal (Hook/Cap)
        // 1: Emissive Glass (Bulb)

        // Mat 0
        const darkMat = createUnifiedMaterial(0x2F4F4F, { roughness: 0.7, metalness: 0.5 });

        // Mat 1 (Bulb)
        const bulbMat = createStandardNodeMaterial({
            roughness: 0.2
        });

        // TSL for Top
        const params = attribute('instanceParams', 'vec4');
        const height = params.x;
        const randomPhase = params.y; // Used for swing physics
        const spawnTime = params.w;

        // Pop-In Logic (Scale from 0)
        const age = uTime.sub(spawnTime);
        const popProgress = smoothstep(0.0, 1.0, age.mul(2.0));
        const overshoot = sin(popProgress.mul(10.0)).mul(float(1.0).sub(popProgress)).mul(0.3);
        const popScale = popProgress.add(overshoot).max(0.001);

        // Scale geometry first (around 0,0,0 - which is top center)
        const scaledPos = positionLocal.mul(popScale);

        // Then Offset
        const offsetPos = scaledPos.add(vec3(0, height.mul(popScale), 0));

        // 2. Apply Sway (Top sways fully)
        // Wind at top is max

        // --- PALETTE: Physics Swing ---
        // A pendulum-like motion lagging behind or independent of the stem
        // Seed phase with instance-specific random value to make it rigid per instance
        const swingPhase = uTime.mul(3.0).add(randomPhase);
        const swingAmp = float(0.1); // Swing amplitude
        const swingX = sin(swingPhase).mul(swingAmp);
        const swingZ = cos(swingPhase.mul(0.8)).mul(swingAmp); // Different freq for chaos
        const swingOffset = vec3(swingX, float(0.0), swingZ);

        // Apply global wind sway (tip of stem)
        const stemTipPos = vec3(0, height, 0);
        const tipDeform = applyStandardDeformation(stemTipPos).sub(stemTipPos);
        const finalPos = offsetPos.add(tipDeform).add(swingOffset);

        // Apply to both materials
        darkMat.positionNode = finalPos;
        bulbMat.positionNode = finalPos;

        // --- PALETTE: Juicy Bulb Material ---
        // Plasma Effect
        const noiseScale = float(5.0);
        const noiseSpeed = uTime.mul(2.0);
        const plasmaNoise = mx_noise_float(positionLocal.add(vec3(0, noiseSpeed, 0)).mul(noiseScale));

        // Mix Colors
        // Base is instanceColor. Hot is slightly yellow/white.
        // instanceColor is a node representing the color set via setColorAt
        const baseColor = instanceColor;
        const hotColor = vec3(1.0, 1.0, 0.8);
        const mixFactor = plasmaNoise.mul(0.5).add(0.5); // 0..1

        // Audio Boost (Pulse)
        const audioBoost = uAudioLow.mul(2.0);
        const totalIntensity = float(1.5).add(audioBoost).add(plasmaNoise.mul(0.5));

        const finalColor = mix(baseColor, hotColor, mixFactor);

        // Juicy Rim Light
        const rim = createJuicyRimLight(finalColor, float(2.0), float(3.0), null);

        // 🎨 PALETTE: Twilight Glow for lantern bulbs
        const glowPhaseOffset = params.y; // reuse randomPhase
        const idlePulse = sin(uTime.mul(float(CONFIG.glow.glowPulseFrequency)).add(glowPhaseOffset)).mul(float(CONFIG.glow.glowPulseAmplitude)).add(1.0).mul(float(0.5)).mul(uAudioLow.mul(0.3).add(0.7));
        const targetGlowColor = color(CONFIG.glow.glowColorMap['lantern']);
        const twilightGlowTint = targetGlowColor
            .mul(uTwilight)
            .mul(float(CONFIG.glow.glowIntensityMax))
            .mul(float(0.4).add(idlePulse));
        const biomeTint = BiomeUniforms.global.noteColor.mul(BiomeUniforms.global.shimmer.mul(0.35));

        bulbMat.emissiveNode = finalColor.mul(totalIntensity).add(rim).add(twilightGlowTint).add(biomeTint)
            .mul(circadianNightGlowMult());
        bulbMat.colorNode = finalColor; // Also set base color

        // Create Mesh
        this.topMesh = new THREE.InstancedMesh(geometry, [darkMat, bulbMat], MAX_LANTERNS);
        this.topMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        // Explicitly create instanceColor buffer for use with setColorAt
        this.topMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(MAX_LANTERNS * 3), 3);
        this.topMesh.geometry.setAttribute('instanceColor', this.topMesh.instanceColor);
        this.topMesh.count = 0;
        this.topMesh.castShadow = true;
        this.topMesh.receiveShadow = true;
    }

    private createTopGeometry(): THREE.BufferGeometry {
        // Merged Geometry: Hook (Torus), Cap (Cone), Bulb (Sphere)
        // Relative to Top connection point (0,0,0)

        const positions: number[] = [];
        const normals: number[] = [];
        const indices: number[] = [];
        const uvs: number[] = [];

        let vertexOffset = 0;
        const groups: { start: number, count: number, materialIndex: number }[] = [];

        const addPart = (geo: THREE.BufferGeometry, matIndex: number, transform: THREE.Matrix4) => {
             const posAttr = geo.attributes.position;
             const normAttr = geo.attributes.normal;
             // uv ignored for now

             for(let i=0; i<posAttr.count; i++){
                 _scratchV.set(posAttr.getX(i), posAttr.getY(i), posAttr.getZ(i));
                 _scratchV.applyMatrix4(transform);
                 positions.push(_scratchV.x, _scratchV.y, _scratchV.z);

                 _scratchN.set(normAttr.getX(i), normAttr.getY(i), normAttr.getZ(i));
                 _scratchN.transformDirection(transform);
                 normals.push(_scratchN.x, _scratchN.y, _scratchN.z);
                 uvs.push(0,0);
             }

             // Indices
             if (geo.index) {
                 for(let i=0; i<geo.index.count; i++){
                     indices.push(geo.index.getX(i) + vertexOffset);
                 }
             } else {
                 for(let i=0; i<posAttr.count; i++){
                     indices.push(i + vertexOffset);
                 }
             }

             vertexOffset += posAttr.count;
        };

        // ⚡ OPTIMIZATION: Module scoped scratch matrix to avoid GC spikes
        const m = _scratchMatrixBatch.identity();

        // 1. Hook (Dark Material 0)
        let startIndex = indices.length;

        // Hook Geometry: Torus segment
        // ⚡ OPTIMIZATION: Use shared geometry via registry (deduplicated)
        const hookGeo = getTorusGeometry(0.5, 0.08, 6, 8, Math.PI);
        m.makeRotationZ(-Math.PI/2);
        m.setPosition(0.5, 0, 0);
        addPart(hookGeo, 0, m);

        // Cap (Cone)
        // ⚡ OPTIMIZATION: Use shared geometry via registry (deduplicated)
        const capGeo = getConeGeometry(0.2, 0.2, 6);
        m.makeTranslation(1.0, -0.2, 0);
        addPart(capGeo, 0, m);

        groups.push({ start: startIndex, count: indices.length - startIndex, materialIndex: 0 });

        // 2. Bulb (Emissive Material 1)
        startIndex = indices.length;

        // Bulb Sphere
        const bulbGeo = sharedGeometries.unitSphere; // R=1
        _scratchV.set(1.0, -0.5, 0);
        _scratchN.set(0.25, 0.4, 0.25); // Using _scratchN as scale scratch here to save memory
        // ⚡ OPTIMIZATION: Re-use scratch quaternion to avoid GC spikes
        _scratchQuat.identity();
        m.compose(_scratchV, _scratchQuat, _scratchN);

        addPart(bulbGeo, 1, m);

        groups.push({ start: startIndex, count: indices.length - startIndex, materialIndex: 1 });

        // Build Geometry
        const geo = new THREE.BufferGeometry();
        geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
        geo.setAttribute('normal', new THREE.Float32BufferAttribute(normals, 3));
        geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
        geo.setIndex(indices);

        for (let i = 0; i < groups.length; i++) { geo.addGroup(groups[i].start, groups[i].count, groups[i].materialIndex); }

        return geo;
    }

    register(dummy: THREE.Object3D, options: any) {
        if (!this.initialized) this.init();
        if (this.count >= MAX_LANTERNS) return;

        const i = this.count;
        this.count++;

        // ⚡ OPTIMIZATION: Mark as batched
        dummy.userData.isBatched = true;

        // Transforms
        _scratchMatrixBatch.compose(dummy.position, dummy.quaternion, dummy.scale);
        // Stem
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMatrixBatch.toArray(this.stemMesh!.instanceMatrix.array, (i) * 16);

        // Top
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMatrixBatch.toArray(this.topMesh!.instanceMatrix.array, (i) * 16);

        // Params
        const height = options.height || 2.5;
        const colorHex = options.color || 0xFFA500;
        const spawnTime = options.spawnTime !== undefined ? options.spawnTime : -100.0;
        // ⚡ OPTIMIZATION: Reuse module-scoped scratch color to avoid GC
        const c = _scratchColor.set(colorHex);

        // Generate Random Phase for this instance
        const randomPhase = Math.random() * Math.PI * 2;

        this.stemParams!.setXYZW(i, height, 0, 0, spawnTime);
        this.topParams!.setXYZW(i, height, randomPhase, 0, spawnTime);

        // Use setColorAt
        // ⚡ OPTIMIZATION: Write directly to instanceColor array to bypass .setColorAt overhead.
        if (this.topMesh!.instanceColor) {
            const colorArray = this.topMesh!.instanceColor.array as Float32Array;
            const colorOffset = i * 3;
            colorArray[colorOffset] = c.r;
            colorArray[colorOffset + 1] = c.g;
            colorArray[colorOffset + 2] = c.b;
        }

        this.stemMesh!.instanceMatrix.needsUpdate = true;
        this.topMesh!.instanceMatrix.needsUpdate = true;
        this.stemParams!.needsUpdate = true;
        this.topParams!.needsUpdate = true;
        if (this.topMesh!.instanceColor) this.topMesh!.instanceColor.needsUpdate = true;
    }

    dispose(): void {
        const meshes = [
            this.stemMesh,
            this.topMesh
        ];
        meshes.forEach(mesh => {
            if (mesh && mesh.parent) {
                safeRemoveAndDispose(mesh.parent, mesh);
            }
        });
    }
}

export const lanternBatcher = LanternBatcher.getInstance();

/**
 * TSL nodes for three-tier foliage LOD (hero / mid / far).
 * Hero tier (factor ≈ 0) preserves pre-LOD visuals; mid/far simplify motion and emissive.
 */
import {
    attribute,
    float,
    mix,
    positionLocal,
    smoothstep,
    uniform,
    vec3,
    floor,
    mod,
} from 'three/tsl';
import type { MeshStandardNodeMaterial } from 'three/webgpu';
import { CONFIG } from '../core/config.ts';
import { $sn } from './material-core/tsl-types.ts';
import { calculatePlayerPush, calculateWindSway } from './material-core.ts';
import type { TSLArg } from './material-core.ts';

/** Continuous LOD factor: 0 = hero, 1 = mid, 2 = far, 3+ = culled */
export const aInstanceLodFactor = attribute('instanceLodFactor', 'float');

/** Synced from CONFIG.foliage.lod each frame (batcher-lod.ts). */
export const uLodImpostorMin = uniform(1.55);
export const uLodImpostorMax = uniform(2.05);
/** Debug: tint instances in tier blend bands (set via ?debug=1 panel). */
export const uLodDebugHighlight = uniform(0.0);

export const lodHeroGate = () => smoothstep(float(1.05), float(0.85), aInstanceLodFactor);
export const lodMidOnlyGate = () => {
    const aboveHero = smoothstep(float(0.85), float(1.05), aInstanceLodFactor);
    const belowFar = smoothstep(float(1.95), float(1.55), aInstanceLodFactor);
    return aboveHero.mul(belowFar);
};
export const lodFarGate = () => smoothstep(float(1.55), float(1.95), aInstanceLodFactor);

/** 0→1 weight for impostor cross-fade (meshes fade out as this rises). */
export const lodImpostorBlend = () =>
    smoothstep(uLodImpostorMin, uLodImpostorMax, aInstanceLodFactor);

/** Mesh opacity during impostor handoff — dither-friendly alpha multiplier. */
export const lodMeshOpacity = () => float(1.0).sub(lodImpostorBlend());

/** Instances actively cross-fading between tiers (hero↔mid or mid↔far/impostor). */
export const lodBlendBandGate = () => {
    const f = aInstanceLodFactor;
    const heroMid = smoothstep(float(0.75), float(0.85), f).mul(
        smoothstep(float(1.15), float(1.05), f)
    );
    const midFar = smoothstep(float(1.45), float(1.55), f).mul(
        smoothstep(float(2.15), float(1.95), f)
    );
    return heroMid.add(midFar).clamp(0.0, 1.0);
};

/** Bayer-style screen dither for opacity (reduces hard alpha pops). */
export const lodDitheredOpacity = (baseOpacity: ReturnType<typeof float> = lodMeshOpacity()) => {
    const cell = floor(positionLocal.x.mul(40.0)).add(floor(positionLocal.y.mul(40.0)).mul(3.0));
    const threshold = mod(cell, float(4.0)).div(4.0);
    return baseOpacity.sub(threshold).mul(4.0).clamp(0.0, 1.0);
};

/**
 * Apply impostor cross-fade opacity to a foliage material (call once per material).
 * Hero tier (<120u) opacity stays 1.0 — only far handoff fades.
 */
export function applyFoliageLodMaterialFade(material: MeshStandardNodeMaterial): void {
    if (
        (material as unknown as { userData: Record<string, unknown> }).userData
            ?.foliageLodFadeApplied
    )
        return;
    (material as unknown as { userData: Record<string, unknown> }).userData.foliageLodFadeApplied =
        true;
    material.transparent = true;
    const existing = material.opacityNode;
    const fade = lodDitheredOpacity();
    material.opacityNode = existing ? $sn(existing).mul(fade) : fade;
    const debugTint = vec3(1.0, 0.55, 1.0);
    const band = lodBlendBandGate().mul(uLodDebugHighlight);
    if (material.colorNode) {
        const colorNode = $sn(material.colorNode);
        material.colorNode = mix(colorNode, colorNode.mul(debugTint), band);
    }
}

/** Push CONFIG.foliage.lod impostor thresholds to TSL uniforms (zero alloc). */
export function syncFoliageLodUniforms(): void {
    const lod = CONFIG.foliage?.lod;
    uLodImpostorMin.value = lod?.impostorMinFactor ?? 1.55;
    uLodImpostorMax.value = lod?.impostorMaxFactor ?? 2.05;
}

/** Player push only within hero band */
export const applyPlayerInteractionWithLod = (basePosNode: TSLArg) => {
    const push = calculatePlayerPush(basePosNode).mul(lodHeroGate());
    return basePosNode.add(push);
};

/** Wind sway attenuated in mid/far tiers */
export const calculateWindSwayWithLod = (posNode: TSLArg) => {
    const wind = calculateWindSway(posNode);
    const weight = lodHeroGate().add(lodMidOnlyGate().mul(0.45));
    return wind.mul(weight);
};

/**
 * Full foliage motion offset for LOD-enabled objects.
 * (deformationNode semantics: displaced position minus positionLocal).
 * 🏗️ ARCHITECT: Single source of truth for LOD deformation.
 * Internally composes wind sway and player push. DO NOT wrap with applyPlayerInteraction.
 */
export const foliageDeformationOffset = (
    baseWithAnimPos: TSLArg,
    extraOffset?: ReturnType<typeof float>,
    subtractNode: typeof positionLocal = positionLocal
) => {
    const heroPos = baseWithAnimPos
        .add(calculatePlayerPush(baseWithAnimPos))
        .add(calculateWindSway(baseWithAnimPos));
    const midPos = baseWithAnimPos.add(calculateWindSway(baseWithAnimPos).mul(0.5));
    const farPos = baseWithAnimPos;

    const heroMid = mix(midPos, heroPos, lodHeroGate());
    let blended: ReturnType<typeof mix> = mix(farPos, heroMid, float(1).sub(lodFarGate()));

    if (extraOffset) {
        const extraWeight = lodHeroGate().add(lodMidOnlyGate().mul(0.35));
        blended = blended.add(extraOffset.mul(extraWeight)) as unknown as ReturnType<typeof mix>;
    }

    // Far tier: collapse in sync with impostor cross-fade (not a hard pop)
    const impostorBlend = lodImpostorBlend();
    const collapse = float(1.0).sub(impostorBlend.mul(0.85));
    blended = blended.mul(collapse) as unknown as ReturnType<typeof mix>;

    return blended.sub(subtractNode);
};

/** Absolute displaced position (for materials using positionNode directly) */
export const foliageMotionPosition = (
    baseWithAnimPos: TSLArg,
    extraOffset?: ReturnType<typeof float>
) => foliageDeformationOffset(baseWithAnimPos, extraOffset).add(positionLocal);

/** Scale emissive / sparkle intensity by LOD tier */
export const scaleEmissiveByLod = (emissiveNode: ReturnType<typeof float>) => {
    const weight = lodHeroGate().add(lodMidOnlyGate().mul(0.42)).add(lodFarGate().mul(0.12));
    return emissiveNode.mul(weight);
};

/** Mix a hero-only multiplier toward 1.0 in mid/far (e.g. audio squash) */
export const lodHeroOnlyMultiplier = (
    heroValue: ReturnType<typeof vec3>,
    identity = vec3(1, 1, 1)
) => mix(identity, heroValue, lodHeroGate());

/**
 * 🏗️ ARCHITECT: Standardized TSL deformation chain for LOD-enabled objects
 * that manually compose their offsets instead of using foliageDeformationOffset.
 */
export const applyStandardDeformationWithLod = (basePosNode: any) => {
    return applyPlayerInteractionWithLod(basePosNode.add(calculateWindSwayWithLod(basePosNode)));
};

// src/foliage/lod.ts
// Level-of-Detail (LOD) system for animated foliage
// Provides ~40% FPS improvement at 5k+ objects through distance-based mesh simplification

import * as THREE from 'three';
import {
    color, float, vec3, positionLocal, mix, attribute, uv, sin, cos, positionWorld,
    normalLocal, varyingProperty
} from 'three/tsl';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
import { foliageGroup } from '../world/state.ts';

const _scratchLODMatrix = new THREE.Matrix4();
import {
    CandyPresets,
    calculateWindSway,
    applyPlayerInteraction,
    uTime,
    uAudioLow,
    uAudioHigh,
    uWindSpeed
} from './index.ts';

// --- Configuration ---

export interface LODConfig {
    /** Distance thresholds: [lod1, lod2, cull] in meters */
    thresholds: [number, number, number];
    /** Geometry segment counts for each LOD level [lod0, lod1, lod2] */
    geometrySegments: {
        sphere: [number, number, number];
        cylinder: [number, number, number];
        capsule: [number, number, number];
        helix: [number, number, number];
        rose: [number, number, number];
    };
    /** Maximum instances per LOD level */
    maxInstances: {
        lod0: number;
        lod1: number;
        lod2: number;
    };
}

export const DEFAULT_LOD_CONFIG: LODConfig = {
    thresholds: [120, 365, 480], // Hero / mid / far+cull — aligned with CONFIG.foliage.lod
    geometrySegments: {
        sphere: [16, 8, 4],
        cylinder: [12, 8, 6],
        capsule: [8, 6, 4],
        helix: [16, 10, 6],
        rose: [64, 32, 16],
    },
    maxInstances: {
        lod0: 1000,  // Close, detailed objects
        lod1: 3000,  // Medium distance
        lod2: 5000,  // Far distance (billboards)
    }
};

// --- LOD Level Enum ---

export enum LODLevel {
    LOD0 = 0,  // High detail: full animation
    LOD1 = 1,  // Medium: simplified animation
    LOD2 = 2,  // Low: billboard/minimal animation
    Culled = 3 // Beyond cull distance
}

// --- Geometry Cache ---

const geometryCache = new Map<string, THREE.BufferGeometry>();

/**
 * Creates or retrieves a cached LOD geometry
 */
export function createLODGeometry(
    geometryType: 'sphere' | 'cylinder' | 'capsule' | 'helix' | 'rose' | 'billboard',
    lodLevel: number
): THREE.BufferGeometry {
    const cacheKey = `${geometryType}_lod${lodLevel}`;

    if (geometryCache.has(cacheKey)) {
        return geometryCache.get(cacheKey)!;
    }

    let geometry: THREE.BufferGeometry;
    const config = DEFAULT_LOD_CONFIG.geometrySegments;

    switch (geometryType) {
        case 'sphere': {
            const segments = config.sphere[lodLevel];
            geometry = new THREE.SphereGeometry(1, segments, segments);
            break;
        }
        case 'cylinder': {
            const segments = config.cylinder[lodLevel];
            geometry = new THREE.CylinderGeometry(1, 1, 1, segments).translate(0, 0.5, 0);
            break;
        }
        case 'capsule': {
            const [radSeg, heightSeg] = lodLevel === 0 ? [8, 6] : lodLevel === 1 ? [6, 4] : [4, 3];
            geometry = new THREE.CapsuleGeometry(0.5, 1, heightSeg, radSeg);
            break;
        }
        case 'helix': {
            const segments = config.helix[lodLevel];
            geometry = new THREE.CylinderGeometry(1, 1, 1, segments, segments * 2).translate(0, 0.5, 0);
            break;
        }
        case 'rose': {
            const segments = config.rose[lodLevel];
            geometry = new THREE.TorusKnotGeometry(0.25, 0.08, segments, Math.max(4, segments / 8), 2, 3);
            break;
        }
        case 'billboard': {
            // Simple plane facing camera
            geometry = new THREE.PlaneGeometry(1, 1);
            break;
        }
        default:
            throw new Error(`Unknown geometry type: ${geometryType}`);
    }

    geometryCache.set(cacheKey, geometry);
    return geometry;
}

// --- Material Factory ---

const materialCache = new Map<string, THREE.Material>();

/**
 * Creates simplified materials for each LOD level
 * LOD0: Full effects (wind sway + player interaction + flutter + audio)
 * LOD1: Simple wind sway only (no player interaction, reduced effects)
 * LOD2: No vertex animation (just rotation), minimal shader complexity
 */
export function getLODMaterial(
    baseMaterial: THREE.Material,
    lodLevel: LODLevel,
    geometryType: string
): THREE.Material {
    const cacheKey = `${geometryType}_${lodLevel}_${baseMaterial.uuid || 'default'}`;

    if (materialCache.has(cacheKey)) {
        return materialCache.get(cacheKey)!;
    }

    let material: THREE.Material;

    switch (lodLevel) {
        case LODLevel.LOD0:
            // Use base material with full effects (already set up in TreeBatcher)
            material = baseMaterial.clone();
            break;

        case LODLevel.LOD1:
            // Simplified: wind sway only, no player interaction
            material = createLOD1Material(geometryType, baseMaterial);
            break;

        case LODLevel.LOD2:
            // Minimal: no vertex animation, simple color
            material = createLOD2Material(geometryType, baseMaterial);
            break;

        default:
            material = baseMaterial.clone();
    }

    materialCache.set(cacheKey, material);
    return material;
}

/**
 * LOD1 Material: Simple wind sway only, no player interaction
 */
function createLOD1Material(geometryType: string, baseMaterial: THREE.Material): THREE.Material {
    const instanceColor = varyingProperty('vec3', 'vInstanceColor');

    switch (geometryType) {
        case 'trunk':
        case 'cylinder': {
            const trunkColor = mix(instanceColor.mul(0.6), instanceColor, positionLocal.y);
            return CandyPresets.Clay(0x8B4513, {
                colorNode: trunkColor,
                roughness: 0.8,
                bumpStrength: 0.1, // Reduced bump for LOD1
                rimStrength: 0.2,
                deformationNode: calculateWindSway(positionLocal), // Wind only, no interaction
                triplanar: true
            });
        }

        case 'sphere':
        case 'leaf': {
            // Simple wind sway without flutter or squash
            const sphereDeform = calculateWindSway(positionLocal);
            return CandyPresets.Gummy(0x228B22, {
                colorNode: instanceColor,
                roughness: 0.4,
                transmission: 0.2, // Reduced transmission
                thickness: 0.5,
                deformationNode: sphereDeform,
                rimStrength: 0.4,
                audioReactStrength: 0.2 // Reduced audio response
            });
        }

        case 'capsule':
        case 'branch': {
            const capsuleDeform = calculateWindSway(positionLocal);
            return CandyPresets.Clay(0x8B4513, {
                colorNode: instanceColor,
                roughness: 0.7,
                deformationNode: capsuleDeform,
                rimStrength: 0.3
            });
        }

        case 'helix': {
            const t = positionLocal.y;
            const angle = t.mul(float(Math.PI * 6.0));
            const radius = t.mul(0.3);
            const spiralPos = vec3(cos(angle).mul(radius), t, sin(angle).mul(radius));
            const helixDeform = calculateWindSway(spiralPos);

            return CandyPresets.Gummy(0x00FA9A, {
                colorNode: instanceColor,
                roughness: 0.3,
                deformationNode: helixDeform,
                emissive: 0xFFFFFF,
                emissiveIntensity: 0.3, // Reduced glow
                rimStrength: 0.5
            });
        }

        case 'rose':
        case 'torusKnot': {
            const roseDeform = calculateWindSway(positionLocal);
            return CandyPresets.Sugar(0xFF69B4, {
                colorNode: instanceColor,
                roughness: 0.4,
                deformationNode: roseDeform,
                sheen: 0.5,
                audioReactStrength: 0.3
            });
        }

        default:
            return baseMaterial.clone();
    }
}

/**
 * LOD2 Material: No vertex animation, simple billboard-style rendering
 */
function createLOD2Material(geometryType: string, baseMaterial: THREE.Material): THREE.Material {
    const instanceColor = varyingProperty('vec3', 'vInstanceColor');

    switch (geometryType) {
        case 'trunk':
        case 'cylinder':
            return CandyPresets.Clay(0x8B4513, {
                colorNode: instanceColor,
                roughness: 0.9,
                bumpStrength: 0.05,
                rimStrength: 0.1
                // No deformation - static mesh
            });

        case 'sphere':
        case 'leaf':
            return CandyPresets.Gummy(0x228B22, {
                colorNode: instanceColor,
                roughness: 0.5,
                transmission: 0.1,
                rimStrength: 0.2
                // No deformation - static mesh
            });

        case 'capsule':
        case 'branch':
            return CandyPresets.Clay(0x8B4513, {
                colorNode: instanceColor,
                roughness: 0.8,
                rimStrength: 0.2
                // No deformation - static mesh
            });

        case 'helix':
            return CandyPresets.Gummy(0x00FA9A, {
                colorNode: instanceColor,
                roughness: 0.4,
                emissive: 0xFFFFFF,
                emissiveIntensity: 0.2,
                rimStrength: 0.3
                // No deformation - static mesh
            });

        case 'rose':
        case 'torusKnot':
            return CandyPresets.Sugar(0xFF69B4, {
                colorNode: instanceColor,
                roughness: 0.5,
                sheen: 0.3
                // No deformation - static mesh
            });

        default:
            return baseMaterial.clone();
    }
}

// --- Instance Data Structure ---

interface LODInstanceData {
    id: number;
    position: THREE.Vector3;
    matrix: THREE.Matrix4;
    color: THREE.Color;
    type: string;
    geometryType: string;
    currentLOD: LODLevel;
    baseMaterial: THREE.Material;
}

// --- LOD Manager ---

export class FoliageLODManager {
    private config: LODConfig;
    private instanceData: Map<number, LODInstanceData> = new Map();
    private nextInstanceId = 0;

    // LOD mesh groups for each geometry type
    private lodMeshes: Map<string, Map<LODLevel, THREE.InstancedMesh>> = new Map();

    // Instance counts per LOD level per geometry type
    private lodCounts: Map<string, Map<LODLevel, number>> = new Map();
    // ⚡ OPTIMIZATION: Pre-allocated buffers for LOD updates to prevent GC spikes
    private _lodUpdates: Map<string, Map<LODLevel, { indices: number[]; matrices: THREE.Matrix4[]; colors: THREE.Color[]; count: number }>> = new Map();

    // Temporary objects for calculations (to avoid GC)
    private _tempVec3 = new THREE.Vector3();
    private _tempMatrix = new THREE.Matrix4();
    private _tempColor = new THREE.Color();

    // Billboard setup for LOD2
    private billboardMesh?: THREE.InstancedMesh;

    constructor(config: Partial<LODConfig> = {}) {
        this.config = { ...DEFAULT_LOD_CONFIG, ...config };
        this.initLODMeshes();
    }

    /**
     * Initialize the LOD mesh structure
     */
    private initLODMeshes(): void {
        const geometryTypes = ['trunk', 'sphere', 'capsule', 'helix', 'rose'];

        for (const geomType of geometryTypes) {
            const lodMap = new Map<LODLevel, THREE.InstancedMesh>();
            const countMap = new Map<LODLevel, number>();

            // Create InstancedMesh for each LOD level
            for (let lod = 0; lod < 3; lod++) {
                const lodLevel = lod as LODLevel;
                const maxCount = this.getMaxInstancesForLOD(lodLevel);

                // Create appropriate geometry for this LOD level
                const geometry = createLODGeometry(
                    geomType as any,
                    lodLevel
                );

                // Create base material (will be cloned per instance type)
                const baseMaterial = this.createBaseMaterial(geomType);
                const lodMaterial = getLODMaterial(baseMaterial, lodLevel, geomType);

                const mesh = new THREE.InstancedMesh(geometry, lodMaterial, maxCount);
                mesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(maxCount * 3), 3);
                mesh.castShadow = lodLevel === LODLevel.LOD0; // Only cast shadows for LOD0
                mesh.receiveShadow = lodLevel !== LODLevel.LOD2;
                mesh.count = 0;
                if (mesh) mesh.visible = true;

                // Store reference for cleanup
                mesh.userData.isLODMesh = true;
                mesh.userData.lodLevel = lodLevel;
                mesh.userData.geometryType = geomType;

                lodMap.set(lodLevel, mesh);
                countMap.set(lodLevel, 0);
                foliageGroup.add(mesh);
            }

            this.lodMeshes.set(geomType, lodMap);
            this.lodCounts.set(geomType, countMap);
        }

        // Initialize billboard mesh for impostor rendering
        this.initBillboardMesh();

        console.log('[FoliageLODManager] Initialized LOD system with thresholds:', this.config.thresholds);
    }

    /**
     * Create a base material for a geometry type
     */
    private createBaseMaterial(geometryType: string): THREE.Material {
        switch (geometryType) {
            case 'trunk':
                return CandyPresets.Clay(0x8B4513);
            case 'sphere':
                return CandyPresets.Gummy(0x228B22);
            case 'capsule':
                return CandyPresets.Clay(0x8B4513);
            case 'helix':
                return CandyPresets.Gummy(0x00FA9A);
            case 'rose':
                return CandyPresets.Sugar(0xFF69B4);
            default:
                return CandyPresets.Clay(0x8B4513);
        }
    }

    /**
     * Initialize billboard mesh for LOD2 impostors
     */
    private initBillboardMesh(): void {
        const geometry = createLODGeometry('billboard', 0);
        const material = new THREE.MeshBasicMaterial({
            color: 0xffffff,
            transparent: true,
            opacity: 0.8,
            side: THREE.DoubleSide
        });

        this.billboardMesh = new THREE.InstancedMesh(
            geometry,
            material,
            this.config.maxInstances.lod2
        );
        this.billboardMesh.instanceColor = new THREE.InstancedBufferAttribute(
            new Float32Array(this.config.maxInstances.lod2 * 3),
            3
        );
        this.billboardMesh.count = 0;
        this.billboardMesh.visible = false; // Hidden by default
        this.billboardMesh.userData.isBillboard = true;

        foliageGroup.add(this.billboardMesh);
    }

    /**
     * Get max instances for a LOD level
     */
    private getMaxInstancesForLOD(lodLevel: LODLevel): number {
        switch (lodLevel) {
            case LODLevel.LOD0:
                return this.config.maxInstances.lod0;
            case LODLevel.LOD1:
                return this.config.maxInstances.lod1;
            case LODLevel.LOD2:
                return this.config.maxInstances.lod2;
            default:
                return 100;
        }
    }

    /**
     * Calculate LOD level based on distance from camera
     */
    calculateLODLevel(distanceSq: number): LODLevel {
        const [lod1Dist, lod2Dist, cullDist] = this.config.thresholds;

        // ⚡ OPTIMIZATION: Use distanceToSquared to eliminate Math.sqrt() overhead in high-frequency LOD loop
        if (distanceSq >= cullDist * cullDist) {
            return LODLevel.Culled;
        } else if (distanceSq >= lod2Dist * lod2Dist) {
            return LODLevel.LOD2;
        } else if (distanceSq >= lod1Dist * lod1Dist) {
            return LODLevel.LOD1;
        }
        return LODLevel.LOD0;
    }

    /**
     * Register a new foliage object with the LOD system
     * Returns the instance ID for later updates
     */
    registerObject(
        matrix: THREE.Matrix4,
        color: THREE.Color,
        type: string,
        geometryType: string,
        baseMaterial?: THREE.Material
    ): number {
        const id = this.nextInstanceId++;

        // Extract position from matrix
        this._tempVec3.setFromMatrixPosition(matrix);

        const data: LODInstanceData = {
            id,
            position: this._tempVec3.clone(),
            matrix: matrix.clone(),
            color: color.clone(),
            type,
            geometryType,
            currentLOD: LODLevel.LOD0, // Will be updated in first frame
            baseMaterial: baseMaterial || this.createBaseMaterial(geometryType)
        };

        this.instanceData.set(id, data);
        return id;
    }

    /**
     * Register multiple instances at once (batch registration)
     */
    registerBatch(
        matrices: THREE.Matrix4[],
        colors: THREE.Color[],
        type: string,
        geometryType: string,
        baseMaterial?: THREE.Material
    ): number[] {
        const ids: number[] = [];
        for (let i = 0; i < matrices.length; i++) {
            const id = this.registerObject(
                matrices[i],
                colors[i],
                type,
                geometryType,
                baseMaterial
            );
            ids.push(id);
        }
        return ids;
    }

    /**
     * Update LOD levels based on camera position
     * Call this every frame
     */
    update(cameraPosition: THREE.Vector3): void {
        // Reset counts
        for (const [geomType, countMap] of this.lodCounts) {
            for (let lod = 0; lod < 3; lod++) {
                countMap.set(lod as LODLevel, 0);
            }
        }

        // Initialize pre-allocated update structure if needed
        for (const geomType of this.lodMeshes.keys()) {
            if (!this._lodUpdates.has(geomType)) {
                this._lodUpdates.set(geomType, new Map());
                for (let lod = 0; lod < 3; lod++) {
                    this._lodUpdates.get(geomType)!.set(lod as LODLevel, {
                        indices: [],
                        matrices: [],
                        colors: [],
                        count: 0
                    });
                }
            } else {
                // Just reset counts to 0 instead of allocating new arrays
                for (let lod = 0; lod < 3; lod++) {
                    const updateData = this._lodUpdates.get(geomType)!.get(lod as LODLevel);
                    if (updateData) {
                        updateData.count = 0;
                        // ⚡ OPTIMIZATION: We don't null out arrays or recreate them, just reset count
                    }
                }
            }
        }

        // Calculate LOD for each instance
        for (const [id, data] of this.instanceData) {
            const dx = data.position.x - cameraPosition.x; const dy = data.position.y - cameraPosition.y; const dz = data.position.z - cameraPosition.z; const distanceSq = dx*dx + dy*dy + dz*dz;
            const newLOD = this.calculateLODLevel(distanceSq);

            // Update stored LOD level
            data.currentLOD = newLOD;

            // Skip culled instances
            if (newLOD === LODLevel.Culled) {
                continue;
            }

            // Add to appropriate LOD update batch (using pre-allocated arrays)
            const geomUpdates = this._lodUpdates.get(data.geometryType);
            if (geomUpdates) {
                const lodUpdate = geomUpdates.get(newLOD);
                if (lodUpdate) {
                    const idx = lodUpdate.count++;
                    lodUpdate.indices[idx] = id;
                    lodUpdate.matrices[idx] = data.matrix;
                    lodUpdate.colors[idx] = data.color;
                }
            }
        }

        // Apply updates to InstancedMeshes
        for (const [geomType, geomUpdates] of this._lodUpdates) {
            for (let lod = 0; lod < 3; lod++) {
                const lodLevel = lod as LODLevel;
                const update = geomUpdates.get(lodLevel);
                const mesh = this.lodMeshes.get(geomType)?.get(lodLevel);

                if (update && mesh) {
                    this.updateInstancedMesh(mesh, update.matrices, update.colors, update.count);
                    this.lodCounts.get(geomType)?.set(lodLevel, update.count);
                }
            }
        }

        // Update billboard orientations for LOD2 instances
        this.updateBillboards(cameraPosition);
    }

    /**
     * Update an InstancedMesh with new instance data
     */
    private updateInstancedMesh(
        mesh: THREE.InstancedMesh,
        matrices: THREE.Matrix4[],
        colors: THREE.Color[],
        elementCount: number
    ): void {
        const count = Math.min(elementCount, mesh.instanceMatrix.count);
        mesh.count = count;

        for (let i = 0; i < count; i++) {
            // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        matrices[i].toArray(mesh.instanceMatrix.array, (i) * 16);
            // ⚡ OPTIMIZATION: Write directly to instanceColor array to bypass .setColorAt overhead.
            if (mesh.instanceColor) {
                const colorArray = mesh.instanceColor.array as Float32Array;
                const colorOffset = i * 3;
                const c = colors[i];
                colorArray[colorOffset] = c.r;
                colorArray[colorOffset + 1] = c.g;
                colorArray[colorOffset + 2] = c.b;
            }
        }

        mesh.instanceMatrix.needsUpdate = true;
        if (mesh.instanceColor) {
            mesh.instanceColor.needsUpdate = true;
        }
    }

    /**
     * Update billboard orientations to face camera
     */
    private updateBillboards(cameraPosition: THREE.Vector3): void {
        if (!this.billboardMesh || this.billboardMesh.count === 0) return;

        // Billboards automatically face camera if we set the mesh to lookAt
        // For true billboarding in InstancedMesh, we'd need custom shader
        // For now, we just ensure the mesh faces the camera
        this.billboardMesh.lookAt(cameraPosition);
    }

    /**
     * Remove an instance from the LOD system
     */
    unregisterObject(id: number): boolean {
        return this.instanceData.delete(id);
    }

    /**
     * Get the current LOD level for an instance
     */
    getInstanceLOD(id: number): LODLevel | undefined {
        return this.instanceData.get(id)?.currentLOD;
    }

    /**
     * Update the transform of an existing instance
     */
    updateInstanceTransform(id: number, matrix: THREE.Matrix4): boolean {
        const data = this.instanceData.get(id);
        if (!data) return false;

        data.matrix.copy(matrix);
        data.position.setFromMatrixPosition(matrix);
        return true;
    }

    /**
     * Get statistics about the current LOD distribution
     */
    getStats(): {
        totalInstances: number;
        lodDistribution: { [key in LODLevel]: number };
        geometryCounts: { [geometryType: string]: { [lod in LODLevel]?: number } };
    } {
        const lodDistribution = {
            [LODLevel.LOD0]: 0,
            [LODLevel.LOD1]: 0,
            [LODLevel.LOD2]: 0,
            [LODLevel.Culled]: 0
        };

        const geometryCounts: { [geometryType: string]: { [lod in LODLevel]?: number } } = {};

        // Count by LOD level
        for (const data of this.instanceData.values()) {
            lodDistribution[data.currentLOD]++;

            if (!geometryCounts[data.geometryType]) {
                geometryCounts[data.geometryType] = {};
            }
            const current = geometryCounts[data.geometryType][data.currentLOD] || 0;
            geometryCounts[data.geometryType][data.currentLOD] = current + 1;
        }

        return {
            totalInstances: this.instanceData.size,
            lodDistribution,
            geometryCounts
        };
    }

    /**
     * Set new distance thresholds
     */
    setThresholds(thresholds: [number, number, number]): void {
        this.config.thresholds = thresholds;
    }

    /**
     * Get all LOD meshes for a geometry type (for external manipulation)
     */
    getLODMeshes(geometryType: string): Map<LODLevel, THREE.InstancedMesh> | undefined {
        return this.lodMeshes.get(geometryType);
    }

    /**
     * Dispose of all LOD resources
     */
    dispose(): void {
        // Dispose of all meshes
        for (const lodMap of this.lodMeshes.values()) {
            for (const mesh of lodMap.values()) {
                // ⚡ OPTIMIZATION: Replaced manual removal with safeRemoveAndDispose to prevent VRAM leaks
                mesh.userData.preventMaterialDispose = true;
                safeRemoveAndDispose(foliageGroup, mesh, true);
            }
        }
        this.lodMeshes.clear();

        // Dispose billboard
        if (this.billboardMesh) {
            safeRemoveAndDispose(foliageGroup, this.billboardMesh, true);
        }

        // Clear caches
        geometryCache.clear();
        materialCache.clear();
        this.instanceData.clear();
        this.lodCounts.clear();
    }
}

// --- Helper Classes for TreeBatcher Integration ---

/**
 * LOD-enabled batch data for a single tree instance
 */
export interface LODTreeInstance {
    id: number;
    type: string;
    componentIds: { [geometryType: string]: number };
}

/**
 * Helper class to integrate LOD with the existing TreeBatcher
 * This provides a bridge between the old registration system and the new LOD system
 */
export class LODTreeBatcher {
    private lodManager: FoliageLODManager;
    private treeInstances: Map<number, LODTreeInstance> = new Map();
    private nextTreeId = 0;

    constructor(config?: Partial<LODConfig>) {
        this.lodManager = new FoliageLODManager(config);
    }

    /**
     * Register a tree group with LOD support
     * Decomposes the tree into components and registers each with appropriate LOD
     */
    registerTree(group: THREE.Group, type: string): number {
        const treeId = this.nextTreeId++;
        const componentIds: { [geometryType: string]: number } = {};

        // ⚡ OPTIMIZATION: Ensure world matrix is ready without deep traversal
        group.updateWorldMatrix(false, false);

        // Traverse and register each mesh component
        group.traverse((child) => {
            if ((child as THREE.Mesh).isMesh) {
                const mesh = child as THREE.Mesh;
                const mat = (Array.isArray(mesh.material) ? mesh.material[0] : mesh.material) as THREE.MeshStandardMaterial;
                // ⚡ OPTIMIZATION: Bypass recursive updateWorldMatrix
                _scratchLODMatrix.multiplyMatrices(group.matrixWorld, mesh.matrix);
                const col = mat.color || new THREE.Color(0xFFFFFF);

                // Map geometry types to our LOD categories
                let geometryType: string | null = null;

                switch (mesh.geometry.type) {
                    case 'CylinderGeometry':
                        geometryType = 'trunk';
                        break;
                    case 'SphereGeometry':
                        geometryType = 'sphere';
                        break;
                    case 'CapsuleGeometry':
                        geometryType = 'capsule';
                        break;
                    case 'TubeGeometry':
                        geometryType = 'helix';
                        break;
                    case 'TorusKnotGeometry':
                        geometryType = 'rose';
                        break;
                }

                if (geometryType) {
                    const instanceId = this.lodManager.registerObject(
                        _scratchLODMatrix,
                        col,
                        type,
                        geometryType,
                        mat
                    );
                    componentIds[geometryType] = instanceId;
                    if (mesh) mesh.visible = false; // Hide original mesh
                }
            }
        });

        const treeInstance: LODTreeInstance = {
            id: treeId,
            type,
            componentIds
        };

        this.treeInstances.set(treeId, treeInstance);
        return treeId;
    }

    /**
     * Update LOD levels - call every frame
     */
    update(cameraPosition: THREE.Vector3): void {
        this.lodManager.update(cameraPosition);
    }

    /**
     * Get LOD statistics
     */
    getStats() {
        return this.lodManager.getStats();
    }

    /**
     * Dispose of all resources
     */
    dispose(): void {
        this.lodManager.dispose();
        this.treeInstances.clear();
    }

    /**
     * Get the underlying LOD manager for advanced operations
     */
    getLODManager(): FoliageLODManager {
        return this.lodManager;
    }
}

