export function createClayMaterial(
    hexColor: number | string | THREE.Color,
    opts: UnifiedMaterialOptions = {}
) {
    return CandyPresets.Clay(hexColor, opts);
}

export function createCandyMaterial(
    hexColor: number | string | THREE.Color,
    opts: UnifiedMaterialOptions = {}
) {
    return CandyPresets.Gummy(hexColor, opts);
}

export function createTexturedClay(hexColor: number | string | THREE.Color, options: any = {}) {
    return createUnifiedMaterial(hexColor, {
        roughness: options.roughness || 0.6,
        bumpStrength: options.bumpStrength || 0.1,
        noiseScale: options.noiseScale || 5.0,
        triplanar: true,
    });
}

export function createSugaredMaterial(hexColor: number | string | THREE.Color, options: any = {}) {
    return createUnifiedMaterial(hexColor, {
        roughness: 0.5,
        bumpStrength: 0.6,
        noiseScale: options.crystalScale || 50.0,
        sheen: 1.0,
        sheenColor: 0xffffff,
        subsurfaceStrength: options.subsurface || 0.2,
    });
}

export function createGradientMaterial(
    colorBottom: number | string | THREE.Color,
    colorTop: number | string | THREE.Color,
    roughness = 0.9
) {
    const windTime = uTime.mul(uWindSpeed.add(0.5));
    const swayPhase = positionWorld.x.mul(0.5).add(positionWorld.z.mul(0.5)).add(windTime);
    const swayAmount = sin(swayPhase).mul(0.1).mul(uWindSpeed.add(0.2));

    const heightFactor = positionLocal.y.max(0.0);

    const windBend = vec3(
        uWindDirection.x.mul(swayAmount).mul(heightFactor.pow(2.0)),
        float(0.0),
        uWindDirection.z.mul(swayAmount).mul(heightFactor.pow(2.0))
    );

    const pushOffset = calculatePlayerPush(positionLocal);

    const totalDeformation = positionLocal.add(windBend).add(pushOffset);

    const gradientNode = mix(color(colorBottom), color(colorTop), uv().y);

    return createUnifiedMaterial(colorBottom, {
        colorNode: gradientNode,
        deformationNode: totalDeformation,
        roughness: roughness,
        bumpStrength: 0.2,
        noiseScale: 4.0,
        triplanar: true,
        metalness: 0.0,
        rimStrength: 0.3,
        rimPower: 3.0,
    });
}

export function createStandardNodeMaterial(options: any = {}) {
    const mat = new MeshStandardNodeMaterial();
    if (options.color !== undefined) mat.colorNode = color(options.color);
    if (options.roughness !== undefined) mat.roughnessNode = float(options.roughness);
    if (options.metalness !== undefined) mat.metalnessNode = float(options.metalness);
    if (options.emissive !== undefined) mat.emissiveNode = color(options.emissive);
    if (options.emissiveIntensity !== undefined && options.emissive !== undefined) {
        mat.emissiveNode = color(options.emissive).mul(float(options.emissiveIntensity));
    }

    if (options.transparent) mat.transparent = true;
    if (options.opacity !== undefined) mat.opacity = options.opacity;
    if (options.side !== undefined) mat.side = options.side;
    if (options.blending !== undefined) mat.blending = options.blending;
    if (options.depthWrite !== undefined) mat.depthWrite = options.depthWrite;

    return mat;
}

export function createTransparentNodeMaterial(options: any = {}) {
    const mat = createStandardNodeMaterial(options);
    mat.transparent = true;
    mat.depthWrite = options.depthWrite !== undefined ? options.depthWrite : false;
    return mat;
}

import {
    color,
    float,
    vec3,
    Fn,
    dot,
    max,
    mx_noise_float,
    positionWorld,
    positionLocal,
    normalWorld,
    normalLocal,
    cameraPosition,
    sin,
    mix,
    abs,
    normalize,
    smoothstep,
} from 'three/tsl';
import { uTime, uAudioHigh } from './shared-resources.ts';
import type { TSLArg, TSLArgOpt } from './tsl-types.ts';

export const triplanarNoise = Fn<[TSLArg, TSLArg]>(([pos, scale]) => {
    const p = pos.mul(scale);
    const n = abs(normalWorld);

    const noiseX = mx_noise_float(vec3(p.y, p.z, 0.0));
    const noiseY = mx_noise_float(vec3(p.x, p.z, 0.0));
    const noiseZ = mx_noise_float(vec3(p.x, p.y, 0.0));

    const blend = n.div(n.x.add(n.y).add(n.z));
    return noiseX.mul(blend.x).add(noiseY.mul(blend.y)).add(noiseZ.mul(blend.z));
});

export const perturbNormal = Fn<[TSLArg, TSLArg, TSLArg, TSLArg]>(
    ([pos, normal, scale, strength]) => {
        const eps = float(0.01);
        const s = scale;

        const n0 = mx_noise_float(pos.mul(s));
        const nX = mx_noise_float(pos.add(vec3(eps, 0.0, 0.0)).mul(s));
        const nY = mx_noise_float(pos.add(vec3(0.0, eps, 0.0)).mul(s));
        const nZ = mx_noise_float(pos.add(vec3(0.0, 0.0, eps)).mul(s));

        const dx = nX.sub(n0).div(eps);
        const dy = nY.sub(n0).div(eps);
        const dz = nZ.sub(n0).div(eps);

        const noiseGrad = vec3(dx, dy, dz);
        const perturbed = normalize(normal.sub(noiseGrad.mul(strength)));
        return perturbed;
    }
);

export const createRimLight = Fn<[TSLArg, TSLArg, TSLArg, TSLArgOpt]>(
    ([colorNode, intensity, power, normalNode]) => {
        const viewDir = normalize(cameraPosition.sub(positionWorld));
        const N = normalNode || normalWorld;

        const NdotV = abs(dot(N, viewDir));
        const rim = float(1.0).sub(NdotV).pow(power);
        return colorNode.mul(rim).mul(intensity);
    }
);

export const createJuicyRimLight = Fn<[TSLArg, TSLArg, TSLArg, TSLArgOpt]>(
    ([baseColor, intensity, power, normalNode]) => {
        const viewDir = normalize(cameraPosition.sub(positionWorld));
        const N = normalNode || normalWorld;
        const NdotV = abs(dot(N, viewDir));
        const rim = float(1.0).sub(NdotV).pow(power);

        const pulse = sin(uTime.mul(3.0)).mul(0.2).add(0.8);
        const audioBoost = uAudioHigh.mul(2.0);

        const magicColor = color(0x00ffff);
        const colorMix = rim.mul(0.5).add(audioBoost.mul(0.2)).min(1.0);
        const finalColor = mix(baseColor, magicColor, colorMix);

        const finalIntensity = intensity.mul(pulse).add(audioBoost);

        return finalColor.mul(rim).mul(finalIntensity);
    }
);

export const createSugarSparkle = Fn<[TSLArgOpt, TSLArg, TSLArg, TSLArg]>(
    ([normalNode, scale, density, intensity]) => {
        const viewDir = normalize(cameraPosition.sub(positionWorld));

        const noiseCoord = positionLocal.mul(scale).add(viewDir.mul(2.0));

        const noiseVal = mx_noise_float(noiseCoord);

        const threshold = float(1.0).sub(density);

        const sparkle = smoothstep(threshold, float(1.0), noiseVal);

        const audioBoost = uAudioHigh.mul(3.0).add(1.0);

        const effectiveNormal = normalNode ?? normalLocal;
        const NdotV = abs(dot(effectiveNormal, viewDir));
        const fresnel = float(1.0).sub(NdotV).pow(2.0).add(0.5);

        return sparkle.mul(intensity).mul(audioBoost).mul(fresnel);
    }
);

export const addRimLight = Fn<[TSLArg, TSLArgOpt]>(([baseColorNode, normalNode]) => {
    return baseColorNode.add(createRimLight(color(0xffffff), float(0.5), float(3.0), normalNode));
});

export const colorFromNote = Fn<[TSLArg]>(([noteIndex]) => {
    const angle = noteIndex.div(12.0).mul(6.28318);

    const r = sin(angle).mul(0.5).add(0.5);
    const g = sin(angle.add(2.0944)).mul(0.5).add(0.5);
    const b = sin(angle.add(4.1888)).mul(0.5).add(0.5);

    return vec3(r, g, b);
});

import * as THREE from 'three';
import type { ShaderNodeObject } from 'three/src/nodes/tsl/TSLCore.js';
import {
    color,
    float,
    uv,
    mix,
    vec3,
    dot,
    max,
    mx_noise_float,
    positionLocal,
    positionWorld,
    normalWorld,
    normalLocal,
    cameraPosition,
    sin,
    abs,
    normalize,
    smoothstep,
    exp,
} from 'three/tsl';
import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import type { Node } from 'three/webgpu';
import { applyGlitch } from '../glitch.ts';
import {
    uTime,
    uAudioHigh,
    uGlitchIntensity,
    uGlitchExplosionCenter,
    uGlitchExplosionRadius,
} from './shared-resources.ts';
import { triplanarNoise, perturbNormal, createRimLight } from './tsl-nodes.ts';
import { $sn } from './tsl-types.ts';

export interface UnifiedMaterialOptions {
    colorNode?: Node;
    deformationNode?: Node;
    roughness?: number;
    metalness?: number;
    bumpStrength?: number;
    noiseScale?: number;
    triplanar?: boolean;
    side?: THREE.Side;
    transmission?: number;
    thickness?: number;
    ior?: number;
    thicknessDistortion?: number;
    subsurfaceStrength?: number;
    subsurfaceColor?: number | string | THREE.Color;
    iridescenceStrength?: number;
    iridescenceFresnelPower?: number;
    sheen?: number;
    sheenColor?: number | string | THREE.Color;
    sheenRoughness?: number;
    animateMoisture?: boolean;
    animatePulse?: boolean;
    audioReactStrength?: number;
    emissive?: number | string | THREE.Color;
    emissiveIntensity?: number;
    contactDarkening?: number;
    contactDarkeningHeight?: number;
    rimStrength?: number;
    rimColor?: number | string | THREE.Color;
    rimPower?: number;
}

export function createUnifiedMaterial(
    hexColor: number | string | THREE.Color,
    options: UnifiedMaterialOptions = {}
) {
    const {
        colorNode = null,
        deformationNode = null,
        roughness = 0.5,
        metalness = 0.0,
        bumpStrength = 0.0,
        noiseScale = 5.0,
        triplanar = false,
        side = THREE.FrontSide,
        emissive = null,
        emissiveIntensity = 1.0,
        transmission = 0.0,
        thickness = 0.0,
        ior = 1.5,
        thicknessDistortion = 0.0,
        subsurfaceStrength = 0.0,
        subsurfaceColor = 0xffffff,
        iridescenceStrength = 0.0,
        iridescenceFresnelPower = 4.0,
        sheen = 0.0,
        sheenColor = 0xffffff,
        sheenRoughness = 1.0,
        animateMoisture = false,
        animatePulse = false,
        audioReactStrength = 0.0,
        contactDarkening = 0.0,
        contactDarkeningHeight = 1.0,
        rimStrength = 0.0,
        rimColor = 0xffffff,
        rimPower = 3.0,
    } = options;

    const material = new MeshPhysicalNodeMaterial();

    if (colorNode) {
        material.colorNode = colorNode;
    } else {
        material.colorNode = color(hexColor);
    }

    if (contactDarkening > 0.0) {
        const gradient = smoothstep(float(0.0), float(contactDarkeningHeight), positionLocal.y).pow(
            2.0
        );
        const aoFactor = mix(float(1.0).sub(float(contactDarkening)), float(1.0), gradient);
        material.colorNode = $sn(material.colorNode).mul(aoFactor);
    }
    material.roughnessNode = float(roughness);
    material.metalnessNode = float(metalness);
    material.side = side;

    if (emissive !== null) {
        material.emissiveNode = color(emissive).mul(float(emissiveIntensity));
    }

    let surfaceNoise: any = float(0.0);

    if (bumpStrength > 0.0 || thicknessDistortion > 0.0 || animateMoisture) {
        let pos = positionLocal;
        if (animateMoisture) {
            const timeOffset = vec3(0.0, uTime.mul(0.2), 0.0);
            pos = pos.add(timeOffset);
        }

        if (triplanar) {
            surfaceNoise = triplanarNoise(pos, float(noiseScale));
        } else {
            surfaceNoise = mx_noise_float(pos.mul(float(noiseScale)));
        }
    }

    if (bumpStrength > 0.0) {
        material.normalNode = perturbNormal(
            positionLocal,
            normalWorld,
            float(noiseScale),
            float(bumpStrength)
        );

        const cavity = smoothstep(0.3, 0.7, surfaceNoise);
        material.colorNode = $sn(material.colorNode).mul(cavity.mul(0.5).add(0.5));
    }

    if (animateMoisture) {
        const wetness = surfaceNoise.mul(0.3);
        material.roughnessNode = $sn(material.roughnessNode).sub(wetness);
    }

    if (transmission > 0.0) {
        material.transmissionNode = float(transmission);
        material.iorNode = float(ior);
        material.transparent = true;

        let thickNode = float(thickness);
        if (thicknessDistortion > 0.0) {
            thickNode = thickNode.mul(surfaceNoise.mul(thicknessDistortion).add(1.0));
        }
        material.thicknessNode = thickNode;

        const absorption = exp(thickNode.negate().mul(0.5));
        material.colorNode = $sn(material.colorNode).mul(absorption.add(0.2));
    }

    if (subsurfaceStrength > 0.0) {
        const lightDir = normalize(vec3(0.5, 1.0, 0.5));

        const NdotL = dot(normalWorld, lightDir);
        const wrap = float(1.0).sub(max(0.0, NdotL)).pow(2.0);

        const sssColorNode = color(subsurfaceColor);
        const sssEffect = wrap.mul(subsurfaceStrength).mul(sssColorNode);
        material.colorNode = $sn(material.colorNode).add(sssEffect);
    }

    if (iridescenceStrength > 0.0) {
        const viewDir = normalize(cameraPosition.sub(positionWorld));
        const NdotV = abs(dot(normalWorld, viewDir));

        const fresnel = float(1.0).sub(NdotV).pow(float(iridescenceFresnelPower));

        const irisR = sin(fresnel.mul(10.0));
        const irisG = sin(fresnel.mul(10.0).add(2.0));
        const irisB = sin(fresnel.mul(10.0).add(4.0));

        const rainbow = vec3(irisR, irisG, irisB).mul(0.5).add(0.5);

        material.emissiveNode = rainbow.mul(iridescenceStrength).mul(fresnel);
    }

    if (animatePulse) {
        const pulse = sin(uTime.mul(3.0)).mul(0.2).add(0.8);
        material.emissiveNode = $sn(material.emissiveNode ?? color(0x000000)).add(
            $sn(material.colorNode).mul(pulse.mul(0.2))
        );
    }

    if (sheen > 0.0) {
        material.sheen = sheen;
        material.sheenNode = color(sheenColor);
        material.sheenRoughnessNode = float(sheenRoughness);
    }

    const basePos: ShaderNodeObject<Node> = $sn(deformationNode ?? material.positionNode ?? positionLocal);

    const distToGlitch = positionWorld.distance(uGlitchExplosionCenter);
    const localGlitchFactor = float(1.0).sub(
        smoothstep(float(0.0), uGlitchExplosionRadius, distToGlitch)
    );
    const isActive = uGlitchExplosionRadius.greaterThan(0.0);
    const localIntensity = localGlitchFactor.mul(float(1.5));
    const combinedIntensity = uGlitchIntensity.add(isActive.select(localIntensity, float(0.0)));

    const glitchRes = applyGlitch(uv(), basePos, combinedIntensity);

    material.positionNode = glitchRes.position;

    if (audioReactStrength > 0.0) {
        const singPulse = uAudioHigh.mul(audioReactStrength);

        const singGlow = $sn(material.colorNode).mul(singPulse).mul(0.5);
        material.emissiveNode = $sn(material.emissiveNode ?? color(0x000000)).add(singGlow);

        const currentPos: ShaderNodeObject<Node> = $sn(material.positionNode ?? positionLocal);

        const vibrationScale = float(20.0);
        const vibrationSpeed = float(10.0);
        const flutterNoise = mx_noise_float(
            positionLocal.mul(vibrationScale).add(uTime.mul(vibrationSpeed))
        );

        const flutterAmp = singPulse.mul(0.02);

        const vibration = normalLocal.mul(flutterNoise).mul(flutterAmp);

        material.positionNode = currentPos.add(vibration);
    }

    if (rimStrength > 0.0) {
        const rimColorNode = color(rimColor);
        const rimEffect = createRimLight(
            rimColorNode,
            float(rimStrength),
            float(rimPower),
            material.normalNode
        );

        material.emissiveNode = $sn(material.emissiveNode ?? color(0x000000)).add(rimEffect);
    }

    material.userData.isUnified = true;
    return material;
}

// src/foliage/mirrors.ts

import * as THREE from 'three';
import {
    float, vec3, vec2, color, positionWorld, normalWorld, cameraPosition, normalize,
    reflect, sin, abs, dot,
    texture, uniform
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { attachReactivity, createRimLight, uAudioHigh, uTime } from './index.ts';

// Global texture for the "Dream Reflection"
// Since we don't have a real cubemap, we generate a static noise/gradient texture
let _dreamEnvTexture: THREE.DataTexture | null = null;

function getDreamEnvTexture(): THREE.DataTexture {
    if (_dreamEnvTexture) return _dreamEnvTexture;

    const size = 512;
    const data = new Uint8Array(size * size * 4);

    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            const idx = (i * size + j) * 4;

            // Normalized coords
            const u = j / size;
            const v = i / size;

            // Sky gradient (top is blue/purple, bottom is pink/orange)
            const skyColor = new THREE.Color().setHSL(0.6 + u * 0.1, 0.8, 0.2 + v * 0.6);

            // Add some "cloud" noise
            const noise = Math.sin(u * 20.0 + v * 15.0) * 0.5 + 0.5;
            const cloudColor = new THREE.Color(0xFFFFFF);

            skyColor.lerp(cloudColor, noise * 0.3 * (1.0 - v)); // More clouds at bottom

            data[idx] = Math.floor(skyColor.r * 255);
            data[idx + 1] = Math.floor(skyColor.g * 255);
            data[idx + 2] = Math.floor(skyColor.b * 255);
            data[idx + 3] = 255;
        }
    }

    _dreamEnvTexture = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
    _dreamEnvTexture.wrapS = THREE.RepeatWrapping;
    _dreamEnvTexture.wrapT = THREE.RepeatWrapping;
    _dreamEnvTexture.minFilter = THREE.LinearFilter;
    _dreamEnvTexture.magFilter = THREE.LinearFilter;
    _dreamEnvTexture.needsUpdate = true;

    return _dreamEnvTexture;
}

export interface MirrorOptions {
    scale?: number;
    shards?: number;
}

/**
 * Creates a "Melody Mirror" - A floating shard that reflects a dream world.
 * The reflection distorts based on audio pitch (Channel 2 Note).
 *
 * @param {MirrorOptions} options
 * @param {number} options.scale - Size of the mirror
 * @param {number} options.shards - Number of shards in the cluster (1 = single mirror)
 */
export function createMelodyMirror(options: MirrorOptions = {}): THREE.Group {
    const scale = options.scale || 1.0;
    const shardCount = options.shards || 3;

    const group = new THREE.Group();
    group.userData.type = 'melody_mirror';

    // Shared material for all shards
    // We use a custom TSL material to simulate the reflection

    const envMap = getDreamEnvTexture();

    // Create the material
    const material = new MeshStandardNodeMaterial();
    material.roughnessNode = float(0.1);
    material.metalnessNode = float(1.0);

    // --- TSL Reflection Logic ---

    // 1. Calculate View Vector and Reflection Vector
    const viewDir = normalize(cameraPosition.sub(positionWorld));
    const N = normalWorld;

    // Base Reflection Vector
    const R = reflect(viewDir.negate(), N);

    // 2. Audio Distortion
    // We want the mirror surface to ripple based on melody
    // Channel 2 Note determines the ripple frequency/pattern
    // Volume (trigger) determines intensity

    // Use uAudioHigh as a proxy for melody activity if specific channel data isn't easily bound globally without per-object uniforms
    // ideally we'd pass specific channel data, but for now we use global uniforms + time

    // Distort R based on noise and audio
    // We simulate a ripple by adding a perturbation to the reflection vector lookup

    // "Melody" warp:
    // Create a time-varying signal
    const warpTime = uTime.mul(2.0);
    const warpSignal = sin(positionWorld.y.mul(5.0).add(warpTime));

    // Intensity driven by audio
    const warpIntensity = uAudioHigh.mul(0.2).add(0.05); // Base warping + audio kick

    // Apply distortion to the UV lookup for the environment map
    // Map spherical coordinates (approx) to UV
    // Simple planar mapping for the fake environment:
    const uvReflect = vec2(
        R.x.mul(0.5).add(0.5),
        R.y.mul(0.5).add(0.5)
    );

    // Add distortion
    const distortedUV = uvReflect.add(vec2(warpSignal, warpSignal).mul(warpIntensity));

    // Sample the environment map
    // We use a texture node with explicit UVs
    const reflectionColor = texture(envMap, distortedUV).rgb;

    // 3. Fresnel / Rim (Using Helper)
    // Create a blue-ish rim light
    const rimColor = color(0xCCDDFF);
    const rimEffect = createRimLight(rimColor, float(2.0), float(3.0), N);

    // 4. Combine
    // Base color is dark (mirror), emission carries the reflection + rim
    material.colorNode = color(0x111111);
    material.emissiveNode = reflectionColor.add(rimEffect);

    // 5. Geometry
    // We create jagged "Shard" geometries
    const shardGeo = new THREE.CylinderGeometry(0, 1, 3, 4, 1); // Pyramid/Diamond like
    shardGeo.translate(0, 0, 0);

    // Create Shards
    for (let i = 0; i < shardCount; i++) {
        const mesh = new THREE.Mesh(shardGeo, material);

        // Randomize shard shape/pos
        const s = scale * (0.5 + Math.random() * 0.5);
        mesh.scale.set(s, s * (1.5 + Math.random()), s * 0.2); // Flat shards

        // Position in cluster
        mesh.position.set(
            (Math.random() - 0.5) * scale,
            (Math.random() - 0.5) * scale,
            (Math.random() - 0.5) * scale
        );

        // Random rotation
        mesh.rotation.set(
            Math.random() * Math.PI,
            Math.random() * Math.PI,
            Math.random() * Math.PI
        );

        // Add animation data
        mesh.userData.rotSpeed = new THREE.Vector3(
            (Math.random() - 0.5) * 0.5,
            (Math.random() - 0.5) * 0.5,
            (Math.random() - 0.5) * 0.5
        );

        group.add(mesh);
    }

    // Make reactive
    // We attach reactivity so it can optionally change color or size,
    // though the material handles the main effect.
    attachReactivity(group, { type: 'sky', lightPreference: { min: 0.0, max: 1.0 } });

    // Custom update method for rotation
    group.userData.onUpdate = (delta: number, audioData: any) => {
        // Slowly rotate shards
        for (let i = 0; i < group.children.length; i++) {
            const child = group.children[i];
            child.rotation.x += child.userData.rotSpeed.x * delta;
            child.rotation.y += child.userData.rotSpeed.y * delta;
            child.rotation.z += child.userData.rotSpeed.z * delta;
        }

        // Bobbing
        group.position.y += Math.sin(uTime.value + group.id) * 0.005;
    };

    return group;
}

import * as THREE from 'three';
import type UniformNode from 'three/src/nodes/core/UniformNode.js';
import { color, vec3, sin, cos, uniform, mix, positionLocal, smoothstep, float } from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { VisualState } from '../audio/audio-system.ts';
import { BiomeUniforms } from '../systems/biome-uniforms.ts';
import { SkyUniforms, skyNoteColorNode } from '../systems/biome-uniforms.ts';
import { attachReactivity, CandyPresets, uAudioLow, uAudioHigh, uTime, createJuicyRimLight } from './index.ts';

// Moon Configuration
export const moonConfig = {
    blinkDuration: 0.2, // seconds
    danceAmplitude: 0.5,
    danceSpeed: 2.0
};

export function createMoon(): THREE.Group {
    const group = new THREE.Group();
    group.name = 'Moon';

    // 1. Moon Body (Sphere)
    const geo = new THREE.SphereGeometry(15, 32, 32);

    // TSL Material for Moon Surface + Blink
    const mat = new MeshStandardNodeMaterial({
        roughness: 0.8,
        metalness: 0.1
    });

    // Base Color (Pale Blue/White)
    const baseColor = color(0xDDEEFF);

    // Blink Effect (Emissive Pulse)
    const uBlink = uniform(0.0); // 0 to 1
    (mat as any).uBlink = uBlink; // Expose to JS

    // 🎨 PALETTE: Juicy Audio-Reactive Moon

    // 1. Bass Pulse (Low Frequency / Kick)
    // The moon gently breathes with the beat, intensifying on strong kicks
    const bassPulse = uAudioLow.mul(0.4);
    const breathing = sin(uTime.mul(2.0)).mul(0.1).add(0.9); // Idle breathing 0.8-1.0
    const activeGlow = breathing.add(bassPulse);

    // 2. Note-Color Reactivity (SkyMoon BiomeUniforms)
    // The moon smoothly shifts to the active note's color based on intensity
    const magicColor = BiomeUniforms.skyMoon.moonNoteColor;
    const melodyShift = BiomeUniforms.skyMoon.moonIntensity.mul(0.8); // 0-0.8 blend
    const audioColor = mix(baseColor, magicColor, melodyShift);

    mat.colorNode = audioColor;

    // 3. Emissive logic: Audio Glow + JS Blink + Rim Light
    // Blink adds a strong white flash on top of the audio glow
    const blinkGlow = color(0xFFFFFF).mul(uBlink.mul(2.0));
    const baseEmissive = audioColor.mul(activeGlow).mul(0.5); // Soft inner glow

    // 4. Juicy Rim Light for the edge pop
    // Modulate rim intensity by bass for a dynamic halo effect
    const rimIntensity = float(1.0).add(bassPulse.mul(2.0));
    const rimLight = createJuicyRimLight(audioColor, rimIntensity, float(3.0), null);

    // 5. Moon Dance: note-colour emissive glow (zero during day via SkyUniforms.intensity)
    const noteMoonEmissive = mix(color(0x000000), skyNoteColorNode, SkyUniforms.intensity);

    mat.emissiveNode = baseEmissive.add(blinkGlow).add(rimLight).add(noteMoonEmissive);

    const moonMesh = new THREE.Mesh(geo, mat);
    moonMesh.castShadow = true; // Moon casts shadow (simulated as directional light source usually, but mesh itself can too)
    group.add(moonMesh);

    // 2. Moon Face (Optional - purely decorative geometry)
    // Simple eyes and mouth for "Charming Moon"
    const faceGroup = new THREE.Group();
    faceGroup.position.z = 14.5; // Surface

    const eyeGeo = new THREE.SphereGeometry(1.5, 16, 16);
    const eyeMat = CandyPresets.Clay(0x111111, { roughness: 0.2 });

    const leftEye = new THREE.Mesh(eyeGeo, eyeMat);
    leftEye.position.set(-4, 3, 0);
    leftEye.scale.z = 0.5; // Flatten

    const rightEye = new THREE.Mesh(eyeGeo, eyeMat);
    rightEye.position.set(4, 3, 0);
    rightEye.scale.z = 0.5;

    // Blink Animation (Scale eyes)
    // We'll handle this in the animate function in main.js or helper here
    group.userData.eyes = [leftEye, rightEye];

    const mouthGeo = new THREE.TorusGeometry(3, 0.5, 8, 16, Math.PI);
    const mouthMat = CandyPresets.Clay(0x111111, { roughness: 0.5 });
    const mouth = new THREE.Mesh(mouthGeo, mouthMat);
    mouth.rotation.z = Math.PI;
    mouth.position.set(0, -2, 0);

    faceGroup.add(leftEye, rightEye, mouth);
    faceGroup.lookAt(0, 0, 100); // Face forward
    group.add(faceGroup);

    // Store state
    group.userData.isMoon = true;
    group.userData.originalPosition = new THREE.Vector3(); // Set when added
    group.userData.velocity = new THREE.Vector3();
    group.userData.blinkTimer = 0;

    // Tag as Sky object
    group.userData.type = 'moon'; // Used for color palette mapping
    group.userData.reactivityType = 'sky';

    return attachReactivity(group);
}

/**
 * Update Moon Animation
 * @param {THREE.Group} moon - Moon group
 * @param {number} delta - Time delta
 * @param {object} audioData - Audio state
 */
export function updateMoon(moon: THREE.Group, delta: number, audioData: VisualState): void {
    if (!moon || !moon.userData.isMoon) return;

    // 1. Dance (Bobbing to beat)
    const timeVal = performance.now() * 0.001;
    const beatPhase = audioData?.beatPhase || 0;
    const groove = audioData?.grooveAmount || 0;

    // Gentle bob always
    const bob = Math.sin(timeVal * moonConfig.danceSpeed) * moonConfig.danceAmplitude;

    // Beat bounce
    const beatBounce = Math.max(0, Math.sin(beatPhase * Math.PI * 2)) * groove * 2.0;

    // Apply to local Y (assuming moon is placed in a container or we modify local position relative to orbit)
    // Since moon moves across sky, we should apply this as a local offset if possible.
    // However, moon is likely child of scene.
    // We might need to handle this carefully if moon position is driven by Day/Night cycle.
    // Recommendation: Add moon mesh to a "MoonContainer" which handles orbit, and animate mesh local position.
    // For now, let's assume moon.children[0] (the mesh) can be animated locally.

    const mesh = moon.children[0] as THREE.Mesh;
    if (mesh) {
        mesh.position.y = bob + beatBounce;
        mesh.rotation.z = Math.sin(timeVal) * 0.05; // Gentle tilt
    }

    // 2. Blink Logic
    // Random blink or on beat
    if (moon.userData.blinkTimer > 0) {
        moon.userData.blinkTimer -= delta;
        // Update uniform
        if ((mesh.material as any).uBlink) {
             // 0..1..0 curve
             const t = 1.0 - (moon.userData.blinkTimer / moonConfig.blinkDuration);
             const val = Math.sin(t * Math.PI);
             (mesh.material as any).uBlink.value = val;
        }

        // Squash eyes
        const eyes = moon.userData.eyes as THREE.Object3D[];
        if (eyes) {
            for (let i = 0; i < eyes.length; i++) { eyes[i].scale.y = 0.1 + (1.0 - Math.sin(Math.PI * (1.0 - moon.userData.blinkTimer/moonConfig.blinkDuration))) * 0.9; }
        }
    } else {
        // Reset eyes
        const eyes = moon.userData.eyes as THREE.Object3D[];
        if (eyes) { for (let i = 0; i < eyes.length; i++) { eyes[i].scale.y = 1.0; } }

        if ((mesh.material as any).uBlink) (mesh.material as any).uBlink.value = 0;

        // Random chance to blink
        if (Math.random() < 0.005) {
            triggerMoonBlink(moon);
        }

        // React to channel trigger via system (flashIntensity set by attachReactivity)
        if (moon.userData.flashIntensity > 0.1) {
             triggerMoonBlink(moon);
             // Consume trigger
             moon.userData.flashIntensity = 0;
        }
    }
}

export function triggerMoonBlink(moon: THREE.Group): void {
    moon.userData.blinkTimer = moonConfig.blinkDuration;
}

