            }

            group.userData.harvested = true;
            group.userData.interactionText = "Harvested";
        }

        if (originalInteract) originalInteract();
    };

    return interactive;
}

// --- UTILITY ---

export function makeInteractive(group: THREE.Group): THREE.Group {
    // Simple wrapper to flag the group as interactive.
    // The actual raycasting often relies on child meshes (like hitMesh).
    group.userData.isInteractive = true;

    // Add default hover behavior if not present
    if (!group.userData.onGazeEnter) {
        group.userData.onGazeEnter = () => {
            // Default scale pop
            group.scale.multiplyScalar(1.1);
        };
    }
    if (!group.userData.onGazeLeave) {
        group.userData.onGazeLeave = () => {
            // Default scale return
            group.scale.multiplyScalar(1 / 1.1);
        };
    }

    return group;
}

// src/foliage/panning-pads.ts

import * as THREE from 'three';
import {
    color, float, mix, uv, distance, vec2, smoothstep, uniform,
    positionLocal, positionWorld, vec3,
    ShaderNodeObject, Node
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { getBiomeUniforms } from '../systems/biome-uniforms.ts';
import { spawnImpact } from './impacts.ts';
import {
    createUnifiedMaterial,
    CandyPresets,
    registerReactiveMaterial,
    attachReactivity,
    sharedGeometries,
    createStandardNodeMaterial,
    uPlayerPosition,
    uTime,

} from './index.ts';
import { $sn } from './material-core/tsl-types.ts';
import { UnifiedMaterialOptions } from './material-core.ts';

export interface PanningPadOptions {
    radius?: number;
    baseColor?: THREE.ColorRepresentation;
    glowColor?: THREE.ColorRepresentation;
    panBias?: number;
}

export function createPanningPad(options: PanningPadOptions = {}): THREE.Group {
    const {
        radius = 1.0,
        baseColor = 0x2E8B57,
        glowColor = 0x00FFFF
    } = options;

    const group = new THREE.Group();

    // --- TSL: Player Interaction (Squash) ---
    // Calculate distance in world space (XZ plane only for cylindrical interaction)
    // We use a safe Z-up/Y-up check assuming standard world coordinates
    const playerPosXZ = vec3(uPlayerPosition.x, float(0.0), uPlayerPosition.z);
    const myPosXZ = vec3(positionWorld.x, float(0.0), positionWorld.z);
    const distToPlayer = distance(myPosXZ, playerPosXZ);

    // Interaction Radius (1.5x pad radius)
    // When player is within this radius, squash begins
    const interactRadius = float(radius * 1.5);

    // Squash Factor: 0.0 (Far) -> 0.5 (Center)
    // smoothstep(max, min, val) returns 0 at max, 1 at min.
    const squashFactor = smoothstep(interactRadius, float(0.0), distToPlayer).mul(0.5);

    // Deform Y: Scale down to (1.0 - 0.5) = 0.5 at center
    // We start from 1.0 (unscaled)
    const scaleY = float(1.0).sub(squashFactor);

    // Bulge XZ: Preserve volume (Volume ~ r^2 * h)
    // new_r = old_r / sqrt(new_h)
    // We use scaleY.sqrt() as divisor. safe since min scaleY is 0.5
    const scaleXZ = float(1.0).div(scaleY.sqrt());

    // Apply deformation to local position
    // Note: This deforms the mesh geometry itself on the GPU
    const squashDeformation = positionLocal.mul(vec3(scaleXZ, scaleY, scaleXZ));

    // 1. The Pad (Flattened Cylinder)
    // We want a mercury/holographic look.
    // Use OilSlick preset but tweak for "mercury" (high metalness, high smoothness)
    const padMatOpts: UnifiedMaterialOptions = {
        roughness: 0.1,
        metalness: 0.9,
        iridescenceStrength: 0.8,
        iridescenceFresnelPower: 2.0,
        bumpStrength: 0.05,
        noiseScale: 4.0,
        sheen: 0.5,
        sheenColor: glowColor instanceof THREE.Color ? glowColor : new THREE.Color(glowColor),
        deformationNode: squashDeformation // ⚡ JUICE: Apply TSL Squash
    };

    const padMat = createUnifiedMaterial(0xCCCCCC, padMatOpts);
    registerReactiveMaterial(padMat);

    const pad = new THREE.Mesh(sharedGeometries.unitCylinder, padMat);
    pad.scale.set(radius, 0.1, radius);
    pad.position.y = 0; // Pivot at bottom
    pad.castShadow = true;
    pad.receiveShadow = true;
    group.add(pad);

    // 2. Radial Glow (Holographic Overlay)
    // Add a slightly larger disc on top with additive blending
    const glowMat = createStandardNodeMaterial({
        color: glowColor,
        roughness: 1.0,
        transparent: true,
        opacity: 0.6,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        side: THREE.DoubleSide
    });

    // TSL Shader logic for radial pulse
    const center = vec2(0.5, 0.5);
    const d = distance(uv(), center).mul(2.0); // 0 at center, 1 at edge
    const ring = smoothstep(0.8, 0.9, d).sub(smoothstep(0.9, 1.0, d)); // A ring at edge
    const core = float(1.0).sub(d); // Gradient from center

    const uGlowOpacity = uniform(0.6); // Default 0.6

    // ⚡ JUICE: Proximity Boost for Glow
    // Re-calculate distance in this material's context
    const glowPlayerDist = distance(vec3(positionWorld.x, float(0.0), positionWorld.z), playerPosXZ);
    const proximityBoost = smoothstep(interactRadius, float(0.0), glowPlayerDist).mul(0.5); // Add up to 0.5 opacity

    // Mix opacity + boost
    glowMat.opacityNode = core.mul(0.3).add(ring).mul(uGlowOpacity.add(proximityBoost));
    // Music Impact: arpeggio grove shimmer/noteColor drives pad glow intensity
    const groveUniforms = getBiomeUniforms('arpeggio_grove');
    const musicGlow = $sn(glowMat.opacityNode).mul(groveUniforms.noteColor).mul(groveUniforms.shimmer).mul(0.5);
    glowMat.emissiveNode = color(glowColor).mul(glowMat.opacityNode).add(musicGlow);

    const glowDisc = new THREE.Mesh(sharedGeometries.quad, glowMat);
    glowDisc.rotation.x = -Math.PI / 2;
    glowDisc.position.y = 0.11; // Just above pad
    glowDisc.scale.set(radius * 2.2, radius * 2.2, 1); // Plane is 1x1, so scale to diameter
    pad.add(glowDisc);

    // Store reference to glow mat for pulsing intensity (used in animateFoliage)
    group.userData.glowMaterial = glowMat;
    group.userData.glowUniform = uGlowOpacity;

    // 3. Configuration
    group.userData.type = 'panningPad';
    group.userData.animationType = 'panningBob';
    group.userData.animationOffset = Math.random() * 100;

    // Reactivity: Map to specific channels for stereo effect
    const panBias = options.panBias !== undefined ? options.panBias : (Math.random() > 0.5 ? -1 : 1);
    group.userData.panBias = panBias; // -1 Left, 1 Right

    // ⚡ JUICE: Interaction Callbacks (Logic Layer)
    // InteractionSystem will call these when player enters proximity or clicks
    group.userData.onProximityEnter = (distanceSq: number) => {
        // Trigger "Land" dust particles
        spawnImpact(group.position, 'land');
    };

    group.userData.onInteract = () => {
        // Trigger "Jump" burst particles (e.g. if player clicks/activates it)
        spawnImpact(group.position, 'jump');
    };

    // Attach standard reactivity (color shifts)
    attachReactivity(group, { minLight: 0.0, maxLight: 1.0 });

    return group;
}

/**
 * plant-pose-machine.ts
 *
 * Per-plant ADSR envelope state machine for day/night pose transitions.
 *
 * Design constraints:
 * - Zero per-frame heap allocations: all state kept in flat Float32Array buffers (SoA layout).
 * - Envelope drives a single float "pose value" per instance (0 = rest/night, 1 = peak/day-bloom).
 * - Day/night bias from the world clock shifts the baseline pose even when music is silent.
 * - Channel intensity from the music reactivity pipeline triggers attack/release.
 */

import * as THREE from 'three';
import { ActiveWave, computeWaveDistSq, getActiveWave } from '../systems/music-wave.ts';

export interface PlantPoseConfig {
    /** Rate at which envelopeLevel ramps toward 1.0 per second when channel is active. */
    attackRate: number;
    /** Rate at which envelopeLevel falls back toward 0.0 per second when channel is inactive. */
    releaseRate: number;
    /** Fraction of dayTarget held at peak envelope (0–1). */
    sustainLevel: number;
    /** Pose value representing full "day bloom" / active target. */
    dayTarget: number;
    /** Pose value representing "night rest" / quiet baseline. */
    nightTarget: number;
    /** Minimum channel intensity that triggers the attack phase. */
    triggerThreshold: number;
    /**
     * Audio channel index to read for intensity.
     * -1 means the batcher determines the source itself (e.g. arpeggio detection).
     */
    channelIndex?: number;
}

/**
 * ADSR-style pose envelope for one plant type.
 *
 * State is stored in three parallel Float32Arrays — one slot per instance.
 * The `update` method iterates all active slots in a single for-loop with no
 * object allocations, satisfying the zero-GC-per-frame requirement.
 */
export class PlantPoseMachine {
    /** Current smoothed pose output read by the batcher. */
    private readonly _currentPose: Float32Array;
    /** Computed target pose for this frame (baseline + envelope contribution). */
    private readonly _targetPose: Float32Array;
    /**
     * Envelope level per instance [0, 1]:
     * rises toward 1 at attackRate when channel is active,
     * falls toward 0 at releaseRate when channel is inactive.
     */
    private readonly _envelopeLevel: Float32Array;
    private readonly _scratchPos: THREE.Vector3 = new THREE.Vector3();

    readonly capacity: number;

    constructor(capacity: number) {
        this.capacity = capacity;
        this._currentPose = new Float32Array(capacity);
        this._targetPose = new Float32Array(capacity);
        this._envelopeLevel = new Float32Array(capacity);
    }

    /**
     * Advance all active instance envelopes by one frame.
     *
     * @param count          Number of active instances (≤ capacity).
     * @param delta          Frame delta in seconds.
     * @param channelIntensity  Normalised channel energy [0, 1] shared for this batcher.
     * @param dayNightBias   World-clock scalar: 0 = full night, 1 = full day.
     * @param config         Per-plant-type envelope constants.
     */
    update(
        count: number,
        delta: number,
        channelIntensity: number,
        dayNightBias: number,
        config: PlantPoseConfig,
        activeWave: ActiveWave | null = null,
        getPlantWorldPosition?: (index: number, out: THREE.Vector3) => void,
        cameraPosition?: THREE.Vector3
    ): void {
        const { attackRate, releaseRate, sustainLevel, dayTarget, nightTarget, triggerThreshold } = config;

        // Day/night baseline: the resting pose even when music is silent.
        const baseline = nightTarget + (dayTarget - nightTarget) * dayNightBias;

        // Peak pose when the envelope is fully engaged.
        const envelopePeak = dayTarget * sustainLevel;

        // Smooth-step factor for currentPose → targetPose lerp.
        // Clamp to [0,1] so large delta values don't overshoot.
        const lerpK = Math.min(1.0, attackRate * delta);

        for (let i = 0; i < count; i++) {
            let triggerValue = channelIntensity;

            if (activeWave && getPlantWorldPosition) {
                getPlantWorldPosition(i, this._scratchPos);
                const distSq = computeWaveDistSq(this._scratchPos, activeWave, cameraPosition);

                const speed = activeWave.speed || 25.0;
                const elapsedSec = Math.max(0, (performance.now() - activeWave.timestamp) / 1000);
                const currentRadius = elapsedSec * speed;
                const waveRadiusSq = currentRadius * currentRadius;

                if (distSq < waveRadiusSq && waveRadiusSq > 0) {
                    const progress = 1.0 - (distSq / waveRadiusSq); // inverted for "arrival" feel
                    triggerValue = Math.min(1.0, progress * 2.0); // quick ramp-up
                } else {
                    triggerValue = 0;
                }
            }

            // --- Envelope advance (attack / release) ---
            if (triggerValue > triggerThreshold) {
                this._envelopeLevel[i] += attackRate * delta;
                if (this._envelopeLevel[i] > 1.0) this._envelopeLevel[i] = 1.0;
            } else {
                this._envelopeLevel[i] -= releaseRate * delta;
                if (this._envelopeLevel[i] < 0.0) this._envelopeLevel[i] = 0.0;
            }

            // --- Target pose: baseline shifted by envelope contribution ---
            this._targetPose[i] = baseline + (envelopePeak - baseline) * this._envelopeLevel[i];

            // --- Smooth currentPose toward targetPose ---
            this._currentPose[i] += (this._targetPose[i] - this._currentPose[i]) * lerpK;
        }
    }

    /** Get the entire array of current poses (⚡ OPTIMIZATION) */
    get currentPoses(): Float32Array {
        return this._currentPose;
    }

    /** Read the current (smoothed) pose value for instance `index`. */
    getPose(index: number): number {
        return this._currentPose[index];
    }

    /** Hard-reset an instance slot (e.g. on unregister / re-register). */
    reset(index: number, value: number = 0): void {
        this._currentPose[index] = value;
        this._targetPose[index] = value;
        this._envelopeLevel[index] = 0;
    }
}

import * as THREE from 'three';
import {
    Fn,
    uniform,
    storage,
    instanceIndex,
    float,
    vec3,
    mix,
    sin,
    cos,
    normalize,
    color,
    mx_noise_float,
    vertexIndex,
    max,
    min,
    length,
    positionLocal,
    time,
    uv,
    distance,
    smoothstep,
    vec2,
} from 'three/tsl';
import { PointsNodeMaterial } from 'three/webgpu';
import { createStorageBufferAttribute } from '../utils/storage-buffer-attribute.ts';
import {
    uTime,
    uAudioLow,
    uAudioHigh,
    uWindSpeed,
    uWindDirection,
    uPlayerPosition,
} from './index.ts';

export function createNeonPollen(count = 2000, areaSize = 30, center = new THREE.Vector3(0, 5, 0)) {
    // 1. Setup Buffers
    const positionBuffer = createStorageBufferAttribute(count, 3);
    const velocityBuffer = createStorageBufferAttribute(count, 3);
    const lifeBuffer = createStorageBufferAttribute(count, 1);

    // Initialize with random data
    for (let i = 0; i < count; i++) {
        // Random position within area (Sphere-ish distribution)
        const r = Math.cbrt(Math.random()) * areaSize; // Cube root for uniform spherical volume
        const theta = Math.random() * Math.PI * 2;
        const phi = Math.acos(2 * Math.random() - 1);

        const x = center.x + r * Math.sin(phi) * Math.cos(theta);
        const y = center.y + r * Math.sin(phi) * Math.sin(theta);
        const z = center.z + r * Math.cos(phi);

        positionBuffer.setXYZ(i, x, y, z);

        // Random small velocity
        velocityBuffer.setXYZ(
            i,
            (Math.random() - 0.5) * 0.05,
            (Math.random() - 0.5) * 0.05,
            (Math.random() - 0.5) * 0.05
        );

        // Life offset / Random seed
        lifeBuffer.setX(i, Math.random() * 100.0);
    }

    // 2. Create Compute Logic
    const positionStorage = storage(positionBuffer, 'vec3', count);
    const velocityStorage = storage(velocityBuffer, 'vec3', count);
    const lifeStorage = storage(lifeBuffer, 'float', count);

    const computePollen = (Fn as any)((): void => {
        const p = positionStorage.element(instanceIndex);
        const v = velocityStorage.element(instanceIndex);

        // --- Forces ---

        // 1. Wind Drift
        // Apply wind force scaled by wind speed
        const windForce = uWindDirection.mul(uWindSpeed).mul(0.05);

        // 2. Curl Noise (Wander)
        const noiseScale = float(0.2);
        const timeScale = uTime.mul(0.3);
        const noiseInput = p.mul(noiseScale).add(timeScale);

        const noiseX = mx_noise_float(noiseInput);
        const noiseY = mx_noise_float(noiseInput.add(vec3(31.41)));
        const noiseZ = mx_noise_float(noiseInput.add(vec3(42.5)));

        const wanderForce = vec3(noiseX, noiseY, noiseZ).mul(0.5);

        // 3. Audio Turbulence (Juice)
        // Bass kick creates a burst outward from center?
        // Or just general chaotic jitter.
        const audioJitter = normalize(v).mul(uAudioLow).mul(2.0);

        // 4. Center Attraction (Soft Constraint)
        const centerVec = vec3(center.x, center.y, center.z);
        const toCenter = centerVec.sub(p);
        const dist = length(toCenter);
        // If outside area, pull back gently
        const areaRadius = float(areaSize);
        const pullStrength = max(float(0.0), dist.sub(areaRadius)).mul(0.1);
        const centerForce = normalize(toCenter).mul(pullStrength);

        // --- PALETTE UPDATE: Player Repulsion (Interaction) ---
        // Push pollen away if player is close
        const toPlayer = p.sub(uPlayerPosition);
        const distToPlayer = length(toPlayer);
        // Repel Radius = 5.0
        const repelRadius = float(5.0);
        const repelFactor = max(float(0.0), repelRadius.sub(distToPlayer));
        // Force increases as distance decreases (Linear falloff)
        const repelForce = normalize(toPlayer).mul(repelFactor).mul(2.0);

        // Integration
        const dt = float(0.016);
        const acceleration = windForce
            .add(wanderForce)
            .add(audioJitter)
            .add(centerForce)
            .add(repelForce);

        const newVel = v.add(acceleration.mul(dt));

        // Damping
        const dampedVel = newVel.mul(0.98);

        // Apply
        v.assign(dampedVel);
        p.assign(p.add(dampedVel.mul(dt)));

        // Floor constraint
        // Keep above water level ~1.8
        p.y.assign(max(p.y, float(1.8)));
    });

    const computeNode = (computePollen() as unknown as { compute: (n: number) => unknown }).compute(count);

    // 3. Visualization Material
    const material = new PointsNodeMaterial({
        size: 0.1, // Will be overridden by sizeNode
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
    });

    const particlePos = positionStorage.element(vertexIndex);
    const particleSeed = lifeStorage.element(vertexIndex);

    material.positionNode = particlePos;

    // --- PALETTE UPDATE: Soft Circular Particle Shape ---
    // Use uv() which maps 0..1 across the point sprite
    const distFromCenter = distance(uv(), vec2(0.5));
    // Smooth circle: 0.5 (edge) -> 0.0 (center)
    // Alpha falls off: 1.0 at center, 0.0 at edge
    const alpha = smoothstep(0.5, 0.2, distFromCenter);

    // Discard pixels outside circle for performance (reduce overdraw?)
    // Or just let alpha handle it. Discard is good for depth buffer but here we are transparent/no-depth-write.
    // Let's just use alpha.

    // --- PALETTE UPDATE: Twinkle & Sparkle ---
    // Random offset based on particleSeed
    const twinkleSpeed = float(5.0);
    const twinkle = sin(uTime.mul(twinkleSpeed).add(particleSeed)).mul(0.5).add(0.5); // 0..1

    // Audio Boost (Highs = Sparkle)
    // When melody plays, sparkles flare up
    const audioBoost = uAudioHigh.mul(3.0);
    const brightness = float(1.0).add(twinkle).add(audioBoost);

    // Color Logic (Neon Gradient)
    // Mix Cyan (0x00FFFF) and Magenta (0xFF00FF) based on position
    const hueMix = sin(particlePos.x.mul(0.1).add(particlePos.z.mul(0.1)).add(uTime))
        .mul(0.5)
        .add(0.5);
    const cyan = color(0x00ffff);
    const magenta = color(0xff00ff);
    const baseColor = mix(cyan, magenta, hueMix);

    // Hot Core (White center)
    // Mix White at center (dist < 0.2)
    const coreMix = smoothstep(0.3, 0.0, distFromCenter);
    const finalColor = mix(baseColor, color(0xffffff), coreMix.mul(0.5)); // 50% white core

    material.colorNode = finalColor.mul(brightness);
    material.opacityNode = alpha; // Apply circular mask

    // Size modulation
    // Base size + audio boost
    // Make them slightly larger so the soft edge is visible
    (material as { sizeNode?: unknown }).sizeNode = float(0.15).add(uAudioHigh.mul(0.1));

    // 4. Mesh
    function ensureUVAttribute(geometry: THREE.BufferGeometry) {
        if (!geometry.attributes.uv && geometry.attributes.position) {
            const count = geometry.attributes.position.count;
            const uvs = new Float32Array(count * 2);
            geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
        }
    }

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', positionBuffer);
    ensureUVAttribute(geometry);
    geometry.drawRange.count = count;

    const pollen = new THREE.Points(geometry, material);
    pollen.frustumCulled = false;
    pollen.userData.computeNode = computeNode;
    pollen.userData.isPollen = true;
    pollen.userData.type = 'neonPollen';

    return pollen;
}

import * as THREE from 'three';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import {
  vec3,
  positionLocal,
  attribute,
  uv,
  mix,
  color,
  float,
  sin,
  instanceIndex
} from 'three/tsl';
import { camera } from '../core/camera-ref.ts';
import { CONFIG } from '../core/config.ts';
import { BiomeUniforms, circadianDayGlowMult, circadianNightGlowMult } from '../systems/biome-uniforms.ts';
import { getActiveWave } from '../systems/music-wave.ts';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
import { writeInstancePose } from '../utils/wasm-batcher-instance.ts';
import { getGroundAlignedQuaternion } from '../world/placement-utils.ts';
import { foliageGroup } from '../world/state.ts';
import { applyInstanceAnimation, ANIMATION_TYPES } from './animation-nodes.ts';
import {
  createUnifiedMaterial,
  registerReactiveMaterial,
  applyStandardDeformation,
  createJuicyRimLight,
  uAudioHigh,
  uAudioLow,
  uTime
} from './index.ts';
import { PlantPoseMachine } from './plant-pose-machine.ts';
import { uTwilight } from './sky.ts';


const MAX_PINES = 200; // conservative default for performance
/** Default melody channel index used when config does not specify channelIndex. */
const DEFAULT_MELODY_CHANNEL_INDEX = 2;
const _scratchMatrix = new THREE.Matrix4();
const _scratchQuaternion = new THREE.Quaternion();

export class PortamentoPineBatcher {
  initialized = false;
  count = 0;
  logicPines: Array<THREE.Object3D> = [];

  // Instanced meshes
  trunkMesh: THREE.InstancedMesh | null = null;
  needleMesh: THREE.InstancedMesh | null = null;
  bendAttribute: THREE.InstancedBufferAttribute | null = null;

  // scratch
  _color = new THREE.Color();

  /**
   * Per-instance ADSR pose machine — drives the spring rest position for each pine.
   * Allocated once with MAX_PINES capacity; no per-frame allocations.
   */
  private _poseMachine!: PlantPoseMachine;

  // scratch / batch pose buffers
  private _batchPositions = new Float32Array(MAX_PINES * 3);
  private _batchQuaternions = new Float32Array(MAX_PINES * 4);
  private _batchScales = new Float32Array(MAX_PINES * 3);
  private _matricesDirty = false;

  private flushMatrices() {
    if (!this._matricesDirty || this.count === 0 || !this.trunkMesh || !this.needleMesh) return;

    const trunkArray = this.trunkMesh.instanceMatrix.array as Float32Array;
    const needleArray = this.needleMesh.instanceMatrix.array as Float32Array;

    writeInstancePose(
      this._batchPositions,
      this._batchQuaternions,
      this._batchScales,
      null,
      trunkArray,
      null,
      1.0,
      this.count
    );
    writeInstancePose(
      this._batchPositions,
      this._batchQuaternions,
      this._batchScales,
      null,
      needleArray,
      null,
      1.0,
      this.count
    );

    this.trunkMesh.instanceMatrix.needsUpdate = true;
    this.needleMesh.instanceMatrix.needsUpdate = true;
    this._matricesDirty = false;
  }

  init() {
    if (this.initialized) return;
    this._poseMachine = new PlantPoseMachine(MAX_PINES);

    // Geometry: merged trunk + needles (pr-281 approach)
    const height = 4.0;
    const segments = 6;
    const segHeight = height / segments;

    const trunkGeometries: THREE.BufferGeometry[] = [];
    const needleGeometries: THREE.BufferGeometry[] = [];

    for (let i = 0; i < segments; i++) {
      const yBase = i * segHeight;
      const rBot = 0.4 * (1 - i / segments) + 0.1;
      const rTop = 0.4 * (1 - (i + 1) / segments) + 0.1;

      const tGeo = new THREE.CylinderGeometry(rTop, rBot, segHeight, 8);
      tGeo.translate(0, yBase + segHeight / 2, 0);
      trunkGeometries.push(tGeo);

      if (i > 1) {
        const needleCount = 8;
        for (let n = 0; n < needleCount; n++) {
          const nGeo = new THREE.ConeGeometry(0.1, 0.6, 4);
          nGeo.rotateZ(1.5);
          nGeo.rotateY((n / needleCount) * Math.PI * 2);
          const px = Math.cos((n / needleCount) * Math.PI * 2) * rBot;
          const pz = Math.sin((n / needleCount) * Math.PI * 2) * rBot;
          nGeo.translate(px, segHeight * 0.5, pz);
          nGeo.translate(0, yBase, 0);
          needleGeometries.push(nGeo);
        }
      }
    }

    const trunkGeo = mergeGeometries(trunkGeometries) as THREE.BufferGeometry;
    const needleGeo = mergeGeometries(needleGeometries) as THREE.BufferGeometry;
    if (!trunkGeo || !needleGeo) {
      console.error('[PortamentoPineBatcher] Geometry merge failed');
      return;
    }

    // --- TSL ANIMATION LOGIC ---
    // Combined deformation: Note Bend + Wind Sway + Player Push
    const animatedPosition = (basePos: any) => {
        // 1. Instance Bend (Note Play)
        const instanceBend = attribute('instanceBend', 'float');
        // Quadratic bend: more at top
        const bendDisplace = vec3(instanceBend.mul(basePos.y.pow(2.0)), float(0.0), float(0.0));

        return applyStandardDeformation(basePos.add(bendDisplace));
    };

    const animPos = animatedPosition(positionLocal);

    // --- MATERIALS ---

    // 1. Trunk: Magic Copper with Patina
    const trunkMat = createUnifiedMaterial(0xB87333, {
        metalness: 0.8,
        roughness: 0.4,
        bumpStrength: 0.2, // Oxidation texture
        noiseScale: 4.0,
        triplanar: true,
        iridescenceStrength: 0.3, // Oil slick look
        colorNode: mix(color(0xB87333), color(0x2E8B57), positionLocal.y.mul(0.25).min(1.0)), // Green at bottom
        deformationNode: animPos
    });

    // 2. Needles: Glowing Emerald Glass
    const needleMat = createUnifiedMaterial(0x2E8B57, {
        transmission: 0.4,
        roughness: 0.2,
        sheen: 1.0,
        sheenColor: 0x00FF00,
        audioReactStrength: 1.0, // Pulse with music
        deformationNode: animPos
    });

    // 🎨 Palette: TSL Audio-Reactive Juice & Neon Rim Light
    const baseGlowColor = color(0x00FF00);
    const audioGlow = uAudioHigh.mul(1.5).add(uAudioLow.mul(0.5));
    const rimLight = createJuicyRimLight(baseGlowColor, float(1.5), float(3.0), null);

    // 🎨 PALETTE: Twilight Glow for portamento pines
    const glowPhaseOffset = float(instanceIndex).mul(0.1);
    const idlePulse = sin(uTime.mul(float(CONFIG.glow.glowPulseFrequency)).add(glowPhaseOffset)).mul(float(CONFIG.glow.glowPulseAmplitude)).add(1.0).mul(float(0.5)).mul(uAudioHigh.mul(0.3).add(0.7));
    const targetGlowColor = color(CONFIG.glow.glowColorMap['portamento']);

    // Music Impact / Twilight fix: uTwilight is now explicitly multiplied into the glow tint
    // (matching the exact pattern from simple-flower-batcher.ts:161).
    // Previously this was a stub (imported but not wired into the final emissive graph in some paths).
    const twilightGlowTint = targetGlowColor
        .mul(uTwilight)
        .mul(float(CONFIG.glow.glowIntensityMax))
        .mul(float(0.3).add(idlePulse));

    needleMat.emissiveNode = baseGlowColor
        .mul(BiomeUniforms.arpeggioGrove.noteColor)
        .mul(audioGlow)
        .mul(circadianDayGlowMult(0.3))
        .add(rimLight.mul(circadianDayGlowMult(0.3)))
        .add(twilightGlowTint.mul(circadianNightGlowMult()));
    registerReactiveMaterial(needleMat);

    this.bendAttribute = new THREE.InstancedBufferAttribute(new Float32Array(MAX_PINES), 1);
    trunkGeo.setAttribute('instanceAnimType', new THREE.InstancedBufferAttribute(new Float32Array(MAX_PINES), 1));
    trunkGeo.setAttribute('instanceAnimOffset', new THREE.InstancedBufferAttribute(new Float32Array(MAX_PINES), 1));
    needleGeo.setAttribute('instanceAnimType', new THREE.InstancedBufferAttribute(new Float32Array(MAX_PINES), 1));
    needleGeo.setAttribute('instanceAnimOffset', new THREE.InstancedBufferAttribute(new Float32Array(MAX_PINES), 1));
    trunkGeo.setAttribute('instanceBend', this.bendAttribute);
    needleGeo.setAttribute('instanceBend', this.bendAttribute);

    this.trunkMesh = new THREE.InstancedMesh(trunkGeo, trunkMat, MAX_PINES);
    this.needleMesh = new THREE.InstancedMesh(needleGeo, needleMat, MAX_PINES);
    this.trunkMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.needleMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.trunkMesh.castShadow = this.needleMesh.castShadow = true;
    this.trunkMesh.receiveShadow = this.needleMesh.receiveShadow = true;

    foliageGroup.add(this.trunkMesh);
    foliageGroup.add(this.needleMesh);

    this.initialized = true;
    console.log('[PortamentoPineBatcher] Initialized (Magic Copper Edition)');
  }

  register(dummy: THREE.Object3D, options = {}) {
    if (!this.initialized) this.init();
    if (this.count >= MAX_PINES) {
      console.warn('[PortamentoBatcher] Max limit reached');
      return;
    }

    // Safety: Ensure physics state exists if not initialized by logic object factory
    if (!dummy.userData.reactivityState) {
        dummy.userData.reactivityState = { currentBend: 0, velocity: 0 };
    }

    const i = this.count++;
    dummy.userData.batchIndex = i;
    dummy.userData.bendFactor = 0;
    this.logicPines[i] = dummy;

    getGroundAlignedQuaternion(dummy, _scratchQuaternion);
    this._batchPositions[i * 3 + 0] = dummy.position.x;
    this._batchPositions[i * 3 + 1] = dummy.position.y;
    this._batchPositions[i * 3 + 2] = dummy.position.z;

    this._batchQuaternions[i * 4 + 0] = _scratchQuaternion.x;
    this._batchQuaternions[i * 4 + 1] = _scratchQuaternion.y;
    this._batchQuaternions[i * 4 + 2] = _scratchQuaternion.z;
    this._batchQuaternions[i * 4 + 3] = _scratchQuaternion.w;

    this._batchScales[i * 3 + 0] = dummy.scale.x;
    this._batchScales[i * 3 + 1] = dummy.scale.y;
    this._batchScales[i * 3 + 2] = dummy.scale.z;

    this._matricesDirty = true;
    this.flushMatrices();

    this.bendAttribute!.setX(i, 0);



    this.trunkMesh!.count = this.count;
    this.needleMesh!.count = this.count;

    return i;
  }

  updateInstance(idx: number, dummy: THREE.Object3D) {
    if (!this.initialized) return;

    getGroundAlignedQuaternion(dummy, _scratchQuaternion);
    this._batchPositions[idx * 3 + 0] = dummy.position.x;
    this._batchPositions[idx * 3 + 1] = dummy.position.y;
    this._batchPositions[idx * 3 + 2] = dummy.position.z;

    this._batchQuaternions[idx * 4 + 0] = _scratchQuaternion.x;
    this._batchQuaternions[idx * 4 + 1] = _scratchQuaternion.y;
    this._batchQuaternions[idx * 4 + 2] = _scratchQuaternion.z;
    this._batchQuaternions[idx * 4 + 3] = _scratchQuaternion.w;

    this._batchScales[idx * 3 + 0] = dummy.scale.x;
    this._batchScales[idx * 3 + 1] = dummy.scale.y;
    this._batchScales[idx * 3 + 2] = dummy.scale.z;

    this._matricesDirty = true;
    this.flushMatrices();
  }

  setBendForIndex(idx: number, value: number) {
    // Legacy support for musical_flora.js:
    // This function is called with 'velocity' by the logic object logic.
    // However, the logic object updates its own shared state (dummy.userData.reactivityState).
    // The physics loop in update() below reads that state directly.
    // So we don't need to manually update the attribute here; the loop handles it
    // including the spring physics integration.
  }

  update(time: number, audioState: any, dayNightBias: number = 1.0) {
    if (!this.initialized || this.count === 0) return;

    let needsUpdate = false;
    const dt = 0.016; // Fixed physics step

    // --- Pose machine: advance per-instance ADSR envelopes ---
    // Use melody channel (index from config) volume as shared channel intensity.
    const poseConfig = CONFIG.plantPose.portamentoPine;
    const channelIdx = poseConfig.channelIndex ?? DEFAULT_MELODY_CHANNEL_INDEX;
    let channelIntensity = 0.0;
    if (audioState && audioState.channelData && audioState.channelData[channelIdx]) {
        channelIntensity = audioState.channelData[channelIdx].volume || 0;
    }
    const activeWave = getActiveWave();
    const cameraPos = camera ? camera.position : undefined;

    const getPlantPos = (index: number, out: THREE.Vector3) => {
        if (!this.trunkMesh) return;
        const array = this.trunkMesh.instanceMatrix.array as Float32Array;
        const offset = index * 16;
        out.set(array[offset + 12], array[offset + 13], array[offset + 14]);
    };

    this._poseMachine.update(this.count, dt, channelIntensity, dayNightBias, poseConfig, activeWave, getPlantPos, cameraPos);

    for (let i = 0; i < this.count; i++) {
        const pine = this.logicPines[i];
        if (!pine || !pine.userData.reactivityState) continue;

        const state = pine.userData.reactivityState; // { currentBend, velocity }

        // --- Spring rest position driven by ADSR pose ---
        // At day with no music: pose ≈ 0   (straight)
        // At night:             pose ≈ -0.05 (gentle droop)
        // Music active:         pose ramps toward dayTarget * sustainLevel (visible forward lean)
        const poseTarget = this._poseMachine.getPose(i);

        // Spring Physics (Hooke's Law + Damping) toward ADSR target
        const k = 10.0;     // Stiffness
        const damp = 0.92;  // Friction

        const force = -k * (state.currentBend - poseTarget);
        state.velocity += force * dt;
        state.velocity *= damp;
        state.currentBend += state.velocity * dt;

        // If significant change, update attribute
        const last = pine.userData._lastUploadedBend || 0;
        if (Math.abs(state.currentBend - last) > 0.001) {
             // ⚡ OPTIMIZATION: Bypassed THREE.BufferAttribute.setX overhead by writing directly to typed array
             this.bendAttribute!.array[i] = state.currentBend;
             pine.userData._lastUploadedBend = state.currentBend;
             needsUpdate = true;
        }
    }

    if (needsUpdate) {
        this.bendAttribute!.needsUpdate = true;
    }
  }

  dispose(): void {
    if (this.trunkMesh && this.trunkMesh.parent) {
      safeRemoveAndDispose(this.trunkMesh.parent, this.trunkMesh);
    }
    if (this.needleMesh && this.needleMesh.parent) {
      safeRemoveAndDispose(this.needleMesh.parent, this.needleMesh);
    }
  }
}

export const portamentoPineBatcher = new PortamentoPineBatcher();

import * as THREE from 'three';
import { BokehPass } from 'three/examples/jsm/postprocessing/BokehPass.js';
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
import { bloom } from 'three/examples/jsm/tsl/display/BloomNode.js';
import { dof } from 'three/examples/jsm/tsl/display/DepthOfFieldNode.js';
import { pass, mix, vec3, uniform, Fn, float, uv, vec2, distance, smoothstep } from 'three/tsl';
import { PostProcessing } from 'three/webgpu';
import { CONFIG, isDofEnabled } from '../core/config.ts';
import type { CandyRenderer } from '../core/init.ts';
import { isWebGPUMode } from '../core/init.ts';

// Global uniforms for reactivity
export const uBloomStrength = uniform(1.0);
export const uColorSaturation = uniform(1.1); // Slightly boosted by default
export const uColorContrast = uniform(1.05);
export const uVignetteStrength = uniform(0.5);
export const uAberrationStrength = uniform(0.002); // Very subtle by default (harsh RGB split removed in favor of prettier candy glow)

// Depth-of-Field controls (read by both pipelines; driven per-frame from game-loop.ts).
//   uDofFocus — focal-plane distance in world units (follows the camera look vector)
//   uDofMix   — 0 = fully sharp, 1 = full bokeh. Lets us fade DoF in near flora and
//               snap back to a sharp world instantly without recompiling shaders.
export const uDofFocus = uniform(CONFIG.postfx.dofFocusDistance);
export const uDofMix = uniform(0.0);
/** 0–1 bloom swell driven by visible god-ray opacity (screen-space scatter companion). */
export const uShaftScatterBoost = uniform(0.0);

/**
 * Initializes the Post-Processing pipeline for Candy World.
 * Automatically selects WebGPU TSL pipeline or WebGL EffectComposer based on renderer.
 * 
 * Features:
 * - Base Scene Render
 * - Bloom (Audio-reactive via uBloomStrength)
 * - Color Correction (Saturation & Contrast)
 *
 * @param renderer The renderer (WebGPU or WebGL)
 * @param scene The main scene
 * @param camera The main camera
 * @param mode The renderer mode ('webgpu' or 'webgl')
 * @returns An object to manage and render the post-processing pipeline
 */
export function initPostProcessing(renderer: CandyRenderer, scene: THREE.Scene, camera: THREE.Camera, mode: 'webgpu' | 'webgl') {
    if (isWebGPUMode(renderer)) {
        return initWebGPUPostProcessing(renderer, scene, camera);
    }
    return initWebGLPostProcessing(renderer, scene, camera);
}

/**
 * WebGPU-specific post-processing pipeline using TSL
 */
function initWebGPUPostProcessing(renderer: CandyRenderer, scene: THREE.Scene, camera: THREE.Camera) {
    if (!isWebGPUMode(renderer)) {
        throw new Error('Expected WebGPU renderer for WebGPU post-processing');
    }

    // 1. Initialize PostProcessing
    const postProcessing = new PostProcessing(renderer);

    // 2. Base Pass
    const scenePass = pass(scene, camera);

    // 3. Bloom Pass
    // threshold: 0.85 - only bright spots (neon/emissive) bloom
    // radius: 0.5 - smooth, wide spread for "Cute Clay" soft glow
    const threshold = uniform(0.85);
    const radius = uniform(0.5);

    const bloomPass = bloom(
        scenePass,
        uBloomStrength as unknown as number,
        radius as unknown as number,
        threshold as unknown as number,
    );

    // 3b. Depth of Field (bokeh) — only built into the graph when enabled at boot,
    // so the default `low` tier carries zero DoF cost. When present it is blended by
    // uDofMix, giving instant sharp↔blur transitions without a shader recompile.
    const dofActive = isDofEnabled();
    let dofColorNode: any = null;
    if (dofActive) {
        // viewZ drives the circle-of-confusion; aperture/maxblur kept subtle (candy bokeh).
        const viewZ = scenePass.getViewZNode();
        dofColorNode = dof(
            scenePass,
            viewZ,
            uDofFocus,
            uniform(CONFIG.postfx.dofAperture),
            uniform(CONFIG.postfx.dofMaxBlur)
        );
        console.log('[PostFX] Depth of Field enabled (WebGPU TSL bokeh)');
    }

    // 4. Color Correction Logic
    const colorCorrection = Fn(() => {
        // Very subtle, soft chromatic aberration (mostly disabled by default for candy aesthetic)
        // The old hard RGB split has been replaced by the much prettier "Candy Glow Pulse" in chromatic.ts
        const caOffset = uAberrationStrength.mul(0.3); // even softer than before
        const uvNode = uv();
        const uvR = uvNode.add(vec2(caOffset, 0.0));
        const uvG = uvNode;
        const uvB = uvNode.sub(vec2(caOffset, 0.0));

        const sceneTex = scenePass.getTextureNode() as unknown as { uv: (coords: ReturnType<typeof vec2>) => ReturnType<typeof vec3> };
        const r = sceneTex.uv(uvR).r;
        const g = sceneTex.uv(uvG).g;
        const b = sceneTex.uv(uvB).b;

        let caColor = vec3(r, g, b);

        // Blend in the bokeh result when DoF is built into the graph. uDofMix=0 keeps
        // the sharp (chromatic-aberrated) scene; uDofMix=1 is full DoF.
        if (dofColorNode) {
            caColor = mix(caColor, dofColorNode.rgb, uDofMix);
        }

        // Base color + Bloom (shaft scatter boost swells bloom when god rays are visible)
        const scatterMul = float(1.0).add(uShaftScatterBoost);
        const color = caColor.add(bloomPass.mul(scatterMul));

        // Saturation
        // Simple luminance dot product
        const luminanceWeight = vec3(0.299, 0.587, 0.114);
        const lum = color.xyz.dot(luminanceWeight);
        const grayscale = vec3(lum);

        // mix(grayscale, original, saturation)
        let satColor = mix(grayscale, color.xyz, uColorSaturation);

        // Contrast
        // smoothstep-like contrast adjustment or simple centering
        const midPoint = vec3(0.5);
        satColor = satColor.sub(midPoint).mul(uColorContrast).add(midPoint) as unknown as ReturnType<typeof mix>;

        // Vignette
        const dist = distance(uvNode, vec2(0.5, 0.5));
        const vig = float(1.0).sub(smoothstep(0.2, 1.0, dist));
        const vignetteMultiplier = mix(float(1.0), vig, uVignetteStrength);
        satColor = satColor.mul(vignetteMultiplier) as unknown as ReturnType<typeof mix>;

        return satColor;
    });

    // 5. Set Final Output Node
    postProcessing.outputNode = colorCorrection();

    const syncSize = () => {
        const width = window.innerWidth;
        const height = window.innerHeight;
        renderer.setSize(width, height);
        postProcessing.needsUpdate = true;
    };

    // Resize handler — PostProcessing does not auto-resize PassNode/Bloom internals.
    window.addEventListener('resize', syncSize);

    return {
        render: () => {
            // Note: renderer.render() should NOT be called before this if we want post processing to handle the main pass
            postProcessing.render();
        },
        syncSize,
        // Expose uniforms for manual tweaking if needed
        uniforms: {
            bloomStrength: uBloomStrength,
            saturation: uColorSaturation,
            contrast: uColorContrast,
            vignetteStrength: uVignetteStrength,
            aberrationStrength: uAberrationStrength
        }
    };
}

/**
 * WebGL-specific post-processing pipeline using EffectComposer
 */
function initWebGLPostProcessing(renderer: CandyRenderer, scene: THREE.Scene, camera: THREE.Camera) {
    if (isWebGPUMode(renderer)) {
        throw new Error('Expected WebGL renderer for WebGL post-processing, got WebGPU');
    }
    const webglRenderer = renderer as THREE.WebGLRenderer;

    // 1. Initialize EffectComposer
    const composer = new EffectComposer(webglRenderer);

    // 2. Add Render Pass (base scene rendering)
    const renderPass = new RenderPass(scene, camera);
    composer.addPass(renderPass);

    // 2b. Depth of Field (WebGL fallback) — degraded but functional bokeh.
    // Only added when DoF is enabled at boot. Toggled per-frame via pass.enabled
    // (uDofMix), so disabling returns to a sharp world instantly.
    let bokehPass: BokehPass | null = null;
    if (isDofEnabled()) {
        bokehPass = new BokehPass(scene, camera, {
            focus: CONFIG.postfx.dofFocusDistance,
            aperture: CONFIG.postfx.dofAperture,
            maxblur: CONFIG.postfx.dofMaxBlur,
        });
        bokehPass.enabled = false; // off until uDofMix rises
        composer.addPass(bokehPass);
        console.log('[PostFX] Depth of Field enabled (WebGL BokehPass)');
    }

    // 3. Add Bloom Pass
    // UnrealBloomPass parameters: (resolution, strength, radius, threshold)
    const resolution = new THREE.Vector2(window.innerWidth, window.innerHeight);
    const bloomPass = new UnrealBloomPass(
        resolution,
        1.0,    // strength (maps to uBloomStrength)
        0.5,    // radius (soft glow spread)
        0.85    // threshold (only bright spots bloom)
    );
    composer.addPass(bloomPass);

    // Resize handler
    const handleResize = () => {
        const width = window.innerWidth;
        const height = window.innerHeight;
        composer.setSize(width, height);
    };
    window.addEventListener('resize', handleResize);

    // Return interface compatible with WebGPU version
    return {
        render: () => {
            // Sync bloom strength: This per-frame read is necessary for audio reactivity.
            // Performance note: Uniforms are reactive in WebGPU mode (TSL), but WebGL requires
            // manual synchronization on every frame. This is an acceptable trade-off for fallback support.
            const scatter = uShaftScatterBoost.value || 0;
            bloomPass.strength = (uBloomStrength.value || 1.0) * (1.0 + scatter);
            // Sync DoF: enable only while mixed in, and track the focal plane.
            if (bokehPass) {
                bokehPass.enabled = uDofMix.value > 0.01;
                (bokehPass.uniforms as any)['focus'].value = uDofFocus.value;
            }
            composer.render();
        },
        syncSize: handleResize,
        // Expose uniforms for compatibility
        uniforms: {
            bloomStrength: uBloomStrength,  // Same uniform as WebGPU; manual sync required
            saturation: uColorSaturation,
            contrast: uColorContrast,
            vignetteStrength: uVignetteStrength,
            aberrationStrength: uAberrationStrength
        },
        // Expose bloom pass for manual control and synchronization
        bloomPass: bloomPass
    };
}

import * as THREE from 'three';
import { CloudBatcher } from './cloud-batcher.ts';
import { createCloud } from './clouds.ts';

/**
 * Generates a procedural cloud layer for the background sky.
 * These clouds are non-interactive and purely visual, handled by the batcher.
 *
 * @param scene The THREE.Scene to add the cloud logic objects to (optional, for hierarchy)
 * @returns Array of generated cloud objects
 */
export function generateCloudLayer(scene: THREE.Scene): THREE.Object3D[] {
    const generatedClouds: THREE.Object3D[] = [];
    // Increase count for a dense layer
    const CLOUD_COUNT = 150;
    const RADIUS = 800;
    const MIN_HEIGHT = 100;
    const HEIGHT_RANGE = 60;

    console.log("[Procedural Sky] Generating cloud layer...");

    // Noise helper (simple sine/cos combination for clustering)
    function getNoise(x: number, z: number): number {
        const scale1 = 0.003;
        const scale2 = 0.01;
        const val = Math.sin(x * scale1) * Math.cos(z * scale1) * 0.7 +
                    Math.sin(x * scale2 + 2.0) * Math.cos(z * scale2 + 1.5) * 0.3;
        return (val + 1.0) * 0.5; // 0.0 to 1.0
    }

    // Drift Logic for background clouds
    // We can reuse the same update function for all background clouds to save memory
    const backgroundCloudUpdate = (dt: number, time: number) => {
        // Slow drift
        // We can access 'this' if we bind or use the object passed to loop
        // But here we'll rely on the cloud.userData which CloudBatcher uses?
        // Actually CloudBatcher calls `cloud.userData.onAnimate(dt, time)`
    };

    for (let i = 0; i < CLOUD_COUNT; i++) {
        // Random position in a large disk
        const angle = Math.random() * Math.PI * 2;
        // Use square root for uniform disk distribution
        const r = Math.sqrt(Math.random()) * RADIUS;

        const x = Math.cos(angle) * r;
        const z = Math.sin(angle) * r;

        // Use noise to determine density/size
        const density = getNoise(x, z);

        // Threshold: Only spawn where noise is high enough to form clusters
        // This creates "banks" of clouds instead of uniform noise
        if (density < 0.35) continue;

        // Create Cloud Logic Object
        // For background clouds, we use fewer puffs per cloud for performance,
        // but larger scale to fill space.
        const scale = 4.0 + density * 6.0; // Massive clouds (4x to 10x)
        const puffCount = Math.floor(8 + density * 8); // 8 to 16 puffs

        const cloud = createCloud({
            scale: scale,
            puffCount: puffCount,
            tier: 2 // Cosmetic tier
        });

        // Set Position
        // Higher density clouds are slightly lower (heavier) for layering effect
        const y = MIN_HEIGHT + Math.random() * HEIGHT_RANGE - (density * 20.0);
        cloud.position.set(x, y, z);

        // Random Rotation
        cloud.rotation.y = Math.random() * Math.PI * 2;
        cloud.rotation.x = (Math.random() - 0.5) * 0.2; // Slight tilt

        // Assign Drift Logic
        // Background clouds drift very slowly along wind (fixed here for simplicity)
        cloud.userData.velocity = new THREE.Vector3(1.0, 0, 0.5);

        cloud.userData.onAnimate = (dt: number, time: number) => {
             // Simple linear drift
             // Wrap around world bounds if needed, or just let them drift (they are far)
             // For now, static is safer for batcher optimization (sleeping clouds)
             // cloud.position.x += dt * 1.0;
        };

        // Register immediately with batcher
        CloudBatcher.getInstance().register(cloud, { scale, puffCount });

        // Add to return list
        generatedClouds.push(cloud);

        // Optional: Add to scene if we want them to be part of the graph (e.g. for debug)
        // scene.add(cloud);
    }

    console.log(`[Procedural Sky] Generated ${generatedClouds.length} background clouds.`);
    return generatedClouds;
}

import * as THREE from 'three';
import type UniformNode from 'three/src/nodes/core/UniformNode.js';
import { color, uv, mix, Fn, uniform, sin, time, smoothstep, float } from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { registerReactiveMaterial } from './foliage-reactivity.ts';
import { uAudioLow, uAudioHigh } from './index.ts';


export const uRainbowOpacity = uniform(0.0);

export function createRainbow(): THREE.Mesh | THREE.Group {
    // TEMP ISOLATION - comment everything below and just return empty
    return new THREE.Group();

    // Large Ring Geometry
    const innerRadius = 80;
    const outerRadius = 90;
    const geometry = new THREE.RingGeometry(innerRadius, outerRadius, 64, 1, 0, Math.PI);

    function ensureUVAttribute(geometry: THREE.BufferGeometry) {
        if (!geometry.attributes.uv && geometry.attributes.position) {
            const count = geometry.attributes.position.count;
            const uvs = new Float32Array(count * 2);
            geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
        }
    }
    ensureUVAttribute(geometry);

    // Position it: Center at (0, -10, -50) so it arcs over the world
    // We'll let the caller position it, but default logic needs to be upright.

    // TSL Material
    const material = new MeshStandardNodeMaterial();
    material.transparent = true;
    material.side = THREE.DoubleSide;
    material.depthWrite = false;
    material.blending = THREE.AdditiveBlending;

    // Rainbow Gradient
    // UV.x goes 0->1 along the arc
    // UV.y goes 0->1 from inner to outer radius

    // Colors
    const cRed = color(0xFF0000);
    const cOrange = color(0xFFA500);
    const cYellow = color(0xFFFF00);
    const cGreen = color(0x008000);
    const cBlue = color(0x0000FF);
    const cIndigo = color(0x4B0082);
    const cViolet = color(0xEE82EE);

    // Multi-stop gradient helper
    // 0.0-0.16: Red->Orange
    // 0.16-0.33: Orange->Yellow
    // ...

    // We use smoothstep logic for bands, or just a simple mix chain.
    // For TSL, it's easier to map uv.y (width of band) to spectrum if we want stripes across the width.
    // Usually rainbows have colors arranged RADIALLY (inner to outer).
    // So we use UV.y.

    const t = uv().y;

    let col = mix(cRed, cOrange, smoothstep(0.0, 0.16, t));
    col = mix(col, cYellow, smoothstep(0.16, 0.33, t));
    col = mix(col, cGreen, smoothstep(0.33, 0.5, t));
    col = mix(col, cBlue, smoothstep(0.5, 0.66, t));
    col = mix(col, cIndigo, smoothstep(0.66, 0.83, t));
    col = mix(col, cViolet, smoothstep(0.83, 1.0, t));

    // Soften edges
    const edgeAlpha = smoothstep(0.0, 0.2, t).mul(smoothstep(1.0, 0.8, t));

    // Soften ends of the arc
    const arcAlpha = smoothstep(0.0, 0.1, uv().x).mul(smoothstep(1.0, 0.9, uv().x));

    // Beat pulse?
    const pulse = sin(time.mul(2.0)).mul(0.1).add(0.9).add(uAudioLow.mul(0.5));

    material.colorNode = col;
    material.opacityNode = uRainbowOpacity.mul(edgeAlpha).mul(arcAlpha).mul(pulse);
    material.emissiveNode = col.mul(float(0.5).add(uAudioHigh.mul(2.0))); // Audio-reactive glow

    registerReactiveMaterial(material);

    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = 'Rainbow';

    // Default transform: upright facing Z
    // RingGeometry creates a flat ring on XY plane.
    // We want it arcing over the ground.
    // Default is perfect. Just need to ensure it's high enough.

    return mesh;
}

import * as THREE from 'three';
import {
    color, float, vec3, Fn, uniform, mix,
    positionLocal, normalWorld,
    cameraPosition, sin, abs, smoothstep, uv,
    mx_noise_float
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { fastInvSqrt } from '../utils/wasm-loader.ts';
import { createUnifiedMaterial } from './index.ts';

/**
 * Melody Ribbon System
 *
 * Creates a dynamic trail that follows a virtual "head" position.
 * The Y position of the head is driven by the pitch of the melody channel.
 * The geometry is updated every frame in JavaScript to create the ribbon path,
 * while TSL handles the material appearance (fading, glowing, sparkling).
 */

const MAX_SEGMENTS = 200; // Number of segments in the ribbon
const SEGMENT_WIDTH = 0.8;
const RIBBON_SPEED = 0.2; // Forward speed in world units per frame
const MIN_PITCH_HEIGHT = 2.0;
const MAX_PITCH_HEIGHT = 15.0;
const SEGMENT_LENGTH = 1.0; // Distance between segments updates if we were distance-based

// Global Uniforms for the ribbon material
const uRibbonTime = uniform(0.0);
const uRibbonColor = uniform(vec3(0.0, 1.0, 1.0)); // Default cyan

interface PathPoint {
    x: number;
    y: number;
    z: number;
    width: number;
}

interface RibbonUserData {
    mesh: THREE.Mesh;
    pathHistory: PathPoint[];
    headPosition: THREE.Vector3;
    headDirection: THREE.Vector3;
    currentPitchHeight: number;
    targetPitchHeight: number;
    isActive: boolean;
}

interface AudioChannelData {
    trigger: number;
    note: number;
}

interface AudioData {
    channelData?: { [key: number]: AudioChannelData };
}

export function createMelodyRibbon(scene: THREE.Scene): THREE.Group {
    const group = new THREE.Group();
    group.name = 'MelodyRibbonSystem';

    // 1. Create BufferGeometry
    // We use a Triangle Strip-like structure but built with indexed triangles for better control
    const vertexCount = (MAX_SEGMENTS + 1) * 2;
    const geometry = new THREE.BufferGeometry();

    const positions = new Float32Array(vertexCount * 3);
    const uvs = new Float32Array(vertexCount * 2);
    const indices: number[] = [];

    // Initialize flat strip along Z
    for (let i = 0; i <= MAX_SEGMENTS; i++) {
        // Left point
        positions[i * 6 + 0] = -SEGMENT_WIDTH / 2;
        positions[i * 6 + 1] = 0;
        positions[i * 6 + 2] = i * SEGMENT_LENGTH;

        uvs[i * 4 + 0] = 0;
        uvs[i * 4 + 1] = i / MAX_SEGMENTS;

        // Right point
        positions[i * 6 + 3] = SEGMENT_WIDTH / 2;
        positions[i * 6 + 4] = 0;
        positions[i * 6 + 5] = i * SEGMENT_LENGTH;

        uvs[i * 4 + 2] = 1;
        uvs[i * 4 + 3] = i / MAX_SEGMENTS;

        if (i < MAX_SEGMENTS) {
            const base = i * 2;
            // Triangle 1
            indices.push(base, base + 1, base + 2);
            // Triangle 2
            indices.push(base + 1, base + 3, base + 2);
        }
    }

    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage));
    geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
    geometry.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(vertexCount * 3).fill(0), 3)); // Dummy normals for TSL
    geometry.setIndex(indices);

    // 2. Create TSL Material
    const material = createUnifiedMaterial(0x00FFFF, {
        roughness: 0.2,
        metalness: 0.1,
        transmission: 0.5,
        thickness: 0.1,
        ior: 1.2,
        side: THREE.DoubleSide
    });

    // Custom TSL logic for the ribbon
    const vUv = uv();

    // Sparkle effect
    const sparkleNoise = mx_noise_float(positionLocal.mul(10.0).add(uRibbonTime));
    const sparkle = smoothstep(0.8, 1.0, sparkleNoise);

    // Gradient Color: mix between Color1 (Low Pitch) and Color2 (High Pitch)?
    // For now, simple glowing cyan/pink gradient
    const gradientColor = mix(vec3(0.0, 0.5, 1.0), vec3(1.0, 0.2, 0.8), sin(vUv.y.mul(10.0).add(uRibbonTime)).mul(0.5).add(0.5));

    // Opacity: Fade at the tail (UV.y near 0)
    const fade = smoothstep(0.0, 0.2, vUv.y);

    material.colorNode = gradientColor;
    material.emissiveNode = gradientColor.mul(sparkle.mul(2.0).add(0.5)); // Base glow + sparkle
    material.opacityNode = fade;
    material.transparent = true;

    // Create Mesh
    const mesh = new THREE.Mesh(geometry, material);
    mesh.frustumCulled = false; // Always render, it moves a lot
    group.add(mesh);

    // Initial State
    const pathHistory: PathPoint[] = [];
    for (let i = 0; i <= MAX_SEGMENTS; i++) {
        pathHistory.push({ x: 0, y: -100, z: 0, width: 0 }); // Start hidden
    }

    // Attach state to group userdata
    group.userData = {
        mesh,
        pathHistory,
        headPosition: new THREE.Vector3(0, 5, 0), // Start somewhere visible
        headDirection: new THREE.Vector3(0, 0, 1),
        currentPitchHeight: 5.0,
        targetPitchHeight: 5.0,
        isActive: false
    } as RibbonUserData;

    scene.add(group);
    return group;
}

export function updateMelodyRibbons(group: THREE.Group, deltaTime: number, audioData: AudioData | null) {
    if (!group || !group.userData.mesh) return;

    const data = group.userData as RibbonUserData;
    const { mesh, pathHistory, headPosition, headDirection } = data;

    // Update Uniforms
    uRibbonTime.value += deltaTime;

    // 1. Get Audio Data (Melody Channel - usually Channel 2)
    // FIX: Access channelData safely
    let volume = 0;
    let note = 0;

    if (audioData && audioData.channelData) {
        // Use Channel 2 (Melody) or fallback to active channels
        const ch = audioData.channelData[2];
        if (ch) {
            volume = ch.trigger || 0; // 'trigger' is the volume/intensity value
            note = ch.note || 0;
        }
    }

    const hasNote = volume > 0.05;

    // 2. Update Head Logic

    // Move forward (Circle path)
    const time = uRibbonTime.value;
    const radius = 30.0;
    const speed = 0.5;

    const targetX = Math.sin(time * speed) * radius;
    const targetZ = Math.cos(time * speed) * radius;

    // Smoothly interpolate X/Z
    headPosition.x += (targetX - headPosition.x) * deltaTime * 2.0;
    headPosition.z += (targetZ - headPosition.z) * deltaTime * 2.0;

    // Calculate Pitch Height
    if (hasNote) {
        // Map MIDI note (e.g. 48 to 84) to height
        // Standard range approx C3 to C6
        const n = note;
        const normalizedPitch = (n % 24) / 24.0; // simple modulation
        data.targetPitchHeight = MIN_PITCH_HEIGHT + normalizedPitch * (MAX_PITCH_HEIGHT - MIN_PITCH_HEIGHT);
    } else {
        // Return to base height
        data.targetPitchHeight = MIN_PITCH_HEIGHT + (MAX_PITCH_HEIGHT - MIN_PITCH_HEIGHT) * 0.5;
    }

    // Lerp height
    headPosition.y += (data.targetPitchHeight - headPosition.y) * deltaTime * 5.0;

    // 3. Update Path History
    // Shift everything down
    pathHistory.shift();
    pathHistory.push({
        x: headPosition.x,
        y: headPosition.y,
        z: headPosition.z,
        width: SEGMENT_WIDTH + volume * 2.0 // Modulate width by volume
    });

    // 4. Update Geometry
    const positionAttr = mesh.geometry.attributes.position;
    const positions = positionAttr.array as Float32Array;

    for (let i = 0; i <= MAX_SEGMENTS; i++) {
        const point = pathHistory[i];

        let dirX = 0, dirZ = 1;
        if (i < MAX_SEGMENTS) {
            const next = pathHistory[i+1];
            const dx = next.x - point.x;
            const dz = next.z - point.z;
            const distSq = dx*dx + dz*dz;
            // ⚡ OPTIMIZATION: Use squared distance dirty check and fast inverse square root to eliminate Math.sqrt()
            if (distSq > 0.000001) {
                const invLen = fastInvSqrt(distSq);
                dirX = dx * invLen;
                dirZ = dz * invLen;
            }
        }

        // Perpendicular vector (-dirZ, dirX)
        const perpX = -dirZ;
        const perpZ = dirX;

        const w = point.width / 2;

        // Left Vertex
        positions[i * 6 + 0] = point.x - perpX * w;
        positions[i * 6 + 1] = point.y;
        positions[i * 6 + 2] = point.z - perpZ * w;

        // Right Vertex
        positions[i * 6 + 3] = point.x + perpX * w;
        positions[i * 6 + 4] = point.y;
        positions[i * 6 + 5] = point.z + perpZ * w;
    }

    positionAttr.needsUpdate = true;
    mesh.geometry.computeVertexNormals();
}

import * as THREE from 'three';
import {
    vec3,
    sin,
    cos,
    positionLocal,
    timerLocal
} from 'three/tsl';
import {
    createUnifiedMaterial,
    uTime,
    uAudioLow
} from './index.ts';

/**
 * Creates the "Arpeggio Shield" - a crystalline barrier.
 * It is attached to the player visually.
 */
export function createShield(): THREE.Mesh {
    const geometry = new THREE.IcosahedronGeometry(1.2, 0); // Low poly crystal look

    // TSL Animation: Rotate and Breathe
    // We modify positionLocal for the vertex shader

    // 1. Rotation (Y-axis spin)
    const speed = 1.0;
    const angle = uTime.mul(speed);
    const c = cos(angle);
    const s = sin(angle);

    // Rotate around Y
    // x' = x*c + z*s
    // z' = -x*s + z*c
    const rotX = positionLocal.x.mul(c).add(positionLocal.z.mul(s));
    const rotZ = positionLocal.x.negate().mul(s).add(positionLocal.z.mul(c));
    const rotPos = vec3(rotX, positionLocal.y, rotZ);

    // 2. Pulse (Audio Reactive)
    // Expand based on Bass (Kick)
    const pulse = uAudioLow.mul(0.2).add(1.0); // 1.0 to 1.2 scale
    const finalPos = rotPos.mul(pulse);

    const material = createUnifiedMaterial(0x00FFFF, {
        deformationNode: finalPos,
        roughness: 0.1,
        metalness: 0.1,
        transmission: 0.6,    // See-through
        thickness: 0.5,       // Refraction depth
        ior: 1.6,             // Crystal-like refraction
        iridescenceStrength: 1.0,
        iridescenceFresnelPower: 2.0,
        sheen: 1.0,
        sheenColor: 0xFF00FF, // Magenta sheen on Cyan base
        side: THREE.FrontSide, // Only render outside for efficiency? Or Double for thickness?
                               // Transmission usually works best with FrontSide + Thickness
        animatePulse: true     // Adds subtle emissive pulse
    });

    const mesh = new THREE.Mesh(geometry, material);
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.renderOrder = 10; // Render after opaque objects for transparency

    return mesh;
}

// src/foliage/silence-spirits.ts

import * as THREE from 'three';
import {
    color, float, mix, sin, cos, positionLocal, positionWorld, vec3, normalWorld,
    mx_noise_float, distance, smoothstep, max, min
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { getBiomeUniforms, type BiomeId } from '../systems/biome-uniforms.ts';
import { grantInvisibility } from '../systems/physics/index.ts';
import {
    sharedGeometries,
    registerReactiveMaterial,
    attachReactivity,
    uTime,
    uPlayerPosition
} from './index.ts';

export interface SilenceSpiritOptions {
    scale?: number;
}

export function createSilenceSpirit(options: SilenceSpiritOptions = {}): THREE.Group {
    const group = new THREE.Group();
    const { scale = 1.0 } = options;

    // PALETTE UPDATE: Ethereal Stardust Material (TSL)
    // Replaces JS-driven opacity animation
    const mat = new MeshStandardNodeMaterial({
        color: 0xEEFFFF,
        transparent: true,
        blending: THREE.AdditiveBlending, // Glowy
        depthWrite: false,
        roughness: 0.2,
        side: THREE.DoubleSide
    });

    // TSL Logic

    // 1. Proximity Dissolve (Flee behavior)
    // Spirit fades away when player approaches (shy/silent)
    const dist = distance(positionWorld, uPlayerPosition);
    // Fully invisible at 1.5 units, fully visible at 8.0 units
    const proximityAlpha = smoothstep(1.5, 8.0, dist);

    // 2. Stardust Noise (Internal motion)
    // Flowing noise texture
    const noiseScale = float(3.0);
    const flowSpeed = vec3(0.0, uTime.mul(0.4), 0.0); // Rising spirit
    const noisePos = positionLocal.mul(noiseScale).sub(flowSpeed);
    const stardust = mx_noise_float(noisePos); // -1 to 1

    // Remap noise to soft clouds (0.2 to 0.8)
    const cloudDensity = stardust.mul(0.3).add(0.5);

    // 3. Pulse (Heartbeat of silence)
    const pulse = sin(uTime.mul(1.5)).mul(0.1).add(0.9);

    // Combine Alpha
    const alpha = cloudDensity.mul(proximityAlpha).mul(pulse).mul(0.8);

    mat.opacityNode = alpha;

    // Emissive Glow
    // Blue-ish core, White edges
    const glowColor = color(0x88CCFF);
    // Music Impact: crystalline nebula shimmer/noteColor tints the ethereal spirits
    const nebulaUniforms = getBiomeUniforms('crystalline_nebula');
    const musicTint = nebulaUniforms.noteColor.mul(nebulaUniforms.shimmer).mul(0.35);
    mat.emissiveNode = glowColor.mul(alpha).mul(2.0).add(musicTint); // Bright glow
    mat.colorNode = color(0xEEFFFF);

    // 1. Ghost Body
    const bodyGeo = new THREE.CapsuleGeometry(0.3 * scale, 1.0 * scale, 4, 8);
    bodyGeo.translate(0, 0.8 * scale, 0);
    // Ensure UVs/Normals for TSL (Capsule usually has them)

    const body = new THREE.Mesh(bodyGeo, mat);
    group.add(body);

    // Antlers / Head (Same material, visual unity)
    const headGeo = new THREE.SphereGeometry(0.25 * scale, 8, 8);
    const head = new THREE.Mesh(headGeo, mat);
    head.position.y = 1.4 * scale;
    body.add(head);

    // 2. State
    group.userData.type = 'silenceSpirit';
    // Removed 'spiritFade' animationType as logic is now in TSL
    group.userData.isVisible = true;

    group.userData.isInteractive = true;
    group.userData.interactionText = "Commune";
    group.userData.onInteract = () => {
        grantInvisibility(5.0);
    };

    // Register for reactivity (maybe for light level checks if needed later)
    // But purely visual fading is now GPU-side.

    return group;
}

import * as THREE from 'three';
import { mergeGeometries, mergeVertices } from 'three/addons/utils/BufferGeometryUtils.js';
import { attribute, color as tslColor, positionLocal, vec3, float, mx_noise_float, mix, sin, smoothstep, normalize, length, positionWorld, uv, distance, vec2, varyingProperty, add } from 'three/tsl';
import { PointsNodeMaterial } from 'three/webgpu';
import { shouldUseFoliageGpuBatch } from '../compute/foliage-gpu-batch.ts';
import { isGpuFoliageDefaultPath } from '../compute/gpu-foliage-flag.ts';
import {
    runGpuPlantPose,
    uploadGpuPlantPositions,
    shouldUseGpuPlantPose,
    type GpuPlantPoseWave,
} from '../compute/gpu-plant-pose.ts';
import { camera } from '../core/camera-ref.ts';
import { CONFIG } from '../core/config.ts';
import { BiomeUniforms, circadianDayGlowMult } from '../systems/biome-uniforms.ts';
import { getActiveWave } from '../systems/music-wave.ts';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
import { foliageGroup } from '../world/state.ts';
import {
    foliageMaterials,
    sharedGeometries,
    CandyPresets,
    createClayMaterial,
    calculateFlowerBloom,
    calculateWindSway,
    applyPlayerInteraction,
    applyStandardDeformation,
    createJuicyRimLight,
    uTime,
    uAudioHigh,
    uAudioLow,
    uPlayerPosition
} from './index.ts';
import { PlantPoseMachine } from './plant-pose-machine.ts';
import { uTwilight } from './sky.ts';

// Use the instanced color varying populated by InstancedMeshNode
const instanceColor = varyingProperty('vec3', 'vInstanceColor');

const MAX_FLOWERS = 1000; // Reduced from 5000 for WebGPU uniform buffer limits
const GRAINS_PER_FLOWER = 5;
const MAX_POLLEN = MAX_FLOWERS * GRAINS_PER_FLOWER;

const _scratchMat = new THREE.Matrix4();
const _scratchMat2 = new THREE.Matrix4();
const _scratchPos = new THREE.Vector3();
const _scratchQuat = new THREE.Quaternion();
const _scratchEuler = new THREE.Euler();
const _scratchScale = new THREE.Vector3();
const _scratchColor = new THREE.Color();

export class SimpleFlowerBatcher {
    private _poseMachine!: PlantPoseMachine;
    private _gpuPositions: Float32Array | null = null;
    private _lastGpuPoses: Float32Array | null = null;
    private _gpuPoseInFlight = false;
    initialized: boolean;
    count: number;

    // Meshes
    stemMesh: THREE.InstancedMesh | null;
    petalMesh: THREE.InstancedMesh | null;
    centerMesh: THREE.InstancedMesh | null;
    stamenMesh: THREE.InstancedMesh | null;
    beamMesh: THREE.InstancedMesh | null;

    // Pollen System
    pollenPoints: THREE.Points | null;
    pollenPositions: Float32Array | null;
    pollenOffsets: Float32Array | null;
    pollenColors: Float32Array | null;

    constructor() {
        this.initialized = false;
        this.count = 0;
        this.stemMesh = null;
        this.petalMesh = null;
        this.centerMesh = null;
        this.stamenMesh = null;
        this.beamMesh = null;
        this.pollenPoints = null;
        this.pollenPositions = null;
        this.pollenOffsets = null;
        this.pollenColors = null;
    }

    init() {
        if (this.initialized) return;

        // 1. Prepare Geometries

        // Stem: Unit Cylinder
        const stemGeo = sharedGeometries.unitCylinder.clone();

        // Petals: Pre-merged 5-petal flower shape
        const petalGeos: THREE.BufferGeometry[] = [];
        let basePetalGeo: THREE.BufferGeometry = new THREE.IcosahedronGeometry(0.15, 0);
        basePetalGeo = mergeVertices(basePetalGeo);
        basePetalGeo.scale(1, 0.5, 1);

        // ⚡ OPTIMIZATION: Re-use scratch variables to avoid GC spikes inside geometry generation loop
        const petalCount = 5;
        for (let i = 0; i < petalCount; i++) {
            const angle = (i / petalCount) * Math.PI * 2;
            _scratchMat.makeRotationZ(Math.PI / 4);
            _scratchMat.setPosition(Math.cos(angle) * 0.18, 0, Math.sin(angle) * 0.18);

            const clone = basePetalGeo.clone();
            clone.applyMatrix4(_scratchMat);
            petalGeos.push(clone);
        }
        const mergedPetals = mergeGeometries(petalGeos);

        // Center: Unit Sphere
        const centerGeo = sharedGeometries.unitSphere.clone();

        // Stamens: 3 Cylinders
        const stamenGeos: THREE.BufferGeometry[] = [];
        const stamenBase = sharedGeometries.unitCylinder;
        // ⚡ OPTIMIZATION: Re-use scratch variables to avoid GC spikes inside stamen generation loop
        const stamenCount = 3;
        for (let i = 0; i < stamenCount; i++) {
            const fixedRz = (i - 1) * 0.3;
            const fixedRx = 0;

            _scratchPos.set(0, 0.075, 0);
            _scratchEuler.set(fixedRx, 0, fixedRz);
            _scratchQuat.setFromEuler(_scratchEuler);
            _scratchScale.set(0.01, 0.15, 0.01);
            _scratchMat.compose(_scratchPos, _scratchQuat, _scratchScale);

            const clone = stamenBase.clone();
            clone.applyMatrix4(_scratchMat);
            stamenGeos.push(clone);
        }
        const mergedStamens = mergeGeometries(stamenGeos);

        // Beam: Cone
        const beamGeo = sharedGeometries.unitCone.clone();

        // 2. Prepare Materials

        // Stem: Reuse existing logic (Wind + Player Push)
        const stemMat = (foliageMaterials as any).flowerStem.clone();

        // Petal: Velvet with Instance Color + Bloom + Wind + Push
        const posBloom = calculateFlowerBloom(positionLocal);
        const posFinal = applyStandardDeformation(posBloom);

        // PALETTE: Enhance Petal Material with "Juice"
        const petalMat = CandyPresets.Velvet(0xFFFFFF, {
            deformationNode: posFinal,
            audioReactStrength: 1.0 // Adds subtle vibration/pulse
        });

        petalMat.colorNode = instanceColor;
        petalMat.sheenNode = instanceColor;

        // 3. Add Juicy Rim Light (Neon Edge)
        const rim = createJuicyRimLight(instanceColor, float(1.0), float(3.0), null);

        // 4. Add Audio-Reactive Glitter
        const glitterNoise = mx_noise_float(positionLocal.mul(float(50.0)).add(uTime.mul(5.0)));
        const glitter = glitterNoise.mul(uAudioHigh).mul(0.5);

        // 5. Add Touch Glow (Player Interaction)
        // If player is close, emit Gold/White glow
        const distToPlayer = length(positionWorld.sub(uPlayerPosition));
        // Fix: smoothstep edges must be low -> high. Invert for distance falloff.
        const touchGlow = float(1.0).sub(smoothstep(0.0, 1.5, distToPlayer));
        const touchColor = vec3(1.0, 0.9, 0.5).mul(touchGlow).mul(2.0); // Gold boost

        // Combine Emissive: Base Emissive (if any) + Rim + Glitter + TouchGlow
        // 🎨 PALETTE: Twilight Glow for simple flowers
        const glowPhaseOffset = positionLocal.x.add(positionLocal.y).add(positionLocal.z).mul(5.0);
        const idlePulse = sin(uTime.mul(float(CONFIG.glow.glowPulseFrequency)).add(glowPhaseOffset)).mul(float(CONFIG.glow.glowPulseAmplitude)).add(1.0).mul(float(0.5)).mul(uAudioLow.mul(0.3).add(0.7));
        const targetGlowColor = tslColor(CONFIG.glow.glowColorMap['flower']);
        const twilightGlowTint = targetGlowColor
            .mul(uTwilight)
            .mul(float(CONFIG.glow.glowIntensityMax))
            .mul(float(0.3).add(idlePulse));
        const biomeTint = BiomeUniforms.musicalFlora.noteColor.mul(BiomeUniforms.musicalFlora.shimmer.mul(0.35));
        // Circadian: diurnal rest dim — music/touch/twilight still add on top.
        const dayGlow = circadianDayGlowMult(0.2);
        petalMat.emissiveNode = add(
            petalMat.emissiveNode ?? tslColor(0x000000),
            rim,
            glitter,
            touchColor,
            twilightGlowTint,
            biomeTint.mul(dayGlow),
        );

        // Center: Velvet (Brown) + Chain
        const centerMat = (foliageMaterials as any).flowerCenter.clone();
        (centerMat as any).positionNode = posFinal;

        // Stamens: Clay (Yellow) + Chain
        const stamenMat = createClayMaterial(0xFFFF00, { deformationNode: posFinal });

        // Beam: Enhanced LightBeam
        const beamMat = (foliageMaterials as any).lightBeam.clone();
        beamMat.colorNode = mix(tslColor(0xFFFFFF), instanceColor, float(0.3));
        const bassPulse = float(0.8).add(uAudioLow);
        beamMat.opacityNode = beamMat.opacityNode.mul(bassPulse);

        // 3. Create InstancedMeshes

        this.stemMesh = this.createInstancedMesh(stemGeo, stemMat, MAX_FLOWERS, 'SimpleFlower_Stem');
        this.petalMesh = this.createInstancedMesh(mergedPetals, petalMat, MAX_FLOWERS, 'SimpleFlower_Petal');
        this.centerMesh = this.createInstancedMesh(centerGeo, centerMat, MAX_FLOWERS, 'SimpleFlower_Center');
        this.stamenMesh = this.createInstancedMesh(mergedStamens, stamenMat, MAX_FLOWERS, 'SimpleFlower_Stamen');
        this.beamMesh = this.createInstancedMesh(beamGeo, beamMat, MAX_FLOWERS, 'SimpleFlower_Beam');
        this.petalMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(MAX_FLOWERS * 3), 3);
        this.beamMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(MAX_FLOWERS * 3), 3);
        // Provide aPoseState so TSL attribute('aPoseState') resolves
        const meshes = [this.stemMesh, this.petalMesh, this.centerMesh, this.stamenMesh, this.beamMesh];
        for (let i = 0; i < meshes.length; i++) {
            meshes[i].geometry.setAttribute('aPoseState', new THREE.InstancedBufferAttribute(new Float32Array(MAX_FLOWERS), 1));
        }

        // Add to Scene
        this.petalMesh.geometry.setAttribute('aPoseState', new THREE.InstancedBufferAttribute(new Float32Array(MAX_FLOWERS).fill(0), 1));

        foliageGroup.add(this.stemMesh);
        foliageGroup.add(this.petalMesh);
        foliageGroup.add(this.centerMesh);
        foliageGroup.add(this.stamenMesh);
        foliageGroup.add(this.beamMesh);

        // 4. Pollen System (Juice)
        this.initPollenSystem();

        this._poseMachine = new PlantPoseMachine(MAX_FLOWERS);
        this._gpuPositions = new Float32Array(MAX_FLOWERS * 3);
        this.initialized = true;
        console.log(`[SimpleFlowerBatcher] Initialized with capacity ${MAX_FLOWERS}`);
    }

    private initPollenSystem() {
        const pollenGeo = new THREE.BufferGeometry();
        this.pollenPositions = new Float32Array(MAX_POLLEN * 3);
        this.pollenOffsets = new Float32Array(MAX_POLLEN * 3);
        this.pollenColors = new Float32Array(MAX_POLLEN * 3);

        pollenGeo.setAttribute('position', new THREE.BufferAttribute(this.pollenPositions, 3));
        pollenGeo.setAttribute('offset', new THREE.BufferAttribute(this.pollenOffsets, 3));
        pollenGeo.setAttribute('color', new THREE.BufferAttribute(this.pollenColors, 3));

        const pollenMat = new PointsNodeMaterial({
            size: 0.1, // Base Size (overridden by sizeNode)
            transparent: true,
            depthWrite: false,
            blending: THREE.AdditiveBlending
        });

        // TSL Logic for Pollen
        const aPos = attribute('position', 'vec3'); // World Pos of Flower Head
        const aOffset = attribute('offset', 'vec3'); // Random Local Offset
        const aColor = attribute('color', 'vec3');

        // Base Position: Flower Head + Local Offset
        const basePos = aPos.add(aOffset);

        // 1. Gentle Hover (Idle)
        const hover = vec3(
            sin(uTime.add(aOffset.x.mul(10.0))).mul(0.05),
            sin(uTime.mul(1.5).add(aOffset.y.mul(10.0))).mul(0.1), // Up/Down
            sin(uTime.add(aOffset.z.mul(10.0))).mul(0.05)
        );

        // 2. Wind Sway (Match Flowers)
        // We pass a proxy local position with Y=1.0 (approx flower height)
        // because calculateWindSway assumes input is local pos relative to pivot at Y=0
        const sway = calculateWindSway(vec3(0.0, 1.0, 0.0));

        // 3. Player Interaction (Wake Turbulence)
        const dist = length(basePos.sub(uPlayerPosition));
        // Fix: smoothstep edges must be low -> high. Invert for distance falloff.
        const push = float(1.0).sub(smoothstep(0.0, 2.5, dist)); // 0 to 1 when close

        // Expand outwards from Player
        const pushDir = normalize(basePos.sub(uPlayerPosition));
        // Turbulence: Swirl based on position + time
        const turb = vec3(
             sin(basePos.y.mul(10.0).add(uTime.mul(10.0))),
             sin(basePos.x.mul(10.0).add(uTime.mul(10.0))),
             sin(basePos.z.mul(10.0).add(uTime.mul(10.0)))
        ).mul(0.2);

        const expansion = pushDir.mul(push).mul(1.5).add(turb.mul(push));

        // Final Position
        pollenMat.positionNode = basePos.add(hover).add(sway).add(expansion);

        // Color: Brighten on interaction
        const brightColor = vec3(1.0, 1.0, 0.8); // White-Gold
        pollenMat.colorNode = mix(aColor, brightColor, push.mul(0.8));

        // Size: Pulse on Audio + Interaction
        const audioPulse = uAudioHigh.mul(0.1);
        const touchPulse = push.mul(0.15);
        (pollenMat as { sizeNode?: unknown }).sizeNode = float(0.05).add(audioPulse).add(touchPulse);

        // Circular soft-disc mask using uv() to avoid the gl_PointCoord WGSL error.
        const pollenCircle = smoothstep(float(0.5), float(0.2), distance(uv(), vec2(0.5, 0.5)));
        pollenMat.opacityNode = float(0.8).mul(pollenCircle);

        this.pollenPoints = new THREE.Points(pollenGeo, pollenMat);
        this.pollenPoints.frustumCulled = false; // Always update
        this.pollenPoints.name = 'SimpleFlower_Pollen';

        foliageGroup.add(this.pollenPoints);
    }

    private createInstancedMesh(geo: THREE.BufferGeometry, mat: THREE.Material, count: number, name: string): THREE.InstancedMesh {
        const mesh = new THREE.InstancedMesh(geo, mat, count);
        mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        mesh.castShadow = true;
        mesh.receiveShadow = true;
        mesh.count = 0;
        mesh.name = name;
        if (!mesh.instanceColor) {
            const defaultColors = new Float32Array(count * 3);
            defaultColors.fill(1.0);
            mesh.instanceColor = new THREE.InstancedBufferAttribute(defaultColors, 3);
        }
        mesh.geometry.setAttribute('instanceColor', mesh.instanceColor);
        return mesh;
    }

    update(time: number, deltaTime: number, audioState: any, dayNightBias: number) {
        if (!this.initialized || this.count === 0 || !this._poseMachine) return;

        const config = CONFIG.plantPose.simpleFlower;
        if (!config) return;

        const kick = audioState?.kickTrigger || audioState?.kick || 0;
        const activeWave = getActiveWave();
        const cameraPos = camera ? camera.position : undefined;

        const useGpuPose = shouldUseGpuPlantPose(this.count);

        if (useGpuPose && this._lastGpuPoses && this._lastGpuPoses.length >= this.count) {
            this._applyPoseState(this._lastGpuPoses);
        } else {
            const getPlantPos = (index: number, out: THREE.Vector3) => {
                if (!this.stemMesh) return;
                const array = this.stemMesh.instanceMatrix.array as Float32Array;
                const offset = index * 16;
                out.set(array[offset + 12], array[offset + 13], array[offset + 14]);
            };

            this._poseMachine.update(
                this.count,
                deltaTime,
                kick,
                dayNightBias,
                config,
                activeWave,
                getPlantPos,
                cameraPos
            );
            this._applyPoseState(this._poseMachine.currentPoses);
        }

        if (useGpuPose && !this._gpuPoseInFlight) {
            this._dispatchGpuPose(deltaTime, kick, dayNightBias, config, activeWave, cameraPos);
        }
    }

    private _applyPoseState(poses: Float32Array): void {
        const meshes = [this.stemMesh, this.petalMesh, this.centerMesh, this.stamenMesh, this.beamMesh];
        for (const mesh of meshes) {
            if (!mesh || mesh.count === 0) continue;
            const attr = mesh.geometry.getAttribute('aPoseState') as THREE.InstancedBufferAttribute;
            if (!attr) continue;
            const array = attr.array as Float32Array;
            const count = mesh.count;
            for (let i = 0; i < count; i++) {
                array[i] = poses[i];
            }
            attr.needsUpdate = true;
        }
    }

    private _dispatchGpuPose(
        deltaTime: number,
        kick: number,
        dayNightBias: number,
        config: NonNullable<typeof CONFIG.plantPose.simpleFlower>,
        activeWave: ReturnType<typeof getActiveWave>,
        cameraPos: THREE.Vector3 | undefined
    ): void {
        if (!this._gpuPositions) return;

        let wave: GpuPlantPoseWave | null = null;
        if (activeWave) {
            const origin = activeWave.origin || cameraPos;
            if (origin) {
                const speed = activeWave.speed || 25.0;
                const elapsedSec = Math.max(0, (performance.now() - activeWave.timestamp) / 1000);
                const radius = elapsedSec * speed;
                wave = {
                    originX: origin.x,
                    originY: origin.y,
                    originZ: origin.z,
                    radiusSq: radius * radius,
                };
            }
        }

        this._gpuPoseInFlight = true;
        void runGpuPlantPose({
            count: this.count,
            delta: deltaTime,
            channelIntensity: kick,
            dayNightBias,
            config,
            wave,
        })
            .then((poses) => {
                if (poses) this._lastGpuPoses = poses;
            })
            .finally(() => {
                this._gpuPoseInFlight = false;
            });
    }

    register(logicObject: THREE.Object3D, options: any = {}) {
        if (!this.initialized) this.init();
        if (this.count >= MAX_FLOWERS) {
            console.warn('[SimpleFlowerBatcher] Capacity full');
            return;
        }

        const i = this.count;
        const { color = 0xFFFFFF } = options;

        if (this._gpuPositions && isGpuFoliageDefaultPath()) {
            const base = i * 3;
            this._gpuPositions[base] = logicObject.position.x;
            this._gpuPositions[base + 1] = logicObject.position.y;
            this._gpuPositions[base + 2] = logicObject.position.z;
            uploadGpuPlantPositions(this._gpuPositions, this.count + 1);
        }

        // 1. Calculate Transforms
        _scratchMat.compose(logicObject.position, logicObject.quaternion, logicObject.scale);
        const baseMatrix = _scratchMat;

        // Stem: Scale (0.05, height, 0.05). Height is random.
        const stemHeight = 0.6 + Math.random() * 0.4;
        _scratchScale.set(0.05, stemHeight, 0.05);
        _scratchMat.makeScale(_scratchScale.x, _scratchScale.y, _scratchScale.z);
        _scratchMat.premultiply(baseMatrix); // Apply World Transform
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMat.toArray(this.stemMesh!.instanceMatrix.array, (i) * 16);

        // Head Transform (At top of stem)
        // Translation(0, stemHeight, 0) relative to Base.
        // ⚡ OPTIMIZATION: Re-use scratch variable to avoid GC spikes
        _scratchMat2.makeTranslation(0, stemHeight, 0);
        _scratchMat2.premultiply(baseMatrix); // directly modify _scratchMat2 for headWorld
        const headWorld = _scratchMat2; // No clone, avoid GC spike

        // Petals
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        headWorld.toArray(this.petalMesh!.instanceMatrix.array, (i) * 16);

        // Color
        if (typeof color === 'number') _scratchColor.setHex(color);
        else if (color instanceof THREE.Color) _scratchColor.copy(color);
        else _scratchColor.set(color as string);
        // ⚡ OPTIMIZATION: Write directly to instanceColor array to bypass .setColorAt overhead.
        if (this.petalMesh!.instanceColor) {
            const colorArray = this.petalMesh!.instanceColor.array as Float32Array;
            const colorOffset = i * 3;
            colorArray[colorOffset] = _scratchColor.r;
            colorArray[colorOffset + 1] = _scratchColor.g;
            colorArray[colorOffset + 2] = _scratchColor.b;
        }

        // Center: Scale(0.1)
        _scratchMat.makeScale(0.1, 0.1, 0.1);
        _scratchMat.premultiply(headWorld);
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMat.toArray(this.centerMesh!.instanceMatrix.array, (i) * 16);

        // Stamens: No extra scale needed (baked in geometry), just head transform
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        headWorld.toArray(this.stamenMesh!.instanceMatrix.array, (i) * 16);

        // Beam: force for glowing variants, otherwise random chance for visual variety.
        const forceBeam = options.forceBeam === true;
        if (forceBeam || Math.random() > 0.5) {
            _scratchMat.makeScale(0.1, 1.0, 0.1);
            _scratchMat.premultiply(headWorld);
            // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMat.toArray(this.beamMesh!.instanceMatrix.array, (i) * 16);
        } else {
            _scratchMat.makeScale(0, 0, 0);
            _scratchMat.premultiply(headWorld);
            // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMat.toArray(this.beamMesh!.instanceMatrix.array, (i) * 16);
        }
        // ⚡ OPTIMIZATION: Write directly to instanceColor array to bypass .setColorAt overhead.
        if (this.beamMesh!.instanceColor) {
            const colorArray = this.beamMesh!.instanceColor.array as Float32Array;
            const colorOffset = i * 3;
            colorArray[colorOffset] = _scratchColor.r;
            colorArray[colorOffset + 1] = _scratchColor.g;
            colorArray[colorOffset + 2] = _scratchColor.b;
        }

        // --- POLLEN REGISTRATION ---
        if (this.pollenPositions && this.pollenOffsets && this.pollenColors) {
            // Extract World Position of Flower Head
            // ⚡ OPTIMIZATION: Re-use scratch variable to avoid GC spikes
            _scratchPos.setFromMatrixPosition(headWorld);

            // Add GRAINS_PER_FLOWER particles
            const startPollen = i * GRAINS_PER_FLOWER;
            for (let p = 0; p < GRAINS_PER_FLOWER; p++) {
                const idx = startPollen + p;

                // Position: Flower Head (Shared base)
                this.pollenPositions[idx * 3] = _scratchPos.x;
                this.pollenPositions[idx * 3 + 1] = _scratchPos.y;
                this.pollenPositions[idx * 3 + 2] = _scratchPos.z;

                // Offset: Random in sphere R=0.25
                const r = 0.25 * Math.random();
                const theta = Math.random() * Math.PI * 2;
                const phi = Math.acos(2 * Math.random() - 1);

                this.pollenOffsets[idx * 3] = r * Math.sin(phi) * Math.cos(theta);
                this.pollenOffsets[idx * 3 + 1] = r * Math.cos(phi) + 0.1; // Slightly above center
                this.pollenOffsets[idx * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);

                // Color: Match Flower
                this.pollenColors[idx * 3] = _scratchColor.r;
                this.pollenColors[idx * 3 + 1] = _scratchColor.g;
                this.pollenColors[idx * 3 + 2] = _scratchColor.b;
            }
        }

        this.count++;

        if (this._poseMachine) {
            this._poseMachine.reset(i, 0);
        }

        // Mark for update
        this.stemMesh!.count = this.count;
        this.petalMesh!.count = this.count;
        this.centerMesh!.count = this.count;
        this.stamenMesh!.count = this.count;
        this.beamMesh!.count = this.count;

        if (!shouldUseFoliageGpuBatch(this.count)) {
            this.stemMesh!.instanceMatrix.needsUpdate = true;

            this.petalMesh!.instanceMatrix.needsUpdate = true;
            if (this.petalMesh!.instanceColor) this.petalMesh!.instanceColor.needsUpdate = true;

            this.centerMesh!.instanceMatrix.needsUpdate = true;

            this.stamenMesh!.instanceMatrix.needsUpdate = true;

            this.beamMesh!.instanceMatrix.needsUpdate = true;
            if (this.beamMesh!.instanceColor) this.beamMesh!.instanceColor.needsUpdate = true;
        }

        // Update Pollen
        if (this.pollenPoints) {
            this.pollenPoints.geometry.attributes.position.needsUpdate = true;
            this.pollenPoints.geometry.attributes.offset.needsUpdate = true;
            this.pollenPoints.geometry.attributes.color.needsUpdate = true;
            // Set draw range (count * grains) - wait, Points renders all vertices in buffer by default?
            // Yes, unless we set drawRange.
            this.pollenPoints.geometry.setDrawRange(0, this.count * GRAINS_PER_FLOWER);
        }
    }

    dispose(): void {
        const meshes = [
            this.stemMesh,
            this.petalMesh,
            this.centerMesh,
            this.stamenMesh,
            this.beamMesh,
            this.pollenPoints
        ];
        meshes.forEach(mesh => {
            if (mesh && mesh.parent) {
                safeRemoveAndDispose(mesh.parent, mesh);
            }
        });
    }
}

export const simpleFlowerBatcher = new SimpleFlowerBatcher();

/**
 * @file src/foliage/sky-islands.ts
 * @brief Floating candy sky-island meshes for the stacked vertical biome (#1363).
 *
 * Few landmasses (one per tier) — shared BiomeUniforms.skyIslands drive TSL
 * rim displacement + emissive shimmer. A lightweight registry tracks islands
 * for debug connectivity / spawn telemetry (not a full InstancedMesh batcher).
 */

import * as THREE from 'three';
import {
    positionLocal,
    vec3,
    float,
    sin,
    time,
    length,
    color,
    add,
    smoothstep,
} from 'three/tsl';
import { getBiomeUniforms } from '../systems/biome-uniforms.ts';
import { attachReactivity } from './foliage-reactivity.ts';
import { CandyPresets, createClayMaterial } from './material-core.ts';

export type SkyIslandLayerKind = 'mist' | 'canopy' | 'nebula';

export interface SkyIslandOptions {
    radius?: number;
    height?: number;
    /** mist = soft pastel clay; canopy = gem-tinged; nebula = crystalline candy */
    kind?: SkyIslandLayerKind;
    layerId?: string;
}

export interface SkyIslandRecord {
    id: string;
    layerId: string;
    kind: SkyIslandLayerKind;
    x: number;
    y: number;
    z: number;
    radius: number;
    topY: number;
    group: THREE.Object3D;
}

const _registry: SkyIslandRecord[] = [];

/** PALETTE: per-layer candy base colors */
const LAYER_COLORS: Record<SkyIslandLayerKind, number> = {
    mist: 0xFFD1DC,    // cotton-candy pink
    canopy: 0xE6E6FA,  // soft lilac
    nebula: 0xB0E0E6,  // powder aurora
};

const LAYER_UNDERSIDE: Record<SkyIslandLayerKind, number> = {
    mist: 0xFFE4E1,
    canopy: 0xDDA0DD,
    nebula: 0x87CEFA,
};

/**
 * Creates a floating sky island with GPU rim heightmap displacement.
 * Pivot is at the walkable top surface (y=0 locally); mesh extends downward.
 */
export function createSkyIsland(options: SkyIslandOptions = {}): THREE.Group {
    const {
        radius = 10,
        height = 3.5,
        kind = 'mist',
        layerId = 'sky_island',
    } = options;

    const group = new THREE.Group();
    group.userData.type = 'sky_island';
    group.userData.biome = 'sky_islands';
    group.userData.layerId = layerId;
    group.userData.islandKind = kind;
    group.userData.islandRadius = radius;
    group.userData.islandHeight = height;
    group.userData.isWalkable = true;

    const segments = 24;
    const islandGeo = new THREE.CylinderGeometry(radius, radius * 0.55, height, segments, 4);

    // CPU organic rim seed (GPU TSL adds live undulation on top)
    const pos = islandGeo.attributes.position;
    for (let i = 0; i < pos.count; i++) {
        const x = pos.getX(i);
        const y = pos.getY(i);
        const z = pos.getZ(i);
        const angle = Math.atan2(z, x);
        const r = Math.sqrt(x * x + z * z);
        const noise = Math.sin(angle * 5) * 0.55 + Math.cos(angle * 9) * 0.35;
        const rim = Math.max(0, (r / Math.max(radius, 0.001)) - 0.55);

        if (y > 0) {
            // Top surface: gentle hills, stronger near rim
            pos.setY(i, y + rim * noise * 0.8 + Math.sin(angle * 3) * 0.15);
        } else {
            // Underside taper with scalloped edge
            const taper = 1 + noise * 0.12 * (r / Math.max(radius, 0.001));
            pos.setX(i, x * taper);
            pos.setZ(i, z * taper);
            pos.setY(i, y - Math.abs(noise) * 0.4);
        }
    }
    islandGeo.computeVertexNormals();

    // Translate so top surface sits near local y=0 (walkable deck)
    islandGeo.translate(0, -height * 0.35, 0);

    const baseColor = LAYER_COLORS[kind];
    const underside = LAYER_UNDERSIDE[kind];

    let islandMat: any;
    if (kind === 'nebula') {
        islandMat = CandyPresets.Crystal(baseColor, {
            roughness: 0.25,
            transmission: 0.15,
        });
        islandMat.clearcoat = 0.9;
    } else if (kind === 'canopy') {
        islandMat = CandyPresets.Sugar(baseColor, {
            roughness: 0.35,
            sheen: 0.8,
        });
    } else {
        islandMat = createClayMaterial(baseColor);
        islandMat.roughness = 0.55;
    }

    // Music Impact: sky_islands shimmer drives rim bob + emissive pastel glow
    const u = getBiomeUniforms('sky_islands') as any;
    const radial = length(vec3(positionLocal.x, float(0), positionLocal.z)).div(float(radius));
    const rimMask = smoothstep(float(0.45), float(1.0), radial);
    const wave = sin(
        radial.mul(12.0)
            .add(time.mul(1.2))
            .add(u.hueShift.mul(6.0))
    ).mul(0.35);
    // Visual Impact: GPU heightmap-style rim displacement (music-reactive amplitude)
    const rimAmp = float(0.25).add(u.shimmer.mul(0.55));
    const rimDisp = vec3(0, rimMask.mul(wave).mul(rimAmp), 0);
    islandMat.positionNode = add(positionLocal, rimDisp);

    const shimmerColor = color(underside);
    const baseEmissive = color(baseColor).mul(u.shimmer).mul(0.45);
    const noteTint = u.noteColor.mul(u.shimmer).mul(0.35);
    const fogLift = u.fogDensity ? u.fogDensity.mul(0.2) : float(0.03);
    islandMat.emissiveNode = add(add(baseEmissive, noteTint), shimmerColor.mul(fogLift));

    const islandMesh = new THREE.Mesh(islandGeo, islandMat);
    islandMesh.castShadow = true;
    islandMesh.receiveShadow = true;
    group.add(islandMesh);

    // Soft candy "soil" disc on top for clearer walkable read
    const deckMat = CandyPresets.Clay(baseColor, { roughness: 0.7, bumpStrength: 0.15 });
    const deck = new THREE.Mesh(
        new THREE.CylinderGeometry(radius * 0.92, radius * 0.92, 0.18, segments),
        deckMat as THREE.Material
    );
    deck.position.y = 0.05;
    deck.receiveShadow = true;
    group.add(deck);

    // Underside stalactite candy drips (decorative)
    const dripCount = kind === 'nebula' ? 5 : 3;
    for (let i = 0; i < dripCount; i++) {
        const a = (i / dripCount) * Math.PI * 2 + 0.4;
        const dist = radius * (0.35 + (i % 3) * 0.15);
        const drip = new THREE.Mesh(
            new THREE.ConeGeometry(0.35 + Math.random() * 0.25, 1.2 + Math.random(), 6),
            createClayMaterial(underside)
        );
        drip.position.set(Math.cos(a) * dist, -height * 0.55, Math.sin(a) * dist);
        drip.rotation.x = Math.PI;
        group.add(drip);
    }

    attachReactivity(group, { type: 'flora' });
    return group;
}

/** Register an island after world placement (absolute Y set). */
export function registerSkyIsland(group: THREE.Object3D): SkyIslandRecord | null {
    if (group.userData.type !== 'sky_island') return null;
    const radius = typeof group.userData.islandRadius === 'number' ? group.userData.islandRadius : 10;
    const kind = (group.userData.islandKind as SkyIslandLayerKind) || 'mist';
    const layerId = typeof group.userData.layerId === 'string' ? group.userData.layerId : 'sky_island';
    const id = typeof group.userData.persistentId === 'string'
        ? group.userData.persistentId
        : `sky_island:${group.position.x.toFixed(1)}_${group.position.z.toFixed(1)}_${group.position.y.toFixed(1)}`;

    const record: SkyIslandRecord = {
        id,
        layerId,
        kind,
        x: group.position.x,
        y: group.position.y,
        z: group.position.z,
        radius,
        topY: group.position.y,
        group,
    };

    const existing = _registry.findIndex(r => r.id === id);
    if (existing >= 0) _registry[existing] = record;
    else _registry.push(record);

    return record;
}

export function getRegisteredSkyIslands(): readonly SkyIslandRecord[] {
    return _registry;
}

export function clearSkyIslandRegistry(): void {
    _registry.length = 0;
}

/**
 * Lightweight batcher facade — tracks islands for connectivity / debug.
 * Materials already share BiomeUniforms; no per-frame instance writes needed.
 */
export class SkyIslandBatcher {
    readonly id = 'sky_islands';

    get count(): number {
        return _registry.length;
    }

    register(group: THREE.Object3D): SkyIslandRecord | null {
        return registerSkyIsland(group);
    }

    clear(): void {
        clearSkyIslandRegistry();
    }
}

export const skyIslandBatcher = new SkyIslandBatcher();

// src/foliage/sky.ts

import * as THREE from 'three';
import type UniformNode from 'three/src/nodes/core/UniformNode.js';
import { color, mix, positionWorld, float, uniform, smoothstep, rangeFog, nodeObject, sin, pow } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { SkyUniforms, skyNoteColorNode } from '../systems/biome-uniforms.ts';
import { uAudioLow, uAudioHigh, uTime } from './index.ts';

// Export uniforms so main.js and weather.js can drive them
export const uSkyTopColor = uniform(color(0x7EC8E3));     
export const uSkyBottomColor = uniform(color(0xFFC5D3)); 
export const uHorizonColor = uniform(color(0xFFE5CC));   
export const uAtmosphereIntensity = uniform(0.3);        

export const uSkyDarkness = uniform(0.0); // 0.0 = Normal, 1.0 = Pitch Black

// --- NEW: Twilight Uniform for Plant Bioluminescence ---
// 0.0 = Day (No Glow), 1.0 = Night/Twilight (Full Glow)
export const uTwilight = uniform(0.0);
// -------------------------------------------------------

// --- Crescendo Fog (Audio Reactive Volumetric Fog) ---
export const uCrescendoFogDensity = uniform(0.0); // 0.0 = clear, 1.0 = dense
/** Base fog near — synced from atmosphere-fog + weather each frame. */
export const uFogNear = uniform(20.0);
/** Base fog far — synced from atmosphere-fog + weather each frame. */
export const uFogFar = uniform(100.0);

export function createCrescendoFogNode(colorNode: any) {
    // Dense fog parameters (computed dynamically from the base uniform values)
    const denseNear = uFogNear.mul(0.2);
    const denseFar = uFogFar.mul(0.3);

    // Interpolate near and far distances based on audio-driven density
    const currentNear = mix(uFogNear, denseNear, uCrescendoFogDensity);
    const currentFar = mix(uFogFar, denseFar, uCrescendoFogDensity);

    // Apply scene darkness to fog color (matches sky logic)
    const finalFogColor = mix(colorNode, color(0x000000), uSkyDarkness);

    return rangeFog(finalFogColor, currentNear, currentFar);
}
// -------------------------------------------------------

export function createSky(): THREE.Mesh {
    const skyGeo = new THREE.SphereGeometry(1000, 32, 24); 

    const offset = float(40.0);   
    const exponent = float(0.6);  

    const h = positionWorld.add(offset).normalize().y;
    const heightFactor = h.max(0.0).pow(exponent);

    // Atmospheric scattering
    const horizonBand = smoothstep(0.0, 0.15, h).mul(smoothstep(0.4, 0.15, h));

    // 🎨 PALETTE: Audio-Reactive Atmosphere Glow
    // The atmosphere pulses gently to the low frequency (kick)
    const audioGlowPulse = uAudioLow.mul(0.3).add(1.0);
    const reactiveAtmosphereIntensity = uAtmosphereIntensity.mul(audioGlowPulse);
    const atmosphereGlow = horizonBand.mul(reactiveAtmosphereIntensity);

    // Gradient Mix
    const midColor = mix(uHorizonColor, uSkyBottomColor, smoothstep(0.0, 0.3, heightFactor));
    const skyColor = mix(midColor, uSkyTopColor, smoothstep(0.2, 1.0, heightFactor));

    // 🎨 PALETTE: Color Shift (Neon/Magic) on High Energy
    // Shift sky colors towards neon magenta/cyan on high hats / cymbals
    const colorCyan = color(0x00FFFF);
    const colorMagenta = color(0xFF00FF);

    // Mix magic color based on height: lower is magenta, higher is cyan
    const magicMix = mix(colorMagenta, colorCyan, heightFactor);

    // Apply shift based on high frequency energy
    const colorShiftFactor = smoothstep(0.3, 1.0, uAudioHigh).pow(float(1.5)).mul(0.4);
    const reactiveSkyColor = mix(skyColor, magicMix, colorShiftFactor);

    const baseColor = mix(reactiveSkyColor, uHorizonColor, atmosphereGlow);

    // Apply Darkness (Darkness Event Logic)
    // When uSkyDarkness approaches 1.0, the whole sky fades to black
    const finalColor = baseColor.mul(float(1.0).sub(uSkyDarkness));

    // Moon Dance: blend in note colour at night (SkyUniforms.intensity = 0 during day)
    const skyWithNote = mix(finalColor, skyNoteColorNode, SkyUniforms.intensity);

    const skyMat = new MeshBasicNodeMaterial();
    skyMat.colorNode = skyWithNote;
    skyMat.side = THREE.BackSide;

    const sky = new THREE.Mesh(skyGeo, skyMat);
    return sky;
}

import * as THREE from 'three';
import { vec4, attribute, float, mix, color, vec3, smoothstep, sin, positionLocal, cos, Fn, instanceIndex, storage, uniform, If, length, floor } from 'three/tsl';
import { PointsNodeMaterial, StorageBufferAttribute } from 'three/webgpu';
import { isCIorHeadless } from '../core/config.ts';

// WGSL-compatible modulo: x - y * floor(x / y)
// Note: Converts inputs to float first since WGSL floor() only works on floats
const modFloat = (x: any, y: any) => {
    const xf = float(x);
    const yf = float(y);
    return xf.sub(yf.mul(xf.div(yf).floor()));
};
import { uTime, uAudioHigh, uAudioLow } from './index.ts';

const TRAIL_SIZE = 2000; // Increased buffer size for richer trails

// Exporting interface for better type safety if needed elsewhere
export interface SparkleTrailUserData {
    head: number;
    isSparkleTrail: boolean;
    bufferSize: number;
    computeNode: any;
    uSpawnPos: any;
    uSpawnVel: any;
    uSpawnCount: any;
    uSpawnIndex: any;
    uDeltaTime: any;
    uCurrentTime: any;
}

function ensureUVAttribute(geometry: THREE.BufferGeometry) {
    if (!geometry.attributes.uv && geometry.attributes.position) {
        const count = geometry.attributes.position.count;
        const uvs = new Float32Array(count * 2);
        geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
    }
}

export function createSparkleTrail(): THREE.Points {
    const geo = new THREE.BufferGeometry();
    const positions = new Float32Array(TRAIL_SIZE * 3);
    const states = new Float32Array(TRAIL_SIZE * 4); // x: birthTime, y: lifeSpan, z: spawnSpeed, w: randomOffset
    const randOffsets = new Float32Array(TRAIL_SIZE * 3); // random position offset for juice

    // Fill with initial data to avoid empty buffer issues
    for (let i = 0; i < TRAIL_SIZE; i++) {
        states[i * 4] = -1000; // birthTime
        states[i * 4 + 1] = 0; // lifeSpan
        states[i * 4 + 2] = 0; // spawnSpeed
        states[i * 4 + 3] = Math.random(); // random scalar

        randOffsets[i * 3] = (Math.random() - 0.5) * 0.6;
        randOffsets[i * 3 + 1] = 0.1 + Math.random() * 0.4;
        randOffsets[i * 3 + 2] = (Math.random() - 0.5) * 0.6;
    }

    // Use Storage Buffers for Compute Shaders
    const positionBuffer = new StorageBufferAttribute(positions, 3);
    const stateBuffer = new StorageBufferAttribute(states, 4);
    const offsetBuffer = new StorageBufferAttribute(randOffsets, 3);

    geo.setAttribute('position', positionBuffer);
    geo.setAttribute('state', stateBuffer);
    ensureUVAttribute(geo);

    // Material
    const mat = new PointsNodeMaterial({
        size: 0.5,
        transparent: true,
        depthWrite: false,
        blending: THREE.AdditiveBlending
    });

    const state = attribute('state', 'vec4');
    const birthTime = state.x;
    const lifeSpan = state.y;
    const spawnSpeed = state.z;

    const age = uTime.sub(birthTime);
    // Add small epsilon to avoid divide by zero, though lifeSpan should be > 0 when active
    const lifeProgress = age.div(lifeSpan.add(0.001)); // 0.0 to 1.0

    // --- TSL PHYSICS (Juice) ---

    // Speed Factor (0.0 at walking, 1.0 at sprint/dash)
    // Helps modulate effects based on how fast player was moving when particle spawned
    // PALETTE: Lowered threshold to 0.5 so even slow walking generates sparkles
    const speedFactor = smoothstep(0.5, 15.0, spawnSpeed);

    // 1. Drift Upwards (Magic Dust rises)
    // Faster movement = Higher drift
    const driftUp = vec3(0.0, age.mul(1.5).add(age.mul(speedFactor).mul(1.0)), 0.0);

    // 2. Swirl Effect (Spiral out as they rise)
    const swirlFreq = float(5.0).add(speedFactor.mul(5.0)); // Faster swirl when running
    const swirlAmp = age.mul(0.2).add(age.mul(speedFactor).mul(0.3)); // Wider swirl when running

    const swirl = vec3(
        sin(age.mul(swirlFreq)).mul(swirlAmp),
        float(0.0),
        cos(age.mul(swirlFreq)).mul(swirlAmp)
    );

    // Apply displacement to the base position
    mat.positionNode = positionLocal.add(driftUp).add(swirl);

    // --- VISUALS ---

    // Opacity: Fade in quickly, fade out smoothly
    const fadeIn = smoothstep(0.0, 0.1, lifeProgress);
    const fadeOut = float(1.0).sub(smoothstep(0.4, 1.0, lifeProgress));
    const opacity = fadeIn.mul(fadeOut);

    // Audio Reactivity: Pulse size with High Frequencies (Hi-hats) AND Low (Kick)
    // Adding Kick (uAudioLow) gives it that "heartbeat" feel
    const audioScale = float(1.0).add(uAudioHigh.mul(2.0)).add(uAudioLow.mul(0.5));

    // Size: Shrink over time, scale by Audio, scale by Speed
    // PALETTE: Smaller base size when walking slow to avoid clutter
    const baseSize = float(0.2).add(speedFactor.mul(0.5));
    const sizeNode = baseSize.mul(float(1.0).sub(lifeProgress)).mul(audioScale);
    (mat as { sizeNode?: unknown }).sizeNode = sizeNode;

    // Color: Cycle Gold -> Pink -> Cyan based on age
    // PALETTE: Tuned colors for maximum candy vibe
    const colorGold = color(0xFFD700);
    const colorPink = color(0xFF69B4);
    const colorCyan = color(0x00FFFF);
    const colorHot = color(0xFF00AA); // Magenta (Hot Pink) for high speed

    // Mix 1: Gold -> Pink (First half)
    const mix1 = mix(colorGold, colorPink, smoothstep(0.0, 0.5, lifeProgress));
    // Mix 2: Result -> Cyan (Second half)
    const coolMix = mix(mix1, colorCyan, smoothstep(0.5, 1.0, lifeProgress));

    // Final Color: Mix Cool -> Hot based on Speed
    // If sprinting, shift towards fiery/energetic colors
    const finalColor = mix(coolMix, colorHot, speedFactor.mul(0.8)); // Increased mix strength to 0.8

    // Twinkle: High frequency sine flicker to simulate glitter
    const randomFlickerOffset = state.w.mul(100.0);
    const twinkle = sin(age.mul(30.0).add(randomFlickerOffset)).mul(0.5).add(0.5);

    // Emission Boost
    const intensity = float(3.0).add(speedFactor.mul(2.0));
    mat.colorNode = finalColor.mul(twinkle.add(0.5)).mul(intensity);
    // Hide particles that are dead
    mat.opacityNode = opacity.mul(smoothstep(0.0, 0.01, lifeSpan));

    const points = new THREE.Points(geo, mat);
    points.frustumCulled = false;

    // COMPUTE SHADER LOGIC
    const uSpawnPos = uniform(new THREE.Vector3());
    const uSpawnVel = uniform(new THREE.Vector3());
    const uSpawnCount = uniform(0);
    const uSpawnIndex = uniform(-1);
    const uCurrentTime = uniform(0);

    const updateTrailCompute = (Fn as any)((): void => {
        const index = instanceIndex;

        const posNode = storage(positionBuffer, 'vec3', positionBuffer.count).element(index);
        const stateNode = storage(stateBuffer, 'vec4', stateBuffer.count).element(index);
        const offsetNode = storage(offsetBuffer, 'vec3', offsetBuffer.count).element(index);

        const spawnCount = uSpawnCount.toVar();
        const spawnIdx = uSpawnIndex.toVar();

        // Handle wrapping logic manually in TSL since modulo operations can be tricky
        // If the current particle index is within the range [spawnIdx, spawnIdx + spawnCount) (handling wrap around)

        // Is this index one of the ones being spawned this frame?
        const diff = index.sub(spawnIdx);
        // Add TRAIL_SIZE to handle negative diffs, then modulo
        const wrappedDiff = modFloat(diff.add(float(TRAIL_SIZE)), float(TRAIL_SIZE));

        If(wrappedDiff.lessThan(spawnCount), () => {
            // Spawn new particle!
            posNode.assign(uSpawnPos.add(offsetNode));

            // Random life between 0.8 and 1.4
            // Since we can't easily do random in compute cleanly per-frame per-instance without state,
            // we use the pre-generated random w component to vary the life
            const randomLife = float(0.8).add(stateNode.w.mul(0.6));

            // Speed is length of uSpawnVel
            const speed = length(uSpawnVel);

            // update state: x=birthTime, y=lifeSpan, z=spawnSpeed, w=keep existing random
            stateNode.assign(vec4(uCurrentTime, randomLife, speed, stateNode.w));
        });
    });

    const computeNode = (updateTrailCompute() as unknown as { compute: (n: number) => unknown }).compute(TRAIL_SIZE);

    // Custom data for JS update loop
    points.userData = {
        head: 0,
        isSparkleTrail: true,
        bufferSize: TRAIL_SIZE,
        computeNode: computeNode,
        uSpawnPos: uSpawnPos,
        uSpawnVel: uSpawnVel,
        uSpawnCount: uSpawnCount,
        uSpawnIndex: uSpawnIndex,
        uCurrentTime: uCurrentTime,
        uDeltaTime: null
    } as SparkleTrailUserData;

    return points;
}

export function updateSparkleTrail(trail: THREE.Points, playerPos: THREE.Vector3, playerVel: THREE.Vector3, time: number, renderer: THREE.WebGLRenderer | any) {
    if (!trail || !trail.userData.isSparkleTrail) return;

    const userData = trail.userData as SparkleTrailUserData;

    // Always update current time for the compute shader to run properly over living particles
    userData.uCurrentTime.value = time;

    const speed = playerVel.length();

    let spawnCount = 0;
    if (speed >= 0.5) {
        // Scale particle count by speed
        // More particles for better trails, but ensure at least 1 when moving slow
        spawnCount = Math.max(1, Math.min(Math.floor(speed / 1.5), 20));

        // Update uniforms for the compute shader to spawn new particles
        userData.uSpawnPos.value.copy(playerPos);
        userData.uSpawnVel.value.copy(playerVel);
        userData.uSpawnCount.value = spawnCount;
        userData.uSpawnIndex.value = userData.head;

        // Advance head
        userData.head = (userData.head + spawnCount) % userData.bufferSize;
    } else {
        // No spawning this frame
        userData.uSpawnCount.value = 0;
    }

    // Execute the compute shader
    if (renderer && renderer.compute && spawnCount > 0) {
        if (!isCIorHeadless()) { renderer.compute(userData.computeNode); }
    }
}

// src/foliage/stars.ts

import * as THREE from 'three';
import type UniformNode from 'three/src/nodes/core/UniformNode.js';
import { color, float, vec3, vec4, time, positionLocal, attribute, uniform, mix, sin, cos, pow, step, smoothstep } from 'three/tsl';
import { PointsNodeMaterial } from 'three/webgpu';
import { uAudioLow, uAudioHigh } from './index.ts';

// Global uniforms
// Removed uStarPulse to fix unison pulsing bug and use direct audio reactivity
export const uStarColor = uniform(color(0xFFFFFF));
export const uStarOpacity = uniform(0.0); // Controls visibility (Day/Night)

export function createStars(count: number = 1500): THREE.Points {
    const geo = new THREE.BufferGeometry();
    const positions = new Float32Array(count * 3);
    const sizes = new Float32Array(count);
    const offsets = new Float32Array(count);
    const colors = new Float32Array(count * 3);
    const normals = new Float32Array(count * 3);

    const radius = 400;

    for (let i = 0; i < count; i++) {
        // Random point on sphere
        const u = Math.random();
        const v = Math.random();
        const theta = 2 * Math.PI * u;
        const phi = Math.acos(2 * v - 1);

        const r = radius * (0.9 + Math.random() * 0.2);
        const x = r * Math.sin(phi) * Math.cos(theta);
        const y = r * Math.sin(phi) * Math.sin(theta);
        const z = r * Math.cos(phi);

        positions[i * 3] = x;
        positions[i * 3 + 1] = Math.abs(y);
        positions[i * 3 + 2] = z;

        normals[i * 3] = 0; normals[i * 3 + 1] = 1; normals[i * 3 + 2] = 0;

        sizes[i] = Math.random() * 2.5 + 0.3;
        offsets[i] = Math.random() * 100;

        // Base natural star colors (White/Blueish/Yellowish)
        const colorType = Math.random();
        if (colorType < 0.7) {
            colors[i * 3] = 1.0; colors[i * 3 + 1] = 1.0; colors[i * 3 + 2] = 1.0;
        } else if (colorType < 0.85) {
            colors[i * 3] = 0.8; colors[i * 3 + 1] = 0.9; colors[i * 3 + 2] = 1.0;
        } else {
            colors[i * 3] = 1.0; colors[i * 3 + 1] = 0.9; colors[i * 3 + 2] = 0.7;
        }
    }

    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geo.setAttribute('normal', new THREE.BufferAttribute(normals, 3));
    geo.setAttribute('size', new THREE.BufferAttribute(sizes, 1));
    geo.setAttribute('offset', new THREE.BufferAttribute(offsets, 1));
    geo.setAttribute('starColor', new THREE.BufferAttribute(colors, 3));

    const mat = new PointsNodeMaterial({
        size: 1.5,
        transparent: true,
        opacity: 0.0, // Driven by uStarOpacity in TSL
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        fog: false
    });

    // We assign TSL nodes to properties of PointsNodeMaterial
    const aOffset = attribute('offset', 'float');
    const aSize = attribute('size', 'float');
    const aStarColor = attribute('starColor', 'vec3');

    // --- PALETTE: Juicy Star Logic ---

    // 1. Twinkle (High Frequency / Hi-Hats)
    // Driven by Time + Offset + AudioHigh
    // This creates the "glitter" effect
    // PALETTE: Vary speed per star for natural feel
    const speedVar = float(3.0).add(sin(aOffset.mul(0.5)).mul(1.5)); // 1.5 to 4.5 speed
    const twinkleSpeed = time.mul(speedVar).add(aOffset);
    const rawTwinkle = sin(twinkleSpeed).mul(0.5).add(0.5); // 0..1 sine wave

    // Add rare gold sparkles (moved up to use for twinkle intensity)
    const isGold = step(0.9, sin(aOffset.mul(2.0))); // Occasional gold

    // Sharpen the twinkle (Power curve) -> Spikes of brightness
    // 🎨 PALETTE: Make the twinkle curve more extreme for non-gold stars, and extra flashy for gold
    const twinklePower = mix(float(5.0), float(3.0), isGold); // Gold has wider twinkle
    const sharpTwinkle = pow(rawTwinkle, twinklePower);

    // Scale twinkle intensity by Audio Highs (Cymbals/Melody)
    // 🎨 PALETTE: Non-linear audio reactivity - highs make them pop exponentially
    const audioTwinkle = uAudioHigh.pow(float(2.0)).mul(5.0);
    // Base twinkle + Audio Twinkle. Gold stars get an extra boost.
    const baseTwinkleMul = mix(float(0.5), float(1.5), isGold);
    const activeTwinkle = sharpTwinkle.mul(baseTwinkleMul.add(audioTwinkle));

    // 2. Randomized Pulse (Low Frequency / Kick)
    // Replaced wave with purely random phase based on offset to break unison
    // This creates a "twinkle chaos" instead of a sweeping wave
    const pulseSpeed = float(0.5).add(sin(aOffset).mul(0.2)); // Slight speed variation
    const pulsePhase = time.mul(pulseSpeed).add(aOffset); // Offset is large (0-100)
    const randomPulse = sin(pulsePhase).mul(0.5).add(0.5); // 0..1

    // Apply Kick energy to the random pulse
    // 🎨 PALETTE: Stars pulse individually to the beat, organically reacting to the kick
    const kickImpact = smoothstep(0.2, 0.8, uAudioLow).pow(float(1.5));
    const kickPulse = kickImpact.mul(randomPulse).mul(3.0);

    // 🎨 PALETTE: Randomize "Twinkle" offset so they don't pulse in unison to the music
    // Even high-hat twinks look better broken up
    const offsetHigh = sin(aOffset.mul(10.0)).mul(0.5).add(0.5); // 0..1
    const randomizedAudioHigh = uAudioHigh.mul(mix(float(0.5), float(1.5), offsetHigh));
    const audioHighTwinkle = randomizedAudioHigh.pow(float(2.0)).mul(5.0);
    const audioHighPulse = sharpTwinkle.mul(baseTwinkleMul.add(audioHighTwinkle));

    // Total Intensity = Base + Twinkle + Pulse
    const intensity = float(0.4).add(audioHighPulse).add(kickPulse);

    // 3. Color Shift (Neon/Magic)
    // Shift towards Cyan/Magenta/Gold on high energy
    const baseColorVec = vec3(aStarColor.x, aStarColor.y, aStarColor.z);

    // Magic colors
    const colorCyan = vec3(0.0, 1.0, 1.0);
    const colorMagenta = vec3(1.0, 0.0, 1.0);
    const colorGold = vec3(1.0, 0.8, 0.0);

    // Pick target color based on star's unique offset
    // Sine of offset gives -1..1. Map to mix factors.
    const selector = sin(aOffset);
    // Mix Cyan vs Magenta/Gold
    // If selector > 0 use Cyan/Magenta, else Gold
    const magicMix = mix(colorCyan, colorMagenta, selector.mul(0.5).add(0.5));
    const targetColor = mix(magicMix, colorGold, isGold);

    // Mix based on audio high (energy)
    // Stronger highs = More neon color
    // 🎨 PALETTE: More vibrant color shift during high energy
    const colorShiftFactor = smoothstep(0.1, 0.9, uAudioHigh).pow(float(1.2));
    const finalRGB = mix(baseColorVec, targetColor, colorShiftFactor);

    // 🎨 PALETTE: Make opacity breathe with the music organically
    // Use the star's unique offset to create a phase offset for the pulse so they don't pulse in perfect unison
    // We add a subtle glow pulse when high energy drops, mixing with base visibility
    const opacityPhase = time.mul(2.0).add(aOffset);
    const pulseOffset = sin(opacityPhase).mul(0.5).add(0.5); // 0 to 1
    const audioOpacity = uStarOpacity.mul(float(1.0).add(smoothstep(0.0, 1.0, uAudioLow).mul(pulseOffset).mul(0.5)));

    // Final Output
    mat.colorNode = vec4(finalRGB, audioOpacity).mul(color(mat.color));
    (mat as { sizeNode?: unknown }).sizeNode = aSize.mul(intensity.max(0.4)); // Keep min size 0.4 so they don't disappear

    // 4. Star Warp/Dance (Existing logic preserved but tuned)
    const pos = positionLocal;
    // Warp outwards on Kick (Low)
    const warpFactor = uAudioLow.mul(10.0);
    const warpedPos = pos.add(pos.normalize().mul(warpFactor));

    // Gentle Rotation
    const angle = time.mul(0.015); // Slightly slower rotation
    const rotatedX = warpedPos.x.mul(cos(angle)).sub(warpedPos.z.mul(sin(angle)));
    const rotatedZ = warpedPos.x.mul(sin(angle)).add(warpedPos.z.mul(cos(angle)));

    mat.positionNode = vec3(rotatedX, warpedPos.y, rotatedZ);

    const stars = new THREE.Points(geo, mat);
    stars.userData.isStars = true;

    return stars;
}

