// src/foliage/water.ts

import * as THREE from 'three';
import {
    color, float, vec3, vec2, Fn, uniform, sin, cos, time, positionLocal,
    uv, normalize, smoothstep, mix, abs, max, positionWorld,
    mx_noise_float, normalLocal
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { CandyPresets, uAudioLow, uAudioHigh, createRimLight, createJuicyRimLight } from './index.ts';

export const uWaveHeight = uniform(1.0); // Base wave height scaler

/**
 * Creates an audio-reactive Waveform Water surface.
 * Uses TSL for vertex displacement and "Cute Clay" shading (SeaJelly preset).
 *
 * @param {number} width
 * @param {number} depth
 * @returns {THREE.Mesh}
 */
export function createWaveformWater(width: number = 400, depth: number = 400): THREE.Mesh {
    // High segment count for smooth vertex displacement
    const geometry = new THREE.PlaneGeometry(width, depth, 128, 128);
    geometry.rotateX(-Math.PI / 2); // Lay flat

    // --- TSL Displacement Logic ---
    const waterDisplacement = Fn(([pos]: any) => {
        // Base rolling wave (Time dependent)
        const bigWave = sin(pos.x.mul(0.05).add(time.mul(0.5))).mul(2.0);

        // Bass-driven pulses (Low Freq)
        // Modulate amplitude with uAudioLow
        const bassWave = cos(pos.z.mul(0.1).sub(time.mul(1.0)))
            .mul(uAudioLow.mul(3.0).add(0.5)); // Base 0.5 + Audio impact

        // Treble ripples (High Freq)
        const rippleX = sin(pos.x.mul(0.5).add(time.mul(2.0)));
        const rippleZ = cos(pos.z.mul(0.4).sub(time.mul(2.5)));
        const trebleRipples = rippleX.mul(rippleZ)
            .mul(uAudioHigh.mul(1.5));

        // Combine
        return bigWave.add(bassWave).add(trebleRipples).mul(uWaveHeight);
    });

    // --- Material Setup ---
    // Use SeaJelly preset for the "Cute Clay" water look
    // Wobbly, wet, very translucent, high transmission
    const material = CandyPresets.SeaJelly(0x44AAFF, {
        roughness: 0.1,
        metalness: 0.1,
        transmission: 0.9,
        ior: 1.33,
        thickness: 2.0,
        animateMoisture: true // Adds scrolling noise to roughness
    });

    // Inject Vertex Displacement
    const pos = positionLocal;
    const displacement = waterDisplacement(pos);

    // Update Y position
    const newPos = vec3(pos.x, pos.y.add(displacement), pos.z);
    material.positionNode = newPos;

    // Recalculate Normals for correct lighting on waves
    // TSL doesn't auto-recalc normals from positionNode yet in all cases,
    // but MeshStandardNodeMaterial handles it reasonably well if the displacement is smooth.
    // Ideally we would compute analytical normals here, but for "Cute Clay", soft is fine.

    // Add Foam/Highlight at peaks
    // We can change color based on height
    const heightFactor = smoothstep(2.0, 5.0, displacement); // 0 at low, 1 at high peaks
    const foamColor = color(0xFFFFFF);
    const waterColor = material.colorNode; // The base color from SeaJelly

    // Mix foam into base color
    material.colorNode = mix(waterColor ?? color(0x00FFFF), foamColor, heightFactor.mul(0.5));

    // --- PALETTE Polish: Melody Sparkles & Rim Light ---

    // 1. Sparkles (Audio Reactive Glitter)
    // Create a high-frequency noise field that moves
    const sparkleScale = positionWorld.mul(0.5);
    const sparkleTime = time.mul(0.5);
    const noiseVal = mx_noise_float(sparkleScale.add(sparkleTime));

    // Threshold to create distinct "glitter" points (top 20% of noise)
    const sparkleMask = smoothstep(0.8, 1.0, noiseVal);

    // Drive intensity with High Frequency audio (Melody/Hi-Hats)
    // "Bioluminescent" look: Cyan/White mix
    const sparkleColor = vec3(0.6, 1.0, 1.0);
    // 🎨 PALETTE: Make sparkles pop aggressively on high energy
    const sparkleIntensity = uAudioHigh.pow(float(1.5)).mul(sparkleMask).mul(5.0); // Boosted brightness

    // 2. Rim Light (Edge Definition)
    // Helps the water separate from the dark background/sky
    // Note: We use normalLocal because displacement modifies the surface,
    // but for simple rim lighting on a plane, the varying view angle provides enough falloff.
    // For better results, we'd need perturbed normals, but this adds a subtle "moonlight sheen".
    // 🎨 PALETTE: Upgraded to Juicy Rim Light for a more magical, audio-reactive edge glow
    const rim = createJuicyRimLight(color(0x00FFFF), float(1.2), float(2.5), normalLocal);

    // 3. Beat Glow (Bass)
    // 🎨 PALETTE: Stronger, more colorful beat glow
    const beatGlow = uAudioLow.pow(float(1.2)).mul(0.5);
    const baseEmissive = vec3(0.0, 0.5, 0.8).mul(beatGlow);

    // Combine all emissive sources
    material.emissiveNode = baseEmissive.add(sparkleColor.mul(sparkleIntensity)).add(rim);

    const mesh = new THREE.Mesh(geometry, material);
    mesh.userData.type = 'water';
    mesh.receiveShadow = true;

    // Optimization: Disable frustum culling if the water covers the whole world
    // or set a large bounding sphere.
    mesh.frustumCulled = false;

    return mesh;
}

import * as THREE from 'three';
import { safeRemoveAndDispose } from '../utils/dispose-utils.ts';
import {
    color, float, vec3, vec2, attribute, positionLocal,
    sin, cos, mix, smoothstep, uniform, If, time, uv,
    varying, dot, normalize, normalLocal, step, Fn, positionWorld,
    instanceIndex, storage, mx_noise_float, normalWorld, floor, add
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';

// WGSL-compatible modulo: x - y * floor(x / y)
// Note: Converts inputs to float first since WGSL floor() only works on floats
const modFloat = (x: any, y: any) => {
    const xf = float(x);
    const yf = float(y);
    return xf.sub(yf.mul(xf.div(yf).floor()));
};
import { CONFIG, getCIAdjustedCount } from '../core/config.ts';
import { getBiomeUniforms, type BiomeId } from '../systems/biome-uniforms.ts';
import { fastInvSqrt } from '../utils/wasm-loader.ts';
import { foliageGroup } from '../world/state.ts';
import {
    sharedGeometries, foliageMaterials, uTime,
    uAudioLow, uAudioHigh, CandyPresets, registerReactiveMaterial, createJuicyRimLight,
    applyStandardDeformation
} from './index.ts';

const MAX_WATERFALLS = getCIAdjustedCount(50, 0.2, 10); // Reduced from 200 for WebGPU uniform buffer limits
const SPLASHES_PER_WATERFALL = 8;
const MAX_SPLASHES = MAX_WATERFALLS * SPLASHES_PER_WATERFALL;

// Scratch variables
const _scratchMatrix = new THREE.Matrix4();
const _scratchPos = new THREE.Vector3();
const _scratchScale = new THREE.Vector3();
const _scratchQuat = new THREE.Quaternion();
const _scratchColor = new THREE.Color();

export class WaterfallBatcher {
    private static instance: WaterfallBatcher;
    private initialized = false;
    private count = 0;

    public mesh: THREE.InstancedMesh | null = null;
    public splashMesh: THREE.InstancedMesh | null = null;

    // ID Maps
    private idToIndex: Map<string, number> = new Map();
    private indexToId: string[] = [];

    // Splash Attributes
    private splashOrigin: THREE.InstancedBufferAttribute | null = null;
    private splashVelocity: THREE.InstancedBufferAttribute | null = null; // Stores random velocity params

    private constructor() {}

    static getInstance(): WaterfallBatcher {
        if (!WaterfallBatcher.instance) {
            WaterfallBatcher.instance = new WaterfallBatcher();
        }
        return WaterfallBatcher.instance;
    }

    init() {
        if (this.initialized) return;

        // 1. Waterfall Column Mesh
        // Base Geometry: Top Radius 1, Bottom Radius 1.5, Height 1
        const colGeo = new THREE.CylinderGeometry(1, 1.5, 1, 32, 16, true);

        // Material (SeaJelly Variant)
        // We use TSL so we can just use the material logic directly or via preset
        // Note: CandyPresets.SeaJelly returns a MeshPhysicalNodeMaterial usually.
        // We need to modify it for InstancedMesh if needed.
        // But since we are using standard TSL nodes, it should work fine.
        const colMat = CandyPresets.SeaJelly(0x00FFFF, {
            transmission: 0.9,
            thickness: 1.2,
            roughness: 0.1,
            ior: 1.33,
            subsurfaceStrength: 0.5,
            subsurfaceColor: 0xCCFFFF,
            animateMoisture: true,
            thicknessDistortion: 0.6,
            side: THREE.DoubleSide
        });

        // Custom TSL Logic for Column (Juicy Upgrade)
        // 1. Flow & Foam (Accelerated by Highs)
        const speed = float(2.0).add(uAudioHigh.mul(2.0));
        const flowUV = uv().add(vec2(0, uTime.mul(speed).negate()));

        const ripple1 = sin(flowUV.y.mul(15.0).add(flowUV.x.mul(5.0))).mul(0.5).add(0.5);
        const ripple2 = sin(flowUV.y.mul(25.0).sub(flowUV.x.mul(10.0)).add(uTime)).mul(0.5).add(0.5);
        const foamNoise = ripple1.mul(ripple2);

        // 2. Bottom Foam Gradient (Pivot is center Y=0, Height=1, so range -0.5 to 0.5)
        // Strong foam at bottom (-0.5) fading out by -0.2
        const yPos = positionLocal.y;
        const bottomGradient = float(1.0).sub(smoothstep(-0.5, -0.2, yPos));
        const totalFoam = foamNoise.add(bottomGradient.mul(2.0)).min(1.0);

        // 3. Jelly Wobble (Vertex Displacement)
        // Wobble based on position and time
        const wobbleTime = uTime.mul(3.0);
        const noiseInput = positionLocal.mul(2.0).add(vec3(0, wobbleTime, 0));
        const wobbleX = mx_noise_float(noiseInput);
        const wobbleZ = mx_noise_float(noiseInput.add(vec3(10.0)));

        // Audio Impact on wobble (Bass Kick makes it bulge)
        const wobbleAmp = float(0.1).add(uAudioLow.mul(0.2));
        const displacement = vec3(wobbleX, float(0.0), wobbleZ).mul(wobbleAmp);

        // Apply Displacement
        const displacedPos = positionLocal.add(displacement);

        // Apply Player Interaction
        colMat.positionNode = applyStandardDeformation(displacedPos); // 🎨 PALETTE: Replaced applyPlayerInteraction with applyStandardDeformation for wind-shear + player interaction

        // 4. Color & Emission
        const uPulseIntensity = uAudioLow.mul(2.0); // Amplified bass
        const uBaseEmission = float(0.2);

        // Gradient: Cyan (Top) to Purple (Bottom)
        // UV.y 0 (Bottom) -> 1 (Top)
        const gradient = mix(color(0xFF00FF), color(0x00FFFF), uv().y);

        // Mix gradient into base color (Base is Cyan from SeaJelly)
        colMat.colorNode = mix(colMat.colorNode ?? color(0x00FFFF), gradient, 0.5);

        // Juicy Rim Light (The "Palette" Polish)
        // Makes the edges glow with energy
        const rimColor = color(0x00FFFF);
        const rim = createJuicyRimLight(rimColor, float(2.0), float(3.0), normalWorld);

        // Total Emission = Gradient + Foam + Rim + Pulse
        // Foam makes it white/bright
        const foamEmission = color(0xFFFFFF).mul(totalFoam.mul(uBaseEmission.add(uPulseIntensity)));

        // Combine: Base Emission + Foam + Rim
        // Music Impact: crystalline nebula shimmer/noteColor adds bioluminescent tint to waterfall
        const nebulaUniforms = getBiomeUniforms('crystalline_nebula');
        const musicTint = nebulaUniforms.noteColor.mul(nebulaUniforms.shimmer).mul(0.3);
        colMat.emissiveNode = gradient.mul(uBaseEmission).add(foamEmission).add(rim).add(musicTint);

        // Roughness: Foam makes it rougher
        const currentRoughness = colMat.roughnessNode ?? float(colMat.roughness);
        colMat.roughnessNode = add(currentRoughness, totalFoam.mul(0.5));

        this.mesh = new THREE.InstancedMesh(colGeo, colMat, MAX_WATERFALLS);
        this.mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.mesh.count = 0;
        this.mesh.frustumCulled = false; // Always update (audio reactivity)

        // 2. Splash Mesh
        const splashGeo = new THREE.SphereGeometry(1, 8, 8); // Base radius 1, scaled down later
        const splashMat = CandyPresets.Sugar(0xFFFFFF, { roughness: 0.4, bumpStrength: 0.2 });

        // Splash TSL Animation
        this.splashOrigin = new THREE.InstancedBufferAttribute(new Float32Array(MAX_SPLASHES * 3), 3);
        this.splashVelocity = new THREE.InstancedBufferAttribute(new Float32Array(MAX_SPLASHES * 3), 3); // x, y, z (randoms)

        splashGeo.setAttribute('aOrigin', this.splashOrigin);
        splashGeo.setAttribute('aVelocity', this.splashVelocity);

        // Logic
        const aOrigin = attribute('aOrigin', 'vec3');
        const aVelocity = attribute('aVelocity', 'vec3'); // Random seed/velocity

        // Time Loop
        // Each splash has a random phase based on its index or random attr
        // We use aVelocity.y as a seed for phase
        const phase = aVelocity.y.mul(10.0);
        const lifeTime = float(1.0); // 1 second loop
        const t = modFloat(uTime.add(phase), lifeTime); // 0 to 1

        // Physics
        // Pos = Origin + Vel * t - 0.5 * g * t^2
        // Initial Velocity (Boosted by Bass)
        const vUp = float(5.0).add(uAudioLow.mul(10.0));

        // Random horizontal spread
        const vX = aVelocity.x.mul(2.0);
        const vZ = aVelocity.z.mul(2.0);

        const pos = vec3(
            aOrigin.x.add(vX.mul(t)),
            aOrigin.y.add(vUp.mul(t).sub(float(20.0).mul(t).mul(t).mul(0.5))), // Gravity = 20
            aOrigin.z.add(vZ.mul(t))
        );

        // Scale down at end of life (Sine curve 0->1->0)
        const scaleLife = sin(t.mul(Math.PI));

        // TSL Scale Logic (Juicy Upgrade)
        // Scale up with Melody (uAudioHigh) for explosive sparkles
        const audioScale = float(1.0).add(uAudioHigh.mul(2.0));

        // Base splash size (0.5) * Life * Audio
        const splashSize = float(0.5).mul(scaleLife).mul(audioScale);

        // Apply position: Center (pos) + Local Vertex (positionLocal * Size)
        splashMat.positionNode = pos.add(positionLocal.mul(splashSize));

        // Color Logic (Juicy Upgrade)
        // Mix from White (Foam) to Cyan/Magenta based on life or randomness
        // Use aVelocity.y (phase seed) to randomize color
        const randomColor = mix(color(0x00FFFF), color(0xFF00FF), sin(aVelocity.y.mul(10.0)).mul(0.5).add(0.5));

        // Flash white at birth (t < 0.2)
        const flash = float(1.0).sub(smoothstep(0.0, 0.2, t));
        const finalColor = mix(randomColor, color(0xFFFFFF), flash);

        splashMat.colorNode = finalColor;

        // Add emission for glow (Bioluminescent splash)
        splashMat.emissiveNode = finalColor.mul(0.5).add(flash.mul(0.5));

        this.splashMesh = new THREE.InstancedMesh(splashGeo, splashMat, MAX_SPLASHES);
        this.splashMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this.splashMesh.count = 0;
        this.splashMesh.frustumCulled = false;

        if (foliageGroup) {
            foliageGroup.add(this.mesh);
            foliageGroup.add(this.splashMesh);
        }

        this.initialized = true;
        console.log('WaterfallBatcher initialized');
    }

    dispose() {
        if (!this.initialized) return;

        [this.mesh, this.splashMesh].forEach(mesh => {
            if (!mesh) return;
            safeRemoveAndDispose(foliageGroup, mesh);
        });

        this.initialized = false;
        this.count = 0;
        this.idToIndex.clear();
    }

    /**
     * Adds a waterfall instance.
     * @param id Unique identifier (e.g. parent UUID)
     * @param position Top center position (StartPos)
     * @param height Height of waterfall
     * @param width Width (diameter) of waterfall
     */
    add(id: string, position: THREE.Vector3, height: number, width: number) {
        if (!this.initialized) this.init();
        if (this.idToIndex.has(id)) return;
        if (this.count >= MAX_WATERFALLS) return;

        const index = this.count;
        this.count++;

        this.idToIndex.set(id, index);
        this.indexToId[index] = id;

        // 1. Setup Column
        // Cylinder Base: R=1, H=1.
        // Scale: X=width, Y=height, Z=width
        // Position: position.y - height/2 (Mid Point)
        _scratchScale.set(width, height, width);
        _scratchQuat.identity();
        _scratchPos.copy(position);
        _scratchPos.y -= height * 0.5;

        _scratchMatrix.compose(_scratchPos, _scratchQuat, _scratchScale);
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMatrix.toArray(this.mesh!.instanceMatrix.array, (index) * 16);
        this.mesh!.instanceMatrix.needsUpdate = true;

        // 2. Setup Splashes (8 per waterfall)
        const startSplash = index * SPLASHES_PER_WATERFALL;
        const bottomY = position.y - height;

        for (let i = 0; i < SPLASHES_PER_WATERFALL; i++) {
            const si = startSplash + i;

            // Origin: Randomly distributed at bottom
            const offsetX = (Math.random() - 0.5) * width;
            const offsetZ = (Math.random() - 0.5) * width;

            this.splashOrigin!.setXYZ(si,
                position.x + offsetX,
                bottomY,
                position.z + offsetZ
            );

            // Velocity Params: X/Z direction, Y seed
            this.splashVelocity!.setXYZ(si,
                (Math.random() - 0.5), // X dir
                Math.random(),         // Y seed (phase)
                (Math.random() - 0.5)  // Z dir
            );

            // Initialize matrix to identity (needed for rendering, even if positionNode overrides)
            _scratchMatrix.identity();
            // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        _scratchMatrix.toArray(this.splashMesh!.instanceMatrix.array, (si) * 16);
        }

        this.splashOrigin!.needsUpdate = true;
        this.splashVelocity!.needsUpdate = true;

        // Update counts
        this.mesh!.count = this.count;
        this.splashMesh!.count = this.count * SPLASHES_PER_WATERFALL;
        this.splashMesh!.instanceMatrix.needsUpdate = true;
    }

    remove(id: string) {
        if (!this.initialized || !this.idToIndex.has(id)) return;

        const indexToRemove = this.idToIndex.get(id)!;
        const lastIndex = this.count - 1;
        const lastId = this.indexToId[lastIndex];

        if (indexToRemove !== lastIndex) {
            // Swap Column
            // ⚡ OPTIMIZATION: Fast memory copy bypassing object instantiation and setMatrixAt overhead
            const matrixArray = this.mesh!.instanceMatrix.array as Float32Array;
            const destOffset = indexToRemove * 16;
            const srcOffset = lastIndex * 16;
            matrixArray.copyWithin(destOffset, srcOffset, srcOffset + 16);

            // Swap Splashes (Block of 8)
            const srcStart = lastIndex * SPLASHES_PER_WATERFALL;
            const destStart = indexToRemove * SPLASHES_PER_WATERFALL;

            this.splashOrigin!.array.copyWithin(destStart * 3, srcStart * 3, srcStart * 3 + SPLASHES_PER_WATERFALL * 3);
            this.splashVelocity!.array.copyWithin(destStart * 3, srcStart * 3, srcStart * 3 + SPLASHES_PER_WATERFALL * 3);

            // Update Map
            this.idToIndex.set(lastId, indexToRemove);
            this.indexToId[indexToRemove] = lastId;
        }

        this.idToIndex.delete(id);
        this.count--;

        this.mesh!.count = this.count;
        this.splashMesh!.count = this.count * SPLASHES_PER_WATERFALL;

        this.mesh!.instanceMatrix.needsUpdate = true;
        this.splashOrigin!.needsUpdate = true;
        this.splashVelocity!.needsUpdate = true;
    }

    /**
     * Updates an instance (e.g. for pulsing thickness).
     * @param id
     * @param thicknessScale Scaling factor for thickness (Z-axis flattening or uniform scale)
     */
    updateInstance(id: string, thicknessScale: number) {
        if (!this.initialized || !this.idToIndex.has(id)) return;

        // Note: We need to know the original scale to modify it.
        // But we didn't store it.
        // We can get it from matrix.
        const index = this.idToIndex.get(id)!;

        // ⚡ OPTIMIZATION: Bypassed .getMatrixAt() and .decompose() overhead.
        // Scale is encoded in the lengths of the column vectors of the 4x4 matrix.
        // We need to change the Z scale. We can modify the 3rd column directly.
        const matrixArray = this.mesh!.instanceMatrix.array as Float32Array;
        const offset = index * 16;

        // Assuming X and Z were equal initially (circular).
        // Current X scale is the magnitude of the 1st column.
        // ⚡ OPTIMIZATION: Use squared scale magnitudes and fast inverse square root to avoid Math.sqrt() in hot loops.
        const m00 = matrixArray[offset + 0], m01 = matrixArray[offset + 1], m02 = matrixArray[offset + 2];
        const scaleXSq = m00 * m00 + m01 * m01 + m02 * m02;

        // Current Z scale is the magnitude of the 3rd column.
        const m20 = matrixArray[offset + 8], m21 = matrixArray[offset + 9], m22 = matrixArray[offset + 10];
        const currentScaleZSq = m20 * m20 + m21 * m21 + m22 * m22;

        // Apply scaling factor to the 3rd column
        if (currentScaleZSq > 0.00000001 && scaleXSq > 0.00000001) {
            // targetZ = X * thicknessScale
            // We want ratio = targetZ / currentZ = (X * thicknessScale) / currentZ
            // ratio = sqrt(scaleXSq) * thicknessScale / sqrt(currentScaleZSq)
            const targetZSq = scaleXSq * thicknessScale * thicknessScale;

            // ⚡ OPTIMIZATION: Bypassed Math.sqrt overhead completely by using a squared distance tolerance check for early-out.
            // Since waterfall thicknesses rarely change dramatically frame-to-frame, this avoids the Math.sqrt in 99% of frames.
            const diffSq = targetZSq - currentScaleZSq;
            if (diffSq > 0.0001 || diffSq < -0.0001) {
                const ratio = Math.sqrt(targetZSq / currentScaleZSq);
                matrixArray[offset + 8] *= ratio;
                matrixArray[offset + 9] *= ratio;
                matrixArray[offset + 10] *= ratio;
            }
        }

        this.mesh!.instanceMatrix.needsUpdate = true;
    }
}

export const waterfallBatcher = WaterfallBatcher.getInstance();

import * as THREE from 'three';
import type UniformNode from 'three/src/nodes/core/UniformNode.js';
import {
    color,
    time,
    uv,
    float,
    vec2,
    mix,
    sin,
    cos,
    step, // ← added cos + step
    uniform,
    normalWorld,
    Fn,
    storage,
    instanceIndex,
    vec3,
    positionLocal,
    max,
    length,
    min,
    abs,
    add,
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { createStorageBufferAttribute } from '../utils/storage-buffer-attribute.ts';
import {
    registerReactiveMaterial,
    attachReactivity,
    CandyPresets,
    uAudioHigh,
    uTime,
    createJuicyRimLight,
} from './index.ts';
/**
 * Creates a bioluminescent waterfall connecting two points.
 * @param {THREE.Vector3} startPos - Top position
 * @param {THREE.Vector3} endPos - Bottom position
 * @param {number} width - Width of the waterfall
 */
export function createWaterfall(
    startPos: THREE.Vector3,
    endPos: THREE.Vector3,
    width: number = 5.0
): THREE.Group {
    const group = new THREE.Group();
    group.name = 'Waterfall';
    const height = startPos.y - endPos.y;
    const midY = (startPos.y + endPos.y) / 2;

    // Cylinder (flat open ends)
    const geo = new THREE.CylinderGeometry(width, width * 1.5, height, 32, 16, true);

    // === SeaJelly material with bioluminescent flow ===
    const mat = CandyPresets.SeaJelly(0x00ffff, {
        transmission: 0.9,
        thickness: 1.2,
        roughness: 0.1,
        ior: 1.33,
        subsurfaceStrength: 0.5,
        subsurfaceColor: 0xccffff,
        animateMoisture: true,
        thicknessDistortion: 0.6,
        side: THREE.DoubleSide,
    });

    const speed = 2.0;
    const flowUV = uv().add(vec2(0, time.mul(speed).negate()));

    const ripple1 = sin(flowUV.y.mul(15.0).add(flowUV.x.mul(5.0)))
        .mul(0.5)
        .add(0.5);
    const ripple2 = sin(flowUV.y.mul(25.0).sub(flowUV.x.mul(10.0)).add(time))
        .mul(0.5)
        .add(0.5);
    const foam = ripple1.mul(ripple2);

    const uPulseIntensity = uniform(0.0);
    const uBaseEmission = float(0.2);

    const gradient = mix(color(0xff00ff), color(0x00ffff), uv().y);
    mat.colorNode = mix(mat.colorNode ?? color(0x00FFFF), gradient, 0.5);

    const rim = createJuicyRimLight(gradient, float(2.0), float(3.0), normalWorld);

    const emission = gradient.mul(uBaseEmission.add(uPulseIntensity)).mul(foam.add(0.2));
    const highIntensity = uAudioHigh.pow(float(1.5)).mul(1.5);
    mat.emissiveNode = emission.add(rim).add(gradient.mul(highIntensity));

    const currentRoughness = mat.roughnessNode ?? float(mat.roughness);
    mat.roughnessNode = add(currentRoughness, foam.mul(0.5));

    const mesh = new THREE.Mesh(geo, mat);
    mesh.position.set(startPos.x, midY, startPos.z);
    mesh.userData.uPulseIntensity = uPulseIntensity;

    registerReactiveMaterial(mat);
    group.add(mesh);

    // === GPU Compute Splashes (Phase 4) ===
    const splashCount = 128;
    const positionBuffer = createStorageBufferAttribute(splashCount, 3);
    const velocityBuffer = createStorageBufferAttribute(splashCount, 3);

    // Initial particle positions/velocities
    for (let i = 0; i < splashCount; i++) {
        const x = startPos.x + (Math.random() - 0.5) * width;
        const y = endPos.y;
        const z = startPos.z + (Math.random() - 0.5) * width;
        positionBuffer.setXYZ(i, x, y, z);
        velocityBuffer.setXYZ(
            i,
            (Math.random() - 0.5) * 2.0,
            Math.random() * 8.0 + 2.0,
            (Math.random() - 0.5) * 2.0
        );
    }

    const positionStorage = storage(positionBuffer, 'vec3', splashCount);
    const velocityStorage = storage(velocityBuffer, 'vec3', splashCount);
    const baseFloorY = float(endPos.y);

    const computeSplashes = (Fn as any)((): void => {
        const p = positionStorage.element(instanceIndex);
        const v = velocityStorage.element(instanceIndex);

        const dt = float(0.016);
        const gravity = vec3(0.0, -20.0, 0.0);

        // Audio-reactive impulse (only on strong beats)
        const audioImpulse = max(float(0.0), uPulseIntensity.sub(0.5)).mul(25.0);
        const randSeed = p.x.mul(10.0).add(p.z.mul(10.0)).add(time.mul(100.0));
        const impulseVar = sin(randSeed).mul(0.5).add(0.5);

        const appliedImpulse = vec3(
            sin(randSeed.mul(2.0)).mul(audioImpulse).mul(0.5),
            audioImpulse.mul(impulseVar),
            cos(randSeed.mul(3.0)).mul(audioImpulse).mul(0.5)
        );

        const acceleration = gravity.add(appliedImpulse);
        const newVel = v.add(acceleration.mul(dt));
        const nextPos = p.add(newVel.mul(dt));

        // Floor collision + respawn
        const bouncedVelY = abs(newVel.y).mul(0.4);
        const isTooSlow = step(bouncedVelY, 1.0);

        const respawnX = float(startPos.x).add(sin(randSeed).mul(width * 0.5));
        const respawnZ = float(startPos.z).add(cos(randSeed).mul(width * 0.5));
        const respawnVel = vec3(
            sin(randSeed.mul(5.0)).mul(1.0),
            abs(cos(randSeed.mul(4.0)))
                .mul(8.0)
                .add(2.0),
            cos(randSeed.mul(6.0)).mul(1.0)
        );

        const bouncePos = vec3(nextPos.x, baseFloorY, nextPos.z);
        const bounceVel = vec3(newVel.x, bouncedVelY, newVel.z);
        const respawnPos = vec3(respawnX, baseFloorY, respawnZ);

        const chosenPos = mix(bouncePos, respawnPos, isTooSlow);
        const chosenVel = mix(bounceVel, respawnVel, isTooSlow);

        const isBelowFloor = step(nextPos.y, baseFloorY);
        const finalPos = mix(nextPos, chosenPos, isBelowFloor);
        const finalVel = mix(newVel, chosenVel, isBelowFloor);

        p.assign(finalPos);
        v.assign(finalVel);
    });

    const computeNode = (computeSplashes() as unknown as { compute: (n: number) => unknown }).compute(splashCount);

    // Splash visuals (Sugar preset + GPU positioning)
    const splashGeo = new THREE.SphereGeometry(width * 0.15, 8, 8);
    const splashMat = CandyPresets.Sugar(0xccffff, {
        roughness: 0.35,
        metalness: 0.0,
    });
    splashMat.transparent = true;
    splashMat.opacity = 0.9;

    const instancePos = positionStorage.element(instanceIndex);
    const instanceVel = velocityStorage.element(instanceIndex);
    const speedScale = length(instanceVel);
    const stretchFactor = min(speedScale.mul(0.12).add(1.0), 2.5);
    const squashFactor = float(1.0).div(stretchFactor.sqrt());
    const scaledVertex = positionLocal.mul(vec3(squashFactor, stretchFactor, squashFactor));

    splashMat.positionNode = instancePos.add(scaledVertex);

    const splashGlowColor = mix(color(0x00ffff), color(0xff00ff), uPulseIntensity);
    splashMat.emissiveNode = splashGlowColor.mul(uPulseIntensity.add(0.4));

    const splashInstanced = new THREE.InstancedMesh(splashGeo, splashMat, splashCount);
    splashInstanced.frustumCulled = false;
    splashInstanced.castShadow = true;
    splashInstanced.receiveShadow = true;
    splashInstanced.userData.computeNode = computeNode;

    group.add(splashInstanced);

    // === Reactivity & tagging ===
    group.userData.type = 'waterfall';
    group.userData.computeNode = computeNode;

    attachReactivity(group, { minLight: 0.0, maxLight: 1.0, type: 'flora' });

    (group as any).reactToNote = (note: any, colorVal: any, velocity: number) => {
        // Strong visual pulse + splash explosion on high-velocity notes
        const targetPulse = 0.6 + velocity * 2.2;
        (mesh.userData.uPulseIntensity as UniformNode<number>).value = Math.max(
            (mesh.userData.uPulseIntensity as UniformNode<number>).value,
            targetPulse
        );
    };

    (group as any).onAnimate = (delta: number, time: number) => {
        // Only decay the pulse (physics is now fully GPU-driven)
        const pulse = mesh.userData.uPulseIntensity as UniformNode<number>;
        if (pulse.value > 0.01) {
            pulse.value = THREE.MathUtils.lerp(pulse.value, 0.0, delta * 6.0);
        }
    };

    return group;
}

import * as THREE from 'three';
import { DataTexture, Vector2, Vector4, RGBAFormat, HalfFloatType, NearestFilter, RepeatWrapping } from 'three';
import { textureStore, instanceIndex, Fn, float, vec4, vec2, ivec2, mx_noise_float, sin, cos, max, min, uniform, floor } from 'three/tsl';

// WGSL-compatible modulo: x - y * floor(x / y)
// Note: Converts inputs to float first since WGSL floor() only works on floats
const modFloat = (x: any, y: any) => {
    const xf = float(x);
    const yf = float(y);
    return xf.sub(yf.mul(xf.div(yf).floor()));
};
import { StorageTexture } from 'three/webgpu';

// Wind texture configuration
export const WIND_TEXTURE_SIZE = 256; // 256x256 wind field
const WIND_TEXTURE_CHANNELS = 4; // RGBA - we use RG for wind X/Z, B for gust, A unused

/**
 * Configuration interface for wind behavior
 */
export interface WindConfig {
    /** Base wind speed multiplier */
    baseSpeed: number;
    /** Turbulence scale - smaller values = larger wind patterns */
    turbulenceScale: number;
    /** Gust frequency - how often gusts occur */
    gustFrequency: number;
    /** Gust strength multiplier */
    gustStrength: number;
    /** Wind direction as angle in radians (0 = +X, PI/2 = +Z) */
    directionAngle: number;
    /** Direction variation - how much wind direction changes over time */
    directionVariation: number;
}

/**
 * Default wind configuration
 */
export const DEFAULT_WIND_CONFIG: WindConfig = {
    baseSpeed: 1.0,
    turbulenceScale: 0.02,
    gustFrequency: 0.3,
    gustStrength: 0.5,
    directionAngle: 0,
    directionVariation: 0.3
};

/**
 * WindComputeSystem - WebGPU Compute Shader Edition
 * 
 * Replaces CPU noise generation with a WebGPU Compute Shader that writes
 * to a StorageTexture. This removes the JS CPU bottleneck and updates
 * the entire 256x256 texture every frame.
 */
export class WindComputeSystem {
    private windTexture: THREE.Texture;
    private timeAccumulator: number = 0;
    private config: WindConfig;

    // Cached direction vectors
    private baseDirection: Vector2 = new Vector2(1, 0);
    private currentDirection: Vector2 = new Vector2(1, 0);

    // Performance tracking
    private frameCount: number = 0;
    private lastUpdateTime: number = 0;
    private averageUpdateTime: number = 0;

    // Uniforms for TSL shaders
    private windParams: Vector4 = new Vector4(1, 0, 0, 1); // x: speed, y: unused, z: unused, w: time

    // Compute specific uniforms
    private uTime = uniform(0);
    private uWindSpeed = uniform(1.0);
    private uWindDirection = uniform(vec2(1, 0));
    private uGustFreq = uniform(0.3);
    private uGustStrength = uniform(0.5);

    private _computeNode: any;

    constructor(config: Partial<WindConfig> = {}) {
        this.config = { ...DEFAULT_WIND_CONFIG, ...config };

        // Create the storage texture for compute shader
        const storageTexture = new StorageTexture(WIND_TEXTURE_SIZE, WIND_TEXTURE_SIZE);
        storageTexture.type = HalfFloatType;
        storageTexture.minFilter = NearestFilter;
        storageTexture.magFilter = NearestFilter;
        storageTexture.wrapS = RepeatWrapping;
        storageTexture.wrapT = RepeatWrapping;
        this.windTexture = storageTexture;

        // Initialize base direction from config
        this.baseDirection.set(
            Math.cos(this.config.directionAngle),
            Math.sin(this.config.directionAngle)
        );
        this.currentDirection.copy(this.baseDirection);
        if (this.uWindDirection.value) {
            const windDir = this.uWindDirection.value as unknown as THREE.Vector3;
            windDir.set(this.currentDirection.x, this.currentDirection.y, 0);
        }

        this.initComputeNode();
    }

    /**
     * Initializes the TSL Compute Node for wind generation
     */
    private initComputeNode() {
        const size = float(WIND_TEXTURE_SIZE);

        const computeWind = (Fn as any)((): void => {
            const index = float(instanceIndex);
            const sizeInt = WIND_TEXTURE_SIZE;

            // Using int math for 2D coord to avoid precision issues
            const x = modFloat(index, float(sizeInt));
            const y = index.div(sizeInt).floor();

            // Normalized coordinates
            const nx = x.div(size);
            const ny = y.div(size);

            // Time offset
            const timeOffset = this.uTime.mul(0.1);

            // Multi-octave noise for natural wind patterns
            const scale1 = float(1.0);
            const scale2 = float(2.0);
            const scale3 = float(4.0);

            // Primary wind flow (large-scale)
            const ax1 = nx.mul(scale1).add(timeOffset.mul(0.1));
            const ay1 = ny.mul(scale1).add(timeOffset.mul(0.05));
            const flowX1 = mx_noise_float(vec2(ax1, ay1));
            const flowY1 = mx_noise_float(vec2(ax1.add(100.0), ay1.add(100.0)));

            // Secondary turbulence (medium-scale)
            const ax2 = nx.mul(scale2).sub(timeOffset.mul(0.2));
            const ay2 = ny.mul(scale2).add(timeOffset.mul(0.15));
            const flowX2 = mx_noise_float(vec2(ax2, ay2)).mul(0.5);
            const flowY2 = mx_noise_float(vec2(ax2.add(100.0), ay2.add(100.0))).mul(0.5);

            // Fine detail (small-scale)
            const ax3 = nx.mul(scale3).add(timeOffset.mul(0.3));
            const ay3 = ny.mul(scale3).sub(timeOffset.mul(0.1));
            const flowX3 = mx_noise_float(vec2(ax3, ay3)).mul(0.25);
            const flowY3 = mx_noise_float(vec2(ax3.add(100.0), ay3.add(100.0))).mul(0.25);

            // Combine octaves
            let windX = flowX1.add(flowX2).add(flowX3).div(1.75);
            let windZ = flowY1.add(flowY2).add(flowY3).div(1.75);

            // Apply base wind direction influence
            const dirInfluence = float(0.7); // How much base direction affects the wind
            windX = windX.mul(float(1.0).sub(dirInfluence)).add(this.uWindDirection.x.mul(dirInfluence));
            windZ = windZ.mul(float(1.0).sub(dirInfluence)).add(this.uWindDirection.y.mul(dirInfluence));

            // Calculate gust intensity
            const gustPhase = nx.mul(2.0).add(ny.mul(1.5)).add(timeOffset.mul(this.uGustFreq));
            const gust = sin(gustPhase).add(1.0).mul(0.5); // 0 to 1
            const gustSharp = gust.pow(3.0).mul(this.uGustStrength);

            // Apply gust to wind strength
            const gustMultiplier = float(1.0).add(gustSharp);
            windX = windX.mul(gustMultiplier).mul(this.uWindSpeed);
            windZ = windZ.mul(gustMultiplier).mul(this.uWindSpeed);

            // Store in texture (RGBA)
            const outColor = vec4(windX, windZ, gustSharp, 0.0);

            // Convert x, y back to int coordinates for textureStore
            const ivec2_coords = ivec2(x, y);
            textureStore(this.windTexture as StorageTexture, ivec2_coords, outColor);
        });

        // Dispatch one thread per pixel
        this._computeNode = (computeWind() as unknown as { compute: (n: number) => unknown }).compute(WIND_TEXTURE_SIZE * WIND_TEXTURE_SIZE);
    }

    /**
     * Get the compute node to be dispatched by the renderer
     */
    getComputeNode() {
        return this._computeNode;
    }

    /**
     * Get the wind texture for use in TSL shaders
     */
    getWindTexture(): THREE.Texture {
        return this.windTexture;
    }

    /**
     * Get shader uniforms for binding to materials
     */
    getUniforms(): { windTexture: THREE.Texture; windParams: Vector4; windSpeed: number } {
        return {
            windTexture: this.windTexture,
            windParams: this.windParams,
            windSpeed: this.config.baseSpeed
        };
    }

    /**
     * Update the wind simulation parameters
     * Call this once per frame with deltaTime in seconds
     */
    update(deltaTime: number): void {
        const startTime = performance.now();

        this.timeAccumulator += deltaTime;
        this.frameCount++;

        // Update wind direction with slow variation
        const directionOscillation = Math.sin(this.timeAccumulator * 0.1) * this.config.directionVariation;
        this.currentDirection.set(
            Math.cos(this.config.directionAngle + directionOscillation),
            Math.sin(this.config.directionAngle + directionOscillation)
        );

        // Update uniforms for the compute shader
        this.uTime.value = this.timeAccumulator;
        this.uWindSpeed.value = this.config.baseSpeed;
        const windDir = this.uWindDirection.value as unknown as THREE.Vector3;
        windDir.set(this.currentDirection.x, this.currentDirection.y, 0);
        this.uGustFreq.value = this.config.gustFrequency;
        this.uGustStrength.value = this.config.gustStrength;

        // Update wind params uniform for materials
        this.windParams.set(
            this.config.baseSpeed,
            this.timeAccumulator,
            this.currentDirection.x,
            this.currentDirection.y
        );

        // Track performance
        const updateTime = performance.now() - startTime;
        this.averageUpdateTime = this.averageUpdateTime * 0.95 + updateTime * 0.05;
        this.lastUpdateTime = updateTime;
    }

    /**
     * Get wind vector at a specific world position and time
     * Use this for CPU-side calculations (e.g., particle effects)
     * NOTE: Since texture is on GPU, we emulate the base noise on CPU for immediate reads
     * if required by physics. This provides a fast approximation.
     */
    getWindAt(x: number, z: number, time: number = this.timeAccumulator): Vector2 {
        // Approximate the wind direction and speed for CPU side effects
        // Full noise is calculated on GPU, so we use a simplified version here
        const gustPhase = (x * 0.01) * 2 + (z * 0.01) * 1.5 + (time * 0.1) * this.config.gustFrequency;
        const gust = (Math.sin(gustPhase) + 1) * 0.5; // 0 to 1
        const gustSharp = Math.pow(gust, 3) * this.config.gustStrength;

        const gustMultiplier = 1.0 + gustSharp;

        return new Vector2(
            this.currentDirection.x * gustMultiplier * this.config.baseSpeed,
            this.currentDirection.y * gustMultiplier * this.config.baseSpeed
        );
    }

    /**
     * Get current wind direction as a normalized vector
     */
    getCurrentDirection(): Vector2 {
        return this.currentDirection.clone();
    }

    /**
     * Get current wind speed
     */
    getWindSpeed(): number {
        return this.config.baseSpeed;
    }

    /**
     * Set wind speed dynamically
     */
    setWindSpeed(speed: number): void {
        this.config.baseSpeed = Math.max(0, speed);
    }

    /**
     * Set wind direction dynamically
     */
    setWindDirection(angle: number): void {
        this.config.directionAngle = angle;
        this.baseDirection.set(Math.cos(angle), Math.sin(angle));
    }

    /**
     * Get performance statistics
     */
    getPerformanceStats(): {
        averageUpdateTime: number;
        lastUpdateTime: number;
        frameCount: number;
        textureSize: number;
        textureMemoryMB: number;
    } {
        return {
            averageUpdateTime: this.averageUpdateTime,
            lastUpdateTime: this.lastUpdateTime,
            frameCount: this.frameCount,
            textureSize: WIND_TEXTURE_SIZE,
            textureMemoryMB: (WIND_TEXTURE_SIZE * WIND_TEXTURE_SIZE * WIND_TEXTURE_CHANNELS * 4) / (1024 * 1024)
        };
    }

    /**
     * Dispose of resources
     */
    dispose(): void {
        this.windTexture.dispose();
    }
}

/**
 * Global singleton instance of the wind compute system
 * Import this for shared wind calculations across the application
 */
export const windComputeSystem = new WindComputeSystem();

/**
 * Creates a TSL-ready wind texture reference
 * Use this function in TSL material definitions to get the wind texture node
 * 
 * Example:
 * ```typescript
 * import { texture, uv } from 'three/tsl';
 * import { getWindTextureNode } from './wind-compute.ts';
 * 
 * const windValue = getWindTextureNode(uv().mul(0.1).add(time * 0.01));
 * ```
 */
export function getWindTextureData(): {
    texture: THREE.Texture;
    params: Vector4;
    sampleScale: number;
} {
    return {
        texture: windComputeSystem.getWindTexture(),
        params: windComputeSystem.getUniforms().windParams,
        sampleScale: 0.1 // Scale factor for UV mapping to world space
    };
}

/**
 * Performance profiler for wind system
 * Tracks FPS before/after optimization
 */
export class WindPerformanceProfiler {
    private frameTimings: number[] = [];
    private lastFrameTime: number = 0;
    private isProfiling: boolean = false;
    private profileStartTime: number = 0;

    startProfiling(): void {
        this.frameTimings = [];
        this.isProfiling = true;
        this.profileStartTime = performance.now();
        this.lastFrameTime = this.profileStartTime;
    }

    recordFrame(): void {
        if (!this.isProfiling) return;

        const now = performance.now();
        const delta = now - this.lastFrameTime;
        this.frameTimings.push(delta);
        this.lastFrameTime = now;
    }

    stopProfiling(): {
        averageFPS: number;
        minFPS: number;
        maxFPS: number;
        totalFrames: number;
        duration: number;
    } {
        this.isProfiling = false;

        if (this.frameTimings.length === 0) {
            return { averageFPS: 0, minFPS: 0, maxFPS: 0, totalFrames: 0, duration: 0 };
        }

        const duration = performance.now() - this.profileStartTime;

        // ⚡ OPTIMIZATION: Eliminate .map() and .reduce() arrays to prevent GC spikes in hot paths
        let sum = 0;
        let minFPS = Infinity;
        let maxFPS = -Infinity;
        const count = this.frameTimings.length;

        for (let i = 0; i < count; i++) {
            const dt = this.frameTimings[i];
            const fps = 1000 / Math.max(dt, 0.1);
            sum += fps;
            if (fps < minFPS) minFPS = fps;
            if (fps > maxFPS) maxFPS = fps;
        }

        return {
            averageFPS: sum / count,
            minFPS: minFPS,
            maxFPS: maxFPS,
            totalFrames: count,
            duration
        };
    }

    /**
     * Log profiling results to console with formatting
     */
    logResults(label: string): void {
        const results = this.stopProfiling();
        console.log(`[WindProfiler] ${label}:`, {
            avgFPS: results.averageFPS.toFixed(1),
            minFPS: results.minFPS.toFixed(1),
            maxFPS: results.maxFPS.toFixed(1),
            frames: results.totalFrames,
            duration: `${(results.duration / 1000).toFixed(1)}s`
        });
    }
}

// Global profiler instance
export const windProfiler = new WindPerformanceProfiler();

import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { ShaderNodeObject, Node } from 'three/tsl';
import {
    time, positionLocal, sin, cos, positionWorld, color, vec3, mix, float, smoothstep
} from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { CONFIG } from '../core/config.ts';
import { BiomeUniforms, uCircadianPhase, circadianNightGlowMult } from '../systems/biome-uniforms.ts';
import { discoverySystem } from '../systems/discovery.ts';
import { makeInteractive } from '../utils/interaction-utils.ts';
import { attachReactivity } from './foliage-reactivity.ts';
import { spawnImpact } from './impacts.ts';
import { CandyPresets, uAudioHigh, uAudioLow, uTime, createJuicyRimLight, getCachedProceduralMaterial, applyPlayerInteraction, calculateWindSway, calculatePlayerPush } from './material-core.ts';
import { uTwilight } from './sky.ts';

export interface WisteriaClusterOptions {
    scale?: number;
    color?: number;
}

let _cachedMergedGeo: THREE.BufferGeometry | null = null;
let _cachedHitGeo: THREE.BufferGeometry | null = null;

/**
 * Creates a cluster of hanging musical vines (Wisteria) that respond to high frequencies.
 */
export function createWisteriaCluster(options: WisteriaClusterOptions = {}) {
    const { scale = 1.0, color: baseHexColor = 0x9B6A9C } = options; // Soft purple clay by default
    const group = new THREE.Group();

    // Aesthetic: "Cute Clay"
    // Use the generic Clay preset and apply audio-reactive TSL deformation.
    // Cache the material to prevent WebGPU compilation freezes
    const material = getCachedProceduralMaterial(`wisteria_cluster_${baseHexColor}`, baseHexColor, () => {
        const mat = CandyPresets.Clay(baseHexColor, {
            roughness: 0.9,
            bumpStrength: 0.1
        });

        // --- TSL Audio-Reactive Sway ---
        // Make it sway organically based on world position and uTime.
        // High frequency audio (uAudioHigh) acts as an impulse/energy multiplier.
        const baseSwayFreq = float(2.0);
        // ADSR Style scale + emissive reaction to high frequency
        const audioEnergy = uAudioHigh.mul(1.5).add(0.5); // Music Impact: hang amp + glow

        // Offset based on positionWorld so multiple clusters aren't perfectly synced
        const swayPhase = positionWorld.x.mul(0.5).add(positionWorld.z.mul(0.3));

        // Calculate sway amount. The top of the vine (y > 0) shouldn't move as much as the bottom (y < 0).
        // Assuming the geometry is created such that it hangs down from y=0.
        // If geometry goes from y=0 to y=-length, then hangFactor goes from 0 to 1.
        // Let's use positionLocal.y.
        // Assume cluster is about 4 units long, so positionLocal.y goes from 0 down to -4.
        const hangFactor = positionLocal.y.div(-4.0).clamp(0.0, 1.0);

        // Music Impact: hang sway × audioEnergy
        const hangSway = vec3(
            sin(uTime.mul(baseSwayFreq).add(swayPhase)).mul(0.5),
            float(0.0),
            cos(uTime.mul(baseSwayFreq.mul(0.8)).add(swayPhase)).mul(0.5)
        ).mul(audioEnergy).mul(hangFactor);

        // Apply night droop (phase→0 at night)
        const circadianDroop = vec3(0, float(-0.4).mul(float(1.0).sub(uCircadianPhase)).mul(hangFactor), 0);

        // Proxy height for wind and player interactions since Wisteria hangs downward (negative Y)
        const proxyPos = vec3(positionLocal.x, hangFactor.mul(4.0), positionLocal.z);

        const wind = calculateWindSway(proxyPos); // proxy: tip bends more
        const playerPush = calculatePlayerPush(proxyPos);

        const pos = positionLocal.add(hangSway).add(circadianDroop).add(wind);
        mat.positionNode = pos.add(playerPush);

        // Glow Effect based on audio
        const baseColorNode = color(baseHexColor);
        const glowColor = color(0xFF66FF); // Neon pink glow
        // Emissive boost driven by uAudioHigh, fading in smoothly — nocturnal gate
        const nightGlow = circadianNightGlowMult();
        mat.emissiveNode = glowColor.mul(BiomeUniforms.arpeggioGrove.noteColor).mul(uAudioHigh.mul(0.8)).mul(nightGlow);

        // 🎨 PALETTE: Juicy Rim Light for volumetric glow
        const rimLight = createJuicyRimLight(color(0xFFFFFF), float(1.5), float(3.0), null);
        mat.emissiveNode = (mat.emissiveNode as ShaderNodeObject<Node>).add(rimLight.mul(nightGlow));

        // 🎨 PALETTE: Twilight Glow for wisteria
        const glowPhaseOffset = positionWorld.x.mul(0.5).add(positionWorld.z.mul(0.3));
        const idlePulse = sin(time.mul(float(CONFIG.glow.glowPulseFrequency)).add(glowPhaseOffset)).mul(float(CONFIG.glow.glowPulseAmplitude)).add(1.0).mul(float(0.5)).mul(uAudioLow.mul(0.3).add(0.7));
        const targetGlowColor = color(CONFIG.glow.glowColorMap['wisteria']);
        const twilightGlowTint = targetGlowColor
            .mul(uTwilight)
            .mul(float(CONFIG.glow.glowIntensityMax))
            .mul(float(0.3).add(idlePulse));

        // ADSR Glow based on tracker channel (sky_moon base color, reactive)
        // Here we just use audioEnergy for a simple ADSR-like reaction
        const baseAdsrGlow = targetGlowColor.mul(audioEnergy).mul(0.3).mul(nightGlow);

        mat.emissiveNode = (mat.emissiveNode as ShaderNodeObject<Node>).add(twilightGlowTint).add(baseAdsrGlow);

        return mat;
    }) as MeshStandardNodeMaterial;

    // --- Geometry Construction ---
    // We create a central hanging stem and several rounded clusters ("grapes" / "petals") hanging off it.

    // Use cached geometry to avoid VRAM leak
    if (!_cachedMergedGeo) {
        const geometries: THREE.BufferGeometry[] = [];

        const vineGeo = new THREE.CylinderGeometry(0.1, 0.05, 4, 8);
        // Shift geometry so the top is at y=0, bottom is at y=-4
        vineGeo.translate(0, -2, 0);
        geometries.push(vineGeo);

        // Add rounded "clusters" (flowers) along the vine
        const clusterGeoBase = new THREE.SphereGeometry(0.4, 16, 16);

        for (let i = 0; i < 5; i++) {
            const clusterGeo = clusterGeoBase.clone();

            // Position them down the vine
            const yPos = -0.5 - (i * 0.7);
            // Offset slightly in x/z for organic look
            const xOffset = (Math.random() - 0.5) * 0.5;
            const zOffset = (Math.random() - 0.5) * 0.5;

            // Vary size
            const s = 1.0 - (i * 0.1); // smaller towards the bottom

            clusterGeo.scale(s, s, s);
            clusterGeo.translate(xOffset, yPos, zOffset);

            geometries.push(clusterGeo);
        }

        _cachedMergedGeo = mergeGeometries(geometries);

        // Clean up temporary geometries to prevent memory leaks
        vineGeo.dispose();
        clusterGeoBase.dispose();
        for (let i = 1; i < geometries.length; i++) {
            geometries[i].dispose();
        }
    }

    const mainMesh = new THREE.Mesh(_cachedMergedGeo, material);
    group.add(mainMesh);

    // Add an invisible hitbox for interaction since the visual mesh hangs down
    if (!_cachedHitGeo) {
        _cachedHitGeo = new THREE.CylinderGeometry(1.0, 1.0, 4);
    }
    const hitMat = new THREE.MeshBasicMaterial({ visible: false });
    const hitMesh = new THREE.Mesh(_cachedHitGeo, hitMat);
    hitMesh.position.y = -2;
    group.add(hitMesh);

    group.scale.setScalar(scale);

    group.userData.type = 'wisteria_cluster';
    group.userData.interactionText = "Commune";

    // Interaction
    group.userData.onInteract = () => {
        // Just trigger a discovery if not already discovered, and visual feedback
        discoverySystem.discover('wisteria_cluster', 'Wisteria Cluster', '🍇');

        // Visual feedback (Particles)
        spawnImpact(group.position, 'spore', baseHexColor);

        // Audio variation
        if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
            (window as any).AudioSystem.playSound('impact', { position: group.position, pitch: Math.random() * 0.2 + 0.9 });
        }

        // Visual pop
        group.scale.setScalar(scale * 1.2);
        setTimeout(() => {
            group.scale.setScalar(scale);
        }, 150);
    };

    const interactive = makeInteractive(group);

    // Ensure reactivity flag is attached
    return attachReactivity(interactive);
}

import * as THREE from 'three';
import { color, float, vec3, uv, positionLocal, mx_noise_float, mix, smoothstep, normalLocal, sin } from 'three/tsl';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uChromaticIntensity } from '../foliage/chromatic.ts';
import { spawnImpact } from '../foliage/impacts.ts';
import { uAudioLow, uAudioHigh, createJuicyRimLight, uTime } from '../foliage/material-core.ts';
import { unlockSystem } from '../systems/unlocks.ts';
import { showToast } from '../utils/toast.ts';

export class ChordStrikeSystem {
    mesh: THREE.Mesh;
    active: boolean = false;
    duration: number = 0;
    maxDuration: number = 3.0; // 3 seconds beam
    radius: number = 0;
    maxRadius: number = 20.0;
    position: THREE.Vector3 = new THREE.Vector3();

    constructor() {
        // Create a massive cylinder for the beam
        const geometry = new THREE.CylinderGeometry(1, 1, 500, 32, 16, true);
        geometry.translate(0, 250, 0); // Base at 0

        // High Energy Plasma Material (TSL)
        const material = new MeshStandardNodeMaterial({
            transparent: true,
            side: THREE.DoubleSide,
            blending: THREE.AdditiveBlending,
            depthWrite: false
        });

        const vUv = uv();

        // 1. Noise-based Plasma
        const timeScale = uTime ? uTime.mul(20.0) : float(0.0);
        const noisePos = vec3(vUv.x.mul(10.0), vUv.y.mul(20.0).sub(timeScale), float(0.0));
        const plasma = mx_noise_float(noisePos).add(float(0.5));

        // 2. Audio Pulse
        const coreIntensity = uAudioLow ? uAudioLow.mul(float(1.5)).add(float(1.0)) : float(1.0);

        // 3. Color Gradient
        const colorBottom = color(0x9933FF); // Deep Purple
        const colorTop = color(0x00FFCC); // Cyan
        const baseColor = mix(colorBottom, colorTop, vUv.y);

        // 4. Edges Fade
        // Fade out horizontally at edges for softness
        const horizontalFade = sin(vUv.x.mul(Math.PI)).pow(2.0);
        // Fade out at top
        const verticalFade = float(1.0).sub(smoothstep(0.8, 1.0, vUv.y));

        const finalColor = baseColor.mul(plasma).mul(coreIntensity).mul(horizontalFade).mul(verticalFade);

        // Disable rim light in chord strike at load to prevent circular dependency resolution issues with audio variables
        material.emissiveNode = finalColor;

        // Deformation: Make it ripple
        const rippleTime = uTime ? uTime.mul(5.0) : float(0.0);
        const ripple = mx_noise_float(vec3(vUv.x.mul(5.0), vUv.y.mul(10.0), rippleTime));
        material.positionNode = positionLocal.add(normalLocal.mul(ripple.mul(float(2.0))));

        this.mesh = new THREE.Mesh(geometry, material);
        if (this.mesh) this.mesh.visible = false;
        this.mesh.frustumCulled = false;
    }

    addToScene(scene: THREE.Scene) {
        scene.add(this.mesh);
    }

    fire(playerPos: THREE.Vector3) {
        if (this.active) return; // Already firing

        // Require 3 Harmony Orbs
        if (!unlockSystem.consume('harmony_orb', 3)) {
            showToast("Need 3 Harmony Orbs! 🔮", "❌");
            return;
        }

        this.active = true;
        this.duration = this.maxDuration;
        this.radius = 0;
        this.position.copy(playerPos);

        // Slightly offset beam to not blind player entirely
        this.position.z -= 5.0;

        this.mesh.position.copy(this.position);
        if (this.mesh) this.mesh.visible = true;
        this.mesh.scale.set(0.1, 1, 0.1);

        showToast("CHORD STRIKE!! 🎶💥", "⚡");

        // Massive initial impact
        if (uChromaticIntensity) {
            uChromaticIntensity.value = 1.0;
        }
        spawnImpact(playerPos, 'explosion', 0x9933FF);
    }

    update(dt: number, scene: THREE.Scene, player: any) {
        if (!this.active) return;

        this.duration -= dt;

        if (this.duration <= 0) {
            this.active = false;
            if (this.mesh) this.mesh.visible = false;
            return;
        }

        // Expand radius quickly, then hold
        const expandSpeed = 20.0;
        if (this.radius < this.maxRadius) {
            this.radius += expandSpeed * dt;
            if (this.radius > this.maxRadius) this.radius = this.maxRadius;
        }

        // Add some jitter to the scale based on audio
        // For a more chaotic "superweapon" feel
        const jitter = (uAudioHigh as any).value * 0.5;
        this.mesh.scale.set(this.radius + jitter, 1, this.radius + jitter);

        // Screen Shake / Glitch effect while active
        if (uChromaticIntensity) {
            // Sustain trauma
            (uChromaticIntensity as any).value = Math.max((uChromaticIntensity as any).value, 0.3 + Math.random() * 0.2);
        }

        // Physics Push: The beam provides a massive updraft
        // Check if player is near the beam
        const dx = player.position.x - this.position.x;
        const dy = player.position.y - this.position.y;
        const dz = player.position.z - this.position.z;
        const distSq = dx * dx + dy * dy + dz * dz;
        if (distSq < (this.radius + 5.0) * (this.radius + 5.0)) {
            // Push player up!
            player.velocity.y += 20.0 * dt;
            player.isGrounded = false;
        }

        // Continuous impact particles at base
        if (Math.random() < 0.2) {
            spawnImpact(this.position, 'magic', 0x00FFCC);
        }
    }
}

