import * as THREE from 'three';
import { positionLocal, uv, float, sin, cos, vec3, uniform, attribute, vec4, vec2, step, mix, smoothstep, Fn } from 'three/tsl';
import { uChromaticIntensity } from '../foliage/chromatic.ts';
import { applyGlitch } from '../foliage/glitch.ts';
import { spawnImpact } from '../foliage/impacts.ts';
import {
    createClayMaterial,
    uGlitchIntensity,
    uTime,
    uAudioLow
} from '../foliage/material-core.ts';
import { unlockSystem } from '../systems/unlocks.ts';

const MAX_MINES = 50;
const _scratchMatrix = new THREE.Matrix4();
const MINE_RADIUS = 0.5;
const TRIGGER_RADIUS = 2.0;
const COOLDOWN = 1.0;

// ⚡ OPTIMIZATION: Shared scratch variables to avoid GC in animation loops
const _scratchDummy = new THREE.Object3D();

// Type Definition for Pool Object
interface Mine {
    active: boolean;
    visible: boolean;
    position: THREE.Vector3;
    rotation: THREE.Euler; // Store rotation state
    scale: number;        // Store scale state
    time: number;
}

class JitterMineSystem {
    mines: Mine[];
    cooldownTimer: number;
    trauma: number;

    // GPU resources are deferred — accessed via getters that trigger init()
    private _mesh: THREE.InstancedMesh | null = null;
    private _spawnBuffer: THREE.InstancedBufferAttribute | null = null;
    private _stateBuffer: THREE.InstancedBufferAttribute | null = null;
    private _initialized = false;

    private initialized = false;

    constructor() {
        this.mines = [];
        this.cooldownTimer = 0;
        this.trauma = 0;
        // Don't eagerly evaluate in constructor to prevent barrel file module load errors
    }

    /**
     * Idempotent initialization of all WebGPU / TSL resources.
     * This is deferred so TSL node math never runs during module load or
     * constructor execution, preventing scope-loss and mangling crashes.
     */
    init() {
        if (this.initialized) return;
        this.initialized = true;

        // Pre-allocate CPU-side mine objects (pure JS — safe at construction time)
        for (let i = 0; i < MAX_MINES; i++) {
            this.mines.push({
                active: false,
                visible: false,
                position: new THREE.Vector3(),
                rotation: new THREE.Euler(),
                scale: 0,
                time: 0
            });
        }


        const geometry = new THREE.IcosahedronGeometry(MINE_RADIUS, 0);

        // Initialize attributes
        const initialSpawns = new Float32Array(MAX_MINES * 4);
        const initialStates = new Float32Array(MAX_MINES * 4);

        for (let i = 0; i < MAX_MINES; i++) {
            initialSpawns[i * 4 + 1] = -9999.0; // Hide initially by moving down
            initialStates[i * 4] = 0.0; // inactive

            // Random rotation axis
            const rx = Math.random() - 0.5;
            const ry = Math.random() - 0.5;
            const rz = Math.random() - 0.5;
            const len = Math.sqrt(rx * rx + ry * ry + rz * rz);
            initialStates[i * 4 + 1] = rx / len;
            initialStates[i * 4 + 2] = ry / len;
            initialStates[i * 4 + 3] = rz / len;
        }

        this._spawnBuffer = new THREE.InstancedBufferAttribute(initialSpawns, 4);
        this._spawnBuffer.setUsage(THREE.DynamicDrawUsage);
        geometry.setAttribute('aSpawn', this._spawnBuffer);

        this._stateBuffer = new THREE.InstancedBufferAttribute(initialStates, 4);
        this._stateBuffer.setUsage(THREE.DynamicDrawUsage);
        geometry.setAttribute('aState', this._stateBuffer);

        // 2. Vertex Shader logic (Stateless GPU Animation)
        // By deferring the node generation to a Fn(), we avoid module-import-time undefined crashes
        // from circular dependencies inside barrel files
        const computeLogic = Fn(() => {
            const aSpawn = attribute('aSpawn', 'vec4');
            const aState = attribute('aState', 'vec4');
        // -----------------------------------------------------------------
        // TSL MATERIAL GRAPH — deferred until first actual use
        // -----------------------------------------------------------------
        const baseGlitch = applyGlitch(
            uv(),
            positionLocal,
            float(0.2).add(sin(uTime.mul(10.0)).mul(0.1))
        );

            const spawnPos = aSpawn.xyz;
            const spawnTime = aSpawn.w;
            const isActive = aState.x;
            const rotAxis = vec3(aState.y, aState.z, aState.w);

            const glitchTime = uTime ? uTime.mul(10.0) : float(0.0);
            const baseGlitchPosition = applyGlitch(uv(), positionLocal, float(0.2).add(sin(glitchTime).mul(0.1))).position;

            const age = uTime ? uTime.sub(spawnTime) : float(0.0);

            // Pulse scale
            const pulse = float(1.0).add(sin(age.mul(10.0)).mul(0.1));
            const finalScale = pulse.mul(isActive);

            // 🎨 PALETTE: Audio-Reactive Squash & Stretch (Heartbeat/Jelly feel)
            // High impact on kick drum (uAudioLow)
            const beatSquash = uAudioLow ? smoothstep(0.2, 0.8, uAudioLow).pow(float(1.5)).mul(0.4) : float(0.0); // Max 40% squash

            // Squash Y axis down, bulge X/Z axes out
            const scaleY = float(1.0).sub(beatSquash);
            const scaleXZ = float(1.0).add(beatSquash.mul(0.5));
            const audioScale = vec3(scaleXZ, scaleY, scaleXZ);

            const scaledPos = baseGlitchPosition.mul(audioScale).mul(finalScale);

            // Rotate around random axis
            const angle = age.mul(2.0); // Rotation speed
            const c = cos(angle);
            const s = sin(angle);
            const t = float(1.0).sub(c);

            const x = rotAxis.x;
            const y = rotAxis.y;
            const z = rotAxis.z;

            // Custom Rodrigues' rotation formula
            const rx = scaledPos.x.mul(t.mul(x).mul(x).add(c))
                .add(scaledPos.y.mul(t.mul(x).mul(y).sub(s.mul(z))))
                .add(scaledPos.z.mul(t.mul(x).mul(z).add(s.mul(y))));

            const ry = scaledPos.x.mul(t.mul(x).mul(y).add(s.mul(z)))
                .add(scaledPos.y.mul(t.mul(y).mul(y).add(c)))
                .add(scaledPos.z.mul(t.mul(y).mul(z).sub(s.mul(x))));

            const rz = scaledPos.x.mul(t.mul(x).mul(z).sub(s.mul(y)))
                .add(scaledPos.y.mul(t.mul(y).mul(z).add(s.mul(x))))
                .add(scaledPos.z.mul(t.mul(z).mul(z).add(c)));

            const rotatedPos = vec3(rx, ry, rz);

            // Position in world
            return rotatedPos.add(spawnPos);
        });

        // Create Glitchy Material using the compute node to prevent instantiation before material-core exports
        const material = createClayMaterial(0xFF00FF, {
            roughness: 0.2,
            metalness: 0.8,
            emissive: 0xFF00FF,
            emissiveIntensity: 0.8,
            bumpStrength: 0.5,
            noiseScale: 20.0,
            deformationNode: computeLogic()
        });

        this._mesh = new THREE.InstancedMesh(geometry, material, MAX_MINES);
        this._mesh.count = MAX_MINES;
        this._mesh.castShadow = true;
        this._mesh.receiveShadow = true;

        for (let i = 0; i < MAX_MINES; i++) {
            // ⚡ OPTIMIZATION: Instance matrix acts purely as an identity transform.
            // Translation, rotation, and scaling are handled entirely by the TSL material node.
            _scratchDummy.position.set(0, 0, 0);
            _scratchDummy.scale.setScalar(1);
            _scratchDummy.rotation.set(0, 0, 0);
            _scratchMatrix.compose(_scratchDummy.position, _scratchDummy.quaternion, _scratchDummy.scale);
            // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
            _scratchMatrix.toArray(this._mesh.instanceMatrix.array, i * 16);
        }
    }

    /** Lazy getter — triggers WebGPU init on first access. */
    get mesh(): THREE.InstancedMesh {
        this.init();
        return this._mesh!;
    }

    /** Lazy getter — triggers WebGPU init on first access. */
    get spawnBuffer(): THREE.InstancedBufferAttribute {
        this.init();
        return this._spawnBuffer!;
    }

    /** Lazy getter — triggers WebGPU init on first access. */
    get stateBuffer(): THREE.InstancedBufferAttribute {
        this.init();
        return this._stateBuffer!;
    }

    spawnMine(position: THREE.Vector3) {
        if (!this.initialized) this.init();
        if (!unlockSystem.isUnlocked('jitter_mines')) {
            return;
        }

        if (this.cooldownTimer > 0) return;

        // Find free slot
        let index = this.mines.findIndex(m => !m.active);

        // If pool full, recycle oldest
        if (index === -1) {
            // Find oldest (largest time)
            let maxTime = -1;
            let oldestIndex = 0;
            for (let i = 0; i < MAX_MINES; i++) {
                if (this.mines[i].time > maxTime) {
                    maxTime = this.mines[i].time;
                    oldestIndex = i;
                }
            }
            index = oldestIndex;
        }

        const mine = this.mines[index];
        mine.active = true;
        if (mine) mine.visible = true;
        mine.position.copy(position);
        mine.time = 0;

        // Update Instance Attributes
        const spawnArray = this.spawnBuffer.array as Float32Array;
        spawnArray[index * 4] = position.x;
        spawnArray[index * 4 + 1] = position.y;
        spawnArray[index * 4 + 2] = position.z;
        // uTime is global from material-core.ts. We pass current time
        spawnArray[index * 4 + 3] = ((uTime as any).value !== undefined) ? (uTime as any).value : performance.now() / 1000;
        this.spawnBuffer.needsUpdate = true;

        const stateArray = this.stateBuffer.array as Float32Array;
        stateArray[index * 4] = 1.0; // active
        this.stateBuffer.needsUpdate = true;

        this.cooldownTimer = COOLDOWN;

        // Play sound (if available globally)
        if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
            (window as any).AudioSystem.playSound('place', { position: position, pitch: 0.8 });
        }
    }

    update(delta: number, playerPos: THREE.Vector3) {
        if (!this.initialized) return;

        if (this.cooldownTimer > 0) {
            this.cooldownTimer -= delta;
        }

        for (let i = 0; i < MAX_MINES; i++) {
            const mine = this.mines[i];

            if (!mine.active) continue;

            // Update CPU-side time tracking (used for recycling oldest if full)
            mine.time += delta;

            // Proximity Check
            const dx = mine.position.x - playerPos.x;
            const dy = mine.position.y - playerPos.y;
            const dz = mine.position.z - playerPos.z;
            const distSq = dx * dx + dy * dy + dz * dz;
            if (distSq < TRIGGER_RADIUS * TRIGGER_RADIUS) {
                this.explode(i);
            }
        }

        // Handle Trauma Decay and Application
        if (this.trauma > 0) {
            this.trauma -= delta * 2.0; // Decay over ~0.5s
            if (this.trauma < 0) this.trauma = 0;

            // Apply to globals (override/boost audio effects)
            if (uChromaticIntensity) {
                (uChromaticIntensity as any).value = Math.max((uChromaticIntensity as any).value, this.trauma);
            }
            if (uGlitchIntensity) {
                (uGlitchIntensity as any).value = Math.max((uGlitchIntensity as any).value, this.trauma);
            }
        }
    }

    explode(index: number) {
        const mine = this.mines[index];
        if (!mine.active) return;

        mine.active = false;
        if (mine) mine.visible = false;

        // Hide on GPU
        const stateArray = this.stateBuffer.array as Float32Array;
        stateArray[index * 4] = 0.0; // inactive (scale 0)
        this.stateBuffer.needsUpdate = true;

        // Visuals
        spawnImpact(mine.position, 'explosion', 0xFF00FF);

        // Glitch Effect
        // Trigger screen trauma
        this.trauma = 1.0;

        // Sound
        if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
            (window as any).AudioSystem.playSound('explosion', { position: mine.position, pitch: 0.5 + Math.random() * 0.5 });
        }
    }
}

// Lazy init to avoid TSL initialization order issues
let _jitterMineSystem: JitterMineSystem | null = null;

export const jitterMineSystem = new Proxy({} as JitterMineSystem, {
    get: (target, prop) => {
        if (!_jitterMineSystem) {
            _jitterMineSystem = new JitterMineSystem();
        }
        return (_jitterMineSystem as any)[prop];
    },
    set: (target, prop, value) => {
        if (!_jitterMineSystem) {
            _jitterMineSystem = new JitterMineSystem();
        }
        (_jitterMineSystem as any)[prop] = value;
        return true;
    }
});

import * as THREE from 'three';
import {
    vec3, float, positionLocal, normalLocal, mx_noise_float,
    mix, sin, smoothstep, normalize, positionWorld, color, attribute,
    storage, instanceIndex, Fn, If, exp, vec4, uniform, rotate, varyingProperty
} from 'three/tsl';
import { MeshStandardNodeMaterial, StorageInstancedBufferAttribute } from 'three/webgpu';
import { getCelestialState } from '../core/cycle.ts';
import { spawnImpact } from '../foliage/impacts.ts';
import { createCandyMaterial, uTime, uAudioHigh, createJuicyRimLight } from '../foliage/material-core.ts';
import { isInLakeBasin } from '../systems/ground-system.ts';
import { triggerHarpoon } from '../systems/physics/index.ts';
import { unlockSystem } from '../systems/unlocks.ts';
import { foliageClouds, foliageGeysers, foliageTraps } from '../world/state.ts';

// Projectile Configuration
const SPEED = 60.0;
const RADIUS = 0.5;
const MAX_PROJECTILES = 100;
const MAX_LIFE = 3.0;

// ⚡ OPTIMIZATION: Scratch objects to prevent GC in hot loops
const _scratchImpactOptions = { color: new THREE.Color(), direction: new THREE.Vector3() };
const _scratchVec3 = new THREE.Vector3();
const _scratchCelestialState = { sunIntensity: 0, moonIntensity: 0 };

class ProjectilePool {
    mesh: THREE.InstancedMesh;
    projectiles: {
        active: boolean;
        life: number;
        velocity: THREE.Vector3;
        position: THREE.Vector3;
        color: THREE.Color;
        scale: number;
    }[];
    color: THREE.Color;

    // TSL Compute Shader Nodes
    computeNode: any;
    uDeltaTime: any;

    // Buffers for CPU <-> GPU sync
    stateArray: Float32Array;
    velocityArray: Float32Array;
    stateBuffer: StorageInstancedBufferAttribute;
    velocityBuffer: StorageInstancedBufferAttribute;

    constructor() {
        const geo = new THREE.SphereGeometry(RADIUS, 16, 16); // Increased detail for displacement

        this.stateArray = new Float32Array(MAX_PROJECTILES * 4);
        this.velocityArray = new Float32Array(MAX_PROJECTILES * 4);

        // Hide all initially
        for (let i = 0; i < MAX_PROJECTILES; i++) {
            this.stateArray[i * 4 + 3] = 0; // life = 0 means dead/hidden
            this.velocityArray[i * 4 + 3] = 0; // scale = 0
        }

        this.stateBuffer = new StorageInstancedBufferAttribute(this.stateArray, 4);
        this.velocityBuffer = new StorageInstancedBufferAttribute(this.velocityArray, 4);

        geo.setAttribute('aState', this.stateBuffer);
        geo.setAttribute('aVelocity', this.velocityBuffer);

        // --- PALETTE UPGRADE: Plasma Material (TSL) ---
        const mat = new MeshStandardNodeMaterial({
            roughness: 0.4,
            metalness: 0.1,
            transparent: true,
            depthWrite: false
        });

        const stateAttr = attribute('aState', 'vec4');
        const velAttr = attribute('aVelocity', 'vec4');

        const instancePos = stateAttr.xyz;
        const life = stateAttr.w;
        const scaleAttr = velAttr.w;

        // 1. Base Color from Instance
        // Use imported instanceColor node
        const baseColor = varyingProperty('vec3', 'vInstanceColor');
        mat.colorNode = baseColor;

        // 2. Plasma Displacement (Wobble)
        // Scroll noise vertically + rotate?
        const plasmaTime = uTime ? uTime.mul(float(3.0)) : float(0.0);
        const noisePos = positionLocal.mul(float(2.0)).add(vec3(0.0, plasmaTime, 0.0));
        const plasmaNoise = mx_noise_float(noisePos);

        // Displace along normal
        const displacement = normalLocal.mul(plasmaNoise.mul(float(0.15)));

        // 3. Audio Pulse (Size)
        // Expand on high frequencies (melody/snare)
        const audioPulse = uAudioHigh ? uAudioHigh.mul(float(0.3)).add(float(1.0)) : float(1.0);

        // Apply spinning rotation ("Juice")
        const spinAxis = normalize(vec3(1.0, 0.0, 1.0));
        const spunTime = uTime ? uTime.mul(float(5.0)) : float(0.0);
        const spunPosition = rotate(positionLocal, spunTime);

        // Apply Total Deformation based on compute shader scale and position
        mat.positionNode = spunPosition.add(displacement).mul(audioPulse).mul(scaleAttr).add(instancePos);

        // Hide dead projectiles
        mat.opacityNode = smoothstep(0.0, 0.01, life);

        // 4. Juicy Rim Light & Glow
        // Strong rim light for energy feel
        // Temporarily omit to prevent circular audio uniform deps on initial instantiation

        // Inner Glow (Emissive)
        // Pulsate the core brightness with audio
        const coreGlow = uAudioHigh ? baseColor.mul(float(0.5).add(uAudioHigh.mul(0.5))) : baseColor.mul(float(0.5));

        mat.emissiveNode = coreGlow;

        this.mesh = new THREE.InstancedMesh(geo, mat, MAX_PROJECTILES);

        // Disable matrix updates and frustum culling since GPU handles transformations
        this.mesh.matrixAutoUpdate = false;
        this.mesh.frustumCulled = false;

        // ⚡ OPTIMIZATION: Write a pure identity matrix into the instanceMatrix buffer
        // WebGPU TSL multiplies custom positionNode output by instanceMatrix
        const identityMatrix = new THREE.Matrix4();
        for (let i = 0; i < MAX_PROJECTILES; i++) {
            // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        identityMatrix.toArray(this.mesh.instanceMatrix.array, (i) * 16);
        }
        this.mesh.instanceMatrix.needsUpdate = true;

        this.mesh.castShadow = true;
        this.mesh.receiveShadow = false;

        // Initialize Instance Colors Buffer
        // Crucial for the TSL material to read per-instance colors
        const colors = new Float32Array(MAX_PROJECTILES * 3);
        this.mesh.instanceColor = new THREE.InstancedBufferAttribute(colors, 3);
        this.mesh.geometry.setAttribute('instanceColor', this.mesh.instanceColor);
        this.mesh.instanceColor.setUsage(THREE.DynamicDrawUsage);

        this.projectiles = [];
        this.color = new THREE.Color();

        // Initialize CPU pool for collision proxy
        for (let i = 0; i < MAX_PROJECTILES; i++) {
            this.projectiles.push({
                active: false,
                life: 0,
                velocity: new THREE.Vector3(),
                position: new THREE.Vector3(),
                color: new THREE.Color(),
                scale: 0
            });

            // Set initial white
            // ⚡ OPTIMIZATION: Reuse color
            this.color.setHex(0xFFFFFF);
            this.mesh.setColorAt(i, this.color);
        }

        // --- WebGPU COMPUTE SHADER LOGIC ---
        this.uDeltaTime = uniform(0);

        const updateProjectilesCompute = (Fn as any)(() => {
            const index = instanceIndex;

            const stateNode = storage(this.stateBuffer, 'vec4', MAX_PROJECTILES).element(index);
            const velNode = storage(this.velocityBuffer, 'vec4', MAX_PROJECTILES).element(index);

            const pos = stateNode.xyz;
            const life = stateNode.w;

            const vel = velNode.xyz;
            const scale = velNode.w;

            const dt = this.uDeltaTime;

            If(life.greaterThan(0.0), () => {
                const newPos = pos.add(vel.mul(dt));
                const newLife = life.sub(dt);

                // Exponential decay approximation for damp(scale, 1.0, 15.0, dt)
                const decay = exp(float(-15.0).mul(dt));
                const newScale = mix(float(1.0), scale, decay);

                stateNode.assign(vec4(newPos, newLife));
                velNode.assign(vec4(vel, newScale));
            });
        });

        this.computeNode = (updateProjectilesCompute() as unknown as { compute: (n: number) => unknown }).compute(MAX_PROJECTILES);
    }

    addToScene(scene: THREE.Scene) {
        scene.add(this.mesh);
    }

    fire(origin: THREE.Vector3, direction: THREE.Vector3) {
        // Find free slot
        let idx = -1;
        for (let i = 0; i < MAX_PROJECTILES; i++) {
            if (!this.projectiles[i].active) {
                idx = i;
                break;
            }
        }

        if (idx === -1) return; // Pool full

        const p = this.projectiles[idx];
        p.active = true;
        p.life = MAX_LIFE;
        p.scale = 0;
        p.position.copy(origin);
        p.velocity.copy(direction).normalize().multiplyScalar(SPEED);

        // Update GPU Backing Buffer
        this.stateArray[idx * 4 + 0] = p.position.x;
        this.stateArray[idx * 4 + 1] = p.position.y;
        this.stateArray[idx * 4 + 2] = p.position.z;
        this.stateArray[idx * 4 + 3] = p.life;

        this.velocityArray[idx * 4 + 0] = p.velocity.x;
        this.velocityArray[idx * 4 + 1] = p.velocity.y;
        this.velocityArray[idx * 4 + 2] = p.velocity.z;
        this.velocityArray[idx * 4 + 3] = p.scale;

        // Small buffer (100 items), upload whole buffer to avoid range collisions
        this.stateBuffer.needsUpdate = true;
        this.velocityBuffer.needsUpdate = true;

        // Rainbow Color Logic
        const time = performance.now() / 1000;
        const hue = (time * 0.5) % 1.0;
        this.color.setHSL(hue, 1.0, 0.5);

        // Update Instance Color
        this.mesh.setColorAt(idx, this.color);
        p.color.copy(this.color); // Store for trail logic

        // JUICE: Muzzle Flash
        _scratchImpactOptions.color.copy(this.color);
        _scratchImpactOptions.direction.copy(direction);
        spawnImpact(origin, 'muzzle', _scratchImpactOptions.color, _scratchImpactOptions.direction);

        // this.mesh.instanceMatrix.needsUpdate = true; // No longer needed
        if (this.mesh.instanceColor) {
            this.mesh.instanceColor.needsUpdate = true;
        }
    }

    update(dt: number, scene: THREE.Scene, weatherSystem: any, isDay: boolean, renderer: THREE.WebGLRenderer | any) {
        // Run GPU Compute Shader first
        if (renderer && renderer.compute) {
            this.uDeltaTime.value = dt;
            renderer.compute(this.computeNode);
        }

        let needsStateUpdate = false;

        for (let i = 0; i < MAX_PROJECTILES; i++) {
            const p = this.projectiles[i];
            if (!p.active) continue;

            // CPU Proxy Simulation (Keeps track of where particles are for collisions)
            p.position.addScaledVector(p.velocity, dt);
            p.life -= dt;
            p.scale = THREE.MathUtils.damp(p.scale, 1.0, 15.0, dt);

            // Sync current CPU proxy position back to stateArray in case we need to upload
            this.stateArray[i * 4 + 0] = p.position.x;
            this.stateArray[i * 4 + 1] = p.position.y;
            this.stateArray[i * 4 + 2] = p.position.z;
            this.stateArray[i * 4 + 3] = p.life;
            this.velocityArray[i * 4 + 3] = p.scale;

            // JUICE: Projectile Trail
            // Spawn every frame for a continuous trail
            _scratchImpactOptions.color.copy(p.color);
            spawnImpact(p.position, 'trail', _scratchImpactOptions.color);

            let hit = false;

            // Collision with Clouds
            const clouds = foliageClouds || [];

            // Optimization: Simple distance check
            // Iterate backwards to allow removal if logic required (though we don't remove clouds here, just state)
            for (let j = clouds.length - 1; j >= 0; j--) {
                const cloud = clouds[j];
                const cloudRadius = 3.0 * (cloud.scale.x || 1.0);
                const dx = p.position.x - cloud.position.x;
                const dy = p.position.y - cloud.position.y;
                const dz = p.position.z - cloud.position.z;
                const distSq = dx * dx + dy * dy + dz * dz;

                if (distSq < (cloudRadius * cloudRadius)) {
                    hit = true;
                    this.handleCloudHit(cloud, scene, isDay);

                     if (weatherSystem && weatherSystem.notifyCloudShot) {
                        weatherSystem.notifyCloudShot(isDay);
                    }
                    break;
                }
            }

            // Collision with Geysers (Charging)
            const geysers = foliageGeysers || [];
            for (let j = geysers.length - 1; j >= 0; j--) {
                const geyser = geysers[j];
                // Check if hit the base (radius ~1.0)
                // Geyser is at y=ground. Check distSq to base.
                const dx = p.position.x - geyser.position.x;
                const dy = p.position.y - geyser.position.y;
                const dz = p.position.z - geyser.position.z;
                const distSq = dx * dx + dy * dy + dz * dz;
                const hitRadius = 1.5;

                if (distSq < (hitRadius * hitRadius) && Math.abs(dy) < 2.0) {
                    hit = true;
                    // Trigger Charge
                    geyser.userData.chargeLevel = (geyser.userData.chargeLevel || 0) + 0.5;
                    // Clamp charge? Let it go high for super boost!

                    // Visuals
                    spawnImpact(geyser.position, 'jump');
                    break;
                }
            }

            // Collision with Water (Waveform Harpoon)
            if (isInLakeBasin(p.position.x, p.position.z) && p.position.y <= 1.5) {
                hit = true;
                // Anchor Harpoon
                triggerHarpoon(p.position);
                spawnImpact(p.position, 'splash'); // Visual feedback
            }

            // Collision with Snare Traps (Reflection)
            const traps = foliageTraps || [];
            for (let j = traps.length - 1; j >= 0; j--) {
                const trap = traps[j];
                // Check bounds (Radius ~0.8 * scale)
                const radius = 1.0 * (trap.scale.x || 1.0);
                const dx = p.position.x - trap.position.x;
                const dy = p.position.y - trap.position.y;
                const dz = p.position.z - trap.position.z;
                const distSq = dx * dx + dy * dy + dz * dz;

                if (distSq < (radius * radius)) {
                     if (unlockSystem.isUnlocked('snap_core')) {
                         // Hit! Reflect!
                         // Calculate Normal: Outward from trap center
                         _scratchVec3.subVectors(p.position, trap.position).normalize();

                         // Reflect Velocity
                         p.velocity.reflect(_scratchVec3);

                         // Trigger Snap Animation (Immediate Close)
                         trap.userData.snapState = 1.0;

                         // Visuals
                         spawnImpact(p.position, 'snare');

                         // Don't destroy projectile, just bounce
                         // Reduce life slightly to prevent infinite bounces
                         p.life -= 0.5;

                         // Ensure projectile is pushed out to avoid multi-frame collisions?
                         // Move it slightly along normal
                         p.position.addScaledVector(_scratchVec3, 0.5);

                         // Break this loop (handled collision for this frame)
                         // But continue inner loop? No, break checking traps for this projectile
                         break;
                     } else {
                         // Hit! Without upgrade, destroy projectile and trigger trap
                         p.life = 0;
                         trap.userData.snapState = 1.0;
                         spawnImpact(p.position, 'snare');
                         break;
                     }
                }
            }

            if (hit || p.life <= 0) {
                p.active = false;

                // Only sync death state to GPU (life = 0)
                this.stateArray[i * 4 + 3] = 0;

                needsStateUpdate = true;
            }
        }

        // Upload whole buffer to avoid range collisions for this small array
        if (needsStateUpdate) {
            this.stateBuffer.needsUpdate = true;
            this.velocityBuffer.needsUpdate = true;
        }
    }

    handleCloudHit(cloud: any, scene: THREE.Scene, isDay: boolean) {
        if (isDay) {
            this.knockDownCloudMist(cloud);
             // Spawn Mist Impact
             spawnImpact(cloud.position, 'mist');
        } else {
            this.knockDownCloudDeluge(cloud);
            // Spawn Rain Impact
            spawnImpact(cloud.position, 'rain');
        }
    }

    knockDownCloudMist(cloud: any) {
        if (cloud.userData.isFalling) return;
        cloud.userData.isFalling = true;

        // ⚡ OPTIMIZATION: Reuse vector. Assume cloud.userData.velocity exists since it's pre-allocated in createCloud.
        // If not, fall back safely.
        if (!cloud.userData.velocity) cloud.userData.velocity = new THREE.Vector3();
        cloud.userData.velocity.set(0, -5.0, 0);

        cloud.traverse((c: any) => {
            if (c.isMesh && c.material) {
                 // Optimization: Modifying material directly assuming simple use case.
            }
        });
    }

    knockDownCloudDeluge(cloud: any) {
        if (cloud.userData.isFalling) return;
        cloud.userData.isFalling = true;

        // ⚡ OPTIMIZATION: Velocity pre-allocated in createCloud (clouds.ts)
        cloud.userData.velocity.set(0, -20.0, 0);
    }
}

// Global Pool Instance
let _projectilePool: ProjectilePool | null = null;
const projectilePool = new Proxy({} as ProjectilePool, {
    get: (target, prop) => {
        if (!_projectilePool) {
            _projectilePool = new ProjectilePool();
        }
        return (_projectilePool as any)[prop];
    },
    set: (target, prop, value) => {
        if (!_projectilePool) {
            _projectilePool = new ProjectilePool();
        }
        (_projectilePool as any)[prop] = value;
        return true;
    }
});
function getProjectilePool(): ProjectilePool {
    return projectilePool as ProjectilePool;
}

let initialized = false;

export function fireRainbow(scene: THREE.Scene, origin: THREE.Vector3, direction: THREE.Vector3) {
    if (!initialized) {
        getProjectilePool().addToScene(scene);
        initialized = true;
    }
    getProjectilePool().fire(origin, direction);
}

export function updateBlaster(dt: number, scene: THREE.Scene, weatherSystem: any, currentTime: number, renderer?: THREE.WebGLRenderer) {
    const celestial = getCelestialState(currentTime, _scratchCelestialState);
    const isDay = celestial.sunIntensity > 0.5;

    // Ensure pool is in scene (safety)
    if (!initialized) {
         getProjectilePool().addToScene(scene);
         initialized = true;
    }

    getProjectilePool().update(dt, scene, weatherSystem, isDay, renderer);
}

/**
 * @file audio_reactive.ts
 * @description Audio integration for particle systems
 * 
 * Provides global uniforms and update functions for audio-reactive particles.
 */

import * as THREE from 'three';
import { uniform, color } from 'three/tsl';
import type { ParticleAudioState } from './particle_config.ts';

// =============================================================================
// GLOBAL AUDIO UNIFORMS FOR PARTICLES
// =============================================================================

/**
 * Global pulse strength uniform for audio-reactive particles
 * Range: 0.0 - 1.0
 */
export const uPulseStrength = uniform(0.0);

/**
 * Global pulse color uniform for audio-reactive particles
 */
export const uPulseColor = uniform(color(0xFFFFFF));

/**
 * Global beat phase uniform (0-1, cycles with beat)
 */
export const uBeatPhase = uniform(0.0);

/**
 * Global audio level uniform (overall volume)
 */
export const uAudioLevel = uniform(0.0);

// =============================================================================
// AUDIO UPDATE
// =============================================================================

/**
 * Updates global particle audio uniforms from audio state.
 * Call this in your animation loop with current audio analysis.
 * 
 * @param state - Current audio state from audio system
 * 
 * @example
 * ```ts
 * // In animation loop:
 * const visualState = audioSystem.update();
 * updateParticleAudioUniforms({
 *     kick: visualState.kickTrigger,
 *     level: visualState.grooveAmount,
 *     beatPhase: visualState.beatPhase,
 *     color: 0xFF00FF
 * });
 * ```
 */
export function updateParticleAudioUniforms(state: ParticleAudioState): void {
    if (state.kick !== undefined) {
        uPulseStrength.value = state.kick;
    }
    if (state.level !== undefined) {
        uAudioLevel.value = state.level;
    }
    if (state.beatPhase !== undefined) {
        uBeatPhase.value = state.beatPhase;
    }
    if (state.color !== undefined) {
        (uPulseColor.value as any).setHex(state.color);
    }
}

/**
 * Gets the current audio uniform values.
 * Useful for debugging or custom integrations.
 */
export function getParticleAudioState(): ParticleAudioState {
    return {
        kick: uPulseStrength.value,
        level: uAudioLevel.value,
        beatPhase: uBeatPhase.value,
        color: (uPulseColor.value as any as THREE.Color).getHex()
    };
}

/**
 * Resets all audio uniforms to default values.
 */
export function resetParticleAudioUniforms(): void {
    uPulseStrength.value = 0.0;
    uAudioLevel.value = 0.0;
    uBeatPhase.value = 0.0;
    (uPulseColor.value as any).setHex(0xFFFFFF);
}

/**
 * @file compute-particle-integration.ts
 * @description Integration helpers for migrating to compute particle systems
 * 
 * This module provides drop-in replacements for existing particle systems
 * with automatic fallback and performance monitoring.
 */

import * as THREE from 'three';
import { getCIAdjustedCount } from '../core/config.ts';
import { createFireflies as createLegacyFireflies } from '../foliage/fireflies.ts';
import { createNeonPollen as createLegacyPollen } from '../foliage/pollen.ts';
import type { ParticleAudioData } from './compute-particles.ts';
import { ComputeParticleSystem, createComputeFireflies, createComputePollen, createComputeSparks, createComputeBerries, createComputeRain, createComputeGemSparks, addComputeSystem } from './compute-particles.ts';

// ⚡ OPTIMIZATION: Detect Headless/CI environments to aggressively scale down particle
// counts and prevent WebGPU Device Lost errors caused by massive VRAM buffer allocations.
export const PARTICLE_QUALITY =
    (typeof navigator !== 'undefined' && /headless|playwright|ci|test/i.test(navigator.userAgent || '')) ||
    (typeof window !== 'undefined' && (window as any).__IS_FULL_BOOT_TEST === true) ||
    (typeof localStorage !== 'undefined' && localStorage.getItem('__IS_FULL_BOOT_TEST') === 'true') ||
    (typeof navigator !== 'undefined' && (navigator as any).webdriver === true)
        ? 'ci'
        : 'full';

console.log(`[ComputeIntegration] PARTICLE_QUALITY determined as: ${PARTICLE_QUALITY}`);

// =============================================================================
// PERFORMANCE MONITORING
// =============================================================================

interface PerformanceMetrics {
    particleCount: number;
    frameTime: number;
    gpuTime: number;
    cpuFallback: boolean;
}

const metrics: Map<string, PerformanceMetrics> = new Map();

export function getParticleMetrics(systemId: string): PerformanceMetrics | undefined {
    return metrics.get(systemId);
}

export function getAllParticleMetrics(): Map<string, PerformanceMetrics> {
    return new Map(metrics);
}

// =============================================================================
// DROP-IN REPLACEMENTS
// =============================================================================

export interface IntegratedFireflyOptions {
    count?: number;
    areaSize?: number;
    useCompute?: boolean;  // Default: true if WebGPU available
}

/**
 * Drop-in replacement for createFireflies from foliage/fireflies.ts
 * Automatically uses GPU compute when available
 */
export function createIntegratedFireflies(options: IntegratedFireflyOptions = {}): THREE.Object3D {
    const { 
        count = 150, 
        areaSize = 100,
        useCompute = true 
    } = options;

    // Check for WebGPU support
    const hasWebGPU = typeof navigator !== 'undefined' && 'gpu' in navigator;
    const skipHeavyParticles = typeof window !== 'undefined' && (window as any).__fastPopulationOverride;

    // Scale down for CI to prevent device crash
    const ciScale = PARTICLE_QUALITY === 'ci' ? 0.01 : 1.0;

    if (PARTICLE_QUALITY === 'ci') return new THREE.Group();

    if (useCompute && hasWebGPU) {
        // Use GPU compute - 300x more particles!
        const targetCount = skipHeavyParticles ? count : Math.min(count * 300, 100000); // Cap at 100k
        const computeCount = Math.max(Math.floor(targetCount * ciScale), 50); // Floor of 50 to avoid WGSL /0 errors

        try {
            const system = createComputeFireflies({
                count: computeCount,
                bounds: { x: areaSize, y: 15, z: areaSize },
                center: new THREE.Vector3(0, 3, 0)
            });

            // Track metrics
            metrics.set('fireflies', {
                particleCount: computeCount,
                frameTime: 0,
                gpuTime: 0,
                cpuFallback: false
            });

            console.log(`[Particles] GPU Fireflies: ${computeCount.toLocaleString()} particles`);

            system.mesh.userData.computeParticleSystem = system;
            return system.mesh;
        } catch (error) {
            console.warn('[Particles] GPU compute failed, falling back to CPU:', error);
        }
    }

    // Fallback to legacy CPU-based fireflies
    const legacy = createLegacyFireflies(count, areaSize);

    metrics.set('fireflies', {
        particleCount: count,
        frameTime: 0,
        gpuTime: 0,
        cpuFallback: true
    });

    console.log(`[Particles] CPU Fireflies: ${count} particles (WebGPU unavailable or disabled)`);

    return legacy;
}

