export default ComputeParticleSystem;

/**
 * @file cpu-particle-system.ts
 * @description CPU-based fallback particle system when WebGPU compute is not available
 */

import * as THREE from 'three';
import { uv, distance, vec2, vec3, smoothstep, sin, float, mix, color, Fn } from 'three/tsl';
import { PointsNodeMaterial } from 'three/webgpu';
import { uTime, uAudioHigh } from '../foliage/material-core.ts';
import { gemCanopyNoteColorNode, BiomeUniforms } from '../systems/biome-uniforms.ts';
import { isEmscriptenReady } from '../utils/wasm-loader-core.ts';
import { updateCpuParticlesNative } from '../utils/wasm-particles-cpp.ts';
import { ComputeParticleType, ComputeParticleConfig, ParticleAudioData } from './compute-particles-types.ts';
import {
    respawnCpuParticle,
    simulateCpuParticles,
    type CpuParticleBuffers,
    type CpuParticleSimParams,
} from './cpu-particle-simulate.ts';

/**
 * CPU-based fallback when WebGPU compute is not available
 * Simulates the same behavior on the CPU for compatibility
 */
export class CPUParticleSystem {
    public mesh: THREE.Points;
    private positions: Float32Array;
    private velocities: Float32Array;
    private lives: Float32Array;
    private sizes: Float32Array;
    private colors: Float32Array;
    private seeds: Float32Array;
    private count: number;
    private type: ComputeParticleType;
    private bounds: { x: number; y: number; z: number };
    private center: THREE.Vector3;
    private sizeRange: { min: number; max: number };
    private buffers: CpuParticleBuffers;

    constructor(config: ComputeParticleConfig) {
        this.count = config.count || 10000;
        this.type = config.type;
        this.bounds = config.bounds || { x: 100, y: 20, z: 100 };
        this.center = config.center || new THREE.Vector3(0, 5, 0);
        this.sizeRange = config.sizeRange || { min: 0.1, max: 0.3 };

        this.positions = new Float32Array(this.count * 3);
        this.velocities = new Float32Array(this.count * 3);
        this.lives = new Float32Array(this.count);
        this.sizes = new Float32Array(this.count);
        this.colors = new Float32Array(this.count * 4);
        this.seeds = new Float32Array(this.count);
        this.buffers = {
            positions: this.positions,
            velocities: this.velocities,
            lives: this.lives,
            sizes: this.sizes,
            colors: this.colors,
            seeds: this.seeds,
        };

        const respawnParams = this.getRespawnParams();
        for (let i = 0; i < this.count; i++) {
            respawnCpuParticle(this.buffers, respawnParams, i, true);
        }

        const geometry = new THREE.BufferGeometry();
        const quadPositions = new Float32Array(this.count * 4 * 3);
        const quadUvs = new Float32Array(this.count * 4 * 2);
        const quadIndices = new Uint32Array(this.count * 6);

        for (let i = 0; i < this.count; i++) {
            for (let j = 0; j < 4; j++) {
                const baseIdx = (i * 4 + j) * 3;
                quadPositions[baseIdx] = 0;
                quadPositions[baseIdx + 1] = 0;
                quadPositions[baseIdx + 2] = 0;

                const uvIdx = (i * 4 + j) * 2;
                quadUvs[uvIdx] = j % 2 === 0 ? 0 : 1;
                quadUvs[uvIdx + 1] = j < 2 ? 0 : 1;
            }

            const idxBase = i * 6;
            quadIndices[idxBase] = i * 4;
            quadIndices[idxBase + 1] = i * 4 + 1;
            quadIndices[idxBase + 2] = i * 4 + 2;
            quadIndices[idxBase + 3] = i * 4 + 1;
            quadIndices[idxBase + 4] = i * 4 + 3;
            quadIndices[idxBase + 5] = i * 4 + 2;
        }

        geometry.setAttribute('position', new THREE.BufferAttribute(quadPositions, 3));
        geometry.setAttribute('uv', new THREE.BufferAttribute(quadUvs, 2));
        geometry.setIndex(new THREE.BufferAttribute(quadIndices, 1));

        const material = this.createMaterial();

        this.mesh = new THREE.Points(geometry, material);
        this.mesh.frustumCulled = false;
        this.mesh.userData.isCPUParticles = true;
        if (this.type === 'gem_sparks') {
            this.mesh.renderOrder = -10;
        }
    }

    private getRespawnParams() {
        return {
            type: this.type,
            centerX: this.center.x,
            centerY: this.center.y,
            centerZ: this.center.z,
            boundsX: this.bounds.x,
            boundsY: this.bounds.y,
            boundsZ: this.bounds.z,
            sizeMin: this.sizeRange.min,
            sizeMax: this.sizeRange.max,
        };
    }

    private buildSimParams(
        deltaTime: number,
        playerPosition: THREE.Vector3,
        audioData: ParticleAudioData,
        now: number
    ): CpuParticleSimParams {
        return {
            type: this.type,
            count: this.count,
            deltaTime,
            centerX: this.center.x,
            centerY: this.center.y,
            centerZ: this.center.z,
            boundsX: this.bounds.x,
            boundsY: this.bounds.y,
            boundsZ: this.bounds.z,
            sizeMin: this.sizeRange.min,
            sizeMax: this.sizeRange.max,
            playerX: playerPosition.x,
            playerY: playerPosition.y,
            playerZ: playerPosition.z,
            audioLow: audioData.low,
            audioHigh: audioData.high || 0,
            windX: audioData.windX || 0,
            windZ: audioData.windZ || 0,
            timeOffsetFirefly: Math.cos(now * 0.001),
            timeOffsetPollen: now * 0.0005,
            timeSec: now * 0.001,
        };
    }

    private createMaterial(): THREE.Material {
        const material = new PointsNodeMaterial({
            transparent: true,
            depthWrite: false,
            blending: THREE.AdditiveBlending
        });

        const aUv = uv();
        const distFromCenter = distance(aUv, vec2(0.5));
        const alpha = smoothstep(0.5, 0.2, distFromCenter);

        material.opacityNode = alpha;

        let finalColor;
        switch (this.type) {
            case 'fireflies':
                finalColor = vec3(0.88, 1.0, 0.0);
                break;
            case 'pollen':
                finalColor = vec3(0.0, 1.0, 1.0);
                break;
            case 'berries':
                finalColor = vec3(1.0, 0.4, 0.0);
                break;
            case 'rain':
                finalColor = vec3(0.6, 0.8, 1.0);
                break;
            case 'sparks':
                finalColor = vec3(1.0, 0.9, 0.5);
                break;
            case 'gem_sparks':
                material.colorNode = Fn(() => {
                    const jewelRuby = color(0xE0115F);
                    const jewelSapphire = color(0x0F52BA);
                    const jewelAmethyst = color(0x9966CC);
                    const baseJewel = mix(jewelRuby, mix(jewelSapphire, jewelAmethyst, float(0.5)), float(0.5));
                    const musicTint = mix(baseJewel, gemCanopyNoteColorNode, BiomeUniforms.gemCanopy.shimmer);
                    const beatBoost = uAudioHigh.mul(0.5).add(1.0);
                    return musicTint.mul(beatBoost);
                })();
                return material;
            default:
                finalColor = vec3(1.0, 1.0, 1.0);
        }

        material.colorNode = finalColor;

        return material;
    }

    update(deltaTime: number, playerPosition: THREE.Vector3, audioData: ParticleAudioData): void {
        const posAttr = this.mesh.geometry.getAttribute('position') as THREE.BufferAttribute;
        const quadPositions = posAttr.array as Float32Array;
        const now = Date.now();
        const simParams = this.buildSimParams(deltaTime, playerPosition, audioData, now);

        if (isEmscriptenReady() && updateCpuParticlesNative(this.buffers, simParams)) {
            // Native path handled simulation; only expand quads below.
        } else {
            simulateCpuParticles(this.buffers, simParams);
        }

        for (let i = 0; i < this.count; i++) {
            this.updateQuadVertices(i, quadPositions);
        }

        posAttr.needsUpdate = true;
    }

    private updateQuadVertices(i: number, positions: Float32Array): void {
        const idx = i * 3;
        const px = this.positions[idx];
        const py = this.positions[idx + 1];
        const pz = this.positions[idx + 2];
        const size = this.sizes[i];
        const baseIdx = i * 4 * 3;

        positions[baseIdx] = px - size;
        positions[baseIdx + 1] = py - size;
        positions[baseIdx + 2] = pz;

        positions[baseIdx + 3] = px + size;
        positions[baseIdx + 4] = py - size;
        positions[baseIdx + 5] = pz;

        positions[baseIdx + 6] = px - size;
        positions[baseIdx + 7] = py + size;
        positions[baseIdx + 8] = pz;

        positions[baseIdx + 9] = px + size;
        positions[baseIdx + 10] = py + size;
        positions[baseIdx + 11] = pz;
    }

    dispose(): void {
        this.mesh.geometry.dispose();
        (this.mesh.material as THREE.Material).dispose();
    }
}

/**
 * @file gpu_particles.ts
 * @description GPU-accelerated particle systems using Three.js TSL
 * 
 * Implements 5 particle systems:
 * - Shimmer particles (floating sparkles)
 * - Bubble streams (rising iridescent bubbles)
 * - Pollen clouds (swirling around flowers)
 * - Leaf confetti (falling with physics)
 * - Pulse rings (audio-reactive expanding rings)
 * 
 * All systems use TSL nodes for GPU-based animation.
 * 
 * @example
 * ```ts
 * import { 
 *     createShimmerParticles, 
 *     createBubbleStream,
 *     addAmbientParticles 
 * } from './gpu_particles';
 * 
 * // Add shimmer sparkles
 * const shimmer = createShimmerParticles({ count: 1000 });
 * scene.add(shimmer.mesh);
 * 
 * // Add bubbles from a position
 * const bubbles = createBubbleStream({ position: new THREE.Vector3(0, 0, 0) });
 * scene.add(bubbles.mesh);
 * ```
 */

import * as THREE from 'three';
import {
    color,
    vec3,
    vec4,
    attribute,
    time,
    positionLocal,
    mix,
    sin,
    cos,
    float,
    floor
} from 'three/tsl';

// WGSL-compatible modulo: x - y * floor(x / y)
// Note: Converts inputs to float first since WGSL floor() only works on floats
const modFloat = (x: any, y: any) => {
    const xf = float(x);
    const yf = float(y);
    return xf.sub(yf.mul(xf.div(yf).floor()));
};
import { PointsNodeMaterial } from 'three/webgpu';
import { uPulseStrength, uPulseColor } from './audio_reactive.ts';
import type {
    IParticleSystem,
    ShimmerParticleConfig,
    BubbleStreamConfig,
    PollenCloudConfig,
    LeafConfettiConfig,
    PulseRingConfig,
    ParticleAudioState,
    ParticleBounds
} from './particle_config.ts';
import { ParticleSystemType } from './particle_config.ts';

// ⚡ OPTIMIZATION: Fast approximations for Math.sin and Math.cos
function fastSin(x: number): number {
    // Bhaskara I approximation for sine
    // Works for x in [0, PI], so we range reduce to [-PI, PI]
    const INV_PI = 0.3183098861837907; // 1 / PI
    let i = x * INV_PI;
    i = i - 2.0 * Math.round(i * 0.5); // Wrap to [-1, 1] range (i.e. [-PI, PI])

    // Now i is in [-1, 1], meaning x is wrapped to [-PI, PI]
    // Taylor minimax approximation or similar continuous polynomial for [-PI, PI]
    // A simple, continuous quadratic-based approximation (Bhaskara I variant)
    // sin(x) ≈ 16*x*(PI - |x|) / (5*PI^2 - 4*|x|*(PI - |x|))  for x in [0, PI]

    const abs_i = Math.abs(i);
    return (16.0 * i * (1.0 - abs_i)) / (5.0 - 4.0 * abs_i * (1.0 - abs_i));
}

function fastCos(x: number): number {
    return fastSin(x + 1.5707963267948966);
}

// =============================================================================
// SHIMMER PARTICLES (Floating Sparkles)
// =============================================================================

/**
 * Shimmer particle system implementation
 */
class ShimmerParticleSystem implements IParticleSystem {
    public readonly type = ParticleSystemType.SHIMMER;
    public readonly mesh: THREE.Points;

    constructor(config: ShimmerParticleConfig = {}) {
        const {
            count = 500,
            bounds = { x: 50, y: 20, z: 50 },
            minSize = 0.1,
            maxSize = 0.3,
            floatAmplitude = 2.0,
            speed = 1.0
        } = config;

        const geometry = new THREE.BufferGeometry();
        const positions = new Float32Array(count * 3);
        const sizes = new Float32Array(count);
        const offsets = new Float32Array(count);
        const colors = new Float32Array(count * 3);

        for (let i = 0; i < count; i++) {
            // Random positions within bounds
            positions[i * 3] = (Math.random() - 0.5) * bounds.x;
            positions[i * 3 + 1] = Math.random() * bounds.y + 2;
            positions[i * 3 + 2] = (Math.random() - 0.5) * bounds.z;

            // Random sizes
            sizes[i] = Math.random() * (maxSize - minSize) + minSize;

            // Random animation offsets for desynchronization
            offsets[i] = Math.random() * 100;

            // Pastel colors
            colors[i * 3] = 0.7 + Math.random() * 0.3;
            colors[i * 3 + 1] = 0.7 + Math.random() * 0.3;
            colors[i * 3 + 2] = 0.7 + Math.random() * 0.3;
        }

        geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
        geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));
        geometry.setAttribute('offset', new THREE.BufferAttribute(offsets, 1));
        geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));

        const ensureUVAttribute = (geometry: THREE.BufferGeometry) => {
            if (!geometry.attributes.uv && geometry.attributes.position) {
                const count = geometry.attributes.position.count;
                const uvs = new Float32Array(count * 2);
                geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
            }
        };
        ensureUVAttribute(geometry);

        const material = new PointsNodeMaterial({
            transparent: true,
            blending: THREE.AdditiveBlending,
            depthWrite: false
        });

        // TSL Animation nodes
        const aOffset = attribute('offset', 'float');
        const aSize = attribute('size', 'float');
        const aColor = attribute('color', 'vec3');

        // Floating animation
        const floatY = time.mul(0.3 * speed).add(aOffset).sin().mul(floatAmplitude);
        const driftX = time.mul(0.1 * speed).add(aOffset.mul(0.1)).sin().mul(0.5);
        const driftZ = time.mul(0.15 * speed).add(aOffset.mul(0.15)).cos().mul(0.5);

        const pos = positionLocal;
        material.positionNode = vec3(
            pos.x.add(driftX),
            pos.y.add(floatY),
            pos.z.add(driftZ)
        );

        // Twinkle effect
        const twinkle = time.mul(3.0 * speed).add(aOffset).sin().mul(0.5).add(0.5);
        (material as any).sizeNode = aSize.mul(twinkle.add(0.3));

        // Color with sparkle
        const sparkle = time.mul(5.0 * speed).add(aOffset.mul(2.0)).sin().mul(0.3).add(0.7);
        material.colorNode = vec4(aColor.mul(sparkle), twinkle);

        this.mesh = new THREE.Points(geometry, material);
        this.mesh.userData.type = 'shimmer';
    }

    public dispose(): void {
        this.mesh.geometry.dispose();
        (this.mesh.material as THREE.Material).dispose();
    }
}

/**
 * Creates a shimmer particle system (floating sparkles).
 * 
 * @param config - Configuration options
 * @returns A shimmer particle system
 * 
 * @example
 * ```ts
 * const shimmer = createShimmerParticles({ 
 *     count: 1000, 
 *     bounds: { x: 100, y: 30, z: 100 } 
 * });
 * scene.add(shimmer.mesh);
 * ```
 */
export function createShimmerParticles(config: ShimmerParticleConfig = {}): IParticleSystem {
    return new ShimmerParticleSystem(config);
}

