/** Global analytics system instance */
export const analytics = new AnalyticsSystem();

/**
 * @file performance.ts
 * @brief Performance tracking for the Analytics System
 * 
 * PerformanceTracker class for tracking FPS, frame times,
 * memory usage, loading phases, and generating performance metrics.
 */

import {
  type FPSHistogram,
  type FrameTimePercentiles,
  type LoadingPhaseTiming,
  type MemorySnapshot,
  type PerformanceMetrics,
  type EventType,
  type SessionData,
  getTimestamp,
} from './types.ts';

/**
 * Callback type for internal event tracking
 */
type TrackEventInternalFn = (type: EventType, properties: Record<string, unknown>) => void;

/**
 * Performance tracker for monitoring FPS, memory, and loading times
 */
export class PerformanceTracker {
  private performanceMetrics: PerformanceMetrics;

  // Performance tracking
  private frameTimes: number[] = [];
  private fpsSamples: { fps: number; timestamp: number }[] = [];
  private memorySnapshots: MemorySnapshot[] = [];
  private loadingTimings: LoadingPhaseTiming[] = [];
  private currentLoadingPhase: LoadingPhaseTiming | null = null;
  private lastFrameTime: number = 0;
  private frameCount: number = 0;
  private fpsUpdateInterval: number = 0;

  // Configuration and callbacks
  private enabled: boolean = false;
  private trackEventInternal: TrackEventInternalFn | null = null;

  constructor() {
    // Initialize performance metrics
    this.performanceMetrics = {
      fpsHistogram: { at60fps: 0, at30fps: 0, below30fps: 0, totalSamples: 0 },
      frameTimePercentiles: { p50: 0, p95: 0, p99: 0 },
      loadingTimings: [],
      memoryHistory: [],
    };
  }

  /**
   * Initialize the performance tracker with dependencies
   */
  initialize(enabled: boolean, trackEventInternal: TrackEventInternalFn): void {
    this.enabled = enabled;
    this.trackEventInternal = trackEventInternal;
  }

  /**
   * Set enabled state
   */
  setEnabled(enabled: boolean): void {
    this.enabled = enabled;
  }

  /**
   * Track a performance metric
   */
  trackPerformance(metric: string, value: number, properties: Record<string, unknown> = {}): void {
    if (!this.enabled || !this.trackEventInternal) return;

    this.trackEventInternal(`perf_${metric}`, {
      value,
      ...properties,
    });
  }

  /**
   * Start tracking a loading phase
   */
  startLoadingPhase(phase: string): void {
    this.currentLoadingPhase = {
      phase,
      startTime: performance.now(),
      duration: 0,
    };
  }

  /**
   * End tracking a loading phase
   */
  endLoadingPhase(phase: string): void {
    if (this.currentLoadingPhase && this.currentLoadingPhase.phase === phase) {
      this.currentLoadingPhase.duration = performance.now() - this.currentLoadingPhase.startTime;
      this.loadingTimings.push({ ...this.currentLoadingPhase });
      this.performanceMetrics.loadingTimings.push({ ...this.currentLoadingPhase });

      if (this.trackEventInternal) {
        this.trackEventInternal('loading_complete', {
          phase,
          duration: this.currentLoadingPhase.duration,
        });
      }

      this.currentLoadingPhase = null;
    }
  }

  /**
   * Record frame time for performance analysis
   * Call this from your render loop
   */
  recordFrameTime(deltaTime: number): void {
    if (!this.enabled) return;

    const now = performance.now();

    // Calculate FPS
    if (this.lastFrameTime > 0) {
      const frameTime = now - this.lastFrameTime;
      this.frameTimes.push(frameTime);

      // Keep last 1000 samples
      if (this.frameTimes.length > 1000) {
        this.frameTimes.shift();
      }

      // Sample FPS every 500ms
      if (now - this.fpsUpdateInterval > 500) {
        const fps = Math.round(1000 / frameTime);
        this.fpsSamples.push({ fps, timestamp: now });

        // Keep last 100 samples
        if (this.fpsSamples.length > 100) {
          this.fpsSamples.shift();
        }

        this.fpsUpdateInterval = now;
      }

      // Update histogram every 100 frames
      this.frameCount++;
      if (this.frameCount % 100 === 0) {
        this.updateFPSHistogram();
      }
    }

    this.lastFrameTime = now;
  }

  /**
   * Record memory snapshot
   */
  recordMemorySnapshot(): void {
    if (!this.enabled || !this.trackEventInternal) return;

    if (performance && (performance as any).memory) {
      const mem = (performance as any).memory;
      const snapshot: MemorySnapshot = {
        timestamp: Date.now(),
        usedJSHeapSize: Math.round(mem.usedJSHeapSize / 1048576 * 100) / 100, // MB
        totalJSHeapSize: Math.round(mem.totalJSHeapSize / 1048576 * 100) / 100,
        jsHeapSizeLimit: Math.round(mem.jsHeapSizeLimit / 1048576 * 100) / 100,
      };

      this.memorySnapshots.push(snapshot);
      this.performanceMetrics.memoryHistory.push(snapshot);

      // Keep last 100 snapshots
      if (this.memorySnapshots.length > 100) {
        this.memorySnapshots.shift();
      }

      // Warn if memory is high (>80% of limit)
      const usageRatio = snapshot.usedJSHeapSize / snapshot.jsHeapSizeLimit;
      if (usageRatio > 0.8) {
        this.trackEventInternal('memory_warning', {
          usageRatio,
          usedMB: snapshot.usedJSHeapSize,
          limitMB: snapshot.jsHeapSizeLimit,
        });
      }
    }
  }

  /**
   * Update FPS histogram from collected samples
   */
  private updateFPSHistogram(): void {
    if (this.fpsSamples.length === 0) return;

    let at60fps = 0;
    let at30fps = 0;
    let below30fps = 0;

    this.fpsSamples.forEach(sample => {
      if (sample.fps >= 60) {
        at60fps++;
      } else if (sample.fps >= 30) {
        at30fps++;
      } else {
        below30fps++;
      }
    });

    const total = this.fpsSamples.length;

    this.performanceMetrics.fpsHistogram = {
      at60fps: Math.round(at60fps / total * 100),
      at30fps: Math.round(at30fps / total * 100),
      below30fps: Math.round(below30fps / total * 100),
      totalSamples: total,
    };

    // Calculate frame time percentiles
    if (this.frameTimes.length > 0) {
      const sorted = [...this.frameTimes].sort((a, b) => a - b);
      const len = sorted.length;

      this.performanceMetrics.frameTimePercentiles = {
        p50: sorted[Math.floor(len * 0.5)],
        p95: sorted[Math.floor(len * 0.95)],
        p99: sorted[Math.floor(len * 0.99)],
      };
    }
  }

  /**
   * Get current FPS histogram
   */
  getFPSHistogram(): FPSHistogram {
    return { ...this.performanceMetrics.fpsHistogram };
  }

  /**
   * Get frame time percentiles
   */
  getFrameTimePercentiles(): FrameTimePercentiles {
    return { ...this.performanceMetrics.frameTimePercentiles };
  }

  /**
   * Get performance metrics for export
   */
  getPerformanceMetrics(): PerformanceMetrics {
    return { ...this.performanceMetrics };
  }

  /**
   * Setup performance tracking (visibility change listener)
   */
  setupPerformanceTracking(trackEventInternal: TrackEventInternalFn): void {
    if (typeof window === 'undefined') return;

    // Listen for visibility changes (tab switching)
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {
        trackEventInternal('app_backgrounded', {});
      } else {
        trackEventInternal('app_foregrounded', {});
      }
    });
  }

  /**
   * Clear all performance data
   */
  clear(): void {
    this.frameTimes = [];
    this.fpsSamples = [];
    this.memorySnapshots = [];
    this.loadingTimings = [];
    this.currentLoadingPhase = null;
    this.lastFrameTime = 0;
    this.frameCount = 0;
    this.fpsUpdateInterval = 0;

    this.performanceMetrics = {
      fpsHistogram: { at60fps: 0, at30fps: 0, below30fps: 0, totalSamples: 0 },
      frameTimePercentiles: { p50: 0, p95: 0, p99: 0 },
      loadingTimings: [],
      memoryHistory: [],
    };
  }
}

/**
 * @file asset-loading-infrastructure.ts
 * @description Core infrastructure classes for asset loading:
 * - LRUCache for memory management
 * - NetworkManager for optimized HTTP/2, range requests, retry logic
 */

import {
    AssetPriority,
    StreamingConfig,
    NetworkStats
} from './asset-streaming-types.ts';

// ============================================================================
// LRU CACHE IMPLEMENTATION
// ============================================================================

/**
 * LRU (Least Recently Used) cache for asset memory management.
 * Automatically evicts least recently used assets when size limit reached.
 */
export class LRUCache<K, V> {
    private cache: Map<K, V> = new Map();
    private maxSize: number;
    private currentSize: number;
    private getSize: (value: V) => number;

    constructor(
        maxSize: number,
        getSize: (value: V) => number = () => 1
    ) {
        this.maxSize = maxSize;
        this.currentSize = 0;
        this.getSize = getSize;
    }

    get(key: K): V | undefined {
        const value = this.cache.get(key);
        if (value !== undefined) {
            // Move to end (most recently used)
            this.cache.delete(key);
            this.cache.set(key, value);
        }
        return value;
    }

    set(key: K, value: V): boolean {
        const size = this.getSize(value);

        // If single item exceeds max size, don't cache
        if (size > this.maxSize) {
            return false;
        }

        // Remove existing entry if present
        if (this.cache.has(key)) {
            const oldValue = this.cache.get(key)!;
            this.currentSize -= this.getSize(oldValue);
            this.cache.delete(key);
        }

        // Evict entries until we have space
        while (this.currentSize + size > this.maxSize && this.cache.size > 0) {
            this.evictLRU();
        }

        this.cache.set(key, value);
        this.currentSize += size;
        return true;
    }

    delete(key: K): boolean {
        const value = this.cache.get(key);
        if (value !== undefined) {
            this.currentSize -= this.getSize(value);
            return this.cache.delete(key);
        }
        return false;
    }

    has(key: K): boolean {
        return this.cache.has(key);
    }

    private evictLRU(): void {
        const firstKey = this.cache.keys().next().value;
        if (firstKey !== undefined) {
            const value = this.cache.get(firstKey)!;
            this.currentSize -= this.getSize(value);
            this.cache.delete(firstKey);
        }
    }

    clear(): void {
        this.cache.clear();
        this.currentSize = 0;
    }

    get size(): number {
        return this.cache.size;
    }

    get byteSize(): number {
        return this.currentSize;
    }

    keys(): IterableIterator<K> {
        return this.cache.keys();
    }

    forEach(callback: (value: V, key: K) => void): void {
        this.cache.forEach(callback);
    }
}

// ============================================================================
// NETWORK MANAGER
// ============================================================================

interface QueuedRequest {
    url: string;
    priority: AssetPriority;
    range?: { start: number; end: number };
    resolve: (response: Response) => void;
    reject: (error: Error) => void;
    attempts: number;
}

/**
 * Manages network requests with optimization features:
 * - HTTP/2 server push simulation
 * - Range requests for large files
 * - Retry with exponential backoff
 * - Request prioritization and queuing
 */
export class NetworkManager {
    private config: StreamingConfig;
    private activeRequests: Map<string, AbortController> = new Map();
    private requestQueue: QueuedRequest[] = [];
    private stats = {
        bytesDownloaded: 0,
        requests: 0,
        failed: 0,
        retries: 0
    };

    constructor(config: StreamingConfig) {
        this.config = config;
    }

    /** Detect network capabilities */
    async detectNetwork(): Promise<NetworkStats> {
        const connection = (navigator as any).connection;

        return {
            bandwidth: 0,  // Would be measured from actual downloads
            latency: 0,    // Would be measured from ping
            connectionType: connection?.effectiveType || 'unknown',
            saveData: connection?.saveData || false,
            downlink: connection?.downlink,
            rtt: connection?.rtt
        };
    }

    /** Fetch asset with all optimizations */
    async fetchAsset(
        url: string,
        priority: AssetPriority = AssetPriority.MEDIUM,
        range?: { start: number; end: number }
    ): Promise<Response> {
        // Check if we can make more concurrent requests
        if (this.activeRequests.size >= this.config.maxConcurrentRequests) {
            // Queue the request
            return new Promise((resolve, reject) => {
                this.requestQueue.push({
                    url, priority, range, resolve, reject, attempts: 0
                });
                // Sort by priority
                this.requestQueue.sort((a, b) => a.priority - b.priority);
            });
        }

        return this.doFetch(url, priority, range);
    }

    private async doFetch(
        url: string,
        priority: AssetPriority,
        range?: { start: number; end: number }
    ): Promise<Response> {
        const abortController = new AbortController();
        this.activeRequests.set(url, abortController);

        const headers: HeadersInit = {};

        // Add priority hint if supported
        if ('priority' in Request.prototype) {
            (headers as any)['priority'] = this.priorityToHint(priority);
        }

        // Add range header if specified
        if (range && this.config.enableRangeRequests) {
            headers['Range'] = `bytes=${range.start}-${range.end}`;
        }

        try {
            const response = await fetch(url, {
                signal: abortController.signal,
                headers
            });

            if (!response.ok && response.status !== 206) {
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            }

            this.stats.requests++;

            // Track bytes downloaded
            const contentLength = response.headers.get('content-length');
            if (contentLength) {
                this.stats.bytesDownloaded += parseInt(contentLength, 10);
            }

            return response;
        } catch (error) {
            this.stats.failed++;
            throw error;
        } finally {
            this.activeRequests.delete(url);
            this.processQueue();
        }
    }

    private priorityToHint(priority: AssetPriority): 'high' | 'low' | 'auto' {
        switch (priority) {
            case AssetPriority.CRITICAL:
            case AssetPriority.HIGH:
                return 'high';
            case AssetPriority.LOW:
            case AssetPriority.BACKGROUND:
                return 'low';
            default:
                return 'auto';
        }
    }

    private processQueue(): void {
        while (
            this.activeRequests.size < this.config.maxConcurrentRequests &&
            this.requestQueue.length > 0
        ) {
            const request = this.requestQueue.shift()!;
            this.doFetch(request.url, request.priority, request.range)
                .then(request.resolve)
                .catch(request.reject);
        }
    }

    /** Retry with exponential backoff */
    async retryWithBackoff<T>(
        operation: () => Promise<T>,
        attempts: number = this.config.retryAttempts
    ): Promise<T> {
        let lastError: Error | undefined;

        for (let i = 0; i < attempts; i++) {
            try {
                return await operation();
            } catch (error) {
                lastError = error instanceof Error ? error : new Error(String(error));
                this.stats.retries++;

                if (i < attempts - 1) {
                    const delay = this.config.retryDelayMs * Math.pow(2, i);
                    await new Promise(resolve => setTimeout(resolve, delay));
                }
            }
        }

        throw lastError;
    }

    /** Cancel all pending requests */
    cancelAll(): void {
        for (const controller of this.activeRequests.values()) {
            controller.abort();
        }
        this.activeRequests.clear();
        this.requestQueue = [];
    }

    getStats(): typeof this.stats {
        return { ...this.stats };
    }
}

/**
 * @file asset-streaming-core.ts
 * @description Core asset streaming orchestrator and main AssetStreamer class
 * 
 * This module contains the main AssetStreamer class which coordinates all streaming subsystems:
 * - RegionManager for grid cell management and spatial organization
 * - LRUCache for memory management and asset eviction
 * - NetworkManager for optimized HTTP/2 loading with retry logic
 * - Specialized loaders (ProgressiveTextureLoader, AudioStreamingLoader, GeometryLODLoader)
 * - PlaceholderManager for graceful fallback rendering
 * 
 * The AssetStreamer is the primary entry point for asset streaming. It manages:
 * - Priority-based loading queues (CRITICAL → BACKGROUND priority levels)
 * - Memory pressure responses with aggressive unloading strategies
 * - Quality level transitions based on available bandwidth
 * - Loading statistics and progress reporting
 * - Batch asset operations for efficiency
 */

import * as THREE from 'three';
import { RegionManager, GridCell, CellState } from '../region-manager.ts';
import { LRUCache, NetworkManager } from './asset-loading-infrastructure.ts';
import {
    ProgressiveTextureLoader,
    AudioStreamingLoader,
    GeometryLODLoader,
    PlaceholderManager
} from './asset-streaming-loader.ts';
import {
    AssetPriority,
    AssetType,
    TextureFormat,
    LoadState,
    QualityLevel,
    MemoryPressure,
    AssetMetadata,
    AssetManifest,
    LoadedAsset,
    LoadingProgress,
    StreamingConfig,
    StreamingStats,
    AssetRequest,
    AssetBatch,
    DEFAULT_STREAMING_CONFIG,
    PRIORITY_DISTANCES,
    PRIORITY_DISTANCES_SQ,
    QUALITY_FORMAT_PREFERENCES
} from './asset-streaming-types.ts';

const _scratchFuturePos = new THREE.Vector3();

/**
 * Main asset streaming and dynamic loading system.
 * 
 * Coordinates all subsystems:
 * - RegionManager for grid cell management
 * - LRUCache for memory management
 * - NetworkManager for optimized loading
 * - Progressive loaders for specialized asset types
 * - PlaceholderManager for fallbacks
 * 
 * Usage:
 * ```typescript
 * const streamer = new AssetStreamer(scene, manifest);
 * streamer.setPlayerPosition(100, 0, 200);
 * streamer.start();
 * 
 * // Load specific asset with priority
 * await streamer.loadAsset('tree_01', AssetPriority.HIGH);
 * 
 * // Preload a region
 * streamer.preloadRegion(100, 200, 3);
 * 
 * // Get loading progress
 * const progress = streamer.getLoadingProgress();
 * ```
 */
export class AssetStreamer {
    // Subsystems
    private regionManager: RegionManager;
    private assetCache: LRUCache<string, LoadedAsset>;
    private networkManager: NetworkManager;
    private progressiveLoader: ProgressiveTextureLoader;
    private audioLoader: AudioStreamingLoader;
    private geometryLoader: GeometryLODLoader;
    private placeholderManager: PlaceholderManager;

    // State
    private config: StreamingConfig;
    private manifest: AssetManifest;
    private assets: Map<string, LoadedAsset> = new Map();
    private loadingQueue: AssetRequest[] = [];
    private activeLoads: Map<string, AbortController> = new Map();
    private playerPosition: THREE.Vector3 = new THREE.Vector3();
    private playerVelocity: THREE.Vector3 = new THREE.Vector3();
    private lastUpdateTime: number = 0;
    private isRunning: boolean = false;

    // Memory tracking
    private textureMemoryUsed: number = 0;
    private geometryMemoryUsed: number = 0;
    private audioMemoryUsed: number = 0;

    // Event callbacks
    private onProgressCallbacks: Array<(progress: LoadingProgress) => void> = [];
    private onAssetLoadedCallbacks: Array<(asset: LoadedAsset) => void> = [];
    private onErrorCallbacks: Array<(error: Error, assetId: string) => void> = [];

    // Statistics
    private stats: StreamingStats = {
        totalAssets: 0,
        loadedAssets: 0,
        loadingAssets: 0,
        pendingAssets: 0,
        errorAssets: 0,
        memoryUsed: 0,
        cacheHits: 0,
        cacheMisses: 0,
        networkBytesDownloaded: 0,
        networkRequests: 0,
        failedRequests: 0,
        avgLoadTime: 0,
        currentMemoryPressure: MemoryPressure.NONE,
        activeCells: 0,
        queuedCells: 0
    };

    constructor(
        private scene: THREE.Scene,
        manifest: AssetManifest,
        config: Partial<StreamingConfig> = {},
        audioContext?: AudioContext
    ) {
        this.config = { ...DEFAULT_STREAMING_CONFIG, ...config };
        this.manifest = manifest;

        this.regionManager = new RegionManager({ cellSize: this.config.cellSize });
        this.assetCache = new LRUCache(
            this.config.lruCacheSize,
            (asset) => asset.metadata.estimatedMemory
        );
        this.networkManager = new NetworkManager(this.config);
        this.progressiveLoader = new ProgressiveTextureLoader();
        this.audioLoader = audioContext ? new AudioStreamingLoader(audioContext) : undefined!;
        this.geometryLoader = new GeometryLODLoader();
        this.placeholderManager = new PlaceholderManager();

        this.stats.totalAssets = Object.keys(manifest.assets).length;
    }

    // ========================================================================
    // CONFIGURATION
    // ========================================================================

    /**
     * Update streaming configuration.
     */
    configure(config: Partial<StreamingConfig>): void {
        this.config = { ...this.config, ...config };

        // Recreate network manager if concurrent requests changed
        if (config.maxConcurrentRequests !== undefined || 
            config.retryAttempts !== undefined ||
            config.retryDelayMs !== undefined) {
            this.networkManager = new NetworkManager(this.config);
        }
    }

    // ========================================================================
    // PUBLIC API
    // ========================================================================

    /**
     * Start the streaming system.
     * Begins monitoring player position and loading regions.
     */
    start(): void {
        if (this.isRunning) return;
        this.isRunning = true;
        this.updateLoop();
    }

    /**
     * Stop the streaming system.
     * Cancels all pending loads.
     */
    stop(): void {
        this.isRunning = false;
        this.networkManager.cancelAll();
        for (const controller of this.activeLoads.values()) {
            controller.abort();
        }
        this.activeLoads.clear();
    }

    /**
     * Load a single asset with priority.
     */
    async loadAsset(assetId: string, priority: AssetPriority = AssetPriority.MEDIUM): Promise<LoadedAsset> {
        if (this.assets.has(assetId)) {
            this.stats.cacheHits++;
            return this.assets.get(assetId)!;
        }

        const manifest = this.manifest.assets[assetId];
        if (!manifest) throw new Error(`Asset not in manifest: ${assetId}`);

        this.stats.cacheMisses++;

        const request: AssetRequest = {
            id: crypto.randomUUID(),
            assetId,
            priority,
            timestamp: Date.now(),
            retries: 0,
            state: LoadState.PENDING
        };

        return new Promise((resolve, reject) => {
            const originalReject = reject;
            reject = (error: Error) => {
                this.onErrorCallbacks.forEach(cb => cb(error, assetId));
                originalReject(error);
            };

            this.loadingQueue.push(request);
            this.loadingQueue.sort((a, b) => b.priority - a.priority);

            // Timeout for ultra-slow connections
            const timeout = setTimeout(() => {
                reject(new Error(`Asset load timeout: ${assetId}`));
                this.activeLoads.delete(assetId);
            }, this.config.retryDelayMs ?? 5000);

            // Monitor load
            const onLoaded = (asset: LoadedAsset) => {
                if (asset.id === assetId) {
                    clearTimeout(timeout);
                    this.onAssetLoadedCallbacks = this.onAssetLoadedCallbacks.filter(cb => cb !== onLoaded);
                    resolve(asset);
                }
            };

            this.onAssetLoadedCallbacks.push(onLoaded);
        });
    }

    /**
     * Load multiple assets in a batch.
     */
    async loadBatch(batch: AssetBatch): Promise<LoadedAsset[]> {
        const loads: Promise<LoadedAsset>[] = [];
        for (let i = 0; i < batch.ids.length; i++) {
            loads.push(this.loadAsset(batch.ids[i], batch.priority));
        }
        return Promise.all(loads);
    }

    /**
     * Get a loaded asset from cache.
     */
    getAsset(assetId: string): LoadedAsset | null {
        return this.assets.get(assetId) || null;
    }

    /**
     * Release an asset and attempt to free memory.
     */
    releaseAsset(assetId: string): void {
        const asset = this.assets.get(assetId);
        if (!asset) return;

        // Dispose of THREE.js resources
        if (asset.metadata.type === AssetType.TEXTURE && asset.data instanceof THREE.Texture) {
            asset.data.dispose();
        } else if (asset.metadata.type === AssetType.GEOMETRY && asset.data instanceof THREE.BufferGeometry) {
            asset.data.dispose();
        }

        this.assets.delete(assetId);
        this.assetCache.delete(assetId);

        // Update memory tracking
        if (asset.metadata.type === AssetType.TEXTURE) {
            this.textureMemoryUsed = Math.max(0, this.textureMemoryUsed - asset.metadata.estimatedMemory);
        } else if (asset.metadata.type === AssetType.GEOMETRY) {
            this.geometryMemoryUsed = Math.max(0, this.geometryMemoryUsed - asset.metadata.estimatedMemory);
        } else if (asset.metadata.type === AssetType.AUDIO) {
            this.audioMemoryUsed = Math.max(0, this.audioMemoryUsed - asset.metadata.estimatedMemory);
        }
    }

    /**
     * Preload all assets in a region without loading to scene.
     */
    async preloadRegion(cellX: number, cellZ: number, radius: number): Promise<void> {
        const cells = this.regionManager.getCellsInRadius(cellX, cellZ, radius);
        for (const cellKey of cells) {
            // ⚡ OPTIMIZATION: Bypassed .split().map() and Object.entries() to prevent GC spikes.
            let i = 0;
            let cx = 0, cz = 0;
            let signX = 1, signZ = 1;

            if (cellKey.charCodeAt(i) === 45) { // '-'
                signX = -1;
                i++;
            }
            while (i < cellKey.length && cellKey.charCodeAt(i) !== 44) { // ','
                cx = cx * 10 + (cellKey.charCodeAt(i) - 48);
                i++;
            }
            cx *= signX;
            i++; // Skip ','

            if (i < cellKey.length && cellKey.charCodeAt(i) === 45) { // '-'
                signZ = -1;
                i++;
            }
            while (i < cellKey.length) {
                cz = cz * 10 + (cellKey.charCodeAt(i) - 48);
                i++;
            }
            cz *= signZ;

            const assets = this.manifest.assets;
            for (const assetId in assets) {
                if (Object.prototype.hasOwnProperty.call(assets, assetId)) {
                    const meta = assets[assetId];
                    if (meta.cellX === cx && meta.cellZ === cz) {
                        await this.loadAsset(assetId, AssetPriority.LOW);
                    }
                }
            }
        }
    }

    /**
     * Get current loading progress.
     */
    getLoadingProgress(): LoadingProgress {
        return {
            bytesLoaded: 0,          // byte-level tracking not yet implemented
            bytesTotal: 0,
            assetsLoaded: this.stats.loadedAssets,
            assetsTotal: this.stats.totalAssets,
            currentAsset: null,
            queueLength: this.loadingQueue.length,
            estimatedTimeRemaining: this.estimateLoadTime()
        };
    }

    /**
     * Set quality level for streaming (affects texture resolution, geometry LOD).
     */
    setQualityLevel(level: QualityLevel): void {
        this.config.quality = level;

        // Reload textures if quality changed
        for (const asset of this.assets.values()) {
            if (asset.metadata.type === AssetType.TEXTURE) {
                // Reload with new quality
                const manifest = this.manifest.assets[asset.id];
                if (manifest.formats) {
                    const preferredFormats = QUALITY_FORMAT_PREFERENCES[level];
                    if (preferredFormats && preferredFormats.length > 0) {
                        this.loadAsset(asset.id, AssetPriority.HIGH);
                    }
                }
            }
        }
    }

    /**
     * Update player position for proximity-based loading.
     */
    setPlayerPosition(x: number, y: number, z: number): void {
        this.playerPosition.set(x, y, z);

        // Detect velocity (simple delta)
        if (this.lastUpdateTime > 0) {
            const dt = (Date.now() - this.lastUpdateTime) / 1000;
            this.playerVelocity.subVectors(this.playerPosition, this.playerPosition).divideScalar(dt);
        }
        this.lastUpdateTime = Date.now();
    }

    /**
     * Get streaming statistics.
     */
    getStats(): Readonly<StreamingStats> {
        return Object.freeze({ ...this.stats });
    }

    /**
     * Register progress callback.
     */
    onProgress(callback: (progress: LoadingProgress) => void): () => void {
        this.onProgressCallbacks.push(callback);
        return () => {
            this.onProgressCallbacks = this.onProgressCallbacks.filter(cb => cb !== callback);
        };
    }

    /**
     * Register asset loaded callback.
     */
    onAssetLoaded(callback: (asset: LoadedAsset) => void): () => void {
        this.onAssetLoadedCallbacks.push(callback);
        return () => {
            this.onAssetLoadedCallbacks = this.onAssetLoadedCallbacks.filter(cb => cb !== callback);
        };
    }

    /**
     * Register error callback.
     */
    onError(callback: (error: Error, assetId: string) => void): () => void {
        this.onErrorCallbacks.push(callback);
        return () => {
            this.onErrorCallbacks = this.onErrorCallbacks.filter(cb => cb !== callback);
        };
    }

    // ========================================================================
    // PRIORITY MANAGEMENT
    // ========================================================================

    /**
     * Update asset priority based on context (time-based or player state).
     */
    private updateAssetPriorities(): void {
        const now = Date.now();
        for (const request of this.loadingQueue) {
            const age = now - request.timestamp;

            // Gradually increase priority for stale requests
            if (age > 5000) {
                request.priority = Math.min(request.priority + 1, AssetPriority.CRITICAL);
            }
        }

        // Re-sort queue
        this.loadingQueue.sort((a, b) => b.priority - a.priority);
    }

    /**
     * Calculate predicted future position for predictive loading.
     */
    private getPredictedPlayerPosition(dt: number): THREE.Vector3 {
        return _scratchFuturePos
            .copy(this.playerPosition)
            .addScaledVector(this.playerVelocity, dt);
    }

    // ========================================================================
    // MEMORY MANAGEMENT
    // ========================================================================

    /**
     * Check memory pressure and respond aggressively if needed.
     */
    private checkMemoryPressure(): void {
        const totalMemory = this.textureMemoryUsed + this.geometryMemoryUsed + this.audioMemoryUsed;
        this.stats.memoryUsed = totalMemory;

        const maxMemory = this.config.maxTextureMemory + this.config.maxGeometryMemory + this.config.maxAudioMemory;
        if (totalMemory > maxMemory * 0.9) {
            this.stats.currentMemoryPressure = MemoryPressure.CRITICAL;
            this.handleMemoryPressure(MemoryPressure.CRITICAL);
        } else if (totalMemory > maxMemory * 0.7) {
            this.stats.currentMemoryPressure = MemoryPressure.HIGH;
            this.handleMemoryPressure(MemoryPressure.HIGH);
        } else if (totalMemory > maxMemory * 0.5) {
            this.stats.currentMemoryPressure = MemoryPressure.MEDIUM;
            this.handleMemoryPressure(MemoryPressure.MEDIUM);
        } else {
            this.stats.currentMemoryPressure = MemoryPressure.NONE;
        }
    }

    /**
     * Respond to memory pressure by unloading non-critical assets.
     */
    private handleMemoryPressure(pressure: MemoryPressure): void {
        if (pressure === MemoryPressure.NONE) return;

        // Unload background priority assets under any pressure
        for (const request of this.loadingQueue) {
            if (request.priority === AssetPriority.BACKGROUND) {
                this.releaseAsset(request.assetId);
            }
        }

        if (pressure === MemoryPressure.HIGH) {
            // Also unload low priority
            for (const request of this.loadingQueue) {
                if (request.priority === AssetPriority.LOW) {
                    this.releaseAsset(request.assetId);
                }
            }
        } else if (pressure === MemoryPressure.CRITICAL) {
            // Unload everything except critical
            for (const request of this.loadingQueue) {
                if (request.priority !== AssetPriority.CRITICAL) {
                    this.releaseAsset(request.assetId);
                }
            }
        }
    }

    // ========================================================================
    // UPDATE LOOP & REGION LOADING
    // ========================================================================

    /**
     * Main streaming update loop.
     */
    private updateLoop(): void {
        if (!this.isRunning) return;

        this.updateAssetPriorities();
        this.loadNextAssets();
        this.checkMemoryPressure();
        this.updateRegionLoading();

        // Report progress
        const progress = this.getLoadingProgress();
        this.onProgressCallbacks.forEach(cb => cb(progress));

        // Schedule next update
        requestAnimationFrame(() => this.updateLoop());
    }

    /**
     * Load next batch of assets from queue.
     */
    private loadNextAssets(): void {
        const concurrentLimit = this.config.maxConcurrentRequests;
        const currentLoading = this.activeLoads.size;
        const available = Math.max(0, concurrentLimit - currentLoading);

        for (let i = 0; i < available && this.loadingQueue.length > 0; i++) {
            const request = this.loadingQueue.shift()!;
            this.loadAssetInternal(request);
        }
    }

    /**
     * Load individual asset from request.
     */
    private async loadAssetInternal(request: AssetRequest): Promise<void> {
        const assetId = request.assetId;
        const manifest = this.manifest.assets[assetId];

        if (!manifest) {
            this.stats.errorAssets++;
            this.onErrorCallbacks.forEach(cb => 
                cb(new Error(`Asset not in manifest: ${assetId}`), assetId)
            );
            return;
        }

        request.state = LoadState.LOADING;
        this.stats.loadingAssets++;

        const controller = new AbortController();
        this.activeLoads.set(assetId, controller);

        try {
            const asset = await this.loadAssetPipeline(assetId, manifest, controller.signal);

            this.assets.set(assetId, asset);
            this.assetCache.set(assetId, asset);

            request.state = LoadState.LOADED;
            this.stats.loadedAssets++;

            this.onAssetLoadedCallbacks.forEach(cb => cb(asset));
        } catch (error) {
            request.retries++;
            if (request.retries < this.config.retryAttempts) {
                // Re-queue with delay
                setTimeout(() => {
                    this.loadingQueue.push(request);
                    this.loadingQueue.sort((a, b) => b.priority - a.priority);
                }, this.config.retryDelayMs);
            } else {
                request.state = LoadState.ERROR;
                this.stats.errorAssets++;
                this.onErrorCallbacks.forEach(cb => cb(error as Error, assetId));
            }
        } finally {
            this.stats.loadingAssets--;
            this.activeLoads.delete(assetId);
        }
    }

    /**
     * Update region-based loading and culling.
     */
    private updateRegionLoading(): void {
        const playerCell = this.regionManager.getCellAtPosition(
            this.playerPosition.x,
            this.playerPosition.z
        );

        if (!playerCell) return;

        // Get cells within streaming radius
        const priorityCells = this.regionManager.getCellsInRadius(
            playerCell.x,
            playerCell.z,
            this.config.loadRadius
        );

        this.stats.activeCells = priorityCells.length;

        // Mark cells as active/inactive based on whether they are in the priority set
        // ⚡ OPTIMIZATION: Bypassed getAllCells() Array.from() allocation to eliminate GC spike in streaming update loop.
        for (const cell of this.regionManager.cells.values()) {
            const cellKey = `${cell.x},${cell.z}`;
            const isActive = priorityCells.includes(cellKey);
            cell.state = isActive ? CellState.LOADED : CellState.UNLOADED;
        }
    }

    // ========================================================================
    // ASSET LOADING PIPELINE
    // ========================================================================

    /**
     * Main asset loading pipeline - routes to specialized loaders.
     */
    private async loadAssetPipeline(
        assetId: string,
        manifest: AssetMetadata,
        signal: AbortSignal
    ): Promise<LoadedAsset> {
        const startTime = Date.now();

        let data;
        const type = manifest.type;

        if (type === AssetType.TEXTURE) {
            data = await this.loadTextureAsset(manifest, signal);
        } else if (type === AssetType.GEOMETRY) {
            data = await this.loadGeometryAsset(manifest, signal);
        } else if (type === AssetType.AUDIO) {
            data = await this.loadAudioAsset(manifest, signal);
        } else if (type === AssetType.DATA) {
            data = this.placeholderManager.getPlaceholder(AssetType.DATA, manifest.estimatedMemory);
        } else {
            throw new Error(`Unknown asset type: ${type}`);
        }

        const loadTime = Date.now() - startTime;
        this.stats.networkRequests++;

        // Update average load time
        if (this.stats.avgLoadTime === 0) {
            this.stats.avgLoadTime = loadTime;
        } else {
            this.stats.avgLoadTime = (this.stats.avgLoadTime * 0.9) + (loadTime * 0.1);
        }

        return {
            id: assetId,
            metadata: manifest,
            state: LoadState.LOADED,
            data,
            progress: 1,
            lastUsed: Date.now(),
            referenceCount: 1,
            quality: this.config.quality,
            loadTime
        };
    }

    /**
     * Load texture asset with progressive loading.
     */
    private async loadTextureAsset(
        manifest: AssetMetadata,
        _signal: AbortSignal
    ): Promise<THREE.Texture> {
        const format = QUALITY_FORMAT_PREFERENCES[this.config.quality];
        const url = manifest.url || '';

        let texture;
        if (manifest.progressive) {
            texture = await this.progressiveLoader.loadProgressive(
                { thumbnail: url, full: url },
                undefined
            );
        } else if (manifest.compressed) {
            texture = await this.progressiveLoader.loadCompressed(url);
        } else {
            // Fallback: load as standard THREE texture
            const loader = new THREE.TextureLoader();
            texture = await loader.loadAsync(url);
        }

        this.textureMemoryUsed += manifest.estimatedMemory;
        return texture;
    }

    /**
     * Load geometry asset with LOD support.
     */
    private async loadGeometryAsset(
        manifest: AssetMetadata,
        _signal: AbortSignal
    ): Promise<THREE.BufferGeometry> {
        const geometry = await this.geometryLoader.loadLOD(
            { low: manifest.url || '' },
            undefined
        );
        this.geometryMemoryUsed += manifest.estimatedMemory;
        return geometry;
    }

    /**
     * Load audio asset with streaming.
     */
    private async loadAudioAsset(
        manifest: AssetMetadata,
        _signal: AbortSignal
    ): Promise<AudioBuffer> {
        if (!this.audioLoader) {
            throw new Error('Audio context not initialized');
        }
        const buffer = await this.audioLoader.streamAudio(
            manifest.url || ''
        );
        this.audioMemoryUsed += manifest.estimatedMemory;
        return buffer;
    }

    /**
     * Estimate time remaining based on current load rates.
     */
    private estimateLoadTime(): number {
        if (this.stats.avgLoadTime === 0 || this.stats.pendingAssets === 0) {
            return 0;
        }
        return (this.stats.pendingAssets * this.stats.avgLoadTime) / this.stats.loadingAssets;
    }
}

/**
 * @file asset-streaming-loader.ts
 * @description Specialized asset loading classes for progressive textures, audio streams, and LOD geometry
 * 
 * Provides infrastructure for different asset types:
 * - ProgressiveTextureLoader: Low-res → high-res texture loading
 * - AudioStreamingLoader: Streamed audio playback with progress tracking
 * - GeometryLODLoader: Level-of-detail geometry loading
 * - PlaceholderManager: Fallback geometry and texture placeholders
 */

import * as THREE from 'three';
import { AssetType } from './asset-streaming-types.ts';

// ============================================================================
// PROGRESSIVE TEXTURE LOADER
// ============================================================================

/**
 * Loads textures progressively - low resolution first, then refines.
 * Similar to progressive JPEG loading for better perceived performance.
 */
export class ProgressiveTextureLoader {
    private textureLoader: THREE.TextureLoader;
    private ktx2Loader?: unknown;  // Would be THREE.KTX2Loader if available

    constructor() {
        this.textureLoader = new THREE.TextureLoader();
    }

    /**
     * Load texture progressively.
     * First loads a thumbnail/preview, then loads full resolution.
     */
    async loadProgressive(
        urls: { thumbnail: string; full: string },
        onProgress?: (progress: number, isLowRes: boolean) => void
    ): Promise<THREE.Texture> {
        return new Promise((resolve, reject) => {
            // Load low-res thumbnail first
            this.textureLoader.load(
                urls.thumbnail,
                (lowResTexture) => {
                    lowResTexture.generateMipmaps = false;
                    lowResTexture.minFilter = THREE.LinearFilter;
                    onProgress?.(0.5, true);

                    // Then load full resolution
                    this.textureLoader.load(
                        urls.full,
                        (fullTexture) => {
                            onProgress?.(1.0, false);
                            resolve(fullTexture);
                        },
                        undefined,
                        (error) => {
                            // If full fails, use low-res as fallback
                            console.warn(`Failed to load full texture, using low-res: ${error}`);
                            resolve(lowResTexture);
                        }
                    );
                },
                undefined,
                (error) => reject(error)
            );
        });
    }

    /**
     * Load compressed texture (KTX2/Basis)
     */
    async loadCompressed(url: string): Promise<THREE.CompressedTexture> {
        if (!this.ktx2Loader) {
            throw new Error('KTX2Loader not initialized');
        }
        // Type assertion needed since ktx2Loader is unknown type
        return (this.ktx2Loader as { loadAsync(url: string): Promise<THREE.CompressedTexture> }).loadAsync(url);
    }
}

// ============================================================================
// AUDIO STREAMING LOADER
// ============================================================================

/**
 * Streams audio for playback while downloading.
 * Uses MediaSource Extensions or chunked loading.
 */
export class AudioStreamingLoader {
    private audioContext: AudioContext;

    constructor(audioContext: AudioContext) {
        this.audioContext = audioContext;
    }

    /**
     * Stream audio - start playing before fully downloaded
     */
    async streamAudio(
        url: string,
        onProgress?: (progress: number) => void
    ): Promise<AudioBuffer> {
        // For now, use standard fetch and decode
        // Full implementation would use MediaSource Extensions
        const response = await fetch(url);
        const reader = response.body?.getReader();

        if (!reader) {
            throw new Error('ReadableStream not supported');
        }

        const chunks: Uint8Array[] = [];
        const contentLength = parseInt(response.headers.get('content-length') || '0', 10);
        let receivedLength = 0;

        while (true) {
            const { done, value } = await reader.read();

            if (done) break;

            chunks.push(value);
            receivedLength += value.length;

            if (contentLength > 0) {
                onProgress?.(receivedLength / contentLength);
            }
        }

        // Combine chunks
        const allChunks = new Uint8Array(receivedLength);
        let position = 0;
        for (const chunk of chunks) {
            allChunks.set(chunk, position);
            position += chunk.length;
        }

        // Decode audio
        const arrayBuffer = allChunks.buffer;
        return this.audioContext.decodeAudioData(arrayBuffer);
    }
}

