/**
 * Creates and manages placeholder assets while real assets load.
 */
export class PlaceholderManager {
    private placeholders: Map<string, THREE.Object3D> = new Map();
    private lowPolyGeometries: Map<string, THREE.BufferGeometry> = new Map();

    /** Get or create placeholder geometry for an asset type */
    getPlaceholder(type: AssetType, estimatedSize: number): THREE.Object3D {
        const key = `${type}_${estimatedSize}`;

        if (this.placeholders.has(key)) {
            return this.placeholders.get(key)!.clone();
        }

        const placeholder = this.createPlaceholder(type, estimatedSize);
        this.placeholders.set(key, placeholder);
        return placeholder.clone();
    }

    private createPlaceholder(type: AssetType, size: number): THREE.Object3D {
        switch (type) {
            case AssetType.GEOMETRY: {
                // Low-poly bounding box representation
                const box = new THREE.BoxGeometry(size, size, size);
                const material = new THREE.MeshBasicMaterial({
                    color: 0x888888,
                    wireframe: true,
                    transparent: true,
                    opacity: 0.5
                });
                return new THREE.Mesh(box, material);
            }

            case AssetType.TEXTURE: {
                // Colored plane as texture placeholder
                const plane = new THREE.PlaneGeometry(size, size);
                const planeMat = new THREE.MeshBasicMaterial({
                    color: Math.random() * 0xffffff,
                    transparent: true,
                    opacity: 0.3
                });
                return new THREE.Mesh(plane, planeMat);
            }

            default: {
                // Generic placeholder
                const generic = new THREE.Group();
                const dot = new THREE.Mesh(
                    new THREE.SphereGeometry(size * 0.1, 8, 8),
                    new THREE.MeshBasicMaterial({ color: 0xffff00 })
                );
                generic.add(dot);
                return generic;
            }
        }
    }

    /** Create low-poly fallback for timeout scenarios */
    createLowPolyFallback(geometry: THREE.BufferGeometry, targetReduction: number = 0.5): THREE.BufferGeometry {
        // Simplified mesh reduction
        // In production, use a proper decimation library
        const positions = geometry.attributes.position?.array as Float32Array;
        if (!positions) return geometry;

        const vertexCount = positions.length / 3;
        const targetCount = Math.floor(vertexCount * targetReduction);
        const step = Math.ceil(vertexCount / targetCount);

        const newPositions: number[] = [];
        for (let i = 0; i < positions.length; i += step * 3) {
            newPositions.push(positions[i], positions[i + 1], positions[i + 2]);
        }

        const simplified = new THREE.BufferGeometry();
        simplified.setAttribute('position', new THREE.Float32BufferAttribute(newPositions, 3));
        return simplified;
    }

    clear(): void {
        this.placeholders.forEach(p => {
            if ((p as THREE.Mesh).geometry) (p as THREE.Mesh).geometry.dispose();
            if ((p as THREE.Mesh).material) ((p as THREE.Mesh).material as THREE.Material).dispose();
        });
        this.placeholders.clear();
    }
}

/**
 * @file asset-streaming-scheduler.ts
 * @description Task scheduling, priority queue management, and batch processing for asset streaming
 * 
 * Provides:
 * - Priority-based asset request queuing
 * - Batch asset loading coordination
 * - Scheduling optimization and metrics
 */

import {
    AssetPriority,
    AssetRequest,
    AssetBatch,
    LoadedAsset,
    LoadingProgress,
    LoadState,
} from './asset-streaming-types.ts';

// ============================================================================
// SCHEDULER CONSTANTS & TYPES
// ============================================================================

/**
 * Scheduler result for processing status
 */
interface SchedulerResult {
    processedCount: number;
    remainingCount: number;
    timeElapsed: number;
}

// ============================================================================
// ASSET SCHEDULER
// ============================================================================

/**
 * Manages task scheduling, priority queues, and batch processing
 * for the asset streaming system.
 */
export class AssetScheduler {
    private loadingQueue: AssetRequest[] = [];
    private activeLoadCount: number = 0;
    private maxConcurrentLoads: number = 6;
    private batchSize: number = 10;

    constructor(maxConcurrentLoads: number = 6, batchSize: number = 10) {
        this.maxConcurrentLoads = maxConcurrentLoads;
        this.batchSize = batchSize;
    }

    // ========================================================================
    // QUEUE MANAGEMENT
    // ========================================================================

    /**
     * Add an asset request to the loading queue.
     */
    enqueueAsset(request: AssetRequest): void {
        this.loadingQueue.push(request);
        this.sortQueue();
    }

    /**
     * Add multiple asset requests to the loading queue.
     */
    enqueueBatch(requests: AssetRequest[]): void {
        this.loadingQueue.push(...requests);
        this.sortQueue();
    }

    /**
     * Remove an asset request from the queue by ID.
     */
    dequeueAsset(id: string): AssetRequest | undefined {
        const index = this.loadingQueue.findIndex(r => r.id === id);
        if (index !== -1) {
            return this.loadingQueue.splice(index, 1)[0];
        }
        return undefined;
    }

    /**
     * Get the next asset to load based on priority.
     */
    getNextAsset(): AssetRequest | undefined {
        if (this.loadingQueue.length === 0) return undefined;

        if (this.activeLoadCount < this.maxConcurrentLoads) {
            this.activeLoadCount++;
            return this.loadingQueue.shift();
        }

        return undefined;
    }

    /**
     * Mark an asset load as complete.
     */
    completeLoad(): void {
        this.activeLoadCount = Math.max(0, this.activeLoadCount - 1);
    }

    /**
     * Get current queue statistics.
     */
    getQueueStats(): {
        totalQueued: number;
        activeLoads: number;
        capacity: number;
    } {
        return {
            totalQueued: this.loadingQueue.length,
            activeLoads: this.activeLoadCount,
            capacity: this.maxConcurrentLoads
        };
    }

    // ========================================================================
    // PRIORITY MANAGEMENT
    // ========================================================================

    /**
     * Re-prioritize an asset in the queue.
     */
    reprioritizeAsset(id: string, newPriority: AssetPriority): boolean {
        const request = this.loadingQueue.find(r => r.id === id);
        if (request) {
            request.priority = newPriority;
            this.sortQueue();
            return true;
        }
        return false;
    }

    /**
     * Get the priority of an asset in the queue.
     */
    getAssetPriority(id: string): AssetPriority | undefined {
        return this.loadingQueue.find(r => r.id === id)?.priority;
    }

    /**
     * Clear the entire queue.
     */
    clearQueue(): void {
        this.loadingQueue = [];
        this.activeLoadCount = 0;
    }

    /**
     * Get queue size.
     */
    getQueueSize(): number {
        return this.loadingQueue.length;
    }

    /**
     * Check if queue has items.
     */
    hasQueuedItems(): boolean {
        return this.loadingQueue.length > 0;
    }

    // ========================================================================
    // BATCH PROCESSING
    // ========================================================================

    /**
     * Get next batch of assets to process.
     * Returns up to batchSize items without exceeding concurrent load limit.
     */
    getNextBatch(): AssetRequest[] {
        const batch: AssetRequest[] = [];
        const availableSlots = this.maxConcurrentLoads - this.activeLoadCount;
        const batchToTake = Math.min(this.batchSize, availableSlots, this.loadingQueue.length);

        for (let i = 0; i < batchToTake; i++) {
            const item = this.loadingQueue.shift();
            if (item) {
                batch.push(item);
                this.activeLoadCount++;
            }
        }

        return batch;
    }

    /**
     * Process a batch of assets with a callback.
     * Returns scheduling metrics.
     */
    async processBatch(
        batch: AssetRequest[],
        processor: (request: AssetRequest) => Promise<LoadedAsset>
    ): Promise<SchedulerResult> {
        const startTime = performance.now();
        let processedCount = 0;
        let failedCount = 0;

        for (const request of batch) {
            try {
                const asset = await processor(request);
                request.resolve?.(asset);
                processedCount++;
            } catch (error) {
                failedCount++;
                const err = error instanceof Error ? error : new Error(String(error));
                request.reject?.(err);
            } finally {
                this.completeLoad();
            }
        }

        const timeElapsed = performance.now() - startTime;

        return {
            processedCount,
            remainingCount: this.loadingQueue.length,
            timeElapsed
        };
    }

    // ========================================================================
    // CONFIGURATION
    // ========================================================================

    /**
     * Set maximum concurrent loads.
     */
    setMaxConcurrentLoads(count: number): void {
        this.maxConcurrentLoads = Math.max(1, count);
    }

    /**
     * Set batch size for batch processing.
     */
    setBatchSize(size: number): void {
        this.batchSize = Math.max(1, size);
    }

    /**
     * Get current configuration.
     */
    getConfig(): { maxConcurrentLoads: number; batchSize: number } {
        return {
            maxConcurrentLoads: this.maxConcurrentLoads,
            batchSize: this.batchSize
        };
    }

    // ========================================================================
    // PRIVATE HELPERS
    // ========================================================================

    /**
     * Sort queue by priority (ascending = highest priority first).
     */
    private sortQueue(): void {
        this.loadingQueue.sort((a, b) => a.priority - b.priority);
    }
}

// ============================================================================
// BATCH COORDINATOR
// ============================================================================

/**
 * Coordinates batch loading operations with progress tracking.
 */
export class BatchCoordinator {
    /**
     * Load a batch of assets with coordinated progress tracking.
     */
    static async loadBatch(
        batch: AssetBatch,
        loadAssetFn: (id: string, priority: AssetPriority) => Promise<LoadedAsset>
    ): Promise<LoadedAsset[]> {
        const { ids, priority, onProgress, onComplete, onError } = batch;
        const results: LoadedAsset[] = [];
        const errors: Error[] = [];
        let loaded = 0;

        const promises: Promise<LoadedAsset>[] = [];
        for (let i = 0; i < ids.length; i++) {
            const id = ids[i];
            promises.push((async () => {
            try {
                const asset = await loadAssetFn(id, priority);
                results.push(asset);
                loaded++;
                onProgress?.(loaded, ids.length);
                return asset;
            } catch (error) {
                const err = error instanceof Error ? error : new Error(String(error));
                errors.push(err);
                throw err;
            }
        })());
        }

        try {
            await Promise.all(promises);
        } catch {
            // Errors already tracked in errors array
        }

        if (errors.length > 0 && onError) {
            onError(errors);
        }

        if (onComplete) {
            onComplete(results);
        }

        return results;
    }

    /**
     * Create asset requests from batch specification.
     */
    static createBatchRequests(
        batch: AssetBatch
    ): AssetRequest[] {
        const requests: AssetRequest[] = [];
        for (let i = 0; i < batch.ids.length; i++) {
            requests.push({
                id: batch.ids[i],
                assetId: batch.ids[i],
                priority: batch.priority,
                timestamp: Date.now(),
                state: LoadState.PENDING,
                retries: 0,
                resolve: () => {},
                reject: () => {},
            });
        }
        return requests;
    }
}

// ============================================================================
// PRIORITY QUEUE
// ============================================================================

/**
 * Specialized priority queue for asset requests.
 * Uses a min-heap for efficient priority-based retrieval.
 */
export class PriorityQueue {
    private items: AssetRequest[] = [];

    /**
     * Enqueue an item with a priority.
     */
    enqueue(request: AssetRequest): void {
        this.items.push(request);
        this.bubbleUp(this.items.length - 1);
    }

    /**
     * Dequeue the highest priority (lowest value) item.
     */
    dequeue(): AssetRequest | undefined {
        if (this.items.length === 0) return undefined;
        if (this.items.length === 1) return this.items.pop();

        const top = this.items[0];
        this.items[0] = this.items.pop()!;
        this.bubbleDown(0);
        return top;
    }

    /**
     * Peek at the highest priority item without removing it.
     */
    peek(): AssetRequest | undefined {
        return this.items[0];
    }

    /**
     * Check if queue is empty.
     */
    isEmpty(): boolean {
        return this.items.length === 0;
    }

    /**
     * Get queue size.
     */
    size(): number {
        return this.items.length;
    }

    /**
     * Clear the queue.
     */
    clear(): void {
        this.items = [];
    }

    /**
     * Get all items (unordered).
     */
    getAllItems(): AssetRequest[] {
        return [...this.items];
    }

    // ========================================================================
    // PRIVATE HEAP OPERATIONS
    // ========================================================================

    private bubbleUp(index: number): void {
        while (index > 0) {
            const parentIndex = Math.floor((index - 1) / 2);
            if (this.items[index].priority >= this.items[parentIndex].priority) break;

            [this.items[index], this.items[parentIndex]] = [this.items[parentIndex], this.items[index]];
            index = parentIndex;
        }
    }

    private bubbleDown(index: number): void {
        while (true) {
            let swapIndex: number | null = null;
            const leftChild = 2 * index + 1;
            const rightChild = 2 * index + 2;

            if (leftChild < this.items.length &&
                this.items[leftChild].priority < this.items[index].priority) {
                swapIndex = leftChild;
            }

            if (rightChild < this.items.length &&
                this.items[rightChild].priority < (swapIndex === null ? this.items[index].priority : this.items[leftChild].priority)) {
                swapIndex = rightChild;
            }

            if (swapIndex === null) break;

            [this.items[index], this.items[swapIndex]] = [this.items[swapIndex], this.items[index]];
            index = swapIndex;
        }
    }
}

// Atmosphere Reactivity — maps tracker audio to post-processing + sky uniforms.
// Zero-allocation hot path: module-scope scratch only.

import musicBindings from '../../assets/music-bindings.json';
import { BeatSync } from '../audio/beat-sync.ts';
import { uBloomStrength } from '../foliage/post-processing.ts';
import { uCrescendoFogDensity } from '../foliage/sky.ts';
import type { AudioData } from '../foliage/types.ts';
import { MRState, toChannels } from './music-reactivity-core.ts';

export interface AtmosphereBloomBinding {
    channels: readonly number[];
    rest: number;
    peak: number;
    smoothing: number;
}

export interface AtmosphereFogBinding {
    scale: number;
    max: number;
    smoothing: number;
}

export interface AtmosphereShaftBinding {
    peak: number;
    smoothing: number;
}

export interface AtmosphereBeatBinding {
    bloomSpike: number;
    shaftShimmer: number;
    decay: number;
}

/** Read each frame by game-loop for shaft visibility / opacity composition. */
export const AtmosphereShaftState = {
    musicOpacity: 0,
    beatShimmer: 0,
    nightMoonbeam: false,
};

const _defaultAtmosphere = (musicBindings as any).atmosphere ?? {};

const _fallbackBloomChannels: readonly number[] = [0, ...musicBindings.biomes.global.shimmer];

let _bloomBinding: AtmosphereBloomBinding = {
    channels: toChannels(_defaultAtmosphere.bloom?.channels) ?? _fallbackBloomChannels,
    rest: typeof _defaultAtmosphere.bloom?.rest === 'number' ? _defaultAtmosphere.bloom.rest : 1.0,
    peak: typeof _defaultAtmosphere.bloom?.peak === 'number' ? _defaultAtmosphere.bloom.peak : 2.5,
    smoothing: typeof _defaultAtmosphere.bloom?.smoothing === 'number' ? _defaultAtmosphere.bloom.smoothing : 8.0,
};

let _fogBinding: AtmosphereFogBinding = {
    scale: typeof _defaultAtmosphere.fogDensity?.scale === 'number' ? _defaultAtmosphere.fogDensity.scale : 0.65,
    max: typeof _defaultAtmosphere.fogDensity?.max === 'number' ? _defaultAtmosphere.fogDensity.max : 0.85,
    smoothing: typeof _defaultAtmosphere.fogDensity?.smoothing === 'number' ? _defaultAtmosphere.fogDensity.smoothing : 6.0,
};

let _shaftBinding: AtmosphereShaftBinding = {
    peak: typeof _defaultAtmosphere.shaftMelody?.peak === 'number' ? _defaultAtmosphere.shaftMelody.peak : 0.35,
    smoothing: typeof _defaultAtmosphere.shaftMelody?.smoothing === 'number' ? _defaultAtmosphere.shaftMelody.smoothing : 10.0,
};

let _beatBinding: AtmosphereBeatBinding = {
    bloomSpike: typeof _defaultAtmosphere.beatPulse?.bloomSpike === 'number' ? _defaultAtmosphere.beatPulse.bloomSpike : 0.45,
    shaftShimmer: typeof _defaultAtmosphere.beatPulse?.shaftShimmer === 'number' ? _defaultAtmosphere.beatPulse.shaftShimmer : 0.12,
    decay: typeof _defaultAtmosphere.beatPulse?.decay === 'number' ? _defaultAtmosphere.beatPulse.decay : 12.0,
};

let _smoothedBassEnergy = 0;
let _smoothedMixEnergy = 0;
let _smoothedMelodyEnergy = 0;
let _beatBloomSpike = 0;
let _beatShaftShimmer = 0;

function _smooth(current: number, target: number, k: number, deltaTime: number): number {
    return current + (target - current) * (1.0 - Math.exp(-k * deltaTime));
}

function _resetAtmosphereBindings(): void {
    _bloomBinding = {
        channels: toChannels(_defaultAtmosphere.bloom?.channels) ?? _fallbackBloomChannels,
        rest: typeof _defaultAtmosphere.bloom?.rest === 'number' ? _defaultAtmosphere.bloom.rest : 1.0,
        peak: typeof _defaultAtmosphere.bloom?.peak === 'number' ? _defaultAtmosphere.bloom.peak : 2.5,
        smoothing: typeof _defaultAtmosphere.bloom?.smoothing === 'number' ? _defaultAtmosphere.bloom.smoothing : 8.0,
    };
    _fogBinding = {
        scale: typeof _defaultAtmosphere.fogDensity?.scale === 'number' ? _defaultAtmosphere.fogDensity.scale : 0.65,
        max: typeof _defaultAtmosphere.fogDensity?.max === 'number' ? _defaultAtmosphere.fogDensity.max : 0.85,
        smoothing: typeof _defaultAtmosphere.fogDensity?.smoothing === 'number' ? _defaultAtmosphere.fogDensity.smoothing : 6.0,
    };
    _shaftBinding = {
        peak: typeof _defaultAtmosphere.shaftMelody?.peak === 'number' ? _defaultAtmosphere.shaftMelody.peak : 0.35,
        smoothing: typeof _defaultAtmosphere.shaftMelody?.smoothing === 'number' ? _defaultAtmosphere.shaftMelody.smoothing : 10.0,
    };
    _beatBinding = {
        bloomSpike: typeof _defaultAtmosphere.beatPulse?.bloomSpike === 'number' ? _defaultAtmosphere.beatPulse.bloomSpike : 0.45,
        shaftShimmer: typeof _defaultAtmosphere.beatPulse?.shaftShimmer === 'number' ? _defaultAtmosphere.beatPulse.shaftShimmer : 0.12,
        decay: typeof _defaultAtmosphere.beatPulse?.decay === 'number' ? _defaultAtmosphere.beatPulse.decay : 12.0,
    };
}

/** Reapply map overrides for atmosphere bindings (called when map music context changes). */
export function applyAtmosphereMapOverrides(overrides: { atmosphere?: Record<string, unknown> } | undefined): void {
    _resetAtmosphereBindings();
    const atmosphere = overrides?.atmosphere;
    if (!atmosphere || typeof atmosphere !== 'object') return;

    const bloom = atmosphere.bloom as Record<string, unknown> | undefined;
    if (bloom) {
        const channels = toChannels(bloom.channels);
        if (channels) _bloomBinding.channels = channels;
        if (typeof bloom.rest === 'number' && Number.isFinite(bloom.rest)) _bloomBinding.rest = bloom.rest;
        if (typeof bloom.peak === 'number' && Number.isFinite(bloom.peak)) _bloomBinding.peak = bloom.peak;
        if (typeof bloom.smoothing === 'number' && Number.isFinite(bloom.smoothing)) _bloomBinding.smoothing = bloom.smoothing;
    }

    const fog = atmosphere.fogDensity as Record<string, unknown> | undefined;
    if (fog) {
        if (typeof fog.scale === 'number' && Number.isFinite(fog.scale)) _fogBinding.scale = fog.scale;
        if (typeof fog.max === 'number' && Number.isFinite(fog.max)) _fogBinding.max = fog.max;
        if (typeof fog.smoothing === 'number' && Number.isFinite(fog.smoothing)) _fogBinding.smoothing = fog.smoothing;
    }

    const shaft = atmosphere.shaftMelody as Record<string, unknown> | undefined;
    if (shaft) {
        if (typeof shaft.peak === 'number' && Number.isFinite(shaft.peak)) _shaftBinding.peak = shaft.peak;
        if (typeof shaft.smoothing === 'number' && Number.isFinite(shaft.smoothing)) _shaftBinding.smoothing = shaft.smoothing;
    }

    const beat = atmosphere.beatPulse as Record<string, unknown> | undefined;
    if (beat) {
        if (typeof beat.bloomSpike === 'number' && Number.isFinite(beat.bloomSpike)) _beatBinding.bloomSpike = beat.bloomSpike;
        if (typeof beat.shaftShimmer === 'number' && Number.isFinite(beat.shaftShimmer)) _beatBinding.shaftShimmer = beat.shaftShimmer;
        if (typeof beat.decay === 'number' && Number.isFinite(beat.decay)) _beatBinding.decay = beat.decay;
    }
}

export function triggerAtmosphereBeatPulse(kickStrength: number): void {
    const kick = Math.max(0, Math.min(1, kickStrength));
    const scale = 0.5 + kick * 0.5;
    _beatBloomSpike = Math.max(_beatBloomSpike, _beatBinding.bloomSpike * scale);
    _beatShaftShimmer = Math.max(_beatShaftShimmer, _beatBinding.shaftShimmer * scale);
}

export function registerAtmosphereBeatSync(beatSync: BeatSync): void {
    beatSync.onBeat((state) => {
        const kick = state?.kickTrigger || 0;
        if (kick > 0.2) triggerAtmosphereBeatPulse(kick);
    });
}

/**
 * Maps audio energy to bloom, crescendo fog, and shaft state.
 * Mutates uniform `.value` only — never reassigns TSL nodes.
 */
export function updateAtmosphereReactivity(
    audioState: AudioData | null,
    deltaTime: number,
    dayNightBias: number,
    isDay: boolean,
    weatherFogBoost = 0,
): void {
    const channels = audioState?.channelData;
    const bloomCh = _bloomBinding.channels;

    // Kick / bass energy → uBloomStrength (Visual Impact: rest 1.0 → peak 2.5 on crescendo)
    let bassAccum = 0;
    if (channels && bloomCh.length > 0) {
        for (let i = 0; i < bloomCh.length; i++) {
            const idx = bloomCh[i];
            if (idx < channels.length) bassAccum += channels[idx].volume;
        }
    }
    const bassNorm = Math.min(1.0, bassAccum / bloomCh.length);
    _smoothedBassEnergy = _smooth(_smoothedBassEnergy, bassNorm, _bloomBinding.smoothing, deltaTime);

    // Mix energy → uCrescendoFogDensity (Visual Impact: candy-dream haze, not murky — capped at 0.85)
    let mixTarget = 0;
    if (channels && channels.length > 0) {
        let totalVolume = 0;
        for (let i = 0; i < channels.length; i++) {
            totalVolume += channels[i].volume;
        }
        const averageVolume = totalVolume / channels.length;
        mixTarget = Math.min(_fogBinding.max, averageVolume * _fogBinding.scale);
    }
    if (weatherFogBoost > 0) {
        mixTarget = Math.min(_fogBinding.max, mixTarget + weatherFogBoost * 0.35);
    }
    _smoothedMixEnergy = _smooth(_smoothedMixEnergy, mixTarget, _fogBinding.smoothing, deltaTime);

    // Melody channel (sky_moon.melody_channel via MRState.skyMoonCh) → shaft opacity driver
    let melodyVol = 0;
    if (channels && MRState.skyMoonCh < channels.length) {
        melodyVol = channels[MRState.skyMoonCh].volume || 0;
    }
    _smoothedMelodyEnergy = _smooth(_smoothedMelodyEnergy, melodyVol, _shaftBinding.smoothing, deltaTime);

    // Decay beat spikes smoothly
    const beatDecay = 1.0 - Math.exp(-_beatBinding.decay * deltaTime);
    _beatBloomSpike -= _beatBloomSpike * beatDecay;
    _beatShaftShimmer -= _beatShaftShimmer * beatDecay;
    if (_beatBloomSpike < 0.001) _beatBloomSpike = 0;
    if (_beatShaftShimmer < 0.001) _beatShaftShimmer = 0;

    if (!channels) {
        _smoothedBassEnergy = _smooth(_smoothedBassEnergy, 0, _bloomBinding.smoothing, deltaTime);
        _smoothedMixEnergy = _smooth(_smoothedMixEnergy, weatherFogBoost > 0 ? Math.min(_fogBinding.max, weatherFogBoost * 0.35) : 0, _fogBinding.smoothing, deltaTime);
        _smoothedMelodyEnergy = _smooth(_smoothedMelodyEnergy, 0, _shaftBinding.smoothing, deltaTime);
    }

    const nightGate = 0.35 + (1.0 - dayNightBias) * 0.65;
    const bloomBase = _bloomBinding.rest + (_bloomBinding.peak - _bloomBinding.rest) * _smoothedBassEnergy * nightGate;
    const bloomTarget = bloomBase + _beatBloomSpike;
    const currentBloom = uBloomStrength.value as number;
    uBloomStrength.value = _smooth(currentBloom, bloomTarget, _bloomBinding.smoothing, deltaTime);

    const currentFog = uCrescendoFogDensity.value as number;
    uCrescendoFogDensity.value = _smooth(currentFog, _smoothedMixEnergy, _fogBinding.smoothing, deltaTime);

    const melodyShaft = Math.min(_shaftBinding.peak, _smoothedMelodyEnergy * _shaftBinding.peak);
    AtmosphereShaftState.musicOpacity = melodyShaft;
    AtmosphereShaftState.beatShimmer = _beatShaftShimmer;
    AtmosphereShaftState.nightMoonbeam = !isDay && (melodyShaft > 0.02 || _beatShaftShimmer > 0.005);
}

/**
 * Awakened flora persistence — durable soft glow for music-reacted plants.
 *
 * Separate from discovery-persistence (spatial "seen" vs music "awakened").
 * Feature-flagged via FEATURE_FLAGS.awakenedPersistence (?awakened, default off).
 */

import * as THREE from 'three';
import { CONFIG, FEATURE_FLAGS } from '../core/config.ts';
import { luminousPlantBatcher } from '../foliage/luminous-plant-batcher.ts';
import { trackEvent } from './analytics/index.ts';
import {
    computePersistentId,
    persistentIdFromString,
    POSITION_QUANTIZE,
} from './awakened-persistent-id.ts';
import { saveSystem } from './save-system/save-system.ts';
import type { AwakenedFloraState } from './save-system/save-types.ts';

// =============================================================================
// Constants & types
// =============================================================================

export const AWAKENED_SCHEMA_VERSION = 1;
export const STORAGE_KEY = 'candy_world_awakened_v1';
export const SAVE_DEBOUNCE_MS = 500;

export { computePersistentId, persistentIdFromString, POSITION_QUANTIZE } from './awakened-persistent-id.ts';

export const DEFAULT_AWAKENED_EMISSIVE_SCALE = CONFIG.glow.awakenedGlowMultiplier;

export const AWAKENABLE_TYPES = new Set(['luminous_plant', 'gem_canopy_tree']);

export type AwakenedBatcherKind = 'luminous' | 'gem_fruit';

export interface BatcherInstanceRef {
    batcher: AwakenedBatcherKind;
    instanceIndex: number;
    gemType?: number;
}

export interface AwakenedMeta {
    type: string;
    biome?: string;
    awakenedAt: number;
    lastNoteColor?: number;
    emissiveScale: number;
}

interface StoredPayload {
    version: number;
    entries: Array<{
        id: number;
        t: string;
        b?: string;
        at: number;
        c?: number;
        e: number;
    }>;
}

interface PlacedEntity {
    persistentId: number;
    type: string;
    biome?: string;
    position: THREE.Vector3;
    refs: BatcherInstanceRef[];
}

// =============================================================================
// AwakenedStore
// =============================================================================

const _scratchPos = new THREE.Vector3();
const AWAKEN_RADIUS_SQ = 30 * 30;

function isHeadless(): boolean {
    return typeof window === 'undefined' ||
        (typeof import.meta !== 'undefined' && (import.meta as { env?: { CI?: string } }).env?.CI === 'true') ||
        (typeof navigator !== 'undefined' && navigator.userAgent.includes('Headless'));
}

function normalizeLegacyState(raw: AwakenedFloraState): { id: number; meta: AwakenedMeta } | null {
    const legacyId = raw.entityId ?? raw.id;
    let id: number;
    if (typeof (raw as { persistentId?: number }).persistentId === 'number') {
        id = (raw as { persistentId: number }).persistentId;
    } else if (typeof legacyId === 'number') {
        id = legacyId >>> 0;
    } else if (typeof legacyId === 'string' && legacyId.length > 0) {
        if (legacyId.startsWith('pos_')) {
            const parts = legacyId.split('_');
            const x = Number(parts[1]);
            const z = Number(parts[2]);
            if (!Number.isNaN(x) && !Number.isNaN(z)) {
                id = computePersistentId(x / 10, z / 10, raw.type ?? 'unknown');
            } else {
                id = persistentIdFromString(legacyId);
            }
        } else {
            id = persistentIdFromString(legacyId);
        }
    } else {
        return null;
    }

    return {
        id,
        meta: {
            type: raw.type ?? 'unknown',
            biome: raw.biome,
            awakenedAt: raw.awakenedAt ?? raw.lastAwakenedTimestamp ?? Date.now(),
            lastNoteColor: raw.lastNoteColor,
            emissiveScale: raw.emissiveScale ?? DEFAULT_AWAKENED_EMISSIVE_SCALE,
        },
    };
}

export class AwakenedStore {
    readonly awakened = new Set<number>();
    private readonly meta = new Map<number, AwakenedMeta>();
    private readonly placed = new Map<number, PlacedEntity>();
    private readonly analyticsFired = new Set<number>();
    private dirty = false;
    private saveDebounceTimer: ReturnType<typeof setTimeout> | null = null;
    private storageAvailable = false;
    private beforeUnloadBound = false;

    constructor() {
        if (isHeadless()) return;
        this.storageAvailable = this.checkStorage();
        this.ensureBeforeUnload();
    }

    isEnabled(): boolean {
        return FEATURE_FLAGS.awakenedPersistence && !isHeadless();
    }

    /** Parse localStorage once; migrate-or-bail on version mismatch (never throws). */
    load(): void {
        if (!this.isEnabled() || !this.storageAvailable) return;
        try {
            const raw = localStorage.getItem(STORAGE_KEY);
            if (!raw) return;
            const parsed = JSON.parse(raw) as StoredPayload;
            if (parsed.version !== AWAKENED_SCHEMA_VERSION || !Array.isArray(parsed.entries)) {
                console.warn('[AwakenedStore] Schema mismatch — bailing on load');
                return;
            }
            for (const entry of parsed.entries) {
                if (typeof entry.id !== 'number') continue;
                this.awakened.add(entry.id);
                this.meta.set(entry.id, {
                    type: entry.t,
                    biome: entry.b,
                    awakenedAt: entry.at,
                    lastNoteColor: entry.c,
                    emissiveScale: entry.e ?? DEFAULT_AWAKENED_EMISSIVE_SCALE,
                });
            }
            console.log(`[AwakenedStore] Loaded ${parsed.entries.length} awakened entries`);
        } catch (e) {
            console.warn('[AwakenedStore] localStorage load failed:', e);
        }
    }

    /** Idempotent — no-op if already awake */
    set(persistentId: number, meta?: Partial<AwakenedMeta>): boolean {
        if (!this.isEnabled() || !persistentId) return false;

        const isNew = !this.awakened.has(persistentId);
        const existing = this.meta.get(persistentId);

        const merged: AwakenedMeta = {
            type: meta?.type ?? existing?.type ?? 'unknown',
            biome: meta?.biome ?? existing?.biome,
            awakenedAt: existing?.awakenedAt ?? meta?.awakenedAt ?? Date.now(),
            lastNoteColor: meta?.lastNoteColor ?? existing?.lastNoteColor,
            emissiveScale: meta?.emissiveScale ?? existing?.emissiveScale ?? DEFAULT_AWAKENED_EMISSIVE_SCALE,
        };

        this.awakened.add(persistentId);
        this.meta.set(persistentId, merged);
        this.dirty = true;

        this.applyVisualState(persistentId, merged);
        this.scheduleDebouncedSave();

        if (isNew && !this.analyticsFired.has(persistentId)) {
            this.analyticsFired.add(persistentId);
            trackEvent('entity_awakened', {
                entityId: String(persistentId),
                type: merged.type,
                biome: merged.biome ?? 'unknown',
            });
        }

        return isNew;
    }

    getMeta(persistentId: number): AwakenedMeta | undefined {
        return this.meta.get(persistentId);
    }

    isAwakened(persistentId: number): boolean {
        return this.awakened.has(persistentId);
    }

    /** Reused output buffer — no allocation */
    getAwakenedIds(out: number[]): number {
        out.length = 0;
        for (const id of this.awakened) {
            out.push(id);
        }
        return out.length;
    }

    registerPlacedEntity(
        persistentId: number,
        type: string,
        biome: string | undefined,
        position: THREE.Vector3,
        refs: BatcherInstanceRef[] = []
    ): void {
        if (!this.isEnabled() || !AWAKENABLE_TYPES.has(type)) return;

        const existing = this.placed.get(persistentId);
        if (existing) {
            existing.refs.push(...refs);
        } else {
            this.placed.set(persistentId, {
                persistentId,
                type,
                biome,
                position: position.clone(),
                refs: [...refs],
            });
        }

        if (this.awakened.has(persistentId)) {
            this.applyVisualState(persistentId, this.meta.get(persistentId));
        }
    }

    tryAwakenNearby(
        type: string,
        origin: THREE.Vector3,
        intensity: number,
        lastNoteColor?: number
    ): void {
        if (!this.isEnabled() || intensity < 0.2 || !AWAKENABLE_TYPES.has(type)) return;

        for (const placed of this.placed.values()) {
            if (placed.type !== type) continue;
            if (this.awakened.has(placed.persistentId)) continue;
            const dx = placed.position.x - origin.x;
            const dz = placed.position.z - origin.z;
            if (dx * dx + dz * dz > AWAKEN_RADIUS_SQ) continue;

            this.set(placed.persistentId, {
                type: placed.type,
                biome: placed.biome,
                lastNoteColor,
            });
        }
    }

    /** Drop orphans (no live instance) and bulk-upload GPU state */
    reconcileAndApplyToBatchers(): void {
        if (!this.isEnabled()) return;

        const knownIds = luminousPlantBatcher.getKnownPersistentIds();
        let dropped = 0;

        for (const id of [...this.awakened]) {
            if (!knownIds.has(id) && !this.placed.has(id)) {
                this.awakened.delete(id);
                this.meta.delete(id);
                dropped++;
                this.dirty = true;
            }
        }

        const bulkEntries: Array<{ persistentId: number; scale: number }> = [];
        for (const id of this.awakened) {
            const meta = this.meta.get(id);
            if (!meta) continue;
            if (knownIds.has(id) || this.placed.has(id)) {
                bulkEntries.push({ persistentId: id, scale: meta.emissiveScale });
            }
        }

        luminousPlantBatcher.applyAwakenedBulk(bulkEntries);

        if (bulkEntries.length > 0 || dropped > 0) {
            console.log(`[AwakenedStore] Applied ${bulkEntries.length} awakened states (${dropped} orphans dropped)`);
        }
    }

    /** @deprecated Use reconcileAndApplyToBatchers */
    applyLoadedStatesToBatchers(): void {
        this.reconcileAndApplyToBatchers();
    }

    serialize(): AwakenedFloraState[] {
        if (!this.isEnabled() || isHeadless()) return [];
        const out: AwakenedFloraState[] = [];
        for (const id of this.awakened) {
            const meta = this.meta.get(id);
            if (!meta) continue;
            out.push({
                persistentId: id,
                entityId: String(id),
                id: String(id),
                type: meta.type,
                biome: meta.biome,
                awakenedAt: meta.awakenedAt,
                lastNoteColor: meta.lastNoteColor,
                emissiveScale: meta.emissiveScale,
                awakened: true,
            });
        }
        return out;
    }

    deserialize(data: AwakenedFloraState[]): void {
        if (!this.isEnabled() || isHeadless()) return;
        this.awakened.clear();
        this.meta.clear();
        for (const raw of data) {
            const normalized = normalizeLegacyState(raw);
            if (!normalized) continue;
            this.awakened.add(normalized.id);
            this.meta.set(normalized.id, normalized.meta);
        }
    }

    exportSnapshot(): string {
        const payload: StoredPayload = {
            version: AWAKENED_SCHEMA_VERSION,
            entries: [],
        };
        for (const id of this.awakened) {
            const m = this.meta.get(id);
            if (!m) continue;
            payload.entries.push({
                id,
                t: m.type,
                b: m.biome,
                at: m.awakenedAt,
                c: m.lastNoteColor,
                e: m.emissiveScale,
            });
        }
        return JSON.stringify(payload);
    }

    importSnapshot(json: string): void {
        if (!this.isEnabled()) return;
        try {
            const parsed = JSON.parse(json) as StoredPayload;
            if (parsed.version !== AWAKENED_SCHEMA_VERSION || !Array.isArray(parsed.entries)) {
                console.warn('[AwakenedStore] importSnapshot: schema mismatch');
                return;
            }
            this.awakened.clear();
            this.meta.clear();
            for (const entry of parsed.entries) {
                this.awakened.add(entry.id);
                this.meta.set(entry.id, {
                    type: entry.t,
                    biome: entry.b,
                    awakenedAt: entry.at,
                    lastNoteColor: entry.c,
                    emissiveScale: entry.e ?? DEFAULT_AWAKENED_EMISSIVE_SCALE,
                });
            }
            this.dirty = true;
            this.saveSync();
            this.reconcileAndApplyToBatchers();
        } catch (e) {
            console.warn('[AwakenedStore] importSnapshot failed:', e);
        }
    }

    reset(): void {
        this.awakened.clear();
        this.meta.clear();
        this.placed.clear();
        this.analyticsFired.clear();
        this.dirty = false;
        if (this.storageAvailable) {
            try { localStorage.removeItem(STORAGE_KEY); } catch { /* ignore */ }
        }
    }

    getTotalAwakenedCount(): number {
        return this.awakened.size;
    }

    // -------------------------------------------------------------------------
    // Debug / dev
    // -------------------------------------------------------------------------

    debugAwaken(persistentId: number, emissiveScale = DEFAULT_AWAKENED_EMISSIVE_SCALE): void {
        if (!this.isEnabled()) {
            console.warn('[AwakenedStore] debugAwaken: flag off (?awakened)');
            return;
        }
        this.set(persistentId, { type: 'luminous_plant', biome: 'luminous_plants', emissiveScale });
        this.saveSync();
        console.log(`[AwakenedStore] debugAwaken(${persistentId})`);
    }

    // -------------------------------------------------------------------------
    // Persistence
    // -------------------------------------------------------------------------

    private scheduleDebouncedSave(): void {
        if (this.saveDebounceTimer) clearTimeout(this.saveDebounceTimer);
        this.saveDebounceTimer = setTimeout(() => {
            this.saveDebounceTimer = null;
            this.saveSync();
            saveSystem.triggerEventSave('entity_awakened');
        }, SAVE_DEBOUNCE_MS);
    }

    saveSync(): void {
        if (!this.isEnabled() || !this.storageAvailable || !this.dirty) return;
        try {
            const payload: StoredPayload = {
                version: AWAKENED_SCHEMA_VERSION,
                entries: [],
            };
            for (const id of this.awakened) {
                const m = this.meta.get(id);
                if (!m) continue;
                payload.entries.push({
                    id,
                    t: m.type,
                    b: m.biome,
                    at: m.awakenedAt,
                    c: m.lastNoteColor,
                    e: m.emissiveScale,
                });
            }
            localStorage.setItem(STORAGE_KEY, JSON.stringify(payload));
            this.dirty = false;
        } catch (e) {
            console.warn('[AwakenedStore] localStorage write failed:', e);
        }
    }

    flushPendingSave(): void {
        if (this.saveDebounceTimer) {
            clearTimeout(this.saveDebounceTimer);
            this.saveDebounceTimer = null;
        }
        this.saveSync();
    }

    private ensureBeforeUnload(): void {
        if (this.beforeUnloadBound || typeof window === 'undefined') return;
        this.beforeUnloadBound = true;
        window.addEventListener('beforeunload', () => {
            this.flushPendingSave();
        });
    }

    private checkStorage(): boolean {
        try {
            if (typeof window === 'undefined' || !window.localStorage) return false;
            const k = '__awakened_test__';
            localStorage.setItem(k, '1');
            localStorage.removeItem(k);
            return true;
        } catch {
            return false;
        }
    }

    private applyVisualState(persistentId: number, meta?: AwakenedMeta): void {
        if (!meta) return;
        const scale = meta.emissiveScale;
        const placed = this.placed.get(persistentId);
        if (placed) {
            for (const ref of placed.refs) {
                if (ref.batcher === 'luminous') {
                    luminousPlantBatcher.applyAwakenedState(persistentId, scale);
                }
            }
        } else if (luminousPlantBatcher.hasPersistentId(persistentId)) {
            luminousPlantBatcher.applyAwakenedState(persistentId, scale);
        }
    }
}

// =============================================================================
// Lazy singleton — never constructed when flag is off
// =============================================================================

let _store: AwakenedStore | null = null;

export function getAwakenedStore(): AwakenedStore | null {
    if (!FEATURE_FLAGS.awakenedPersistence || isHeadless()) return null;
    if (!_store) {
        _store = new AwakenedStore();
        _store.load();
    }
    return _store;
}

/** Resolve stable persistentId from a placed object */
export function resolvePersistentId(obj: THREE.Object3D): number {
    const ud = obj.userData;
    if (typeof ud.persistentId === 'number') {
        return ud.persistentId >>> 0;
    }
    if (typeof ud.persistentId === 'string' && ud.persistentId.length > 0) {
        return persistentIdFromString(ud.persistentId);
    }
    if (typeof ud.mapEntityId === 'string' && ud.mapEntityId.length > 0) {
        return persistentIdFromString(ud.mapEntityId);
    }
    obj.getWorldPosition(_scratchPos);
    const typeId = (typeof ud.type === 'string' && ud.type) ? ud.type : 'unknown';
    return computePersistentId(_scratchPos.x, _scratchPos.z, typeId);
}

// =============================================================================
// Facade for existing call sites (music-reactivity, placement hooks, save)
// =============================================================================

function store(): AwakenedStore | null {
    return getAwakenedStore();
}

export const awakenedPersistence = {
    isEnabled(): boolean {
        return FEATURE_FLAGS.awakenedPersistence && !isHeadless();
    },

    resolvePersistentId,

    registerPlacedEntity(
        persistentId: number,
        type: string,
        biome: string | undefined,
        position: THREE.Vector3,
        refs: BatcherInstanceRef[] = []
    ): void {
        store()?.registerPlacedEntity(persistentId, type, biome, position, refs);
    },

    markAwakened(
        persistentId: number,
        meta: { type: string; biome?: string; lastNoteColor?: number; emissiveScale?: number }
    ): boolean {
        return store()?.set(persistentId, meta) ?? false;
    },

    isAwakened(persistentId: number): boolean {
        return store()?.isAwakened(persistentId) ?? false;
    },

    getState(persistentId: number): AwakenedMeta | undefined {
        return store()?.getMeta(persistentId);
    },

    tryAwakenNearby(
        type: string,
        origin: THREE.Vector3,
        intensity: number,
        lastNoteColor?: number
    ): void {
        store()?.tryAwakenNearby(type, origin, intensity, lastNoteColor);
    },

    applyLoadedStatesToBatchers(): void {
        store()?.reconcileAndApplyToBatchers();
    },

    reconcileOrphans(): number {
        const s = store();
        if (!s) return 0;
        const before = s.getTotalAwakenedCount();
        s.reconcileAndApplyToBatchers();
        return before - s.getTotalAwakenedCount();
    },

    serialize(): AwakenedFloraState[] {
        return store()?.serialize() ?? [];
    },

    deserialize(data: AwakenedFloraState[]): void {
        store()?.deserialize(data);
    },

    reset(): void {
        store()?.reset();
        _store = null;
    },

    getTotalAwakenedCount(): number {
        return store()?.getTotalAwakenedCount() ?? 0;
    },

    /** @deprecated Use getAwakenedStore */
    loadFromLocalStorage(): void {
        store()?.load();
    },

    debugAwaken(persistentId: number, emissiveScale?: number): void {
        store()?.debugAwaken(persistentId, emissiveScale);
    },

    exportSnapshot(): string {
        return store()?.exportSnapshot() ?? '{"version":1,"entries":[]}';
    },

    importSnapshot(json: string): void {
        store()?.importSnapshot(json);
    },
};

/** @deprecated Use AwakenedStore */
export { AwakenedStore as AwakenedPersistenceManager };

if (typeof window !== 'undefined') {
    const w = window as unknown as Record<string, unknown>;
    w.awakenedPersistence = awakenedPersistence;
    w.debugAwaken = (id: number) => awakenedPersistence.debugAwaken(id);
}

