/** Pure distance → target LOD factor (0 hero, 1 mid, 2 far, 3 culled). Exported for tests. */
export function computeTargetLodFactor(
    distance: number,
    cfg: Pick<FoliageLodConfig, 'heroMax' | 'midMax' | 'blendWidth' | 'farCull'> = getFoliageLodConfig()
): number {
    if (distance >= cfg.farCull) return 3;

    const bw = Math.max(1, cfg.blendWidth);
    const heroEdge = cfg.heroMax;
    const midEdge = cfg.midMax;

    if (distance <= heroEdge - bw) return 0;
    if (distance <= heroEdge + bw) {
        const t = (distance - (heroEdge - bw)) / (2 * bw);
        return smoothstep01(t);
    }
    if (distance <= midEdge - bw) return 1;
    if (distance <= midEdge + bw) {
        const t = (distance - (midEdge - bw)) / (2 * bw);
        return 1 + smoothstep01(t);
    }
    return 2;
}

/**
 * ⚡ OPTIMIZATION: Pure squared distance → target LOD factor.
 * Defers Math.sqrt() until we are exactly within a blend range.
 */
export function computeTargetLodFactorSq(
    distSq: number,
    cfg: Pick<FoliageLodConfig, 'heroMax' | 'midMax' | 'blendWidth' | 'farCull'> = getFoliageLodConfig()
): number {
    if (distSq >= cfg.farCull * cfg.farCull) return 3;

    const bw = Math.max(1, cfg.blendWidth);
    const heroEdge = cfg.heroMax;
    const midEdge = cfg.midMax;

    const heroMin = heroEdge - bw;
    if (heroMin >= 0 && distSq <= heroMin * heroMin) return 0;

    const heroMax = heroEdge + bw;
    if (distSq <= heroMax * heroMax) {
        const distance = Math.sqrt(distSq);
        const t = (distance - heroMin) / (2 * bw);
        return smoothstep01(t);
    }

    const midMin = midEdge - bw;
    if (midMin >= 0 && distSq <= midMin * midMin) return 1;

    const midMax = midEdge + bw;
    if (distSq <= midMax * midMax) {
        const distance = Math.sqrt(distSq);
        const t = (distance - midMin) / (2 * bw);
        return 1 + smoothstep01(t);
    }
    return 2;
}

function smoothstep01(t: number): number {
    const x = Math.max(0, Math.min(1, t));
    return x * x * (3 - 2 * x);
}

/** True when instance is in a tier cross-fade band (for stats / debug). */
export function isInLodBlendBand(factor: number, cfg: FoliageLodConfig = getFoliageLodConfig()): boolean {
    if (factor >= 3) return false;
    if (factor > 0.75 && factor < 1.15) return true;
    if (factor > 1.45 && factor < 2.15) return true;
    if (factor >= cfg.impostorMinFactor && factor <= cfg.impostorMaxFactor) return true;
    return false;
}

function impostorAlphaFromFactor(factor: number, cfg: FoliageLodConfig): number {
    if (factor < cfg.impostorMinFactor) return 0;
    if (factor >= cfg.impostorMaxFactor) return 1;
    const t = (factor - cfg.impostorMinFactor) / (cfg.impostorMaxFactor - cfg.impostorMinFactor);
    return smoothstep01(t);
}

export function setFoliageLodDebugHighlight(enabled: boolean): void {
    _debugHighlight = enabled;
    uLodDebugHighlight.value = enabled ? 1.0 : 0.0;
}

export function registerFoliageBatcherLod(target: BatcherLodTarget): void {
    if (_targets.some((t) => t.id === target.id)) return;
    _targets.push(target);
    for (const mesh of target.getMeshes()) {
        trackLodMesh(mesh);
    }
}

function trackLodMesh(mesh: THREE.InstancedMesh): void {
    if (_meshTracks.has(mesh)) return;
    ensureInstanceLodAttribute(mesh);

    const count = mesh.instanceMatrix.count;
    _meshTracks.set(mesh, new Float32Array(count));

    // ⚡ OPTIMIZATION: Cached impostor scales at registration to eliminate O(N) matrix basis extraction and Math.sqrt() overhead in the high-frequency LOD loop.
    const maxScales = new Float32Array(count);
    precomputeMaxScales(mesh, maxScales);
    _meshMaxScales.set(mesh, maxScales);

    mesh.userData.foliageLodTracked = true;
}

function precomputeMaxScales(mesh: THREE.InstancedMesh, maxScales: Float32Array): void {
    const matrixArray = mesh.instanceMatrix.array as Float32Array;
    const count = maxScales.length; // Use buffer capacity rather than active count to cover future additions
    for (let i = 0; i < count; i++) {
        const offset = i * 16;
        const m00 = matrixArray[offset + 0], m01 = matrixArray[offset + 1], m02 = matrixArray[offset + 2];
        const m10 = matrixArray[offset + 4], m11 = matrixArray[offset + 5], m12 = matrixArray[offset + 6];
        const m20 = matrixArray[offset + 8], m21 = matrixArray[offset + 9], m22 = matrixArray[offset + 10];

        const scaleXSq = m00 * m00 + m01 * m01 + m02 * m02;
        const scaleYSq = m10 * m10 + m11 * m11 + m12 * m12;
        const scaleZSq = m20 * m20 + m21 * m21 + m22 * m22;
        const maxScaleSq = Math.max(scaleXSq, scaleYSq, scaleZSq);

        maxScales[i] = Math.sqrt(maxScaleSq);
    }
}

function ensureImpostorMesh(): THREE.InstancedMesh {
    if (_impostorMesh) return _impostorMesh;

    const geo = new THREE.PlaneGeometry(1, 1);
    const aImpostorAlpha = attribute(IMPOSTOR_ALPHA_ATTR, 'float');
    const instanceColor = varyingProperty('vec3', 'vInstanceColor');
    const mat = new MeshBasicNodeMaterial({
        transparent: true,
        depthWrite: false,
        side: THREE.DoubleSide,
    });
    mat.colorNode = instanceColor;
    mat.opacityNode = aImpostorAlpha.mul(float(0.92));

    _impostorMesh = new THREE.InstancedMesh(geo, mat, _impostorCapacity);
    _impostorMesh.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(_impostorCapacity * 3), 3);
    geo.setAttribute(
        IMPOSTOR_ALPHA_ATTR,
        new THREE.InstancedBufferAttribute(new Float32Array(_impostorCapacity), 1)
    );
    _impostorMesh.frustumCulled = false;
    _impostorMesh.count = 0;
    _impostorMesh.name = 'FoliageFarImpostor';
    _impostorMesh.userData.isFoliageImpostor = true;
    foliageGroup.add(_impostorMesh);
    return _impostorMesh;
}

function _billboardMatrixFromCamera(
    camera: THREE.Camera,
    px: number,
    py: number,
    pz: number,
    width: number,
    height: number
): void {
    _scratchMatrix.makeRotationFromQuaternion(camera.quaternion);
    _scratchScale.set(width, height, 1);
    _scratchMatrix.scale(_scratchScale);
    _scratchMatrix.setPosition(px, py, pz);
    _billboardMatrix.copy(_scratchMatrix);
}

const _billboardMatrix = new THREE.Matrix4();

function accumulateStats(factor: number, cfg: FoliageLodConfig): void {
    if (isInLodBlendBand(factor, cfg)) _stats.blendBand++;
    if (factor >= 3) _stats.culled++;
    else if (factor >= 1.55) _stats.far++;
    else if (factor >= 0.85) _stats.mid++;
    else _stats.hero++;
    _stats.total++;
}

export function getFoliageLodStats(): Readonly<FoliageLodStats> {
    return _stats;
}

export function updateFoliageBatcherLOD(camera: THREE.Camera, delta: number): void {
    const cfg = getFoliageLodConfig();
    if (!cfg.enabled || _meshTracks.size === 0) return;

    syncFoliageLodUniforms();
    uLodDebugHighlight.value = _debugHighlight ? 1.0 : 0.0;

    _stats.hero = 0;
    _stats.mid = 0;
    _stats.far = 0;
    _stats.culled = 0;
    _stats.impostors = 0;
    _stats.blendBand = 0;
    _stats.total = 0;


    const impostor = cfg.useImpostors ? ensureImpostorMesh() : null;
    let alphaAttr: THREE.InstancedBufferAttribute | undefined, alphaArray: Float32Array | undefined, impostorCount = 0;
    const farCullSq = cfg.farCull * cfg.farCull;
    const fogR = uAerialFogColor.value.r;
    const fogG = uAerialFogColor.value.g;
    const fogB = uAerialFogColor.value.b;
    const aerialMix = 0.55;

    if (impostor) {
        alphaAttr = impostor.geometry.getAttribute(IMPOSTOR_ALPHA_ATTR) as THREE.InstancedBufferAttribute;
        alphaArray = alphaAttr.array as Float32Array;
    }

    camera.getWorldPosition(_cameraPos);
    const blendT = cfg.blendSeconds > 0 ? Math.min(1, delta / cfg.blendSeconds) : 1;

    for (const [mesh, smoothed] of _meshTracks) {
        const count = mesh.count;
        if (count === 0) continue;

        if (smoothed.length < mesh.instanceMatrix.count) {
            const reqCount = mesh.instanceMatrix.count;
            const nextCapacity = Math.max(reqCount, smoothed.length * 2);

            const nextSmoothed = new Float32Array(nextCapacity);
            nextSmoothed.set(smoothed);
            _meshTracks.set(mesh, nextSmoothed);

            const oldScales = _meshMaxScales.get(mesh);
            const nextScales = new Float32Array(nextCapacity);
            if (oldScales) nextScales.set(oldScales);
            precomputeMaxScales(mesh, nextScales);
            _meshMaxScales.set(mesh, nextScales);
            continue;
        }

        const maxScales = _meshMaxScales.get(mesh);
        const attr = ensureInstanceLodAttribute(mesh);
        const attrArray = attr.array as Float32Array;
        const matrixArray = mesh.instanceMatrix.array as Float32Array;
        const colorArray = mesh.instanceColor?.array as Float32Array | undefined;

        for (let i = 0; i < count; i++) {
            const offset = i * 16;
            const px = matrixArray[offset + 12];
            const py = matrixArray[offset + 13];
            const pz = matrixArray[offset + 14];

            const dx = px - _cameraPos.x;
            const dy = py - _cameraPos.y;
            const dz = pz - _cameraPos.z;
            const distSq = dx * dx + dy * dy + dz * dz;

            // ⚡ OPTIMIZATION: Bypassed redundant second loop and double distance calculations by updating impostors inline.
            const target = computeTargetLodFactorSq(distSq, cfg);
            const current = smoothed[i];
            const next = current + (target - current) * blendT;
            smoothed[i] = next;
            attrArray[i] = next;
            accumulateStats(next, cfg);

            if (impostor) {
                const factor = next;
                const alpha = impostorAlphaFromFactor(factor, cfg);
                if (alpha > 0.001 && factor < 3 && impostorCount < _impostorCapacity && distSq < farCullSq) {
                    const scaleVal = maxScales ? maxScales[i] : 1;
                    const size = scaleVal * cfg.impostorScaleMul;

                    _billboardMatrixFromCamera(camera, px, py, pz, size, size * cfg.impostorAspect);
                    _billboardMatrix.toArray(impostor.instanceMatrix.array, impostorCount * 16);

                    if (impostor.instanceColor && colorArray) {
                        const dst = impostor.instanceColor.array as Float32Array;
                        const srcOff = i * 3;
                        const dstOff = impostorCount * 3;
                        const sr = colorArray[srcOff];
                        const sg = colorArray[srcOff + 1];
                        const sb = colorArray[srcOff + 2];
                        dst[dstOff] = sr * (1 - aerialMix) + fogR * aerialMix;
                        dst[dstOff + 1] = sg * (1 - aerialMix) + fogG * aerialMix;
                        dst[dstOff + 2] = sb * (1 - aerialMix) + fogB * aerialMix;
                    }

                    alphaArray![impostorCount] = alpha;
                    impostorCount++;
                }
            }
        }

        attr.needsUpdate = true;
    }

    if (impostor) {
        impostor.count = impostorCount;
        impostor.instanceMatrix.needsUpdate = true;
        if (impostor.instanceColor) impostor.instanceColor.needsUpdate = true;
        alphaAttr!.needsUpdate = true;
    } else if (_impostorMesh) {
        _impostorMesh.count = 0;
    }
    _stats.impostors = impostorCount;
}

export function refreshFoliageLodMesh(mesh: THREE.InstancedMesh, oldMesh?: THREE.InstancedMesh): void {
    ensureInstanceLodAttribute(mesh);
    const prev = oldMesh ? _meshTracks.get(oldMesh) : _meshTracks.get(mesh);
    const prevScales = oldMesh ? _meshMaxScales.get(oldMesh) : _meshMaxScales.get(mesh);
    const reqCount = mesh.instanceMatrix.count;

    // ⚡ OPTIMIZATION: Bypassed repeated Float32Array allocations by reusing buffers when capacity allows
    let next: Float32Array;
    if (prev && prev.length >= reqCount) {
        next = prev;
    } else {
        const nextCapacity = prev ? Math.max(reqCount, prev.length * 2) : reqCount;
        next = new Float32Array(nextCapacity);
        if (prev) {
            next.set(prev);
        }
    }

    _meshTracks.set(mesh, next);

    let nextScales: Float32Array;
    if (prevScales && prevScales.length >= reqCount) {
        nextScales = prevScales;
    } else {
        const nextCapacity = prevScales ? Math.max(reqCount, prevScales.length * 2) : reqCount;
        nextScales = new Float32Array(nextCapacity);
        if (prevScales) {
            nextScales.set(prevScales);
        }
    }
    precomputeMaxScales(mesh, nextScales);
    _meshMaxScales.set(mesh, nextScales);

    if (oldMesh && oldMesh !== mesh) {
        _meshTracks.delete(oldMesh);
        _meshMaxScales.delete(oldMesh);
    }
}

export function getFoliageLodImpostorMesh(): THREE.InstancedMesh | null {
    return _impostorMesh;
}

export function disposeFoliageBatcherLOD(): void {
    _targets.length = 0;
    _meshTracks.clear();
    _meshMaxScales.clear();
    if (_impostorMesh) {
        safeRemoveAndDispose(foliageGroup as unknown as THREE.Scene, _impostorMesh);
        _impostorMesh = null;
    }
}

// Dev hooks
if (typeof window !== 'undefined') {
    const w = window as unknown as {
        __foliageLodStats?: () => Readonly<FoliageLodStats>;
        __setFoliageLodDebugHighlight?: (enabled: boolean) => void;
    };
    w.__foliageLodStats = getFoliageLodStats;
    w.__setFoliageLodDebugHighlight = setFoliageLodDebugHighlight;
}

import * as THREE from 'three';
/**
 * Shared TSL uniform nodes for biome-specific music reactivity.
 *
 * These nodes are created ONCE at module-init time and mutated each frame
 * by the music-reactivity binding system — zero per-frame allocations.
 *
 * Material graphs: import BiomeUniforms and reference e.g.
 *   BiomeUniforms.arpeggioGrove.shimmer  (a TSL UniformNode<float>)
 *
 * Update loop: mutate .value only — never reassign the node itself.
 *   BiomeUniforms.arpeggioGrove.shimmer.value = 0.75;
 */

import { DataTexture, RGBAFormat, HalfFloatType, Color, NearestFilter, DataUtils } from 'three';
import { uniform, texture, vec2, mix, float } from 'three/tsl';
import { CONFIG } from '../core/config.ts';

export const BiomeUniforms = {
    /**
     * Arpeggio Grove — tracker channels defined in assets/music-bindings.json
     * under "arpeggio_grove".
     */
    arpeggioGrove: {
        /** 0–1 sparkle/shimmer emissive boost driven by melody channels. */
        shimmer: uniform(0.0),
        /** 0–1 hue-mix factor — blends frond colour towards an accent tint. */
        hueShift: uniform(0.0),
        noteColor: uniform(new THREE.Color(0xffffff)),
    },

    /**
     * Crystalline Nebula — tracker channels defined in assets/music-bindings.json
     * under "crystalline_nebula".
     */
    crystallineNebula: {
        /** 0–1 shimmer emissive boost on lotus rings. */
        shimmer: uniform(0.0),
        /** ≥1 amplitude multiplier for the lotus bass-pulse displacement. */
        amplitudeScale: uniform(1.0),
        noteColor: uniform(new THREE.Color(0xffffff)),
    },

    /**
     * Sky & Moon — tracker channels defined in assets/music-bindings.json
     * under "sky_moon".
     */
    skyMoon: {
        /** RGB color for note reactivity */
        moonNoteColor: uniform(new THREE.Color(0xffffff)),
        /** 0-1 intensity based on channels */
        moonIntensity: uniform(0.0),
    },

    /**
     * Global — screen-wide or ambient effects (e.g. chromatic pulse overlay).
     */

    /**
     * Musical Flora — tracker channels defined in assets/music-bindings.json
     * under "musical_flora".
     */
    musicalFlora: {
        shimmer: uniform(0.0),
        hueShift: uniform(0.0),
        noteColor: uniform(new THREE.Color(0xffffff)),
    },

    /**
     * Lake Features — tracker channels defined in assets/music-bindings.json
     * under "lake_features".
     */
    lakeFeatures: {
        shimmer: uniform(0.0),
        hueShift: uniform(0.0),
        noteColor: uniform(new THREE.Color(0xffffff)),
    },

    /**
     * Gem Canopy — hanging jewel fruits; channels in music-bindings.json gem_canopy.
     */
    gemCanopy: {
        shimmer: uniform(0.0),
        hueShift: uniform(0.0),
        noteColor: uniform(new THREE.Color(0xffffff)),
    },

    /**
     * Sky Islands — stacked floating landmasses; channels in music-bindings.json sky_islands.
     * fogDensity drives mist-layer atmosphere (0–1).
     */
    skyIslands: {
        shimmer: uniform(0.0),
        hueShift: uniform(0.0),
        noteColor: uniform(new THREE.Color(0xffffff)),
        /** 0–1 mist/fog density for low-mist layer atmosphere. Visual Impact: soft pastel haze */
        fogDensity: uniform(0.15),
    },

    /**
     * Sugar Caves — subterranean crystal ribs; channels in music-bindings.json sugar_caves.
     */
    sugarCaves: {
        shimmer: uniform(0.0),
        hueShift: uniform(0.0),
        noteColor: uniform(new THREE.Color(0xffffff)),
    },

    global: {
        /** 0–1 shimmer emissive boost for global effects. */
        shimmer: uniform(0.0),
        /** 0–1 hue-mix factor for global color shifts. */
        hueShift: uniform(0.0),
        noteColor: uniform(new THREE.Color(0xffffff)),
    },
} as const;

// ---------------------------------------------------------------------------
// Sky / Moon note-colour uniforms (Moon Dance feature)
// ---------------------------------------------------------------------------

/**
 * TSL uniforms for the note-driven sky/moon hue shift.
 * Created once at module init — mutate .value only each frame.
 *
 * noteIndex : float 0–127, maps into skyLutData; GPU normalises to UV [0,1].
 * intensity : float 0–1, mix factor between base sky/moon colour and note colour.
 *             Set to 0 during daytime so the feature has zero impact on day scenes.
 */

export const LuminousPlantUniforms = {
    /** 0-1 intensity based on channels */
    intensity: uniform(0.0),
    /** RGB color for note reactivity */
    noteColor: uniform(new THREE.Color(0xffffff)),
    /** Active note index for precise mapping (0-127) */
    noteIndex: uniform(0.0),
} as const;

export const SkyUniforms = {
    noteIndex: uniform(0.0),
    intensity: uniform(0.0),
} as const;

/**
 * 128-slot RGBA-float LUT: maps note index → hue colour.
 * Shared between GPU DataTexture (skyNoteColorNode) and CPU moon lerp.
 *
 * Uses chromatic colors mapped from CONFIG.noteColorMap.sky
 */ const CHROMATIC_SCALE = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

export const skyLutData = new Float32Array(128 * 4);

(function buildSkyLut() {
    const c = new Color();

    // Use configurable note colors from CONFIG (preferred)
    // Falls back to the old rainbow if CONFIG.noteColorMap is not available
    const noteColorMap = CONFIG?.noteColorMap?.global || {};

    for (let i = 0; i < 128; i++) {
        const chromaticIdx = Math.floor((i * 12) / 128);
        const pitchClass = chromaticIdx % 12;
        const noteName = CHROMATIC_SCALE[pitchClass];

        const hexColor = noteColorMap[noteName] || 0xffffff;

        c.setHex(hexColor);

        skyLutData[i * 4 + 0] = c.r;
        skyLutData[i * 4 + 1] = c.g;
        skyLutData[i * 4 + 2] = c.b;
        skyLutData[i * 4 + 3] = 1.0;
    }
})();

// r32float textures are non-filterable in WebGPU — Three.js falls back to
// textureLoad(...) without the required mip-level argument, causing a WGSL
// parse error.  HalfFloatType (r16float) IS filterable, so Three.js can use
// textureSample instead.  The same fix is applied in ground-heightmap.ts.
const _skyLutHalf = new Uint16Array(128 * 4);
for (let i = 0; i < 128 * 4; i++) _skyLutHalf[i] = DataUtils.toHalfFloat(skyLutData[i]);
const _skyLutTex = new DataTexture(_skyLutHalf, 128, 1, RGBAFormat, HalfFloatType);
_skyLutTex.minFilter = NearestFilter;
_skyLutTex.magFilter = NearestFilter;
_skyLutTex.needsUpdate = true;

/**
 * TSL node: samples the note-colour LUT for the current SkyUniforms.noteIndex.
 * UV uses pixel-centre addressing: (noteIndex + 0.5) / 128 keeps sampling
 * strictly within the 128-slot range and avoids edge/wrap artefacts.
 * Safe to use in both the sky dome colorNode and the moon emissiveNode.
 */
export const skyNoteColorNode = texture(
    _skyLutTex,
    vec2(SkyUniforms.noteIndex.add(0.5).div(128.0), 0.5)
).rgb;

/**
 * 128-slot RGBA-float LUT: maps note index -> hue colour for Luminous Plants.
 */
export const luminousPlantsLutData = new Float32Array(128 * 4);
(function buildLuminousPlantsLut() {
    const c = new Color();
    const CHROMATIC_SCALE = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    const plantMap = CONFIG.noteColorMap.luminous_plants || CONFIG.noteColorMap.global;

    for (let i = 0; i < 128; i++) {
        const chromaticIdx = Math.floor((i / 128) * 12);
        const noteName = CHROMATIC_SCALE[chromaticIdx];
        const hex = plantMap[noteName] || 0xffffff;

        c.setHex(hex);
        luminousPlantsLutData[i * 4 + 0] = c.r;
        luminousPlantsLutData[i * 4 + 1] = c.g;
        luminousPlantsLutData[i * 4 + 2] = c.b;
        luminousPlantsLutData[i * 4 + 3] = 1.0;
    }
})();

const _luminousPlantsLutHalf = new Uint16Array(128 * 4);
for (let i = 0; i < 128 * 4; i++)
    _luminousPlantsLutHalf[i] = DataUtils.toHalfFloat(luminousPlantsLutData[i]);
const _luminousPlantsLutTex = new DataTexture(
    _luminousPlantsLutHalf,
    128,
    1,
    RGBAFormat,
    HalfFloatType
);
_luminousPlantsLutTex.minFilter = NearestFilter;
_luminousPlantsLutTex.magFilter = NearestFilter;
_luminousPlantsLutTex.needsUpdate = true;

/**
 * TSL node: samples the note-colour LUT for the current LuminousPlantUniforms.noteIndex.
 */
export const luminousPlantsNoteColorNode = texture(
    _luminousPlantsLutTex,
    vec2(LuminousPlantUniforms.noteIndex.add(0.5).div(128.0), 0.5)
).rgb;

/** Gem canopy note tint — driven by music-reactivity noteColor lerp (same pattern as arpeggio grove). */
export const gemCanopyNoteColorNode = BiomeUniforms.gemCanopy.noteColor;

/** Sky islands note tint — driven by music-reactivity noteColor lerp. */
export const skyIslandsNoteColorNode = BiomeUniforms.skyIslands.noteColor;

// ---------------------------------------------------------------------------
// Biome tagging & uniform lookup (foundational for scalable music reactivity)
// ---------------------------------------------------------------------------

/**
 * Lightweight biome identifier.
 * Used to tag foliage objects and to look up the correct uniform group without
 * hard-coded imports everywhere.
 *
 * Add new values here + corresponding entry in BiomeUniforms (or alias) when
 * introducing a new musical biome.
 */
export type BiomeId =
    | 'arpeggio_grove'
    | 'crystalline_nebula'
    | 'luminous_plants'
    | 'sky_moon'
    | 'global'
    | 'musical_flora'
    | 'lake_features'
    | 'gem_canopy'
    | 'sky_islands'
    | 'sugar_caves';

/**
 * Returns the appropriate uniform group for a given biome tag.
 * Falls back to arpeggioGrove for unknown / unset values (safe default).
 *
 * Usage in batchers / material graphs:
 *   const uniforms = getBiomeUniforms(biome);
 *   ... uniforms.noteColor ...
 *
 * This makes adding a third (or Nth) biome cheap and prevents wiring drift.
 */
export function getBiomeUniforms(biome: BiomeId | string | undefined) {
    switch (biome) {
        case 'arpeggio_grove':
            return BiomeUniforms.arpeggioGrove;
        case 'crystalline_nebula':
            return BiomeUniforms.crystallineNebula;
        case 'luminous_plants':
            // Luminous primarily uses its own LuminousPlantUniforms for intensity/noteIndex,
            // but we expose the noteColor here for wave / shared tinting use cases.
            return {
                ...BiomeUniforms.arpeggioGrove, // shape compatibility if someone expects the common fields
                noteColor: LuminousPlantUniforms.noteColor as any,
                // intensity / noteIndex live on LuminousPlantUniforms directly
            } as any;
        case 'sky_moon':
            // Sky/Moon uses different key names internally; alias them to the common shape.
            return {
                shimmer: BiomeUniforms.skyMoon.moonIntensity as any,
                hueShift: uniform(0.0),
                noteColor: BiomeUniforms.skyMoon.moonNoteColor as any,
            };
        case 'musical_flora':
            return BiomeUniforms.musicalFlora;
        case 'lake_features':
            return BiomeUniforms.lakeFeatures;
        case 'gem_canopy':
            return BiomeUniforms.gemCanopy;
        case 'sky_islands':
            return BiomeUniforms.skyIslands;
        case 'sugar_caves':
            return BiomeUniforms.sugarCaves;
        case 'global':
            return BiomeUniforms.global;
        default:
            return BiomeUniforms.arpeggioGrove;
    }
}

/** Convenience re-export of the type for consumers that only need the id. */
export type { BiomeId as BiomeTag };

// ---------------------------------------------------------------------------
// Circadian uniforms — written by CircadianController once per frame.
// Consumed by opted-in foliage batchers; zero cost for batchers that ignore them.
// ---------------------------------------------------------------------------

/**
 * 0 = night, 1 = day. Lerped by CircadianController each frame.
 * Read-only from batcher TSL; mutate only via CircadianController.
 */
export const uCircadianPhase = uniform(0.5);

/**
 * Additive pose offset to add on top of the music-driven pose.
 * Precomputed by CircadianController: lerp(nightPoseOffset, dayPoseOffset, ease(phase)).
 */
export const uCircadianPoseOffset = uniform(0.0);

/**
 * TSL helper — nocturnal bioluminescence gate.
 * phase=0 (night) → nightGlowMultiplier; phase=1 (day) → 1.0.
 * Prefer this over hand-rolled mix() so batchers stay in sync with CONFIG.circadian.
 */
export function circadianNightGlowMult() {
    return mix(float(CONFIG.circadian.nightGlowMultiplier), float(1.0), uCircadianPhase);
}

/**
 * TSL helper — diurnal rest dim (flowers / canopy that sleep at night).
 * phase=0 (night) → nightFloor; phase=1 (day) → 1.0.
 * Music wave / player interaction still override via separate additive terms.
 */
export function circadianDayGlowMult(nightFloor: number = 0.25) {
    return mix(float(nightFloor), float(1.0), uCircadianPhase);
}

/**
 * Deferred Visual Loader
 * 
 * A prioritized, batched loader for non-critical visual elements.
 * Spawns visual effects over multiple frames to prevent CPU/GPU spikes.
 * 
 * Usage Example (replacing initDeferredVisuals()):
 * 
 * ```typescript
 * import { DeferredLoader, LoadPriority } from './systems/deferred-loader';
 * import { 
 *   createFluidFog, createAurora, createChromaticPulse, 
 *   createMelodyRibbon, createSparkleTrail, createDiscoveryEffect,
 *   createDandelionSeedSystem, createImpactSystem
 * } from './foliage';
 * import { initCelestialBodies } from './foliage/celestial-bodies';
 * import { jitterMineSystem } from './gameplay/jitter-mines';
 * import { createHarpoonLine } from './gameplay/harpoon-line';
 * 
 * // Create the loader
 * const visualLoader = new DeferredLoader();
 * 
 * // Add items by priority
 * visualLoader.add(LoadPriority.CRITICAL, 'fluidFog', () => {
 *   const fog = createFluidFog(200, 200);
 *   scene.add(fog);
 *   return fog;
 * });
 * 
 * visualLoader.add(LoadPriority.HIGH, 'aurora', () => {
 *   const aurora = createAurora();
 *   scene.add(aurora);
 *   return aurora;
 * });
 * 
 * visualLoader.add(LoadPriority.HIGH, 'chromaticPulse', () => {
 *   const pulse = createChromaticPulse();
 *   camera.add(pulse);
 *   return pulse;
 * });
 * 
 * visualLoader.add(LoadPriority.MEDIUM, 'celestialBodies', () => {
 *   initCelestialBodies(scene);
 *   return true;
 * });
 * 
 * visualLoader.add(LoadPriority.MEDIUM, 'dandelionSeedSystem', () => {
 *   const seeds = createDandelionSeedSystem();
 *   scene.add(seeds);
 *   return seeds;
 * });
 * 
 * visualLoader.add(LoadPriority.LOW, 'melodyRibbon', () => {
 *   return createMelodyRibbon(scene);
 * });
 * 
 * visualLoader.add(LoadPriority.LOW, 'sparkleTrail', () => {
 *   const trail = createSparkleTrail();
 *   scene.add(trail);
 *   return trail;
 * });
 * 
 * visualLoader.add(LoadPriority.LOW, 'discoveryEffect', () => {
 *   const effect = createDiscoveryEffect();
 *   scene.add(effect.mesh);
 *   return effect;
 * });
 * 
 * // Listen for progress events
 * visualLoader.on('progress', ({ loaded, total, percent }) => {
 *   console.log(`Visuals loaded: ${loaded}/${total} (${percent}%)`);
 * });
 * 
 * visualLoader.on('tierComplete', ({ priority, priorityName }) => {
 *   console.log(`Priority tier ${priorityName} complete!`);
 * });
 * 
 * visualLoader.on('complete', ({ loaded }) => {
 *   console.log(`All ${loaded} visual elements loaded!`);
 * });
 * 
 * // Start loading (processes 1-2 items per frame)
 * visualLoader.start();
 * 
 * // Optional: Pause/resume loading
 * // visualLoader.pause();
 * // visualLoader.resume();
 * 
 * // Optional: Check status
 * // const status = visualLoader.getStatus();
 * // console.log(status.isComplete, status.percent);
 * ```
 */

import { spawnTracker } from '../world/spawn-tracker.ts';

export enum LoadPriority {
  CRITICAL = 0,  // Player sees immediately - load first
  HIGH = 1,      // Visible but not immediately
  MEDIUM = 2,    // Background elements
  LOW = 3,       // Optional/polish effects
}

const PRIORITY_NAMES: Record<LoadPriority, string> = {
  [LoadPriority.CRITICAL]: 'CRITICAL',
  [LoadPriority.HIGH]: 'HIGH',
  [LoadPriority.MEDIUM]: 'MEDIUM',
  [LoadPriority.LOW]: 'LOW',
};

interface LoadItem<T = unknown> {
  id: string;
  priority: LoadPriority;
  loader: () => T;
  result?: T;
  loaded: boolean;
}

interface ProgressEvent {
  loaded: number;
  total: number;
  percent: number;
  currentItem: string | null;
}

interface TierCompleteEvent {
  priority: LoadPriority;
  priorityName: string;
  itemsInTier: number;
}

interface CompleteEvent {
  loaded: number;
  total: number;
  results: Map<string, unknown>;
}

interface ErrorEvent {
  id: string;
  priority: LoadPriority;
  error: Error;
}

type EventType = 'progress' | 'tierComplete' | 'complete' | 'error' | 'itemLoaded';
type EventCallback<T> = (data: T) => void;

export class DeferredLoader {
  private items: LoadItem[] = [];
  private loadedCount = 0;
  private isRunning = false;
  private isPaused = false;
  private currentIndex = 0;
  private completedTiers = new Set<LoadPriority>();
  private results = new Map<string, unknown>();
  private listeners: Map<EventType, EventCallback<unknown>[]> = new Map();
  private rafId: number | null = null;
  private batchSize: number;

  // Use requestIdleCallback if available, fallback to setTimeout(0)
  private useIdleCallback: boolean;
  private idleTimeout: number;

  constructor(options: { batchSize?: number; useIdleCallback?: boolean; idleTimeout?: number } = {}) {
    this.batchSize = options.batchSize ?? 1; // Process 1 item per batch by default for smooth frame times
    this.useIdleCallback = options.useIdleCallback ?? true;
    this.idleTimeout = options.idleTimeout ?? 16; // 16ms = 1 frame at 60fps
  }

  /**
   * Add a visual element to the loading queue
   */
  add<T>(priority: LoadPriority, id: string, loader: () => T): this {
    this.items.push({
      id,
      priority,
      loader,
      loaded: false,
    });
    // Sort by priority so critical items load first
    this.items.sort((a, b) => a.priority - b.priority);
    return this;
  }

  /**
   * Start loading visual elements in batches
   */
  start(): this {
    if (this.isRunning) return this;

    this.isRunning = true;
    this.isPaused = false;
    this.scheduleNextBatch();

    return this;
  }

  /**
   * Pause loading (call resume() to continue)
   */
  pause(): this {
    this.isPaused = true;
    return this;
  }

  /**
   * Resume loading after pause
   */
  resume(): this {
    if (!this.isRunning || !this.isPaused) return this;

    this.isPaused = false;
    this.scheduleNextBatch();
    return this;
  }

  /**
   * Stop loading completely (cannot be resumed)
   */
  stop(): this {
    this.isRunning = false;
    this.isPaused = false;
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    return this;
  }

  /**
   * Get current loading status
   */
  getStatus(): {
    isRunning: boolean;
    isPaused: boolean;
    isComplete: boolean;
    loaded: number;
    total: number;
    percent: number;
    currentPriority: LoadPriority | null;
  } {
    const total = this.items.length;
    const percent = total > 0 ? Math.round((this.loadedCount / total) * 100) : 100;
    const currentItem = this.items[this.currentIndex];

    return {
      isRunning: this.isRunning,
      isPaused: this.isPaused,
      isComplete: this.loadedCount >= total && total > 0,
      loaded: this.loadedCount,
      total,
      percent,
      currentPriority: currentItem?.priority ?? null,
    };
  }

  /**
   * Get the result of a loaded item
   */
  getResult<T>(id: string): T | undefined {
    return this.results.get(id) as T | undefined;
  }

  /**
   * Get all loaded results
   */
  getAllResults(): Map<string, unknown> {
    return new Map(this.results);
  }

  /**
   * Check if a specific item has been loaded
   */
  isLoaded(id: string): boolean {
    const item = this.items.find(i => i.id === id);
    return item?.loaded ?? false;
  }

  /**
   * Register an event listener
   */
  on<T>(event: 'progress', callback: EventCallback<ProgressEvent>): void;
  on<T>(event: 'tierComplete', callback: EventCallback<TierCompleteEvent>): void;
  on<T>(event: 'complete', callback: EventCallback<CompleteEvent>): void;
  on<T>(event: 'error', callback: EventCallback<ErrorEvent>): void;
  on<T>(event: 'itemLoaded', callback: EventCallback<{ id: string; priority: LoadPriority; result: unknown }>): void;
  on<T>(event: EventType, callback: EventCallback<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    this.listeners.get(event)!.push(callback as EventCallback<unknown>);
  }

  /**
   * Remove an event listener
   */
  off(event: EventType, callback: EventCallback<unknown>): void {
    const callbacks = this.listeners.get(event);
    if (callbacks) {
      const index = callbacks.indexOf(callback);
      if (index > -1) {
        callbacks.splice(index, 1);
      }
    }
  }

  private emit<T>(event: EventType, data: T): void {
    const callbacks = this.listeners.get(event);
    if (callbacks) {
      callbacks.forEach(cb => {
        try {
          cb(data);
        } catch (err) {
          console.error(`[DeferredLoader] Error in '${event}' handler:`, err);
        }
      });
    }
  }

  private scheduleNextBatch(): void {
    if (!this.isRunning || this.isPaused) return;
    if (this.currentIndex >= this.items.length) return;

    if (this.useIdleCallback && typeof requestIdleCallback !== 'undefined') {
      requestIdleCallback(
        (deadline) => this.loadNextBatch(deadline),
        { timeout: this.idleTimeout }
      );
    } else {
      // Fallback: use requestAnimationFrame for frame-budget-friendly loading
      this.rafId = requestAnimationFrame(() => {
        this.loadNextBatch(null);
      });
    }
  }

  private loadNextBatch(deadline: IdleDeadline | null): void {
    if (!this.isRunning || this.isPaused) return;

    const itemsToProcess = Math.min(this.batchSize, this.items.length - this.currentIndex);
    const startPriority = this.items[this.currentIndex]?.priority ?? null;
    let itemsProcessedInTier = 0;

    for (let i = 0; i < itemsToProcess; i++) {
      // Check if we're running out of frame time (if using requestIdleCallback)
      if (deadline && deadline.timeRemaining() < 1) {
        this.scheduleNextBatch();
        return;
      }

      const item = this.items[this.currentIndex];
      if (!item || item.loaded) {
        this.currentIndex++;
        continue;
      }

      try {
        const result = item.loader();
        item.result = result;
        item.loaded = true;
        this.results.set(item.id, result);
        this.loadedCount++;
        itemsProcessedInTier++;

        this.emit('itemLoaded', {
          id: item.id,
          priority: item.priority,
          result,
        });

        this.emit('progress', {
          loaded: this.loadedCount,
          total: this.items.length,
          percent: Math.round((this.loadedCount / this.items.length) * 100),
          currentItem: item.id,
        });

        this.currentIndex++;

        // Check if we completed a priority tier
        const nextItem = this.items[this.currentIndex];
        if (nextItem?.priority !== item.priority || this.currentIndex >= this.items.length) {
          if (!this.completedTiers.has(item.priority)) {
            this.completedTiers.add(item.priority);
            this.emit('tierComplete', {
              priority: item.priority,
              priorityName: PRIORITY_NAMES[item.priority],
              itemsInTier: itemsProcessedInTier,
            });
          }
        }
      } catch (error) {
        spawnTracker.recordFailure('deferred_loader_item', error, {
          context: `deferred-loader:${item.id}`,
          countAttempt: true,
        });
        console.error(`[DeferredLoader] Failed to load '${item.id}':`, error);
        this.emit('error', {
          id: item.id,
          priority: item.priority,
          error: error instanceof Error ? error : new Error(String(error)),
        });
        spawnTracker.recordAttempt(`deferred:${item.id}`, false, error);
        item.loaded = true; // Mark as loaded to skip in future
        this.currentIndex++;
      }
    }

    // Check if all items are loaded
    if (this.currentIndex >= this.items.length) {
      this.isRunning = false;
      this.emit('complete', {
        loaded: this.loadedCount,
        total: this.items.length,
        results: this.results,
      });
    } else {
      // Schedule next batch
      this.scheduleNextBatch();
    }
  }
}

// Default export for convenience
export default DeferredLoader;

/**
 * @file discovery-optimized.ts
 * @brief Spatial grid-optimized flora discovery system
 * 
 * Replaces O(N) distance checks with O(1) spatial grid lookups.
 * Uses WASM batch processing for maximum efficiency.
 * Integrates with DiscoveryPersistence for timestamped tracking.
 * 
 * @example
 * ```ts
 * import { OptimizedDiscoverySystem } from './discovery-optimized';
 * import { DISCOVERY_MAP } from './discovery_map';
 * 
 * const discovery = new OptimizedDiscoverySystem();
 * 
 * // Register all discoverable objects during world generation
 * for (const obj of animatedFoliage) {
 *     const type = obj.userData.type;
 *     if (DISCOVERY_MAP[type]) {
 *         discovery.registerObject(obj.position, type);
 *     }
 * }
 * 
 * // In animation loop - O(1) lookup
 * const discovered = discovery.checkDiscovery(player.position);
 * if (discovered) {
 *     showToast(`Discovered: ${discovered.name}!`, discovered.icon);
 * }
 * ```
 */

import * as THREE from 'three';
import { isEmscriptenReady, getEmscriptenInstance, getNativeFunc } from '../utils/wasm-loader-core.ts';
import { getWasmInstance } from '../utils/wasm-loader.ts';
import { discoveryPersistence } from './discovery-persistence.ts';
import { discoverySystem } from './discovery.ts';
import { DISCOVERY_MAP } from './discovery_map.ts';

// Type definition for discovery info
interface DiscoveryInfo {
    name: string;
    icon: string;
}

// Object tracking
interface RegisteredObject {
    index: number;
    type: string;
    discoveryInfo: DiscoveryInfo;
}

// Squared discovery radius matching assembly/discovery.ts (5 m)
const CPP_DISCOVERY_RADIUS_SQ = 25.0;
// Max results per queryDiscoveries call (small buffer, discoveries are rare)
const CPP_MAX_QUERY_RESULTS = 16;

/**
 * Optimized discovery system using WASM spatial grid.
 * Routing priority: C++/Emscripten → AssemblyScript → JS fallback.
 */
export class OptimizedDiscoverySystem {
    private wasmInitialized = false;
    private objectRegistry = new Map<number, RegisteredObject>();
    private typeToObjects = new Map<string, number[]>();
    private nextId = 0;

    // AssemblyScript WASM function bindings
    private wasmInitDiscovery: (() => void) | null = null;
    private wasmRegisterObject: ((x: number, y: number, z: number, typeId: number) => number) | null = null;
    private wasmCheckDiscovery: ((x: number, y: number, z: number, typeFilter: number) => number) | null = null;
    private wasmMarkDiscovered: ((id: number) => void) | null = null;
    private wasmIsDiscovered: ((id: number) => number) | null = null;
    private wasmGetTypeId: ((id: number) => number) | null = null;
    private wasmResetAll: (() => void) | null = null;
    private wasmGetUndiscoveredCount: (() => number) | null = null;

    // Type ID encoding for the AssemblyScript path (map type string ↔ numeric ID)
    private typeToId = new Map<string, number>();
    private idToType = new Map<number, string>();
    private nextTypeId = 1;

    // C++/Emscripten function bindings
    private cppInitialized = false;
    private cppRegister: ((...args: number[]) => number) | null = null;
    private cppQuery: ((...args: number[]) => number) | null = null;
    private cppClear: ((...args: number[]) => number) | null = null;
    private cppMalloc: ((size: number) => number) | null = null;
    private cppFree: ((ptr: number) => void) | null = null;
    private cppHeap32: Int32Array | null = null;
    private cppOutPtr = 0; // pre-allocated output buffer in Emscripten heap

    private _initialized = false;

    private ensureInitialized(): void {
        if (this._initialized) return;
        this._initialized = true;
        this.initWasm();
        this.loadPersistedDiscoveries();
    }

    /**
     * Initialize backends: C++ first, then AssemblyScript.
     */
    private initWasm(): void {
        // --- C++ / Emscripten path (preferred) ---
        if (isEmscriptenReady()) {
            try {
                const emInst = getEmscriptenInstance() as any;
                const initGrid  = getNativeFunc('initDiscoveryGrid');
                const register  = getNativeFunc('registerDiscoverable');
                const query     = getNativeFunc('queryDiscoveries');
                const clear     = getNativeFunc('clearDiscoveryGrid');
                const malloc    = emInst?._malloc as ((n: number) => number) | undefined;
                const free      = emInst?._free  as ((p: number) => void)   | undefined;
                const heap32    = emInst?.HEAP32  as Int32Array | undefined;

                if (initGrid && register && query && clear && malloc && heap32) {
                    // Allocate output buffer once (CPP_MAX_QUERY_RESULTS × 4 bytes)
                    const outPtr = malloc(CPP_MAX_QUERY_RESULTS * 4);
                    if (outPtr) {
                        // initDiscoveryGrid(cols=16, rows=16, originX=-128, originZ=-128, cellSize=16)
                        initGrid(16, 16, -128, -128, 16);
                        this.cppRegister    = register;
                        this.cppQuery       = query;
                        this.cppClear       = clear;
                        this.cppMalloc      = malloc;
                        this.cppFree        = free ?? null;
                        this.cppHeap32      = heap32;
                        this.cppOutPtr      = outPtr;
                        this.cppInitialized = true;
                        console.log('[OptimizedDiscovery] C++ spatial grid initialized');
                        return; // skip ASC init
                    }
                }
            } catch (e) {
                console.warn('[OptimizedDiscovery] C++ discovery init failed, trying ASC:', e);
            }
        }

        // --- AssemblyScript path (fallback) ---
        const instance = getWasmInstance();
        if (!instance) {
            console.log('[OptimizedDiscovery] WASM not available, will use JS fallback');
            return;
        }

        this.wasmInitDiscovery        = (instance.exports as any).initDiscoverySystem;
        this.wasmRegisterObject       = (instance.exports as any).registerDiscoveryObject;
        this.wasmCheckDiscovery       = (instance.exports as any).checkDiscoverySpatial;
        this.wasmMarkDiscovered       = (instance.exports as any).markDiscovered;
        this.wasmIsDiscovered         = (instance.exports as any).isObjectDiscovered;
        this.wasmGetTypeId            = (instance.exports as any).getDiscoveryTypeId;
        this.wasmResetAll             = (instance.exports as any).resetAllDiscoveries;
        this.wasmGetUndiscoveredCount = (instance.exports as any).getUndiscoveredCount;

        if (this.wasmInitDiscovery) {
            // The discovery system writes to addresses up to ~276KB. Guard against
            // running on a WASM build whose initialMemory is too small (old 4-page
            // binaries only have 256KB), which would throw RuntimeError immediately.
            const mem = (instance.exports as any).memory as WebAssembly.Memory;
            const DISCOVERY_REQUIRED_BYTES = 280000;
            if (mem && mem.buffer.byteLength < DISCOVERY_REQUIRED_BYTES) {
                console.warn('[OptimizedDiscovery] WASM memory too small for discovery system, using JS fallback');
                this.wasmInitDiscovery = null;
                return;
            }
            try {
                this.wasmInitDiscovery();
                this.wasmInitialized = true;
                console.log('[OptimizedDiscovery] ASC spatial grid initialized');
            } catch (e) {
                console.warn('[OptimizedDiscovery] WASM initDiscoverySystem failed, using JS fallback:', e);
                this.wasmInitDiscovery = null;
            }
        }
    }

    /**
     * Load persisted discoveries and sync with WASM
     */
    private loadPersistedDiscoveries(): void {
        const persisted = discoveryPersistence.getAllDiscoveries();

        for (const discovery of persisted) {
            // Sync with legacy discoverySystem for backward compatibility
            if (!discoverySystem.isDiscovered(discovery.id)) {
                const info = DISCOVERY_MAP[discovery.id];
                if (info) {
                    // Add to legacy system without triggering save
                    (discoverySystem as any).discoveredItems?.add(discovery.id);
                }
            }
        }

        if (persisted.length > 0) {
            console.log(`[OptimizedDiscovery] Loaded ${persisted.length} persisted discoveries`);
        }
    }

    /**
     * Get or create a numeric type ID for a type string
     */
    private getTypeId(type: string): number {
        if (!this.typeToId.has(type)) {
            const id = this.nextTypeId++;
            this.typeToId.set(type, id);
            this.idToType.set(id, type);
        }
        return this.typeToId.get(type)!;
    }

    /**
     * Register a discoverable object.
     * @param position - World position
     * @param type - Object type (e.g., 'mushroom', 'flower')
     * @returns Registration ID, or -1 if failed
     */
    registerObject(position: THREE.Vector3, type: string): number {
        this.ensureInitialized();
        const discoveryInfo = DISCOVERY_MAP[type];
        if (!discoveryInfo) {
            return -1;
        }

        // Skip types already discovered (from persistence)
        if (discoveryPersistence.hasDiscovery(type) || discoverySystem.isDiscovered(type)) {
            return -1;
        }

        const id = this.nextId++;

        // C++ path: passes the JS id directly so queryDiscoveries returns it verbatim
        if (this.cppInitialized && this.cppRegister) {
            this.cppRegister(id, position.x, position.z);
        } else if (this.wasmInitialized && this.wasmRegisterObject) {
            // ASC path: needs a numeric typeId
            const typeId = this.getTypeId(type);
            const wasmIndex = this.wasmRegisterObject(position.x, position.y, position.z, typeId);
            this.objectRegistry.set(id, { index: wasmIndex, type, discoveryInfo });
            if (!this.typeToObjects.has(type)) this.typeToObjects.set(type, []);
            this.typeToObjects.get(type)!.push(id);
            return id;
        }

        // JS registry (C++ path also needs this for the id→type lookup)
        this.objectRegistry.set(id, { index: id, type, discoveryInfo });
        if (!this.typeToObjects.has(type)) this.typeToObjects.set(type, []);
        this.typeToObjects.get(type)!.push(id);

        return id;
    }

    /**
     * Check for discoveries at a player position.
     * Routes to C++ when the Emscripten module is loaded, otherwise AssemblyScript.
     * @param playerPos - Player position
     * @returns Discovery info if something was discovered, null otherwise
     */
    checkDiscovery(playerPos: THREE.Vector3): DiscoveryInfo | null {
        this.ensureInitialized();
        if (this.cppInitialized) {
            return this.checkDiscoveryCpp(playerPos);
        }
        if (!this.wasmInitialized || !this.wasmCheckDiscovery) {
            return this.checkDiscoveryJS(playerPos);
        }

        // AssemblyScript spatial grid
        const discoveredIndex = this.wasmCheckDiscovery(playerPos.x, playerPos.y, playerPos.z, 0);

        if (discoveredIndex >= 0) {
            const typeId = this.wasmGetTypeId!(discoveredIndex);
            const type = this.idToType.get(typeId);

            if (type) {
                const obj = this.findObjectByWasmIndex(discoveredIndex);
                if (obj) {
                    this.persistDiscovery(type, obj.discoveryInfo.name, obj.discoveryInfo.icon);
                    return obj.discoveryInfo;
                }
            }
        }

        return null;
    }

    /**
     * Persist a discovery through the persistence layer
     */
    private persistDiscovery(id: string, name: string, icon: string): void {
        // Add to persistence layer (handles timestamps)
        const isNew = discoveryPersistence.addDiscovery(id, name, icon);

        if (isNew) {
            // Also notify legacy system for toast display
            discoverySystem.discover(id, name, icon);

            console.log(`[OptimizedDiscovery] Persisted discovery: ${name} (${id})`);
        }
    }

    /**
     * Find a registered object by its WASM index
     */
    private findObjectByWasmIndex(wasmIndex: number): RegisteredObject | null {
        for (const obj of this.objectRegistry.values()) {
            if (obj.index === wasmIndex) {
                return obj;
            }
        }
        return null;
    }

    /**
     * C++ discovery query via Emscripten spatial grid.
     * queryDiscoveries returns caller-provided IDs; the TS layer decides which
     * are still undiscovered.
     */
    private checkDiscoveryCpp(playerPos: THREE.Vector3): DiscoveryInfo | null {
        if (!this.cppQuery || !this.cppHeap32 || !this.cppOutPtr) return null;

        const count = this.cppQuery(
            playerPos.x, playerPos.z,
            CPP_DISCOVERY_RADIUS_SQ,
            this.cppOutPtr,
            CPP_MAX_QUERY_RESULTS
        );
        if (count <= 0) return null;

        const base = this.cppOutPtr >> 2; // byte offset → Int32Array index
        for (let i = 0; i < count; i++) {
            const id = this.cppHeap32[base + i];
            const obj = this.objectRegistry.get(id);
            if (!obj) continue;
            if (discoveryPersistence.hasDiscovery(obj.type) || discoverySystem.isDiscovered(obj.type)) continue;

            this.persistDiscovery(obj.type, obj.discoveryInfo.name, obj.discoveryInfo.icon);
            return obj.discoveryInfo;
        }
        return null;
    }

    /**
     * JavaScript fallback for discovery check
     * Uses O(N) distance check (original implementation)
     */
    private checkDiscoveryJS(playerPos: THREE.Vector3): DiscoveryInfo | null {
        const DISCOVERY_RADIUS_SQ = 5.0 * 5.0;

        for (const [id, obj] of this.objectRegistry) {
            // Skip already discovered
            if (discoveryPersistence.hasDiscovery(obj.type) || discoverySystem.isDiscovered(obj.type)) {
                continue;
            }

            // This is a simplified check - we'd need to store positions in JS
            // For now, just return null to indicate no discovery
            // In practice, the WASM path will be used
        }

        return null;
    }

    /**
     * Mark a type as discovered
     */
    markDiscovered(type: string): void {
        const discoveryInfo = DISCOVERY_MAP[type];
        if (discoveryInfo) {
            // Use persistence layer
            this.persistDiscovery(type, discoveryInfo.name, discoveryInfo.icon);
        }

        // Also mark in WASM
        if (this.wasmInitialized) {
            const objects = this.typeToObjects.get(type);
            if (objects) {
                for (const id of objects) {
                    const obj = this.objectRegistry.get(id);
                    if (obj && obj.index >= 0 && this.wasmMarkDiscovered) {
                        this.wasmMarkDiscovered(obj.index);
                    }
                }
            }
        }
    }

    /**
     * Check if a type is discovered
     */
    isDiscovered(type: string): boolean {
        return discoveryPersistence.hasDiscovery(type) || discoverySystem.isDiscovered(type);
    }

    /**
     * Get count of undiscovered objects
     */
    getUndiscoveredCount(): number {
        this.ensureInitialized();
        if (this.wasmInitialized && this.wasmGetUndiscoveredCount) {
            return this.wasmGetUndiscoveredCount();
        }

        // JS fallback
        let count = 0;
        for (const [type, objects] of this.typeToObjects) {
            if (!this.isDiscovered(type)) {
                count += objects.length;
            }
        }
        return count;
    }

    /**
     * Reset all discoveries
     */
    reset(): void {
        this.ensureInitialized();
        discoveryPersistence.clear();
        discoverySystem.reset();

        if (this.cppInitialized && this.cppClear) {
            this.cppClear();
        } else if (this.wasmInitialized && this.wasmResetAll) {
            this.wasmResetAll();
        }
    }

    /**
     * Sync discoveries with server
     * @param serverDiscoveries - Array of discoveries from server
     */
    syncWithServer(serverDiscoveries: Array<{ id: string; timestamp: number }>): void {
        const formatted: any[] = [];
        for (let i = 0; i < serverDiscoveries.length; i++) {
            const d = serverDiscoveries[i];
            formatted.push({
            id: d.id,
            timestamp: d.timestamp,
            metadata: DISCOVERY_MAP[d.id] ? {
                displayName: DISCOVERY_MAP[d.id].name,
                icon: DISCOVERY_MAP[d.id].icon
            } : undefined
        });
        }

        discoveryPersistence.mergeWithServer(formatted);

        // Update legacy system
        for (const d of serverDiscoveries) {
            if (!discoverySystem.isDiscovered(d.id)) {
                const info = DISCOVERY_MAP[d.id];
                if (info) {
                    (discoverySystem as any).discoveredItems?.add(d.id);
                }
            }
        }

        console.log(`[OptimizedDiscovery] Synced ${serverDiscoveries.length} discoveries with server`);
    }

    /**
     * Get discoveries that need to be synced to server
     */
    getPendingSync(): Array<{ id: string; timestamp: number }> {
        const pending = discoveryPersistence.getPendingSync();
        const result = [];
        for (let i = 0; i < pending.length; i++) {
            result.push({
                id: pending[i].id,
                timestamp: pending[i].timestamp
            });
        }
        return result;
    }

    /**
     * Get registration statistics
     */
    getStats(): {
        registeredObjects: number;
        uniqueTypes: number;
        undiscoveredCount: number;
        usingWasm: boolean;
        persistedCount: number;
        pendingSync: number;
    } {
        this.ensureInitialized();
        const persistenceStats = discoveryPersistence.getStats();

        return {
            registeredObjects: this.objectRegistry.size,
            uniqueTypes: this.typeToObjects.size,
            undiscoveredCount: this.getUndiscoveredCount(),
            usingWasm: this.cppInitialized || this.wasmInitialized,
            persistedCount: persistenceStats.total,
            pendingSync: persistenceStats.pendingSync
        };
    }

    /**
     * Check if using WASM acceleration (either C++ or AssemblyScript)
     */
    isUsingWasm(): boolean {
        this.ensureInitialized();
        return this.cppInitialized || this.wasmInitialized;
    }

    /**
     * Check if using the C++/Emscripten backend (highest performance)
     */
    isUsingCpp(): boolean {
        return this.cppInitialized;
    }

    /**
     * Check if persistence layer is available
     */
    isPersistenceAvailable(): boolean {
        return discoveryPersistence.available;
    }

    /**
     * Dispose of all resources
     */
    dispose(): void {
        if (this.cppInitialized && this.cppFree && this.cppOutPtr) {
            this.cppFree(this.cppOutPtr);
            this.cppOutPtr = 0;
        }
        this.objectRegistry.clear();
        this.typeToObjects.clear();
        this.typeToId.clear();
        this.idToType.clear();
    }
}

