export function runMemoryBenchmark() {
  console.log('--- ECS Memory Benchmark ---');
  const world = new World();
  const NUM_ENTITIES = 100000;

  const startMemory = (globalThis as any).process?.memoryUsage?.().heapUsed;

  console.time('Create Entities');
  for (let i = 0; i < NUM_ENTITIES; i++) {
    const entity = world.createEntity();
    world.addComponent(entity, 'Position', { x: Math.random(), y: Math.random(), z: Math.random() });
    world.addComponent(entity, 'Velocity', { x: Math.random(), y: Math.random(), z: Math.random() });
  }
  console.timeEnd('Create Entities');

  const endMemory = (globalThis as any).process?.memoryUsage?.().heapUsed;

  if (startMemory && endMemory) {
    console.log(`Memory used for ${NUM_ENTITIES} entities with Position & Velocity: ${((endMemory - startMemory) / 1024 / 1024).toFixed(2)} MB`);
  } else {
    console.log('Memory API not available to report exact memory usage.');
  }

  console.time('Get Matching Entities');
  // Usually this is cached in an archetype query
  const entitiesToUpdate = world.getEntitiesWithComponents(['Position', 'Velocity']);
  console.timeEnd('Get Matching Entities');

  console.time('Update Loop (100 iterations)');
  for(let iter = 0; iter < 100; iter++) {
    // Iterate properly via the ECS interface rather than bypassing it
    for (let i = 0; i < entitiesToUpdate.length; i++) {
        const entity = entitiesToUpdate[i];
        const pos = world.getComponent<{x: number, y: number, z: number}>(entity, 'Position');
        const vel = world.getComponent<{x: number, y: number, z: number}>(entity, 'Velocity');
        if (pos && vel) {
            pos.x += vel.x * 0.016;
            pos.y += vel.y * 0.016;
            pos.z += vel.z * 0.016;
        }
    }
  }
  console.timeEnd('Update Loop (100 iterations)');

  console.log('--- ECS Benchmark Complete ---');
}

/**
 * @file foliage-ecs-bridge.ts
 * @brief Zero-copy ECS ↔ Emscripten animation batch bridge for foliage hot paths.
 *
 * Strategy
 * --------
 * Each simple animation type (shiver / spring / float / cloudBob) gets its own
 * ECS component with strideBytes = ENTRY_SIZE (24 bytes = 6 f32s), matching the
 * ENTRY_STRIDE layout that batchShiver_c / batchSpring_c / … already expect.
 *
 * When the C++ ECS is active and entities are registered via `registerEntity`,
 * `runBatch` can:
 *   1. Call ecsQueryComponents(typeMask) entirely in C++ — O(n) sequential scan
 *      of the alive-entity bitmask array, no JS iteration.
 *   2. Call ecsQueryComponentPointers(typeMask, compType, …) to get the slab
 *      base pointer for each matching entity.  Because all entities of one type
 *      share the same slab, iterating results is a single sequential memory walk.
 *   3. Pass the contiguous slab data to batchShiver_c / … directly — zero JS
 *      marshalling of per-entity animation inputs.
 *
 * Three.js property writes (rotation.z etc.) must still happen in JS because
 * Three.js object graphs are not accessible from WASM.
 *
 * Usage
 * -----
 *   const bridge = FoliageEcsBridge.getInstance();
 *   // During world generation (once per entity):
 *   const entityId = bridge.registerEntity(mesh, 'shiver');
 *   // Per frame (called from FoliageBatcher.flushSimpleBatches):
 *   bridge.runBatch('shiver', time, intensity);
 */

import type { FoliageObject } from '../../foliage/types.ts';
import { getNativeFunc, isEmscriptenReady, getEmscriptenInstance } from '../../utils/wasm-loader-core.ts';
import type { NativeComponentCodec, Component } from './types.ts';
import { World } from './world.ts';

// Must match ENTRY_STRIDE=6 and RESULT_STRIDE=4 in animation_batch_utils.h
const ENTRY_STRIDE = 6;  // floats per input entry
const RESULT_STRIDE = 4; // floats per output entry
const ENTRY_SIZE = ENTRY_STRIDE * 4;  // bytes
const RESULT_SIZE = RESULT_STRIDE * 4; // bytes

export type SimpleAnimType = 'shiver' | 'spring' | 'float' | 'cloudBob';

// Animation-type → apply function that writes WASM results back to Three.js mesh
type ApplyFn = (obj: FoliageObject, results: Float32Array, offset: number) => void;

const APPLY_FNS: Record<SimpleAnimType, ApplyFn> = {
    shiver: (obj, data, offset) => {
        obj.rotation.z = data[offset];
        obj.rotation.x = data[offset + 1];
    },
    spring: (obj, data, offset) => {
        obj.scale.y = data[offset];
        obj.scale.x = data[offset + 1];
        obj.scale.z = data[offset + 2];
    },
    float: (obj, data, offset) => {
        obj.position.y = data[offset];
    },
    cloudBob: (obj, data, offset) => {
        obj.position.y = data[offset];
        obj.rotation.y = data[offset + 1];
    },
};

// Component shape — only used for the TypeScript codec; actual data is f32 packed.
interface FoliageAnimInput extends Component {
    animOffset: number;
    intensity: number;
    originalY: number;
    _pad0: number;
    _pad1: number;
    _pad2: number;
}

interface FoliageAnimResult extends Component {
    out0: number;
    out1: number;
    out2: number;
    out3: number;
}

function makeInputCodec(maxEntities: number): NativeComponentCodec<FoliageAnimInput> {
    return {
        strideBytes: ENTRY_SIZE,
        maxEntities,
        write(view, c) {
            view.setFloat32(0,  c.animOffset, true);
            view.setFloat32(4,  c.intensity,  true);
            view.setFloat32(8,  c.originalY,  true);
            view.setFloat32(12, c._pad0,      true);
            view.setFloat32(16, c._pad1,      true);
            view.setFloat32(20, c._pad2,      true);
        },
        read(view) {
            return {
                animOffset: view.getFloat32(0,  true),
                intensity:  view.getFloat32(4,  true),
                originalY:  view.getFloat32(8,  true),
                _pad0:      view.getFloat32(12, true),
                _pad1:      view.getFloat32(16, true),
                _pad2:      view.getFloat32(20, true),
            };
        },
    };
}

function makeResultCodec(maxEntities: number): NativeComponentCodec<FoliageAnimResult> {
    return {
        strideBytes: RESULT_SIZE,
        maxEntities,
        write(view, c) {
            view.setFloat32(0,  c.out0, true);
            view.setFloat32(4,  c.out1, true);
            view.setFloat32(8,  c.out2, true);
            view.setFloat32(12, c.out3, true);
        },
        read(view) {
            return {
                out0: view.getFloat32(0,  true),
                out1: view.getFloat32(4,  true),
                out2: view.getFloat32(8,  true),
                out3: view.getFloat32(12, true),
            };
        },
    };
}

interface TypeSlot {
    inputCompName:  string;
    resultCompName: string;
    entities: FoliageObject[];  // parallel array: entityId → mesh
    entityIds: number[];
    batchFnName: string;
    applyFn: ApplyFn;
}

const MAX_FOLIAGE_PER_TYPE = 4000;

export class FoliageEcsBridge {
    private static _instance: FoliageEcsBridge | null = null;

    private world: World;
    private slots: Record<SimpleAnimType, TypeSlot>;
    private ready = false;

    // Pre-allocated result buffer in Emscripten heap
    private resultPtr = 0;
    private resultBuf: Float32Array | null = null;
    private emMalloc: ((n: number) => number) | null = null;
    private emFree:   ((p: number) => void) | null = null;
    private emHeapF32: Float32Array | null = null;
    private emHeapU8:  Uint8Array  | null = null;

    private constructor() {
        this.world = new World();

        const types: SimpleAnimType[] = ['shiver', 'spring', 'float', 'cloudBob'];
        const batchFns: Record<SimpleAnimType, string> = {
            shiver:   'batchShiver_c',
            spring:   'batchSpring_c',
            float:    'batchFloat_c',
            cloudBob: 'batchCloudBob_c',
        };

        this.slots = {} as Record<SimpleAnimType, TypeSlot>;
        for (const t of types) {
            this.slots[t] = {
                inputCompName:  `FoliageAnim_${t}_Input`,
                resultCompName: `FoliageAnim_${t}_Result`,
                entities:  [],
                entityIds: [],
                batchFnName: batchFns[t],
                applyFn: APPLY_FNS[t],
            };
        }

        this._tryInit();
    }

    static getInstance(): FoliageEcsBridge {
        if (!FoliageEcsBridge._instance) {
            FoliageEcsBridge._instance = new FoliageEcsBridge();
        }
        return FoliageEcsBridge._instance;
    }

    /** True when the C++ ECS backend is ready and components are registered */
    isReady(): boolean { return this.ready; }

    /**
     * Register a foliage mesh as an ECS entity.
     * @returns The ECS entity ID, or -1 if the bridge is not active.
     */
    registerEntity(mesh: FoliageObject, animType: SimpleAnimType): number {
        if (!this.ready) return -1;
        const slot = this.slots[animType];

        const entityId = this.world.createEntity();
        const animOffset = (mesh.userData.animationOffset as number) ?? 0;
        const originalY  = (mesh.userData.originalY    as number) ?? mesh.position.y;

        this.world.addComponent(entityId, slot.inputCompName, {
            animOffset,
            intensity: 1.0,
            originalY,
            _pad0: 0, _pad1: 0, _pad2: 0,
        } satisfies FoliageAnimInput);

        this.world.addComponent(entityId, slot.resultCompName, {
            out0: 0, out1: 0, out2: 0, out3: 0,
        } satisfies FoliageAnimResult);

        slot.entities.push(mesh);
        slot.entityIds.push(entityId);
        return entityId;
    }

    /**
     * Hot-path: iterate all registered entities of animType entirely through C++.
     *
     * Flow:
     *   1. Update per-entity intensity in the input slab (one DataView write per entity).
     *   2. C++ ecsQueryComponentPointers returns the slab base pointer — O(n) C++ scan.
     *   3. C++ batchShiver_c / … operates on the slab in-place — zero extra copies.
     *   4. JS applies output floats to Three.js mesh properties.
     *
     * @returns number of entities processed, or -1 if bridge not active.
     */
    runBatch(animType: SimpleAnimType, time: number, intensity: number): number {
        if (!this.ready || !this.emHeapF32 || !this.resultBuf) return -1;
        const slot = this.slots[animType];
        if (slot.entities.length === 0) return 0;

        const count = slot.entities.length;

        // Step 1 — refresh per-entity intensity in the C++ input slab
        // We use queryNativeTable to get the slab pointers, then write intensity.
        const table = this.world.queryNativeTable([slot.inputCompName]);
        if (!table || table.count !== count) return -1;

        const inputPtrs = table.pointers[slot.inputCompName];
        const heapU8    = this.emHeapU8!;

        for (let i = 0; i < count; i++) {
            const ptr = inputPtrs[i];
            // Float32 offset 1 (bytes 4-7) = intensity field
            heapU8[ptr + 4]  =  (intensity * 1000 | 0) & 0xFF;
            const view = new DataView(heapU8.buffer, ptr, ENTRY_SIZE);
            view.setFloat32(4, intensity, true);
        }

        // Step 2 — get the input slab base pointer for the first entity.
        // Because entities were registered sequentially their slab slots are
        // contiguous; the base pointer of slot[0] is the start of the dense array.
        const slabBase = inputPtrs[0];

        // Step 3 — call the C++ batch animation function on the slab.
        const batchFn = getNativeFunc(slot.batchFnName);
        if (!batchFn) return -1;

        batchFn(slabBase, count, time, intensity, this.resultPtr);

        // Step 4 — apply results to Three.js meshes.
        const results = this.resultBuf;
        const applyFn = slot.applyFn;
        for (let i = 0; i < count; i++) {
            applyFn(slot.entities[i], results, i * RESULT_STRIDE);
        }

        return count;
    }

    /** Remove all registered entities (call on scene teardown). */
    clear(): void {
        for (const t in this.slots) {
            const slot = this.slots[t as SimpleAnimType];
            for (const id of slot.entityIds) this.world.destroyEntity(id);
            slot.entities.length  = 0;
            slot.entityIds.length = 0;
        }
    }

    // -------------------------------------------------------------------------

    private _tryInit(): void {
        if (!isEmscriptenReady()) return;
        if (!this.world.isUsingCpp()) return;

        try {
            const emInst = getEmscriptenInstance() as any;
            this.emMalloc  = emInst?._malloc;
            this.emFree    = emInst?._free;
            this.emHeapF32 = emInst?.HEAPF32 as Float32Array;
            this.emHeapU8  = emInst?.HEAPU8  as Uint8Array;

            if (!this.emMalloc || !this.emHeapF32 || !this.emHeapU8) return;

            // Allocate a result buffer large enough for MAX_FOLIAGE_PER_TYPE results
            this.resultPtr = this.emMalloc(MAX_FOLIAGE_PER_TYPE * RESULT_SIZE);
            if (!this.resultPtr) return;

            // Create a persistent Float32Array view over the result buffer
            this.resultBuf = new Float32Array(
                this.emHeapF32.buffer,
                this.resultPtr,
                MAX_FOLIAGE_PER_TYPE * RESULT_STRIDE
            );

            // Register native components for each animation type
            for (const t in this.slots) {
                const slot = this.slots[t as SimpleAnimType];
                const inputOk  = this.world.registerNativeComponent(
                    slot.inputCompName, makeInputCodec(MAX_FOLIAGE_PER_TYPE));
                const resultOk = this.world.registerNativeComponent(
                    slot.resultCompName, makeResultCodec(MAX_FOLIAGE_PER_TYPE));
                if (!inputOk || !resultOk) return;
            }

            this.ready = true;
            console.log('[FoliageEcsBridge] C++ ECS animation hot path active');
        } catch {
            this.ready = false;
        }
    }
}

export type Entity = number;

export interface Component {
  [key: string]: any;
}

export interface System {
  update: (dt: number) => void;
}

export interface NativeComponentCodec<T extends Component> {
  strideBytes: number;
  maxEntities?: number;
  write: (view: DataView, component: T) => void;
  read: (view: DataView) => T;
}

export interface NativeQueryTable {
  ids: Uint32Array;
  pointers: Record<string, Uint32Array>;
  count: number;
}

import { isEmscriptenReady, getNativeFunc, getEmscriptenInstance } from '../../utils/wasm-loader-core.ts';
import { Entity, Component, System, NativeComponentCodec, NativeQueryTable } from './types.ts';

// =============================================================================
// C++ ECS BRIDGE
// =============================================================================

const CPP_QUERY_BUF_SIZE = 4096; // max entities returned per query

interface CppEcsBindings {
    createEntity: () => number;
    destroyEntity: (id: number) => void;
    isAlive: (id: number) => number;
    registerComponent: (stride: number, max: number) => number;
    getComponent: (entityId: number, type: number) => number;
    setComponent: (entityId: number, type: number, dataPtr: number) => void;
    addComponent: (entityId: number, type: number) => void;
    removeComponent: (entityId: number, type: number) => void;
    hasComponent: (entityId: number, type: number) => number;
    queryComponents: (mask: number, outPtr: number, max: number) => number;
    queryComponentPointers: (mask: number, type: number, outPtr: number, max: number) => number;
    getComponentStride: (type: number) => number;
    malloc: (size: number) => number;
    free: (ptr: number) => void;
    heapU8: Uint8Array;
    heap32: Int32Array;
    /** output buffer ptr pre-allocated in Emscripten heap */
    queryBufPtr: number;
    /** output pointer buffer ptr pre-allocated in Emscripten heap */
    queryPtrBufPtr: number;
}

function bindCppEcs(): CppEcsBindings | null {
    if (!isEmscriptenReady()) return null;
    try {
        const emInst = getEmscriptenInstance() as any;
        const createEntity     = getNativeFunc('ecsCreateEntity');
        const destroyEntity    = getNativeFunc('ecsDestroyEntity');
        const isAlive          = getNativeFunc('ecsIsAlive');
        const registerComponent= getNativeFunc('ecsRegisterComponent');
        const getComponent     = getNativeFunc('ecsGetComponent');
        const setComponent     = getNativeFunc('ecsSetComponent');
        const addComponent     = getNativeFunc('ecsAddComponent');
        const removeComponent  = getNativeFunc('ecsRemoveComponent');
        const hasComponent     = getNativeFunc('ecsHasComponent');
        const queryComponents  = getNativeFunc('ecsQueryComponents');
        const queryComponentPointers = getNativeFunc('ecsQueryComponentPointers');
        const getComponentStride = getNativeFunc('ecsGetComponentStride');
        const malloc           = emInst?._malloc as ((n: number) => number) | undefined;
        const free             = emInst?._free  as ((p: number) => void) | undefined;
        const heapU8           = emInst?.HEAPU8 as Uint8Array | undefined;
        const heap32           = emInst?.HEAP32 as Int32Array | undefined;
        const initEcs          = getNativeFunc('ecsInit');

        if (!createEntity || !destroyEntity || !isAlive || !registerComponent ||
            !getComponent || !setComponent || !addComponent || !removeComponent ||
            !hasComponent || !queryComponents || !queryComponentPointers || !getComponentStride ||
            !malloc || !heapU8 || !heap32) {
            return null;
        }

        const queryBufPtr = malloc(CPP_QUERY_BUF_SIZE * 4);
        const queryPtrBufPtr = malloc(CPP_QUERY_BUF_SIZE * 4);
        if (!queryBufPtr || !queryPtrBufPtr) {
            if (queryBufPtr) free?.(queryBufPtr);
            if (queryPtrBufPtr) free?.(queryPtrBufPtr);
            return null;
        }

        // Reset the C++ world (idempotent)
        initEcs?.();

        return {
            createEntity, destroyEntity, isAlive,
            registerComponent, getComponent, setComponent,
            addComponent, removeComponent, hasComponent,
            queryComponents, queryComponentPointers, getComponentStride,
            malloc, free: free ?? (() => {}),
            heapU8, heap32, queryBufPtr, queryPtrBufPtr,
        };
    } catch {
        return null;
    }
}

interface NativeComponentMeta<T extends Component = Component> {
    codec: NativeComponentCodec<T>;
    type: number;
    scratchPtr: number;
}

// =============================================================================
// WORLD
// =============================================================================

/**
 * Entity-Component World.
 * Routes entity lifecycle and batch queries to C++/Emscripten when available;
 * component data always lives in JavaScript (arbitrary JS object shapes cannot
 * be cheaply serialised to fixed-stride C++ slabs).
 *
 * Hot-path optimisation: `getEntitiesWithComponents` uses the C++ bitmask query
 * when the Emscripten module is loaded, avoiding the O(entities × components)
 * JS loop.
 */
export class World {
    // JS-side entity tracking (kept in sync with C++ for API compatibility)
    private nextEntityId: Entity = 1;
    private entities: Set<Entity> = new Set();

    // Dense arrays for high-performance JS-side iteration
    private components: Map<string, any[]> = new Map();
    private entityToIndex: Map<string, Map<Entity, number>> = new Map();
    private indexToEntity: Map<string, Map<number, Entity>> = new Map();

    private systems: System[] = [];

    // C++ binding (null when Emscripten is not available)
    private cpp: CppEcsBindings | null = null;
    // Maps component name → C++ type index (for bitmask queries)
    private cppTypeMap: Map<string, number> = new Map();
    private nativeComponents: Map<string, NativeComponentMeta> = new Map();
    // Track which C++ entities correspond to JS entities (1:1 if C++ is active)
    private jsToCpp: Map<Entity, number> = new Map();

    constructor() {
        this.cpp = bindCppEcs();
        if (this.cpp) {
            console.log('[ECS] C++ backend active — entity queries will use WASM bitmask path');
        }
    }

    // =========================================================================
    // Entity lifecycle
    // =========================================================================

    createEntity(): Entity {
        let id: Entity;
        if (this.cpp) {
            const cppId = this.cpp.createEntity();
            // Use the C++ generational ID directly as the JS entity ID so they stay in sync
            id = cppId;
            this.jsToCpp.set(id, cppId);
        } else {
            id = this.nextEntityId++;
        }
        this.entities.add(id);
        return id;
    }

    destroyEntity(entity: Entity) {
        this.entities.delete(entity);
        const componentNames = Array.from(this.entityToIndex.keys());
        for (const name of componentNames) {
            if (this.entityToIndex.get(name)?.has(entity)) {
                this.removeComponent(entity, name);
            }
        }
        if (this.cpp) {
            const cppId = this.jsToCpp.get(entity) ?? entity;
            this.cpp.destroyEntity(cppId);
            this.jsToCpp.delete(entity);
        }
    }

    // =========================================================================
    // Component management
    // =========================================================================

    addComponent<T extends Component>(entity: Entity, componentName: string, component: T) {
        const existing = this.entityToIndex.get(componentName);
        if (existing?.has(entity)) {
            this.setComponent(entity, componentName, component);
            return;
        }

        if (!this.components.has(componentName)) {
            this.components.set(componentName, []);
            this.entityToIndex.set(componentName, new Map());
            this.indexToEntity.set(componentName, new Map());
        }

        const componentArray   = this.components.get(componentName)!;
        const indexMap         = this.entityToIndex.get(componentName)!;
        const reverseIndexMap  = this.indexToEntity.get(componentName)!;

        const index = componentArray.length;
        componentArray.push(component);
        indexMap.set(entity, index);
        reverseIndexMap.set(index, entity);

        this.writeNativeComponent(entity, componentName, component);
    }

    removeComponent(entity: Entity, componentName: string) {
        const indexMap        = this.entityToIndex.get(componentName);
        const reverseIndexMap = this.indexToEntity.get(componentName);

        if (!indexMap || !reverseIndexMap || !indexMap.has(entity)) return;

        const indexToRemove = indexMap.get(entity)!;
        const componentArray = this.components.get(componentName)!;
        const lastIndex = componentArray.length - 1;

        if (indexToRemove !== lastIndex) {
            const lastElement = componentArray[lastIndex];
            const lastEntity  = reverseIndexMap.get(lastIndex)!;
            componentArray[indexToRemove] = lastElement;
            indexMap.set(lastEntity, indexToRemove);
            reverseIndexMap.set(indexToRemove, lastEntity);
        }

        componentArray.pop();
        indexMap.delete(entity);
        reverseIndexMap.delete(lastIndex);

        // Clear C++ bit
        if (this.cpp) {
            const type = this.cppTypeMap.get(componentName);
            if (type !== undefined) {
                const cppId = this.jsToCpp.get(entity) ?? entity;
                this.cpp.removeComponent(cppId, type);
            }
        }
    }

    getComponent<T extends Component>(entity: Entity, componentName: string): T | undefined {
        const indexMap = this.entityToIndex.get(componentName);
        if (!indexMap || !indexMap.has(entity)) return undefined;
        const index = indexMap.get(entity)!;
        const nativeMeta = this.nativeComponents.get(componentName);
        if (nativeMeta && this.cpp) {
            const cppId = this.jsToCpp.get(entity) ?? entity;
            const ptr = this.cpp.getComponent(cppId, nativeMeta.type);
            if (ptr) {
                const component = nativeMeta.codec.read(
                    new DataView(this.cpp.heapU8.buffer, ptr, nativeMeta.codec.strideBytes)
                ) as T;
                this.components.get(componentName)![index] = component;
                return component;
            }
        }
        return this.components.get(componentName)![index] as T;
    }

    setComponent<T extends Component>(entity: Entity, componentName: string, component: T) {
        const indexMap = this.entityToIndex.get(componentName);
        if (!indexMap || !indexMap.has(entity)) {
            this.addComponent(entity, componentName, component);
            return;
        }
        this.components.get(componentName)![indexMap.get(entity)!] = component;
        this.writeNativeComponent(entity, componentName, component);
    }

    hasComponent(entity: Entity, componentName: string): boolean {
        const indexMap = this.entityToIndex.get(componentName);
        return indexMap ? indexMap.has(entity) : false;
    }

    // =========================================================================
    // Systems
    // =========================================================================

    addSystem(system: System) {
        this.systems.push(system);
    }

    update(dt: number) {
        for (const system of this.systems) {
            system.update(dt);
        }
    }

    // =========================================================================
    // Batch query — uses C++ bitmask when Emscripten is available
    // =========================================================================

    /**
     * Return entities that have ALL of the named components.
     * Routes to C++ WASM bitmask query when available (avoids O(N×M) JS loop).
     */
    getEntitiesWithComponents(components: string[]): Entity[] {
        if (this.cpp && components.length > 0) {
            return this.getEntitiesWithComponentsCpp(components);
        }
        return this.getEntitiesWithComponentsJS(components);
    }

    /** True when the C++/Emscripten backend is handling entity operations */
    isUsingCpp(): boolean {
        return this.cpp !== null;
    }

    registerNativeComponent<T extends Component>(componentName: string, codec: NativeComponentCodec<T>): boolean {
        if (!this.cpp) return false;
        if (this.nativeComponents.has(componentName)) return true;

        const maxEntities = codec.maxEntities ?? 65536;
        const type = this.cpp.registerComponent(codec.strideBytes, maxEntities);
        if (type < 0) return false;

        const scratchPtr = this.cpp.malloc(codec.strideBytes);
        if (!scratchPtr) return false;

        this.cppTypeMap.set(componentName, type);
        this.nativeComponents.set(componentName, {
            codec: codec as unknown as NativeComponentCodec<Component>,
            type,
            scratchPtr
        });
        return true;
    }

    queryNativeTable(componentNames: string[]): NativeQueryTable | null {
        if (!this.cpp || componentNames.length === 0) return null;

        let mask = 0;
        for (const name of componentNames) {
            const meta = this.nativeComponents.get(name);
            if (!meta) return null;
            mask |= (1 << meta.type);
        }

        const count = this.cpp.queryComponents(mask, this.cpp.queryBufPtr, CPP_QUERY_BUF_SIZE);
        if (count <= 0) {
            return { ids: new Uint32Array(0), pointers: {}, count: 0 };
        }

        const ids = new Uint32Array(count);
        ids.set(new Uint32Array(this.cpp.heap32.buffer, this.cpp.queryBufPtr, count));

        const pointers: Record<string, Uint32Array> = {};
        for (const name of componentNames) {
            const meta = this.nativeComponents.get(name)!;
            const written = this.cpp.queryComponentPointers(mask, meta.type, this.cpp.queryPtrBufPtr, CPP_QUERY_BUF_SIZE);
            if (written !== count) return null;
            pointers[name] = new Uint32Array(count);
            pointers[name].set(new Uint32Array(this.cpp.heap32.buffer, this.cpp.queryPtrBufPtr, count));
        }

        return { ids, pointers, count };
    }

    // =========================================================================
    // Private helpers
    // =========================================================================

    private getEntitiesWithComponentsCpp(components: string[]): Entity[] {
        const cpp = this.cpp!;

        // Build bitmask from registered types (register on first use)
        let mask = 0;
        for (const name of components) {
            const type = this.ensureCppType(name);
            mask |= (1 << type);
        }

        const count = cpp.queryComponents(mask, cpp.queryBufPtr, CPP_QUERY_BUF_SIZE);
        if (count <= 0) return [];

        const base = cpp.queryBufPtr >> 2; // byte → Int32Array index
        const result: Entity[] = new Array(count);
        for (let i = 0; i < count; i++) {
            result[i] = cpp.heap32[base + i] as Entity;
        }
        return result;
    }

    private getEntitiesWithComponentsJS(components: string[]): Entity[] {
        const result: Entity[] = [];
        for (const entity of this.entities) {
            let hasAll = true;
            for (const c of components) {
                if (!this.hasComponent(entity, c)) { hasAll = false; break; }
            }
            if (hasAll) result.push(entity);
        }
        return result;
    }

    /**
     * Get the C++ type index for a component name, registering it if needed.
     * Uses a stride of 0 (marker-only) for unknown/JS-only components.
     */
    private ensureCppType(componentName: string): number {
        const nativeMeta = this.nativeComponents.get(componentName);
        if (nativeMeta) {
            return nativeMeta.type;
        }
        if (this.cppTypeMap.has(componentName)) {
            return this.cppTypeMap.get(componentName)!;
        }
        // Register as a 1-byte marker slab (data lives in JS)
        const type = this.cpp!.registerComponent(1, 65536);
        if (type < 0) {
            // C++ out of slots; use a stable hash mod 32 as best-effort fallback
            const fallback = componentName.split('').reduce((h, c) => (h * 31 + c.charCodeAt(0)) & 0x7FFFFFFF, 0) % 32;
            this.cppTypeMap.set(componentName, fallback);
            return fallback;
        }
        this.cppTypeMap.set(componentName, type);
        return type;
    }

    private writeNativeComponent<T extends Component>(entity: Entity, componentName: string, component: T) {
        if (!this.cpp) return;
        const nativeMeta = this.nativeComponents.get(componentName);
        if (nativeMeta) {
            const view = new DataView(this.cpp.heapU8.buffer, nativeMeta.scratchPtr, nativeMeta.codec.strideBytes);
            nativeMeta.codec.write(view, component);
            const cppId = this.jsToCpp.get(entity) ?? entity;
            this.cpp.setComponent(cppId, nativeMeta.type, nativeMeta.scratchPtr);
            return;
        }

        const type = this.ensureCppType(componentName);
        const cppId = this.jsToCpp.get(entity) ?? entity;
        this.cpp.addComponent(cppId, type);
    }
}

/**
 * WASM ↔ JS bridge for assembly/boids.ts updateBoids.
 * JS fallback mirrors the WASM spatial-grid boids when AS is unavailable.
 */

import { wasmMemory, wasmInstance, wasmUpdateBoids, cppUpdateBoids, emscriptenMemory } from '../../utils/wasm-loader-core.ts';
import type { WasmExports } from '../../utils/wasm-loader-types.ts';
import { FAUNA_BOID_STRIDE } from './types.ts';

const MAX_BOIDS = 256;
const GRID_DIM = 32;
const CELL_SIZE = 8;
const WORLD_MIN = -128;
const WORLD_MAX = 128;

const SEP_RADIUS_SQ = 4;
const ALIGN_RADIUS_SQ = 25;
const COH_RADIUS_SQ = 64;
const PLAYER_AVOID_RADIUS_SQ = 100;

const _gridHeads = new Int32Array(GRID_DIM * GRID_DIM);
const _gridNext = new Int32Array(MAX_BOIDS);

function cellIndex(x: number, z: number): number {
    const cx = Math.floor((x - WORLD_MIN) / CELL_SIZE);
    const cz = Math.floor((z - WORLD_MIN) / CELL_SIZE);
    if (cx < 0 || cx >= GRID_DIM || cz < 0 || cz >= GRID_DIM) return -1;
    return cz * GRID_DIM + cx;
}

function getGroundHeightJS(x: number, z: number): number {
    if (Number.isNaN(x) || Number.isNaN(z)) return 0;
    return (
        Math.sin(x * 0.05) * 2 +
        Math.cos(z * 0.05) * 2 +
        Math.sin(x * 0.2) * 0.3 +
        Math.cos(z * 0.15) * 0.3
    );
}

function maxSpeedForSpecies(species: number): number {
    if (species === 1) return 3.5;
    if (species === 2) return 2.0;
    return 1.8;
}

function groundOffsetForSpecies(species: number): number {
    if (species === 1) return 0.22;
    if (species === 2) return 0;
    return 0.14;
}

function applyGroundFollow(
    species: number,
    x: number,
    z: number,
    time: number,
    phase: number
): number {
    const ground = getGroundHeightJS(x, z);
    if (species === 2) {
        return ground + 2.5 + Math.sin(time * 1.2 + phase) * 0.6;
    }
    if (species === 1) {
        return (
            ground + groundOffsetForSpecies(species) + Math.abs(Math.sin(time * 4 + phase)) * 0.35
        );
    }
    return ground + groundOffsetForSpecies(species);
}

function rebuildGrid(heap: Float32Array, byteOffset: number, count: number): void {
    _gridHeads.fill(-1);
    const base = byteOffset >> 2;
    for (let i = 0; i < count; i++) {
        const b = base + i * FAUNA_BOID_STRIDE;
        const x = heap[b];
        const z = heap[b + 2];
        const idx = cellIndex(x, z);
        if (idx < 0) continue;
        _gridNext[i] = _gridHeads[idx];
        _gridHeads[idx] = i;
    }
}

/** JS fallback — same algorithm as assembly/boids.ts */
export function updateBoidsJS(
    heap: Float32Array,
    byteOffset: number,
    count: number,
    dt: number,
    playerX: number,
    playerZ: number,
    time: number
): void {
    const n = Math.min(count, MAX_BOIDS);
    const clampedDt = Math.max(0, Math.min(dt, 0.1));
    const base = byteOffset >> 2;

    rebuildGrid(heap, byteOffset, n);

    for (let i = 0; i < n; i++) {
        const b = base + i * FAUNA_BOID_STRIDE;
        let x = heap[b];
        let y = heap[b + 1];
        let z = heap[b + 2];
        let vx = heap[b + 3];
        let vy = heap[b + 4];
        let vz = heap[b + 5];
        const phase = heap[b + 6];
        const species = heap[b + 7] | 0;

        let sepX = 0,
            sepY = 0,
            sepZ = 0;
        let aliX = 0,
            aliY = 0,
            aliZ = 0;
        let cohX = 0,
            cohY = 0,
            cohZ = 0;
        let aliCount = 0;
        let cohCount = 0;

        const homeCell = cellIndex(x, z);
        if (homeCell >= 0) {
            const cx0 = homeCell % GRID_DIM;
            const cz0 = (homeCell / GRID_DIM) | 0;
            for (let dz = -1; dz <= 1; dz++) {
                for (let dx = -1; dx <= 1; dx++) {
                    const cx = cx0 + dx;
                    const cz = cz0 + dz;
                    if (cx < 0 || cx >= GRID_DIM || cz < 0 || cz >= GRID_DIM) continue;
                    const cell = cz * GRID_DIM + cx;
                    let j = _gridHeads[cell];
                    while (j >= 0) {
                        if (j !== i) {
                            const ob = base + j * FAUNA_BOID_STRIDE;
                            const ox = heap[ob];
                            const oy = heap[ob + 1];
                            const oz = heap[ob + 2];
                            const ovx = heap[ob + 3];
                            const ovy = heap[ob + 4];
                            const ovz = heap[ob + 5];
                            const ddx = ox - x;
                            const ddy = oy - y;
                            const ddz = oz - z;
                            const d2 = ddx * ddx + ddy * ddy + ddz * ddz;

                            if (d2 < SEP_RADIUS_SQ && d2 > 0.0001) {
                                const inv = 1 / d2;
                                sepX += (x - ox) * inv;
                                sepY += (y - oy) * inv;
                                sepZ += (z - oz) * inv;
                            }
                            if (d2 < ALIGN_RADIUS_SQ) {
                                aliX += ovx;
                                aliY += ovy;
                                aliZ += ovz;
                                aliCount++;
                            }
                            if (d2 < COH_RADIUS_SQ) {
                                cohX += ox;
                                cohY += oy;
                                cohZ += oz;
                                cohCount++;
                            }
                        }
                        j = _gridNext[j];
                    }
                }
            }
        }

        const pdx = x - playerX;
        const pdz = z - playerZ;
        const pd2 = pdx * pdx + pdz * pdz;
        if (pd2 < PLAYER_AVOID_RADIUS_SQ && pd2 > 0.01) {
            const push = (1 - pd2 / PLAYER_AVOID_RADIUS_SQ) * 4;
            sepX += (pdx / pd2) * push;
            sepZ += (pdz / pd2) * push;
        }

        const wanderX = Math.sin(time * 0.7 + phase * 3.1) * 0.4;
        const wanderZ = Math.cos(time * 0.6 + phase * 2.7) * 0.4;

        let ax = sepX * 2.5 + wanderX;
        let ay = sepY;
        let az = sepZ * 2.5 + wanderZ;

        if (aliCount > 0) {
            const inv = 1 / aliCount;
            ax += (aliX * inv - vx) * 0.5;
            ay += (aliY * inv - vy) * 0.3;
            az += (aliZ * inv - vz) * 0.5;
        }
        if (cohCount > 0) {
            const inv = 1 / cohCount;
            ax += (cohX * inv - x) * 0.15;
            ay += (cohY * inv - y) * 0.05;
            az += (cohZ * inv - z) * 0.15;
        }

        vx += ax * clampedDt;
        vy += ay * clampedDt;
        vz += az * clampedDt;

        const damp = 0.92;
        vx *= damp;
        vy *= damp;
        vz *= damp;

        const maxSpd = maxSpeedForSpecies(species);
        const spd2 = vx * vx + vy * vy + vz * vz;
        if (spd2 > maxSpd * maxSpd) {
            const scale = maxSpd / Math.sqrt(spd2);
            vx *= scale;
            vy *= scale;
            vz *= scale;
        }

        x += vx * clampedDt;
        z += vz * clampedDt;

        if (x < WORLD_MIN) {
            x = WORLD_MIN;
            vx = Math.abs(vx);
        }
        if (x > WORLD_MAX) {
            x = WORLD_MAX;
            vx = -Math.abs(vx);
        }
        if (z < WORLD_MIN) {
            z = WORLD_MIN;
            vz = Math.abs(vz);
        }
        if (z > WORLD_MAX) {
            z = WORLD_MAX;
            vz = -Math.abs(vz);
        }

        y = applyGroundFollow(species, x, z, time, phase);
        if (species !== 2) vy *= 0.5;

        heap[b] = x;
        heap[b + 1] = y;
        heap[b + 2] = z;
        heap[b + 3] = vx;
        heap[b + 4] = vy;
        heap[b + 5] = vz;
    }
}

export function bindBoidsWasm(): void {
    // wasmUpdateBoids is populated by wasm-loader-core cacheWasmFunctions at boot.
}

export function updateBoidsBatch(
    heap: Float32Array,
    byteOffset: number,
    count: number,
    dt: number,
    playerX: number,
    playerZ: number,
    time: number
): void {
    // ⚡ OPTIMIZATION: Try C++ Boids Scale-Up first
    if (cppUpdateBoids && emscriptenMemory) {
        cppUpdateBoids(byteOffset, count, dt, playerX, playerZ, time);
        return;
    }
    if (wasmUpdateBoids && wasmMemory) {
        wasmUpdateBoids(byteOffset, count, dt, playerX, playerZ, time);
        return;
    }
    updateBoidsJS(heap, byteOffset, count, dt, playerX, playerZ, time);
}

export function allocateBoidsBuffer(count: number): { ptr: number; view: Float32Array } | null {
    if (cppUpdateBoids && emscriptenMemory) {
        // C++ module uses its own malloc
        const malloc = (window as any).candyNative?._malloc || (window as any).candyNative?.malloc;
        if (malloc) {
            const bytes = count * FAUNA_BOID_STRIDE * 4;
            const ptr = malloc(bytes);
            if (ptr) {
                const view = new Float32Array((emscriptenMemory as any).buffer || emscriptenMemory, ptr, count * FAUNA_BOID_STRIDE);
                return { ptr, view };
            }
        }
    }

    if (!wasmInstance || !wasmMemory) return null;
    const malloc = (wasmInstance.exports as WasmExports).malloc as
        ((n: number) => number) | undefined;
    if (!malloc) return null;
    const bytes = count * FAUNA_BOID_STRIDE * 4;
    const ptr = malloc(bytes);
    if (!ptr) return null;
    const view = new Float32Array(wasmMemory.buffer, ptr, count * FAUNA_BOID_STRIDE);
    return { ptr, view };
}

export function freeBoidsBuffer(ptr: number): void {
    if (!ptr) return;
    if (cppUpdateBoids && emscriptenMemory) {
        const free = (window as any).candyNative?._free || (window as any).candyNative?.free;
        if (free) {
            free(ptr);
            return;
        }
    }

    if (!wasmInstance) return;
    const free = (wasmInstance.exports as WasmExports).free as ((p: number) => void) | undefined;
    free?.(ptr);
}

