    updateBoidsBatch,
} from './boids-bridge.ts';
import { spawnFaunaPopulation } from './spawn.ts';
import { FAUNA_BOID_STRIDE, FaunaSpecies, type FaunaSpawnEntry } from './types.ts';

const _up = new THREE.Vector3(0, 1, 0);
const _normal = new THREE.Vector3();
const _fwd = new THREE.Vector3();
const _quat = new THREE.Quaternion();
const _yawQuat = new THREE.Quaternion();
const _tiltQuat = new THREE.Quaternion();
const _mat = new THREE.Matrix4();
const _pos = new THREE.Vector3();
const _scale = new THREE.Vector3(1, 1, 1);

export class FaunaSystem {
    private static _instance: FaunaSystem | null = null;

    readonly world = new World();
    private _bufferPtr = 0;
    private _heap: Float32Array | null = null;
    private _entries: FaunaSpawnEntry[] = [];
    private _count = 0;
    private _initialized = false;

    static getInstance(): FaunaSystem {
        if (!FaunaSystem._instance) {
            FaunaSystem._instance = new FaunaSystem();
        }
        return FaunaSystem._instance;
    }

    get count(): number {
        return this._count;
    }

    init(): void {
        if (this._initialized || !FEATURE_FLAGS.fauna || !CONFIG.fauna?.enabled) return;

        bindBoidsWasm();

        const maxCount = CONFIG.fauna?.maxInstances ?? 96;
        const alloc = allocateBoidsBuffer(maxCount);
        if (alloc) {
            this._bufferPtr = alloc.ptr;
            this._heap = alloc.view;
        } else {
            this._bufferPtr = 0;
            this._heap = new Float32Array(maxCount * FAUNA_BOID_STRIDE);
        }

        FaunaBatcher.getInstance().init();

        this._entries = spawnFaunaPopulation({
            world: this.world,
            buffer: this._heap,
            bufferByteOffset: this._bufferPtr,
            maxCount,
            seed: CONFIG.fauna?.seed ?? 42,
        });
        this._count = this._entries.length;

        const batcher = FaunaBatcher.getInstance();
        for (const { component } of this._entries) {
            const b = component.slot * FAUNA_BOID_STRIDE;
            batcher.addInstance(
                component.species,
                this._heap![b],
                this._heap![b + 1],
                this._heap![b + 2],
                component.biome,
                this._heap![b + 6],
                component.slot
            );
        }

        this._initialized = true;
        console.log(`[Fauna] Spawned ${this._count} ambient critters (cap ${maxCount})`);
    }

    update(dt: number, time: number): void {
        if (!this._initialized || !this._heap || this._count === 0) return;

        updateBoidsBatch(
            this._heap,
            this._bufferPtr,
            this._count,
            dt,
            player.position.x,
            player.position.z,
            time
        );

        const batcher = FaunaBatcher.getInstance();
        const base = this._bufferPtr >> 2;

        for (const { component } of this._entries) {
            const b = base + component.slot * FAUNA_BOID_STRIDE;
            const x = this._heap[b];
            const y = this._heap[b + 1];
            const z = this._heap[b + 2];
            const vx = this._heap[b + 3];
            const vz = this._heap[b + 5];
            const phase = this._heap[b + 6];

            sampleGroundNormal(x, z, _normal);
            component.normalX = _normal.x;
            component.normalY = _normal.y;
            component.normalZ = _normal.z;

            _pos.set(x, y, z);
            _fwd.set(vx, 0, vz);
            if (_fwd.lengthSq() < 0.0001) {
                _fwd.set(Math.sin(phase), 0, Math.cos(phase));
            }
            _fwd.normalize();
            _normal.set(component.normalX, component.normalY, component.normalZ);
            if (_normal.lengthSq() < 0.01) _normal.set(0, 1, 0);
            else _normal.normalize();

            _tiltQuat.setFromUnitVectors(_up, _normal);
            const yaw = Math.atan2(_fwd.x, _fwd.z);
            _yawQuat.setFromAxisAngle(_normal, yaw);
            _quat.copy(_tiltQuat).multiply(_yawQuat);

            const scaleMul =
                component.species === FaunaSpecies.JellybeanHopper
                    ? 1.1
                    : component.species === FaunaSpecies.SugarMoth
                      ? 0.9
                      : 1.0;
            _scale.set(scaleMul, scaleMul, scaleMul);

            _mat.compose(_pos, _quat, _scale);
            batcher.setInstanceMatrix(
                component.species,
                component.slot,
                _mat,
                component.biome,
                phase
            );
        }

        batcher.syncMatrices();

        if (isFaunaDebugEnabled()) {
            updateFaunaDebug(this._heap, this._bufferPtr, this._count, this._entries);
        }
    }

    dispose(): void {
        if (this._bufferPtr) {
            freeBoidsBuffer(this._bufferPtr);
        }
        this._bufferPtr = 0;
        this._heap = null;
        this._entries = [];
        this._count = 0;
        this._initialized = false;
        FaunaSystem._instance = null;
    }
}

export function initFaunaSystem(): void {
    if (!CONFIG.fauna?.enabled) return;
    FaunaSystem.getInstance().init();
}

export function updateFaunaSystem(dt: number, time: number): void {
    if (!CONFIG.fauna?.enabled) return;
    FaunaSystem.getInstance().update(dt, time);
}

/**
 * Biome-weighted fauna spawning — places critters on authoritative ground surface.
 */

import * as THREE from 'three';
import { CONFIG } from '../../core/config.ts';
import { animatedFoliage } from '../../world/state.ts';
import { World } from '../ecs/world.ts';
import { getGroundHeight, sampleGroundNormal } from '../ground-system.ts';
import { faunaComponentCodec } from './components.ts';
import { getSkyIslandRoostAnchors, DEFAULT_ROOST_PLAN } from './roosts.ts';
import {
    FaunaSpecies,
    FaunaState,
    FAUNA_BOID_STRIDE,
    type FaunaBiomeDensity,
    type FaunaComponent,
    type FaunaSpawnEntry,
} from './types.ts';

const WORLD_MIN = -120;
const WORLD_MAX = 120;

const _scratchNormal = new THREE.Vector3();
const _scratchPos = new THREE.Vector3();

/** Default spawn density per biome (instances per 10k m² approx). */
const DEFAULT_BIOME_DENSITY: Record<string, FaunaBiomeDensity> = {
    arpeggio_grove: { beetle: 8, hopper: 6, moth: 4 },
    crystalline_nebula: { beetle: 4, hopper: 3, moth: 10 },
    luminous_plants: { beetle: 5, hopper: 4, moth: 8 },
    gem_canopy: { beetle: 6, hopper: 5, moth: 3 },
    lake_features: { beetle: 3, hopper: 2, moth: 5 },
    sky_islands: { beetle: 2, hopper: 2, moth: 9 },
    global: { beetle: 5, hopper: 4, moth: 4 },
};

/** Species mix used for sky-island roosts when CONFIG omits one. */
const DEFAULT_ROOST_DENSITY: FaunaBiomeDensity = { beetle: 1, hopper: 1, moth: 8 };

/**
 * Max |deckY - groundQueryY| tolerated before a roost anchor is rejected.
 *
 * The walkable platform registered for an island spans `[topY - 0.8, topY]`, so
 * a healthy query lands within ~1u of the registry's deck Y. A larger gap means
 * the platform never registered (placement failed, or the island was culled) and
 * the query fell through to terrain far below — dropping the anchor is what
 * keeps a roost from spawning in midair or inside the ground.
 */
const ROOST_DECK_TOLERANCE = 2.5;

/** Hover offset above the resolved surface, per species. */
function speciesHoverOffset(species: FaunaSpecies): number {
    if (species === FaunaSpecies.SugarMoth) return 2.5;
    if (species === FaunaSpecies.JellybeanHopper) return 0.22;
    return 0.14;
}

function mulberry32(seed: number): () => number {
    let s = seed >>> 0;
    return () => {
        s = (s + 0x6d2b79f5) >>> 0;
        let t = s;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

function resolveBiomeAt(x: number, z: number): string {
    let bestBiome = 'global';
    let bestDist = Infinity;
    for (let i = 0; i < animatedFoliage.length; i++) {
        const obj = animatedFoliage[i];
        const biome = obj.userData?.biome as string | undefined;
        if (!biome) continue;
        obj.getWorldPosition(_scratchPos);
        const dx = _scratchPos.x - x;
        const dz = _scratchPos.z - z;
        const d2 = dx * dx + dz * dz;
        if (d2 < bestDist) {
            bestDist = d2;
            bestBiome = biome;
        }
    }
    return bestBiome;
}

function speciesForSlot(slot: number, density: FaunaBiomeDensity, rng: () => number): FaunaSpecies {
    const total = density.beetle + density.hopper + density.moth;
    if (total <= 0) return FaunaSpecies.GumdropBeetle;
    let pick = rng() * total;
    if (pick < density.beetle) return FaunaSpecies.GumdropBeetle;
    pick -= density.beetle;
    if (pick < density.hopper) return FaunaSpecies.JellybeanHopper;
    return FaunaSpecies.SugarMoth;
}

export interface SpawnFaunaOptions {
    world: World;
    buffer: Float32Array;
    bufferByteOffset: number;
    maxCount: number;
    seed?: number;
}

/** Shared writer for both spawn passes — keeps buffer layout in one place. */
function writeCritter(
    ctx: {
        world: World;
        buffer: Float32Array;
        base: number;
        rng: () => number;
        entries: FaunaSpawnEntry[];
    },
    slot: number,
    x: number,
    surfaceY: number,
    z: number,
    species: FaunaSpecies,
    biome: string
): void {
    const { world, buffer, base, rng, entries } = ctx;
    const normal = sampleGroundNormal(x, z, _scratchNormal);

    const b = base + slot * FAUNA_BOID_STRIDE;
    buffer[b] = x;
    buffer[b + 1] = surfaceY + speciesHoverOffset(species);
    buffer[b + 2] = z;
    buffer[b + 3] = (rng() - 0.5) * 0.5;
    buffer[b + 4] = 0;
    buffer[b + 5] = (rng() - 0.5) * 0.5;
    buffer[b + 6] = rng() * Math.PI * 2;
    buffer[b + 7] = species;

    const entity = world.createEntity();
    const component: FaunaComponent = {
        slot,
        species,
        state: FaunaState.Wander,
        biome,
        normalX: normal.x,
        normalY: normal.y,
        normalZ: normal.z,
    };
    world.addComponent(entity, 'fauna', component);
    entries.push({ entity, component });
}

/**
 * Seat a flock on each registered sky-island deck (#1363 task 7).
 *
 * Runs before the terrain scatter so roosts are guaranteed a slice of the cap
 * rather than competing with ~58k m² of random samples. Returns the next free
 * slot; a no-op returning `startSlot` when roosts are disabled or no islands
 * are registered (CORE mode / `SKY_ISLANDS.enabled === false`).
 */
function spawnSkyIslandRoosts(
    ctx: {
        world: World;
        buffer: Float32Array;
        base: number;
        rng: () => number;
        entries: FaunaSpawnEntry[];
    },
    startSlot: number,
    maxCount: number
): number {
    const cfg = CONFIG.fauna?.roosts;
    if (cfg && cfg.enabled === false) return startSlot;

    const anchors = getSkyIslandRoostAnchors(
        {
            perIsland: cfg?.perIsland ?? DEFAULT_ROOST_PLAN.perIsland,
            ringInset: cfg?.ringInset ?? DEFAULT_ROOST_PLAN.ringInset,
            jitter: cfg?.jitter ?? DEFAULT_ROOST_PLAN.jitter,
        },
        ctx.rng
    );
    if (anchors.length === 0) return startSlot;

    const density = cfg?.density ?? DEFAULT_ROOST_DENSITY;
    let slot = startSlot;
    let rejected = 0;

    for (const anchor of anchors) {
        if (slot >= maxCount) break;

        // Resolve through the unified ground query so the deck comes from the
        // registered walkable platform, not the registry's cached Y (#1265).
        const surfaceY = getGroundHeight(anchor.x, anchor.z);
        if (Math.abs(surfaceY - anchor.y) > ROOST_DECK_TOLERANCE) {
            rejected++;
            continue;
        }

        const species = speciesForSlot(slot, density, ctx.rng);
        writeCritter(ctx, slot, anchor.x, surfaceY, anchor.z, species, 'sky_islands');
        slot++;
    }

    const placed = slot - startSlot;
    if (rejected > 0) {
        console.warn(
            `[Fauna] ${rejected}/${anchors.length} sky-island roosts skipped — deck not resolvable via ground query`
        );
    }
    if (placed > 0) {
        console.log(`[Fauna] Seated ${placed} roost critters across sky islands`);
    }
    return slot;
}

/**
 * Spawn fauna into ECS + dense boid buffer. Returns spawn entries for the batcher.
 */
export function spawnFaunaPopulation(opts: SpawnFaunaOptions): FaunaSpawnEntry[] {
    const { world, buffer, bufferByteOffset, maxCount } = opts;
    const rng = mulberry32(opts.seed ?? 0xc0ffee);
    const biomeDensity = CONFIG.fauna?.biomeDensity ?? DEFAULT_BIOME_DENSITY;
    const areaScale = (CONFIG.fauna?.areaScale ?? 1.0) * ((WORLD_MAX - WORLD_MIN) / 256);

    world.registerNativeComponent('fauna', faunaComponentCodec);

    const entries: FaunaSpawnEntry[] = [];
    const base = bufferByteOffset >> 2;
    const ctx = { world, buffer, base, rng, entries };

    // Reserved pass: sky-island roost flocks (#1363 task 7).
    let slot = spawnSkyIslandRoosts(ctx, 0, maxCount);

    // Terrain scatter fills whatever cap remains.
    const attempts = maxCount * 4;
    for (let a = 0; a < attempts && slot < maxCount; a++) {
        const x = WORLD_MIN + rng() * (WORLD_MAX - WORLD_MIN);
        const z = WORLD_MIN + rng() * (WORLD_MAX - WORLD_MIN);
        const biome = resolveBiomeAt(x, z);
        const density = biomeDensity[biome] ?? biomeDensity.global ?? DEFAULT_BIOME_DENSITY.global;

        const spawnRoll = rng();
        const threshold = ((density.beetle + density.hopper + density.moth) / 30) * areaScale;
        if (spawnRoll > Math.min(0.85, threshold)) continue;

        const species = speciesForSlot(slot, density, rng);
        const y = getGroundHeight(x, z);

        writeCritter(ctx, slot, x, y, z, species, biome);
        slot++;
    }

    return entries;
}

import * as THREE from 'three';
import { DataUtils } from 'three';
import { VisualState } from '../audio/audio-system.ts';
import {
    fluidInit, fluidStep, fluidAddDensity, fluidAddVelocity, getFluidDensityView
} from '../utils/wasm-loader.ts';

export class FluidSystem {
    private size: number = 128;
    public texture: THREE.DataTexture;
    private textureData: Uint16Array;
    private densityView: Float32Array | null = null;
    private initialized: boolean = false;

    constructor() {
        // Create initial texture (black)
        // RedFormat + HalfFloatType (r16float): filterable in WebGPU without any device extensions,
        // which avoids the 'textureLoad(texture_2d, vec2)' WGSL error caused by r32float textures.
        this.textureData = new Uint16Array(this.size * this.size);
        this.texture = new THREE.DataTexture(
            this.textureData as Uint16Array<ArrayBuffer>,
            this.size,
            this.size,
            THREE.RedFormat,
            THREE.HalfFloatType
        );
        this.texture.magFilter = THREE.LinearFilter;
        this.texture.minFilter = THREE.LinearFilter;
        this.texture.needsUpdate = true;
    }

    init() {
        try {
            fluidInit(this.size);
            this.densityView = getFluidDensityView(this.size);
            if (this.densityView) {
                this.initialized = true;
                console.log('[FluidSystem] Initialized C++ Fluid Solver');
            }
        } catch (e) {
            console.warn('[FluidSystem] Failed to init WASM fluid:', e);
        }
    }

    update(delta: number, audio: VisualState) {
        // Try to lazy init if WASM became ready
        if (!this.initialized) {
            this.densityView = getFluidDensityView(this.size);
            if (this.densityView) {
                this.initialized = true;
                console.log('[FluidSystem] Late Init Success');
            } else {
                return;
            }
        }

        const dt = Math.min(delta, 0.1);

        // --- Input Injection ---

        const kick = audio.kickTrigger ?? 0;
        const high =
            audio.channelData?.reduce((max, ch) => Math.max(max, ch.volume ?? 0), 0) ??
            audio.grooveAmount ??
            0;

        // 1. Kick Drum: Upward blast from bottom center
        if (kick > 0.1) {
             const cx = this.size / 2;
             const cy = 5; // Bottom
             const spread = 5;

             for(let i=0; i<3; i++) {
                 const ox = (Math.random() - 0.5) * spread;
                 const oy = (Math.random() - 0.5) * spread;

                 // Add Density
                 this.addDensity(cx + ox, cy + oy, 50 * kick * dt);

                 // Add Velocity (Upward)
                 this.addVelocity(cx + ox, cy + oy, (Math.random()-0.5)*2, 10 * kick);
             }
        }

        // 2. High Freq: Random sparkles/drips
        if (high > 0.2) {
             const x = Math.floor(Math.random() * this.size);
             const y = Math.floor(Math.random() * this.size);
             this.addDensity(x, y, 20 * high * dt);
             this.addVelocity(x, y, (Math.random()-0.5)*5, (Math.random()-0.5)*5);
        }

        // --- Simulation Step ---
        // visc, diff
        fluidStep(dt, 0.00001, 0.00001);

        // --- Update Texture ---
        // Copy WASM memory to Texture buffer, converting float32 → float16.
        // Note: densityView is a view into the WASM heap.
        // textureData is a Uint16Array holding half-float values.
        if (this.densityView) {
            for (let i = 0; i < this.densityView.length; i++) {
                this.textureData[i] = DataUtils.toHalfFloat(this.densityView[i]);
            }
            this.texture.needsUpdate = true;
        }
    }

    addDensity(x: number, y: number, amount: number) {
        fluidAddDensity(Math.floor(x), Math.floor(y), amount);
    }

    addVelocity(x: number, y: number, amountX: number, amountY: number) {
        fluidAddVelocity(Math.floor(x), Math.floor(y), amountX, amountY);
    }
}

// Global instance
export const fluidSystem = new FluidSystem();

import * as THREE from 'three';
import { color, float, attribute, storage, instanceIndex, Fn, If, vec4, uniform, positionLocal, smoothstep } from 'three/tsl';
import { MeshStandardNodeMaterial, StorageInstancedBufferAttribute } from 'three/webgpu';
import { addCameraShake } from '../core/camera-shake.ts';
import { spawnImpact } from '../foliage/impacts.ts';
import { uGlitchExplosionCenter, uGlitchExplosionRadius, sharedGeometries } from '../foliage/index.ts';
import { getGroundHeight } from '../systems/ground-system.ts';

const MAX_GRENADES = 10; // Simple fixed pool size

// Simple interface for an active glitch grenade CPU proxy
interface GlitchGrenade {
    active: boolean;
    position: THREE.Vector3;
    velocity: THREE.Vector3;
    lifetime: number; // Max flight time just in case it falls into the void
}

class GlitchGrenadeSystem {
    private grenades: GlitchGrenade[] = [];
    private explosionTimer: number = 0;

    // ⚡ OPTIMIZATION: Use InstancedMesh instead of instantiating individual meshes
    private mesh: THREE.InstancedMesh;
    private initialized: boolean = false;

    // Compute Shader nodes
    private computeNode: any;
    private uDeltaTime: any;

    // Buffers for CPU <-> GPU sync
    private stateArray: Float32Array;
    private velocityArray: Float32Array;
    private stateBuffer: StorageInstancedBufferAttribute;
    private velocityBuffer: StorageInstancedBufferAttribute;

    // Config
    private gravity: number = 15.0;
    private throwSpeed: number = 20.0;
    private maxLifetime: number = 5.0;
    private explosionDuration: number = 2.0; // How long the glitch field lasts
    private explosionRadiusMax: number = 8.0;

    constructor() {
        const geo = sharedGeometries.unitSphere.clone(); // Clone to avoid modifying shared geometry attributes

        this.stateArray = new Float32Array(MAX_GRENADES * 4);
        this.velocityArray = new Float32Array(MAX_GRENADES * 4);

        // Hide all initially
        for (let i = 0; i < MAX_GRENADES; i++) {
            this.stateArray[i * 4 + 3] = 0; // w = 0 means inactive
        }

        this.stateBuffer = new StorageInstancedBufferAttribute(this.stateArray, 4);
        this.velocityBuffer = new StorageInstancedBufferAttribute(this.velocityArray, 4);

        geo.setAttribute('aState', this.stateBuffer);
        geo.setAttribute('aVelocity', this.velocityBuffer);

        const mat = new MeshStandardNodeMaterial({
            transparent: true,
            depthWrite: false
        });

        mat.colorNode = color(0x00ffff);
        mat.emissiveNode = color(0xff00ff);
        mat.roughnessNode = float(0.2);

        const stateAttr = attribute('aState', 'vec4');
        const velAttr = attribute('aVelocity', 'vec4');

        const instancePos = stateAttr.xyz;
        const activeState = stateAttr.w;

        // Fixed scale for grenades
        const scale = float(0.3);

        mat.positionNode = positionLocal.mul(scale).add(instancePos);

        // Hide inactive grenades
        mat.opacityNode = smoothstep(0.0, 0.01, activeState);

        this.mesh = new THREE.InstancedMesh(geo, mat, MAX_GRENADES);
        this.mesh.matrixAutoUpdate = false;
        this.mesh.frustumCulled = false;
        this.mesh.castShadow = true;

        // ⚡ OPTIMIZATION: Write a pure identity matrix into the instanceMatrix buffer
        const identityMatrix = new THREE.Matrix4();
        for (let i = 0; i < MAX_GRENADES; i++) {
            // ⚡ OPTIMIZATION: Write directly to instanceMatrix array instead of updateMatrix + setMatrixAt
        identityMatrix.toArray(this.mesh.instanceMatrix.array, (i) * 16);
        }
        this.mesh.instanceMatrix.needsUpdate = true;

        // ⚡ OPTIMIZATION: Initialize CPU Object Pool (Collision Proxy)
        for (let i = 0; i < MAX_GRENADES; i++) {
            this.grenades.push({
                active: false,
                position: new THREE.Vector3(),
                velocity: new THREE.Vector3(),
                lifetime: 0
            });
        }

        // --- WebGPU COMPUTE SHADER LOGIC ---
        this.uDeltaTime = uniform(0);

        const updateGrenadesCompute = (Fn as any)((): void => {
            const index = instanceIndex;

            const stateNode = storage(this.stateBuffer, 'vec4', MAX_GRENADES).element(index);
            const velNode = storage(this.velocityBuffer, 'vec4', MAX_GRENADES).element(index);

            const pos = stateNode.xyz;
            const active = stateNode.w;

            const vel = velNode.xyz;

            const dt = this.uDeltaTime;

            If(active.greaterThan(0.0), () => {
                // Apply gravity
                const newVel = vec4(vel.x, vel.y.sub(float(this.gravity).mul(dt)), vel.z, 0.0);
                // Move
                const newPos = pos.add(newVel.xyz.mul(dt));

                stateNode.assign(vec4(newPos, active));
                velNode.assign(newVel);
            });
        });

        this.computeNode = (updateGrenadesCompute() as unknown as { compute: (n: number) => unknown }).compute(MAX_GRENADES);
    }

    /**
     * Throws a new glitch grenade from the origin in the given direction.
     */
    public throwGrenade(scene: THREE.Scene, origin: THREE.Vector3, direction: THREE.Vector3) {
        if (!this.initialized) {
            scene.add(this.mesh);
            this.initialized = true;
        }

        // Find inactive grenade
        let idx = -1;
        for (let i = 0; i < MAX_GRENADES; i++) {
            if (!this.grenades[i].active) {
                idx = i;
                break;
            }
        }

        if (idx === -1) return; // Pool full

        const grenade = this.grenades[idx];
        grenade.active = true;
        grenade.lifetime = 0;

        // Start slightly in front of the player/camera
        grenade.position.copy(origin).addScaledVector(direction, 0.5);

        // Calculate initial velocity (forward + slightly up for arc)
        grenade.velocity.copy(direction).normalize().multiplyScalar(this.throwSpeed);
        grenade.velocity.y += 5.0; // Upward arc

        // Update GPU Backing Buffer
        this.stateArray[idx * 4 + 0] = grenade.position.x;
        this.stateArray[idx * 4 + 1] = grenade.position.y;
        this.stateArray[idx * 4 + 2] = grenade.position.z;
        this.stateArray[idx * 4 + 3] = 1.0; // active

        this.velocityArray[idx * 4 + 0] = grenade.velocity.x;
        this.velocityArray[idx * 4 + 1] = grenade.velocity.y;
        this.velocityArray[idx * 4 + 2] = grenade.velocity.z;
        this.velocityArray[idx * 4 + 3] = 0.0;

        this.stateBuffer.needsUpdate = true;
        this.velocityBuffer.needsUpdate = true;

        // Spawn small throw effect
        spawnImpact(grenade.position, 'dash');
    }

    /**
     * Updates grenade physics and the explosion fading logic.
     */
    public update(delta: number, scene: THREE.Scene, renderer?: THREE.WebGLRenderer | any) {
        // Run GPU Compute Shader first
        if (renderer && renderer.compute) {
            this.uDeltaTime.value = delta;
            renderer.compute(this.computeNode);
        }

        // 1. Update Explosion Fading (Decrement Timer)
        if (this.explosionTimer > 0) {
            this.explosionTimer -= delta;

            if (this.explosionTimer <= 0) {
                // Turn off glitch field completely
                uGlitchExplosionRadius.value = 0;
            } else {
                // Stay large for a bit, then shrink
                const progress = this.explosionTimer / this.explosionDuration;
                const radiusFactor = Math.pow(progress, 0.5);
                uGlitchExplosionRadius.value = this.explosionRadiusMax * radiusFactor;
            }
        }

        if (!this.initialized) return;

        let needsStateUpdate = false;

        // 2. Update CPU proxy for collisions
        for (let i = 0; i < MAX_GRENADES; i++) {
            const grenade = this.grenades[i];

            if (!grenade.active) continue;

            // CPU Proxy Simulation
            grenade.velocity.y -= this.gravity * delta;
            grenade.position.addScaledVector(grenade.velocity, delta);
            grenade.lifetime += delta;

            // Check Ground Collision using unified ground height
            const groundY = getGroundHeight(grenade.position.x, grenade.position.z);

            if (grenade.position.y <= groundY || grenade.lifetime > this.maxLifetime) {
                // Snap to ground level if it hit
                if (grenade.position.y <= groundY) {
                     grenade.position.y = groundY;
                }

                // EXPLODE!
                this.triggerExplosion(grenade.position);

                // Cleanup (Deactivate and hide)
                grenade.active = false;

                // Sync death state to GPU
                this.stateArray[i * 4 + 3] = 0; // inactive
                needsStateUpdate = true;
            } else {
                // Sync current CPU proxy position back to stateArray
                // in case we need to upload due to other grenades dying
                this.stateArray[i * 4 + 0] = grenade.position.x;
                this.stateArray[i * 4 + 1] = grenade.position.y;
                this.stateArray[i * 4 + 2] = grenade.position.z;
                this.stateArray[i * 4 + 3] = 1.0;

                this.velocityArray[i * 4 + 0] = grenade.velocity.x;
                this.velocityArray[i * 4 + 1] = grenade.velocity.y;
                this.velocityArray[i * 4 + 2] = grenade.velocity.z;
            }
        }

        if (needsStateUpdate) {
            this.stateBuffer.needsUpdate = true;
            this.velocityBuffer.needsUpdate = true;
        }
    }

    private triggerExplosion(position: THREE.Vector3) {
        // Set the TSL uniforms to apply the local glitch shader
        (uGlitchExplosionCenter.value as unknown as THREE.Vector3).copy(position);
        uGlitchExplosionRadius.value = this.explosionRadiusMax;

        // Reset timer
        this.explosionTimer = this.explosionDuration;

        // Visual impact (reusing spore or jump for now)
        spawnImpact(position, 'spore');

        // 🎨 Palette: Juice up the explosion with shake and sound
        addCameraShake(0.8);
        if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
            (window as any).AudioSystem.playSound('explosion', { position, pitch: 0.5 + Math.random() * 0.5, volume: 1.0 });
        }
    }
}

// Export singleton instance
export const glitchGrenadeSystem = new GlitchGrenadeSystem();

import * as THREE from 'three';
import { CONFIG } from '../core/config.ts';

// Define interface for interactive objects with userdata
export interface InteractiveObject extends THREE.Object3D {
    userData: {
        onProximityEnter?: (distanceSq: number) => void;
        onProximityLeave?: () => void;
        onGazeEnter?: () => void;
        onGazeLeave?: () => void;
        onInteract?: () => void;
        // Other possible userData properties
        [key: string]: any;
    };
    visible: boolean;
    parent: THREE.Object3D | null;
}

// Callback type for reticle updates
export type ReticleCallback = (state: 'idle' | 'hover' | 'interact', label?: string) => void;

export class InteractionSystem {
    camera: THREE.Camera;
    raycaster: THREE.Raycaster;
    hoveredObject: InteractiveObject | null;

    // ⚡ OPTIMIZATION: Replacing Sets with Arrays to prevent Iterator allocation spikes in hot loops
    _nearbyArrayA: InteractiveObject[];
    _nearbyArrayB: InteractiveObject[];
    nearbyObjects: InteractiveObject[];
    _nearbyCountA: number;
    _nearbyCountB: number;
    nearbyCount: number;

    _candidatesScratch: InteractiveObject[];
    _scratchVec2: THREE.Vector2;
    reticleCallback: ReticleCallback | null;

    proximityRadius: number;
    proximityRadiusSq: number;
    interactionDistance: number;

    constructor(camera: THREE.Camera, reticleCallback: ReticleCallback | null) {
        this.camera = camera;
        this.raycaster = new THREE.Raycaster();

        // Use CONFIG if available, otherwise fallback
        this.raycaster.far = CONFIG?.interaction?.maxDistance || 50;

        this.hoveredObject = null;

        // ⚡ OPTIMIZATION: Double-buffered Arrays to avoid 'new Set()' and Iterator creation every frame
        this._nearbyArrayA = [];
        this._nearbyArrayB = [];
        this.nearbyObjects = this._nearbyArrayA; // Points to the "Previous Frame" array initially
        this._nearbyCountA = 0;
        this._nearbyCountB = 0;
        this.nearbyCount = 0;

        // ⚡ OPTIMIZATION: Reusable scratch array for raycast candidates
        this._candidatesScratch = [];

        // ⚡ OPTIMIZATION: Reusable Vector2 for raycasting to avoid per-frame allocation
        this._scratchVec2 = new THREE.Vector2(0, 0);

        this.reticleCallback = reticleCallback;

        // Load settings
        this.proximityRadius = CONFIG?.interaction?.proximityRadius || 12.0;
        this.proximityRadiusSq = this.proximityRadius * this.proximityRadius;
        this.interactionDistance = CONFIG?.interaction?.interactionDistance || 8.0;
    }

    // ⚡ OPTIMIZATION: Accepts array of lists to avoid argument spreading allocation
    update(dt: number, playerPosition: THREE.Vector3, interactableLists: (THREE.Object3D[] | undefined)[]) {
        // Swap arrays: 'nearbyObjects' becomes 'prevNearby', and we fill 'nextNearby'
        const prevNearby = this.nearbyObjects;
        const prevCount = this.nearbyCount;

        let nextNearby: InteractiveObject[];
        let nextCount = 0;

        if (prevNearby === this._nearbyArrayA) {
            nextNearby = this._nearbyArrayB;
            this._nearbyCountB = 0;
        } else {
            nextNearby = this._nearbyArrayA;
            this._nearbyCountA = 0;
        }

        // 1. PROXIMITY CHECK
        // Populate nextNearby with ALL close objects from all input lists
        const px = playerPosition.x;
        const py = playerPosition.y;
        const pz = playerPosition.z;
        const radiusSq = this.proximityRadiusSq;

        for (let i = 0; i < interactableLists.length; i++) {
            const list = interactableLists[i];
            if (!list || !Array.isArray(list)) continue;

            const len = list.length;
            for (let j = 0; j < len; j++) {
                const obj = list[j] as InteractiveObject;
                // Safety: Skip invalid objects or those without position
                if (!obj || !obj.position || !obj.visible) continue;

                const ud = obj.userData;
                if (!ud || (!ud.onProximityEnter && !ud.onProximityLeave && !ud.onGazeEnter && !ud.onGazeLeave && !ud.onInteract && !ud.interactionText)) continue;

                // ⚡ OPTIMIZATION: Inline distance squared check to avoid Three.js Vector3.distanceToSquared allocations and function call overhead.
                const pos = obj.position;
                const dx = px - pos.x;
                const dy = py - pos.y;
                const dz = pz - pos.z;
                const distSq = dx*dx + dy*dy + dz*dz;

                if (distSq < radiusSq) {
                    nextNearby[nextCount++] = obj;
                }
            }
        }

        // ⚡ OPTIMIZATION: Null out remaining array elements to prevent memory leaks from retained old objects
        for (let i = nextCount; i < nextNearby.length; i++) {
            if (nextNearby[i] === null) break; // Already cleared remainder
            nextNearby[i] = null as any;
        }

        // ⚡ OPTIMIZATION: O(N^2) check is fine here because nearby count is usually very small (< 10)
        // Check for Enters (Object is in Next but was not in Prev)
        for (let i = 0; i < nextCount; i++) {
            const obj = nextNearby[i];
            let found = false;
            for (let j = 0; j < prevCount; j++) {
                if (prevNearby[j] === obj) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                if (obj.userData?.onProximityEnter) {
                    // ⚡ OPTIMIZATION: Replaced distanceTo() with distanceToSquared() and removed Math.sqrt() overhead.
                    try { obj.userData.onProximityEnter(playerPosition.distanceToSquared(obj.position)); } catch(e) { console.warn('Proximity Enter Error:', e); }
                }
            }
        }

        // Check for Leaves (Object was in Prev but is not in Next)
        for (let i = 0; i < prevCount; i++) {
            const obj = prevNearby[i];
            let found = false;
            for (let j = 0; j < nextCount; j++) {
                if (nextNearby[j] === obj) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                if (obj.userData?.onProximityLeave) {
                    try { obj.userData.onProximityLeave(); } catch(e) { console.warn('Proximity Leave Error:', e); }
                }
                if (this.hoveredObject === obj) this.handleHover(null);
            }
        }

        // Update pointer for next frame
        this.nearbyObjects = nextNearby;
        this.nearbyCount = nextCount;

        // 2. GAZE CHECK
        // Populate scratch array from the active portion of the array
        this._candidatesScratch.length = 0;
        for (let i = 0; i < this.nearbyCount; i++) {
            const obj = this.nearbyObjects[i];
            // Extra Safety: Ensure root object is valid before raycasting
            if (obj && obj.visible !== false) {
                this._candidatesScratch.push(obj);
            }
        }

        const candidates = this._candidatesScratch;

        if (candidates.length > 0) {
            // ⚡ OPTIMIZATION: Use scratch vector
            this._scratchVec2.set(0, 0);
            this.raycaster.setFromCamera(this._scratchVec2, this.camera);

            // CRITICAL: Wrap raycast in try/catch to handle malformed geometry.
            // When using recursive=true, Raycaster visits all children.
            // If any child is a Mesh with undefined geometry (e.g., loading state),
            // accessing 'boundingSphere' will throw a TypeError.
            try {
                // Raycaster.intersectObjects accepts Object3D[], but candidates is InteractiveObject[].
                // InteractiveObject extends Object3D, so this is valid.
                const intersects = this.raycaster.intersectObjects(candidates, true);

                if (intersects.length > 0) {
                    let hitObj = intersects[0].object as unknown as InteractiveObject; // Start with the mesh hit
                    let rootObj: InteractiveObject | null = null;
                    const hitDist = intersects[0].distance;

                    // Bubble up to find the logic root (the Group with userData)
                    let depth = 0;

                    while (hitObj && depth < 10) {
                        // We check if this ancestor is one of our tracked interactables
                        let isTracked = false;
                        for (let k = 0; k < this.nearbyCount; k++) {
                            if (this.nearbyObjects[k] === hitObj) {
                                isTracked = true;
                                break;
                            }
                        }
                        if (isTracked) {
                            rootObj = hitObj;
                            break;
                        }
                        hitObj = hitObj.parent as InteractiveObject;
                        depth++;
                    }

                    if (rootObj && hitDist < this.interactionDistance) {
                        this.handleHover(rootObj);
                        return;
                    }
                }
            } catch (err: any) {
                // Suppress "boundingSphere of undefined" errors caused by uninitialized meshes
                // This keeps the game loop running even if one object is glitches.
                if (err instanceof TypeError && err.message.includes('boundingSphere')) {
                    // Known safe error, ignore
                } else {
                    if (Math.random() < 0.01) console.warn("Interaction Raycast Warning:", err);
                }
            }
        }

        this.handleHover(null);
    }

    handleHover(object: InteractiveObject | null) {
        if (this.hoveredObject === object) return;

        // Leave old
        if (this.hoveredObject && this.hoveredObject.userData?.onGazeLeave) {
            try { this.hoveredObject.userData.onGazeLeave(); } catch(e) { void e; }
        }

        // Enter new
        this.hoveredObject = object;

        if (this.hoveredObject) {
            if (this.hoveredObject.userData?.onGazeEnter) {
                try { this.hoveredObject.userData.onGazeEnter(); } catch(e) { void e; }
            }
            if (this.reticleCallback) {
                const label = this.getLabel(this.hoveredObject);
                this.reticleCallback('hover', label);
            }
        } else {
            if (this.reticleCallback) this.reticleCallback('idle');
        }
    }

    private getLabel(object: InteractiveObject): string {
        if (object.userData?.interactionText) return object.userData.interactionText;
        if (object.userData?.type) {
            const type = object.userData.type;
            // Simple fallback formatting
            return type.charAt(0).toUpperCase() + type.slice(1);
        }
        return '';
   }

    triggerClick(): boolean {
        if (this.hoveredObject && this.hoveredObject.userData?.onInteract) {
            try {
                this.hoveredObject.userData.onInteract();
                if (this.reticleCallback) {
                    this.reticleCallback('interact');
                    // Restore hover state with label
                    setTimeout(() => {
                        if (this.reticleCallback && this.hoveredObject) {
                            const label = this.getLabel(this.hoveredObject);
                            this.reticleCallback('hover', label);
                        }
                    }, 150);
                }
                return true;
            } catch(e) {
                console.warn("Interact Error", e);
            }
        }
        return false;
    }
}

/**
 * Loading Manager
 *
 * Centralized progress tracker for all loading phases and subtasks.
 * Acts as the single source of truth for loading state — including the
 * post-interactive deferred population phase driven by BackgroundProcessor.
 */

import { DEFAULT_LOADING_PHASES } from '../ui/loading-screen-types';

export interface LoadingTaskOptions {
    id: string;
    name: string;
    weight: number; // Relative importance/time cost (0-1 typically)
    description?: string;
    totalSubTasks?: number;
    isDeferred?: boolean;
}

export interface TaskState {
    id: string;
    name: string;
    weight: number;
    description: string;
    totalSubTasks: number;
    completedSubTasks: number;
    percentComplete: number; // 0 to 100
    isDeferred: boolean;
    startTime: number;
    endTime: number;
    status: 'pending' | 'active' | 'completed' | 'error' | 'skipped';
}

export interface GlobalProgressState {
    overallPercent: number; // 0 to 100
    activeTaskId: string | null;
    activeTaskName: string | null;
    activeTaskDescription: string | null;
    estimatedTimeRemaining: number; // seconds
    // Deferred / post-interactive population progress
    deferredCompleted: number;
    deferredTotal: number;
    deferredFailed: number;
    deferredPercent: number; // 0-100, 0 if not started
    deferredEtaMs: number;  // -1 = unknown, 0 = done, >0 = ms remaining
}

export type ProgressCallback = (state: GlobalProgressState, tasks: Map<string, TaskState>) => void;
export type PhaseChangeCallback = (activeTaskId: string | null) => void;

export class LoadingManager {
    private tasks: Map<string, TaskState> = new Map();
    private taskOrder: string[] = [];
    private activeTaskId: string | null = null;

    // Callbacks
    private onProgressCallbacks: Set<ProgressCallback> = new Set();
    private onPhaseChangeCallbacks: Set<PhaseChangeCallback> = new Set();

    // Timing stats
    private averageTaskTimeMs: number = 0;
    private completedWeights: number = 0;
    private totalWeight: number = 0;
    private globalStartTime: number = 0;

    // Deferred population state (driven by BackgroundProcessor)
    private deferredCompleted: number = 0;
    private deferredTotal: number = 0;
    private deferredFailed: number = 0;
    private deferredEtaMs: number = -1;

    constructor() {}

    /**
     * Register a new task/phase.
     */
    registerTask(options: LoadingTaskOptions): void {
        const state: TaskState = {
            id: options.id,
            name: options.name,
            weight: options.weight,
            description: options.description || '',
            totalSubTasks: options.totalSubTasks || 100,
            completedSubTasks: 0,
            percentComplete: 0,
            isDeferred: options.isDeferred || false,
            startTime: 0,
            endTime: 0,
            status: 'pending'
        };

        this.tasks.set(options.id, state);
        this.taskOrder.push(options.id);
        this.totalWeight += options.weight;
    }

    /**
     * Starts a task, marking it as active.
     */
    startTask(id: string): void {
        const task = this.tasks.get(id);
        if (!task) {
            console.warn(`[LoadingManager] Cannot start unknown task: ${id}`);
            return;
        }

        if (this.globalStartTime === 0) {
            this.globalStartTime = performance.now();
        }

        task.status = 'active';
        task.startTime = performance.now();
        this.activeTaskId = id;

        this.emitPhaseChange();
        this.emitProgress();
    }

    /**
     * Report progress for a task directly (e.g. 0 to 100) or by subtasks.
     */
    reportProgress(id: string, completed: number, total?: number, description?: string): void {
        const task = this.tasks.get(id);
        if (!task) return;

        if (total !== undefined) {
            task.totalSubTasks = total;
        }

        task.completedSubTasks = Math.min(completed, task.totalSubTasks);
        task.percentComplete = task.totalSubTasks > 0
            ? (task.completedSubTasks / task.totalSubTasks) * 100
            : 100;

        if (description) {
            task.description = description;
        }

        if (task.status !== 'active' && task.status !== 'completed') {
            this.startTask(id);
        }

        this.emitProgress();
    }

    /**
     * Increment the subtask count for a task.
     */
    incrementSubtask(id: string, amount: number = 1, description?: string): void {
        const task = this.tasks.get(id);
        if (!task) return;

        this.reportProgress(id, task.completedSubTasks + amount, task.totalSubTasks, description);
    }

    /**
     * Marks a task as complete.
     */
    completeTask(id: string): void {
        const task = this.tasks.get(id);
        if (!task) return;

        task.status = 'completed';
        task.completedSubTasks = task.totalSubTasks;
        task.percentComplete = 100;
        task.endTime = performance.now();

        this.completedWeights += task.weight;
        this.updateAverageTime(task.endTime - task.startTime, task.weight);

        if (this.activeTaskId === id) {
            this.activeTaskId = null;
        }

        this.emitProgress();
    }

    /**
     * Skips a deferred task.
     */
    skipTask(id: string): void {
        const task = this.tasks.get(id);
        if (!task || !task.isDeferred) {
            console.warn(`[LoadingManager] Cannot skip task: ${id}`);
            return;
        }

        task.status = 'skipped';
        task.endTime = performance.now();
        this.completedWeights += task.weight * 0.5;

        if (this.activeTaskId === id) {
            this.activeTaskId = null;
        }

        this.emitProgress();
    }

    /**
     * Updates the task description
     */
    setTaskDescription(id: string, description: string): void {
        const task = this.tasks.get(id);
        if (task) {
            task.description = description;
            this.emitProgress();
        }
    }

    /**
     * Report progress from BackgroundProcessor for the post-interactive
     * deferred population phase.  This drives both the HUD indicator and any
     * 'deferred-population' task registered in the phase list.
     *
     * @param completed  Tasks completed so far (success + failed)
     * @param total      Total tasks enqueued
     * @param failed     Tasks that threw during execution
     */
    reportDeferredProgress(completed: number, total: number, failed: number = 0, etaMs: number = -1): void {
        this.deferredCompleted = completed;
        this.deferredTotal = total;
        this.deferredFailed = failed;
        this.deferredEtaMs = etaMs;

        // Also drive any registered 'deferred-population' task
        const task = this.tasks.get('deferred-population');
        if (task && task.status !== 'completed' && task.status !== 'skipped') {
            const pct = total > 0 ? Math.round((completed / total) * 100) : 0;
            const failLabel = failed > 0 ? ` (${failed} failed)` : '';
            this.reportProgress(
                'deferred-population',
                completed,
                total,
                `Populating horizon: ${completed}/${total}${failLabel}`
            );
            return; // reportProgress already emits
        }

        this.emitProgress();
    }

    /**
     * Calculates overall weighted progress (0 to 100).
     */
    getOverallProgress(): number {
        if (this.totalWeight === 0) return 0;

        let currentCompletedWeight = this.completedWeights;

        if (this.activeTaskId) {
            const activeTask = this.tasks.get(this.activeTaskId);
            if (activeTask && activeTask.status === 'active') {
                currentCompletedWeight += activeTask.weight * (activeTask.percentComplete / 100);
            }
        }

        return (currentCompletedWeight / this.totalWeight) * 100;
    }

    /**
     * Deferred population percent (0–100). 0 if not started.
     */
    getDeferredPercent(): number {
        return this.deferredTotal > 0
            ? Math.min(100, Math.round((this.deferredCompleted / this.deferredTotal) * 100))
            : 0;
    }

    /**
     * Calculates estimated time remaining in seconds.
     */
    getEstimatedTimeRemaining(): number {
        if (this.averageTaskTimeMs === 0 || this.totalWeight === 0) return -1;

        let remainingWeight = this.totalWeight - this.completedWeights;

        if (this.activeTaskId) {
            const activeTask = this.tasks.get(this.activeTaskId);
            if (activeTask && activeTask.status === 'active') {
                remainingWeight -= activeTask.weight * (activeTask.percentComplete / 100);
            }
        }

        const estimatedMs = remainingWeight * this.averageTaskTimeMs;
        return Math.max(0, Math.ceil(estimatedMs / 1000));
    }

    private updateAverageTime(durationMs: number, weight: number): void {
        if (weight <= 0) return;
        const normalizedTime = durationMs / weight;

        if (this.averageTaskTimeMs === 0) {
            this.averageTaskTimeMs = normalizedTime;
        } else {
            this.averageTaskTimeMs = (this.averageTaskTimeMs * 0.7) + (normalizedTime * 0.3);
        }
    }

    private emitProgress(): void {
        if (this.onProgressCallbacks.size === 0) return;

        const activeTask = this.activeTaskId ? this.tasks.get(this.activeTaskId) : null;
        const state: GlobalProgressState = {
            overallPercent: this.getOverallProgress(),
            activeTaskId: this.activeTaskId,
            activeTaskName: activeTask ? activeTask.name : null,
            activeTaskDescription: activeTask ? activeTask.description : null,
            estimatedTimeRemaining: this.getEstimatedTimeRemaining(),
            deferredCompleted: this.deferredCompleted,
            deferredTotal: this.deferredTotal,
            deferredFailed: this.deferredFailed,
            deferredPercent: this.getDeferredPercent(),
            deferredEtaMs: this.deferredEtaMs,
        };

        for (const cb of this.onProgressCallbacks) cb(state, this.tasks);
    }

    private emitPhaseChange(): void {
        for (const cb of this.onPhaseChangeCallbacks) cb(this.activeTaskId);
    }

    // Event subscription
    onProgress(cb: ProgressCallback): () => void {
        this.onProgressCallbacks.add(cb);
        return () => this.onProgressCallbacks.delete(cb);
    }

    onPhaseChange(cb: PhaseChangeCallback): () => void {
        this.onPhaseChangeCallbacks.add(cb);
        return () => this.onPhaseChangeCallbacks.delete(cb);
    }

    // Getters
    getTask(id: string): TaskState | undefined {
        return this.tasks.get(id);
    }

    getAllTasks(): TaskState[] {
        const tasks: TaskState[] = [];
        for (let i = 0; i < this.taskOrder.length; i++) {
            tasks.push(this.tasks.get(this.taskOrder[i])!);
        }
        return tasks;
    }
}

export const globalLoadingManager = new LoadingManager();

/**
 * @file material-batcher.ts
 * @brief WASM-accelerated material flash/fade batching
 * 
 * Batches material color lerping operations to reduce GC pressure
 * and improve performance when processing many reactive materials.
 * 
 * @example
 * ```ts
 * import { MaterialBatcher } from './systems/material-batcher';
 * 
 * const batcher = MaterialBatcher.getInstance();
 * 
 * // Register a material for batch processing
 * batcher.registerMaterial(mesh.material, baseColor, isBasic, hasEmissive);
 * 
 * // Trigger a flash
 * batcher.triggerFlash(mesh.material, flashColor, intensity);
 * 
 * // In animation loop - batch processes all materials
 * batcher.update(deltaTime);
 * ```
 */

import * as THREE from 'three';
import { CONFIG } from '../core/config.ts';
import { getWasmInstance } from '../utils/wasm-loader.ts';

// Material entry tracking
interface MaterialEntry {
    material: THREE.Material;
    index: number;
    isBasic: boolean;
    hasEmissive: boolean;
    baseColor: THREE.Color;
}

// Configuration
const MAX_MATERIALS = 2000;
const MATERIAL_STRIDE = 12; // floats per material
const RESULT_STRIDE = 4; // r, g, b, emissiveIntensity

// Memory layout (must match AssemblyScript)
const OFF_CURRENT_R = 0;
const OFF_CURRENT_G = 1;
const OFF_CURRENT_B = 2;
const OFF_BASE_R = 3;
const OFF_BASE_G = 4;
const OFF_BASE_B = 5;
const OFF_FLASH_R = 6;
const OFF_FLASH_G = 7;
const OFF_FLASH_B = 8;
const OFF_FLASH_INTENSITY = 9;
const OFF_EMISSIVE_INTENSITY = 10;
const OFF_FLAGS = 11;

// WASM memory offsets (must match AssemblyScript)
const MATERIAL_BUFFER_OFFSET = 200000;
const RESULT_BUFFER_OFFSET = 300000;

// Flag bits
const FLAG_BASIC = 1;
const FLAG_EMISSIVE = 2;
const FLAG_NEEDS_FADE = 4;

/**
 * Global material batcher for flash/fade operations
 */
export class MaterialBatcher {
    private static instance: MaterialBatcher;
    private initialized = false;

    // Material registry
    private materials = new Map<THREE.Material, MaterialEntry>();
    private materialList: MaterialEntry[] = [];
    private nextIndex = 0;

    // WASM function bindings
    private wasmBatchFlash: ((count: number, fadeSpeed: number, snapThreshold: number, flashScale: number) => number) | null = null;
    private wasmInitMaterial: ((index: number, ...args: number[]) => void) | null = null;
    private wasmTriggerFlash: ((index: number, r: number, g: number, b: number, intensity: number) => void) | null = null;
    private wasmGetResult: ((index: number, outPtr: number) => void) | null = null;
    private wasmNeedsFadeBack: ((index: number) => number) | null = null;
    private wasmGetFlashIntensity: ((index: number) => number) | null = null;

    // Result buffer (reused)
    private resultBuffer = new Float32Array(RESULT_STRIDE);
    private resultPtr = 0;

    // Stats
    private activeMaterials = 0;

    private constructor() {}

    static getInstance(): MaterialBatcher {
        if (!MaterialBatcher.instance) {
            MaterialBatcher.instance = new MaterialBatcher();
        }
        return MaterialBatcher.instance;
    }

    /**
     * Initialize WASM bindings and memory
     */
    init(): boolean {
        if (this.initialized) return true;

        const instance = getWasmInstance();
        if (!instance) {
            console.log('[MaterialBatcher] WASM not available, using JS fallback');
            return false;
        }

        // Bind WASM functions
        this.wasmBatchFlash = (instance.exports as any).batchMaterialFlash;
        this.wasmInitMaterial = (instance.exports as any).initMaterialEntry;
        this.wasmTriggerFlash = (instance.exports as any).triggerMaterialFlash;
        this.wasmGetResult = (instance.exports as any).getMaterialResult;
        this.wasmNeedsFadeBack = (instance.exports as any).materialNeedsFadeBack;
        this.wasmGetFlashIntensity = (instance.exports as any).getMaterialFlashIntensity;

        if (!this.wasmBatchFlash) {
            console.log('[MaterialBatcher] WASM batch function not available, using JS fallback');
            return false;
        }

        // Allocate result buffer in WASM memory
        const memory = (instance.exports as any).memory;
        if (memory) {
            // Use a small buffer at a fixed offset after the result buffer
            this.resultPtr = 400000; // 400KB
        }

        this.initialized = true;
        console.log('[MaterialBatcher] Initialized with WASM acceleration');
        return true;
    }

    /**
     * Register a material for batch processing
     * @param material - The Three.js material
     * @param baseColor - The base/resting color
     * @param isBasicMaterial - Whether it's MeshBasicMaterial
     * @param hasEmissive - Whether material has emissive property
     * @returns The material index, or -1 if at capacity
     */
    registerMaterial(
        material: THREE.Material,
        baseColor: THREE.Color,
        isBasicMaterial: boolean,
        hasEmissive: boolean
    ): number {
        // Check if already registered
        if (this.materials.has(material)) {
            return this.materials.get(material)!.index;
        }

        // Check capacity
        if (this.nextIndex >= MAX_MATERIALS) {
            console.warn('[MaterialBatcher] At capacity, material not registered');
            return -1;
        }

        if (!this.initialized) {
            this.init();
        }

        const index = this.nextIndex++;

        // Create entry
        const entry: MaterialEntry = {
            material,
            index,
            isBasic: isBasicMaterial,
            hasEmissive,
            baseColor: baseColor.clone()
        };

        this.materials.set(material, entry);
        this.materialList.push(entry);

        // Initialize in WASM
        if (this.initialized && this.wasmInitMaterial) {
            const currentColor = (material as any).color || new THREE.Color(0xFFFFFF);

            this.wasmInitMaterial(
                index,
                currentColor.r, currentColor.g, currentColor.b,
                baseColor.r, baseColor.g, baseColor.b,
                isBasicMaterial ? 1 : 0,
                hasEmissive ? 1 : 0
            );
        }

        return index;
    }

    /**
     * Unregister a material
     */
    unregisterMaterial(material: THREE.Material): void {
        const entry = this.materials.get(material);
        if (!entry) return;

        this.materials.delete(material);

        // Remove from list
        const idx = this.materialList.indexOf(entry);
        if (idx >= 0) {
            this.materialList.splice(idx, 1);
        }

        // Note: We don't reuse indices to keep it simple
        // In a production system, we'd want index reuse
    }

    /**
     * Trigger a flash on a material
     * @param material - The material to flash
     * @param color - Flash color
     * @param intensity - Flash intensity (0-1)
     */
    triggerFlash(material: THREE.Material, color: THREE.Color, intensity: number): void {
        const entry = this.materials.get(material);
        if (!entry) {
            // Material not registered, skip
            return;
        }

        if (this.initialized && this.wasmTriggerFlash) {
            this.wasmTriggerFlash(
                entry.index,
                color.r, color.g, color.b,
                intensity
            );
        } else {
            // JS fallback - set directly on userData for compatibility with existing code
            (material as any).userData = (material as any).userData || {};
            (material as any).userData.flashIntensity = intensity;
            (material as any).userData.flashColor = color;
            (material as any).userData.flashDecay = 0.05;
        }
    }

    /**
     * Update all batched materials
     * Call this once per frame
     */
    update(deltaTime: number): void {
        if (this.materialList.length === 0) return;

        if (this.initialized && this.wasmBatchFlash) {
            this.updateWasm();
        } else {
            this.updateJS();
        }
    }

    /**
     * Update using WASM batch processing
     */
    private updateWasm(): void {
        const instance = getWasmInstance();
        if (!instance) return;

        // Sync material data to WASM (in case JS modified it)
        this.syncToWasm();

        // Get config values
        const fadeSpeed = (CONFIG as any).reactivity?.fadeSpeed ?? 0.06;
        const snapThreshold = (CONFIG as any).reactivity?.fadeSnapThreshold ?? 0.06;
        const flashScale = (CONFIG as any).flashScale ?? 2.0;

        // Batch process
        this.activeMaterials = this.wasmBatchFlash!(
            this.materialList.length,
            fadeSpeed,
            snapThreshold,
            flashScale
        );

        // Sync results back to materials
        this.syncFromWasm();
    }

    /**
     * Sync current material state to WASM memory
     */
    private syncToWasm(): void {
        const instance = getWasmInstance();
        if (!instance) return;

        const F32 = new Float32Array((instance.exports.memory as any).buffer);

        for (const entry of this.materialList) {
            const base = MATERIAL_BUFFER_OFFSET + (entry.index * MATERIAL_STRIDE * 4);
            const mat = entry.material as any;

            // Update current color if it exists
            if (mat.color) {
                F32[base / 4 + OFF_CURRENT_R] = mat.color.r;
                F32[base / 4 + OFF_CURRENT_G] = mat.color.g;
                F32[base / 4 + OFF_CURRENT_B] = mat.color.b;
            }

            // Update flash intensity from userData
            if (mat.userData?.flashIntensity !== undefined) {
                F32[base / 4 + OFF_FLASH_INTENSITY] = mat.userData.flashIntensity;
            }

            // Update flags
            let flags = (entry.isBasic ? FLAG_BASIC : 0) | (entry.hasEmissive ? FLAG_EMISSIVE : 0);
            if (mat.userData?._needsFadeBack) {
                flags |= FLAG_NEEDS_FADE;
            }
            F32[base / 4 + OFF_FLAGS] = flags;
        }
    }

    /**
     * Sync WASM results back to materials
     */
    private syncFromWasm(): void {
        const instance = getWasmInstance();
        if (!instance) return;

        const F32 = new Float32Array((instance.exports.memory as any).buffer);

        for (const entry of this.materialList) {
            const resultBase = RESULT_BUFFER_OFFSET + (entry.index * RESULT_STRIDE * 4);
            const mat = entry.material as any;

            // Read results
            const r = F32[resultBase / 4];
            const g = F32[resultBase / 4 + 1];
            const b = F32[resultBase / 4 + 2];
            const emissiveIntensity = F32[resultBase / 4 + 3];

            // Apply to material
            if (mat.color) {
                mat.color.setRGB(r, g, b);
            }

            if (entry.hasEmissive && mat.emissive) {
                mat.emissive.setRGB(r, g, b);
                mat.emissiveIntensity = emissiveIntensity;
            }

            // Update flags
            const base = MATERIAL_BUFFER_OFFSET + (entry.index * MATERIAL_STRIDE * 4);
            const flags = F32[base / 4 + OFF_FLAGS];
            mat.userData = mat.userData || {};
            mat.userData._needsFadeBack = (flags & FLAG_NEEDS_FADE) !== 0;
            mat.userData.flashIntensity = F32[base / 4 + OFF_FLASH_INTENSITY];
        }
    }

    /**
     * Update using JavaScript fallback
     */
    private updateJS(): void {
        // In JS fallback mode, the existing animation.ts code handles updates
        // We just track active materials for stats
        this.activeMaterials = 0;

        for (const entry of this.materialList) {
            const mat = entry.material as any;
            if (mat.userData?.flashIntensity > 0 || mat.userData?._needsFadeBack) {
                this.activeMaterials++;
            }
        }
    }

    /**
     * Get the number of active materials (flashing or fading)
     */
    getActiveCount(): number {
        return this.activeMaterials;
    }

    /**
     * Get the total number of registered materials
     */
    getRegisteredCount(): number {
        return this.materialList.length;
    }

    /**
     * Check if using WASM acceleration
     */
    isUsingWasm(): boolean {
        return this.initialized;
    }

    /**
     * Dispose of all resources
     */
    dispose(): void {
        this.materials.clear();
        this.materialList = [];
        this.nextIndex = 0;
        this.activeMaterials = 0;
    }
}

// Global instance
export const materialBatcher = MaterialBatcher.getInstance();

