/**
 * @file presence.ts
 * @brief Opt-in multiplayer presence via Supabase Realtime (presence + broadcast).
 *
 * Room key = world seed. Publishes camera pose at ~10 Hz. No accounts — ephemeral session ids.
 * Requires VITE_SUPABASE_URL + VITE_SUPABASE_ANON_KEY. Networking stays off until join().
 */

import type { RealtimeChannel } from '@supabase/supabase-js';
import * as THREE from 'three';
import { CONFIG, FEATURE_FLAGS } from '../../core/config.ts';
import { spawnImpact } from '../../foliage/impacts.ts';
import { announce } from '../../ui/announcer.ts';
import { getWorldSeed } from '../../world/world-seed.ts';
import { getBiomeAtPosition } from './biome-at-position.ts';
import {
    BIOME_DISPLAY_NAMES,
    detectPeerBiomeEntry,
    ingestPose,
    mergePresenceMeta,
    pruneStalePeers,
} from './presence-protocol.ts';
import {
    PRESENCE_BROADCAST_EVENT,
    type PresenceMeta,
    type PresencePose,
    type RemotePeer,
} from './presence-types.ts';
import { remoteAvatars } from './remote-avatars.ts';

const PRESENCE_OPT_IN_KEY = 'candy_presence_opt_in';
const STALE_PEER_MS = 15_000;
const MAX_SNAPSHOTS = 8;

const _scratchQuat = new THREE.Quaternion();

type SupabaseClient = import('@supabase/supabase-js').SupabaseClient;

function getSupabaseConfig(): { url: string; anonKey: string } | null {
    const url = import.meta.env.VITE_SUPABASE_URL;
    const anonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
    if (typeof url !== 'string' || url.length === 0) return null;
    if (typeof anonKey !== 'string' || anonKey.length === 0) return null;
    return { url, anonKey };
}

export function isPresenceBackendConfigured(): boolean {
    return getSupabaseConfig() !== null;
}

export function isPresenceOptedIn(): boolean {
    try {
        if (new URLSearchParams(window.location.search).has('presence')) return true;
        return localStorage.getItem(PRESENCE_OPT_IN_KEY) === '1';
    } catch {
        return false;
    }
}

export function setPresenceOptIn(enabled: boolean): void {
    try {
        if (enabled) {
            localStorage.setItem(PRESENCE_OPT_IN_KEY, '1');
        } else {
            localStorage.removeItem(PRESENCE_OPT_IN_KEY);
        }
    } catch {
        /* ignore */
    }
}

const EMOJI_POOL = ['🍬', '🌸', '🦋', '⭐', '🍭', '🫧', '🌙', '✨'];

function randomEmoji(): string {
    return EMOJI_POOL[Math.floor(Math.random() * EMOJI_POOL.length)];
}

function randomLabel(): string {
    const n = Math.floor(Math.random() * 900) + 100;
    return `Explorer-${n}`;
}

export class PresenceSystem {
    private static _instance: PresenceSystem | null = null;

    private _client: SupabaseClient | null = null;
    private _channel: RealtimeChannel | null = null;
    private _sessionId = '';
    private _label = '';
    private _emoji = '';
    private _joined = false;
    private _lastPublish = 0;
    private _peers = new Map<string, RemotePeer>();
    private _localPos = new THREE.Vector3();
    private _shareDiscoveryGlow = false;
    private _hideSelf = false;
    private _mutedPeerIds = new Set<string>();
    private _peersDirty = false;

    static getInstance(): PresenceSystem {
        if (!PresenceSystem._instance) {
            PresenceSystem._instance = new PresenceSystem();
        }
        return PresenceSystem._instance;
    }

    get joined(): boolean {
        return this._joined;
    }

    get peerCount(): number {
        return this._peers.size;
    }

    get peers(): ReadonlyMap<string, RemotePeer> {
        return this._peers;
    }

    setHideSelf(hide: boolean): void {
        this._hideSelf = hide;
    }

    get hideSelf(): boolean {
        return this._hideSelf;
    }

    mutePeer(peerId: string): void {
        this._mutedPeerIds.add(peerId);
        remoteAvatars.setMutedPeers(this._mutedPeerIds);
        this._peersDirty = true;
    }

    unmutePeer(peerId: string): void {
        this._mutedPeerIds.delete(peerId);
        remoteAvatars.setMutedPeers(this._mutedPeerIds);
        this._peersDirty = true;
    }

    isPeerMuted(peerId: string): boolean {
        return this._mutedPeerIds.has(peerId);
    }

    /** Future seam: mirror save-system shareDiscoveryGlowWithPeers */
    setShareDiscoveryGlow(enabled: boolean): void {
        this._shareDiscoveryGlow = enabled;
    }

    bindScene(scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.Renderer): void {
        remoteAvatars.init(scene, camera, renderer);
    }

    async join(opts?: { label?: string; emoji?: string; seed?: number }): Promise<boolean> {
        if (!FEATURE_FLAGS.presence) {
            console.warn('[Presence] Feature flag disabled (?presence=1 to enable UI)');
            return false;
        }

        const cfg = getSupabaseConfig();
        if (!cfg) {
            console.warn(
                '[Presence] Supabase not configured (set VITE_SUPABASE_URL + VITE_SUPABASE_ANON_KEY)'
            );
            return false;
        }

        if (this._joined) return true;

        const { createClient } = await import('@supabase/supabase-js');
        this._client = createClient(cfg.url, cfg.anonKey, {
            realtime: { params: { eventsPerSecond: CONFIG.presence?.tickHz ?? 10 } },
        });

        this._sessionId = crypto.randomUUID();
        this._label = opts?.label?.trim() || randomLabel();
        this._emoji = opts?.emoji?.trim() || randomEmoji();

        const seed = opts?.seed ?? getWorldSeed();
        const room = `candy:${seed}`;

        const meta: PresenceMeta = {
            id: this._sessionId,
            label: this._label,
            emoji: this._emoji,
            shareDiscoveryGlow: this._shareDiscoveryGlow,
        };

        this._channel = this._client.channel(room, {
            config: {
                presence: { key: this._sessionId },
                broadcast: { self: false },
            },
        });

        this._channel.on('presence', { event: 'sync' }, () => {
            this._mergePresenceState();
        });
        this._channel.on('presence', { event: 'join' }, () => {
            this._mergePresenceState();
        });
        this._channel.on('presence', { event: 'leave' }, ({ key }) => {
            if (key) this._removePeer(key);
        });
        this._channel.on('broadcast', { event: PRESENCE_BROADCAST_EVENT }, ({ payload }) => {
            this._ingestPose(payload as PresencePose);
        });

        const subscribed = await new Promise<boolean>((resolve) => {
            this._channel!.subscribe(async (status) => {
                if (status === 'SUBSCRIBED') {
                    await this._channel!.track(meta);
                    this._joined = true;
                    setPresenceOptIn(true);
                    this._peersDirty = true;
                    console.log(`[Presence] Joined room ${room} as ${this._emoji} ${this._label}`);
                    resolve(true);
                } else if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT') {
                    console.error('[Presence] Channel subscription failed:', status);
                    resolve(false);
                }
            });
        });

        if (!subscribed) {
            await this.leave();
        }
        return subscribed;
    }

    async leave(): Promise<void> {
        if (this._channel) {
            try {
                await this._channel.untrack();
                await this._client?.removeChannel(this._channel);
            } catch (err) {
                console.warn('[Presence] Teardown error:', err);
            }
        }
        this._channel = null;
        this._client = null;
        this._joined = false;
        this._peers.clear();
        remoteAvatars.syncPeers(this._peers, this._localPos);
        console.log('[Presence] Left room');
    }

    update(
        _delta: number,
        camera: THREE.PerspectiveCamera,
        fallbackPosition?: THREE.Vector3
    ): void {
        if (!this._joined || !this._channel) return;

        const tickMs = 1000 / (CONFIG.presence?.tickHz ?? 10);
        const now = performance.now();

        camera.getWorldPosition(this._localPos);
        if (fallbackPosition) {
            this._localPos.y = fallbackPosition.y;
        }

        this._pruneStalePeers(now);

        if (now - this._lastPublish >= tickMs && !this._hideSelf) {
            this._lastPublish = now;
            camera.getWorldQuaternion(_scratchQuat);
            const biome = getBiomeAtPosition(this._localPos.x, this._localPos.z);
            const pose: PresencePose = {
                id: this._sessionId,
                pos: [this._localPos.x, this._localPos.y, this._localPos.z],
                quat: [_scratchQuat.x, _scratchQuat.y, _scratchQuat.z, _scratchQuat.w],
                biome,
                ts: now,
            };
            void this._channel.send({
                type: 'broadcast',
                event: PRESENCE_BROADCAST_EVENT,
                payload: pose,
            });
        }

        remoteAvatars.setMutedPeers(this._mutedPeerIds);
        remoteAvatars.syncPeers(this._peers, this._localPos);
        remoteAvatars.updateTags();

        // ⚡ OPTIMIZATION: Bypassed per-frame array allocation and UI DOM updates by dirty-flagging peer list emits
        if (this._peersDirty) {
            this._emitPeerListUpdate();
            this._peersDirty = false;
        }
    }

    private _emitPeerListUpdate(): void {
        if (typeof window === 'undefined') return;
        window.dispatchEvent(
            new CustomEvent('candy:presence-peers', {
                detail: {
                    peers: [...this._peers.values()].map((p) => ({
                        id: p.id,
                        label: p.label,
                        emoji: p.emoji,
                        muted: this._mutedPeerIds.has(p.id),
                    })),
                    peerCount: this._peers.size,
                    maxPeers: CONFIG.presence?.maxPeers ?? 16,
                },
            })
        );
    }

    private _onPeerBiomeEntry(peer: RemotePeer, biome: string): void {
        const name = BIOME_DISPLAY_NAMES[biome] ?? biome.replace(/_/g, ' ');
        announce(`An explorer entered the ${name}`, 'polite');
        if (peer.snapshots.length > 0) {
            const snap = peer.snapshots[peer.snapshots.length - 1];
            spawnImpact(
                { x: snap.pos[0], y: snap.pos[1], z: snap.pos[2] },
                'spore',
                0xffb6e8
            );
        }
    }

    dispose(): void {
        void this.leave();
        remoteAvatars.dispose();
    }

    private _mergePresenceState(): void {
        if (!this._channel) return;
        const state = this._channel.presenceState<PresenceMeta>();
        const changed = mergePresenceMeta(
            this._peers,
            state,
            this._sessionId,
            CONFIG.presence?.maxPeers ?? 16
        );
        // Fallback for simple merge that doesn't return boolean, or if it does
        this._peersDirty = true;
        this._emitPeerListUpdate();
    }

    private _ingestPose(payload: PresencePose | null | undefined): void {
        if (!ingestPose(this._peers, this._sessionId, payload)) return;
        const peer = this._peers.get(payload!.id);
        if (!peer) return;
        const entered = detectPeerBiomeEntry(peer);
        if (entered) this._onPeerBiomeEntry(peer, entered);
    }

    private _removePeer(id: string): void {
        if (this._peers.has(id)) {
            this._peers.delete(id);
            this._peersDirty = true;
        }
    }

    private _pruneStalePeers(now: number): void {
        const removed = pruneStalePeers(this._peers, now, STALE_PEER_MS);
        if (removed.length > 0) {
            this._peersDirty = true;
        }
        if (removed.length > 0) this._emitPeerListUpdate();
    }
}

export const presenceSystem = PresenceSystem.getInstance();

if (typeof window !== 'undefined') {
    window.addEventListener('beforeunload', () => {
        teardownPresence();
    });
}

export function initPresenceFromOptIn(
    scene: THREE.Scene,
    camera: THREE.PerspectiveCamera,
    renderer: THREE.Renderer
): void {
    if (!FEATURE_FLAGS.presence || !isPresenceOptedIn()) return;
    presenceSystem.bindScene(scene, camera, renderer);
    void presenceSystem.join();
}

export function updatePresenceSystem(
    delta: number,
    camera: THREE.PerspectiveCamera,
    playerPosition?: THREE.Vector3
): void {
    if (!FEATURE_FLAGS.presence || !presenceSystem.joined) return;
    presenceSystem.update(delta, camera, playerPosition);
}

export function teardownPresence(): void {
    void presenceSystem.leave();
}

/**
 * Remote peer avatars — pooled instanced candy meshes + HTML name tags.
 */

import * as THREE from 'three';
import { color, float } from 'three/tsl';
import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import { CONFIG } from '../../core/config.ts';
import { foliageGroup } from '../../world/state.ts';
import type { RemotePeer } from './presence-types.ts';

const _scratchPos = new THREE.Vector3();
const _scratchQuat = new THREE.Quaternion();
const _scratchScale = new THREE.Vector3(1, 1, 1);
const _scratchMat = new THREE.Matrix4();
const _scratchHide = new THREE.Matrix4();
const _interpPos = new THREE.Vector3();
const _interpQuat = new THREE.Quaternion();

const CANDY_COLORS = [0xff69b4, 0x87cefa, 0x98fb98, 0xffd1dc, 0xe6e6fa, 0xffb347];

function hashToColor(id: string): number {
    let h = 0;
    for (let i = 0; i < id.length; i++) {
        h = (Math.imul(31, h) + id.charCodeAt(i)) | 0;
    }
    return CANDY_COLORS[Math.abs(h) % CANDY_COLORS.length];
}

interface TagSlot {
    el: HTMLDivElement;
    peerId: string | null;
    visible: boolean;
}

export class RemoteAvatars {
    private static _instance: RemoteAvatars | null = null;

    private _mesh: THREE.InstancedMesh | null = null;
    private _peerOrder: string[] = [];
    private _peerToSlot = new Map<string, number>();
    private _slotPeer: (string | null)[] = [];
    private _tags: TagSlot[] = [];
    private _tagRoot: HTMLDivElement | null = null;
    private _camera: THREE.PerspectiveCamera | null = null;
    private _renderer: THREE.Renderer | null = null;
    private _initialized = false;
    private _interpDelayMs = 100;
    private _mutedPeerIds: Set<string> = new Set();

    static getInstance(): RemoteAvatars {
        if (!RemoteAvatars._instance) {
            RemoteAvatars._instance = new RemoteAvatars();
        }
        return RemoteAvatars._instance;
    }

    init(_scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.Renderer): void {
        if (this._initialized) return;

        const maxPeers = CONFIG.presence?.maxPeers ?? 16;
        const geo = new THREE.DodecahedronGeometry(0.35, 0);
        geo.translate(0, 0.35, 0);

        const mat = new MeshPhysicalNodeMaterial({
            roughness: 0.25,
            metalness: 0,
            clearcoat: 0.85,
            clearcoatRoughness: 0.15,
        });

        // Base color is white, will be multiplied by instanceColor
        mat.colorNode = color(0xffffff);

        this._mesh = new THREE.InstancedMesh(geo, mat, maxPeers);
        this._mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
        this._mesh.instanceColor = new THREE.InstancedBufferAttribute(
            new Float32Array(maxPeers * 3),
            3
        );
        this._mesh.instanceColor.setUsage(THREE.DynamicDrawUsage);
        this._mesh.frustumCulled = false;
        this._mesh.count = 0;
        this._mesh.name = 'remote-presence-avatars';

        foliageGroup.add(this._mesh);

        _scratchHide.makeScale(0, 0, 0);
        this._slotPeer = new Array(maxPeers).fill(null);
        for (let i = 0; i < maxPeers; i++) {
            // ⚡ OPTIMIZATION: Write directly to instanceMatrix.array instead of updateMatrix + setMatrixAt
            _scratchHide.toArray(this._mesh.instanceMatrix.array, i * 16);
            // Initialize colors to white (or anything, they will be overwritten when slot is allocated)
            this._mesh.instanceColor.array[i * 3 + 0] = 1;
            this._mesh.instanceColor.array[i * 3 + 1] = 1;
            this._mesh.instanceColor.array[i * 3 + 2] = 1;
        }
        this._mesh.instanceMatrix.needsUpdate = true;
        this._mesh.instanceColor.needsUpdate = true;

        this._tagRoot = document.createElement('div');
        this._tagRoot.id = 'presence-tags';
        this._tagRoot.style.cssText =
            'position:fixed;inset:0;pointer-events:none;z-index:150;overflow:hidden;';
        document.body.appendChild(this._tagRoot);

        for (let i = 0; i < maxPeers; i++) {
            const el = document.createElement('div');
            el.className = 'presence-tag';
            el.style.cssText =
                'position:absolute;transform:translate(-50%,-100%);white-space:nowrap;' +
                'font-size:12px;font-weight:600;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,0.5);' +
                'padding:2px 6px;border-radius:8px;background:rgba(255,105,180,0.55);display:none;';
            this._tagRoot.appendChild(el);
            this._tags.push({ el, peerId: null, visible: false });
        }

        this._camera = camera;
        this._renderer = renderer;
        this._initialized = true;
    }

    setMutedPeers(muted: ReadonlySet<string>): void {
        this._mutedPeerIds = new Set(muted);
    }

    dispose(): void {
        if (this._mesh) {
            foliageGroup.remove(this._mesh);
            this._mesh.geometry.dispose();
            (this._mesh.material as THREE.Material).dispose();
            this._mesh = null;
        }
        if (this._tagRoot?.parentNode) {
            this._tagRoot.parentNode.removeChild(this._tagRoot);
        }
        this._tagRoot = null;
        this._tags = [];
        this._peerOrder = [];
        this._peerToSlot.clear();
        this._initialized = false;
    }

    private _allocateSlot(peerId: string): number | null {
        const maxPeers = CONFIG.presence?.maxPeers ?? 16;
        const existing = this._peerToSlot.get(peerId);
        if (existing !== undefined) return existing;

        for (let i = 0; i < maxPeers; i++) {
            if (this._slotPeer[i] === null) {
                this._slotPeer[i] = peerId;
                this._peerToSlot.set(peerId, i);
                if (!this._peerOrder.includes(peerId)) {
                    this._peerOrder.push(peerId);
                }
                return i;
            }
        }
        return null;
    }

    private _freeSlot(peerId: string): void {
        const slot = this._peerToSlot.get(peerId);
        if (slot === undefined || !this._mesh) return;
        this._slotPeer[slot] = null;
        this._peerToSlot.delete(peerId);
        const idx = this._peerOrder.indexOf(peerId);
        if (idx >= 0) this._peerOrder.splice(idx, 1);
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix.array instead of updateMatrix + setMatrixAt
        _scratchHide.toArray(this._mesh.instanceMatrix.array, slot * 16);
        const tag = this._tags[slot];
        if (tag) {
            tag.peerId = null;
            tag.visible = false;
            tag.el.style.display = 'none';
        }
    }

    private _samplePose(
        peer: RemotePeer,
        now: number,
        outPos: THREE.Vector3,
        outQuat: THREE.Quaternion
    ): boolean {
        const snaps = peer.snapshots;
        if (snaps.length === 0) return false;

        const renderTime = now - this._interpDelayMs;
        if (snaps.length === 1 || renderTime <= snaps[0].ts) {
            const s = snaps[snaps.length - 1];
            outPos.set(s.pos[0], s.pos[1], s.pos[2]);
            outQuat.set(s.quat[0], s.quat[1], s.quat[2], s.quat[3]);
            return true;
        }

        let a = snaps[0];
        let b = snaps[snaps.length - 1];
        for (let i = 0; i < snaps.length - 1; i++) {
            if (snaps[i].ts <= renderTime && snaps[i + 1].ts >= renderTime) {
                a = snaps[i];
                b = snaps[i + 1];
                break;
            }
        }

        const span = Math.max(1, b.ts - a.ts);
        const t = THREE.MathUtils.clamp((renderTime - a.ts) / span, 0, 1);
        outPos.set(
            THREE.MathUtils.lerp(a.pos[0], b.pos[0], t),
            THREE.MathUtils.lerp(a.pos[1], b.pos[1], t),
            THREE.MathUtils.lerp(a.pos[2], b.pos[2], t)
        );
        outQuat.set(a.quat[0], a.quat[1], a.quat[2], a.quat[3]);
        _scratchQuat.set(b.quat[0], b.quat[1], b.quat[2], b.quat[3]);
        outQuat.slerp(_scratchQuat, t);
        return true;
    }

    syncPeers(peers: Map<string, RemotePeer>, localPlayerPos: THREE.Vector3): void {
        if (!this._initialized || !this._mesh || !this._camera) return;

        const cullDist = CONFIG.presence?.cullDistance ?? 120;
        const cullDistSq = cullDist * cullDist;
        const now = performance.now();
        let visibleCount = 0;

        // ⚡ OPTIMIZATION: Bypassed Array/Set allocation in hot presence update loop using reverse indexing.
        for (let i = this._peerOrder.length - 1; i >= 0; i--) {
            const peerId = this._peerOrder[i];
            if (!peers.has(peerId)) this._freeSlot(peerId);
        }

        for (const [peerId, peer] of peers) {
            if (this._mutedPeerIds.has(peerId)) {
                this._freeSlot(peerId);
                continue;
            }
            const slot = this._allocateSlot(peerId);
            if (slot === null) continue;

            if (!this._samplePose(peer, now, _interpPos, _interpQuat)) continue;

            const dx = _interpPos.x - localPlayerPos.x;
            const dz = _interpPos.z - localPlayerPos.z;
            const distSq = dx * dx + dz * dz;
            const inRange = distSq <= cullDistSq && !this._mutedPeerIds.has(peerId);

            if (inRange) {
                _scratchScale.set(1, 1, 1);
                _scratchMat.compose(_interpPos, _interpQuat, _scratchScale);
                // ⚡ OPTIMIZATION: Write directly to instanceMatrix.array instead of updateMatrix + setMatrixAt
                _scratchMat.toArray(this._mesh.instanceMatrix.array, slot * 16);
                visibleCount++;

                const tint = hashToColor(peerId);

                // Write directly to instanceColor array to avoid allocation/overhead
                const r = ((tint >> 16) & 255) / 255.0;
                const g = ((tint >> 8) & 255) / 255.0;
                const b = (tint & 255) / 255.0;
                this._mesh.instanceColor!.array[slot * 3 + 0] = r;
                this._mesh.instanceColor!.array[slot * 3 + 1] = g;
                this._mesh.instanceColor!.array[slot * 3 + 2] = b;

                const tag = this._tags[slot];
                if (tag) {
                    tag.peerId = peerId;
                    tag.visible = true;
                    tag.el.textContent = `${peer.emoji} ${peer.label}`;
                    tag.el.style.display = 'block';
                    tag.el.style.background = `rgba(${(tint >> 16) & 255}, ${(tint >> 8) & 255}, ${tint & 255}, 0.55)`;
                }
            } else {
                // ⚡ OPTIMIZATION: Write directly to instanceMatrix.array instead of updateMatrix + setMatrixAt
                _scratchHide.toArray(this._mesh.instanceMatrix.array, slot * 16);
                const tag = this._tags[slot];
                if (tag) {
                    tag.visible = false;
                    tag.el.style.display = 'none';
                }
            }
        }

        this._mesh.count = Math.max(visibleCount, this._peerToSlot.size);
        this._mesh.instanceMatrix.needsUpdate = true;
        this._mesh.instanceColor!.needsUpdate = true;
    }

    updateTags(): void {
        if (!this._camera || !this._renderer || !this._mesh) return;

        const canvas = this._renderer.domElement;
        const w = canvas.clientWidth;
        const h = canvas.clientHeight;
        if (w === 0 || h === 0) return;

        for (let slot = 0; slot < this._tags.length; slot++) {
            const tag = this._tags[slot];
            if (!tag.visible || !tag.peerId) continue;

            this._mesh.getMatrixAt(slot, _scratchMat);
            _scratchMat.decompose(_scratchPos, _scratchQuat, _scratchScale);
            _scratchPos.y += 0.9;
            _scratchPos.project(this._camera);

            if (_scratchPos.z > 1) {
                tag.el.style.display = 'none';
                continue;
            }

            const sx = (_scratchPos.x * 0.5 + 0.5) * w;
            const sy = (-_scratchPos.y * 0.5 + 0.5) * h;
            tag.el.style.display = 'block';
            tag.el.style.left = `${sx}px`;
            tag.el.style.top = `${sy}px`;
        }
    }
}

export const remoteAvatars = RemoteAvatars.getInstance();

/**
 * @file performance-budget-core.ts
 * @brief Runtime Performance Budget System Core for Candy World
 * 
 * Enforces limits on frame time, memory usage, and instance count to prevent
 * silent performance degradation. Provides adaptive quality reduction.
 * 
 * @example
 * ```ts
 * import { PerformanceBudget, PERFORMANCE_BUDGETS } from './systems/performance-budget';
 * 
 * // Auto-detect budget based on hardware
 * const budget = new PerformanceBudget();
 * budget.autoDetectBudget();
 * 
 * // Or use a preset
 * const budget = new PerformanceBudget(PERFORMANCE_BUDGETS.desktop);
 * 
 * // In render loop
 * budget.beginFrame();
 * // ... render ...
 * budget.endFrame();
 * 
 * // Check budgets
 * if (budget.isOverBudget('frameTime')) {
 *   budget.applyAdaptiveReduction();
 * }
 * ```
 */

import {
  BudgetMode,
  BudgetType,
  BudgetConfig,
  InstanceBudget,
  PerformanceBudgetConfig,
  PerformanceMetrics,
  BudgetViolation,
  AdaptiveSettings,
  PERFORMANCE_BUDGETS
} from './performance-budget-types.ts';

// Re-export types for convenience
export {
  BudgetMode,
  BudgetType,
  BudgetConfig,
  InstanceBudget,
  PerformanceBudgetConfig,
  PerformanceMetrics,
  BudgetViolation,
  AdaptiveSettings,
  PERFORMANCE_BUDGETS
};

/**
 * Runtime performance budget system that tracks and enforces performance limits.
 * 
 * Features:
 * - Track frame time, memory, instances, draw calls, and shader compilations
 * - Configurable enforcement modes (OFF, WARN, STRICT, ADAPTIVE)
 * - Automatic quality reduction when budgets are exceeded
 * - Hardware-based budget auto-detection
 */
export class PerformanceBudget {
  // Configuration
  private config: PerformanceBudgetConfig;
  private budgets: Map<BudgetType, BudgetConfig> = new Map();
  private instanceBudgets: Map<string, InstanceBudget> = new Map();

  // Runtime state
  private frameStartTime = 0;
  private currentMetrics: PerformanceMetrics = {
    frameTime: 0,
    memory: 0,
    instances: 0,
    drawCalls: 0,
    shaderCompilations: 0,
    timestamp: 0
  };

  // Tracking history for adaptive mode
  private frameTimeHistory: number[] = [];
  private readonly historyLength = 60; // 1 second at 60fps
  private consecutiveOverBudgetFrames: Map<BudgetType, number> = new Map();

  // Violation tracking
  private violations: BudgetViolation[] = [];
  private maxViolations = 100;

  // Adaptive settings
  private adaptiveSettings: AdaptiveSettings = {
    lodDistanceMultiplier: 1.0,
    shadowDistanceMultiplier: 1.0,
    particleDensityMultiplier: 1.0,
    aggressiveBatching: false,
    meshMerging: false,
    unloadDistantFoliage: false
  };

  // Draw call tracking
  private drawCallCount = 0;
  private shaderCompilationCount = 0;

  // Event callbacks
  private onViolationCallbacks: ((violation: BudgetViolation) => void)[] = [];
  private onAdaptiveChangeCallbacks: ((settings: AdaptiveSettings) => void)[] = [];

  constructor(config?: Partial<PerformanceBudgetConfig>) {
    this.config = {
      frameTime: 16.67,
      memory: 512,
      instances: 2000,
      drawCalls: 500,
      shaderCompilations: 200,
      defaultMode: BudgetMode.WARN,
      ...config
    };

    this.initializeBudgets();
  }

  // ============================================================================
  // Initialization
  // ============================================================================

  private initializeBudgets(): void {
    const defaultMode = this.config.defaultMode ?? BudgetMode.WARN;

    // Initialize standard budgets
    this.budgets.set('frameTime', {
      limit: this.config.frameTime,
      mode: defaultMode,
      graceFrames: 3,
      adaptiveThreshold: 0.9
    });

    this.budgets.set('memory', {
      limit: this.config.memory,
      mode: defaultMode,
      graceFrames: 10,
      adaptiveThreshold: 0.85
    });

    this.budgets.set('instances', {
      limit: this.config.instances,
      mode: defaultMode,
      graceFrames: 5,
      adaptiveThreshold: 0.95
    });

    this.budgets.set('drawCalls', {
      limit: this.config.drawCalls,
      mode: defaultMode,
      graceFrames: 2,
      adaptiveThreshold: 0.95
    });

    this.budgets.set('shaderCompilations', {
      limit: this.config.shaderCompilations,
      mode: BudgetMode.WARN, // Shader compilations are one-time, less critical
      graceFrames: 0,
      adaptiveThreshold: 1.0
    });

    // Initialize per-type instance budgets if provided
    if (this.config.instanceBudgets) {
      for (const [type, limit] of Object.entries(this.config.instanceBudgets)) {
        this.instanceBudgets.set(type, {
          maxCount: limit,
          currentCount: 0,
          mode: defaultMode
        });
      }
    }
  }

  // ============================================================================
  // Auto-Detection
  // ============================================================================

  /**
   * Automatically detect and set appropriate budget based on hardware capabilities.
   * Uses navigator.hardwareConcurrency, navigator.deviceMemory, and WebGPU adapter info.
   * 
   * @returns The detected tier ('mobile' | 'desktop' | 'highEnd')
   */
  async autoDetectBudget(): Promise<'mobile' | 'desktop' | 'highEnd'> {
    let score = 0;

    // Check CPU cores (hardwareConcurrency)
    const cores = navigator.hardwareConcurrency || 4;
    if (cores <= 4) score -= 2;
    else if (cores <= 8) score += 0;
    else score += 2;

    // Check device memory (if available)
    const deviceMemory = (navigator as any).deviceMemory;
    if (deviceMemory) {
      if (deviceMemory <= 4) score -= 2;
      else if (deviceMemory <= 8) score += 0;
      else score += 2;
    }

    // Check WebGPU capabilities
    try {
      if ('gpu' in navigator) {
        const adapter = await (navigator as any).gpu.requestAdapter();
        if (adapter) {
          const info = await adapter.requestAdapterInfo();

          // Check for discrete GPU
          const isDiscrete = info.architecture === 'discrete' || 
                            info.description?.toLowerCase().includes('nvidia') ||
                            info.description?.toLowerCase().includes('amd') ||
                            info.description?.toLowerCase().includes('radeon') ||
                            info.description?.toLowerCase().includes('geforce');

          if (isDiscrete) score += 3;
          else score += 1;

          // Check device type
          if (info.deviceType === 'integrated') score -= 1;
          else if (info.deviceType === 'discrete') score += 1;
        }
      }
    } catch (e) {
      // WebGPU not available, rely on other metrics
    }

    // Check for mobile user agent
    const isMobile = /Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);
    if (isMobile) score -= 2;

    // Determine tier based on score
    let tier: 'mobile' | 'desktop' | 'highEnd';
    if (score <= -2) {
      tier = 'mobile';
    } else if (score >= 3) {
      tier = 'highEnd';
    } else {
      tier = 'desktop';
    }

    // Apply the detected budget
    this.setBudget(PERFORMANCE_BUDGETS[tier]);

    console.log(`[PerformanceBudget] Auto-detected tier: ${tier} (score: ${score})`);

    return tier;
  }

  /**
   * Set a new budget configuration
   */
  setBudget(config: PerformanceBudgetConfig): void {
    this.config = config;
    this.initializeBudgets();
    this.resetMetrics();
  }

  // ============================================================================
  // Frame Tracking
  // ============================================================================

  /**
   * Call at the beginning of each frame to start timing
   */
  beginFrame(): void {
    this.frameStartTime = performance.now();
    this.drawCallCount = 0;
  }

  /**
   * Call at the end of each frame to complete timing and check budgets
   */
  endFrame(): void {
    const frameEndTime = performance.now();
    const frameTime = frameEndTime - this.frameStartTime;

    // Update metrics
    this.currentMetrics.frameTime = frameTime;
    this.currentMetrics.timestamp = frameEndTime;
    this.currentMetrics.drawCalls = this.drawCallCount;

    // Update memory estimate
    this.updateMemoryEstimate();

    // Update history
    this.frameTimeHistory.push(frameTime);
    if (this.frameTimeHistory.length > this.historyLength) {
      this.frameTimeHistory.shift();
    }

    // Check all budgets
    this.checkBudgets();
  }

  /**
   * Get the current frame time in milliseconds
   */
  getFrameTime(): number {
    return this.currentMetrics.frameTime;
  }

  /**
   * Get average frame time over the last N frames
   */
  getAverageFrameTime(frames = 60): number {
    const recent = this.frameTimeHistory.slice(-frames);
    if (recent.length === 0) return 0;
    return recent.reduce((a, b) => a + b, 0) / recent.length;
  }

  /**
   * Get current FPS
   */
  getFPS(): number {
    const avgFrameTime = this.getAverageFrameTime();
    if (avgFrameTime === 0) return 0;
    return 1000 / avgFrameTime;
  }

  // ============================================================================
  // Memory Tracking
  // ============================================================================

  private updateMemoryEstimate(): void {
    // Try to get actual memory usage if available (Chrome only)
    const memory = (performance as any).memory;
    if (memory) {
      // Convert to MB
      this.currentMetrics.memory = memory.usedJSHeapSize / (1024 * 1024);
    } else {
      // Estimate based on tracked instances
      this.currentMetrics.memory = this.estimateMemoryUsage();
    }
  }

  private estimateMemoryUsage(): number {
    // Rough estimation: ~1KB per instance + base overhead
    const instanceMemory = this.currentMetrics.instances * 1;
    const baseOverhead = 50; // Base JS heap overhead in MB
    return baseOverhead + instanceMemory;
  }

  /**
   * Get current memory usage in MB
   */
  getMemoryUsage(): number {
    return this.currentMetrics.memory;
  }

  // ============================================================================
  // Instance Tracking
  // ============================================================================

  /**
   * Register instances of a specific type
   * @param type The foliage/instance type
   * @param count Number of instances
   * @returns Whether the registration was within budget
   */
  registerInstances(type: string, count: number): boolean {
    // Update total instances
    this.currentMetrics.instances += count;

    // Update per-type budget if tracked
    const budget = this.instanceBudgets.get(type);
    if (budget) {
      budget.currentCount += count;

      // Check if over budget
      if (budget.currentCount > budget.maxCount) {
        this.handleViolation('instances', budget.maxCount, budget.currentCount);

        if (budget.mode === BudgetMode.STRICT) {
          return false;
        }
      }
    }

    // Check total instance budget
    const totalBudget = this.budgets.get('instances');
    if (totalBudget && this.currentMetrics.instances > totalBudget.limit) {
      this.handleViolation('instances', totalBudget.limit, this.currentMetrics.instances);

      if (totalBudget.mode === BudgetMode.STRICT) {
        return false;
      }
    }

    return true;
  }

  /**
   * Unregister instances of a specific type
   */
  unregisterInstances(type: string, count: number): void {
    this.currentMetrics.instances = Math.max(0, this.currentMetrics.instances - count);

    const budget = this.instanceBudgets.get(type);
    if (budget) {
      budget.currentCount = Math.max(0, budget.currentCount - count);
    }
  }

  /**
   * Get current instance count
   */
  getInstanceCount(): number {
    return this.currentMetrics.instances;
  }

  /**
   * Get instance count for a specific type
   */
  getInstanceCountByType(type: string): number {
    return this.instanceBudgets.get(type)?.currentCount ?? 0;
  }

  // ============================================================================
  // Draw Call Tracking
  // ============================================================================

  /**
   * Increment the draw call counter
   */
  incrementDrawCalls(count = 1): void {
    this.drawCallCount += count;
  }

  /**
   * Get current draw call count for this frame
   */
  getDrawCallCount(): number {
    return this.drawCallCount;
  }

  // ============================================================================
  // Shader Compilation Tracking
  // ============================================================================

  /**
   * Track a shader compilation
   */
  trackShaderCompilation(): void {
    this.shaderCompilationCount++;
    this.currentMetrics.shaderCompilations = this.shaderCompilationCount;

    const budget = this.budgets.get('shaderCompilations');
    if (budget && this.shaderCompilationCount > budget.limit) {
      this.handleViolation('shaderCompilations', budget.limit, this.shaderCompilationCount);
    }
  }

  /**
   * Get total shader compilations this session
   */
  getShaderCompilationCount(): number {
    return this.shaderCompilationCount;
  }

  // ============================================================================
  // Budget Checking
  // ============================================================================

  private checkBudgets(): void {
    // Check frame time
    const frameTimeBudget = this.budgets.get('frameTime');
    if (frameTimeBudget) {
      const avgFrameTime = this.getAverageFrameTime(10); // Check over 10 frames
      if (avgFrameTime > frameTimeBudget.limit) {
        this.handleViolation('frameTime', frameTimeBudget.limit, avgFrameTime);
      }
    }

    // Check memory
    const memoryBudget = this.budgets.get('memory');
    if (memoryBudget && this.currentMetrics.memory > memoryBudget.limit) {
      this.handleViolation('memory', memoryBudget.limit, this.currentMetrics.memory);
    }

    // Check instances
    const instanceBudget = this.budgets.get('instances');
    if (instanceBudget && this.currentMetrics.instances > instanceBudget.limit) {
      this.handleViolation('instances', instanceBudget.limit, this.currentMetrics.instances);
    }

    // Check draw calls
    const drawCallBudget = this.budgets.get('drawCalls');
    if (drawCallBudget && this.drawCallCount > drawCallBudget.limit) {
      this.handleViolation('drawCalls', drawCallBudget.limit, this.drawCallCount);
    }
  }

  private handleViolation(type: BudgetType, budget: number, actual: number): void {
    const overBy = actual - budget;
    const overByPercent = (overBy / budget) * 100;

    // Determine severity
    let severity: 'low' | 'medium' | 'high' | 'critical';
    if (overByPercent < 10) severity = 'low';
    else if (overByPercent < 25) severity = 'medium';
    else if (overByPercent < 50) severity = 'high';
    else severity = 'critical';

    // Track consecutive frames
    const consecutive = (this.consecutiveOverBudgetFrames.get(type) || 0) + 1;
    this.consecutiveOverBudgetFrames.set(type, consecutive);

    const budgetConfig = this.budgets.get(type);
    if (!budgetConfig) return;

    // Check grace period
    if (consecutive < budgetConfig.graceFrames) {
      return; // Still in grace period
    }

    // Create violation record
    const violation: BudgetViolation = {
      type,
      budget,
      actual,
      overBy,
      overByPercent,
      timestamp: performance.now(),
      severity
    };

    this.violations.push(violation);
    if (this.violations.length > this.maxViolations) {
      this.violations.shift();
    }

    // Handle based on mode
    switch (budgetConfig.mode) {
      case BudgetMode.OFF:
        break;

      case BudgetMode.WARN:
        console.warn(
          `[PerformanceBudget] ${type} exceeded: ${actual.toFixed(2)} / ${budget.toFixed(2)} ` +
          `(+${overByPercent.toFixed(1)}%) - ${severity}`
        );
        break;

      case BudgetMode.STRICT:
        console.error(
          `[PerformanceBudget] STRICT: ${type} exceeded: ${actual.toFixed(2)} / ${budget.toFixed(2)} ` +
          `(+${overByPercent.toFixed(1)}%)`
        );
        break;

      case BudgetMode.ADAPTIVE:
        this.applyAdaptiveReduction(type);
        break;
    }

    // Notify listeners
    for (let i = 0; i < this.onViolationCallbacks.length; i++) { const cb = this.onViolationCallbacks[i];
      try {
        cb(violation);
      } catch (e) {
        console.error('[PerformanceBudget] Error in violation callback:', e);
      }
    }
  }

  /**
   * Check if a specific budget type is currently over budget
   */
  isOverBudget(type: BudgetType): boolean {
    const budget = this.budgets.get(type);
    if (!budget) return false;

    switch (type) {
      case 'frameTime':
        return this.getAverageFrameTime(5) > budget.limit;
      case 'memory':
        return this.currentMetrics.memory > budget.limit;
      case 'instances':
        return this.currentMetrics.instances > budget.limit;
      case 'drawCalls':
        return this.drawCallCount > budget.limit;
      case 'shaderCompilations':
        return this.shaderCompilationCount > budget.limit;
      default:
        return false;
    }
  }

  /**
   * Get remaining budget for a type (negative if over)
   */
  getRemainingBudget(type: BudgetType): number {
    const budget = this.budgets.get(type);
    if (!budget) return 0;

    switch (type) {
      case 'frameTime':
        return budget.limit - this.currentMetrics.frameTime;
      case 'memory':
        return budget.limit - this.currentMetrics.memory;
      case 'instances':
        return budget.limit - this.currentMetrics.instances;
      case 'drawCalls':
        return budget.limit - this.drawCallCount;
      case 'shaderCompilations':
        return budget.limit - this.shaderCompilationCount;
      default:
        return 0;
    }
  }

  /**
   * Get budget utilization as a percentage (0-100+)
   */
  getBudgetUtilization(type: BudgetType): number {
    const budget = this.budgets.get(type);
    if (!budget || budget.limit === 0) return 0;

    switch (type) {
      case 'frameTime':
        return (this.currentMetrics.frameTime / budget.limit) * 100;
      case 'memory':
        return (this.currentMetrics.memory / budget.limit) * 100;
      case 'instances':
        return (this.currentMetrics.instances / budget.limit) * 100;
      case 'drawCalls':
        return (this.drawCallCount / budget.limit) * 100;
      case 'shaderCompilations':
        return (this.shaderCompilationCount / budget.limit) * 100;
      default:
        return 0;
    }
  }

  // ============================================================================
  // Adaptive Quality Reduction
  // ============================================================================

  /**
   * Apply adaptive quality reduction based on the budget type that's over
   */
  applyAdaptiveReduction(type?: BudgetType): void {
    const specificType = type || this.findMostOverBudget();
    if (!specificType) return;

    const budget = this.budgets.get(specificType);
    if (!budget) return;

    const utilization = this.getBudgetUtilization(specificType);
    if (utilization < budget.adaptiveThreshold * 100) return;

    let changed = false;

    switch (specificType) {
      case 'frameTime':
        changed = this.reduceForFrameTime();
        break;
      case 'memory':
        changed = this.reduceForMemory();
        break;
      case 'instances':
        changed = this.reduceForInstances();
        break;
      case 'drawCalls':
        changed = this.reduceForDrawCalls();
        break;
    }

    if (changed) {
      console.log(`[PerformanceBudget] Applied adaptive reduction for ${specificType}:`, this.adaptiveSettings);

      for (let i = 0; i < this.onAdaptiveChangeCallbacks.length; i++) { const cb = this.onAdaptiveChangeCallbacks[i];
        try {
          cb(this.adaptiveSettings);
        } catch (e) {
          console.error('[PerformanceBudget] Error in adaptive callback:', e);
        }
      }

      // Reset consecutive counter after applying reduction
      this.consecutiveOverBudgetFrames.set(specificType, 0);
    }
  }

  private findMostOverBudget(): BudgetType | null {
    let maxUtilization = 0;
    let worstType: BudgetType | null = null;

    for (const type of this.budgets.keys()) {
      const utilization = this.getBudgetUtilization(type);
      if (utilization > maxUtilization) {
        maxUtilization = utilization;
        worstType = type;
      }
    }

    return worstType;
  }

  private reduceForFrameTime(): boolean {
    let changed = false;

    // Reduce LOD distance
    if (this.adaptiveSettings.lodDistanceMultiplier > 0.5) {
      this.adaptiveSettings.lodDistanceMultiplier *= 0.9;
      changed = true;
    }

    // Reduce shadow distance
    if (this.adaptiveSettings.shadowDistanceMultiplier > 0.5) {
      this.adaptiveSettings.shadowDistanceMultiplier *= 0.9;
      changed = true;
    }

    // Reduce particle density
    if (this.adaptiveSettings.particleDensityMultiplier > 0.3) {
      this.adaptiveSettings.particleDensityMultiplier *= 0.9;
      changed = true;
    }

    // Enable aggressive batching if not already
    if (!this.adaptiveSettings.aggressiveBatching) {
      this.adaptiveSettings.aggressiveBatching = true;
      changed = true;
    }

    return changed;
  }

  private reduceForMemory(): boolean {
    let changed = false;

    // Enable distant foliage unloading
    if (!this.adaptiveSettings.unloadDistantFoliage) {
      this.adaptiveSettings.unloadDistantFoliage = true;
      changed = true;
    }

    // Reduce LOD distance to unload more
    if (this.adaptiveSettings.lodDistanceMultiplier > 0.5) {
      this.adaptiveSettings.lodDistanceMultiplier *= 0.85;
      changed = true;
    }

    return changed;
  }

  private reduceForInstances(): boolean {
    let changed = false;

    // Enable aggressive batching
    if (!this.adaptiveSettings.aggressiveBatching) {
      this.adaptiveSettings.aggressiveBatching = true;
      changed = true;
    }

    // Reduce LOD distance
    if (this.adaptiveSettings.lodDistanceMultiplier > 0.5) {
      this.adaptiveSettings.lodDistanceMultiplier *= 0.9;
      changed = true;
    }

    // Enable distant foliage unloading
    if (!this.adaptiveSettings.unloadDistantFoliage) {
      this.adaptiveSettings.unloadDistantFoliage = true;
      changed = true;
    }

    return changed;
  }

  private reduceForDrawCalls(): boolean {
    let changed = false;

    // Enable mesh merging
    if (!this.adaptiveSettings.meshMerging) {
      this.adaptiveSettings.meshMerging = true;
      changed = true;
    }

    // Enable aggressive batching
    if (!this.adaptiveSettings.aggressiveBatching) {
      this.adaptiveSettings.aggressiveBatching = true;
      changed = true;
    }

    // Reduce LOD distance
    if (this.adaptiveSettings.lodDistanceMultiplier > 0.5) {
      this.adaptiveSettings.lodDistanceMultiplier *= 0.9;
      changed = true;
    }

    return changed;
  }

  /**
   * Get current adaptive quality settings
   */
  getAdaptiveSettings(): AdaptiveSettings {
    return { ...this.adaptiveSettings };
  }

  /**
   * Reset adaptive settings to default
   */
  resetAdaptiveSettings(): void {
    this.adaptiveSettings = {
      lodDistanceMultiplier: 1.0,
      shadowDistanceMultiplier: 1.0,
      particleDensityMultiplier: 1.0,
      aggressiveBatching: false,
      meshMerging: false,
      unloadDistantFoliage: false
    };

    for (let i = 0; i < this.onAdaptiveChangeCallbacks.length; i++) { const cb = this.onAdaptiveChangeCallbacks[i];
      try {
        cb(this.adaptiveSettings);
      } catch (e) {
        console.error('[PerformanceBudget] Error in adaptive callback:', e);
      }
    }
  }

  // ============================================================================
  // Event Listeners
  // ============================================================================

  /**
   * Register a callback for budget violations
   */
  onViolation(callback: (violation: BudgetViolation) => void): void {
    this.onViolationCallbacks.push(callback);
  }

  /**
   * Remove a violation callback
   */
  offViolation(callback: (violation: BudgetViolation) => void): void {
    const index = this.onViolationCallbacks.indexOf(callback);
    if (index > -1) {
      this.onViolationCallbacks.splice(index, 1);
    }
  }

  /**
   * Register a callback for adaptive settings changes
   */
  onAdaptiveChange(callback: (settings: AdaptiveSettings) => void): void {
    this.onAdaptiveChangeCallbacks.push(callback);
  }

  /**
   * Remove an adaptive change callback
   */
  offAdaptiveChange(callback: (settings: AdaptiveSettings) => void): void {
    const index = this.onAdaptiveChangeCallbacks.indexOf(callback);
    if (index > -1) {
      this.onAdaptiveChangeCallbacks.splice(index, 1);
    }
  }

  // ============================================================================
  // Utility Methods
  // ============================================================================

  /**
   * Get all recent violations
   */
  getViolations(): BudgetViolation[] {
    return [...this.violations];
  }

  /**
   * Clear violation history
   */
  clearViolations(): void {
    this.violations = [];
  }

  /**
   * Get current performance metrics
   */
  getMetrics(): PerformanceMetrics {
    return { ...this.currentMetrics };
  }

  /**
   * Reset all metrics and counters
   */
  resetMetrics(): void {
    this.currentMetrics = {
      frameTime: 0,
      memory: 0,
      instances: 0,
      drawCalls: 0,
      shaderCompilations: 0,
      timestamp: 0
    };
    this.frameTimeHistory = [];
    this.consecutiveOverBudgetFrames.clear();
    this.violations = [];
    this.shaderCompilationCount = 0;
    this.drawCallCount = 0;
  }

  /**
   * Get full status report
   */
  getStatus(): {
    config: PerformanceBudgetConfig;
    metrics: PerformanceMetrics;
    adaptiveSettings: AdaptiveSettings;
    violations: number;
    isOverBudget: Record<BudgetType, boolean>;
    utilization: Record<BudgetType, number>;
  } {
    const isOverBudget: Record<BudgetType, boolean> = {
      frameTime: this.isOverBudget('frameTime'),
      memory: this.isOverBudget('memory'),
      instances: this.isOverBudget('instances'),
      drawCalls: this.isOverBudget('drawCalls'),
      shaderCompilations: this.isOverBudget('shaderCompilations')
    };

    const utilization: Record<BudgetType, number> = {
      frameTime: this.getBudgetUtilization('frameTime'),
      memory: this.getBudgetUtilization('memory'),
      instances: this.getBudgetUtilization('instances'),
      drawCalls: this.getBudgetUtilization('drawCalls'),
      shaderCompilations: this.getBudgetUtilization('shaderCompilations')
    };

    return {
      config: this.config,
      metrics: this.getMetrics(),
      adaptiveSettings: this.getAdaptiveSettings(),
      violations: this.violations.length,
      isOverBudget,
      utilization
    };
  }

  /**
   * Dispose of all resources
   */
  dispose(): void {
    this.onViolationCallbacks = [];
    this.onAdaptiveChangeCallbacks = [];
  }
}

