/**
 * Main physics update loop.
 * Orchestrates state transitions, ability handling, and collision checks.
 * @param delta - Time delta in seconds
 * @param camera - Active camera
 * @param controls - Player controls
 * @param keyStates - Current key states
 * @param audioState - Audio state for reactivity
 */
export function updatePhysics(delta: number, camera: THREE.Camera, controls: any, keyStates: KeyStates, audioState: AudioState) {
    // 1. Update Global Environmental Modifiers (Wind, Groove)
    updateEnvironmentalModifiers(delta, audioState);

    // Check if player is within active glitch grenade field
    // ⚡ OPTIMIZATION: Faster radius squared check
    const glitchRad = uGlitchExplosionRadius.value;
    if (glitchRad > 0) {
        const center = uGlitchExplosionCenter.value as unknown as THREE.Vector3;
        const dx = player.position.x - center.x;
        const dy = player.position.y - center.y;
        const dz = player.position.z - center.z;
        const distSq = dx*dx + dy*dy + dz*dz;

        if (distSq < glitchRad * glitchRad) {
            // Player is inside the glitch field - grant intangibility/phasing
            if (!player.isPhasing) {
                player.isPhasing = true;
                player.phaseTimer = 0.5; // Short duration, refreshed each frame while inside
            } else {
                // Refresh timer while inside
                if (player.phaseTimer < 0.5) player.phaseTimer = 0.5;
            }
        }
    }

    // 2. Check Triggers & State Transitions
    updateStateTransitions(camera, keyStates);

    // 3. Execute State Logic
    switch (player.currentState) {
        case PlayerState.DANCING:
            updateDancingState(delta, camera, controls, keyStates, audioState);
            break;
        case PlayerState.VINE:
            updateVineState(delta, camera, keyStates);
            break;
        case PlayerState.SWIMMING:
            updateSwimmingState(delta, camera, controls, keyStates, audioState);
            break;
        case PlayerState.CLIMBING:
            updateClimbingState(delta, camera, controls, keyStates);
            break;
        case PlayerState.DEFAULT:
        default:
            updateDefaultState(delta, camera, controls, keyStates, audioState);
            break;
    }

    // 4. Update Input History (for next frame edge detection)
    _lastInputState.jump = keyStates.jump;
    _lastInputState.dash = keyStates.dash;
    _lastInputState.dodgeRoll = keyStates.dodgeRoll;
    _lastInputState.dance = keyStates.dance;
    _lastInputState.phase = keyStates.phase;
    _lastInputState.clap = keyStates.clap;
    _lastInputState.forward = keyStates.forward;

    // 5. Check Flora Discovery (Throttled)
    const frameCount = Math.floor(Date.now() / 16);
    if (frameCount % 10 === 0) {
        checkFloraDiscovery(player.position);
    }

    // Sync back
    camera.position.x = player.position.x;
    camera.position.z = player.position.z;
    // 🎨 PALETTE: Smooth vertical tracking (LERP) for better game feel
    const targetY = player.position.y;
    const lerpSpeed = CONFIG.ground.followLerpSpeed;
    const maxStep = CONFIG.ground.followMaxStep;
    let nextY = THREE.MathUtils.lerp(camera.position.y, targetY, Math.min(delta * lerpSpeed, 1.0));
    nextY = THREE.MathUtils.clamp(nextY, camera.position.y - maxStep, camera.position.y + maxStep);
    camera.position.y = nextY;
}

// --- State: DEFAULT (Walking/Falling) ---
/**
 * Updates physics for the DEFAULT state (walking/falling).
 * Handles C++ physics integration, collision resolution, and foliage interactions.
 */
function updateDefaultState(delta: number, camera: THREE.Camera, controls: any, keyStates: KeyStates, audioState: AudioState) {
    if (!cppPhysicsInitialized) {
        initCppPhysics(camera);
        setCppPhysicsInitialized(true);
    }

    // ⚡ OPTIMIZATION: Caching time to avoid multiple Date.now() calls
    const now = performance.now(); // More precise than Date.now()

    // ⚡ OPTIMIZATION: Only update vines if they are somewhat near the player.
    for (let i = 0; i < vineSwings.length; i++) {
        const v = vineSwings[i];
        if (v !== activeVineSwing) {
            // Simple distance check (e.g. 50 units) before calling update to save CPU
            if (v.anchorPoint) {
                const dx = player.position.x - v.anchorPoint.x;
                const dz = player.position.z - v.anchorPoint.z;
                if (dx*dx + dz*dz < 2500) {
                    v.update(player as any, delta, null);
                }
            } else {
                v.update(player as any, delta, null);
            }
        }
    }

    if (now - lastVineDetachTime > 500) {
        checkVineAttachment(camera);
    }

    // --- ABILITIES & MOVEMENT ---
    handleAbilities(delta, camera, keyStates);

    // Update Phase Shift Timer
    if (player.isPhasing) {
        player.phaseTimer -= delta;
        if (player.phaseTimer <= 0) {
            player.isPhasing = false;
            showToast("Phase Shift Ended", "👻");
        }
    }

    // Update Invisibility Timer
    if (player.isInvisible) {
        player.invisibilityTimer -= delta;
        if (player.invisibilityTimer <= 0) {
            player.isInvisible = false;
            showToast("Camouflage Faded", "💨");
        }
    }

    // Decay Chromatic Pulse (Hack for now, ideally moved to a proper FX system)
    // If Phasing, keep intensity high
    if (player.isPhasing) {
        if (uChromaticIntensity) uChromaticIntensity.value = 0.8 + Math.sin(Date.now() * 0.01) * 0.1;
    } else {
        if (uChromaticIntensity && uChromaticIntensity.value > 0) {
            uChromaticIntensity.value = Math.max(0, uChromaticIntensity.value - delta * 2.0);
        }
    }

    const { moveVec: moveInput, moveSpeed: baseMoveSpeed } = calculateMovementInput(camera, keyStates, player);
    let moveSpeed = baseMoveSpeed;

    // --- Groove Boots Logic ---
    const hasGrooveBoots = unlockSystem.isUnlocked('groove_boots');
    // If we have groove boots AND groove gravity is significantly active (< 0.95)
    if (hasGrooveBoots && grooveGravity.multiplier < 0.95) {
        // Boost speed based on how strong the groove is (lower multiplier = stronger groove)
        const grooveBoost = 1.0 + (1.0 - grooveGravity.multiplier); // e.g., 0.8 -> 1.2x speed
        moveSpeed *= grooveBoost;

        // Visual/Audio Feedback could be added here periodically or when moving fast
        if (player.isGrounded && moveInput.lengthSq() > 0 && Math.random() < 0.05) {
             spawnImpact(player.position, 'dash'); // Sparkles at feet
        }
        discoverySystem.discover('groove_boots', 'Groove Boots', '🥾');
    }

    // 🎨 Palette: Sparkle trail when moving fast (Dash / Sprint / Fall)
    if (player.velocity.lengthSq() > 400 && Math.random() < 0.3) {
        spawnImpact(player.position, 'trail');
    }

    // 3. Sync State with C++
    setPlayerState(player.position.x, player.position.y, player.position.z, player.velocity.x, player.velocity.y, player.velocity.z);

    // 4. Run C++ Update (Pass World Space Vectors)
    // CRITICAL FIX: If we are in the Lake Basin, we MUST use JS Physics.
    // The C++ WASM engine does not know about the visual carving and will return the wrong ground height (floating player).
    const px = player.position.x;
    const pz = player.position.z;
    const inLakeBasin = isInLakeBasin(px, pz);

    let onGround = -1; // Default to failure/fallback

    // Prevent C++ from applying jump force if we are doing an Air Jump (which isn't grounded)
    const effectiveJumpInput = (player.isGrounded && keyStates.jump) ? 1 : 0;

    // --- BPM Wind Player Impact ---
    const hasWindAnchor = unlockSystem.isUnlocked('wind_anchor');
    let windForceX = 0;
    let windForceZ = 0;
    if (!hasWindAnchor && bpmWind.strength > 0) {
        // Apply wind force scaled by strength
        // The strength ranges [0, 1]. Apply a constant push velocity.
        const windPushForce = 25.0; // units/sec max
        windForceX = bpmWind.direction.x * bpmWind.strength * windPushForce * delta;
        windForceZ = bpmWind.direction.z * bpmWind.strength * windPushForce * delta;
    } else if (hasWindAnchor && bpmWind.strength > 0.5) {
        discoverySystem.discover('wind_anchor', 'Wind Anchor', '⚓');
    }

    if (!inLakeBasin) {
        onGround = updatePhysicsCPP(
            delta,
            moveInput.x,
            moveInput.z,
            moveSpeed,
            effectiveJumpInput > 0,
            keyStates.sprint,
            keyStates.sneak,
            grooveGravity.multiplier
        );
    }

    if (onGround >= 0) {
        // C++ Success
        getPlayerState(_scratchPlayerState);
        player.position.set(_scratchPlayerState.x + windForceX, _scratchPlayerState.y, _scratchPlayerState.z + windForceZ);
        player.velocity.set(_scratchPlayerState.vx, _scratchPlayerState.vy, _scratchPlayerState.vz);

        // Reset jump key if we successfully jumped (velocity.y > 0)
        // But only if we were grounded before (normal jump)
        if (player.velocity.y > 0 && player.isGrounded) {
             keyStates.jump = false;
             spawnImpact(player.position, 'jump');
             // 🎨 Palette: Audio feedback for jump
             if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                 (window as any).AudioSystem.playSound('jump', { pitch: Math.random() * 0.2 + 0.9, volume: 0.5 });
             }
             if (typeof uChromaticIntensity !== 'undefined') {
                 uChromaticIntensity.value = 0.2;
             }
        }

        const wasGrounded = player.isGrounded;
        player.isGrounded = (onGround === 1);

        if (!wasGrounded && player.isGrounded && player.velocity.y < -1.0) {
            // 🎨 PALETTE: Make landing feedback dynamic based on fall velocity
            const fallSpeed = Math.abs(player.velocity.y);

            if (fallSpeed > 15.0) {
                // Hard fall -> Big splash, heavy screen distortion
                spawnImpact(player.position, 'land');
                spawnImpact(player.position, 'dash'); // Extra particles
                addCameraShake(0.4); // 🎨 Palette: Heavy landing shake
                if (uChromaticIntensity) uChromaticIntensity.value = 0.8;
                // 🎨 Palette: Heavy impact audio
                if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                    (window as any).AudioSystem.playSound('impact', { pitch: 0.6, volume: 1.0 });
                }
            } else if (fallSpeed > 8.0) {
                // Medium fall
                spawnImpact(player.position, 'land');
                addCameraShake(0.15); // 🎨 Palette: Medium landing shake
                if (uChromaticIntensity) uChromaticIntensity.value = 0.5;
                // 🎨 Palette: Medium impact audio
                if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                    (window as any).AudioSystem.playSound('impact', { pitch: 0.8, volume: 0.7 });
                }
            } else {
                // Soft landing
                spawnImpact(player.position, 'jump'); // Lighter particle burst
                if (uChromaticIntensity) uChromaticIntensity.value = 0.2;
                // 🎨 Palette: Soft impact audio
                if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                    (window as any).AudioSystem.playSound('impact', { pitch: 1.2, volume: 0.4 });
                }
            }
        }
    } else {
        // JS Fallback (Used for Lake Basin or C++ Failure)
        updateJSFallbackMovement(delta, camera, controls, keyStates, moveSpeed);
        player.position.x += windForceX;
        player.position.z += windForceZ;
    }

    // Issue #1265: Reconcile C++ / fallback Y with the authoritative ground query.
    // Smoothly tracks terrain when grounded; preserves platform elevation when high.
    if (player.isGrounded || player.velocity.y <= 0) {
        const prevY = player.position.y;
        const nextY = reconcileGroundedEyeY(
            prevY,
            player.position.x,
            player.position.z,
            delta,
            { isGrounded: player.isGrounded, velocityY: player.velocity.y }
        );
        if (nextY !== prevY) {
            player.position.y = nextY;
            if (player.isGrounded) {
                player.velocity.y = 0;
            }
        }
    }

    // --- WASM COLLISION RESOLVER (New) ---
    // Try WASM resolution first
    const kickTrigger = audioState?.kickTrigger || 0.0;
    const wasmResolved = resolveGameCollisionsWASM(player, kickTrigger);

    // Check discovery flags based on what happened?
    if (wasmResolved) {
         if (player.velocity.y > 12.0) {
              discoverySystem.discover('trampoline_shroom', 'Trampoline Mushroom', '🍄');
              keyStates.jump = false;

              // --- VERTICAL ECOSYSTEM: Audio-Reactive Mushroom Bounce ---
              // Scale bounce height with current kick strength / note energy
              const kick = audioState?.kickTrigger || 0;
              const noteStrength = audioState?.noteVelocity || kick;
              const bounceMultiplier = 1.0 + noteStrength * 0.8; // 1.0x - 1.8x
              player.velocity.y *= bounceMultiplier;

              // 🎨 Palette: Add "Juice" to trampoline mushroom bounce
              spawnImpact(player.position, 'jump');
              addCameraShake(0.3 * bounceMultiplier); // 🎨 Palette: Trampoline bounce shake
              if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                  (window as any).AudioSystem.playSound('impact', { pitch: 1.2 + noteStrength * 0.6, volume: 0.8 });
              }
              if (typeof uChromaticIntensity !== 'undefined') {
                  uChromaticIntensity.value = 0.5 * bounceMultiplier;
              }
         }
         // Check if we landed on a cloud (isGrounded=true at High Y)
         if (player.isGrounded && player.position.y > 10.0) {
              discoverySystem.discover('cloud_platform', 'Solid Cloud', '☁️');
         }
    }

    // --- Panning Pads (JS Physics) --
    // Explicit check for dynamic panning pads (bobbing platforms)
    checkPanningPads();

    // --- Kick-Drum Geysers (Riding the Plume) ---
    checkGeysers(delta);

    // --- Snare Traps (Knockback) ---
    checkSnareTraps(delta);

    // --- Portamento Pines (Slingshot/Ramp) ---
    checkPortamentoPines(delta);

    // --- Vibrato Violets (Frequency Distortion Field) ---
    checkVibratoViolets(delta, audioState);

    // --- Retrigger Mushrooms (Strobe Sickness HUD Flicker) ---
    checkRetriggerMushrooms(delta, audioState);

    // --- Harmony Orbs (Collection) ---
    checkHarmonyOrbs();
}

// src/systems/physics/physics-states.ts
// State handlers: Swimming, Vine, Climbing, Dancing, Default

import * as THREE from 'three';
import { uChromaticIntensity } from '../../foliage/chromatic.ts';
import { spawnImpact } from '../../foliage/impacts.ts';
import { fastInvSqrt } from '../../utils/wasm-loader.ts';
import { 
    activeVineSwing, 
    setActiveVineSwing, 
    lastVineDetachTime, 
    setLastVineDetachTime, 
    vineSwings,
    foliageVineLadders
} from '../../world/state.ts';
import { discoverySystem } from '../discovery.ts';
import { getGroundHeight as getAuthoritativeGroundHeight } from '../ground-system.ts';
import { calculateWaterLevel } from '../physics.core.ts';
import { 
    player, 
    PlayerState, 
    _lastInputState,
    _scratchSwimDir,
    _scratchCamDir,
    _scratchCamRight,
    _scratchMoveVec,
    _scratchUp,
    SWIMMING_GRAVITY,
    SWIMMING_DRAG,
    PLAYER_HEIGHT_OFFSET,
    DANCE_KICK_THRESHOLD,
    bpmWind,
    grooveGravity,
    AudioState,
    KeyStates,
    foliageCaves
} from './physics-types.ts';

// Helper: Unified Ground Height (authoritative terrain + lake + island + platforms)

// --- Environmental Modifiers ---
export function updateEnvironmentalModifiers(delta: number, audioState: AudioState) {
    if (audioState) {
        // Groove Gravity
        const groove = audioState.grooveAmount || 0;
        grooveGravity.targetMultiplier = 1.0 - (groove * 0.4);
        grooveGravity.multiplier += (grooveGravity.targetMultiplier - grooveGravity.multiplier) * delta * 5.0;
        player.gravity = grooveGravity.baseGravity * grooveGravity.multiplier;

        // BPM Wind (Visuals only for now)
        const currentBPM = audioState.bpm || 120;
        bpmWind.bpm = currentBPM;
        bpmWind.targetStrength = Math.min(1.0, (currentBPM - 60) / 120);
        bpmWind.strength += (bpmWind.targetStrength - bpmWind.strength) * delta * 2;
    }
}

// --- State Transitions ---
export function updateStateTransitions(camera: THREE.Camera, keyStates: KeyStates) {
    const playerPos = player.position;

    // A. Check Dance Mode Toggle (Toggle on/off with R key)
    const isDancePressed = keyStates.dance;
    const isDanceTriggered = isDancePressed && !_lastInputState.dance;

    if (isDanceTriggered) {
        if (player.currentState === PlayerState.DANCING) {
            // Exit dance mode
            player.currentState = PlayerState.DEFAULT;
            player.isDancing = false;
            player.danceTime = 0;
            // Clean up dance state
            // ⚡ OPTIMIZATION: Instead of undefined, just let the logic reset values on next dance to avoid GC
            player.danceStartY = undefined;
            // Reset camera rotation
            camera.rotation.z = 0;
        } else if (player.currentState === PlayerState.DEFAULT) {
            // Enter dance mode
            player.currentState = PlayerState.DANCING;
            player.isDancing = true;
            player.danceTime = 0;
        }
    }

    // Skip other state transitions when dancing
    if (player.currentState === PlayerState.DANCING) {
        return;
    }

    // C. Check Climbing Transitions
    if (player.currentState === PlayerState.DEFAULT) {
        const nearest = findNearestClimbable(playerPos, 2.5);
        if (nearest) {
            // Enter climbing when pressing forward near a ladder
            const isForwardPressed = keyStates.forward;
            const isForwardTriggered = isForwardPressed && !_lastInputState.forward;
            if (isForwardTriggered) {
                player.currentState = PlayerState.CLIMBING;
                player.climbTarget = nearest;
                const length = nearest.userData.vineLength || 10;
                player.climbTopY = nearest.position.y;
                discoverySystem.discover('vine_ladder', 'Vine Ladder', '🪜');
            }
        }
    } else if (player.currentState === PlayerState.CLIMBING) {
        const isJumpPressed = keyStates.jump;
        const isJumpTriggered = isJumpPressed && !_lastInputState.jump;
        if (isJumpTriggered) {
            // Detach with boost
            player.currentState = PlayerState.DEFAULT;
            player.velocity.y = CLIMB_DETACH_BOOST;
            player.climbTarget = null;
        }
    }

    // B. Check Water Level / Cave Flooding
    // MIGRATED: Now uses TypeScript version from physics.core.ts
    const waterLevel = calculateWaterLevel(playerPos, foliageCaves);

    const wasSwimming = player.currentState === PlayerState.SWIMMING;
    const isNowUnderwater = playerPos.y < waterLevel;
    player.isUnderwater = isNowUnderwater;

    // Transition: Enter/Exit Water
    if (isNowUnderwater && !wasSwimming) {
        player.currentState = PlayerState.SWIMMING;
        // Dampen velocity on entry
        player.velocity.multiplyScalar(0.5);
    } else if (!isNowUnderwater && wasSwimming) {
        // Exit water logic
        if (playerPos.y > waterLevel) {
            player.currentState = PlayerState.DEFAULT;
            if (keyStates.jump) player.velocity.y = 8.0; // Boost out
        }
    }

    // Transition: Vine Handling
    if (activeVineSwing) {
        player.currentState = PlayerState.VINE;
        discoverySystem.discover('vine_swing', 'Swingable Vine', '🪜');
    } else if (player.currentState === PlayerState.VINE) {
        player.currentState = PlayerState.DEFAULT;
    }
}

// --- State: SWIMMING ---
export function updateSwimmingState(
    delta: number, 
    camera: THREE.Camera, 
    controls: any, 
    keyStates: KeyStates, 
    audioState: AudioState | null
) {
    player.velocity.y -= (SWIMMING_GRAVITY * delta);
    // Clamp drag factor to [0,1] to prevent velocity reversal on large delta (e.g., tab switch)
    player.velocity.multiplyScalar(Math.max(0, 1.0 - (SWIMMING_DRAG * delta)));

    const kickTrigger = audioState?.kickTrigger || 0.0;
    const surfBoost = kickTrigger > 0.5 ? kickTrigger * 1.5 : 0;

    // Base speed + potential surfing boost on kick
    const swimSpeed = player.speed * (0.6 + surfBoost);
    const swimDir = _scratchSwimDir.set(0, 0, 0);

    if (keyStates.forward) swimDir.z += 1;
    if (keyStates.backward) swimDir.z -= 1;
    if (keyStates.right) swimDir.x += 1;
    if (keyStates.left) swimDir.x -= 1;

    if (swimDir.lengthSq() > 0) {
        swimDir.normalize();
        const camDir = _scratchCamDir;
        camera.getWorldDirection(camDir);
        const camRight = _scratchCamRight;
        camRight.crossVectors(camDir, _scratchUp);

        const moveVec = _scratchMoveVec.set(0, 0, 0)
            .addScaledVector(camDir, swimDir.z)
            .addScaledVector(camRight, swimDir.x);

        player.velocity.addScaledVector(moveVec, swimSpeed * delta);

        // Surfing feedback if moving forward
        if (surfBoost > 0 && keyStates.forward) {
            // Only trigger occasionally so we don't spam impacts/toasts
            if (Math.random() < 0.05) {
                spawnImpact(player.position, 'dash');
                if (uChromaticIntensity) {
                    uChromaticIntensity.value = 0.3;
                }
                discoverySystem.discover('waveform_surfing', 'Waveform Surfing', '🌊');
            }
        }
    }

    if (keyStates.jump) player.velocity.y += 10 * delta;
    if (keyStates.sneak) player.velocity.y -= 10 * delta;

    // Harpoon Mechanics
    if (player.harpoon.active) {
        const dx = player.harpoon.anchor.x - player.position.x;
        const dy = player.harpoon.anchor.y - player.position.y;
        const dz = player.harpoon.anchor.z - player.position.z;
        const distSq = dx*dx + dy*dy + dz*dz;

        if (distSq < 4.0) { // Reached anchor
            player.harpoon.active = false;
            player.velocity.y += 15.0; // Boost out
            spawnImpact(player.position, 'jump');
        } else {
            // Pull towards anchor
            // ⚡ OPTIMIZATION: Bypassed Math.sqrt overhead using fastInvSqrt for vector normalization
            const invDist = fastInvSqrt(distSq);
            // Modulate pull speed with kick drum
            const kickBoost = audioState?.kickTrigger ? audioState.kickTrigger * 20.0 : 0;
            const pullSpeed = 30.0 + kickBoost;

            player.velocity.x += (dx * invDist) * pullSpeed * delta;
            player.velocity.y += (dy * invDist) * pullSpeed * delta;
            player.velocity.z += (dz * invDist) * pullSpeed * delta;

            if (Math.random() < 0.1) {
                spawnImpact(player.position, 'dash');
            }
        }
    }

    // controls.moveRight/Forward applies to the camera object directly, which we synced to player.position
    // But Three.js PointerLockControls uses its own internal object.
    // We update position manually here instead.

    player.position.x += player.velocity.x * delta;
    player.position.z += player.velocity.z * delta;
    player.position.y += player.velocity.y * delta;
}

// --- State: VINE SWING ---
export function updateVineState(delta: number, camera: THREE.Camera, keyStates: KeyStates) {
    if (activeVineSwing) {
        // VineSwing.update expects PlayerObject, but Camera is an Object3D
        // We pass camera for visual updates (positioning) - it's compatible enough
        activeVineSwing.update(camera as any, delta, keyStates);

        // CRITICAL: Sync player position to match camera immediately
        // because VineSwing modified camera.position
        player.position.copy(camera.position);

        if (keyStates.jump) {
            // detach modifies velocity, pass player (has velocity)
            setLastVineDetachTime(activeVineSwing.detach(player as any));
            setActiveVineSwing(null);
            keyStates.jump = false;
            player.currentState = PlayerState.DEFAULT;
        }
    }
}

// --- State: CLIMBING ---
const CLIMB_SPEED = 6.0;
const CLIMB_DETACH_BOOST = 8.0;
const CLIMB_MAX_DIST_SQ = 2.5 * 2.5;

export function updateClimbingState(
    delta: number,
    camera: THREE.Camera,
    controls: any,
    keyStates: KeyStates
) {
    if (!player.climbTarget) {
        player.currentState = PlayerState.DEFAULT;
        return;
    }

    const target = player.climbTarget;
    const topY = player.climbTopY;

    // Horizontal snap: keep player centered on the climbable
    player.position.x += (target.position.x - player.position.x) * 5.0 * delta;
    player.position.z += (target.position.z - player.position.z) * 5.0 * delta;

    // Vertical movement
    if (keyStates.forward || keyStates.jump) {
        player.position.y += CLIMB_SPEED * delta;
    } else if (keyStates.backward || keyStates.sneak) {
        player.position.y -= CLIMB_SPEED * delta;
    }

    // Clamp to bottom (don't go below ladder base)
    const length = target.userData.vineLength || 10;
    const baseY = target.position.y - length;
    if (player.position.y < baseY + PLAYER_HEIGHT_OFFSET) {
        player.position.y = baseY + PLAYER_HEIGHT_OFFSET;
        // Drop off at bottom
        player.currentState = PlayerState.DEFAULT;
        player.climbTarget = null;
        return;
    }

    // Auto-step off at top
    if (player.position.y >= topY - 0.5) {
        player.position.y = topY + PLAYER_HEIGHT_OFFSET;
        player.currentState = PlayerState.DEFAULT;
        player.climbTarget = null;
        // Small forward nudge so we don't immediately fall back
        const forward = _scratchCamDir.set(0, 0, -1).applyQuaternion(camera.quaternion);
        forward.y = 0;
        forward.normalize();
        player.position.addScaledVector(forward, 0.5);
        return;
    }

    // Check if we strayed too far horizontally
    const dx = player.position.x - target.position.x;
    const dz = player.position.z - target.position.z;
    if (dx * dx + dz * dz > CLIMB_MAX_DIST_SQ) {
        player.currentState = PlayerState.DEFAULT;
        player.climbTarget = null;
    }

    player.velocity.set(0, 0, 0);
}

// Helper: Find nearest climbable object
const _scratchClimbablePos = new THREE.Vector3();

export function findNearestClimbable(
    position: THREE.Vector3,
    maxRadius: number = 2.0
): THREE.Object3D | null {
    let best: THREE.Object3D | null = null;
    let bestDistSq = maxRadius * maxRadius;

    for (const ladder of foliageVineLadders) {
        _scratchClimbablePos.copy(ladder.position);
        // Ladder anchor is at top, bottom extends down by length
        const length = ladder.userData.vineLength || 10;
        const bottomY = _scratchClimbablePos.y - length;
        // Only climbable if player is within vertical range
        if (position.y < bottomY - 1.0 || position.y > _scratchClimbablePos.y + 1.0) continue;

        const dx = position.x - _scratchClimbablePos.x;
        const dz = position.z - _scratchClimbablePos.z;
        const distSq = dx * dx + dz * dz;
        if (distSq < bestDistSq) {
            bestDistSq = distSq;
            best = ladder;
        }
    }

    return best;
}

// --- State: DANCING ---
export function updateDancingState(
    delta: number, 
    camera: THREE.Camera, 
    controls: any, 
    keyStates: KeyStates, 
    audioState: AudioState | null
) {
    // Unlock pointer if locked
    if (document.pointerLockElement === document.body) {
        controls.unlock();
    }

    // Store initial values before updating dance time so that we can check for danceTime === 0
    const isFirstFrame = player.danceTime === 0;

    // Update dance time
    player.danceTime += delta;

    // Get BPM and beat info from audio (with fallbacks for when no music is playing)
    const bpm = audioState?.bpm ?? 120;
    const beatPhase = audioState?.beatPhase ?? 0;
    const kickTrigger = audioState?.kickTrigger ?? 0;

    // Calculate beat duration in seconds
    const beatDuration = 60.0 / bpm;
    const danceSpeed = 1.0 + (bpm / 120.0); // Faster dance at higher BPMs

    // Position movement: Small circular pattern
    const circleRadius = 0.5 + (kickTrigger * 0.3); // Bigger circle on kicks
    const circleSpeed = danceSpeed * 2.0;
    const angle = player.danceTime * circleSpeed;

    // Store initial position on first frame
    // ⚡ OPTIMIZATION: Zero-allocation dance state initialization
    if (isFirstFrame || !player.danceStartPos) {
        player.danceStartPos = player.danceStartPos || new THREE.Vector3();
        player.danceStartPos.copy(player.position);
        player.danceStartY = getAuthoritativeGroundHeight(player.position.x, player.position.z) + PLAYER_HEIGHT_OFFSET;
    }

    // Move in a circle around starting position
    player.position.x = player.danceStartPos.x + Math.sin(angle) * circleRadius;
    player.position.z = player.danceStartPos.z + Math.cos(angle) * circleRadius;

    // Bob up and down with the beat
    const bobAmount = 0.3 + (kickTrigger * 0.2);
    const bobPhase = beatPhase * Math.PI * 2;
    // TypeScript safety: danceStartY is initialized right after danceStartPos
    player.position.y = (player.danceStartY || 0) + Math.sin(bobPhase) * bobAmount;

    // Camera view movement: Rotate and tilt based on music
    // Get current camera rotation
    const pitchAmount = Math.sin(player.danceTime * danceSpeed * 1.5) * 0.15; // Tilt up/down
    const yawAmount = Math.cos(player.danceTime * danceSpeed) * 0.3; // Turn left/right

    // Apply rotation relative to initial orientation
    // ⚡ OPTIMIZATION: Zero-allocation dance state initialization
    if (isFirstFrame || !player.danceStartRotation) {
        player.danceStartRotation = player.danceStartRotation || { x: 0, y: 0, z: 0 };
        player.danceStartRotation.x = camera.rotation.x;
        player.danceStartRotation.y = camera.rotation.y;
        player.danceStartRotation.z = camera.rotation.z;
    }

    // Smooth rotation animation
    camera.rotation.x = player.danceStartRotation.x + pitchAmount;
    camera.rotation.y = player.danceStartRotation.y + yawAmount;

    // Extra bounce on kick
    if (kickTrigger > DANCE_KICK_THRESHOLD) {
        camera.rotation.z = Math.sin(player.danceTime * 10) * 0.05;
    } else {
        camera.rotation.z *= 0.9; // Dampen roll
    }

    // Zero velocity while dancing
    player.velocity.set(0, 0, 0);

    // Discovery
    if (player.danceTime < 0.1) {
        discoverySystem.discover('ability_dance', 'Dance Mode', '💃');
    }
}

// src/systems/physics/physics-types.ts
// Types, constants, and shared state for physics system

import * as THREE from 'three';
import { CONFIG } from '../../core/config.ts';
import { PlayerState as CorePlayerState, KeyStates } from '../physics.core.ts';

// Re-export KeyStates for convenience
export type { KeyStates };

// --- Types ---

export interface AudioState {
    grooveAmount?: number;
    bpm?: number;
    kickTrigger?: number;
    beatPhase?: number;
    channelData?: any[];
    [key: string]: any;
}

export interface PlayerExtended extends CorePlayerState {
    airJumpsLeft: number;
    dashCooldown: number;
    canDash: boolean;
    dodgeRollCooldown: number;
    canDodgeRoll: boolean;
    isDancing: boolean;
    danceTime: number;
    danceStartPos?: THREE.Vector3;
    danceStartY?: number;
    danceStartRotation?: { x: number; y: number; z: number };
    hasShield: boolean;
    isPhasing: boolean;
    phaseTimer: number;
    isInvisible: boolean;
    invisibilityTimer: number;
    harpoon: {
        active: boolean;
        anchor: THREE.Vector3;
    };
    climbTarget: THREE.Object3D | null;
    climbTopY: number;
}

