interface PhysicsSyncObject {
    position?: {
        x?: number;
        y?: number;
        z?: number;
    };
}

function hasFinitePosition(obj: PhysicsSyncObject): boolean {
    const position = obj?.position;
    return Number.isFinite(position?.x) && Number.isFinite(position?.y) && Number.isFinite(position?.z);
}

function filterValidPhysicsObjects<T extends PhysicsSyncObject>(objects: T[] | undefined, label: string): T[] {
    if (!Array.isArray(objects) || objects.length === 0) {
        return [];
    }

    const validObjects: T[] = [];
    for (let i = 0; i < objects.length; i++) {
        if (hasFinitePosition(objects[i])) {
            validObjects.push(objects[i]);
        }
    }

    if (validObjects.length !== objects.length) {
        console.warn(`[Physics] Skipping ${objects.length - validObjects.length} invalid ${label} objects during WASM collision sync.`);
    }
    return validObjects;
}

/**
 * Checks for flora discovery within player proximity.
 */
export function checkFloraDiscovery(playerPos: THREE.Vector3) {
    if (optimizedDiscovery.isUsingWasm()) {
        checkPlayerDiscovery(playerPos);
    } else {
        // ⚡ OPTIMIZATION: Converted O(N) array search into a Spatial Hash Grid query for flora discovery
        const DISCOVERY_RADIUS_SQ = 5.0 * 5.0;
        const nearbyObjects = physicsDiscoveryGrid.findNearby(playerPos.x, playerPos.z, 5.0);

        for (let i = 0; i < nearbyObjects.length; i++) {
            const obj = nearbyObjects[i];
            const type = obj.userData?.type;
            if (!type) continue;

            const discoveryInfo = DISCOVERY_MAP[type];
            if (discoveryInfo && !discoverySystem.isDiscovered(type)) {
                const dx = playerPos.x - obj.position.x;
                const dy = playerPos.y - obj.position.y;
                const dz = playerPos.z - obj.position.z;
                const distSq = dx*dx + dy*dy + dz*dz;

                if (distSq < DISCOVERY_RADIUS_SQ) {
                    discoverySystem.discover(type, discoveryInfo.name, discoveryInfo.icon);
                }
            }
        }
    }
    if (player.velocity.lengthSq() > 400 && Math.random() < 0.3) {
        spawnImpact(player.position, 'trail');
    }
}

/**
 * Harmony orb collection mechanics.
 */
export function checkHarmonyOrbs() {
    const playerPos = player.position;
    const radiusSq = 2.0 * 2.0;
    for (let i = 0; i < harmonyOrbSystem.orbs.length; i++) {
        const orb = harmonyOrbSystem.orbs[i];
        if (!orb.active) continue;
        const dx = orb.position.x - playerPos.x;
        const dy = orb.position.y - playerPos.y;
        const dz = orb.position.z - playerPos.z;
        const distSq = dx*dx + dy*dy + dz*dz;
        if (distSq < radiusSq) {
            orb.active = false;
            harmonyOrbSystem.dummy.position.set(0, -9999, 0);
            harmonyOrbSystem.dummy.scale.setScalar(0);
            _scratchMatrix.compose(harmonyOrbSystem.dummy.position, harmonyOrbSystem.dummy.quaternion, harmonyOrbSystem.dummy.scale);
            _scratchMatrix.toArray(harmonyOrbSystem.mesh.instanceMatrix.array, (i) * 16);
            harmonyOrbSystem.mesh.instanceMatrix.needsUpdate = true;
            spawnImpact(orb.position, 'berry', 0x9933FF);
            unlockSystem.harvest('harmony_orb', 1, 'Harmony Orb');
            if (uChromaticIntensity) {
                uChromaticIntensity.value = Math.max(uChromaticIntensity.value, 0.4);
            }
        }
    }
}

/**
 * Retrigger mushroom strobe effect triggers.
 */
export function checkRetriggerMushrooms(delta: number, audioState: AudioState | null) {
    if (!audioState || !audioState.channelData) return;
    const playerPos = player.position;
    let inStrobeField = false;
    let maxIntensity = 0;

    // ⚡ OPTIMIZATION: Hoisted O(N) audio channel scan outside the spatial query loop
    let isStrobing = false;
    for (const ch of audioState.channelData) {
        if (ch.activeEffect === 5 && ch.effectValue > 0) {
            isStrobing = true;
            break;
        }
    }

    if (isStrobing) {
        const nearbyObjects = physicsFoliageGrid.findNearby(playerPos.x, playerPos.z, 15.0);
        for (let i = 0; i < nearbyObjects.length; i++) {
            const obj = nearbyObjects[i];
            if (obj.userData?.type === 'retrigger_mushroom') {
                const dx = playerPos.x - obj.position.x;
                const dz = playerPos.z - obj.position.z;
                const distSq = dx * dx + dz * dz;
                if (distSq < 15.0 * 15.0) {
                    inStrobeField = true;
                    const localIntensity = 1.0 - (distSq / 225.0);
                    if (localIntensity > maxIntensity) {
                        maxIntensity = localIntensity;
                    }
                }
            }
        }
    }

    if (inStrobeField) {
        if (typeof uStrobeIntensity !== 'undefined') {
            uStrobeIntensity.value = Math.max(uStrobeIntensity.value, maxIntensity * 0.8);
        }
    } else {
        if (typeof uStrobeIntensity !== 'undefined' && uStrobeIntensity.value > 0) {
            uStrobeIntensity.value = Math.max(0, uStrobeIntensity.value - delta * 2.0);
        }
    }
}

/**
 * Vibrato violet frequency distortion field effects.
 */
export function checkVibratoViolets(delta: number, audioState: AudioState | null) {
    if (!audioState || !audioState.channelData) return;
    const playerPos = player.position;
    let inDistortionField = false;

    // ⚡ OPTIMIZATION: Hoisted O(N) audio channel scan outside the spatial query loop
    let isVibrating = false;
    for (const ch of audioState.channelData) {
        if (ch.activeEffect === 4 && ch.effectValue > 0) {
            isVibrating = true;
            break;
        }
    }

    if (!isVibrating) return; // Early out if no vibration is active

    const nearbyObjects = physicsFoliageGrid.findNearby(playerPos.x, playerPos.z, 20.0);
    for (let i = 0; i < nearbyObjects.length; i++) {
        const obj = nearbyObjects[i];
        if (obj.userData?.type === 'vibratoViolet') {
            const dx = playerPos.x - obj.position.x;
            const dz = playerPos.z - obj.position.z;
            const distSq = dx * dx + dz * dz;
            if (distSq < 20.0 * 20.0) {
                inDistortionField = true;
                if (typeof uChromaticIntensity !== 'undefined' && uChromaticIntensity.value < 0.3) {
                     uChromaticIntensity.value += delta * 1.5;
                }
                break;
            }
        }
    }
}

/**
 * Portamento pine slingshot/ramp mechanics.
 */
export function checkPortamentoPines(delta: number) {
    const playerPos = player.position;
    const now = performance.now();
    const nearbyPines = physicsPinesGrid.findNearby(playerPos.x, playerPos.z, 5.0);
    for (let i = 0; i < nearbyPines.length; i++) {
        const pine = nearbyPines[i];
        const dx = playerPos.x - pine.position.x;
        const dz = playerPos.z - pine.position.z;
        const distSq = dx*dx + dz*dz;
        const interactRadius = 1.2;
        if (distSq < interactRadius * interactRadius) {
            const dy = playerPos.y - pine.position.y;
            if (dy > 0 && dy < 4.0) {
                const state = pine.userData.reactivityState;
                if (!state) continue;
                const bendDir = _scratchCamDir.set(1, 0, 0).applyQuaternion(pine.quaternion);
                const bend = state.currentBend || 0;
                const pushDir = _scratchMoveVec.set(dx, 0, dz).normalize();
                const pushAlignment = pushDir.dot(bendDir);
                const pushStrength = 60.0;
                state.velocity += pushAlignment * pushStrength * delta;
                if (now - (pine.userData.lastLaunchTime || 0) < 1000) continue;
                if (bend > 0.5) {
                    if (player.velocity.y < 5.0) {
                         player.velocity.y = 25.0 * (Math.abs(bend) / 1.0);
                         player.velocity.addScaledVector(bendDir, 10.0);
                         spawnImpact(playerPos, 'jump');
                         discoverySystem.discover('portamento_pine', 'Portamento Pine', '🌲');
                         player.airJumpsLeft = 1;
                         player.isGrounded = false;
                         pine.userData.lastLaunchTime = now;
                    }
                }
                else if (bend < -0.5) {
                    if (state.velocity > 5.0) {
                         player.velocity.addScaledVector(bendDir, 40.0 * Math.abs(bend));
                         player.velocity.y = 15.0;
                         spawnImpact(playerPos, 'dash');
                         discoverySystem.discover('portamento_pine', 'Portamento Pine', '🌲');
                         player.airJumpsLeft = 1;
                         player.isGrounded = false;
                         pine.userData.lastLaunchTime = now;
                    }
                }
            }
        }
    }
}

/**
 * Snare trap knockback mechanics.
 */
export function checkSnareTraps(delta: number) {
    const nearbyTraps = physicsTrapsGrid.findNearby(player.position.x, player.position.z, 5.0);
    for (let i = 0; i < nearbyTraps.length; i++) {
        const trap = nearbyTraps[i];
        const dx = player.position.x - trap.position.x;
        const dz = player.position.z - trap.position.z;
        const distSq = dx * dx + dz * dz;
        const radius = 0.8 * (trap.scale.x || 1.0);
        if (distSq < radius * radius) {
            const dy = player.position.y - trap.position.y;
            if (dy > -0.5 && dy < 1.5) {
                const snapState = trap.userData.snapState || 0;
                if (snapState < 0.2) {
                     trap.userData.snapState = 1.0;
                     spawnImpact(trap.position, 'snare');
                }
                if (trap.userData.snapState > 0.5) {
                     const pushDir = _scratchMoveVec.set(dx, 0, dz).normalize();
                     if (pushDir.lengthSq() === 0) pushDir.set(1, 0, 0);
                     player.velocity.addScaledVector(pushDir, 60.0 * delta * snapState);
                     player.velocity.y = Math.max(player.velocity.y, 15.0 * snapState);
                     player.isGrounded = false;
                     if (Math.random() < 0.2) {
                         if (uChromaticIntensity) uChromaticIntensity.value = 0.8;
                         spawnImpact(player.position, 'snare');
                         addCameraShake(0.6);
                         if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                             (window as any).AudioSystem.playSound('impact', { pitch: 0.4, volume: 1.0 });
                         }
                         showToast("Snared! 🪤", "⚠️");
                     }
                }
            }
        }
    }
}

/**
 * Geyser lift mechanics.
 * Hot path: batchGeyserLaunch (C++ when available, JS fallback otherwise).
 */
export function checkGeysers(delta: number) {
    const nearbyGeysers = physicsGeysersGrid.findNearby(player.position.x, player.position.z, 5.0);
    if (nearbyGeysers.length === 0) return;

    const { data, count } = packGeysers(nearbyGeysers);
    const result = batchGeyserLaunch(
        player.position.x,
        player.position.y,
        player.position.z,
        player.velocity.y,
        delta,
        data,
        count
    );

    if (result.hit) {
        player.velocity.y = result.vy;
        if (result.airJump) player.airJumpsLeft = 1;
        if (result.unground) player.isGrounded = false;
        discoverySystem.discover('kick_drum_geyser', 'Kick-Drum Geyser', '⛲');
    }
}

/**
 * Panning pad bobbing platform mechanics.
 * Hot path: batchPadForces (C++ when available, JS fallback otherwise).
 */
export function checkPanningPads() {
    const nearbyPads = physicsPanningPadsGrid.findNearby(player.position.x, player.position.z, 10.0);
    if (nearbyPads.length === 0) return;

    const { data, count } = packPads(nearbyPads);
    const result = batchPadForces(
        player.position.x,
        player.position.y,
        player.position.z,
        player.velocity.y,
        data,
        count
    );

    if (!result.hit) return;

    if (result.action === 'launch') {
        player.velocity.y = result.vy;
        player.airJumpsLeft = 1;
        const pad = nearbyPads[result.padIndex];
        if (pad) {
            spawnImpact(pad.position, 'jump');
            discoverySystem.discover('panning_pad', 'Panning Pad', '🪷');
        }
    } else if (result.action === 'snap') {
        player.position.y = result.snapY;
        player.velocity.y = 0;
        player.isGrounded = true;
    }
}

/**
 * JavaScript fallback movement (used for Lake Basin).
 */
export function updateJSFallbackMovement(delta: number, camera: THREE.Camera, controls: any, keyStates: KeyStates, moveSpeed: number) {
    const camDir = _scratchCamDir;
    camera.getWorldDirection(camDir);
    camDir.y = 0;
    camDir.normalize();
    const camRight = _scratchCamRight.crossVectors(camDir, _scratchUp);
    const _targetVelocity = _scratchTargetVel.set(0, 0, 0);
    if (keyStates.forward) _targetVelocity.add(camDir);
    if (keyStates.backward) _targetVelocity.sub(camDir);
    if (keyStates.right) _targetVelocity.add(camRight);
    if (keyStates.left) _targetVelocity.sub(camRight);
    if (_targetVelocity.lengthSq() > 0) _targetVelocity.normalize().multiplyScalar(moveSpeed);
    const smoothing = Math.min(1.0, 15.0 * delta);
    player.velocity.x += (_targetVelocity.x - player.velocity.x) * smoothing;
    player.velocity.z += (_targetVelocity.z - player.velocity.z) * smoothing;
    player.velocity.y -= player.gravity * delta;
    player.position.x += player.velocity.x * delta;
    player.position.z += player.velocity.z * delta;
    player.position.y += player.velocity.y * delta;
    const groundY = getGroundHeight(player.position.x, player.position.z);
    const eyeY = groundY + CONFIG.player.eyeHeight;
    const wasGrounded = player.isGrounded;
    if (player.position.y < eyeY && player.velocity.y <= 0) {
        player.position.y = eyeY;
        player.velocity.y = 0;
        player.isGrounded = true;
        if (!wasGrounded) {
             const fallSpeed = Math.abs(player.velocity.y);
             if (fallSpeed > 15.0) {
                 spawnImpact(player.position, 'land');
                 spawnImpact(player.position, 'dash');
                 addCameraShake(0.4);
                 if (uChromaticIntensity) uChromaticIntensity.value = 0.8;
                 if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                     (window as any).AudioSystem.playSound('impact', { pitch: 0.6, volume: 1.0 });
                 }
             } else if (fallSpeed > 8.0) {
                 spawnImpact(player.position, 'land');
                 addCameraShake(0.15);
                 if (uChromaticIntensity) uChromaticIntensity.value = 0.5;
                 if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                     (window as any).AudioSystem.playSound('impact', { pitch: 0.8, volume: 0.7 });
                 }
             } else {
                 spawnImpact(player.position, 'jump');
                 if (uChromaticIntensity) uChromaticIntensity.value = 0.2;
                 if ((window as any).AudioSystem && (window as any).AudioSystem.playSound) {
                     (window as any).AudioSystem.playSound('impact', { pitch: 1.2, volume: 0.4 });
                 }
             }
        }
    } else {
        player.isGrounded = false;
    }

    if (player.isGrounded) {
        const smoothedY = reconcileGroundedEyeY(
            player.position.y,
            player.position.x,
            player.position.z,
            delta,
            { isGrounded: true, velocityY: player.velocity.y }
        );
        if (smoothedY !== player.position.y) {
            player.position.y = smoothedY;
            player.velocity.y = 0;
        }
    }

    if (player.isGrounded && keyStates.jump) {
        player.velocity.y = 8.0;
        player.isGrounded = false;
    }
}

/**
 * Vine attachment detection and handler.
 * Proximity scan uses batchVineInteraction; attach still runs in JS.
 */
export function checkVineAttachment(_camera: THREE.Camera) {
    if (!vineSwings || vineSwings.length === 0) return;

    const playerPos = player.position;
    const playerVel = player.velocity;
    const vineManagers: unknown[] = [];
    const { data, count } = packVines(vineSwings, undefined, vineManagers);
    if (count === 0) return;

    const prox = batchVineInteraction(
        playerPos.x, playerPos.y, playerPos.z,
        playerVel.x, playerVel.y, playerVel.z,
        data, count
    );

    if (!prox.inAttachZone || prox.candidateIndex < 0) return;

    const vineManager = vineManagers[prox.candidateIndex] as any;
    if (vineManager) {
        vineManager.isPlayerAttached = true;
        if (vineManager.swingPlane) {
            vineManager.swingPlane.set(prox.swingPlaneX, 0, prox.swingPlaneZ);
        }
        vineManager.swingAngle = prox.swingAngle;
        vineManager.swingAngularVel = prox.swingAngularVel;
        setActiveVineSwing(vineManager);
    }
}

/**
 * Initialize C++ physics engine (one-time setup).
 */
export async function initCppPhysics(camera: THREE.Camera) {
    initPhysics(camera.position.x, camera.position.y, camera.position.z);
    const validMushrooms = filterValidPhysicsObjects(foliageMushrooms, 'mushroom');
    const validClouds = filterValidPhysicsObjects(foliageClouds, 'cloud');
    const validTrampolines = filterValidPhysicsObjects(foliageTrampolines, 'trampoline');
    const totalCount = validMushrooms.length + validClouds.length + validTrampolines.length;
    console.log(`[Physics] Uploading obstacle batch: ${validMushrooms.length} mushrooms, ${validClouds.length} clouds, ${validTrampolines.length} trampolines (total: ${totalCount})`);
    if (totalCount > 0) {
        const batchData = new Float32Array(totalCount * 9);
        let ptr = 0;
        for (const m of validMushrooms) {
            batchData[ptr++] = 0;
            batchData[ptr++] = m.position.x;
            batchData[ptr++] = m.position.y;
            batchData[ptr++] = m.position.z;
            batchData[ptr++] = 0;
            batchData[ptr++] = (m.userData as any).capHeight || 3;
            batchData[ptr++] = (m.userData as any).stemRadius || 0.5;
            batchData[ptr++] = (m.userData as any).capRadius || 2;
            batchData[ptr++] = (m.userData as any).isTrampoline ? 1 : 0;
        }
        for (const c of validClouds) {
            batchData[ptr++] = 1;
            batchData[ptr++] = c.position.x;
            batchData[ptr++] = c.position.y;
            batchData[ptr++] = c.position.z;
            batchData[ptr++] = (c.scale.x || 1) * 2.0;
            batchData[ptr++] = (c.scale.y || 1) * 0.8;
            batchData[ptr++] = 0;
            batchData[ptr++] = (c.userData as any).tier || 1;
            batchData[ptr++] = 0;
        }
        for (const t of validTrampolines) {
            batchData[ptr++] = 2;
            batchData[ptr++] = t.position.x;
            batchData[ptr++] = t.position.y;
            batchData[ptr++] = t.position.z;
            batchData[ptr++] = (t.userData as any).bounceRadius || 0.5;
            batchData[ptr++] = (t.userData as any).bounceHeight || 0.5;
            batchData[ptr++] = (t.userData as any).bounceForce || 12;
            batchData[ptr++] = 0;
            batchData[ptr++] = 0;
        }
    } else {
        // Core mode or early startup: no physics obstacles yet — safe to skip batch upload.
        console.log('[Physics] No obstacles to batch-upload (Core mode or empty scene); skipping.');
    }
    initDynamicFoliageBridge(500);
    const validCaves = filterValidPhysicsObjects(foliageCaves, 'cave');
    const rawFerns = Array.isArray(arpeggioFernBatcher.logicFerns) ? arpeggioFernBatcher.logicFerns : [];
    const validFerns = filterValidPhysicsObjects(rawFerns, 'arpeggio fern');
    const fernCount = validFerns.length;
    if (rawFerns.length === 0) {
        console.log('[Physics] Arpeggio fern batcher is empty or uninitialized; skipping dynamic foliage collision sync.');
    }
    if (fernCount > 0) {
        uploadCollisionObjects(validCaves as any, validMushrooms as any, validClouds as any, validTrampolines as any, validFerns);
    } else {
        // No arpeggio ferns yet (Core mode): upload only structural collision objects.
        uploadCollisionObjects(validCaves as any, validMushrooms as any, validClouds as any, validTrampolines as any, []);
    }
    console.log('[Physics] Engines Initialized (C++ & ASC).');
}

/**
 * @file region-manager-lod.ts
 * @description LOD transitions and spatial queries for RegionManager
 */

import * as THREE from 'three';
import { CONFIG } from '../core/config.ts';
import { batchDistanceCull, uploadPositionsFlat } from '../utils/wasm-batch.ts';
import { updateFoliageBatcherLOD } from './batcher-lod.ts';
import { distanceToCellSq, cellToBounds, getCellKey } from './region-manager-core.ts';
import { GridCell, CellState, SpatialQueryResult, RegionManager } from './region-manager-core.ts';

const _scratchCells: GridCell[] = [];
const _scratchPositions = new Float32Array(5000 * 4);

/** Generate cells in spiral order for priority loading */
export function getSpiralCells(centerX: number, centerZ: number, radius: number): Array<{ x: number; z: number }> {
    const result: Array<{ x: number; z: number }> = [];
    result.push({ x: centerX, z: centerZ });
    for (let r = 1; r <= radius; r++) {
        for (let x = centerX - r + 1; x <= centerX + r - 1; x++) result.push({ x, z: centerZ - r });
        for (let z = centerZ - r + 1; z <= centerZ + r - 1; z++) result.push({ x: centerX + r, z });
        for (let x = centerX + r - 1; x >= centerX - r + 1; x--) result.push({ x, z: centerZ + r });
        for (let z = centerZ + r - 1; z >= centerZ - r + 1; z--) result.push({ x: centerX - r, z });
        result.push({ x: centerX - r, z: centerZ - r });
        result.push({ x: centerX + r, z: centerZ - r });
        result.push({ x: centerX + r, z: centerZ + r });
        result.push({ x: centerX - r, z: centerZ + r });
    }
    return result;
}

export function getCellsToLoad(
    manager: RegionManager,
    centerX?: number,
    centerZ?: number,
    radius?: number
): GridCell[] {
    const cx = centerX ?? manager.playerCellX;
    const cz = centerZ ?? manager.playerCellZ;
    const r = radius ?? manager.config.loadRadius;

    const result: GridCell[] = [];
    const spiral = getSpiralCells(cx, cz, r);

    for (const { x, z } of spiral) {
        const cell = manager.getCell(x, z);
        if (cell && (cell.state === CellState.UNLOADED || cell.state === CellState.QUEUED)) {
            result.push(cell);
        }
    }
    return result;
}

export function getCellsToUnload(
    manager: RegionManager,
    centerX?: number,
    centerZ?: number,
    radius?: number
): GridCell[] {
    const cx = centerX ?? manager.playerCellX;
    const cz = centerZ ?? manager.playerCellZ;
    const r = radius ?? manager.config.unloadRadius;
    const rSq = r * r;

    const result: GridCell[] = [];
    let count = 0;
    for (const cell of manager.cells.values()) {
        if (cell.state === CellState.LOADED) {
            _scratchCells[count] = cell;
            if (count < 5000) {
                const idx = count * 4;
                _scratchPositions[idx] = cell.x;
                _scratchPositions[idx + 1] = 0;
                _scratchPositions[idx + 2] = cell.z;
                _scratchPositions[idx + 3] = 0;
            }
            count++;
        }
    }

    if (count > 0 && count <= 5000) {
        uploadPositionsFlat(_scratchPositions, count);
        const { flags } = batchDistanceCull(cx, 0, cz, r, count);
        if (flags) {
            for (let i = 0; i < count; i++) {
                if (flags[i] === 0.0) {
                    result.push(_scratchCells[i]);
                }
            }
            for (let i = 0; i < count; i++) _scratchCells[i] = null as any;
            return result;
        }
    }

    for (let i = 0; i < count; i++) {
        const cell = _scratchCells[i];
        const dx = cell.x - cx;
        const dz = cell.z - cz;
        if (dx * dx + dz * dz > rSq) {
            result.push(cell);
        }
        _scratchCells[i] = null as any;
    }

    return result;
}

export function getCellsInRadius(centerX: number, centerZ: number, radius: number): string[] {
    const keys: string[] = [];
    for (let dx = -radius; dx <= radius; dx++) {
        for (let dz = -radius; dz <= radius; dz++) {
            if (dx * dx + dz * dz <= radius * radius) {
                keys.push(getCellKey(centerX + dx, centerZ + dz));
            }
        }
    }
    return keys;
}

export function getDistantCells(manager: RegionManager, minRadius: number): GridCell[] {
    const result: GridCell[] = [];
    const minRadiusSq = minRadius * minRadius;
    let count = 0;

    for (const cell of manager.cells.values()) {
        if (cell.state === CellState.LOADED) {
            _scratchCells[count] = cell;
            if (count < 5000) {
                const idx = count * 4;
                _scratchPositions[idx] = cell.x;
                _scratchPositions[idx + 1] = 0;
                _scratchPositions[idx + 2] = cell.z;
                _scratchPositions[idx + 3] = 0;
            }
            count++;
        }
    }

    if (count > 0 && count <= 5000) {
        uploadPositionsFlat(_scratchPositions, count);
        const { flags } = batchDistanceCull(manager.playerCellX, 0, manager.playerCellZ, minRadius, count);
        if (flags) {
            for (let i = 0; i < count; i++) {
                if (flags[i] === 0.0) {
                    result.push(_scratchCells[i]);
                }
            }
        } else {
            for (let i = 0; i < count; i++) {
                const cell = _scratchCells[i];
                const dx = cell.x - manager.playerCellX;
                const dz = cell.z - manager.playerCellZ;
                if (dx * dx + dz * dz >= minRadiusSq) {
                    result.push(cell);
                }
            }
        }
    } else {
        for (let i = 0; i < count; i++) {
            const cell = _scratchCells[i];
            const dx = cell.x - manager.playerCellX;
            const dz = cell.z - manager.playerCellZ;
            if (dx * dx + dz * dz >= minRadiusSq) {
                result.push(cell);
            }
        }
    }

    for (let i = 0; i < count; i++) _scratchCells[i] = null as any;

    result.sort((a, b) => {
        const dxA = a.x - manager.playerCellX;
        const dzA = a.z - manager.playerCellZ;
        const dxB = b.x - manager.playerCellX;
        const dzB = b.z - manager.playerCellZ;
        return (dxB * dxB + dzB * dzB) - (dxA * dxA + dzA * dzA);
    });

    return result;
}

export function queryBoundingBox(manager: RegionManager, minX: number, maxX: number, minZ: number, maxZ: number): GridCell[] {
    const minCellX = Math.floor(minX / manager.config.cellSize);
    const minCellZ = Math.floor(minZ / manager.config.cellSize);
    const maxCellX = Math.floor(maxX / manager.config.cellSize);
    const maxCellZ = Math.floor(maxZ / manager.config.cellSize);

    const result: GridCell[] = [];
    for (let x = minCellX; x <= maxCellX; x++) {
        for (let z = minCellZ; z <= maxCellZ; z++) {
            const cell = manager.getCell(x, z);
            if (cell) result.push(cell);
        }
    }
    return result;
}

export function queryCircle(manager: RegionManager, centerX: number, centerZ: number, radius: number): GridCell[] {
    const minCellX = Math.floor((centerX - radius) / manager.config.cellSize);
    const maxCellX = Math.floor((centerX + radius) / manager.config.cellSize);
    const minCellZ = Math.floor((centerZ - radius) / manager.config.cellSize);
    const maxCellZ = Math.floor((centerZ + radius) / manager.config.cellSize);

    const result: GridCell[] = [];
    const radiusSq = radius * radius;

    for (let x = minCellX; x <= maxCellX; x++) {
        for (let z = minCellZ; z <= maxCellZ; z++) {
            const bounds = cellToBounds(x, z, manager.config.cellSize);
            const dx = Math.max(bounds.minX - centerX, 0, centerX - bounds.maxX);
            const dz = Math.max(bounds.minZ - centerZ, 0, centerZ - bounds.maxZ);

            if (dx * dx + dz * dz <= radiusSq) {
                const cell = manager.getCell(x, z);
                if (cell) result.push(cell);
            }
        }
    }
    return result;
}

export function queryDetailed(
    manager: RegionManager,
    options: { centerX: number; centerZ: number; radius: number; onlyLoaded?: boolean }
): SpatialQueryResult {
    const minCellX = Math.floor((options.centerX - options.radius) / manager.config.cellSize);
    const maxCellX = Math.floor((options.centerX + options.radius) / manager.config.cellSize);
    const minCellZ = Math.floor((options.centerZ - options.radius) / manager.config.cellSize);
    const maxCellZ = Math.floor((options.centerZ + options.radius) / manager.config.cellSize);

    _scratchCells.length = 0;
    const radiusSq = options.radius * options.radius;

    for (let x = minCellX; x <= maxCellX; x++) {
        for (let z = minCellZ; z <= maxCellZ; z++) {
            const bounds = cellToBounds(x, z, manager.config.cellSize);
            const dx = Math.max(bounds.minX - options.centerX, 0, options.centerX - bounds.maxX);
            const dz = Math.max(bounds.minZ - options.centerZ, 0, options.centerZ - bounds.maxZ);

            if (dx * dx + dz * dz <= radiusSq) {
                const cell = manager.getCell(x, z);
                if (cell && (!options.onlyLoaded || cell.state === CellState.LOADED)) {
                    _scratchCells.push(cell);
                }
            }
        }
    }

    let totalAssets = 0;
    for (const cell of _scratchCells) {
        totalAssets += cell.assetIds.length;
    }

    return {
        cells: _scratchCells.slice(),
        totalAssets,
        estimatedMemory: totalAssets * 1024 * 1024
    };
}

export function getLODLevelForCell(manager: RegionManager, cell: GridCell): number {
    const distanceSq = distanceToCellSq(
        manager.playerWorldX,
        manager.playerWorldZ,
        cell.x,
        cell.z,
        manager.config.cellSize
    );

    const radii = getFoliageLodRadiiForRegion();

    for (let i = 0; i < radii.length; i++) {
        if (distanceSq <= radii[i] * radii[i]) {
            return i;
        }
    }

    return radii.length - 1;
}

/** Align region streaming LOD radii with CONFIG.foliage.lod batcher thresholds */
export function getFoliageLodRadiiForRegion(): number[] {
    const lod = CONFIG.foliage?.lod;
    if (!lod) return [120, 365, 480, 640];
    return [
        lod.heroMax ?? 120,
        lod.midMax ?? 365,
        lod.farCull ?? 480,
        (lod.farCull ?? 480) + 160
    ];
}

export function syncRegionLodConfig(manager: RegionManager): void {
    manager.config.lodRadii = getFoliageLodRadiiForRegion();
}

export function updateRegionFoliageLod(
    manager: RegionManager,
    camera: THREE.Camera,
    delta: number
): void {
    manager.playerWorldX = camera.position.x;
    manager.playerWorldZ = camera.position.z;
    updateFoliageBatcherLOD(camera, delta);
}

export class CellLoader {
    private loadingCells: Map<string, {
        cell: GridCell;
        loadedAssets: number;
        totalAssets: number;
        startTime: number;
    }> = new Map();

    startLoading(cell: GridCell): void {
        cell.state = CellState.LOADING;
        this.loadingCells.set(cell.key, {
            cell,
            loadedAssets: 0,
            totalAssets: cell.assetIds.length,
            startTime: performance.now()
        });
    }

    markAssetLoaded(cellKey: string, assetId: string): void {
        const loading = this.loadingCells.get(cellKey);
        if (!loading) return;
        loading.loadedAssets++;
        loading.cell.lastAccessed = performance.now();
    }

    isComplete(cellKey: string): boolean {
        const loading = this.loadingCells.get(cellKey);
        return loading ? loading.loadedAssets >= loading.totalAssets : false;
    }

    getProgress(cellKey: string): number {
        const loading = this.loadingCells.get(cellKey);
        return loading ? loading.loadedAssets / Math.max(1, loading.totalAssets) : 0;
    }

    finishLoading(cellKey: string): number {
        const loading = this.loadingCells.get(cellKey);
        if (!loading) return 0;
        const loadTime = performance.now() - loading.startTime;
        this.loadingCells.delete(cellKey);
        return loadTime;
    }

    cancelLoading(cellKey: string): void {
        this.loadingCells.delete(cellKey);
    }

    getLoadingCells(): GridCell[] {
        _scratchCells.length = 0;
        for (const loadingInfo of this.loadingCells.values()) {
            _scratchCells.push(loadingInfo.cell);
        }
        return _scratchCells;
    }
}

/**
 * Save system integration for Candy World.
 * Wires SaveSystem gather/apply hooks to live game state.
 */

import { FEATURE_FLAGS } from '../core/config.ts';
import { awakenedPersistence } from './awakened-persistence-api.ts';
import { discoverySystem } from './discovery.ts';
import { player } from './physics/index.ts';
import {
    saveSystem,
    createPlayerSaveData,
    createWorldSaveData,
    createProgressSaveData,
    type SaveData,
} from './save-system/index.ts';
import { unlockSystem } from './unlocks.ts';

type SaveSystemInternals = {
    gatherPlayerData: () => SaveData['player'];
    gatherWorldData: () => SaveData['world'];
    gatherProgressData: (playtime: number) => SaveData['progress'];
};

type UnlockSystemSnapshot = {
    inventory: Record<string, number>;
    unlocks: Set<string>;
};

/**
 * Connect save system to game state providers. Call once during boot.
 */
export function initializeSaveSystemIntegration(): void {
    const internal = saveSystem as unknown as SaveSystemInternals;

    internal.gatherPlayerData = gatherPlayerData;
    internal.gatherWorldData = gatherWorldData;
    internal.gatherProgressData = gatherProgressData;

    saveSystem.onSaveComplete = () => {
        console.log('[Save] Game saved successfully');
    };

    saveSystem.onLoadComplete = (data) => {
        console.log('[Save] Game loaded:', data.metadata.slotName);
        applyLoadedData(data);
    };

    setupEventSaves();
    console.log('[Save] Save system integration initialized');
}

function gatherPlayerData(): SaveData['player'] {
    return createPlayerSaveData(
        { x: player.position.x, y: player.position.y, z: player.position.z },
        { x: 0, y: 0, z: 0 },
        { x: player.velocity.x, y: player.velocity.y, z: player.velocity.z },
        {
            energy: player.energy,
            maxEnergy: player.maxEnergy,
            currentState: player.currentState,
            airJumpsLeft: player.airJumpsLeft,
            hasShield: player.hasShield,
            isPhasing: player.isPhasing,
            isInvisible: player.isInvisible,
        }
    );
}

function gatherWorldData(): SaveData['world'] {
    return createWorldSaveData(
        0.5,
        { state: 'clear', intensity: 0, stormCharge: 0 },
        { season: 'spring', progress: 0, moonPhase: 0 }
    );
}

function gatherProgressData(playtime: number): SaveData['progress'] {
    const discoveries = discoverySystem.getDiscoveredIds();
    const unlocksInternal = unlockSystem as unknown as UnlockSystemSnapshot;

    return {
        ...createProgressSaveData(
            discoveries,
            { ...unlocksInternal.inventory },
            [],
            Array.from(unlocksInternal.unlocks),
            playtime
        ),
        awakenedFlora: FEATURE_FLAGS.awakenedPersistence
            ? awakenedPersistence.serialize()
            : undefined,
    };
}

export function applyLoadedData(data: SaveData): void {
    if (data.player.position) {
        player.position.set(data.player.position.x, data.player.position.y, data.player.position.z);
    }
    if (data.player.velocity) {
        player.velocity.set(data.player.velocity.x, data.player.velocity.y, data.player.velocity.z);
    }

    player.energy = data.player.energy;
    player.maxEnergy = data.player.maxEnergy;
    player.currentState = data.player.currentState;
    player.airJumpsLeft = data.player.airJumpsLeft;
    player.hasShield = data.player.hasShield;
    player.isPhasing = data.player.isPhasing;
    player.isInvisible = data.player.isInvisible;

    const unlocksInternal = unlockSystem as unknown as UnlockSystemSnapshot;
    unlocksInternal.unlocks.clear();
    for (const id of data.progress.unlocks) {
        unlocksInternal.unlocks.add(id);
    }

    // ⚡ OPTIMIZATION: Replaced Object.keys() with fast zero-allocation for..in loop to prevent GC spikes
    for (const key in unlocksInternal.inventory) {
        delete unlocksInternal.inventory[key];
    }
    Object.assign(unlocksInternal.inventory, data.progress.inventory);

    if (FEATURE_FLAGS.awakenedPersistence) {
        awakenedPersistence.deserialize(data.progress.awakenedFlora ?? []);
        awakenedPersistence.applyLoadedStatesToBatchers();
    }

    saveSystem.updateSettings(data.settings);
}

function setupEventSaves(): void {
    const originalDiscover = discoverySystem.discover.bind(discoverySystem);
    discoverySystem.discover = (id: string, displayName: string, icon?: string) => {
        const result = originalDiscover(id, displayName, icon);
        if (result) saveSystem.triggerEventSave('discovery');
        return result;
    };

    const originalHarvest = unlockSystem.harvest.bind(unlockSystem);
    unlockSystem.harvest = (itemId: string, amount?: number, displayName?: string) => {
        originalHarvest(itemId, amount, displayName);
        saveSystem.triggerEventSave('harvest');
    };
}

if (typeof window !== 'undefined') {
    (window as unknown as Record<string, unknown>).saveIntegration = {
        initialize: initializeSaveSystemIntegration,
        applyData: applyLoadedData,
    };
}

