import * as THREE from 'three';

// --- Constants ---
const DEFAULT_FRAME_TIME = 0.016; // 60 FPS (1/60 second)

// --- Type Definitions ---

export interface WeatherState {
    state: 'clear' | 'rain' | 'storm';
    intensity: number;
    stormCharge: number;
}

export interface CelestialState {
    sunIntensity: number;
    moonIntensity: number;
    sunAngle: number;
    isDaytime: boolean;
    isNight: boolean;
}

export interface SeasonalState {
    season: string;
    seasonProgress: number;
    moonPhase: number;
}

export interface LightLevelData {
    sunPower: number;
    moonPower: number;
    globalLight: number;
}

export interface FavorabilityData {
    floraFavorability: number;
    fungiFavorability: number;
    lanternFavorability: number;
}

export interface WeatherBias {
    biasState: 'clear' | 'rain' | 'storm';
    biasIntensity: number;
    type: string;
}

// --- Core Weather Functions ---

/**
 * Calculate global light level based on celestial and weather state
 * Hot path - called every frame
 */
export function calculateGlobalLightLevel(
    celestial: CelestialState,
    seasonal: SeasonalState,
    cloudDensity: number
): LightLevelData {
    const sunPower = celestial.sunIntensity * (1.0 - cloudDensity * 0.7);
    const moonPower = celestial.moonIntensity * 0.3;
    const globalLight = Math.max(0, sunPower + moonPower);

    return {
        sunPower,
        moonPower,
        globalLight
    };
}

/**
 * Calculate flora/fungi favorability based on conditions
 * Used for growth rate calculations
 */
export function calculateFavorability(
    globalLight: number,
    intensity: number,
    stormCharge: number,
    weatherState: 'clear' | 'rain' | 'storm'
): FavorabilityData {
    const moisture = intensity + (stormCharge * 0.5);

    let floraFavorability = globalLight * (0.5 + moisture);
    if (moisture > 0.9) {
        floraFavorability *= 0.5;
    }

    const fungiFavorability = (1.0 - globalLight) * (0.2 + moisture * 1.5);
    const lanternFavorability = (weatherState === 'storm' ? 1.0 : 0.0) + 
                                (1.0 - globalLight) * 0.2;

    return {
        floraFavorability,
        fungiFavorability,
        lanternFavorability
    };
}

/**
 * Calculate mushroom growth rate based on weather
 * Hot path - affects all mushrooms every frame
 */
export function calculateMushroomGrowthRate(
    weatherState: 'clear' | 'rain' | 'storm',
    bassIntensity: number,
    sunPower: number,
    fungiFavorability: number
): number {
    const isRaining = weatherState === 'rain' || weatherState === 'storm';

    if (isRaining) {
        // Grow: Base rate + bass boost
        const baseRate = 0.01;
        const bassBoost = bassIntensity * 0.02;
        return baseRate + bassBoost;
    } else {
        // Shrink if sunny
        if (sunPower > 0.3) {
            return -0.005; // Slow shrink
        }
    }

    return 0;
}

/**
 * Update weather state based on audio and bias
 * State machine logic for weather transitions
 */
export function calculateWeatherStateTransition(
    currentState: 'clear' | 'rain' | 'storm',
    currentIntensity: number,
    currentStormCharge: number,
    bassIntensity: number,
    melodyVol: number,
    groove: number,
    weatherBias: WeatherBias | null,
    transitionSpeed: number
): WeatherState {
    let targetIntensity = 0;
    let newState = currentState;
    let newStormCharge = currentStormCharge;

    // Apply Cycle Bias if provided
    if (weatherBias && weatherBias.biasIntensity > 0.1) {
        if (weatherBias.biasState === 'storm') {
            targetIntensity = 0.8 * weatherBias.biasIntensity;
            newStormCharge += 0.01 * weatherBias.biasIntensity;
        } else if (weatherBias.biasState === 'rain') {
            targetIntensity = 0.5 * weatherBias.biasIntensity;
        } else {
            targetIntensity = 0.0;
        }
    } else {
        // Audio-Driven Logic
        if (bassIntensity > 0.6 && groove > 0.5) {
            targetIntensity = 0.5 + (bassIntensity * 0.5);
            newStormCharge += 0.02;
        } else if (melodyVol > 0.4) {
            targetIntensity = 0.3;
        } else {
            targetIntensity = 0.0;
        }
    }

    // Storm Charge Decay
    newStormCharge = Math.max(0, newStormCharge - 0.005);
    newStormCharge = Math.min(1.0, newStormCharge);

    // State Transitions
    if (newStormCharge > 0.8) {
        newState = 'storm';
        targetIntensity = Math.max(targetIntensity, 0.8);
    } else if (targetIntensity > 0.3) {
        newState = 'rain';
    } else {
        newState = 'clear';
    }

    // Smooth intensity transition
    const newIntensity = currentIntensity + 
        (targetIntensity - currentIntensity) * transitionSpeed;

    return {
        state: newState,
        intensity: newIntensity,
        stormCharge: newStormCharge
    };
}

/**
 * Calculate fog density based on weather and audio
 * Used for crescendo fog effect
 */
export function calculateFogDensity(
    baseFogNear: number,
    baseFogFar: number,
    weatherIntensity: number,
    audioVolume: number,
    cloudDensity: number
): { near: number; far: number } {
    // Crescendo Fog Logic
    const fogFactor = audioVolume * 0.4 * cloudDensity;
    const weatherFogFactor = weatherIntensity * 0.3;

    const totalFogFactor = fogFactor + weatherFogFactor;

    const near = baseFogNear * (1.0 - totalFogFactor * 0.5);
    const far = baseFogFar * (1.0 - totalFogFactor * 0.4);

    return { near, far };
}

/**
 * Calculate wind speed and direction
 * Used for environmental effects
 */
export function calculateWindParameters(
    currentWindSpeed: number,
    targetWindSpeed: number,
    weatherState: 'clear' | 'rain' | 'storm',
    weatherIntensity: number,
    delta: number
): { windSpeed: number; windTargetSpeed: number } {
    let newTargetWindSpeed = targetWindSpeed;

    if (weatherState === 'storm') {
        newTargetWindSpeed = 2.0 + weatherIntensity;
    } else if (weatherState === 'rain') {
        newTargetWindSpeed = 0.5 + weatherIntensity * 0.5;
    } else {
        newTargetWindSpeed = 0.1;
    }

    const newWindSpeed = currentWindSpeed + 
        (newTargetWindSpeed - currentWindSpeed) * delta * 2.0;

    return {
        windSpeed: newWindSpeed,
        windTargetSpeed: newTargetWindSpeed
    };
}

/**
 * Calculate ground water level changes
 * Affects cave flooding
 */
export function calculateGroundWaterLevel(
    currentLevel: number,
    weatherState: 'clear' | 'rain' | 'storm',
    delta: number = DEFAULT_FRAME_TIME
): number {
    let newLevel = currentLevel;

    if (weatherState === 'rain') {
        newLevel = Math.min(1.0, newLevel + 0.0005);
    } else if (weatherState === 'storm') {
        newLevel = Math.min(1.0, newLevel + 0.0015);
    } else {
        newLevel = Math.max(0.0, newLevel - 0.0003);
    }

    return newLevel;
}

/**
 * Calculate rainbow timer and opacity
 * Appears after storm clears
 */
export function calculateRainbowOpacity(
    rainbowTimer: number,
    delta: number = DEFAULT_FRAME_TIME
): { timer: number; opacity: number } {
    let newTimer = rainbowTimer;
    let opacity = 0.0;

    if (rainbowTimer > 0) {
        newTimer -= delta;
        opacity = 1.0;

        // Fade in
        if (rainbowTimer > 40.0) {
            opacity = (45.0 - rainbowTimer) / 5.0;
        }
        // Fade out
        else if (rainbowTimer < 5.0) {
            opacity = rainbowTimer / 5.0;
        }

        opacity *= 0.6;
    }

    return { timer: Math.max(0, newTimer), opacity };
}

// src/systems/weather/weather-atmosphere.ts
// Atmospheric effects: fog, lighting, wind, twilight, lightning

import * as THREE from 'three';
import type { VisualState } from '../../audio/audio-system.ts';
import { CYCLE_DURATION, DURATION_SUNRISE, DURATION_DAY, DURATION_SUNSET, DURATION_PRE_DAWN, CONFIG } from '../../core/config.ts';
import { chargeBerries, shakeBerriesLoose, updateGlobalBerryScale } from '../../foliage/berries.ts';
import { uSkyDarkness, uTwilight, uCrescendoFogDensity, uFogNear, uFogFar } from '../../foliage/sky.ts';
import { syncFogTelemetryFromScene } from '../atmosphere-fog.ts';
import { WeatherState } from '../weather-types.ts';
import type { WeatherSystem } from './weather.ts';


// Scratch objects
const _scratchBlack = new THREE.Color(0x000000);

export class AtmosphereManager {
    private weatherSystem: WeatherSystem;

    constructor(weatherSystem: WeatherSystem) {
        this.weatherSystem = weatherSystem;
    }

    /**
     * Get global light level based on celestial and seasonal state
     */
    getGlobalLightLevel(celestial: any, seasonal: any): number {
        const sun = celestial.sunIntensity * (seasonal ? seasonal.sunInclination : 1.0);
        const moon = celestial.moonIntensity * (seasonal ? seasonal.moonPhase : 1.0) * 0.25;
        const stars = 0.05;
        const cloudCover = this.weatherSystem.cloudDensity;
        const totalLight = (sun + moon + stars) * (1.0 - (cloudCover * 0.8));
        return Math.min(1.0, totalLight);
    }

    /**
     * Returns 0.0 (Day), ramp to 1.0 (Night), ramp down to 0.0 (Day)
     */
    getTwilightGlowIntensity(cyclePos: number): number {
        const sunsetStart = DURATION_SUNRISE + DURATION_DAY;
        const sunsetEnd = sunsetStart + DURATION_SUNSET;

        const twilightStart = sunsetStart - 30; // Start glowing 30s before sunset starts
        const nightStart = sunsetEnd;

        // Simple logic:
        // 1. If Day (Sunrise -> Sunset-30s): 0
        // 2. If Transition (Sunset-30s -> SunsetEnd): Ramp 0->1
        // 3. If Night (SunsetEnd -> PreDawn): 1
        // 4. If Dawn (PreDawn -> Sunrise): Ramp 1->0

        if (cyclePos < twilightStart && cyclePos > DURATION_SUNRISE) return 0.0; // Day

        if (cyclePos >= twilightStart && cyclePos < nightStart) {
            // Ramp Up
            const duration = nightStart - twilightStart;
            return (cyclePos - twilightStart) / duration;
        }

        if (cyclePos >= nightStart && cyclePos < CYCLE_DURATION - DURATION_SUNRISE) {
            // Night (roughly) - Check for pre-dawn fade
            const dawnStart = CYCLE_DURATION - DURATION_PRE_DAWN;

            if (cyclePos >= dawnStart) {
                // Ramp Down
                const progress = (cyclePos - dawnStart) / DURATION_PRE_DAWN;
                return 1.0 - progress;
            }

            return 1.0; // Full Night Glow
        }

        // Sunrise buffer
        if (cyclePos < DURATION_SUNRISE) {
            return 0.0;
        }

        return 0.0;
    }

    /**
     * Simple helper for other systems
     */
    isNight(lastTwilightProgress: number): boolean {
        return lastTwilightProgress > 0.5;
    }

    /**
     * Apply darkness logic based on celestial state
     */
    applyDarknessLogic(celestial: any, moonPhase: number): void {
        const scene = this.weatherSystem.scene;
        const cloudDensity = this.weatherSystem.cloudDensity;

        const nightFactor = celestial.moonIntensity;
        const densityFactor = cloudDensity;
        const moonDarkness = 1.0 - (moonPhase || 0) * 0.5;
        const darkness = nightFactor * densityFactor * moonDarkness * 0.95;

        if (scene.fog && (scene.fog as THREE.Fog).color) {
            (scene.fog as THREE.Fog).color.lerp(_scratchBlack, darkness);
        }
        if (uSkyDarkness) uSkyDarkness.value = darkness;
        this.weatherSystem.darknessFactor = darkness;
    }

    /**
     * Update fog based on weather state and audio
     */
    updateFog(audioData: VisualState, state: WeatherState, intensity: number, darknessFactor: number, baseFogNear: number, baseFogFar: number, weatherType: string, fog: THREE.Fog | THREE.FogExp2 | null, deltaTime = 0.016): void {
        if (!fog) return;

        let fogMultiplier = 1.0;
        let nearModifier = 1.0;

        switch (state) {
            case WeatherState.RAIN: fogMultiplier = 0.8; break;
            case WeatherState.STORM: fogMultiplier = 0.6; break;
            default: fogMultiplier = 1.0;
        }

        // Special Fog Types (Time-of-Day)
        if (weatherType === 'mist') {
            // Mist is dense but bright. Pull 'near' closer.
            nearModifier = 0.3;
        } else if (weatherType === 'drizzle') {
             // Drizzle slightly closer
             nearModifier = 0.8;
        }

        let crescendoFactor = 0;
        if (uCrescendoFogDensity) {
            // Atmosphere reactivity owns uCrescendoFogDensity — read, do not overwrite.
            crescendoFactor = uCrescendoFogDensity.value as number;
        } else if (audioData && audioData.channelData && audioData.channelData.length > 0) {
            let totalVolume = 0;
            for (let i = 0; i < audioData.channelData.length; i++) {
                totalVolume += audioData.channelData[i].volume;
            }
            const averageVolume = totalVolume / audioData.channelData.length;
            crescendoFactor = Math.min(1.0, averageVolume * 0.5);
        }

        const weatherVisibility = (1.0 - intensity * (1.0 - fogMultiplier));
        const darknessVisibility = (1.0 - (darknessFactor || 0) * 0.7);
        const crescendoVisibility = (1.0 - crescendoFactor);

        const totalVisibility = weatherVisibility * darknessVisibility * crescendoVisibility;

        const targetNear = (baseFogNear * nearModifier) * totalVisibility;
        const targetFar = baseFogFar * totalVisibility;

        const lerpK = 1.0 - Math.exp(-CONFIG.atmosphere.fog.lerpSpeed * deltaTime);

        // Update TSL Fog Global Limits (WebGPU fogNode reads these)
        if (uFogNear && uFogFar) {
            const curNear = uFogNear.value as number;
            const curFar = uFogFar.value as number;
            uFogNear.value = curNear + (targetNear - curNear) * lerpK;
            uFogFar.value = curFar + (targetFar - curFar) * lerpK;
        }

        // Keep standard THREE.Fog fallback updated (WebGL path)
        if (fog instanceof THREE.Fog) {
            fog.near += (targetNear - fog.near) * lerpK;
            fog.far += (targetFar - fog.far) * lerpK;
        }

        syncFogTelemetryFromScene(fog instanceof THREE.Fog ? fog : null);
    }

    /**
     * Update berry seasonal size based on cycle position
     */
    updateBerrySeasonalSize(cyclePos: number): void {
        const SUNRISE = 60, DAY = 420, SUNSET = 60, DUSK = 180, DEEP = 120, PREDAWN = 120;
        let phase = 'day';
        let phaseProgress = 0;

        if (cyclePos < SUNRISE) {
            phase = 'sunrise';
            phaseProgress = cyclePos / SUNRISE;
        } else if (cyclePos < SUNRISE + DAY) {
            phase = 'day';
            phaseProgress = (cyclePos - SUNRISE) / DAY;
        } else if (cyclePos < SUNRISE + DAY + SUNSET) {
            phase = 'sunset';
            phaseProgress = (cyclePos - SUNRISE - DAY) / SUNSET;
        } else if (cyclePos < SUNRISE + DAY + SUNSET + DUSK) {
            phase = 'dusk';
            phaseProgress = (cyclePos - SUNRISE - DAY - SUNSET) / DUSK;
        } else if (cyclePos < SUNRISE + DAY + SUNSET + DUSK + DEEP) {
            phase = 'deepNight';
            phaseProgress = (cyclePos - SUNRISE - DAY - SUNSET - DUSK) / DEEP;
        } else {
            phase = 'preDawn';
            phaseProgress = (cyclePos - SUNRISE - DAY - SUNSET - DUSK - DEEP) / PREDAWN;
        }

        // Update global uniform that all berry shaders read
        updateGlobalBerryScale(phase, phaseProgress);
    }

    /**
     * Update wind physics and direction
     */
    updateWind(
        time: number,
        audioData: VisualState,
        celestial: any,
        windDirection: THREE.Vector3,
        windSpeed: number,
        windTargetSpeed: number,
        trackedMushrooms: any[]
    ): { windDirection: THREE.Vector3; windSpeed: number; windTargetSpeed: number } {
        const channels = audioData.channelData || [];
        const highFreqVol = (channels[3] as any)?.volume || 0;
        const melodyVol = (channels[2] as any)?.volume || 0;

        windTargetSpeed = Math.max(highFreqVol, melodyVol * 0.5);
        windSpeed += (windTargetSpeed - windSpeed) * 0.02;

        const rotSpeed = (audioData.beatPhase || 0) * 0.001;

        // Apply rotation around Y axis
        const x = windDirection.x;
        const z = windDirection.z;
        const cos = Math.cos(rotSpeed);
        const sin = Math.sin(rotSpeed);
        windDirection.x = x * cos - z * sin;
        windDirection.z = x * sin + z * cos;

        const dayProgress = (time % CYCLE_DURATION) / CYCLE_DURATION;
        const sunAngle = dayProgress * Math.PI * 2;
        const sunDirX = Math.cos(sunAngle);
        const sunDirY = Math.sin(sunAngle);

        // Lerp towards celestial force (opposite sun direction)
        windDirection.x += (sunDirX * -1 - windDirection.x) * 0.1;
        windDirection.y += (sunDirY * -1 - windDirection.y) * 0.1;

        // Calculate giant mushroom attraction
        let giantsX = 0, giantsZ = 0, giantsCount = 0;
        for (let i = 0, len = trackedMushrooms.length; i < len; i++) {
            const m = trackedMushrooms[i];
            if (m.userData.size === 'giant') {
                giantsX += m.position.x;
                giantsZ += m.position.z;
                giantsCount++;
            }
        }

        if (giantsCount > 0) {
            const centerX = giantsX / giantsCount;
            const centerZ = giantsZ / giantsCount;
            const len = Math.sqrt(centerX * centerX + centerZ * centerZ) || 1;
            const attractX = centerX / len;
            const attractZ = centerZ / len;

            windDirection.x += (attractX - windDirection.x) * 0.05;
            windDirection.z += (attractZ - windDirection.z) * 0.05;
        }

        // Normalize
        const dirLen = Math.sqrt(windDirection.x * windDirection.x + windDirection.y * windDirection.y + windDirection.z * windDirection.z) || 1;
        windDirection.x /= dirLen;
        windDirection.y /= dirLen;
        windDirection.z /= dirLen;

        return { windDirection, windSpeed, windTargetSpeed };
    }

    /**
     * Update lightning effects
     */
    updateLightning(
        time: number,
        bassIntensity: number,
        lightningTimer: number,
        lightningActive: boolean,
        lightningLight: THREE.PointLight
    ): { lightningTimer: number; lightningActive: boolean } {
        lightningTimer -= 0.016;

        if (bassIntensity > 0.8 && lightningTimer <= 0 && Math.random() > 0.7) {
            lightningActive = true;
            lightningTimer = 0.5 + Math.random() * 1.0;
            lightningLight.intensity = 5 + Math.random() * 5;
            lightningLight.position.set(
                (Math.random() - 0.5) * 60,
                40 + Math.random() * 20,
                (Math.random() - 0.5) * 60
            );
        }

        if (lightningActive) {
            lightningLight.intensity *= 0.85;
            if (lightningLight.intensity < 0.1) {
                lightningActive = false;
                lightningLight.intensity = 0;
            }
        }

        return { lightningTimer, lightningActive };
    }

    /**
     * Charge berry glow during storms
     */
    chargeBerryGlow(bassIntensity: number, trackedTrees: any[], trackedShrubs: any[]): void {
        const chargeAmount = bassIntensity * 0.05;

        for (let i = 0, len = trackedTrees.length; i < len; i++) {
            const tree = trackedTrees[i];
            if (tree.userData.berries) chargeBerries(tree.userData.berries, chargeAmount);
        }
        for (let i = 0, len = trackedShrubs.length; i < len; i++) {
            const shrub = trackedShrubs[i];
            if (shrub.userData.berries) chargeBerries(shrub.userData.berries, chargeAmount);
        }

        if (bassIntensity > 0.6) {
            for (let i = 0, len = trackedTrees.length; i < len; i++) {
                const tree = trackedTrees[i];
                if (tree.userData.berries) shakeBerriesLoose(tree.userData.berries, bassIntensity);
            }
            for (let i = 0, len = trackedShrubs.length; i < len; i++) {
                const shrub = trackedShrubs[i];
                if (shrub.userData.berries) shakeBerriesLoose(shrub.userData.berries, bassIntensity);
            }
        }
    }
}

// src/systems/weather/weather-ecosystem.ts
// Ecosystem management: cloud-mushroom interactions, spawning, waterfalls

import * as THREE from 'three';
import { updateCloudAttraction, isCloudOverTarget } from '../../foliage/clouds.ts';
import { flowerBatcher } from '../../foliage/flower-batcher.ts';
import { createLanternFlower } from '../../foliage/flowers.ts';
import { cleanupReactivity } from '../../foliage/foliage-reactivity.ts';
import { mushroomBatcher } from '../../foliage/mushroom-batcher.ts';
import { createMushroom } from '../../foliage/mushrooms.ts';
import { replaceMushroomWithGiant } from '../../foliage/mushrooms.ts';
import { FoliageGrowthOptions } from '../../foliage/types.ts';
import { waterfallBatcher } from '../../foliage/waterfall-batcher.ts';
import { safeRemoveAndDispose } from '../../utils/dispose-utils.ts';
import { getGroundHeight, uploadMushroomSpecs, batchMushroomSpawnCandidates, readSpawnCandidates, isWasmReady } from '../../utils/wasm-loader.ts';
import { spawnNearbyFoliage } from '../../world/generation.ts';
import { foliageClouds } from '../../world/state.ts';
import { cpuAnimatedFoliage } from '../../world/state.ts';
import { musicReactivitySystem } from '../music-reactivity.ts';
import type { WeatherSystem } from './weather.ts';

// Scratch objects for optimization
const _scratchSunDir = new THREE.Vector3();
const _scratchWaterfallPos = new THREE.Vector3();
const _scratchMPos = new THREE.Vector3();
const _scratchFPos = new THREE.Vector3();
const _lastSpawnTimes = new Map<string, number>();

export class EcosystemManager {
    private weatherSystem: WeatherSystem;
    private _claimedMushroomsScratch: Set<string>;
    private _lastSpawnCheck: number = 0;
    private _spawnCapPerFrame: number = 3;
    private _spawnThrottle: number = 0.5;

    constructor(weatherSystem: WeatherSystem) {
        this.weatherSystem = weatherSystem;
        this._claimedMushroomsScratch = new Set();
    }

    /**
     * Main ecosystem update loop - handles cloud-mushroom behavior
     */
    updateEcosystem(dt: number): void {
        const trackedMushrooms = this.weatherSystem.trackedMushrooms;

        // Only run if we have active entities
        if (!foliageClouds || foliageClouds.length === 0 || trackedMushrooms.length === 0) return;

        // TRACKING SET: Prevents multiple clouds from picking the same mushroom
        // Use scratch set + clear() instead of allocating new Set() every frame
        const claimedMushrooms = this._claimedMushroomsScratch;
        claimedMushrooms.clear();

        // 1. Register existing locks first
        for (let i = 0, len = foliageClouds.length; i < len; i++) {
            const cloud: any = foliageClouds[i];
            if (cloud.userData.targetMushroom) {
                claimedMushrooms.add(cloud.userData.targetMushroom.uuid);
            }
        }

        // 2. Process Clouds
        for (let i = 0, len = foliageClouds.length; i < len; i++) {
            const cloud: any = foliageClouds[i];
            // Skip dead/falling clouds
            if (cloud.userData.isFalling) {
                // If it had a target, we implicitly release it by not moving towards it
                cloud.userData.targetMushroom = null;
                continue;
            }

            // A. Find Target (if none)
            if (!cloud.userData.targetMushroom) {
                let minDistSq = 1000000;
                let candidate = null;

                const cx = cloud.position.x;
                const cy = cloud.position.y;
                const cz = cloud.position.z;

                for (let j = 0, mLen = trackedMushrooms.length; j < mLen; j++) {
                    const m = trackedMushrooms[j];
                    // Rule: Don't target if already claimed by another cloud
                    if (claimedMushrooms.has(m.uuid)) continue;

                    // Rule: Favor Small mushrooms initially to grow them
                    // But if it's already Giant, we can still latch on if we are close (permanent barrier logic)

                    // ⚡ OPTIMIZATION: Bypassed THREE.Vector3.distanceToSquared() overhead in nested O(N) loop with raw math
                    const mx = m.position.x;
                    const my = m.position.y;
                    const mz = m.position.z;
                    const distSq = (cx - mx) * (cx - mx) + (cy - my) * (cy - my) + (cz - mz) * (cz - mz);

                    if (distSq < 2500 && distSq < minDistSq) { // 50m scan range (50*50 = 2500)
                        minDistSq = distSq;
                        candidate = m;
                    }
                }

                if (candidate) {
                    cloud.userData.targetMushroom = candidate;
                    claimedMushrooms.add(candidate.uuid); // Claim it immediately
                }
            }

            // B. Execute Behavior
            if (cloud.userData.targetMushroom) {
                const target = cloud.userData.targetMushroom;

                // Safety check: Mushroom might have been deleted/replaced
                if (!target.parent) {
                    cloud.userData.targetMushroom = null;
                    continue;
                }

                // Steer
                updateCloudAttraction(cloud, target.position, dt);

                // Rain Logic
                if (isCloudOverTarget(cloud, target.position)) {
                    // Increase Wetness
                    if (!target.userData.wetness) target.userData.wetness = 0;
                    target.userData.wetness += dt * 1.5;

                    // Growth Threshold (~3 seconds of dedicated rain)
                    if (target.userData.wetness > 3.0 && target.userData.size !== 'giant') {
                        this.transformMushroom(target);
                    }
                }
            }
        }
    }

    /**
     * Transform a regular mushroom into a giant mushroom
     */
    transformMushroom(oldMushroom: any): void {
        const scene = this.weatherSystem.scene;
        const trackedMushrooms = this.weatherSystem.trackedMushrooms;
        const index = trackedMushrooms.indexOf(oldMushroom);
        if (index === -1) return;

        // Perform the Swap
        const newGiant = replaceMushroomWithGiant(scene, oldMushroom);

        if (newGiant) {
            // Update WeatherSystem Registry
            trackedMushrooms[index] = newGiant;

            // Critical: Update the Cloud's reference!
            // Find the cloud that was targeting the old mushroom
            for (let i = 0, len = foliageClouds.length; i < len; i++) {
                const c: any = foliageClouds[i];
                if (c.userData.targetMushroom === oldMushroom) {
                    c.userData.targetMushroom = newGiant;

                    // Lift the cloud up! Giants are tall.
                    c.position.y = Math.max(c.position.y, newGiant.position.y + 25);
                }
            }
        }
    }

    /**
     * Manage mushroom pool size - prevent unbounded growth
     */
    manageMushroomCount(): void {
        const MAX_MUSHROOMS = 150;
        const trackedMushrooms = this.weatherSystem.trackedMushrooms;
        const mushroomPool = this.weatherSystem.mushroomPool;
        const scene = this.weatherSystem.scene;

        if (trackedMushrooms.length > MAX_MUSHROOMS) {
            const toRemove = trackedMushrooms.shift(); // FIFO: Remove oldest

            if (toRemove) {
                // Remove from Scene so it doesn't double-register when pooled
                if (toRemove.parent) safeRemoveAndDispose(toRemove.parent as THREE.Scene, toRemove);
                if (mushroomBatcher && mushroomBatcher.removeInstance) {
                    mushroomBatcher.removeInstance(toRemove);
                }
                cleanupReactivity(toRemove);
                if (musicReactivitySystem && musicReactivitySystem.unregisterObject) {
                    musicReactivitySystem.unregisterObject(toRemove, 'mushroom');
                }

                // Return to pool instead of disposing materials to prevent GC stutter
                if (toRemove.userData.isBioluminescent === undefined) {
                    mushroomPool.push(toRemove);
                } else {
                    // Dispose special mushrooms (e.g. Giant, Bioluminescent)
                    toRemove.traverse((child: any) => {
                        if (child.material) {
                            if (Array.isArray(child.material)) {
                                for (let i = 0; i < child.material.length; i++) {
                                    const m: any = child.material[i];
                                    if (m.userData?.isClone && m.dispose) m.dispose();
                                }
                            } else if (child.material.userData?.isClone && child.material.dispose) {
                                child.material.dispose();
                            }
                        }
                    });
                }
            }
        }
    }

    /**
     * Update mushroom waterfall particle effects
     */
    updateMushroomWaterfalls(time: number, bassIntensity: number, state: any, intensity: number, trackedMushrooms: any[], mushroomWaterfalls: Set<string>): void {
        const isRaining = state !== 'clear' && intensity > 0.4;

        for (let i = 0, len = trackedMushrooms.length; i < len; i++) {
            const mushroom = trackedMushrooms[i];
            if (mushroom.userData.size === 'giant') {
                const uuid = mushroom.uuid;

                if (isRaining) {
                    if (!mushroomWaterfalls.has(uuid)) {
                        const radius = mushroom.userData.capRadius || 5.0;
                        const height = mushroom.userData.capHeight || 8.0;

                        // Use scratch vectors
                        _scratchSunDir.set(mushroom.position.x + radius * 0.8, height * 0.8, mushroom.position.z);
                        _scratchWaterfallPos.set(mushroom.position.x + radius * 0.8, height * 0.8, mushroom.position.z);

                        // Add to batcher
                        waterfallBatcher.add(uuid, _scratchSunDir, height * 0.8, 2.0);
                        waterfallBatcher.add(uuid, _scratchWaterfallPos, height * 0.8, 2.0);
                        mushroomWaterfalls.add(uuid);
                    }

                    if (bassIntensity > 0.5) {
                        waterfallBatcher.updateInstance(uuid, 1.0 + bassIntensity * 0.1);
                    }
                } else {
                    if (mushroomWaterfalls.has(uuid)) {
                        waterfallBatcher.remove(uuid);
                        mushroomWaterfalls.delete(uuid);
                    }
                }
            }
        }
    }


    /**
     * Handle spawning logic based on favorability scores
     */
    handleSpawning(time: number, fungiScore: number, lanternScore: number, globalLight: number, onSpawnFoliage: ((object: any, isNew: boolean, duration: number) => void) | null, isRaining: boolean): void {
        if (time - this._lastSpawnCheck < this._spawnThrottle) return;
        this._lastSpawnCheck = time;

        if (fungiScore > 0.8) {
            if (Math.random() < 0.4) this.spawnFoliage('mushroom', true, onSpawnFoliage);
        }
        if (lanternScore > 0.6) {
            if (Math.random() < 0.3) this.spawnFoliage('lantern', false, onSpawnFoliage);
        }
        if (globalLight > 0.7 && fungiScore < 0.3) {
             if (Math.random() < 0.2) this.spawnFoliage('flower', false, onSpawnFoliage);
        }

        // Feature: Rain-Driven Spreading
        if (isRaining && Math.random() < 0.2) {
            const growthOptions: FoliageGrowthOptions = {
                spawnRadius: 10,
                spawnChanceBase: 0.3,
                maxOffspring: 2,
                growthWindowMs: 5000,
                densityLimit: 5
            };

            const sources: { position: THREE.Vector3; type: 'mushroom' | 'flower' }[] = [];

            // 1. Non-batched sources (legacy fallback)
            for (const plant of cpuAnimatedFoliage) {
                if (!plant.userData) continue;
                if (plant.userData.type === 'mushroom' || plant.userData.isFlower) {
                    sources.push({
                        position: plant.position,
                        type: plant.userData.type === 'mushroom' ? 'mushroom' : 'flower'
                    });
                }
            }

// ⚡ OPTIMIZATION: Reuse module-level scratches (zero allocation per tick)
if (mushroomBatcher.getRandomPosition(_scratchMPos)) {
    sources.push({ position: _scratchMPos, type: 'mushroom' });
}

if (flowerBatcher.getRandomPosition(_scratchFPos)) {
    sources.push({ position: _scratchFPos, type: 'flower' });
}

            if (sources.length > 0) {
                const source = sources[Math.floor(Math.random() * sources.length)];

                // Throttle: use a module-level Map keyed by position string
                const now = Date.now();
                const key = `${source.type}_${Math.round(source.position.x)}_${Math.round(source.position.z)}`;
                const lastSpawn = _lastSpawnTimes.get(key) || 0;

                if (now - lastSpawn > growthOptions.growthWindowMs) {
                    spawnNearbyFoliage(source.position, source.type, growthOptions, this.weatherSystem);
                    _lastSpawnTimes.set(key, now);
                }
            }
        }
    }
    /**
     * Spawn a single foliage object
     */
    spawnFoliage(type: string, isGlowing: boolean, onSpawnFoliage: ((object: any, isNew: boolean, duration: number) => void) | null): void {
        if (!onSpawnFoliage) return;

        const x = (Math.random() - 0.5) * 60;
        const z = (Math.random() - 0.5) * 60;
        const y = getGroundHeight(x, z);

        let object;
        if (type === 'mushroom') {
            object = createMushroom({
                size: 'regular',
                scale: 0.5 + Math.random() * 0.5,
                isBioluminescent: isGlowing
            });
        } else if (type === 'lantern') {
            object = createLanternFlower({
                height: 2.0 + Math.random() * 1.5,
                color: 0xFFaa00
            });
        }

        if (object) {
            object.position.set(x, y, z);
            object.scale.setScalar(0.01);
            onSpawnFoliage(object, true, 0);
            if (type === 'mushroom') {
                this.weatherSystem.registerMushroom(object);
                this.manageMushroomCount();
            }
            if (type === 'lantern') this.weatherSystem.registerFlower(object);
        }
    }

    /**
     * Handle wind-based mushroom spawning
     */
    handleWindSpawning(
        time: number,
        windSpeed: number,
        windDirection: THREE.Vector3,
        trackedMushrooms: any[],
        mushroomPool: any[],
        onSpawnFoliage: ((object: any, isNew: boolean, duration: number) => void) | null,
        scene: THREE.Scene
    ): void {
        const count = trackedMushrooms.length;
        if (windSpeed > 0.4 && count > 0) {
            if (time - this._lastSpawnCheck > this._spawnThrottle) {
                this._lastSpawnCheck = time;

                if (!isWasmReady() || typeof batchMushroomSpawnCandidates !== 'function') {
                    this.spawnMushroomsJS(windSpeed, windDirection, trackedMushrooms, mushroomPool, onSpawnFoliage, scene);
                } else {
                    this.spawnMushroomsWASM(time, windDirection, windSpeed, count, trackedMushrooms, mushroomPool, onSpawnFoliage, scene);
                }
            }
        }
    }

    private spawnMushroomsJS(
        windSpeed: number,
        windDirection: THREE.Vector3,
        trackedMushrooms: any[],
        mushroomPool: any[],
        onSpawnFoliage: ((object: any, isNew: boolean, duration: number) => void) | null,
        scene: THREE.Scene
    ): void {
        let spawned = 0;
        for (let i = 0; i < trackedMushrooms.length && spawned < this._spawnCapPerFrame; i++) {
            const m = trackedMushrooms[i];
            const colorIndex = m.userData?.colorIndex ?? -1;
            const colorWeight = (colorIndex >= 0 && colorIndex <= 3) ? 0.02 : 0.005;
            const spawnChance = colorWeight * windSpeed;
            if (Math.random() < spawnChance) {
                const distance = 3 + Math.random() * 8;
                const jitter = 2 + Math.random() * 3;
                const nx = m.position.x + windDirection.x * distance + (Math.random() - 0.5) * jitter;
                const nz = m.position.z + windDirection.z * distance + (Math.random() - 0.5) * jitter;
                const ny = getGroundHeight(nx, nz);
                let newM;
                if (mushroomPool.length > 0) {
                    newM = mushroomPool.pop();
                    if (newM) newM.visible = true;
                    newM.scale.setScalar(0.7);
                    newM.userData.colorIndex = colorIndex;
                } else {
                    newM = createMushroom({ size: 'regular', scale: 0.7, colorIndex: colorIndex });
                }
                newM.position.set(nx, ny, nz);
                newM.rotation.y = Math.random() * Math.PI * 2;
                if (onSpawnFoliage) {
                    try { onSpawnFoliage(newM, true, 0.5); } catch (e) { void e; }
                } else {
                    if (!newM.parent) scene.add(newM);
                    this.weatherSystem.registerMushroom(newM);
                }
                this.manageMushroomCount();
                spawned++;
            }
        }
    }

    private spawnMushroomsWASM(
        time: number,
        windDirection: THREE.Vector3,
        windSpeed: number,
        count: number,
        trackedMushrooms: any[],
        mushroomPool: any[],
        onSpawnFoliage: ((object: any, isNew: boolean, duration: number) => void) | null,
        scene: THREE.Scene
    ): void {
        try {
            uploadMushroomSpecs(trackedMushrooms);
            const spawnThreshold = 1.0;
            const minDistance = 3.0;
            const maxDistance = 8.0;
            const candidateCount = batchMushroomSpawnCandidates(time, windDirection.x, windDirection.z, windSpeed, count, spawnThreshold, minDistance, maxDistance);
            if (candidateCount > 0) {
                const candidates = readSpawnCandidates(candidateCount);
                let spawned = 0;
                for (const c of candidates) {
                    if (spawned >= this._spawnCapPerFrame) break;
                    let newM;
                    if (mushroomPool.length > 0) {
                        newM = mushroomPool.pop();
                        if (newM) newM.visible = true;
                        newM.scale.setScalar(0.7);
                        newM.userData.colorIndex = c.colorIndex;
                    } else {
                        newM = createMushroom({ size: 'regular', scale: 0.7, colorIndex: c.colorIndex });
                    }
                    newM.position.set(c.x, c.y, c.z);
                    newM.rotation.y = Math.random() * Math.PI * 2;
                    if (onSpawnFoliage) {
                        try { onSpawnFoliage(newM, true, 0.5); } catch (e) { void e; }
                    } else {
                        if (!newM.parent) scene.add(newM);
                        this.weatherSystem.registerMushroom(newM);
                    }
                    this.manageMushroomCount();
                    spawned++;
                }
            }
        } catch (e) {
            console.warn('WASM spawn path failed, falling back to JS:', e);
        }
    }
}

import * as THREE from 'three';
import { ComputeParticleSystem } from '../../compute/particle_compute.ts';
import { CONFIG } from '../../core/config.ts';
import { triggerGrowth, triggerBloom } from '../../foliage/animation.ts';
import { createAurora, uAuroraIntensity } from '../../foliage/aurora.ts';
import { uChromaticIntensity } from '../../foliage/chromatic.ts';
import {
    uCloudRainbowIntensity,
    uCloudLightningStrength,
    uCloudLightningColor,
} from '../../foliage/clouds.ts';
import { createRainbow, uRainbowOpacity } from '../../foliage/index.ts';
import { createIntegratedRain } from '../../particles/compute-integration.ts';

// src/systems/weather/weather-effects.ts
// Visual effects management: rainbow, aurora, lightning, plant growth

import type { ComputeParticleSystem as Phase4ComputeSystem } from '../../particles/compute-particles-types.ts';
import { safeRemoveAndDispose } from '../../utils/dispose-utils.ts';
import { WeatherState } from '../weather-types.ts';

// Cache palette keys outside the render loop to prevent GC spikes during storms
// Evaluate keys lazily since this module may load before config is initialized
let _cachedCloudPaletteKeys: string[] | null = null;
const getCloudPaletteKeys = () => {
    if (!_cachedCloudPaletteKeys) {
        _cachedCloudPaletteKeys = Object.keys(
            (CONFIG?.noteColorMap && CONFIG?.noteColorMap?.cloud) || {}
        );
    }
    return _cachedCloudPaletteKeys;
};

export interface EffectsState {
    rainbow: any; // Mesh
    aurora: any; // Mesh
    rainbowTimer: number;
    lightningLight: THREE.PointLight;
    lightningActive: boolean;
    lightningTimer: number;
    rainMesh: THREE.Points | null;
    mistMesh: THREE.Points | null;
    percussionRain: Phase4ComputeSystem | null;
    melodicMist: ComputeParticleSystem | null;
}

// ⚡ OPTIMIZATION: Module-scoped variables to eliminate per-frame allocations in weather particle updates
const _scratchVecZero = new THREE.Vector3(0, 0, 0);
const _scratchParticleAudioDataRain = {
    low: 0,
    mid: 0,
    high: 0,
    beat: false,
    groove: 0,
    windX: 0,
    windZ: 0,
    windSpeed: 0,
};
const _scratchParticleAudioDataMist = { kick: 0, low: 0, mid: 0 } as any;

export class EffectsManager {
    private scene: THREE.Scene;
    private state: EffectsState;

    constructor(scene: THREE.Scene) {
        this.scene = scene;
        this.state = {
            rainbow: null,
            aurora: null,
            rainbowTimer: 0,
            lightningLight: new THREE.PointLight(0xffffff, 0, 200),
            lightningActive: false,
            lightningTimer: 0,
            rainMesh: null,
            mistMesh: null,
            percussionRain: null,
            melodicMist: null,
        };
    }

    /**
     * Get the current effects state
     */
    getState(): EffectsState {
        return this.state;
    }

    /**
     * Initialize rainbow effect
     */
    initRainbow(): void {
        this.state.rainbow = createRainbow();
        this.state.rainbow.position.set(0, -20, -100);
        this.state.rainbow.scale.setScalar(2.0);
        this.scene.add(this.state.rainbow);
    }

    /**
     * Initialize aurora effect
     */
    initAurora(): void {
        this.state.aurora = createAurora();
        this.scene.add(this.state.aurora);
    }

    /**
     * Initialize lightning light
     */
    initLightning(): void {
        this.state.lightningLight.position.set(0, 50, 0);
        this.scene.add(this.state.lightningLight);
    }

    /**
     * Set renderer for particle systems
     */
    setRenderer(renderer: any): void {
        if (!this.state.percussionRain) {
            this.state.rainMesh = createIntegratedRain({
                count: 2000,
                areaSize: 50,
                center: new THREE.Vector3(0, 40, 0),
            }) as THREE.Points;
            this.state.percussionRain =
                (this.state.rainMesh.userData?.computeParticleSystem as Phase4ComputeSystem) ||
                null;
            this.state.rainMesh.visible = false;
            this.scene.add(this.state.rainMesh);
        }

        if (!this.state.melodicMist) {
            this.state.melodicMist = new ComputeParticleSystem(1000, renderer, {
                type: 'rain',
                spawnCenter: new THREE.Vector3(0, 5, 0),
                gravity: new THREE.Vector3(0, 0, 0),
            });
            this.state.mistMesh = this.state.melodicMist.createMesh();
            this.state.mistMesh.visible = false;
            this.scene.add(this.state.mistMesh);
        }
    }

    /**
     * Update rainbow fade in/out
     */
    updateRainbow(
        dt: number,
        lastState: WeatherState,
        currentState: WeatherState,
        rainbowTimer: number
    ): number {
        // Start rainbow timer when transitioning from STORM to non-STORM
        if (lastState === WeatherState.STORM && currentState !== WeatherState.STORM) {
            rainbowTimer = 45.0;
        }

        if (rainbowTimer > 0) {
            rainbowTimer -= dt;
            let opacity = 1.0;
            if (rainbowTimer > 40.0) opacity = (45.0 - rainbowTimer) / 5.0;
            else if (rainbowTimer < 5.0) opacity = rainbowTimer / 5.0;
            if (uRainbowOpacity) uRainbowOpacity.value = opacity * 0.6;
        } else {
            if (uRainbowOpacity) uRainbowOpacity.value = 0.0;
        }

        return rainbowTimer;
    }

    /**
     * Update aurora intensity based on weather/night
     */
    updateAurora(twilightIntensity: number, state: WeatherState): void {
        // Aurora appears at Night (twilightIntensity > 0.8) and when Clear or Storm
        let targetAurora = 0.0;
        if (twilightIntensity > 0.8) {
            if (state === WeatherState.CLEAR) targetAurora = 0.8;
            else if (state === WeatherState.STORM)
                targetAurora = 1.0; // Magic Storm
            else targetAurora = 0.0; // Rain hides it
        }

        // Lerp Intensity
        if (uAuroraIntensity) {
            const current = uAuroraIntensity.value as number;
            uAuroraIntensity.value = current + (targetAurora - current) * 0.02; // Smooth fade
        }
    }

    /**
     * Update cloud lightning effects
     */
    updateCloudLightning(
        state: WeatherState,
        intensity: number,
        bassIntensity: number,
        cloudDensity: number,
        lightningLight: THREE.PointLight
    ): boolean {
        let lightningActive = false;

        if (state === WeatherState.STORM && (bassIntensity > 0.8 || Math.random() < 0.01)) {
            try {
                if (uCloudLightningStrength) uCloudLightningStrength.value = 1.0;
            } catch (e) {
                /* ignored */
            }

            const keys = getCloudPaletteKeys();
            if (keys.length > 0) {
                const randomKey = keys[Math.floor(Math.random() * keys.length)];
                const colorHex = CONFIG.noteColorMap.cloud[randomKey];
                try {
                    if (uCloudLightningColor) {
                        (uCloudLightningColor.value as unknown as THREE.Color).setHex(colorHex);
                    }
                } catch (e) {
                    /* ignored */
                }
                lightningLight.color.setHex(colorHex);
                lightningLight.intensity = 10 * cloudDensity;
                lightningLight.position.set(
                    (Math.random() - 0.5) * 100,
                    50,
                    (Math.random() - 0.5) * 100
                );
                lightningActive = true;
            }
        } else {
            try {
                if (uCloudLightningStrength) {
                    uCloudLightningStrength.value *= 0.85;
                }
            } catch (e) {
                /* ignored */
            }
        }

        return lightningActive;
    }

    /**
     * Update cloud rainbow intensity
     */
    updateCloudRainbow(melodyVol: number, highVol: number, cloudDensity: number): void {
        const rainbowTarget = (melodyVol * 0.5 + highVol * 0.5) * cloudDensity;
        try {
            if (uCloudRainbowIntensity) {
                uCloudRainbowIntensity.value +=
                    (rainbowTarget - uCloudRainbowIntensity.value) * 0.05;
            }
        } catch (e) {
            /* ignored */
        }
    }

    /**
     * Trigger chromatic pulse on palette mode change
     */
    triggerPalettePulse(): void {
        if (uChromaticIntensity) {
            uChromaticIntensity.value = 1.0; // Sharp pulse
        }
    }

    /**
     * Grow plants with given intensity
     */
    growPlants(trackedTrees: any[], trackedMushrooms: any[], intensity: number): void {
        triggerGrowth(trackedTrees, intensity);
        triggerGrowth(trackedMushrooms, intensity);
    }

    /**
     * Bloom flora with given intensity
     */
    bloomFlora(trackedFlowers: any[], intensity: number): void {
        triggerBloom(trackedFlowers, intensity);
    }

    /**
     * Update rain and mist particle systems
     */
    updateParticleSystems(
        renderer: any,
        dt: number,
        bassIntensity: number,
        melodyVol: number,
        weatherType: string,
        state: WeatherState
    ): void {
        const { percussionRain, melodicMist, rainMesh, mistMesh } = this.state;

        // Update separately to support missing systems in fallback mode

        const shouldShowRain = bassIntensity > 0.2 || state !== WeatherState.CLEAR;
        const shouldShowMist =
            melodyVol > 0.2 || (weatherType === 'mist' && state === WeatherState.RAIN);

        if (rainMesh) {
            if (rainMesh) rainMesh.visible = shouldShowRain;
        }
        if (mistMesh) {
            if (mistMesh) mistMesh.visible = shouldShowMist;
        }

        if (shouldShowRain && percussionRain) {
            _scratchParticleAudioDataRain.low = bassIntensity;
            _scratchParticleAudioDataRain.mid = melodyVol;
            percussionRain.update(renderer, dt, _scratchVecZero, _scratchParticleAudioDataRain);
        }

        if (shouldShowMist && melodicMist) {
            // old CPU update for mist
            _scratchParticleAudioDataMist.kick = bassIntensity;
            _scratchParticleAudioDataMist.low = bassIntensity;
            _scratchParticleAudioDataMist.mid = melodyVol;
            melodicMist.update(dt, _scratchParticleAudioDataMist, 0);

            // Dynamic color behavior
            if (weatherType === 'mist') {
                melodicMist.setBaseColor(0xddffdd);
            } else {
                melodicMist.setBaseColor(0xaaffaa);
            }
        }
    }

    /**
     * Get rain mesh for visibility control
     */
    getRainMesh(): THREE.Points | null {
        return this.state.rainMesh;
    }

    /**
     * Get mist mesh for visibility control
     */
    getMistMesh(): THREE.Points | null {
        return this.state.mistMesh;
    }

    /**
     * Dispose of all effects
     */
    dispose(): void {
        const { percussionRain, melodicMist, rainMesh, mistMesh, lightningLight, rainbow } =
            this.state;

        if (percussionRain) {
            percussionRain.dispose();
            if (rainMesh) {
                safeRemoveAndDispose(this.scene, rainMesh);
            }
        }
        if (melodicMist) {
            melodicMist.dispose();
            if (mistMesh) {
                safeRemoveAndDispose(this.scene, mistMesh);
            }
        }
        if (lightningLight) {
            // ⚡ OPTIMIZATION: Ensure temporary lights are disposed before removal to prevent VRAM leaks.
            safeRemoveAndDispose(this.scene, lightningLight);
        }
        if (rainbow) {
            safeRemoveAndDispose(this.scene, rainbow);
        }
    }
}

