export type MenuSection = 
  | 'presets'
  | 'motor'
  | 'visual'
  | 'cognitive'
  | 'auditory'
  | 'screen-reader';

export interface MenuItem {
  id: string;
  label: string;
  description?: string;
  type: 'toggle' | 'slider' | 'select' | 'button' | 'color' | 'keybind';
  section: MenuSection;
  defaultValue?: unknown;
  min?: number;
  max?: number;
  step?: number;
  options?: { value: string; label: string }[];
  action?: () => void;
}

// ============================================================================
// Accessibility Menu Class
// ============================================================================

/**
 * AccessibilityMenuCore manages the accessibility settings dialog.
 * Provides state management, lifecycle hooks, and focus trapping.
 */
export class AccessibilityMenuCore {
  protected container: HTMLElement | null = null;
  protected overlay: HTMLElement | null = null;
  protected isOpen = false;
  protected a11y: AccessibilitySystem;
  protected currentSection: MenuSection = 'presets';
  protected menuItems: MenuItem[] = [];
  protected focusIndex = 0;
  protected saveButton: HTMLButtonElement | null = null;
  protected releaseFocusTrap: (() => void) | null = null;
  protected lastFocusedElement: HTMLElement | null = null;
  protected boundKeyHandler = this.handleKeyDown.bind(this);

  constructor() {
    this.a11y = getAccessibilitySystem();
  }

  // ============================================================================
  // Menu Lifecycle
  // ============================================================================

  open(): void {
    if (this.isOpen) return;

    this.lastFocusedElement = document.activeElement as HTMLElement;

    this.createMenu();
    this.isOpen = true;
    document.addEventListener('keydown', this.boundKeyHandler);

    // Force DOM reflow
    void this.overlay!.offsetWidth;
    void this.container!.offsetWidth;

    // Apply active CSS styles
    this.overlay!.style.opacity = '1';
    this.container!.style.opacity = '1';
    this.container!.style.transform = 'scale(1)';

    // Trap focus after transition
    if (this.container) {
      yieldToPaint(50).then(() => {
        if (this.container && this.isOpen) {
          this.releaseFocusTrap = trapFocusInside(this.container);
        }
      });
      announce('Accessibility menu opened. Use Tab to navigate, Enter to select.', 'polite');
    }

    const openA11yBtn = document.getElementById('openA11yBtn');
    if (openA11yBtn) openA11yBtn.setAttribute('aria-expanded', 'true');
    const a11yMenuButton = document.getElementById('a11y-menu-button');
    if (a11yMenuButton) a11yMenuButton.setAttribute('aria-expanded', 'true');
  }

  close(): void {
    if (!this.isOpen) return;

    // Release focus
    if (this.releaseFocusTrap) {
      this.releaseFocusTrap();
      this.releaseFocusTrap = null;
    }

    if (this.lastFocusedElement && typeof this.lastFocusedElement.focus === 'function') {
      this.lastFocusedElement.focus({ preventScroll: true });
    }
    this.lastFocusedElement = null;

    // Remove elements
    if (this.container) {
      this.container.style.opacity = '0';
      this.container.style.transform = 'scale(0.95)';
    }
    if (this.overlay) {
      this.overlay.style.opacity = '0';
    }

    setTimeout(() => {
      if (this.overlay && this.overlay.parentNode) {
        this.overlay.parentNode.removeChild(this.overlay);
      }
      this.container = null;
      this.overlay = null;
    }, 300);

    document.removeEventListener('keydown', this.boundKeyHandler);
    this.isOpen = false;

    const openA11yBtn = document.getElementById('openA11yBtn');
    if (openA11yBtn) openA11yBtn.setAttribute('aria-expanded', 'false');
    const a11yMenuButton = document.getElementById('a11y-menu-button');
    if (a11yMenuButton) a11yMenuButton.setAttribute('aria-expanded', 'false');

    announce('Accessibility menu closed', 'polite');
  }

  // ============================================================================
  // Menu Creation (delegated to rendering module)
  // ============================================================================

  protected createMenu(): void {
    throw new Error('createMenu() must be implemented by subclass or mixin');
  }

  // ============================================================================
  // Keyboard Navigation (delegated to handlers module)
  // ============================================================================

  protected handleKeyDown(event: KeyboardEvent): void {
    throw new Error('handleKeyDown() must be implemented by subclass or mixin');
  }

  // ============================================================================
  // State Management
  // ============================================================================

  protected switchSection(section: MenuSection): void {
    this.currentSection = section;
    this.refreshMainPanel();
    this.updateSidebarSelection();
    announce(`Switched to ${this.formatActionName(section)} settings`, 'polite');
    const newTab = this.container?.querySelector(`#tab-${section}`) as HTMLElement;
    if (newTab) newTab.focus({ preventScroll: true });
  }

  protected refreshMainPanel(): void {
    const panel = this.container?.querySelector('[role="tabpanel"]') as HTMLElement;
    if (!panel) return;

    panel.id = `panel-${this.currentSection}`;
    panel.setAttribute('aria-labelledby', `tab-${this.currentSection}`);
    this.renderSection(panel, this.currentSection);
  }

  protected renderSection(container: HTMLElement, section: MenuSection): void {
    // To be overridden by rendering subclass
  }

  protected updateSidebarSelection(): void {
    const buttons = this.container?.querySelectorAll('[role="tab"]') as NodeListOf<HTMLButtonElement>;
    const sections = ['presets', 'motor', 'visual', 'cognitive', 'auditory', 'screen-reader'] as const;

    buttons?.forEach((btn, index) => {
      const isActive = sections[index] === this.currentSection;
      btn.setAttribute('aria-selected', isActive.toString());
      btn.tabIndex = isActive ? 0 : -1;
      btn.style.background = isActive ? 'var(--menu-active, #4a4a4a)' : 'transparent';
    });
  }

  // ============================================================================
  // Utility Methods
  // ============================================================================

  protected formatActionName(action: string): string {
    return action
      .replace(/([A-Z])/g, ' $1')
      .replace(/^./, str => str.toUpperCase())
      .trim();
  }

}

/**
 * Accessibility Menu - Event Handlers Module
 * Handles keyboard navigation and key rebinding for the accessibility settings menu.
 */

import { announce } from '../systems/accessibility';
import { MenuSection } from './accessibility-menu-core';
import { AccessibilityMenuRendering } from './accessibility-menu-rendering';

/**
 * Extension of AccessibilityMenuRendering with event handler methods.
 * These methods handle keyboard navigation and keybinding management.
 */
export class AccessibilityMenuHandlers extends AccessibilityMenuRendering {

  // ============================================================================
  // Event Handlers
  // ============================================================================

  protected handleKeyDown(event: KeyboardEvent): void {
    if (event.key === 'Escape') {
      this.close();
      event.preventDefault();
      return;
    }

    // ♿ Aria: Keyboard tactile feedback for interactive elements
    if (event.key === 'Enter' || event.key === ' ') {
      const activeElement = document.activeElement as HTMLElement;
      if (activeElement && (
        activeElement.classList.contains('a11y-tab') ||
        activeElement.classList.contains('a11y-button') ||
        activeElement.classList.contains('a11y-preset-card') ||
        activeElement.classList.contains('a11y-close-btn')
      )) {
        if (!activeElement.classList.contains('keyboard-active')) {
          activeElement.classList.add('keyboard-active');

          // ♿ Aria: Remove class on keyup and blur to match tactile hold duration
          const removeFeedback = () => {
            activeElement.classList.remove('keyboard-active');
            activeElement.removeEventListener('keyup', removeFeedback);
            activeElement.removeEventListener('blur', removeFeedback);
          };

          activeElement.addEventListener('keyup', removeFeedback);
          activeElement.addEventListener('blur', removeFeedback);
        }
      }
    }

    // ♿ Aria: Keyboard navigation for Tabs (Up/Down/Left/Right Arrows)
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown' || event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      const activeElement = document.activeElement as HTMLElement;
      if (activeElement && activeElement.getAttribute('role') === 'tab') {
        event.preventDefault();
        const tabs = Array.from(this.container?.querySelectorAll('[role="tab"]') || []) as HTMLElement[];
        const currentIndex = tabs.indexOf(activeElement);
        if (currentIndex >= 0) {
          let nextIndex = (event.key === 'ArrowDown' || event.key === 'ArrowRight') ? currentIndex + 1 : currentIndex - 1;
          if (nextIndex >= tabs.length) nextIndex = 0;
          if (nextIndex < 0) nextIndex = tabs.length - 1;

          const nextTab = tabs[nextIndex];
          nextTab.focus({ preventScroll: true });
          nextTab.click(); // Selection follows focus
        }
      }
    }
  }

  protected startKeyRebind(action: string, button: HTMLButtonElement): void {
    button.textContent = 'Press key...';
    button.style.background = 'var(--menu-active, #4a4a4a)';

    const handler = (e: KeyboardEvent) => {
      e.preventDefault();

      if (e.key === 'Escape') {
        button.textContent = 'Cancelled';
        setTimeout(() => this.refreshMainPanel(), 500);
      } else {
        // Update keybinding
        const keybindings = new Map(this.a11y.getSettings().input.keybindings);
        const existing = keybindings.get(action);
        if (existing) {
          keybindings.set(action, { ...existing, key: e.key });
          this.a11y.updateInputSettings({ keybindings });
        }
        button.textContent = `Set to ${e.key}`;
        announce(`${this.formatActionName(action)} bound to ${e.key}`, 'polite');
        setTimeout(() => this.refreshMainPanel(), 500);
      }

      document.removeEventListener('keydown', handler);
    };

    document.addEventListener('keydown', handler);
  }
}

/**
 * Accessibility Menu - Rendering Module
 * Handles all DOM creation and rendering logic for the accessibility settings menu.
 * This module extends the core AccessibilityMenu class with rendering capabilities.
 */

import { trapFocusInside } from '../utils/interaction-utils';
import { AccessibilityMenuCore, MenuSection } from './accessibility-menu-core';
import { announce } from './announcer';

/**
 * Extension of AccessibilityMenuCore with rendering methods.
 * These methods handle all DOM creation and section rendering.
 */
export class AccessibilityMenuRendering extends AccessibilityMenuCore {

  // ============================================================================
  // DOM Creation Methods
  // ============================================================================

  protected createMenu(): void {
    // Create overlay
    this.overlay = document.createElement('div');
    this.overlay.className = 'a11y-menu-overlay';
    this.overlay.style.cssText = `
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.8);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 10000;
      opacity: 0;
      transition: opacity 0.3s ease;
    `;

    // Create menu container
    this.container = document.createElement('div');
    this.container.className = 'a11y-menu-container';
    this.container.setAttribute('role', 'dialog');
    this.container.setAttribute('aria-modal', 'true');
    this.container.setAttribute('tabindex', '-1');
    this.container.setAttribute('aria-labelledby', 'a11y-menu-title');
    this.container.style.cssText = `
      background: var(--menu-bg, #2a2a2a);
      border-radius: 12px;
      width: 90%;
      max-width: 800px;
      max-height: 90vh;
      display: flex;
      flex-direction: column;
      overflow: hidden;
      color: var(--menu-text, #ffffff);
      font-family: system-ui, -apple-system, sans-serif;
      opacity: 0;
      transform: scale(0.95);
      transition: opacity 0.3s ease, transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    `;

    this.container.appendChild(this.createHeader());
    this.container.appendChild(this.createContent());
    this.container.appendChild(this.createFooter());

    this.overlay.appendChild(this.container);
    document.body.appendChild(this.overlay);

    // Set up keyboard listener
    this.container.addEventListener('keydown', (e) => this.handleKeyDown(e));
  }

  private createHeader(): HTMLElement {
    const header = document.createElement('header');
    header.style.cssText = `
      padding: 20px;
      border-bottom: 1px solid var(--menu-border, #444);
      display: flex;
      justify-content: space-between;
      align-items: center;
    `;

    const title = document.createElement('h2');
    title.id = 'a11y-menu-title';
    title.textContent = 'Accessibility Settings';
    title.style.cssText = `
      margin: 0;
      font-size: 1.5rem;
      color: var(--menu-heading, #fff);
    `;

    const closeBtn = document.createElement('button');
    closeBtn.className = 'a11y-close-btn a11y-button';
    closeBtn.textContent = '✕';
    closeBtn.style.cssText = `
      ${this.getButtonStyle()}
      width: 40px;
      height: 40px;
      padding: 0;
      border-radius: 4px;
      cursor: pointer;
      font-size: 1.2rem;
    `;
    closeBtn.onclick = () => {
      this.close();
    };
    closeBtn.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        if (!closeBtn.classList.contains('keyboard-active')) {
          closeBtn.classList.add('keyboard-active');
          const removeFeedback = () => {
            closeBtn.classList.remove('keyboard-active');
            closeBtn.removeEventListener('keyup', removeFeedback);
            closeBtn.removeEventListener('blur', removeFeedback);
          };
          closeBtn.addEventListener('keyup', removeFeedback);
          closeBtn.addEventListener('blur', removeFeedback);
        }
      }
    });
    closeBtn.setAttribute('aria-label', 'Close accessibility menu');

    header.appendChild(title);
    header.appendChild(closeBtn);
    return header;
  }

  private createContent(): HTMLElement {
    const content = document.createElement('div');
    content.style.cssText = `
      display: flex;
      flex: 1;
      min-height: 0;
      overflow: hidden;
    `;

    const sidebar = this.createSidebar();
    const mainPanel = this.createMainPanel();

    content.appendChild(sidebar);
    content.appendChild(mainPanel);
    return content;
  }

  private createSidebar(): HTMLElement {
    const sidebar = document.createElement('aside');
    sidebar.role = 'tablist';
    sidebar.style.cssText = `
      width: 160px;
      border-right: 1px solid var(--menu-border, #444);
      background: var(--menu-sidebar-bg, #2a2a2a);
      overflow-y: auto;
      padding: 10px 0;
    `;

    const sections: MenuSection[] = ['presets', 'motor', 'visual', 'cognitive', 'auditory', 'screen-reader'];
    const labels = {
      presets: 'Presets',
      motor: 'Motor',
      visual: 'Visual',
      cognitive: 'Cognitive',
      auditory: 'Auditory',
      'screen-reader': 'Screen Reader'
    };

    const sectionMenuItems = sections; // all sections are always available

    for (const section of sections) {
      const isActive = this.currentSection === section;
      const tab = document.createElement('button');
      tab.className = 'a11y-tab';
      tab.id = `tab-${section}`;
      tab.role = 'tab';
      tab.setAttribute('aria-selected', isActive ? 'true' : 'false');
      tab.tabIndex = isActive ? 0 : -1;
      tab.setAttribute('aria-controls', `panel-${section}`);
      tab.textContent = labels[section];
      tab.style.cssText = `
        width: 100%;
        padding: 12px;
        color: var(--menu-text, #ccc);
        border: none;
        border-left: 3px solid transparent;
        cursor: pointer;
        text-align: left;
      `;
      tab.onclick = () => {
        this.switchSection(section);
      };
      tab.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          if (!tab.classList.contains('keyboard-active')) {
            tab.classList.add('keyboard-active');
            const removeFeedback = () => {
              tab.classList.remove('keyboard-active');
              tab.removeEventListener('keyup', removeFeedback);
              tab.removeEventListener('blur', removeFeedback);
            };
            tab.addEventListener('keyup', removeFeedback);
            tab.addEventListener('blur', removeFeedback);
          }
        }
      });

      sidebar.appendChild(tab);
    }

    return sidebar;
  }

  private createMainPanel(): HTMLElement {
    const main = document.createElement('main');
    main.id = `panel-${this.currentSection}`;
    main.setAttribute('role', 'tabpanel');
    main.setAttribute('aria-labelledby', `tab-${this.currentSection}`);
    main.tabIndex = 0;
    main.style.cssText = `
      flex: 1;
      overflow-y: auto;
      padding: 20px;
      background: var(--menu-bg, #1a1a1a);
      color: var(--menu-text, #fff);
    `;

    this.renderSection(main, this.currentSection);
    return main;
  }

  private createFooter(): HTMLElement {
    const footer = document.createElement('footer');
    footer.style.cssText = `
      padding: 15px 20px;
      border-top: 1px solid var(--menu-border, #444);
      background: var(--menu-footer-bg, #2a2a2a);
      text-align: center;
      font-size: 0.9rem;
      color: var(--menu-text-muted, #999);
    `;

    footer.textContent = 'Press ESC to close';
    footer.setAttribute('aria-label', 'Footer help text');

    return footer;
  }

  private getButtonStyle(): string {
    return `
      background: var(--menu-button-bg, #3a3a3a);
      color: var(--menu-text, #fff);
      border: 1px solid var(--menu-border, #444);
      border-radius: 4px;
      padding: 8px 16px;
      font-size: 1rem;
      transition: all 0.2s;
    `;
  }

  // ============================================================================
  // Section Rendering
  // ============================================================================

  protected renderSection(container: HTMLElement, section: MenuSection): void {
    container.innerHTML = '';
    switch (section) {
      case 'presets':
        this.renderPresetsSection(container);
        break;
      case 'motor':
        this.renderMotorSection(container);
        break;
      case 'visual':
        this.renderVisualSection(container);
        break;
      case 'cognitive':
        this.renderCognitiveSection(container);
        break;
      case 'auditory':
        this.renderAuditorySection(container);
        break;
      case 'screen-reader':
        this.renderScreenReaderSection(container);
        break;
    }
  }

  private renderPresetsSection(container: HTMLElement): void {
    const settings = this.a11y.getSettings();

    this.createSectionTitle(container, 'Quick Presets');
    this.createSectionSubtitle(container, 'Apply predefined accessibility profiles');

    const presets = [
      { id: 'legible', label: 'Legible', desc: 'High contrast & larger text' },
      { id: 'motor-friendly', label: 'Motor-Friendly', desc: 'Larger buttons & reduced motion' },
      { id: 'minimal-distractions', label: 'Focus', desc: 'Minimal colors & animations' }
    ];

    const grid = document.createElement('div');
    grid.style.cssText = `
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
      gap: 12px;
      margin-top: 20px;
    `;

    for (const preset of presets) {
      const card = document.createElement('button');
      card.className = 'a11y-preset-card a11y-button';
      card.style.cssText = `
        ${this.getButtonStyle()}
        padding: 16px;
        cursor: pointer;
        text-align: left;
        display: flex;
        flex-direction: column;
        gap: 8px;
      `;

      const title = document.createElement('strong');
      title.textContent = preset.label;
      const desc = document.createElement('small');
      desc.textContent = preset.desc;

      card.appendChild(title);
      card.appendChild(desc);
      card.onclick = () => {
        this.a11y.applyPreset(preset.id);
        announce(`${preset.label} preset applied`, 'polite');
        this.highlightActiveCard(grid, card);
      };

      grid.appendChild(card);
    }

    container.appendChild(grid);
  }

  private highlightActiveCard(container: HTMLElement, activeCard: HTMLElement): void {
    const cards = container.querySelectorAll('button');
    cards.forEach(card => {
      card.style.outline = card === activeCard ? '2px solid var(--a11y-color, #00aaff)' : 'none';
    });
  }

  private renderMotorSection(container: HTMLElement): void {
    const settings = this.a11y.getSettings();

    this.createSectionTitle(container, 'Motor Accessibility');
    this.createSectionSubtitle(container, 'Control & movement settings');

    // Pointer speed — maps to input.sensitivity (0.1–2.0)
    this.createSlider(container, 'Pointer Speed', 'input.sensitivity', settings.input.sensitivity, 0.1, 2, 0.1, (val) => {
      this.a11y.updateInputSettings({ sensitivity: val });
    });

    // Reduced motion — maps to visual.motionReduction
    this.createToggle(container, 'Reduce Motion', 'visual.motionReduction', settings.visual.motionReduction, (val) => {
      this.a11y.updateVisualSettings({ motionReduction: val });
    });

    // Keybindings
    this.createSectionTitle(container, 'Keybindings');
    const keybindingContainer = document.createElement('div');
    keybindingContainer.style.cssText = 'display: flex; flex-direction: column; gap: 10px;';

    const keybindings = settings.input.keybindings;
    for (const [action, binding] of keybindings.entries()) {
      const row = document.createElement('div');
      row.style.cssText = 'display: flex; justify-content: space-between; align-items: center;';

      const label = document.createElement('label');
      label.textContent = this.formatActionName(action);
      label.style.cssText = 'flex: 1;';

      const btn = document.createElement('button');
      btn.className = 'a11y-button';
      btn.textContent = binding.key || 'Unbound';
      btn.style.cssText = `${this.getButtonStyle()} width: 120px;`;
      btn.onclick = () => {
        this.startKeyRebind(action, btn);
      };
      btn.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          if (!btn.classList.contains('keyboard-active')) {
            btn.classList.add('keyboard-active');
            const removeFeedback = () => {
              btn.classList.remove('keyboard-active');
              btn.removeEventListener('keyup', removeFeedback);
              btn.removeEventListener('blur', removeFeedback);
            };
            btn.addEventListener('keyup', removeFeedback);
            btn.addEventListener('blur', removeFeedback);
          }
        }
      });

      row.appendChild(label);
      row.appendChild(btn);
      keybindingContainer.appendChild(row);
    }

    container.appendChild(keybindingContainer);
  }

  /**
   * Begin listening for the next keypress to rebind an action.
   * The button label updates to show the new key; the binding is persisted
   * via updateInputSettings once a key is captured.
   */
  protected startKeyRebind(action: string, btn: HTMLButtonElement): void {
    const originalText = btn.textContent ?? '';
    btn.textContent = 'Press a key…';
    btn.setAttribute('aria-label', `Rebinding ${action} — press a key`);
    const handler = (e: KeyboardEvent): void => {
      e.preventDefault();
      document.removeEventListener('keydown', handler, true);
      const keybindings = new Map(this.a11y.getSettings().input.keybindings);
      const existing = keybindings.get(action);
      keybindings.set(action, { ...(existing ?? {}), key: e.key });
      this.a11y.updateInputSettings({ keybindings });
      btn.textContent = e.key;
      btn.setAttribute('aria-label', `${action} bound to ${e.key}`);
    };
    document.addEventListener('keydown', handler, true);
    // Safety timeout: cancel rebind after 10 s of no input
    setTimeout(() => {
      document.removeEventListener('keydown', handler, true);
      if (btn.textContent === 'Press a key…') btn.textContent = originalText;
    }, 10_000);
  }

  private renderVisualSection(container: HTMLElement): void {
    const settings = this.a11y.getSettings();

    this.createSectionTitle(container, 'Visual Accessibility');
    this.createSectionSubtitle(container, 'Colors, contrast & text settings');

    // High contrast
    this.createToggle(container, 'High Contrast', 'visual.highContrast', settings.visual.highContrast, (val) => {
      this.a11y.updateVisualSettings({ highContrast: val });
    });

    // Color blindness
    this.createSelect(container, 'Color Blindness Mode', 'visual.colorBlindMode', settings.visual.colorBlindMode, ['none', 'protanopia', 'deuteranopia', 'tritanopia', 'achromatopsia'], (val) => {
      this.a11y.updateVisualSettings({ colorBlindMode: val as any });
    });

    // Motion reduction
    this.createToggle(container, 'Reduce Motion', 'visual.motionReduction', settings.visual.motionReduction, (val) => {
      this.a11y.updateVisualSettings({ motionReduction: val });
    });

    // Screen shake
    this.createToggle(container, 'Screen Shake', 'visual.screenShake', settings.visual.screenShake, (val) => {
      this.a11y.updateVisualSettings({ screenShake: val });
    });

    // Brightness
    this.createSlider(container, 'Brightness', 'visual.brightness', settings.visual.brightness, 0.5, 1.5, 0.05, (val) => {
      this.a11y.updateVisualSettings({ brightness: val });
    });

    // Crosshair color
    this.createColorPicker(container, 'Crosshair Color', 'visual.crosshairColor', settings.visual.crosshairColor, (val) => {
      this.a11y.updateVisualSettings({ crosshairColor: val });
    });
  }

  private renderCognitiveSection(container: HTMLElement): void {
    const settings = this.a11y.getSettings();

    this.createSectionTitle(container, 'Cognitive Accessibility');
    this.createSectionSubtitle(container, 'Simplification & focus settings');

    // Simplified UI (was: simplifyUI — renamed to simplifiedUI in AccessibilitySettings)
    this.createToggle(container, 'Simplify Interface', 'cognitive.simplifiedUI', settings.cognitive.simplifiedUI, (val) => {
      this.a11y.updateCognitiveSettings({ simplifiedUI: val });
