  // ============================================================================
  // UI Component Factories
  // ============================================================================

  protected createSectionTitle(container: HTMLElement, title: string): void {
    const titleEl = document.createElement('h3');
    titleEl.textContent = title;
    titleEl.style.cssText = `
      margin: 0 0 8px 0;
      font-size: 1.2rem;
      color: var(--menu-heading, #fff);
      font-weight: 600;
    `;
    container.appendChild(titleEl);
  }

  protected createSectionSubtitle(container: HTMLElement, subtitle: string): void {
    const subtitleEl = document.createElement('p');
    subtitleEl.textContent = subtitle;
    subtitleEl.style.cssText = `
      margin: 0 0 16px 0;
      font-size: 0.9rem;
      color: var(--menu-text-muted, #999);
    `;
    container.appendChild(subtitleEl);
  }

  private createToggle(container: HTMLElement, label: string, id: string, checked: boolean, onChange: (val: boolean) => void): void {
    const wrapper = document.createElement('div');
    wrapper.style.cssText = `
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 12px;
    `;

    // ♿ Aria: Use <div> instead of <label> for custom button switches to prevent double-announcing
    const labelEl = document.createElement('div');
    labelEl.textContent = label;
    labelEl.id = `${id}-label`;
    labelEl.style.cssText = 'flex: 1; cursor: pointer;';

    // ♿ Aria: Format custom toggles as <button type="button" role="switch" aria-checked="...">
    const toggleBtn = document.createElement('button');
    toggleBtn.type = 'button';
    toggleBtn.className = 'a11y-button';
    toggleBtn.id = id;
    toggleBtn.setAttribute('role', 'switch');
    toggleBtn.setAttribute('aria-checked', checked.toString());
    toggleBtn.setAttribute('aria-labelledby', labelEl.id);

    // Switch styling
    toggleBtn.style.cssText = `
      width: 44px;
      height: 24px;
      cursor: pointer;
      border-radius: 12px;
      border: 2px solid var(--menu-border, #444);
      background: ${checked ? 'var(--a11y-color, #00aaff)' : 'transparent'};
      position: relative;
      padding: 0;
    `;

    // Inner thumb
    const thumb = document.createElement('div');
    thumb.style.cssText = `
      width: 14px;
      height: 14px;
      border-radius: 50%;
      background: white;
      position: absolute;
      top: 3px;
      left: ${checked ? '23px' : '3px'};
      transition: left 0.2s, background 0.2s;
    `;
    toggleBtn.appendChild(thumb);

    let isChecked = checked;
    const toggleState = (e?: Event) => {
      if (e) e.preventDefault();
      isChecked = !isChecked;

      toggleBtn.setAttribute('aria-checked', isChecked.toString());
      toggleBtn.style.background = isChecked ? 'var(--a11y-color, #00aaff)' : 'transparent';
      thumb.style.left = isChecked ? '23px' : '3px';

      onChange(isChecked);
    };

    toggleBtn.addEventListener('click', toggleState);
    labelEl.addEventListener('click', toggleState);

    wrapper.appendChild(labelEl);
    wrapper.appendChild(toggleBtn);
    container.appendChild(wrapper);
  }

  private createSlider(container: HTMLElement, label: string, id: string, value: number, min: number, max: number, step: number, onChange: (val: number) => void): void {
    const wrapper = document.createElement('div');
    wrapper.style.cssText = 'margin-bottom: 16px;';

    const labelEl = document.createElement('label');
    labelEl.textContent = label;
    labelEl.htmlFor = id;
    labelEl.style.cssText = 'display: block; margin-bottom: 6px; font-weight: 500;';

    const sliderWrapper = document.createElement('div');
    sliderWrapper.style.cssText = 'display: flex; gap: 12px; align-items: center;';

    const slider = document.createElement('input');
    slider.type = 'range';
    slider.id = id;
    slider.min = min.toString();
    slider.max = max.toString();
    slider.step = step.toString();
    slider.value = value.toString();
    slider.style.cssText = 'flex: 1;';
    slider.oninput = () => onChange(parseFloat(slider.value));

    const valueDisplay = document.createElement('span');
    valueDisplay.textContent = value.toFixed(2);
    valueDisplay.style.cssText = 'width: 50px; text-align: right; font-size: 0.9rem; color: var(--menu-text-muted, #999);';

    slider.oninput = () => {
      const val = parseFloat(slider.value);
      valueDisplay.textContent = val.toFixed(2);
      onChange(val);
    };

    sliderWrapper.appendChild(slider);
    sliderWrapper.appendChild(valueDisplay);

    wrapper.appendChild(labelEl);
    wrapper.appendChild(sliderWrapper);
    container.appendChild(wrapper);
  }

  private createSelect(container: HTMLElement, label: string, id: string, value: string, options: string[], onChange: (val: string) => void): void {
    const wrapper = document.createElement('div');
    wrapper.style.cssText = 'margin-bottom: 16px;';

    const labelEl = document.createElement('label');
    labelEl.textContent = label;
    labelEl.htmlFor = id;
    labelEl.style.cssText = 'display: block; margin-bottom: 6px; font-weight: 500;';

    const select = document.createElement('select');
    select.className = 'a11y-select';
    select.id = id;
    select.style.cssText = `
      ${this.getButtonStyle()}
      width: 100%;
      cursor: pointer;
    `;
    select.value = value;
    select.onchange = () => onChange(select.value);

    for (const option of options) {
      const optEl = document.createElement('option');
      optEl.value = option;
      optEl.textContent = option.charAt(0).toUpperCase() + option.slice(1);
      select.appendChild(optEl);
    }

    wrapper.appendChild(labelEl);
    wrapper.appendChild(select);
    container.appendChild(wrapper);
  }

  private createColorPicker(container: HTMLElement, label: string, id: string, value: string, onChange: (val: string) => void): void {
    const wrapper = document.createElement('div');
    wrapper.style.cssText = 'margin-bottom: 16px;';

    const labelEl = document.createElement('label');
    labelEl.textContent = label;
    labelEl.htmlFor = id;
    labelEl.style.cssText = 'display: block; margin-bottom: 6px; font-weight: 500;';

    const colorWrapper = document.createElement('div');
    colorWrapper.style.cssText = 'display: flex; gap: 12px; align-items: center;';

    const colorInput = document.createElement('input');
    colorInput.type = 'color';
    colorInput.id = id;
    colorInput.value = value;
    colorInput.style.cssText = 'width: 50px; height: 50px; border: 1px solid var(--menu-border, #444); cursor: pointer; border-radius: 4px;';
    colorInput.onchange = () => onChange(colorInput.value);

    const textDiv = document.createElement('div');
    textDiv.style.cssText = 'flex: 1;';

    const hexInput = document.createElement('input');
    hexInput.type = 'text';
    hexInput.value = value;
    hexInput.style.cssText = `
      ${this.getButtonStyle()}
      width: 100%;
      font-family: monospace;
    `;
    hexInput.onchange = () => {
      if (/^#[0-9A-Fa-f]{6}$/.test(hexInput.value)) {
        colorInput.value = hexInput.value;
        onChange(hexInput.value);
      }
    };

    textDiv.appendChild(hexInput);
    colorWrapper.appendChild(colorInput);
    colorWrapper.appendChild(textDiv);

    wrapper.appendChild(labelEl);
    wrapper.appendChild(colorWrapper);
    container.appendChild(wrapper);
  }
}

import { analytics, trackEvent } from '../systems/analytics';
import { trapFocusInside } from '../utils/interaction-utils.ts';
import { yieldToPaint } from '../utils/yield-to-paint.ts';
import {
  DebugPanelElements,
  DebugStats,
  injectStyles,
  makeDraggable,
  createElements,
  drawFPSHistogram,
  updateSessionStats,
  updateMetricsStats,
  updateEventLogUI
} from './analytics-debug-ui.ts';

// =============================================================================
// Analytics Debug Overlay Class
// =============================================================================

export class AnalyticsDebugOverlay {
  private elements: DebugPanelElements | null = null;
  private isVisible = false;
  private isMinimized = false;
  private updateInterval: number | null = null;
  private eventLog: Array<{ time: string; type: string; props: string }> = [];
  private maxEventLog = 50;
  private releaseFocusTrap: (() => void) | null = null;
  private lastFocusedElement: HTMLElement | null = null;

  constructor() {
    injectStyles();
  }

  /**
   * Setup control button handlers
   */
  private setupControls(): void {
    // Enable/disable toggle
    const enabledToggle = document.getElementById('analytics-toggle-enabled');
    if (enabledToggle) {
      enabledToggle.addEventListener('click', () => {
        const config = analytics.getConfig();
        analytics.setEnabled(!config.enabled);
        enabledToggle.classList.toggle('active');
        enabledToggle.setAttribute('aria-checked', (!config.enabled).toString());
        this.refresh();
      });
    }

    // Local only toggle
    const localToggle = document.getElementById('analytics-toggle-local');
    if (localToggle) {
      localToggle.addEventListener('click', () => {
        const config = analytics.getConfig();
        analytics.updateConfig({ localOnly: !config.localOnly });
        localToggle.classList.toggle('active');
        localToggle.setAttribute('aria-checked', (!config.localOnly).toString());
      });
    }

    // Export button
    const exportBtn = document.getElementById('analytics-export-btn');
    if (exportBtn) {
      exportBtn.addEventListener('click', () => {
        analytics.downloadExport();
        trackEvent('debug_export_data', {});
      });
    }

    // Refresh button
    const refreshBtn = document.getElementById('analytics-refresh-btn');
    if (refreshBtn) {
      refreshBtn.addEventListener('click', () => {
        this.refresh();
      });
    }

    // Clear button
    const clearBtn = document.getElementById('analytics-clear-btn');
    if (clearBtn) {
      clearBtn.addEventListener('click', () => {
        if (confirm('Are you sure you want to clear all analytics data? This cannot be undone.')) {
          analytics.clear();
          this.eventLog = [];
          this.refresh();
        }
      });
    }

    // Event delegation for dynamically added buttons (like the CTA in empty state)
    if (this.elements?.eventsSection) {
      this.elements.eventsSection.addEventListener('click', (e) => {
        const target = e.target as HTMLElement;
        const button = target.closest('#analytics-test-event-btn');
        if (button) {
          trackEvent('test_event', { source: 'debug_ui' });
        }
      });
    }

    // Add keyboard tactile feedback to all interactive elements in this menu
    if (this.elements?.container) {
      this.elements.container.addEventListener('keydown', (e: KeyboardEvent) => {
        if (e.key === 'Enter' || e.key === ' ') {
          const target = e.target as HTMLElement;
          if (
            target &&
            (target.classList.contains('analytics-debug-button') ||
             target.classList.contains('analytics-debug-close') ||
             target.classList.contains('analytics-debug-toggle-switch'))
          ) {
            if (!target.classList.contains('keyboard-active')) {
              target.classList.add('keyboard-active');
              const removeFeedback = () => {
                target.classList.remove('keyboard-active');
                target.removeEventListener('keyup', removeFeedback);
                target.removeEventListener('blur', removeFeedback);
              };
              target.addEventListener('keyup', removeFeedback);
              target.addEventListener('blur', removeFeedback);
            }
          }
        }
      });
    }
  }

  /**
   * Hook into analytics event tracking
   */
  private hookEventTracking(): void {
    // We'll get events from the debug stats updates
    // In a real implementation, we might want to subscribe to events
  }

  /**
   * Show the debug overlay
   */
  show(): void {
    if (this.isVisible) return;

    this.lastFocusedElement = document.activeElement as HTMLElement;
    this.elements = createElements(
      () => this.hide(),
      () => this.toggleMinimize()
    );
    this.isVisible = true;

    // Force DOM reflow
    void this.elements.container.offsetWidth;

    // Apply active styles
    this.elements.container.style.opacity = '1';
    this.elements.container.style.transform = 'scale(1)';

    // Trap focus inside the overlay
    yieldToPaint(50).then(() => {
      if (this.isVisible && this.elements?.container) {
        this.releaseFocusTrap = trapFocusInside(this.elements.container);
      }
    });

    // Setup control handlers
    this.setupControls();

    // Track events
    this.hookEventTracking();

    // Start update loop
    this.refresh();
    this.updateInterval = window.setInterval(() => {
      this.refresh();
    }, 1000);

    trackEvent('debug_overlay_opened', {});
  }

  /**
   * Hide the debug overlay
   */
  hide(): void {
    if (!this.isVisible || !this.elements) return;

    // Release focus trap and restore focus
    if (this.releaseFocusTrap) {
      this.releaseFocusTrap();
      this.releaseFocusTrap = null;
    }
    if (this.lastFocusedElement && typeof this.lastFocusedElement.focus === 'function') {
      this.lastFocusedElement.focus({ preventScroll: true });
    }
    this.lastFocusedElement = null;

    this.elements.container.style.opacity = '0';
    this.elements.container.style.transform = 'scale(0.95)';
    const containerToRemove = this.elements.container;
    setTimeout(() => {
      containerToRemove.remove();
    }, 300);
    this.elements = null;
    this.isVisible = false;

    if (this.updateInterval) {
      clearInterval(this.updateInterval);
      this.updateInterval = null;
    }

    trackEvent('debug_overlay_closed', {});
  }

  /**
   * Toggle visibility
   */
  toggle(): void {
    if (this.isVisible) {
      this.hide();
    } else {
      this.show();
    }
  }

  /**
   * Toggle minimize state
   */
  toggleMinimize(): void {
    if (!this.elements) return;

    this.isMinimized = !this.isMinimized;
    this.elements.container.classList.toggle('analytics-debug-minimized', this.isMinimized);
  }

  /**
   * Refresh the display
   */
  refresh(): void {
    if (!this.elements) return;

    const stats = analytics.getDebugStats();
    const session = analytics.getSession();

    drawFPSHistogram(this.elements.fpsCanvas, stats.fpsHistogram);
    updateSessionStats(this.elements.sessionSection, session, stats);
    updateMetricsStats(this.elements.metricsSection, stats);
    this.updateEventLog();
  }

  /**
   * Add an event to the log
   */
  addEvent(type: string, properties: Record<string, unknown>): void {
    const time = new Date().toLocaleTimeString();
    const props = JSON.stringify(properties);
    const truncatedProps = props.length > 50 ? props.slice(0, 50) + '...' : props;

    this.eventLog.unshift({ time, type, props: truncatedProps });

    // Keep only recent events
    if (this.eventLog.length > this.maxEventLog) {
      this.eventLog.pop();
    }

    // Update display if visible
    if (this.isVisible) {
      this.updateEventLog();
    }
  }

  /**
   * Update event log display
   */
  private updateEventLog(): void {
    if (!this.elements) return;
    updateEventLogUI(this.elements.eventsSection, this.eventLog);
  }

  /**
   * Check if overlay is visible
   */
  isOpen(): boolean {
    return this.isVisible;
  }
}

// =============================================================================
// Singleton Instance
// =============================================================================

/** Global analytics debug overlay instance */
export const analyticsDebug = new AnalyticsDebugOverlay();

// =============================================================================
// Convenience Functions
// =============================================================================

/**
 * Toggle the analytics debug overlay
 */
export function toggleAnalyticsDebug(): void {
  analyticsDebug.toggle();
}

/**
 * Show the analytics debug overlay
 */
export function showAnalyticsDebug(): void {
  analyticsDebug.show();
}

/**
 * Hide the analytics debug overlay
 */
export function hideAnalyticsDebug(): void {
  analyticsDebug.hide();
}

// =============================================================================
// Console Command Registration
// =============================================================================

/**
 * Register the /stats command
 */
export function registerStatsCommand(): void {
  if (typeof window === 'undefined') return;

  // Add to window for console access
  (window as any).toggleAnalyticsDebug = toggleAnalyticsDebug;
  (window as any).showAnalyticsDebug = showAnalyticsDebug;
  (window as any).hideAnalyticsDebug = hideAnalyticsDebug;
  (window as any).analyticsDebug = analyticsDebug;

  console.log('%c🍭 Candy World Analytics', 'color: #ff69b4; font-weight: bold; font-size: 14px');
  console.log('%cAvailable commands:', 'color: #888');
  console.log('  %ctoggleAnalyticsDebug()%c - Toggle debug overlay', 'color: #4ade80', 'color: #aaa');
  console.log('  %canalytics.exportData()%c - Get all analytics data', 'color: #4ade80', 'color: #aaa');
  console.log('  %canalytics.downloadExport()%c - Download data as JSON', 'color: #4ade80', 'color: #aaa');

  // Listen for /stats in console input (for games with chat)
  const originalConsoleLog = console.log;
  console.log = function(...args: any[]) {
    originalConsoleLog.apply(console, args);

    // Check if this is a command message
    if (args.length > 0 && typeof args[0] === 'string') {
      const msg = args[0].trim().toLowerCase();
      if (msg === '/stats' || msg === '/analytics') {
        toggleAnalyticsDebug();
      }
    }
  };
}

// Auto-register only when this module is explicitly loaded (e.g. ?debug=1).
// Do not side-effect on accidental barrel import — see analytics-debug-lazy.ts (#1361).
export function ensureAnalyticsDebugRegistered(): void {
  if (typeof window !== 'undefined') {
    registerStatsCommand();
  }
}

/**
 * Lazy analytics-debug entry — only loaded for `?debug=1` / `/stats` (#1361).
 */
export async function loadAnalyticsDebug(): Promise<typeof import('./analytics-debug.ts')> {
    return import('./analytics-debug.ts');
}

/** Prefetch + register `/stats` when debug mode is on. */
export async function initAnalyticsDebugIfNeeded(): Promise<void> {
    if (typeof window === 'undefined') return;
    const params = new URLSearchParams(window.location.search);
    const debugOn = params.get('debug') === '1' || params.get('debug') === 'true';
    if (!debugOn) {
        // Still expose a console stub that loads on demand
        (window as any).toggleAnalyticsDebug = async () => {
            const m = await loadAnalyticsDebug();
            m.toggleAnalyticsDebug();
        };
        return;
    }
    const m = await loadAnalyticsDebug();
    m.registerStatsCommand();
}

