import { log } from '../utils/log.ts';
import { showToast } from '../utils/toast.ts';
import { getReport } from '../world/spawn-tracker.ts';

/**
 * Wire the deferred indicator's spawn-failure badge once, then update its
 * visibility and count on subsequent calls.
 */
export function updateSpawnFailureBadge(
    indicator: HTMLElement,
    failedHint?: number
): void {
    const failedCount = failedHint !== undefined ? failedHint : getReport().failed;
    const failEl = indicator.querySelector('.deferred-fail') as HTMLElement | null;
    const failCountEl = indicator.querySelector('.fail-count') as HTMLElement | null;
    if (!failEl || !failCountEl) return;

    if (failedCount > 0) {
        failCountEl.textContent = String(failedCount);
        failEl.style.display = 'inline';
        failEl.setAttribute('aria-hidden', 'false');
        failEl.setAttribute('title', `${failedCount} object(s) failed to spawn — click for details`);

        if (!(failEl as any)._spawnClickWired) {
            (failEl as any)._spawnClickWired = true;
            const handleActivate = (ev: Event) => {
                ev.stopPropagation();
                try {
                    const r = getReport();
                    const summary = `Spawn failures: ${r.failed}/${r.attempted} (succeeded ${r.succeeded}). By type: ${Object.entries(r.failuresByType).map(([k,v])=>k+':'+v).join(', ') || 'n/a'}`;
                    log.debug('SpawnTracker', 'Failures during population', r.failuresByType, 'Last errors:', r.lastErrors);
                    showToast(summary + ' — see console for full list', '⚠️', 6000);
                } catch (e) { log.warn('Deferred', 'failed to show spawn report', e); }
            };
            failEl.addEventListener('click', handleActivate);
            failEl.addEventListener('keydown', (ev: KeyboardEvent) => {
                if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); handleActivate(ev); }
            });
        }
    } else {
        failEl.style.display = 'none';
        failEl.setAttribute('aria-hidden', 'true');
    }
}

/**
 * Lazy save-menu entry points — load the heavy UI only when a menu is opened (#1361).
 */
import type { SaveData } from '../../systems/save-system/index.ts';
import type { SaveMenu, SaveMenuOptions } from './save-menu.ts';

type SaveMenuModule = typeof import('./index.ts');

let _mod: SaveMenuModule | null = null;
let _loadPromise: Promise<SaveMenuModule> | null = null;

function loadSaveMenu(): Promise<SaveMenuModule> {
    if (_mod) return Promise.resolve(_mod);
    if (!_loadPromise) {
        _loadPromise = import('./index.ts').then((m) => {
            _mod = m;
            return m;
        });
    }
    return _loadPromise;
}

export async function openSaveMenu(options: SaveMenuOptions = {}): Promise<SaveMenu> {
    const m = await loadSaveMenu();
    return m.openSaveMenu(options);
}

export async function openLoadMenu(onLoad: (data: SaveData) => void): Promise<SaveMenu> {
    const m = await loadSaveMenu();
    return m.openLoadMenu(onLoad);
}

export async function openSaveGameMenu(onSave?: (slotId: string) => void): Promise<SaveMenu> {
    const m = await loadSaveMenu();
    return m.openSaveGameMenu(onSave);
}

export async function closeSaveMenu(): Promise<void> {
    if (!_mod) return;
    _mod.closeSaveMenu();
}

export async function isSaveMenuOpen(): Promise<boolean> {
    if (!_mod) return false;
    return _mod.isSaveMenuOpen();
}

export async function showSaveIndicator(duration: number = 2000): Promise<void> {
    const m = await loadSaveMenu();
    m.showSaveIndicator(duration);
}

/** Install window.* stubs that dynamic-import on first call. */
export function installSaveMenuGlobals(): void {
    if (typeof window === 'undefined') return;
    (window as any).openSaveMenu = (options?: SaveMenuOptions) => openSaveMenu(options);
    (window as any).openLoadMenu = (onLoad: (data: SaveData) => void) => openLoadMenu(onLoad);
    (window as any).openSaveGameMenu = (onSave?: (slotId: string) => void) => openSaveGameMenu(onSave);
    (window as any).closeSaveMenu = () => closeSaveMenu();
}

