/**
 * Report geometry deduplication statistics to console
 * Call this after scene initialization to see savings
 */
export function reportGeometryStats(): void {
    const stats = geometryRegistry.getStats();
    const unique = geometryRegistry.getUniqueCount();
    const totalRefs = geometryRegistry.getTotalRefCount();

    log.info('GeometryDedup', '=== Geometry Deduplication Report ===');
    log.info('GeometryDedup', `Cache hits:     ${stats.hits.toLocaleString()}`);
    log.info('GeometryDedup', `Cache misses:   ${stats.misses.toLocaleString()}`);
    log.info('GeometryDedup', `Hit rate:       ${stats.totalRequests > 0 ? ((stats.hits / stats.totalRequests) * 100).toFixed(1) : 0}%`);
    log.info('GeometryDedup', `Unique geometries: ${unique.toLocaleString()}`);
    log.info('GeometryDedup', `Total references:  ${totalRefs.toLocaleString()}`);
    log.info('GeometryDedup', `Memory saved:   ${(stats.memorySaved / 1024 / 1024).toFixed(2)} MB`);
    log.info('GeometryDedup', '=====================================');
}

/**
 * Debug helper - list all registered geometries
 */
export function listRegisteredGeometries(): void {
    const entries = geometryRegistry.getAllEntries();
    log.info('GeometryDedup', '=== Registered Geometries ===');
    entries.forEach(({ key, refCount, type }) => {
        log.info('GeometryDedup', `[${refCount}x] ${type}: ${key.substring(0, 80)}...`);
    });
    log.info('GeometryDedup', `Total: ${entries.length} unique geometries`);
}

// src/utils/geometry-pool.ts
// BufferGeometry object pool — recycles disposed geometry objects so that
// subsequent allocations can reuse pre-existing TypedArray backing memory
// instead of triggering fresh GC-managed heap allocations.
//
// Usage pattern (LOD streaming / chunk lifecycle):
//
//   // Acquire a geometry slot (from pool if available, otherwise brand-new)
//   const geo = geometryPool.acquire('sphere-r1-s16');
//
//   // … populate geo.setAttribute / setIndex as needed …
//
//   // When the chunk is unloaded, return the geometry to the pool
//   geometryPool.release('sphere-r1-s16', geo);
//
// The pool intentionally does NOT dispose the geometry on release —
// it keeps the underlying TypedArray allocations alive so they can be
// reused by the next acquire() call for the same key.  Use
// geometryPool.flush() to free everything when you are sure no further
// reuse will occur (e.g. full scene reset).
//
// For sharing a single immutable geometry among many read-only meshes
// (no LOD churn), prefer the existing GeometryRegistry in geometry-dedup.ts.

import * as THREE from 'three';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface PoolStats {
    /** Number of acquire() calls served from the pool (reuses). */
    hits: number;
    /** Number of acquire() calls that created a fresh geometry. */
    misses: number;
    /** Total number of geometries currently waiting in the pool. */
    pooledCount: number;
    /** Maximum pool depth ever observed for any single key. */
    peakDepth: number;
    /** Estimated bytes saved through reuse (32 bytes per vertex * vertices reused). */
    estimatedBytesSaved: number;
}

// ---------------------------------------------------------------------------
// GeometryPool
// ---------------------------------------------------------------------------

/**
 * Time-budgeted object pool for `THREE.BufferGeometry` instances.
 *
 * Geometries are keyed by an arbitrary string so callers can maintain
 * separate pools for different shapes/resolutions without cross-contamination.
 * A per-key `maxDepth` caps the pool size to prevent unbounded memory growth
 * when many geometries are released but never re-acquired.
 */
export class GeometryPool {
    /** Keyed pools of recycled geometry objects. */
    private readonly pools: Map<string, THREE.BufferGeometry[]> = new Map();

    /** Maximum number of idle geometries kept per key. */
    private readonly maxDepth: number;

    private stats: PoolStats = {
        hits: 0,
        misses: 0,
        pooledCount: 0,
        peakDepth: 0,
        estimatedBytesSaved: 0,
    };

    /**
     * @param maxDepth Maximum idle geometries kept per key.  32 is a sensible
     *   default for typical chunk-streaming windows (≤ 16 visible chunks × 2
     *   geometry types per chunk).  Set lower to limit memory; set higher if
     *   you have many concurrent geometry types and hot reuse patterns.
     */
    constructor(maxDepth: number = 32) {
        this.maxDepth = maxDepth;
    }

    // -----------------------------------------------------------------------
    // Core API
    // -----------------------------------------------------------------------

    /**
     * Acquire a recycled geometry for `key`, or create a new one via `factory`
     * when the pool for that key is empty.
     *
     * @param key     Identifier shared by geometries of the same shape/size.
     * @param factory Called to construct a fresh geometry on a pool miss.
     */
    acquire(key: string, factory: () => THREE.BufferGeometry): THREE.BufferGeometry {
        const pool = this.pools.get(key);
        if (pool && pool.length > 0) {
            const geo = pool.pop()!;
            this.stats.hits++;
            this.stats.pooledCount--;
            this.stats.estimatedBytesSaved += this.estimateBytes(geo);
            return geo;
        }

        this.stats.misses++;
        return factory();
    }

    /**
     * Return a geometry to the pool for future reuse.
     *
     * The geometry is NOT disposed here; its TypedArray attributes are kept
     * alive so the next `acquire()` can overwrite them cheaply.  If the pool
     * for `key` is already at `maxDepth`, the geometry is disposed and
     * discarded to prevent unbounded memory growth.
     *
     * @param key Identifier that was used in the matching `acquire()` call.
     * @param geo The geometry to return.
     */
    release(key: string, geo: THREE.BufferGeometry): void {
        if (!geo) return;

        let pool = this.pools.get(key);
        if (!pool) {
            pool = [];
            this.pools.set(key, pool);
        }

        if (pool.length >= this.maxDepth) {
            // Pool is full — dispose and discard rather than leak memory.
            geo.dispose();
            return;
        }

        pool.push(geo);
        this.stats.pooledCount++;
        if (pool.length > this.stats.peakDepth) {
            this.stats.peakDepth = pool.length;
        }
    }

    // -----------------------------------------------------------------------
    // Maintenance
    // -----------------------------------------------------------------------

    /**
     * Dispose and remove all pooled geometries for a specific key.
     */
    flushKey(key: string): void {
        const pool = this.pools.get(key);
        if (!pool) return;
        for (const geo of pool) geo.dispose();
        this.stats.pooledCount -= pool.length;
        this.pools.delete(key);
    }

    /**
     * Dispose and remove all pooled geometries across every key.
     * Call this on a full scene reset or when navigating away.
     */
    flush(): void {
        for (const [, pool] of this.pools) {
            for (const geo of pool) geo.dispose();
        }
        this.pools.clear();
        this.stats.pooledCount = 0;
    }

    // -----------------------------------------------------------------------
    // Introspection
    // -----------------------------------------------------------------------

    /** Returns a snapshot of the current pool statistics. */
    getStats(): Readonly<PoolStats> {
        return { ...this.stats };
    }

    /** Returns the current depth of the pool for a given key. */
    getDepth(key: string): number {
        return this.pools.get(key)?.length ?? 0;
    }

    /** Returns all keys with at least one pooled geometry. */
    getActiveKeys(): string[] {
        return Array.from(this.pools.entries())
            .filter(([, p]) => p.length > 0)
            .map(([k]) => k);
    }

    /** Logs pool statistics to the console (debug helper). */
    logStats(): void {
        const s = this.getStats();
        const hitRate = s.hits + s.misses > 0
            ? ((s.hits / (s.hits + s.misses)) * 100).toFixed(1)
            : '0.0';
        console.log(
            `[GeometryPool] hits=${s.hits} misses=${s.misses} (${hitRate}% hit rate) ` +
            `pooled=${s.pooledCount} peakDepth=${s.peakDepth} ` +
            `saved≈${(s.estimatedBytesSaved / 1024 / 1024).toFixed(2)}MB`
        );
    }

    // -----------------------------------------------------------------------
    // Private helpers
    // -----------------------------------------------------------------------

    private estimateBytes(geo: THREE.BufferGeometry): number {
        let bytes = 0;
        for (const attr of Object.values(geo.attributes)) {
            if (attr instanceof THREE.BufferAttribute) {
                bytes += attr.array.byteLength;
            }
        }
        if (geo.index) {
            bytes += geo.index.array.byteLength;
        }
        return bytes;
    }
}

// ---------------------------------------------------------------------------
// Global singleton — use this unless you need an isolated pool scope.
// ---------------------------------------------------------------------------

/**
 * Maximum pooled geometries per key for the application-wide pool.
 * 32 covers the typical chunk-streaming window (≤ 16 visible chunks × 2 geometry
 * types per chunk) while preventing unbounded memory growth during burst unloads.
 * Tune this if the scene uses larger streaming windows.
 */
const DEFAULT_MAX_POOL_DEPTH = 32;

/** Application-wide geometry pool. */
export const globalGeometryPool = new GeometryPool(DEFAULT_MAX_POOL_DEPTH);

/**
 * Performance profiler utility
 * Tracks frame timing and displays a debug overlay
 */

interface Measure {
    label: string;
    start: number;
    end?: number;
    duration?: number;
}

interface FrameData {
    frameTime: number;
    measures: Map<string, number>;
}

/**
 * Profiler class for measuring performance
 */
export class Profiler {
    /** Whether profiling is enabled */
    public enabled: boolean;

    /** Map of current measurements by label (label -> duration in ms) */
    public measures: Map<string, number>;

    /** Start time of current frame */
    public frameStart: number;

    /** History of frame times for averaging */
    public frameHistory: number[];

    /** Canvas element for debug UI */
    public canvas: HTMLCanvasElement | null;

    /** Canvas 2D context */
    public ctx: CanvasRenderingContext2D | null;

    constructor() {
        this.enabled = false;
        this.measures = new Map<string, number>();
        this.frameStart = 0;
        this.frameHistory = [];
        this.canvas = null;
        this.ctx = null;
    }

    /**
     * Toggle profiler on/off
     */
    toggle(): void {
        this.enabled = !this.enabled;
        if (this.enabled) {
            this.setupCanvas();
        } else {
            this.cleanupCanvas();
        }
    }

    /**
     * Mark the start of a new frame
     */
    startFrame(): void {
        if (!this.enabled) return;
        this.frameStart = performance.now();
        this.measures.clear();
    }

    /**
     * Measure the execution time of a function
     * @param label - Label for this measurement
     * @param fn - Function to measure
     * @returns The result of the function
     */
    measure<T>(label: string, fn: () => T): T {
        if (!this.enabled) return fn();

        const start = performance.now();
        const result = fn();
        const end = performance.now();

        this.measures.set(label, end - start);
        return result;
    }

    /**
     * Mark the end of the current frame and update history
     */
    endFrame(): void {
        if (!this.enabled || this.frameStart === 0) return;

        const frameTime = performance.now() - this.frameStart;
        this.frameHistory.push(frameTime);

        // Keep last 60 frames
        if (this.frameHistory.length > 60) {
            this.frameHistory.shift();
        }

        this.drawUI();
    }

    /**
     * Draw the profiler debug UI
     */
    drawUI(): void {
        if (!this.ctx || !this.canvas) return;

        const ctx = this.ctx;
        const width = this.canvas.width;
        const height = this.canvas.height;

        // Clear canvas
        ctx.clearRect(0, 0, width, height);

        // Calculate average frame time
        let sum = 0; for (let i = 0; i < this.frameHistory.length; i++) sum += this.frameHistory[i]; const avgFrameTime = sum / this.frameHistory.length;
        const fps = Math.round(1000 / avgFrameTime);

        // Draw background
        ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
        ctx.fillRect(10, 10, 200, 80 + this.measures.size * 20);

        // Draw FPS
        ctx.fillStyle = fps >= 55 ? '#00ff00' : fps >= 30 ? '#ffff00' : '#ff0000';
        ctx.font = 'bold 16px monospace';
        ctx.fillText(`FPS: ${fps}`, 20, 30);

        // Draw frame time
        ctx.fillStyle = '#ffffff';
        ctx.fillText(`Frame: ${avgFrameTime.toFixed(2)}ms`, 20, 50);

        // Draw measurements
        let y = 70;
        this.measures.forEach((duration, label) => {
            ctx.fillStyle = '#aaaaaa';
            ctx.font = '12px monospace';
            ctx.fillText(`${label}: ${duration.toFixed(2)}ms`, 20, y);
            y += 20;
        });
    }

    /**
     * Setup the debug canvas
     */
    private setupCanvas(): void {
        this.canvas = document.createElement('canvas');
        this.canvas.id = 'profiler-canvas';
        this.canvas.width = 220;
        this.canvas.height = 200;
        this.canvas.style.position = 'fixed';
        this.canvas.style.top = '10px';
        this.canvas.style.right = '10px';
        this.canvas.style.zIndex = '9999';
        this.canvas.style.pointerEvents = 'none';

        const ctx = this.canvas.getContext('2d');
        if (ctx) {
            this.ctx = ctx;
        }

        document.body.appendChild(this.canvas);
    }

    /**
     * Remove the debug canvas
     */
    private cleanupCanvas(): void {
        if (this.canvas && this.canvas.parentNode) {
            this.canvas.parentNode.removeChild(this.canvas);
        }
        this.canvas = null;
        this.ctx = null;
    }
}

/** Singleton profiler instance */
export const profiler = new Profiler();

import * as THREE from 'three';


export interface PhaseTiming {
  name: string;
  startTime: number;
  endTime: number;
  duration: number;
  memoryBefore?: number;
  memoryAfter?: number;
  memoryDelta?: number;
}

export interface WebGPUMetrics {
  bufferAllocations: number;
  bufferTotalSize: number;
  shaderCompilations: number;
  shaderCompileTime: number;
  pipelineCreations: number;
}

export interface InstancedMeshMetrics {
  count: number;
  totalInstances: number;
  meshesByType: Map<string, number>;
}

export interface StartupReport {
  timestamp: string;
  userAgent: string;
  totalTime: number;
  phases: PhaseTiming[];
  memory: {
    initial: number;
    peak: number;
    final: number;
    delta: number;
  };
  webgpu: WebGPUMetrics;
  instancedMeshes: InstancedMeshMetrics;
  wasm: {
    assemblyScriptLoaded: boolean;
    emscriptenLoaded: boolean;
    initTime: number;
  };
  tsl: {
    materialCount: number;
    compilePhases: PhaseTiming[];
  };
  /** Warmup batch metrics (populated by recordWarmupMetrics) */
  warmup: {
    batches: number;
    batchMaxMs: number;
  };
  /** Number of generation chunks yielded to the browser (populated by recordGenerationChunk) */
  generationChunksStreamed: number;
  slowPhases: PhaseTiming[];
  warnings: string[];
}

export interface ProfilerConfig {
  slowPhaseThreshold: number; // ms
  enableOverlay: boolean;
  enableConsole: boolean;
  saveToFile: boolean;
  filePath: string;
}

import {
    PhaseTiming,
    InstancedMeshMetrics,
    WebGPUMetrics,
    ProfilerConfig,
} from './startup-profiler-types.ts';
import { formatBytes, formatDuration, getMemoryUsage } from './startup-profiler-utils.ts';
import { uiState, finalizeStartupProfile } from './startup-profiler.ts';

const overlayContainer: HTMLElement | null = null;
const overlayCanvas: HTMLCanvasElement | null = null;
const overlayCtx: CanvasRenderingContext2D | null = null;

/**
 * Snapshot of profiler state needed to render the overlay.
 * Callers push updated state via setProfilerRenderState() whenever
 * the profiler advances (e.g. after endPhase or finalizeStartupProfile).
 */
export interface ProfilerRenderState {
    completedPhases: PhaseTiming[];
    startupStartTime: number;
    memorySnapshots: number[];
    config: ProfilerConfig;
    instancedMeshMetrics: InstancedMeshMetrics;
    webgpuMetrics: WebGPUMetrics;
}

const _defaultRenderState: ProfilerRenderState = {
    completedPhases: [],
    startupStartTime: 0,
    memorySnapshots: [],
    config: {
        slowPhaseThreshold: 100,
        enableOverlay: true,
        enableConsole: true,
        saveToFile: false,
        filePath: '',
    },
    instancedMeshMetrics: { count: 0, totalInstances: 0, meshesByType: new Map() },
    webgpuMetrics: {
        bufferAllocations: 0,
        bufferTotalSize: 0,
        shaderCompilations: 0,
        shaderCompileTime: 0,
        pipelineCreations: 0,
    },
};

let _renderState: ProfilerRenderState = { ..._defaultRenderState };

/** Push a fresh snapshot of profiler state for the overlay renderer to use. */
export function setProfilerRenderState(state: Partial<ProfilerRenderState>): void {
    _renderState = { ..._renderState, ...state };
}

export function createOverlay(): void {
    if (uiState.overlayContainer) return;

    // Container
    uiState.overlayContainer = document.createElement('div');
    uiState.overlayContainer.id = 'startup-profiler-overlay';
    uiState.overlayContainer.style.cssText = `
    position: fixed;
    top: 10px;
    right: 10px;
    z-index: 10000;
    background: rgba(10, 10, 30, 0.95);
    border: 2px solid #FF6B6B;
    border-radius: 12px;
    padding: 16px;
    font-family: 'Segoe UI', system-ui, sans-serif;
    font-size: 13px;
    color: #fff;
    min-width: 320px;
    max-width: 400px;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(8px);
    transition: opacity 0.3s ease;
  `;

    // Header
    const header = document.createElement('div');
    header.style.cssText = `
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
    padding-bottom: 8px;
    border-bottom: 1px solid rgba(255, 107, 107, 0.3);
  `;
    header.innerHTML = `
    <span style="font-weight: bold; font-size: 14px; color: #FF6B6B;">🚀 Startup Profiler</span>
    <button id="startup-profiler-close" style="
      background: none;
      border: none;
      color: #fff;
      cursor: pointer;
      font-size: 18px;
      padding: 0;
      width: 24px;
      height: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 4px;
      transition: background 0.2s;
    ">×</button>
  `;
    uiState.overlayContainer.appendChild(header);

    // Content area
    const content = document.createElement('div');
    content.id = 'startup-profiler-content';
    uiState.overlayContainer.appendChild(content);

    // Canvas for charts
    uiState.overlayCanvas = document.createElement('canvas');
    uiState.overlayCanvas.width = 360;
    uiState.overlayCanvas.height = 200;
    uiState.overlayCanvas.style.cssText = `
    width: 100%;
    height: auto;
    margin-top: 12px;
    border-radius: 6px;
    background: rgba(0, 0, 0, 0.3);
  `;
    uiState.overlayContainer.appendChild(uiState.overlayCanvas);
    uiState.overlayCtx = uiState.overlayCanvas.getContext('2d');

    // Footer with actions
    const footer = document.createElement('div');
    footer.style.cssText = `
    margin-top: 12px;
    padding-top: 8px;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    display: flex;
    gap: 8px;
    font-size: 11px;
  `;
    footer.innerHTML = `
    <button id="startup-profiler-export" style="
      background: #FF6B6B;
      border: none;
      color: white;
      padding: 6px 12px;
      border-radius: 4px;
      cursor: pointer;
      font-size: 11px;
      font-weight: 600;
    ">Export JSON</button>
    <button id="startup-profiler-hide" style="
      background: rgba(255, 255, 255, 0.1);
      border: none;
      color: white;
      padding: 6px 12px;
      border-radius: 4px;
      cursor: pointer;
      font-size: 11px;
    ">Hide</button>
  `;
    uiState.overlayContainer.appendChild(footer);

    document.body.appendChild(uiState.overlayContainer);

    // Event listeners
    document.getElementById('startup-profiler-close')?.addEventListener('click', hideOverlay);
    document.getElementById('startup-profiler-hide')?.addEventListener('click', hideOverlay);
    document.getElementById('startup-profiler-export')?.addEventListener('click', () => {
        // typefix: behaviour-preserving — finalizeStartupProfile() internally calls
        // generateReport() + saveReportToFile() which were previously private.
        finalizeStartupProfile();
    });
}

export function drawOverlay(): void {
    if (!uiState.overlayCtx || !uiState.overlayCanvas) return;

    const ctx = uiState.overlayCtx;
    const canvas = uiState.overlayCanvas;
    const width = canvas.width;
    const height = canvas.height;

    // Clear
    ctx.clearRect(0, 0, width, height);

    // Background
    ctx.fillStyle = 'rgba(0, 0, 0, 0.2)';
    ctx.fillRect(0, 0, width, height);

    // Update content HTML
    const content = document.getElementById('startup-profiler-content');
    if (content) {
        const completedPhases = _renderState.completedPhases;
        const startupStartTime = _renderState.startupStartTime;
        const memorySnapshots = _renderState.memorySnapshots;
        const totalTime =
            completedPhases.length > 0
                ? completedPhases[completedPhases.length - 1].endTime - startupStartTime
                : 0;

        const currentMemory = getMemoryUsage();
        const memoryDelta = currentMemory - (memorySnapshots[0] || 0);

        content.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 8px;">
        <div style="background: rgba(255,255,255,0.05); padding: 8px; border-radius: 6px;">
          <div style="font-size: 10px; color: #888; text-transform: uppercase;">Total Time</div>
          <div style="font-size: 18px; font-weight: bold; color: ${totalTime > 5000 ? '#FF6B6B' : '#4ADE80'};">
            ${formatDuration(totalTime)}
          </div>
        </div>
        <div style="background: rgba(255,255,255,0.05); padding: 8px; border-radius: 6px;">
          <div style="font-size: 10px; color: #888; text-transform: uppercase;">Memory Δ</div>
          <div style="font-size: 18px; font-weight: bold; color: ${memoryDelta > 100 * 1024 * 1024 ? '#FBBF24' : '#4ADE80'};">
            ${formatBytes(memoryDelta)}
          </div>
        </div>
      </div>
      <div style="font-size: 11px; color: #888; margin-bottom: 4px;">Phase Breakdown:</div>
    `;
    }

    // Draw phase bars
    const completedPhases = _renderState.completedPhases;
    const config = _renderState.config;
    const instancedMeshMetrics = _renderState.instancedMeshMetrics;
    const webgpuMetrics = _renderState.webgpuMetrics;
    const maxDuration = Math.max(...completedPhases.map((p: PhaseTiming) => p.duration), 1);
    const barHeight = 20;
    const barSpacing = 4;
    const maxBars = 6;
    const startY = 10;

    completedPhases.slice(-maxBars).forEach((phase: PhaseTiming, index: number) => {
        const y = startY + index * (barHeight + barSpacing);
        const barWidth = (phase.duration / maxDuration) * (width - 120);

        // Bar background
        ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
        ctx.fillRect(80, y, width - 120, barHeight);

        // Bar fill - color based on duration
        if (phase.duration > config.slowPhaseThreshold) {
            ctx.fillStyle = '#FF6B6B'; // Red for slow
        } else if (phase.duration > 50) {
            ctx.fillStyle = '#FBBF24'; // Yellow for medium
        } else {
            ctx.fillStyle = '#4ADE80'; // Green for fast
        }
        ctx.fillRect(80, y, barWidth, barHeight);

        // Phase name (truncated)
        ctx.fillStyle = '#fff';
        ctx.font = '11px sans-serif';
        const shortName = phase.name.length > 12 ? phase.name.substring(0, 12) + '...' : phase.name;
        ctx.fillText(shortName, 4, y + 14);

        // Duration
        ctx.fillStyle = '#aaa';
        ctx.font = '10px monospace';
        ctx.fillText(`${phase.duration.toFixed(0)}ms`, 85 + barWidth + 4, y + 14);
    });

    // Draw warnings
    const slowPhases = completedPhases.filter(
        (p: PhaseTiming) => p.duration > config.slowPhaseThreshold
    );
    if (slowPhases.length > 0) {
        const warningY = startY + maxBars * (barHeight + barSpacing) + 10;
        ctx.fillStyle = '#FF6B6B';
        ctx.font = 'bold 11px sans-serif';
        ctx.fillText(`⚠️ ${slowPhases.length} slow phase(s) detected`, 4, warningY);
    }

    // Draw InstancedMesh count
    const meshY = height - 30;
    ctx.fillStyle = '#888';
    ctx.font = '10px sans-serif';
    ctx.fillText(
        `InstancedMeshes: ${instancedMeshMetrics.count} (${instancedMeshMetrics.totalInstances.toLocaleString()} instances)`,
        4,
        meshY
    );

    // Draw WebGPU metrics
    if (webgpuMetrics.shaderCompilations > 0) {
        ctx.fillText(
            `Shaders: ${webgpuMetrics.shaderCompilations} compiled in ${formatDuration(webgpuMetrics.shaderCompileTime)}`,
            4,
            meshY + 14
        );
    }
}

export function showOverlay(): void {
    if (!uiState.overlayContainer) {
        createOverlay();
    }
    if (uiState.overlayContainer) {
        uiState.overlayContainer.style.display = 'block';
        uiState.overlayContainer.style.opacity = '1';
        drawOverlay();
    }
}

export function hideOverlay(): void {
    if (uiState.overlayContainer) {
        uiState.overlayContainer.style.opacity = '0';
        setTimeout(() => {
            if (uiState.overlayContainer) uiState.overlayContainer.style.display = 'none';
        }, 300);
    }
}

/**
 * Toggle the profiler overlay visibility
 */
export function toggleOverlay(): void {
    if (!overlayContainer || overlayContainer.style.display === 'none') {
        showOverlay();
    } else {
        hideOverlay();
    }
}

export function getMemoryUsage(): number {
  if (typeof window !== 'undefined' && (window.performance as any)?.memory) {
    return (window.performance as any).memory.usedJSHeapSize;
  }
  return 0;
}

export function getMemoryTotal(): number {
  if (typeof window !== 'undefined' && (window.performance as any)?.memory) {
    return (window.performance as any).memory.totalJSHeapSize;
  }
  return 0;
}

export function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 B';
  const k = 1024;
  const sizes = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

export function formatDuration(ms: number): string {
  if (ms < 1) return ms.toFixed(2) + 'ms';
  if (ms < 1000) return ms.toFixed(0) + 'ms';
  return (ms / 1000).toFixed(2) + 's';
}

import { getMemoryUsage, getMemoryTotal, formatBytes, formatDuration } from './startup-profiler-utils.ts';
/**
 * @file startup-profiler.ts
 * @brief Comprehensive startup profiler dashboard for candy_world
 * 
 * Tracks startup phases, memory usage, WebGPU metrics, and shader compilation.
 * Outputs structured JSON report and provides browser overlay visualization.
 */

import * as THREE from 'three';

// ============================================================================
// Types & Interfaces
// ============================================================================
import { getGpuContext } from '../rendering/gpu-context.ts';
import { PhaseTiming, WebGPUMetrics, InstancedMeshMetrics, StartupReport, ProfilerConfig } from './startup-profiler-types.ts';
// ============================================================================
// Configuration
// ============================================================================

const DEFAULT_CONFIG: ProfilerConfig = {
  slowPhaseThreshold: 100, // Phases >100ms are "slow"
  enableOverlay: true,
  enableConsole: true,
  saveToFile: true,
  filePath: '/startup-profile.json',
};

// ============================================================================
// Global State
// ============================================================================

let config: ProfilerConfig = { ...DEFAULT_CONFIG };
let isEnabled = false;
let startupStartTime = 0;
const phases: Map<string, PhaseTiming> = new Map();
let completedPhases: PhaseTiming[] = [];
let warnings: string[] = [];
let memorySnapshots: number[] = [];

// WebGPU tracking
let webgpuMetrics: WebGPUMetrics = {
  bufferAllocations: 0,
  bufferTotalSize: 0,
  shaderCompilations: 0,
  shaderCompileTime: 0,
  pipelineCreations: 0,
};

/** The shared device we have already wrapped (wrap it at most once). */
let instrumentedDevice: GPUDevice | null = null;

// InstancedMesh tracking
let instancedMeshMetrics: InstancedMeshMetrics = {
  count: 0,
  totalInstances: 0,
  meshesByType: new Map(),
};

// WASM tracking
let wasmMetrics = {
  assemblyScriptLoaded: false,
  emscriptenLoaded: false,
  initTime: 0,
  initStartTime: 0,
};

// TSL tracking
let tslMetrics = {
  materialCount: 0,
  compilePhases: [] as PhaseTiming[],
};

// Warmup batch tracking
let warmupMetrics = {
  batches: 0,
  batchMaxMs: 0,
};

// Generation chunk streaming counter
let generationChunksStreamed = 0;

// UI Elements
export const uiState = {
  overlayContainer: null as HTMLElement | null,
  overlayCanvas: null as HTMLCanvasElement | null,
  overlayCtx: null as CanvasRenderingContext2D | null,
};

// Original console methods (for hooking)
let originalConsoleTime: typeof console.time;
let originalConsoleTimeEnd: typeof console.timeEnd;
let originalConsoleLog: typeof console.log;

// InstancedMesh constructor tracking
let originalInstancedMesh: typeof THREE.InstancedMesh;

// ============================================================================
// Console Hook
// ============================================================================

const TRACKED_PHASES = [
  'Core Scene Setup',
  'Audio & Systems Init',
  'World Generation',
  'Deferred Visuals Init',
  'Environmental Effects',
  'Celestial Elements',
  'Musical Elements',
  'WASM Initialization',
  'TSL Material Compilation',
  'Shader Warmup',
  'Map Generation',
];

function hookConsole() {
  originalConsoleTime = console.time;
  originalConsoleTimeEnd = console.timeEnd;
  originalConsoleLog = console.log;

  console.time = (label: string) => {
    if (isEnabled && TRACKED_PHASES.some(p => label.includes(p) || p.includes(label))) {
      startPhase(label);
    }
    return originalConsoleTime.call(console, label);
  };

  console.timeEnd = (label: string) => {
    if (isEnabled && TRACKED_PHASES.some(p => label.includes(p) || p.includes(label))) {
      endPhase(label);
    }
    return originalConsoleTimeEnd.call(console, label);
  };
}

function unhookConsole() {
  if (originalConsoleTime) console.time = originalConsoleTime;
  if (originalConsoleTimeEnd) console.timeEnd = originalConsoleTimeEnd;
}

