    id: string;
    type: string;
    position: Vec3;
    rotation?: MapRotation;
}

export interface LoadedCandyMap {
    source: string;
    data: CandyMapData;
    entities: LoadedMapEntity[];
    getEntitiesByType(type: string): LoadedMapEntity[];
    getEntitiesByBiome(biome: string): LoadedMapEntity[];
    getEntityById(id: string): LoadedMapEntity | undefined;
    getEntitiesByIds(ids: readonly string[], out?: LoadedMapEntity[]): LoadedMapEntity[];
    getEntitiesInBounds(bounds: {
        minX: number;
        minY?: number;
        minZ: number;
        maxX: number;
        maxY?: number;
        maxZ: number;
    }): LoadedMapEntity[];
    getNearestEntities(query: {
        origin: Vec3 | { x: number; z: number };
        radius: number;
        limit?: number;
        priorityTypes?: readonly string[];
        excludeIds?: ReadonlySet<string>;
        out?: LoadedMapEntity[];
    }): LoadedMapEntity[];
    streamEntitiesNear(
        origin: Vec3 | { x: number; z: number },
        maxRadius: number,
        priorityTypes?: readonly string[],
        options?: {
            ringSize?: number;
            chunkSize?: number;
            excludeIds?: ReadonlySet<string>;
        }
    ): IterableIterator<LoadedMapEntity[]>;
    getExpectedInstanceCounts(): Readonly<Record<string, number>>;
}

const MAX_MAP_ENTITIES = 20000;
const DEFAULT_SPATIAL_CELL_SIZE = 40;

interface NearestScratch {
    entity: LoadedMapEntity;
    priorityRank: number;
    distSq: number;
}

const TYPE_ALIASES: Record<string, string> = {
    panningPad: 'panning_pad',
    panningpad: 'panning_pad',
    instrumentShrine: 'instrument_shrine',
    instrumentshrine: 'instrument_shrine',
    kickDrumGeyser: 'kick_drum_geyser',
    snareTrap: 'snare_trap',
    subwooferLotus: 'subwoofer_lotus',
    prismRoseBush: 'prism_rose_bush',
    fiberOpticWillow: 'fiber_optic_willow',
    bubbleWillow: 'bubble_willow',
    gemCanopyTree: 'gem_canopy_tree',
    portamentoPine: 'portamento_pine',
    arpeggioFern: 'arpeggio_fern',
    cymbalDandelion: 'cymbal_dandelion',
    retriggerMushroom: 'retrigger_mushroom',
    vibratoViolet: 'vibrato_violet',
    tremoloTulip: 'tremolo_tulip',
    floatingOrb: 'floating_orb',
    swingableVine: 'swingable_vine',
    vineLadder: 'vine_ladder',
    wisteriaCluster: 'wisteria_cluster',
    silenceSpirit: 'silence_spirit',
    melodyMirror: 'melody_mirror',
};

function normalizeType(type: string): string {
    const trimmed = type.trim();
    return TYPE_ALIASES[trimmed] ?? trimmed;
}

function isFiniteNumber(value: unknown): value is number {
    return typeof value === 'number' && Number.isFinite(value);
}

function asVec3(value: unknown): Vec3 | null {
    if (!Array.isArray(value) || value.length !== 3) return null;
    if (!isFiniteNumber(value[0]) || !isFiniteNumber(value[1]) || !isFiniteNumber(value[2]))
        return null;
    return [value[0], value[1], value[2]];
}

function asQuat(value: unknown): Quat | null {
    if (!Array.isArray(value) || value.length !== 4) return null;
    if (
        !isFiniteNumber(value[0]) ||
        !isFiniteNumber(value[1]) ||
        !isFiniteNumber(value[2]) ||
        !isFiniteNumber(value[3])
    )
        return null;
    return [value[0], value[1], value[2], value[3]];
}

function normalizeRotation(rotation: CandyMapEntity['rotation']): MapRotation | undefined {
    if (rotation === undefined || rotation === null) return undefined;
    if (isFiniteNumber(rotation)) {
        return { euler: [0, rotation, 0], order: 'YXZ' };
    }
    const euler = asVec3(rotation);
    if (euler) {
        return { euler, order: 'YXZ' };
    }
    const quat = asQuat(rotation);
    if (quat) {
        return { quat };
    }
    if (typeof rotation === 'object') {
        const eulerFromObj = asVec3((rotation as MapRotation).euler);
        const quatFromObj = asQuat((rotation as MapRotation).quat);
        if (!eulerFromObj && !quatFromObj) return undefined;
        return {
            euler: eulerFromObj ?? undefined,
            quat: quatFromObj ?? undefined,
            order:
                typeof (rotation as MapRotation).order === 'string'
                    ? (rotation as MapRotation).order
                    : 'YXZ',
        };
    }
    return undefined;
}

function normalizeScale(scale: unknown): MapScale | undefined {
    if (scale === undefined || scale === null) return undefined;
    if (isFiniteNumber(scale)) return scale;
    const vec3 = asVec3(scale);
    if (vec3) return vec3;
    return undefined;
}

function validateMapShape(raw: unknown, source: string): asserts raw is CandyMapData {
    if (!raw || typeof raw !== 'object') {
        throw new Error(`[MapLoader] Invalid map from ${source}: expected JSON object.`);
    }
    const entities = (raw as CandyMapData).entities;
    if (!Array.isArray(entities)) {
        throw new Error(`[MapLoader] Invalid map from ${source}: "entities" must be an array.`);
    }
    const expectedCounts = (raw as CandyMapData).metadata?.expectedInstanceCounts;
    if (expectedCounts !== undefined) {
        if (
            !expectedCounts ||
            typeof expectedCounts !== 'object' ||
            Array.isArray(expectedCounts)
        ) {
            throw new Error(
                `[MapLoader] Invalid map from ${source}: metadata.expectedInstanceCounts must be an object.`
            );
        }
        for (const [type, count] of Object.entries(expectedCounts)) {
            if (typeof type !== 'string' || type.trim().length === 0) {
                throw new Error(
                    `[MapLoader] Invalid expected instance count key "${type}" from ${source}.`
                );
            }
            if (!Number.isInteger(count) || count < 0 || count > 50000) {
                throw new Error(
                    `[MapLoader] Invalid expected instance count for "${type}" from ${source}: must be integer in [0, 50000].`
                );
            }
        }
    }
    if (entities.length > MAX_MAP_ENTITIES) {
        throw new Error(
            `[MapLoader] Invalid map from ${source}: entity cap exceeded (${entities.length}/${MAX_MAP_ENTITIES}).`
        );
    }
    for (let i = 0; i < entities.length; i++) {
        const entity = entities[i] as CandyMapEntity;
        if (!entity || typeof entity !== 'object') {
            throw new Error(`[MapLoader] Invalid entity at index ${i}: expected object.`);
        }
        if (typeof entity.type !== 'string' || entity.type.trim().length === 0) {
            throw new Error(
                `[MapLoader] Invalid entity at index ${i}: "type" must be a non-empty string.`
            );
        }
        const position = asVec3(entity.position);
        if (!position) {
            throw new Error(
                `[MapLoader] Invalid entity "${entity.type}" at index ${i}: "position" must be [x,y,z].`
            );
        }
        if (entity.scale !== undefined && normalizeScale(entity.scale) === undefined) {
            throw new Error(
                `[MapLoader] Invalid entity "${entity.type}" at index ${i}: "scale" must be number or [x,y,z].`
            );
        }
        if (entity.rotation !== undefined && normalizeRotation(entity.rotation) === undefined) {
            throw new Error(
                `[MapLoader] Invalid entity "${entity.type}" at index ${i}: unsupported rotation shape.`
            );
        }
        if (entity.music !== undefined) {
            validateMusicHints(
                entity.music,
                `[MapLoader] Invalid music hints for entity "${entity.type}" at index ${i}`
            );
        }
    }

    const regions = (raw as CandyMapData).regions;
    if (regions !== undefined) {
        if (!Array.isArray(regions)) {
            throw new Error(
                `[MapLoader] Invalid map from ${source}: "regions" must be an array when provided.`
            );
        }
        for (let i = 0; i < regions.length; i++) {
            const region = regions[i];
            if (!region || typeof region !== 'object') {
                throw new Error(`[MapLoader] Invalid region at index ${i}: expected object.`);
            }
            if (typeof region.id !== 'string' || region.id.trim().length === 0) {
                throw new Error(
                    `[MapLoader] Invalid region at index ${i}: "id" must be a non-empty string.`
                );
            }
            if (
                !region.bounds ||
                typeof region.bounds !== 'object' ||
                !Array.isArray(region.bounds.min) ||
                !Array.isArray(region.bounds.max) ||
                region.bounds.min.length !== 2 ||
                region.bounds.max.length !== 2 ||
                !isFiniteNumber(region.bounds.min[0]) ||
                !isFiniteNumber(region.bounds.min[1]) ||
                !isFiniteNumber(region.bounds.max[0]) ||
                !isFiniteNumber(region.bounds.max[1])
            ) {
                throw new Error(
                    `[MapLoader] Invalid region "${region.id}": bounds must be { min:[x,z], max:[x,z] }.`
                );
            }
            if (region.music !== undefined) {
                validateMusicHints(
                    region.music,
                    `[MapLoader] Invalid music hints for region "${region.id}"`
                );
            }
        }
    }

    const mapMusic = (raw as CandyMapData).music;
    if (mapMusic !== undefined) {
        validateMapMusicOverrides(mapMusic, '[MapLoader] Invalid map-level music overrides');
    }
}

function validateChannelList(value: unknown, context: string): void {
    if (!Array.isArray(value)) throw new Error(`${context}: expected integer array.`);
    for (let i = 0; i < value.length; i++) {
        const channel = value[i];
        if (!Number.isInteger(channel) || channel < 0 || channel > 255) {
            throw new Error(
                `${context}: channel "${channel}" at index ${i} is out of range (0-255 integer).`
            );
        }
    }
}

function validateMusicHints(raw: unknown, context: string): asserts raw is MapMusicHints {
    if (!raw || typeof raw !== 'object') throw new Error(`${context}: expected object.`);
    const hints = raw as MapMusicHints;
    if (hints.channels !== undefined) validateChannelList(hints.channels, `${context}.channels`);
    if (
        hints.intensityScale !== undefined &&
        (!isFiniteNumber(hints.intensityScale) ||
            hints.intensityScale < 0 ||
            hints.intensityScale > 10)
    ) {
        throw new Error(`${context}.intensityScale must be a finite number in [0, 10].`);
    }
    if (
        hints.trackerChannel !== undefined &&
        (!Number.isInteger(hints.trackerChannel) ||
            hints.trackerChannel < 0 ||
            hints.trackerChannel > 255)
    ) {
        throw new Error(`${context}.trackerChannel must be an integer in [0, 255].`);
    }
}

function validateMapMusicOverrides(
    raw: unknown,
    context: string
): asserts raw is MapMusicOverrides {
    if (!raw || typeof raw !== 'object') throw new Error(`${context}: expected object.`);
    const overrides = raw as MapMusicOverrides;

    if (overrides.biomes !== undefined) {
        if (typeof overrides.biomes !== 'object' || Array.isArray(overrides.biomes)) {
            throw new Error(`${context}.biomes must be an object.`);
        }
        for (const [biome, binding] of Object.entries(overrides.biomes)) {
            if (!binding || typeof binding !== 'object') {
                throw new Error(`${context}.biomes.${biome} must be an object.`);
            }
            const candidate = binding as MapMusicChannelBinding;
            if (candidate.shimmer !== undefined)
                validateChannelList(candidate.shimmer, `${context}.biomes.${biome}.shimmer`);
            if (candidate.hueShift !== undefined)
                validateChannelList(candidate.hueShift, `${context}.biomes.${biome}.hueShift`);
            if (candidate.noteColor !== undefined)
                validateChannelList(candidate.noteColor, `${context}.biomes.${biome}.noteColor`);
            if (candidate.amplitudeScale !== undefined)
                validateChannelList(
                    candidate.amplitudeScale,
                    `${context}.biomes.${biome}.amplitudeScale`
                );
            if (candidate.intensity !== undefined)
                validateChannelList(candidate.intensity, `${context}.biomes.${biome}.intensity`);
            if (
                candidate.intensityScale !== undefined &&
                (!isFiniteNumber(candidate.intensityScale) ||
                    candidate.intensityScale < 0 ||
                    candidate.intensityScale > 10)
            ) {
                throw new Error(
                    `${context}.biomes.${biome}.intensityScale must be a finite number in [0, 10].`
                );
            }
        }
    }

    if (overrides.skyMoon?.melodyChannel !== undefined) {
        const channel = overrides.skyMoon.melodyChannel;
        if (!Number.isInteger(channel) || channel < 0 || channel > 255) {
            throw new Error(`${context}.skyMoon.melodyChannel must be an integer in [0, 255].`);
        }
    }
    if (overrides.luminousPlants?.trackerChannel !== undefined) {
        const channel = overrides.luminousPlants.trackerChannel;
        if (!Number.isInteger(channel) || channel < 0 || channel > 255) {
            throw new Error(
                `${context}.luminousPlants.trackerChannel must be an integer in [0, 255].`
            );
        }
    }
    if (
        overrides.skyWave?.targetBiomes !== undefined &&
        !Array.isArray(overrides.skyWave.targetBiomes)
    ) {
        throw new Error(`${context}.skyWave.targetBiomes must be an array of strings.`);
    }

    const weather = overrides.weatherReactivity;
    if (weather && typeof weather === 'object') {
        for (const [name, binding] of Object.entries(weather)) {
            if (!binding || typeof binding !== 'object') continue;
            const typed = binding as MapWeatherBinding;
            if (
                typed.channel !== undefined &&
                (!Number.isInteger(typed.channel) || typed.channel < 0 || typed.channel > 255)
            ) {
                throw new Error(
                    `${context}.weatherReactivity.${name}.channel must be an integer in [0, 255].`
                );
            }
            if (
                typed.smoothing !== undefined &&
                (!isFiniteNumber(typed.smoothing) || typed.smoothing <= 0 || typed.smoothing > 10)
            ) {
                throw new Error(
                    `${context}.weatherReactivity.${name}.smoothing must be in (0, 10].`
                );
            }
            if (
                typed.scale !== undefined &&
                (!isFiniteNumber(typed.scale) || typed.scale < 0 || typed.scale > 10)
            ) {
                throw new Error(`${context}.weatherReactivity.${name}.scale must be in [0, 10].`);
            }
        }
    }
}

function isV1Map(data: CandyMapData): boolean {
    const version = data.metadata?.version;
    if (version === undefined || version === null || version === '') return true;
    if (typeof version === 'number') return Math.floor(version) === 1;
    const trimmed = String(version).trim();
    if (trimmed === '1') return true;
    const numericPrefix = Number(trimmed.split('.')[0]);
    if (Number.isFinite(numericPrefix)) return numericPrefix === 1;
    return trimmed.startsWith('1.');
}

function hasSetpieceLayer(data: CandyMapData, layer: string): boolean {
    return data.entities.some(
        (entity) => entity.layer === layer || entity.id?.startsWith(`setpiece:${layer}:`)
    );
}

function getEntityPosition(entity: CandyMapEntity): Vec3 | null {
    return asVec3(entity.position);
}

function hasEntityNear(
    entities: CandyMapEntity[],
    type: string,
    centerX: number,
    centerZ: number,
    radius: number
): boolean {
    const radiusSq = radius * radius;
    return entities.some((entity) => {
        if (normalizeType(entity.type) !== type) return false;
        const position = getEntityPosition(entity);
        if (!position) return false;
        const dx = position[0] - centerX;
        const dz = position[2] - centerZ;
        return dx * dx + dz * dz <= radiusSq;
    });
}

function addLegacySetpieces(base: CandyMapData): CandyMapData {
    if (!isV1Map(base)) return base;

    const entities = [...base.entities];
    const groveLayer = 'setpiece-arpeggio-grove';
    const lakeLayer = 'setpiece-lake-island';
    const caveLayer = 'setpiece-cave';

    if (
        !entities.some((entity) => normalizeType(entity.type) === 'cave') &&
        !hasSetpieceLayer(base, caveLayer)
    ) {
        entities.push({
            id: 'setpiece:cave:entrance',
            type: 'cave',
            category: 'setpiece',
            layer: caveLayer,
            biome: 'lake',
            position: [25, 0, 25],
            params: { lookAtOrigin: true, scale: 2.0 },
            critical: true,
        });
    }

    const hasArpeggioSignature =
        hasEntityNear(
            entities,
            'subwoofer_lotus',
            ARPEGGIO_GROVE_SETPIECE.centerX,
            ARPEGGIO_GROVE_SETPIECE.centerZ,
            ARPEGGIO_GROVE_SETPIECE.radius * 0.9
        ) ||
        hasEntityNear(
            entities,
            'arpeggio_fern',
            ARPEGGIO_GROVE_SETPIECE.centerX,
            ARPEGGIO_GROVE_SETPIECE.centerZ,
            ARPEGGIO_GROVE_SETPIECE.radius
        );

    if (!hasSetpieceLayer(base, groveLayer) && !hasArpeggioSignature) {
        const { centerX, centerZ, radius } = ARPEGGIO_GROVE_SETPIECE;
        entities.push({
            id: 'setpiece:arpeggio:lotus',
            type: 'subwoofer_lotus',
            category: 'setpiece',
            layer: groveLayer,
            biome: 'arpeggio_grove',
            position: [centerX, 0, centerZ],
            scale: 1.5,
            music: { biomeTag: 'arpeggio_grove' },
            critical: true,
        });
        const fernCount = 7;
        const fernRadius = radius * 0.4;
        for (let i = 0; i < fernCount; i++) {
            const angle = (i / fernCount) * Math.PI * 2;
            entities.push({
                id: `setpiece:arpeggio:fern:${i}`,
                type: 'arpeggio_fern',
                category: 'setpiece',
                layer: groveLayer,
                biome: 'arpeggio_grove',
                position: [
                    centerX + Math.cos(angle) * fernRadius,
                    0,
                    centerZ + Math.sin(angle) * fernRadius,
                ],
                scale: 1.1,
                rotation: { euler: [0, angle + Math.PI, 0], order: 'YXZ' },
                music: { biomeTag: 'arpeggio_grove' },
                critical: true,
            });
        }
        const outerCount = 4;
        const outerRadius = radius * 0.8;
        for (let i = 0; i < outerCount; i++) {
            const angle = (i / outerCount) * Math.PI * 2 + 0.2;
            const common = {
                category: 'setpiece',
                layer: groveLayer,
                biome: 'arpeggio_grove',
                position: [
                    centerX + Math.cos(angle) * outerRadius,
                    0,
                    centerZ + Math.sin(angle) * outerRadius,
                ] as Vec3,
                music: { biomeTag: 'arpeggio_grove' },
                critical: true,
            };
            if (i % 2 === 0) {
                entities.push({
                    id: `setpiece:arpeggio:geyser:${i}`,
                    type: 'kick_drum_geyser',
                    ...common,
                });
            } else {
                entities.push({
                    id: `setpiece:arpeggio:violet:${i}`,
                    type: 'vibrato_violet',
                    ...common,
                });
            }
        }
    }

    const hasLakeSignature =
        hasEntityNear(
            entities,
            'retrigger_mushroom',
            LAKE_ISLAND_SETPIECE.centerX,
            LAKE_ISLAND_SETPIECE.centerZ,
            LAKE_ISLAND_SETPIECE.radius * 0.9
        ) ||
        hasEntityNear(
            entities,
            'kick_drum_geyser',
            LAKE_ISLAND_SETPIECE.centerX,
            LAKE_ISLAND_SETPIECE.centerZ,
            LAKE_ISLAND_SETPIECE.radius
        );

    if (!hasSetpieceLayer(base, lakeLayer) && !hasLakeSignature) {
        const { centerX, centerZ, radius } = LAKE_ISLAND_SETPIECE;
        entities.push({
            id: 'setpiece:lake:core',
            type: 'retrigger_mushroom',
            category: 'setpiece',
            layer: lakeLayer,
            biome: 'lake',
            position: [centerX, 0, centerZ],
            scale: 1.5,
            params: { retriggerSpeed: 4, color: 0x00ffff },
            critical: true,
        });
        const geyserCount = 6;
        for (let i = 0; i < geyserCount; i++) {
            const angle = (i / geyserCount) * Math.PI * 2;
            entities.push({
                id: `setpiece:lake:geyser:${i}`,
                type: 'kick_drum_geyser',
                category: 'setpiece',
                layer: lakeLayer,
                biome: 'lake',
                position: [
                    centerX + Math.cos(angle) * radius * 0.7,
                    0,
                    centerZ + Math.sin(angle) * radius * 0.7,
                ],
                rotation: { euler: [0, angle + Math.PI, 0], order: 'YXZ' },
            });
        }
    }

    return {
        ...base,
        entities,
    };
}

function normalizeEntity(entity: CandyMapEntity, index: number): LoadedMapEntity {
    const type = normalizeType(entity.type);
    const placement = entity.placement ?? (type === 'cloud' ? 'absolute' : 'ground');
    const biome = entity.biome ?? entity.music?.biomeTag;
    const params = entity.params && typeof entity.params === 'object' ? entity.params : undefined;
    return {
        ...entity,
        id: entity.id ?? `${type}_${index}`,
        type,
        position: asVec3(entity.position)!,
        rotation: normalizeRotation(entity.rotation),
        scale: normalizeScale(entity.scale),
        placement,
        biome,
        music: normalizeMusicHints(entity.music),
        params,
    };
}

function normalizeMusicHints(raw: CandyMapEntity['music']): CandyMapEntity['music'] | undefined {
    if (!raw || typeof raw !== 'object') return undefined;
    const biome = raw.biomeOverride ?? raw.biome ?? raw.biomeTag;
    return {
        ...raw,
        biome: biome ?? raw.biome,
        biomeTag: biome ?? raw.biomeTag,
    };
}

function getOriginXZ(origin: Vec3 | { x: number; z: number }): { x: number; z: number } {
    if (Array.isArray(origin)) {
        return { x: origin[0], z: origin[2] };
    }
    return { x: origin.x, z: origin.z };
}

function cellKey(cellX: number, cellZ: number): string {
    return `${cellX},${cellZ}`;
}

function toCellCoord(value: number, cellSize: number): number {
    return Math.floor(value / cellSize);
}

class LoadedCandyMapImpl implements LoadedCandyMap {
    source: string;
    data: CandyMapData;
    entities: LoadedMapEntity[];
    private cellSize: number;
    private cellIndex: Map<string, LoadedMapEntity[]> = new Map();
    private byType: Map<string, LoadedMapEntity[]> = new Map();
    private byBiome: Map<string, LoadedMapEntity[]> = new Map();
    private byId: Map<string, LoadedMapEntity> = new Map();
    private nearestScratch: NearestScratch[] = [];
    private nearestScratchCount: number = 0;
    private streamScratch: LoadedMapEntity[] = [];
    private streamChunkScratch: LoadedMapEntity[] = [];
    private expectedInstanceCounts: Readonly<Record<string, number>>;

    constructor(source: string, data: CandyMapData, entities: LoadedMapEntity[]) {
        this.source = source;
        this.data = data;
        this.entities = entities;
        this.cellSize = DEFAULT_SPATIAL_CELL_SIZE;
        this.buildIndexes();
        this.expectedInstanceCounts = this.buildExpectedInstanceCounts();
    }

    private buildExpectedInstanceCounts(): Readonly<Record<string, number>> {
        const explicit = this.data.metadata?.expectedInstanceCounts;
        if (explicit && typeof explicit === 'object') {
            const normalized: Record<string, number> = {};
            for (const [rawType, value] of Object.entries(explicit)) {
                if (!Number.isInteger(value) || value < 0) continue;
                normalized[normalizeType(rawType)] = value;
            }
            return normalized;
        }
        const derived: Record<string, number> = {};
        for (const entity of this.entities) {
            derived[entity.type] = (derived[entity.type] ?? 0) + 1;
        }
        return derived;
    }

    private buildIndexes(): void {
        for (const entity of this.entities) {
            this.byId.set(entity.id, entity);

            const typeList = this.byType.get(entity.type);
            if (typeList) typeList.push(entity);
            else this.byType.set(entity.type, [entity]);

            const biomeTag = entity.biome ?? entity.music?.biomeTag;
            if (biomeTag) {
                const biomeList = this.byBiome.get(biomeTag);
                if (biomeList) biomeList.push(entity);
                else this.byBiome.set(biomeTag, [entity]);
            }

            const [x, , z] = entity.position;
            const cx = toCellCoord(x, this.cellSize);
            const cz = toCellCoord(z, this.cellSize);
            const key = cellKey(cx, cz);
            const cellEntities = this.cellIndex.get(key);
            if (cellEntities) {
                cellEntities.push(entity);
            } else {
                this.cellIndex.set(key, [entity]);
            }
        }
    }

    getEntitiesByType(type: string): LoadedMapEntity[] {
        const normalized = normalizeType(type);
        return this.byType.get(normalized) ?? [];
    }

    getEntitiesByBiome(biome: string): LoadedMapEntity[] {
        return this.byBiome.get(biome) ?? [];
    }

    getEntityById(id: string): LoadedMapEntity | undefined {
        return this.byId.get(id);
    }

    getEntitiesByIds(ids: readonly string[], out: LoadedMapEntity[] = []): LoadedMapEntity[] {
        out.length = 0;
        for (let i = 0; i < ids.length; i++) {
            const entity = this.byId.get(ids[i]);
            if (entity) out.push(entity);
        }
        return out;
    }

    getEntitiesInBounds(bounds: {
        minX: number;
        minY?: number;
        minZ: number;
        maxX: number;
        maxY?: number;
        maxZ: number;
    }): LoadedMapEntity[] {
        const minY = bounds.minY ?? Number.NEGATIVE_INFINITY;
        const maxY = bounds.maxY ?? Number.POSITIVE_INFINITY;
        return this.getNearestEntities({
            origin: { x: (bounds.minX + bounds.maxX) * 0.5, z: (bounds.minZ + bounds.maxZ) * 0.5 },
            // Half the diagonal covers the box from its center — the exact
            // filter below keeps results correct either way, this just
            // trims the number of spatial cells scanned to find them.
            radius: Math.hypot(bounds.maxX - bounds.minX, bounds.maxZ - bounds.minZ) * 0.5,
            out: [],
        }).filter((entity) => {
            const [x, y, z] = entity.position;
            return (
                x >= bounds.minX &&
                x <= bounds.maxX &&
                y >= minY &&
                y <= maxY &&
                z >= bounds.minZ &&
                z <= bounds.maxZ
            );
        });
    }

    getNearestEntities(query: {
        origin: Vec3 | { x: number; z: number };
        radius: number;
        limit?: number;
        priorityTypes?: readonly string[];
        excludeIds?: ReadonlySet<string>;
        out?: LoadedMapEntity[];
    }): LoadedMapEntity[] {
        const { x: originX, z: originZ } = getOriginXZ(query.origin);
        const radius = Math.max(0, query.radius);
        const radiusSq = radius * radius;
        const maxCount = query.limit ?? Number.POSITIVE_INFINITY;
        const out = query.out ?? [];
        out.length = 0;

        const priorityMap = new Map<string, number>();
        if (query.priorityTypes) {
            for (let i = 0; i < query.priorityTypes.length; i++) {
                priorityMap.set(normalizeType(query.priorityTypes[i]), i);
            }
        }
        const defaultRank = priorityMap.size + 1;

        let minCellX = Number.NEGATIVE_INFINITY;
        let maxCellX = Number.POSITIVE_INFINITY;
        let minCellZ = Number.NEGATIVE_INFINITY;
        let maxCellZ = Number.POSITIVE_INFINITY;
        if (Number.isFinite(radius)) {
            minCellX = toCellCoord(originX - radius, this.cellSize);
            maxCellX = toCellCoord(originX + radius, this.cellSize);
            minCellZ = toCellCoord(originZ - radius, this.cellSize);
            maxCellZ = toCellCoord(originZ + radius, this.cellSize);
        }

        this.nearestScratchCount = 0;
        if (Number.isFinite(radius)) {
            for (let cz = minCellZ; cz <= maxCellZ; cz++) {
                for (let cx = minCellX; cx <= maxCellX; cx++) {
                    const cellEntities = this.cellIndex.get(cellKey(cx, cz));
                    if (!cellEntities) continue;
                    for (const entity of cellEntities) {
                        if (query.excludeIds?.has(entity.id)) continue;
                        const dx = entity.position[0] - originX;
                        const dz = entity.position[2] - originZ;
                        const distSq = dx * dx + dz * dz;
                        if (distSq > radiusSq) continue;
                        const rank = priorityMap.get(entity.type) ?? defaultRank;
                        const slot = this.nearestScratch[this.nearestScratchCount] ?? {
                            entity,
                            priorityRank: rank,
                            distSq,
                        };
                        slot.entity = entity;
                        slot.priorityRank = rank;
                        slot.distSq = distSq;
                        this.nearestScratch[this.nearestScratchCount] = slot;
                        this.nearestScratchCount++;
                    }
                }
            }
        } else {
            for (const entity of this.entities) {
                if (query.excludeIds?.has(entity.id)) continue;
                const dx = entity.position[0] - originX;
                const dz = entity.position[2] - originZ;
                const distSq = dx * dx + dz * dz;
                const rank = priorityMap.get(entity.type) ?? defaultRank;
                const slot = this.nearestScratch[this.nearestScratchCount] ?? {
                    entity,
                    priorityRank: rank,
                    distSq,
                };
                slot.entity = entity;
                slot.priorityRank = rank;
                slot.distSq = distSq;
                this.nearestScratch[this.nearestScratchCount] = slot;
                this.nearestScratchCount++;
            }
        }

        this.nearestScratch.length = this.nearestScratchCount;
        this.nearestScratch.sort((a, b) => {
            if (a.priorityRank !== b.priorityRank) return a.priorityRank - b.priorityRank;
            return a.distSq - b.distSq;
        });

        const count = Math.min(this.nearestScratchCount, maxCount);
        for (let i = 0; i < count; i++) {
            out.push(this.nearestScratch[i].entity);
        }
        return out;
    }

    *streamEntitiesNear(
        origin: Vec3 | { x: number; z: number },
        maxRadius: number,
        priorityTypes?: readonly string[],
        options?: {
            ringSize?: number;
            chunkSize?: number;
            excludeIds?: ReadonlySet<string>;
        }
    ): IterableIterator<LoadedMapEntity[]> {
        const ringSize = Math.max(8, options?.ringSize ?? 36);
        const chunkSize = Math.max(10, options?.chunkSize ?? 40);
        const { x: originX, z: originZ } = getOriginXZ(origin);
        const ordered = this.getNearestEntities({
            origin,
            radius: maxRadius,
            priorityTypes,
            excludeIds: options?.excludeIds,
            out: this.streamScratch,
        });

        let currentRing = -1;
        let currentChunkSize = 0;
        this.streamChunkScratch.length = 0;
        for (const entity of ordered) {
            const dx = entity.position[0] - originX;
            const dz = entity.position[2] - originZ;
            const ring = Math.floor(Math.hypot(dx, dz) / ringSize);
            if ((currentRing !== -1 && ring !== currentRing) || currentChunkSize >= chunkSize) {
                yield [...this.streamChunkScratch];
                this.streamChunkScratch.length = 0;
                currentChunkSize = 0;
            }
            currentRing = ring;
            this.streamChunkScratch.push(entity);
            currentChunkSize++;
        }
        if (this.streamChunkScratch.length > 0) {
            yield [...this.streamChunkScratch];
            this.streamChunkScratch.length = 0;
        }
    }

    getExpectedInstanceCounts(): Readonly<Record<string, number>> {
        return this.expectedInstanceCounts;
    }
}

async function fetchMapJson(source: string): Promise<unknown> {
    if (typeof window === 'undefined') {
        throw new Error('[MapLoader] String map sources require a browser environment.');
    }
    const url = new URL(source, window.location.href);
    if (url.origin !== window.location.origin) {
        throw new Error(`[MapLoader] Refusing cross-origin map source: ${source}`);
    }
    const response = await fetch(url.toString(), { credentials: 'same-origin' });
    if (!response.ok) {
        throw new Error(
            `[MapLoader] Failed to load map "${source}" (${response.status} ${response.statusText})`
        );
    }
    return response.json();
}

export function getMapSourceFromUrl(
    defaultSource: string = new URL('../../assets/map.json', import.meta.url).href
): string {
    if (typeof window === 'undefined') return defaultSource;
    const params = new URLSearchParams(window.location.search);
    const fromQuery = params.get('map');
    if (!fromQuery || fromQuery.trim().length === 0) return defaultSource;
    return fromQuery;
}

export async function loadMap(source: string | CandyMapData): Promise<LoadedCandyMap> {
    const sourceLabel = typeof source === 'string' ? source : '[inline-map]';
    const raw = typeof source === 'string' ? await fetchMapJson(source) : source;
    validateMapShape(raw, sourceLabel);
    const withSetpieces = addLegacySetpieces(raw);
    validateMapShape(withSetpieces, sourceLabel);

    const entities = withSetpieces.entities.map((entity, index) => normalizeEntity(entity, index));
    const data: CandyMapData = {
        ...withSetpieces,
        metadata: {
            ...withSetpieces.metadata,
            version: withSetpieces.metadata?.version ?? '1.0',
        },
        entities,
        music: withSetpieces.music,
    };

    return new LoadedCandyMapImpl(sourceLabel, data, entities);
}

// --- Build-time spatial chunk index (assets/map-chunks.json) ---
// Produced by tools/map-generator/build-chunk-index.ts. Maps "cx,cz" chunk keys
// (world position divided by chunkSize, floored) to the entity ids inside that
// chunk, so ChunkStreamer can look up "what's near the spawn tile" without
// scanning every entity in the map. A reserved "__meta__" key carries the
// chunk size and total indexed entity count used for the CI parity check.
//
// Single source of truth for the chunk grid size — chunk-streamer.ts and
// build-chunk-index.ts both import this instead of redeclaring "32" so the
// index and the runtime grid can never silently disagree.
export const DEFAULT_MAP_CHUNK_STREAM_SIZE = 32;

export interface MapChunkIndex {
    chunkSize: number;
    entityCount: number;
    chunks: Map<string, string[]>;
}

interface RawMapChunkIndexFile {
    __meta__?: { chunkSize?: number; entityCount?: number };
    [chunkKey: string]: unknown;
}

const CHUNK_INDEX_META_KEY = '__meta__';

/**
 * Fetch and parse the build-time chunk index. Returns null (never throws) when
 * the artifact is missing, stale, or malformed — callers must fall back to
 * computing chunk membership from the loaded map directly (dev / hot-reload
 * without a regenerated index).
 */
export async function loadMapChunkIndex(
    source: string = new URL('../../assets/map-chunks.json', import.meta.url).href
): Promise<MapChunkIndex | null> {
    try {
        const raw = (await fetchMapJson(source)) as RawMapChunkIndexFile;
        if (!raw || typeof raw !== 'object') return null;
        const meta = raw[CHUNK_INDEX_META_KEY];
        const chunkSize =
            typeof meta?.chunkSize === 'number' && meta.chunkSize > 0
                ? meta.chunkSize
                : DEFAULT_MAP_CHUNK_STREAM_SIZE;
        const entityCount = typeof meta?.entityCount === 'number' ? meta.entityCount : -1;

        const chunks = new Map<string, string[]>();
        for (const [key, value] of Object.entries(raw)) {
            if (key === CHUNK_INDEX_META_KEY) continue;
            if (!Array.isArray(value)) continue;
            const ids = value.filter((v): v is string => typeof v === 'string');
            chunks.set(key, ids);
        }
        if (chunks.size === 0) return null;
        return { chunkSize, entityCount, chunks };
    } catch (error) {
        console.warn(
            `[MapLoader] Chunk index unavailable (${source}); falling back to bounding-box queries.`,
            error
        );
        return null;
    }
}

export function setupMapHotReload(source: string, onReload: () => void): void {
    const hot = (import.meta as any).hot;
    if (!hot || typeof source !== 'string') return;
    hot.on('vite:beforeUpdate', (payload: { updates?: Array<{ path?: string }> }) => {
        if (!payload?.updates) return;
        const normalizedSource = source.replace(/^\.\//, '').replace(/^\//, '');
        const shouldReload = payload.updates.some((update) => {
            const path = update.path ?? '';
            return path.endsWith(normalizedSource) || path.endsWith(source);
        });
        if (shouldReload) onReload();
    });
}

/**
 * @file src/world/sky-island-graph.ts
 * @brief Connectivity graph for stacked sky islands (#1363).
 *
 * Nodes = islands / cloud hops / lift pads.
 * Edges = vine ladders, cloud hops, music-reactive lift pads.
 * Debug viz via `?debugIslands=1`.
 */

import * as THREE from 'three';
import { safeRemoveAndDispose } from '../utils/dispose-utils';

export type SkyIslandEdgeKind = 'vine_ladder' | 'cloud_hop' | 'lift_pad' | 'approach';

export interface SkyIslandNode {
    id: string;
    layerId: string;
    x: number;
    y: number;
    z: number;
    kind: 'island' | 'cloud' | 'pad' | 'ground';
}

export interface SkyIslandEdge {
    id: string;
    from: string;
    to: string;
    kind: SkyIslandEdgeKind;
}

const _nodes = new Map<string, SkyIslandNode>();
const _edges: SkyIslandEdge[] = [];

let _debugEnabled = false;
let _scene: THREE.Scene | null = null;
let _edgeLines: THREE.LineSegments | null = null;
let _nodeMarkers: THREE.InstancedMesh | null = null;

function isDebugFlagEnabled(): boolean {
    try {
        return new URLSearchParams(window.location.search).get('debugIslands') === '1';
    } catch {
        return false;
    }
}

export function clearSkyIslandGraph(): void {
    _nodes.clear();
    _edges.length = 0;
    disposeDebugMeshes();
}

export function registerSkyIslandNode(node: SkyIslandNode): void {
    _nodes.set(node.id, node);
}

export function registerSkyIslandEdge(edge: SkyIslandEdge): void {
    const existing = _edges.findIndex(e => e.id === edge.id);
    if (existing >= 0) _edges[existing] = edge;
    else _edges.push(edge);
}

export function getSkyIslandNodes(): readonly SkyIslandNode[] {
    return Array.from(_nodes.values());
}

export function getSkyIslandEdges(): readonly SkyIslandEdge[] {
    return _edges;
}

/** Validate that every edge references known nodes and Y increases along climb edges. */
export function validateSkyIslandGraph(): { ok: boolean; errors: string[] } {
    const errors: string[] = [];
    for (const edge of _edges) {
        const from = _nodes.get(edge.from);
        const to = _nodes.get(edge.to);
        if (!from) errors.push(`edge ${edge.id}: missing from node ${edge.from}`);
        if (!to) errors.push(`edge ${edge.id}: missing to node ${edge.to}`);
        if (from && to && edge.kind === 'vine_ladder' && to.y <= from.y) {
            errors.push(`edge ${edge.id}: vine ladder should climb (to.y ${to.y} <= from.y ${from.y})`);
        }
    }
    return { ok: errors.length === 0, errors };
}

/**
 * Sample a synthetic traversal path: ground → lowest island → highest.
 * Used by unit tests as a #1265 regression guard (platform Y preserved).
 */
export function buildTraversalWaypoints(): Array<{ x: number; y: number; z: number; id: string }> {
    const islands = Array.from(_nodes.values())
        .filter(n => n.kind === 'island' || n.kind === 'cloud')
        .sort((a, b) => a.y - b.y);
    if (islands.length === 0) return [];
    const path: Array<{ x: number; y: number; z: number; id: string }> = [
        { x: islands[0].x, y: 2.0, z: islands[0].z, id: 'spawn_ground' },
    ];
    for (const n of islands) {
        path.push({ x: n.x, y: n.y, z: n.z, id: n.id });
    }
    // Return descent
    for (let i = islands.length - 2; i >= 0; i--) {
        path.push({ x: islands[i].x, y: islands[i].y, z: islands[i].z, id: `return:${islands[i].id}` });
    }
    path.push({ x: islands[0].x, y: 2.0, z: islands[0].z, id: 'return_ground' });
    return path;
}

function disposeDebugMeshes(): void {
    // ⚡ OPTIMIZATION: Replaced manual scene.remove with safeRemoveAndDispose to prevent VRAM leaks.
    if (_edgeLines && _scene) {
        safeRemoveAndDispose(_scene, _edgeLines);
        _edgeLines = null;
    }
    if (_nodeMarkers && _scene) {
        safeRemoveAndDispose(_scene, _nodeMarkers);
        _nodeMarkers = null;
    }
}

/** Init debug overlay when `?debugIslands=1`. Call after scene exists. */
export function initSkyIslandDebug(scene: THREE.Scene): void {
    _scene = scene;
    _debugEnabled = isDebugFlagEnabled();
    if (!_debugEnabled) return;
    rebuildSkyIslandDebug();
    (window as any).__skyIslandGraph = {
        nodes: () => getSkyIslandNodes(),
        edges: () => getSkyIslandEdges(),
        validate: validateSkyIslandGraph,
        waypoints: buildTraversalWaypoints,
    };
    console.log('[SkyIslands] debug viz enabled (?debugIslands=1)');
}

export function rebuildSkyIslandDebug(): void {
    if (!_debugEnabled || !_scene) return;
    disposeDebugMeshes();

    const nodes = getSkyIslandNodes();
    const edges = getSkyIslandEdges();
    if (nodes.length === 0) return;

    // Edge lines
    const positions: number[] = [];
    const colors: number[] = [];
    const kindColor = (kind: SkyIslandEdgeKind): THREE.Color => {
        switch (kind) {
            case 'vine_ladder': return new THREE.Color(0x32CD32);
            case 'cloud_hop': return new THREE.Color(0x00FFFF);
            case 'lift_pad': return new THREE.Color(0xFF69B4);
            default: return new THREE.Color(0xFFD700);
        }
    };
    for (const edge of edges) {
        const from = _nodes.get(edge.from);
        const to = _nodes.get(edge.to);
        if (!from || !to) continue;
        positions.push(from.x, from.y + 0.5, from.z, to.x, to.y + 0.5, to.z);
        const c = kindColor(edge.kind);
        colors.push(c.r, c.g, c.b, c.r, c.g, c.b);
    }
    if (positions.length > 0) {
        const geo = new THREE.BufferGeometry();
        geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
        geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
        const mat = new THREE.LineBasicMaterial({ vertexColors: true, depthTest: false });
        _edgeLines = new THREE.LineSegments(geo, mat);
        _edgeLines.renderOrder = 9998;
        _edgeLines.frustumCulled = false;
        _scene.add(_edgeLines);
    }

    // Node markers
    const markerGeo = new THREE.SphereGeometry(0.45, 8, 8);
    const markerMat = new THREE.MeshBasicMaterial({ color: 0xFF69B4, depthTest: false });
    _nodeMarkers = new THREE.InstancedMesh(markerGeo, markerMat, nodes.length);
    _nodeMarkers.renderOrder = 9999;
    _nodeMarkers.frustumCulled = false;
    const dummy = new THREE.Object3D();
    nodes.forEach((n, i) => {
        // ⚡ OPTIMIZATION: Write directly to instanceMatrix.array instead of updateMatrix + setMatrixAt
        dummy.matrix.makeTranslation(n.x, n.y + 0.6, n.z);
        dummy.matrix.toArray(_nodeMarkers!.instanceMatrix.array, i * 16);
    });
    _nodeMarkers.instanceMatrix.needsUpdate = true;
    _scene.add(_nodeMarkers);
}

export interface SpawnTypeStats {
    attempted: number;
    succeeded: number;
    failed: number;
}

export interface SpawnFailureEntry {
    type: string;
    context: string;
    message: string;
}

export interface WorldPopulationReport {
    attemptCount: number;
    successCount: number;
    failCount: number;
    byType: Record<string, SpawnTypeStats>;
    errors: SpawnFailureEntry[];
}

const MAX_ERROR_ENTRIES = 25;

class SpawnTracker {
    private report: WorldPopulationReport = this.createEmptyReport();

    reset(): void {
        this.report = this.createEmptyReport();
        this.publish();
    }

    recordAttempt(type: string): void {
        const safeType = this.normalizeType(type);
        this.report.attemptCount++;
        this.ensureTypeStats(safeType).attempted++;
        this.publish();
    }

    recordSuccess(type: string): void {
        const safeType = this.normalizeType(type);
        this.report.successCount++;
        this.ensureTypeStats(safeType).succeeded++;
        this.publish();
    }

    recordFailure(
        type: string,
        error: unknown,
        options?: { context?: string; countAttempt?: boolean }
    ): void {
        const safeType = this.normalizeType(type);
        if (options?.countAttempt) {
            this.report.attemptCount++;
            this.ensureTypeStats(safeType).attempted++;
        }

        this.report.failCount++;
        this.ensureTypeStats(safeType).failed++;
        this.report.errors.push({
            type: safeType,
            context: options?.context ?? 'spawn',
            message: this.toErrorMessage(error),
        });
        if (this.report.errors.length > MAX_ERROR_ENTRIES) {
            this.report.errors.splice(0, this.report.errors.length - MAX_ERROR_ENTRIES);
        }
        this.publish();
    }

    getReport(): WorldPopulationReport {
        const byType: Record<string, SpawnTypeStats> = {};
        for (const type in this.report.byType) {
            byType[type] = { ...this.report.byType[type] };
        }

        const errors: SpawnFailureEntry[] = [];
        for (let i = 0; i < this.report.errors.length; i++) {
            errors.push({ ...this.report.errors[i] });
        }

        return {
            attemptCount: this.report.attemptCount,
            successCount: this.report.successCount,
            failCount: this.report.failCount,
            byType,
            errors,
        };
    }

    private ensureTypeStats(type: string): SpawnTypeStats {
        if (!this.report.byType[type]) {
            this.report.byType[type] = { attempted: 0, succeeded: 0, failed: 0 };
        }
        return this.report.byType[type];
    }

    private createEmptyReport(): WorldPopulationReport {
        return {
            attemptCount: 0,
            successCount: 0,
            failCount: 0,
            byType: {},
            errors: [],
        };
    }

    private toErrorMessage(error: unknown): string {
        if (error instanceof Error) return error.message;
        if (typeof error === 'string') return error;
        try {
            return JSON.stringify(error);
        } catch {
            return String(error);
        }
    }

    private normalizeType(type: string): string {
        const trimmed = type.trim();
        return trimmed.length > 0 ? trimmed : 'unknown';
    }

    private publish(): void {
        if (typeof window !== 'undefined') {
            window.__worldPopulationReport = this.getReport();
        }
    }
}

export const spawnTracker = new SpawnTracker();

export function resetSpawnTracker(): void {
    spawnTracker.reset();
}

declare global {
    interface Window {
        __worldPopulationReport?: WorldPopulationReport;
    }
}
/**
 * Spawn Tracker
 *
 * Lightweight, zero-allocation-on-success counters for map entity and procedural
 * object instantiation success/failure rates. Used to surface visible diagnostics
 * when background / deferred population does not produce the full expected scene.
 *
 * Wires into:
 *  - processMapEntity catch (generation-core.ts)
 *  - procedural extras catch (generation-decorators.ts)
 *  - BackgroundProcessor error path (for world-spawn tasks)
 *
 * Exposes:
 *  - recordSpawnAttempt(type, success, error?)
 *  - getReport()
 *  - reset()
 *  - window.__spawnReport (populated on demand / updates)
 *
 * Designed to be safe to call from hot paths (simple increments).
 */

export interface SpawnReport {
    attempted: number;
    succeeded: number;
    failed: number;
    failuresByType: Record<string, number>;
    lastErrors: Array<{ type: string; message: string; ts: number }>;
}

const MAX_LAST_ERRORS = 8;

let attempted = 0;
let succeeded = 0;
let failed = 0;
const failuresByType: Record<string, number> = Object.create(null);
const lastErrors: SpawnReport['lastErrors'] = [];

let lastReport: SpawnReport | null = null;
let dirty = true;

function makeReport(): SpawnReport {
    return {
        attempted,
        succeeded,
        failed,
        failuresByType: { ...failuresByType },
        lastErrors: lastErrors.slice(), // small copy is fine
    };
}

export function recordSpawnAttempt(type: string, success: boolean, error?: unknown): void {
    attempted++;
    const key = type || 'unknown';

    if (success) {
        succeeded++;
    } else {
        failed++;
        failuresByType[key] = (failuresByType[key] || 0) + 1;

        let msg = 'unknown error';
        if (error instanceof Error) {
            msg = error.message || error.toString();
        } else if (error != null) {
            msg = String(error);
        }
        lastErrors.push({ type: key, message: msg.slice(0, 200), ts: Date.now() });
        if (lastErrors.length > MAX_LAST_ERRORS) {
            lastErrors.shift();
        }
    }

    dirty = true;

    // Keep a live global for easy inspection / tests (no getter cost on happy path)
    try {
        (window as any).__spawnReport = getReport();
    } catch {
        // non-browser or no window — ignore
    }
}

export function getReport(): SpawnReport {
    if (!dirty && lastReport) return lastReport;
    lastReport = makeReport();
    dirty = false;
    return lastReport;
}

export function reset(): void {
    attempted = 0;
    succeeded = 0;
    failed = 0;
    for (const k in failuresByType) delete failuresByType[k];
    lastErrors.length = 0;
    lastReport = null;
    dirty = true;

    try {
        delete (window as any).__spawnReport;
    } catch { /* ignore */ }
}

/**
 * Helper for background-processor style errors when the task id looks like a world spawn.
 */
export function maybeRecordBackgroundFailure(taskId: string, error: unknown): boolean {
    if (!taskId) return false;
    // Heuristic: map_stream_*, map_fallback_*, proc_extra_*, world spawn tasks
    if (
        taskId.startsWith('map_stream_') ||
        taskId.startsWith('map_fallback_') ||
        taskId.startsWith('proc_') ||
        taskId.includes('spawn') ||
        taskId.includes('foliage')
    ) {
        // Extract a friendly type
        const m = taskId.match(/(?:map_stream_|map_fallback_|proc_)([a-z0-9_]+)/i);
        const t = m ? m[1] : taskId.split('_').pop() || 'background';
        recordSpawnAttempt(t, false, error);
        return true;
    }
    return false;
}

// For tests / manual reset in console
try {
    (window as any).__resetSpawnReport = reset;
} catch { /* ignore */ }

/**
 * World Health Validator
 *
 * Called once after `worldFullyPopulated` to verify that expected scene
 * objects actually landed.  All data comes from already-maintained counters
 * (SpawnTracker, state arrays, batcher telemetry) — no scene traversal.
 *
 * Exposes:
 *   window.__worldHealth  — live report for devtools / tests
 *   CustomEvent 'worldHealth' on document — detail = WorldHealthReport
 */

import { getReport as getSpawnReport } from './spawn-tracker.ts';
import {
    animatedFoliage,
    interactiveObjects,
    foliageMushrooms,
    foliageClouds,
    foliageGeysers,
    foliageTraps,
    foliageVineLadders,
    foliageTrampolines,
    foliagePanningPads,
    foliagePortamentoPines,
} from './state.ts';

export interface WorldHealthBatcherEntry {
    id: string;
    label: string;
    instances: number;
}

export interface WorldHealthReport {
    /** WorldMode that was active when the report was taken. */
    mode: string;
    /** Millisecond timestamp. */
    ts: number;

    // ---- spawn-tracker totals ----
    attempted: number;
    succeeded: number;
    failed: number;
    failuresByType: Record<string, number>;

    // ---- live scene counts (O(1) array reads) ----
    sceneObjects: {
        animatedFoliage: number;
        interactive: number;
        mushrooms: number;
        clouds: number;
        geysers: number;
        traps: number;
        vineLadders: number;
        trampolines: number;
        panningPads: number;
        portamentoPines: number;
    };

    // ---- batcher instance counts ----
    batchers: {
        totalInstances: number;
        entries: WorldHealthBatcherEntry[];
    };

    // ---- derived health signals ----
    warnings: string[];
    healthy: boolean;
}

/** Minimum objects we expect to see in a healthy FULL-mode scene. */
const FULL_MODE_MINIMUMS: Partial<Record<keyof WorldHealthReport['sceneObjects'], number>> = {
    animatedFoliage: 50,
    mushrooms: 5,
    clouds: 3,
};

/** Fraction of attempted spawns that may fail before we flag unhealthy. */
const FAILURE_RATE_THRESHOLD = 0.05; // 5 %

export function validateWorldPopulation(mode: string = 'UNKNOWN'): WorldHealthReport {
    const spawn = getSpawnReport();

    const sceneObjects: WorldHealthReport['sceneObjects'] = {
        animatedFoliage:  animatedFoliage.length,
        interactive:      interactiveObjects.length,
        mushrooms:        foliageMushrooms.length,
        clouds:           foliageClouds.length,
        geysers:          foliageGeysers.length,
        traps:            foliageTraps.length,
        vineLadders:      foliageVineLadders.length,
        trampolines:      foliageTrampolines.length,
        panningPads:      foliagePanningPads.length,
        portamentoPines:  foliagePortamentoPines.length,
    };

    // Batcher telemetry — lazy import keeps the health check self-contained;
    // fall back gracefully if the module hasn't loaded yet.
    const batcherEntries: WorldHealthBatcherEntry[] = [];
    let batcherTotal = 0;
    try {
        // collectBatcherTelemetry is synchronous; import is evaluated at module parse
        // time via top-level import in batcher-telemetry — we call via the window
        // shim that installBatcherTelemetry() registered so we avoid a circular dep.
        const telem = (typeof window !== 'undefined' && (window as any).__getBatcherTelemetry)
            ? (window as any).__getBatcherTelemetry() as { totalInstances: number; entries: Array<{ id: string; label: string; instances: number }> }
            : null;
        if (telem) {
            batcherTotal = telem.totalInstances;
            const entriesLen = telem.entries.length;
            for (let i = 0; i < entriesLen; i++) {
                const e = telem.entries[i];
                batcherEntries.push({ id: e.id, label: e.label, instances: e.instances });
            }
        }
    } catch { /* telemetry not available — non-fatal */ }

    const warnings: string[] = [];

    // 1. Spawn failures
    if (spawn.failed > 0) {
        const rate = spawn.attempted > 0 ? spawn.failed / spawn.attempted : 0;
        const pct = (rate * 100).toFixed(1);
        let typesStr = '';
        for (const k in spawn.failuresByType) {
            if (typesStr.length > 0) typesStr += ', ';
            typesStr += `${k}:${spawn.failuresByType[k]}`;
        }
        warnings.push(`${spawn.failed} spawn failure(s) (${pct}% of ${spawn.attempted} attempted). Types: ${typesStr}`);
    }

    // 2. Under-count checks (only meaningful in FULL mode)
    if (mode === 'FULL' || mode === 'FAST_FULL') {
        for (const [key, min] of Object.entries(FULL_MODE_MINIMUMS) as [keyof typeof FULL_MODE_MINIMUMS, number][]) {
            const actual = sceneObjects[key];
            if (actual < min) {
                warnings.push(`Expected ≥${min} ${key}, found ${actual}.`);
            }
        }
    }

    // 3. Excessive failure rate
    const failureRate = spawn.attempted > 0 ? spawn.failed / spawn.attempted : 0;
    if (spawn.attempted > 10 && failureRate > FAILURE_RATE_THRESHOLD) {
        warnings.push(`Spawn failure rate ${(failureRate * 100).toFixed(1)}% exceeds ${FAILURE_RATE_THRESHOLD * 100}% threshold.`);
    }

    const healthy = warnings.length === 0;

    const report: WorldHealthReport = {
        mode,
        ts: Date.now(),
        attempted: spawn.attempted,
        succeeded: spawn.succeeded,
        failed: spawn.failed,
        failuresByType: { ...spawn.failuresByType },
        sceneObjects,
        batchers: { totalInstances: batcherTotal, entries: batcherEntries },
        warnings,
        healthy,
    };

    // Publish to window for devtools / smoke tests
    try { (window as any).__worldHealth = report; } catch { /* SSR / node */ }

    // Log summary
    if (healthy) {
        console.log(
            `[WorldHealth] ✓ ${mode} | ${spawn.succeeded}/${spawn.attempted} spawned` +
            ` | foliage=${sceneObjects.animatedFoliage} interactive=${sceneObjects.interactive}` +
            ` | batchers=${batcherTotal} instances`
        );
    } else {
        console.warn('[WorldHealth] ⚠ Warnings after population:');
        warnings.forEach(w => console.warn(`  • ${w}`));
    }
    console.debug('[WorldHealth] Full report:', report);

    // Dispatch event so tests / systems can react
    try {
        document.dispatchEvent(new CustomEvent('worldHealth', { detail: report }));
    } catch { /* non-browser */ }

    return report;
}

// vite.config.js
import { defineConfig } from 'vite';
import wasm from 'vite-plugin-wasm';
import topLevelAwait from 'vite-plugin-top-level-await';

// Set modern build target so top-level await in dependencies (e.g. three/examples WebGPU helper)
// doesn't get transformed to an unsupported lower target during bundle/transpile.
export default defineConfig({
    plugins: [wasm(), topLevelAwait()],
    base: './',
    build: {
        sourcemap: true,
        minify: true,
        target: 'es2022',
        // Ensures assets don't get lost in complex folder structures
        assetsDir: './',
        // Restrict rollup input to only the app's root index.html so Vite doesn't try to
        // analyze unrelated HTML files (like those under emsdk/tests) which can import
        // non-app modules such as loader.mjs.
        rollupOptions: {
            input: {
                main: './index.html',
            },
            output: {
                manualChunks(id) {
                    // Vendor chunk - all third-party dependencies
                    if (id.includes('node_modules')) {
                        return 'vendor';
                    }
                    // NOTE: audio + boot UI modules stay in `app` (separate chunks caused
                    // Circular chunk: * ↔ app). weather/particles/compute stay in `weather`
                    // — folding weather into `app` breaks init (TDZ); splitting particles
                    // out of `weather` deadlocks boot. One benign weather ↔ app warning remains.
                    // Workers
                    if (id.includes('/src/workers/')) {
                        return 'workers';
                    }

                    // --- Lazy chunks (#1361): only reached via dynamic import() ---
                    // Thin *lazy.ts stubs stay in `app` (statically imported); the heavy
                    // modules below are loaded via import() from those stubs.
                    // Gameplay abilities (blaster, mines, chord, harpoon, glitch grenade)
                    if (
                        (id.includes('/src/gameplay/') && !id.endsWith('/gameplay/lazy.ts')) ||
                        id.includes('/src/systems/glitch-grenade.ts')
                    ) {
                        return 'gameplay';
                    }
                    // Save menu UI + save-system core (exclude thin lazy stubs)
                    if (
                        (id.includes('/src/ui/save-menu/') && !id.endsWith('/save-menu/lazy.ts')) ||
                        id.includes('/src/systems/save-system/')
                    ) {
                        return 'save-ui';
                    }
                    // Accessibility settings DOM (lazy-loaded menu)
                    if (
                        id.includes('/src/ui/accessibility-menu') &&
                        !id.endsWith('/accessibility-menu-lazy.ts')
                    ) {
                        return 'accessibility-ui';
                    }
                    // Dev cloud placement tool (lazy stub stays in app)
                    if (id.includes('/src/world/cloud-placer.ts')) {
                        return 'cloud-placer';
                    }
                    // Save integration hooks (lazy stub stays in app)
                    if (id.includes('/src/systems/save-integration.ts')) {
                        return 'save-ui';
                    }
                    // Analytics debug overlay (?debug=1 / /stats) — not the *-lazy stub
                    if (
                        id.includes('/src/ui/analytics-debug.ts') ||
                        id.includes('/src/ui/analytics-debug-ui.ts') ||
                        id.includes('/src/ui/analytics-debug-handlers.ts')
                    ) {
                        return 'analytics-debug';
                    }
                    // World content decorators (procedural extras, gem canopy, mycelium)
                    if (id.includes('/src/world/generation-decorators.ts')) {
                        return 'world-content';
                    }
                    // Debug tools (panel, gizmos, ground/placement/circadian/fauna overlays)
                    if (
                        id.includes('/src/debug/') &&
                        !id.endsWith('/debug/stages.ts') &&
                        !id.endsWith('/debug/index.ts') &&
                        !id.endsWith('/debug/lazy.ts') &&
                        !id.endsWith('/debug/tools-stub.ts')
                    ) {
                        return 'debug';
                    }
                    // camera-modes, hud-ui, interaction, playlist-ui, presence, photo-mode:
                    // co-located in `app` — separate chunks created Rollup circular-chunk
                    // warnings (app ↔ chunk) without reducing first-paint bytes.
                    if (id.includes('/src/systems/loading-manager.ts')) {
                        return 'loading-ui';
                    }
                    if (id.includes('/src/world/world-health.ts')) {
                        return 'world-health';
                    }
                    if (id.includes('/src/ui/mode-badge.ts')) {
                        return 'mode-badge';
                    }
                    if (id.includes('/src/foliage/batcher-telemetry.ts')) {
                        return 'telemetry';
                    }
                    // Shader warmup (loading-screen phase — not first-paint brain)
                    if (id.includes('/src/rendering/shader-warmup.ts')) {
                        return 'shader-warmup';
                    }
                    // Awakened flora persistence (feature-flagged ?awakened)
                    if (id.includes('/src/systems/awakened-persistence.ts')) {
                        return 'awakened';
                    }
                    // Generative soundtrack engine (not music-mode.ts resolver)
                    if (
                        id.includes('/src/audio/generative/') &&
                        !id.endsWith('/generative/music-mode.ts')
                    ) {
                        return 'generative-music';
                    }

                    // Weather + particles + compute — separate from `app`. Folding weather
                    // into `app` breaks init order (TDZ). particles/compute must stay with
                    // weather (not app) or dynamic weather load deadlocks at boot.
                    if (
                        id.includes('/src/systems/weather/') ||
                        id.includes('/src/particles/') ||
                        id.includes('/src/compute/')
                    ) {
                        return 'weather';
                    }

                    // Remaining app code with intertwined imports stays in one chunk to
                    // avoid circular *chunk* dependencies (foliage ↔ systems core, etc.).
                    if (
                        id.includes('/src/core/') ||
                        id.includes('/src/audio/') ||
                        id.includes('/src/foliage/') ||
                        id.includes('/src/rendering/') ||
                        id.includes('/src/systems/') ||
                        id.includes('/src/ui/') ||
                        id.includes('/src/utils/') ||
                        id.includes('/src/world/')
                    ) {
                        return 'app';
                    }
                    // Remaining modules stay in main
                },
                chunkFileNames: (chunkInfo) => {
                    const prefix = chunkInfo.name === 'vendor' ? 'chunks/vendor' : 'chunks/[name]';
                    return `${prefix}-[hash].js`;
                },
                assetFileNames: (assetInfo) => {
                    const info = assetInfo;
                    if (info.name?.endsWith('.wasm')) {
                        return 'wasm/[name]-[hash][extname]';
                    }
                    if (/\.(png|jpg|svg|gif|webp)$/.test(info.name || '')) {
                        return 'images/[name]-[hash][extname]';
                    }
                    return 'assets/[name]-[hash][extname]';
                },
            },
        },
        // Optimize chunk size warnings
        chunkSizeWarningLimit: 500,
    },
    esbuild: {
        // ensure esbuild treats code as modern so top-level await is preserved
        target: 'es2022',
    },
    // Ensure optimizeDeps only scans the app root entry (index.html) and targets
    // modern JS (esnext) so top-level await in dependencies is preserved.
    optimizeDeps: {
        // Force dependency scanning to the app's root index -- don't scan test HTML files
        // inside emsdk or other bundles which can include non-app modules such as loader.mjs.
        entries: ['./index.html'],
        esbuildOptions: {
            target: 'esnext',
        },
    },
    server: {
        headers: {
            // These headers are REQUIRED for SharedArrayBuffer (Pthreads)
            'Cross-Origin-Opener-Policy': 'same-origin',
            'Cross-Origin-Embedder-Policy': 'require-corp',
        },
        // Keep Vite from serving files outside the repository root by default.
        fs: {
            strict: true,
        },
        // Ignore the emsdk test folder (these are unrelated test HTML files that can
        // confuse Vite's dependency scanner and cause unresolved import errors).
        watch: {
            ignored: ['**/emsdk/**'],
        },
    },
    // Ensure the worker file is treated correctly if using Vite's worker import (optional but safe)
    worker: {
        format: 'es',
        plugins: () => [wasm(), topLevelAwait()],
    },
});
